Object.assign(window.__LB,{"10000": ["病机", "左喉风红肿欲腐而脉数，数为热盛之象，与原文\"阴薄肝亢，温邪内郁\"相合。阴分薄弱则肝阳偏亢，温邪内郁化热，热势方张故脉数，提示邪热鸱张、病势进展，未可忽视。", ["数"]], "10001": ["病机", "烂喉风脉数不畅，数主热，不畅示郁。原文谓\"心肝不潜，风火郁肺\"，风火内郁不得宣透，故脉数而涩滞不畅，热郁于里、腐势有蔓延之虞，故诫防腐蔓延不可忽视。", ["数"]], "10002": ["病机", "本条与上条同文，烂喉风脉数不畅，数示风火内郁之热，不畅示郁结不宣。心肝不潜、风火郁肺，热郁肺系则喉腐，脉象反映热郁交争之势，故强调防腐蔓延、不可忽视。", ["数"]], "10003": ["主病", "喉关红肿哽痛妨咽、痰核、耳失聪而脉数，数主热。原文断为肝风内动、风热上扰，故见喉关红肿、痰核结聚、耳窍失聪，脉数应其热势，治法宜平肝泄风，脉数正是风热鸱张之征。", ["数"]], "10004": ["病机", "脉微滑而见头右半痛、目起星、眩晕耳鸣、经居三月，原文谓\"营虚肝亢，化风上升\"。微为营血不足，滑主痰，营虚则肝阳失涵，化风上扰清窍，故诸症蜂起，脉微滑正示虚中夹痰、风阳上旋之机，治在阴分。", ["微", "滑"]], "10005": ["病机", "脉软弦微数，软示阴分不足，弦为肝阳偏亢，微数示虚热内扰。原文\"阴不涵阳\"，故颧赤目干、咽干、寐不安，皆阴虚阳浮、虚热上炎之候，脉象软弦兼数正合阴亏阳亢之病机，故治在阴分。", ["软", "弦", "数"]], "10006": ["预后", "鼻衄连日不止、头晕微热而脉数，数主热盛，热迫血妄行则衄不止。阴不敛阳、虚热上扰故头晕微热，脉数示热势未平，原文诫\"防转重，弗忽\"，提示脉数不去则血热难清，有转重之虞。", ["数"]], "10007": ["兼症", "目赤星翳稍愈、步履轻便而脉弦、腰背痛，弦为肝脉，主肝阳偏亢、气机不畅。目症虽减而脉仍弦，说明肝亢未平；腰背痛与弦脉并见，示肝气不舒、筋脉失和，故原文谓宜治所急，当从弦脉着眼调肝。", ["弦"]], "10008": ["病机", "脉濡滑，濡主气阴不足、气虚不运，滑主痰湿内蕴。原文谓气虚则积痰、阴虚则火浮，痰火相合上蒙清窍，故见耳鸣重听。濡滑并见，正合气虚痰盛、火浮不清之机，治当标本兼顾，勿使助火滞痰。", ["濡", "滑"]], "10009": ["病机", "左部软弦，软为不足、弦属木旺，右软滑实为痰气内结。原文谓肾水不足，木火挟痰气乘之而成重听。软弦示水亏木失柔养，滑实示痰气壅盛，故病根深远，非标本兼治不可。", ["软", "弦", "滑", "实"]], "10010": ["病机", "脉细数，细为阴血不足，数为火盛。原文谓水不涵木，木火挟风毒结于眼胞，毒肿溃及鼻梁，牙关紧而半面尽肿。细数正合阴虚火旺、风毒炽盛之机，内外同病，故不易奏功。", ["细", "数"]], "10011": ["病机", "脉数主热，原文谓牙槽风内外肿甚、牙关拘紧、作痛焮热，表热脉数，明示风热郁于阳明络脉。热盛则肿痛焮热，风郁则牙关拘紧，故治宜清化泄降，以泄阳明风热。", ["数"]], "10012": ["病机", "脉数带弦，数为热盛，弦为木郁风动。原文谓牙槽风内外肿胀、稍有寒热，乃风热郁于阳明而兼肝木不调。数示热，弦示风，风热相搏故肿胀寒热，治当内外两治，清化与疏泄并行。", ["数", "弦"]], "10013": ["病机", "脉数主热，原文谓牙骱痈久伏、牙关紧，脉数，断为肝木不潜、风热上亢。久伏之痈因肝木失潜、风热上攻而发，数脉正应风热亢盛，故宜泄化，泄其风热、化其久伏之毒。", ["数"]], "10014": ["病机", "脉细主阴血不足、正气亏虚。原文谓穿腮牙痈外肿极坚、牙关启闭不利，兼头痛耳鸣、易于惊惕，细脉示正虚而邪结坚牢，肝血不足则惊惕，虚风上扰则头痛耳鸣，故法当先治所急。", ["细"]], "10015": ["病机", "脉弦主肝木偏旺、气机郁滞。原文谓齿痛较减而肝木未平，二便不流利，脉弦，说明肝失疏泄、气机不畅，木旺则二便不利。弦脉应肝，故宜平肝泄降，使肝木平而气机通利。", ["弦"]], "10016": ["病机", "脉数主热，风热入阳明络，热邪鼓动气血，故脉数。左牙龈肿痛、曾有寒热，为风热客于阳明经络，正邪交争之象。热郁则脉数，宜清化泄降以解阳明风热。", ["数"]], "10017": ["病机", "脉软弦微数，软为阴虚，弦为肝亢，微数示伏风内动。表热之后肌灼口干、牙骱酸、头胀晕，乃阴虚肝亢、伏风流走之征。脉弦数应肝风，软应阴亏，故宜内外两治。", ["软", "弦", "数"]], "10018": ["病机", "脉弦沉，弦主肝旺，沉主里主水。水亏肝旺，风复亢之，故齿痛连头；外寒内热、胸闷不思食、便闭舌白，皆肝风内动、水亏木亢之象。脉沉弦正合水亏肝旺之机。", ["弦", "沉"]], "10019": ["病机", "脉弦细，弦为肝郁，细为营虚水亏。营虚水亏，痰气互阻，结为乳癖；阳明素有湿热，故须肝胃兼治。脉弦细应肝郁营虚、痰气凝结之病机。", ["弦", "细"]], "10020": ["兼症", "脉濡滑，濡主湿，滑主痰。咳嗽不畅、胸痛咽痛、乳块作胀，为痰湿内阻、气机不畅之兼症。脉濡滑应痰湿壅滞，故当治所急，先化痰湿以畅气机。", ["濡", "滑"]], "10021": ["预后", "脉细为营阴亏虚，郁火伤阴，痰气交结，酿成乳岩，溃腐流血、旁坚如石，乃脏病外显。脉细示正气已虚，邪毒深结，故曰脏病外症中之内病，理之不易，预后堪忧。", ["细"]], "10022": ["病机", "脉细弦，细主虚，弦主肝郁痰凝。痰气流络，络气失宣，故左腿骱酸痛不能行动；盗汗为虚象。因虚而病，痰阻络脉，脉细弦正合虚中夹痰之机，理之不易。", ["细", "弦"]], "10023": ["预后", "脉细主肝胃虚、营卫失调。疬痰久积，中间软红已有伏脓，势难消散，作寒发热，乃正虚邪恋。脉细示气血不足，托毒无力，故收功殊非易易，预后需慎。", ["细"]], "10024": ["病机", "脉濡主湿、主气血不足。此案流注腐肉未脱尽而新肉不多，正虚无力托毒，脉濡反映气血亏虚、湿浊留恋，故宜托未尽之毒兼养营宣络，使气血和畅以助收口。", ["濡"]], "10025": ["病机", "脉数主热，伏主邪郁深伏。时毒风痰大势初定而左边坚硬，风痰浊交阻胆胃，络气失宣，热郁于内故数而伏，宜泄风清火以宣通络气。", ["数", "伏"]], "10026": ["病机", "脉数主热，弦主痛、主肝风。牙槽风内外肿胀、稍有寒热，风火郁于阳明经络，故脉数弦，当内外两治以清散风火。", ["数", "弦"]], "10027": ["病机", "脉弦数主火盛阴伤。肺痈脓血较减而臭痰尚多、舌黄质红，火升少寐、肢冷，乃火升于上、阳不外达，体虚病冗，脉弦数正示火未清而阴已伤。", ["弦", "数"]], "10028": ["病机", "脉软弦主气阴两乏而兼湿。偏背疽新肉红甚、四围孔多，适当湿令、胃呆，软为气阴不足，弦为湿阻络气，故不能重用补药，宜慎起居以缓收口。", ["软", "弦"]], "10029": ["病机", "脉数主热。溲痛得瘥而囊肿仍甚、表热脉数，湿热内恋未清，故当以泄化湿热为治。", ["数"]], "10030": ["病机", "脉弦数主火热内郁。肺痈近日反复且伤风，鼻塞手冷、腹痛，弦数为火热未清而兼外风，病绪见多，兼顾不易。", ["弦", "数"]], "10031": ["病机", "脉濡主湿、主本体不足。癣药咬破肾囊延腐大痛，湿热为患，脉濡、头蒙示湿浊内蕴而正气不足，既防脱囊又虑别生枝节，急急解散湿热为要。", ["濡"]], "10032": ["病机", "脉数主热，此案牙槽风肿胀作痛、纳少，乃风热之邪走入阳明络脉，势在方张。数脉应热邪亢盛，与表热、肿胀相应，示病势未衰，故不可忽视。", ["数"]], "10033": ["兼症", "脉微弦，弦主气机不畅、木郁克土，微则病势未甚。症见胸闷瘕攻、头晕、舌白，为肝郁脾湿、气滞痰凝之象；癀痘满布则毒邪外发。脉症合参，宜兼顾旁，不可专治痘而忽略气郁。", ["弦", "微"]], "10034": ["预后", "原文未识脉名，仅言“形色脉俱惫”，脉象模糊。病缠三月，形色脉皆惫，便溏，跨马流注肿胀，乃气血耗伤、脾肾俱损，正虚邪恋。内外同病，正气难支，故断为不易治，属预后不良之候。", []], "10035": ["病机", "脉数主热，此痰痈肿胀、表热，乃风湿痰浊交阻，郁而化热。数脉示热邪内蕴，与痰浊相搏，最防痰升气塞，上蒙清窍。脉症相应，故不可忽。", ["数"]], "10036": ["病机", "右脉软主气分不足，左脉微弦主肝郁血少。气郁化痰，痰入筋骨发为流痰，溃后气营交困，络脉失养，故患处肿木、手臂不能举动。脉象反映内因虚损，故曰不易速效。", ["软", "弦", "微"]], "10037": ["兼症", "脉沉滑主湿浊内蕴，右带数则湿热偏盛。痔疮便后绕肛易肿，乃气阴不足、湿热下陷；脘脐作痛、感冒咳嗽，为肝脾不调、肺气失宣。脉症合参，宜择要立方，兼顾气阴与湿热。", ["沉", "滑", "数"]], "10038": ["病机", "脉濡主湿，此湿毒流痰，腐久不敛、易于出血，两膝酸，乃湿热走三阴络分，营络受损。濡脉应湿邪黏滞，与腐久出血、膝酸相应，示湿毒深伏，一时不易速效。", ["濡"]], "10039": ["病机", "脉大微数，大主邪盛，数主热，微数示热势未炽。心肝不潜，蕴热上亢，后项脑际作胀，痛楚不能著枕，乃热壅络脉。脉症合参，延防凝聚成疡，故未可忽。", ["大", "数", "微"]], "10040": ["病机", "脉软少神，为气血亏虚、肝肾积虚之象。流痰复溃，脓多气秽，足膝无力，乃久病耗伤，正气不复。脉软主虚，少神示胃气衰败，故断为肝肾积虚，急当培补，以冀渐复。", ["软"]], "10041": ["病机", "脉软主虚，咳嗽气逆、气短、腰腿酸软，皆积虚已甚之候。软脉为气血不足，脾肾亏虚，不能纳气充骨，故治宜求本，培补脾肾。", ["软"]], "10042": ["病机", "原文未及脉象，然述少腹之下、胯弯之上横肿僵木，渐觉抽痛，断为湿痰下注、肝肾络阻、痹阻气血而蒸脓。地处至阴，溃脓不透，非纯阴症，故主张宣通血脉、疏解痰湿。", []], "10043": ["病机", "脉数主热，湿热流入关节，两腿酸痛，痛入腿骱，舌白黄，乃湿热毒郁不宣之象。数脉为邪热内郁，故宜清化分利，使湿热分消。", ["数"]], "10044": ["病机", "脉数主热，两腿弯酸痛不能履地，形寒微热，头胀胸闷，为湿热郁阻、营卫不和之候。数脉示邪热内蕴，防聚疡，故宜早治弗忽。", ["数"]], "10045": ["病机", "脉数主热，头痛耳鸣失聪，湿疹发，头项伏核不一，乃湿热郁蒸、上扰清窍、外发肌肤之象。数脉为热郁，故宜泄降法，清利湿热。", ["数"]], "10046": ["病机", "脉濡主湿，气分不足，湿热下陷，始病痔坠，渐转脱肛。濡脉为湿滞气弱，湿热下注，故先清利湿热，以除下陷之因。", ["濡"]], "10047": ["病机", "脉来濡主湿，肝肾虚寒，寒湿下阻，右足肿痛，延防结疡。濡脉示湿滞，寒湿阻络，气血不畅，故急则治标，先祛寒湿。", ["濡"]], "10048": ["病机", "脉左细不畅、右虚弦，细为阴血不足，虚弦为肝脾失调、气机不舒。三阴不足则痰湿逗留，流注左环跳而作痛；神疲嗜卧、腹中作胀，皆脾虚气滞、湿痰内阻之象。脉细不畅正合痰湿阻络、气血不利，故曰病绪杂出，当循序养之。", ["细", "虚", "弦"]], "10049": ["病机", "脉微数，微为正气不足，数为有热。湿疮不净，湿热蕴久化风，风热上扰则口歪。脉数示风热内盛，微则示湿疮日久伤正。原文宜泄风清热利湿，正合脉数主热、微示正虚湿恋之病机。", ["微", "数"]], "10050": ["病机", "脉数主热，疬痰受风复发，肿硬酸痛，头晕纳少，口干苦，皆风热痰毒壅结之候。数脉示热毒炽盛，故防溃头。原文以脉数点出热势，与肿硬酸痛、口干苦相应，说明痰毒化热、有酿脓破溃之势。", ["数"]], "10051": ["预后", "鹤口疽肿溃流脓而脉细，细为气血两虚。溃后脓流，正气已伤，脉不洪数而反细，示气血不足以托毒生肌，故最防淹缠不已。原文以脉细断其收口难期，正合溃后脉细主正虚、预后缠绵之机。", ["细"]], "10052": ["病机", "脉数主热，流注发于左肩臂、痛楚著骨、舌黄腻，为伏风深重、痰湿化热之象。数脉示热毒内蕴，与舌黄腻相应，说明伏风挟湿痰壅阻经络，热势已成，故不易消散。原文以脉数断其伏风深重。", ["数"]], "10053": ["病机", "脉软弦，软为气血不足，弦为痰浊阻络、气机不利。疡症收口之后，气血未复，痰浊留滞经络，左半体麻木，正合软弦之脉。原文谓气血不能流利，宜标本两治，即补虚与化痰通络并行，脉象与症候相印。", ["软", "弦"]], "10054": ["兼症", "脉数主热，湿疮日久形疲色夺，近增寒热，咳痰较浓、时松时窒，为疮后正虚又感外邪。数脉示新感发热，与寒热相应。原文谓本症之外又有新感，须解散之，说明脉数在此标示新感之热，非独疮毒。", ["数"]], "10055": ["病机", "脉细为肝肾不足、精血亏虚。骨槽风因肝肾不足，风邪乘虚入于筋骨，右牙骱酸痛著骨。细脉示正虚不能托邪，风毒深踞骨间，故成骨槽风。原文以脉细点明虚为本、风为标，与酸痛著骨之症相应。", ["细"]], "10056": ["病机", "左脉细甚，右较大较弦，细为阴血亏少、心肾两亏，弦为肝胆气火亢盛。原文谓“本虚标实”，正合细弦并见之象：虚在根本，实在痰热与肝胆气火上亢，故风波易起，病情易反复。", ["细", "弦"]], "10057": ["预后", "虚损日久，百节尽痛、气急夜喘、胃呆不食，脉细示气血根本枯槁，不能充脉。原文断为“根本槁极，恐非草木可以为力”，脉细在此非一般虚象，而是生机衰微之候，故归预后。", ["细"]], "10058": ["兼症", "心神恍惚渐定、夜寐交安、便溏亦瘥，示病势渐退，而仍有往来寒热，脉细为气营未复、正虚未充之象。此段以脉细配合寒热等兼症，说明余邪未尽而正气尚弱。", ["细"]], "10059": ["病机", "风热客上焦，手太阴受病，发为喉疳且腐势甚盛，脉数正应热邪亢盛、正邪交争。原文谓“正当发越之际”，数脉示热势方张，故须清化泄降，使上焦风热得解。", ["数"]], "10060": ["病机", "气营不足，神思倦怠而畏寒，脉细为气血亏虚、脉道不充之征。细脉与倦怠、畏寒相应，说明本原虚损，阳气营血俱不足，故原文主张“从本原调理”，以补益为要。", ["细"]], "10061": ["病机", "脱力久不复，舌白，脉濡。濡为湿浊内阻、阳气不运之象，舌白亦示浊阴偏盛。原文主“通阳泄浊”，正因濡脉反映阳气痹阻、湿浊留恋，非单纯虚损，故以通阳化浊为治。", ["濡"]], "10062": ["病机", "脉软，原文直指“气不足也”；又足底易痛为肾阴虚，手足少力为气虚。软脉主正气虚弱、脉道无力，与气虚少力相应，故治以补气养营、化风痰、通经脉，标本兼治。", ["软"]], "10063": ["病机", "气郁血滞经阻，寒热咳嗽腹不舒，脉软弦细。软为气不足，弦为气郁，细为血少脉道不充，三象合示气血郁滞而本虚。原文谓“积病深远，非易速效”，正因虚实夹杂、病根深固。", ["软", "弦", "细"]], "10064": ["妇人", "脉濡滑，濡主湿、滑主痰，提示痰湿内蕴。症见恶寒恶心、少纳头晕、痰多，为痰湿中阻、脾胃升降失司之象。原文谓“颇有怀麟之状”，濡滑亦为妊娠常见脉，故须慎养起居，以防误治。", ["濡", "滑"]], "10065": ["主病", "脉弦主痛、主气机不畅。连心胸痛、气急，为胸阳痹阻、气滞血瘀；有汗畏风、热不透，兼表邪未解。脉弦反映内外合邪、气机郁滞，故宜表里两治，解表通阳并行。", ["弦"]], "10066": ["病机", "脉细弦，细主阴血不足，弦主气滞或肝郁。脘痛大势得减而脉仍细弦，舌中剥，示胃阴亏虚、肝气未和。此脉象说明病机由实转虚，阴伤气滞并存，故宜守前意增减，养阴柔肝。", ["细", "弦"]], "10067": ["病机", "脉濡主湿、主虚。惊恐抑郁、心肝交病，不得寐、咳不畅、心宕气逆，为情志所伤、气机逆乱，兼湿浊内阻。濡脉反映正气不足、湿郁气滞，故须加意慎养，调畅情志。", ["濡"]], "10068": ["病机", "脉微滑，微主正气不足，滑主湿热内蕴。消渴渐瘥而便热、神疲，为津气两伤、湿热未清。微滑之脉示正虚邪恋，故宜生津化湿热，标本兼顾。", ["微", "滑"]], "10069": ["治法", "转筋而脉伏，伏主邪闭气机、阳气不达。原文以当门珠箔治之，转筋脉伏力能匡，说明药后脉气渐复。脉伏反映筋脉挛急、气血壅滞，治当开闭通阳。", ["伏"]], "10070": ["其他", "此段论良医须识学兼到，方能“明脉理之精微，而制治有其要”。脉理精微指脉象变化微妙难辨，非具体脉象。强调识病源虚实与脉理精微并重，属医论，非论特定病机。", []], "10071": ["预后", "嗽而脉数，数主热、主虚。久嗽脉数，为脏阴亏虚、虚热内生，金水同治即肺肾同调。原文谓“恐延损怯”，示脉数示阴亏热扰，预后须防虚损成怯。", ["数"]], "10072": ["病机", "脉数而见咳嗽，数主热，热扰肺金则咳；然原文并见盗汗形寒，盗汗为阴不内守，形寒为阳不外护，故断为营卫交虚。数脉在此非实热，乃虚热外浮之象，营卫两伤，卫外不固则形寒，营阴不守则盗汗，肺气上逆则咳嗽，三者相合，正合营卫交虚之机。", ["数"]], "10073": ["病机", "脉数无序，数而失其常序，是阴亏于下、阳亢于上之象。阴不制阳，虚火内扰，故脉数无伦；血来点粒乃阳亢迫血妄行。原文以春夏木火炎炎为喻，言时令助其木火，火愈炎则阴愈亏，故虑其发而不已，紧扣阴亏阳亢之机。", ["数"]], "10074": ["病机", "脉弦且出鱼际，弦为肝脉，出鱼际则肝木之气上溢，是木火郁而不泄之象。肝郁化火，横逆犯胃，阳明受戕，故食下稍有不适当即䐜胀，饥则嘈杂难耐。原文明言肝胃同治、肝木宜疏、胃府宜降，正以弦脉出鱼际定其木火郁逆、阳明受戕之病机。", ["弦"]], "10075": ["病机", "脉细如丝，细主阴血亏少、阳气衰微；形神尩羸，形瘦神疲，与细脉相应。嗽而气逆，是下焦阳气颇衰，不能摄纳，气逆于上。原文最虑喘脱，正因阳衰根浅，虚气上逆有暴脱之虞；延至春和日暖，阳气得助，始可无虞，紧扣下焦阳衰之机。", ["细"]], "10076": ["病机", "脉数而软，数为有热，软为无力，是虚热而非实火之象。嗽逆暮盛，暮则阳气入阴，虚热内扰于肺，故咳逆入暮加剧。数而软并见，说明热由虚生、气不敛摄，肺失清肃，与嗽逆暮盛之症相应，主虚热恋肺、气逆不降之病机。", ["数", "软"]], "10077": ["病机", "望色萎黄，参脉微细，微为阳气衰微，细为阴血不足，合而断为中阳困顿之候。中阳不振，运化失司，故烦劳则病呕尤甚，劳则耗气，中阳愈困，胃气上逆而呕。原文法宜温之，正以微细脉定其中阳困顿、当温运中焦之病机。", ["微", "细"]], "10078": ["病机", "脉沉弦，沉主里、主气郁，弦主肝木。肝气郁结于里，横逆犯胃，胃失和降，故脘胀噫气；肝郁化火，内扰心神则口燥不寐。原文宜和肝胃，正以沉弦定其病在里、属肝胃不和之机，脘胀噫气与口燥不寐皆由此郁逆而来。", ["沉", "弦"]], "10079": ["病机", "脉微细，微为阳气虚衰，细为阴血不足，是阴阳气血俱虚之象。此段仅出脉象而未列症候，然微细并见，主正气亏虚、阳衰阴弱，多见于虚劳、中阳困顿或久病体弱之候，其病机为气血两虚、阳气不振，脉道充盈不足故见微细。", ["微", "细"]], "10080": ["病机", "脉虚为营气不足之象，营血亏虚则胃气虽能知饥，而脾运无力，故恶食。虚脉主气血两虚，此段以脉虚统摄知饥恶食之症，说明病机在营分亏虚、脾胃运化不健，故治法宜益营分，而非消导攻伐。", ["虚"]], "10081": ["病机", "腹痛已止而左脉尚弦，说明痛势虽缓，肝木偏亢之气未平。弦为肝脉，左关候肝，痛止而脉仍弦，是病机重点已由气滞腹痛转为肝气未和、余邪未尽，故仍当留意肝木疏泄失常，不可因痛止而遽断痊愈。", ["弦"]], "10082": ["病机", "脉来微细，为气血阴阳俱不足之象；形神尩羸、脊热头旋、咽喉如梗，皆精血亏虚、督脉失养所致。经事如期说明病不在冲任血海，而属督脉空虚，故脉微细主虚损，法宜温养以填补督脉。", ["微", "细"]], "10083": ["病机", "左脉弦为肝阳偏亢之征，阳气偏亢则木火易升，温邪乘虚侵之，肺失清肃故咳嗽。弦脉主肝主痛主气逆，此段以左脉弦点明阳气偏亢、温邪外侵之病机，故不用苦寒直折，而宜甘药缓肝润肺。", ["弦"]], "10084": ["病机", "脉尚弦芤，弦为肝木偏旺、气机郁滞，芤为阴血亏耗、脉道失充。弦芤并见，说明乙癸同源之地，肝血肾阴两伤而肝气未和。初之气中乙癸同治，即从肝肾精血亏虚、木气偏亢之病机着眼调治。", ["弦", "芤"]], "10085": ["病机", "脉涩为气血运行不畅、胃阳不振之象。食下拒纳，说明胃中阳气虚弱，不能腐熟通降，故脉道涩滞不利。涩脉主气滞血瘀、阳衰不运，此段以脉涩点明胃阳不足、纳运失职之病机，故治法宜理胃阳。", ["涩"]], "10086": ["病机", "左脉弦数，弦为肝阳偏亢，数为火热内动。咳嗽失血由少阴亏虚、厥阳不潜，肝火上逆灼肺伤络所致。左脉候肝肾，弦数并见说明阴亏于下、阳亢于上，故病机为少阴颇亏、厥阳不潜，非单纯外感咳嗽。", ["弦", "数"]], "10087": ["病机", "脉细涩为阴血亏少、脉道不利之象。咳嗽三月不愈，是温邪伏于肺卫，久羁不解，渐耗阴液，故脉由细转涩。细主阴虚，涩主血少气滞，此段说明温邪伏肺日久，正渐延阴损劳怯之途，病机重在伏邪伤阴。", ["细", "涩"]], "10088": ["病机", "脉弦长为木火亢盛之象，弦主肝木，长主气火有余。原文谓“木火上逆刑金”，肝火循经上逆，灼伤肺金，致清肃下降之职失司，故见噫气。久延不愈，气火交阻，噎格之患由此而生。治当开怀解郁，以平木火。", ["弦", "长"]], "10089": ["病机", "脉出鱼际，为寸脉浮盛，主木火内郁，不得宣达。木郁化火，戕伐阳明胃土，故吞酸；壮火食气，耗伤正气，故神倦。此“壮火食气”之病机，火盛则气衰，非独外邪，内郁之火亦能耗气。", []], "10090": ["病机", "脉涩为营血虚少、脉道不利之征。营虚则血不养心，心悸由生；血虚不能上荣，故头胀；阴血不足，阳气浮越不潜，扰动血络，则便血。此营虚阳浮、血不循经之病机，涩脉正是营亏血滞之反映。", ["涩"]], "10091": ["主病", "劳伤失血，脉细为阴血亏耗、脉道不充之象。劳伤既久，气血内损，失血之后，营血更虚，脉道失于充盈，故脉细如线。细脉主虚，此段以脉细点明失血之因在于劳伤，正气已亏，非暴失血可比。", ["细"]], "10092": ["预后", "脉微为阳气衰微、正气大亏之候。形痹者，阳气不能温煦形体，故麻木不仁。原文谓“正气已亏，温邪未净”，正虚而邪恋，脉微示抗邪无力，症势不轻。微脉在此提示正不胜邪，预后堪虑，非轻浅之疾。", ["微"]], "10093": ["兼症", "左脉数，左属心肝，数为热象。心火亢盛，上刑肺金则咳嗽；肝火上炎，扰及清窍则耳聋。数脉主热，此段以左脉数点明咳嗽耳聋之因在于心肝火旺，热邪内扰，非外感风寒之咳，亦非肾虚之聋。", ["数"]], "10094": ["误治", "脉弦劲如循刀刃，为肝阴亏耗、木失柔养而亢逆之象。郁则络瘀气痹，失血气逆，法当宣通，然脉弦劲示正气已虚，阴不制阳，若再行宣通攻伐，必更伤正气。故当以甘缓柔肝，不可峻通，此脉示禁宣通之误。", ["弦", "劲"]], "10095": ["病机", "脉涩为血少脉滞之征。血虚不能濡养筋脉，虚风内动，故肢麻；脾虚运化失职，痰湿内生，故痰多。原文谓“虚风鼓动使然”，涩脉示营血亏虚，筋脉失养，内风由虚而生，非外风所致，痰多亦因虚而生。", ["涩"]], "10096": ["主病", "头重脘闷而脉弦，弦为肝脉，主气机郁滞、痰湿内阻。清阳不升则头重，中焦气滞湿阻则脘闷，脉弦正应肝郁乘脾、湿浊内停之机，故以弦脉提示气郁湿滞为患。", ["弦"]], "10097": ["病机", "左脉弦劲，为肝阴亏虚、厥阳偏炽之象。弦劲乃阴不制阳、肝气刚劲失柔所致，虽可暂泻络瘀，然脉象示肝阴颇亏，久泻必伤正，故原文诫不宜以此为长计，弦劲在此主阴虚阳亢之病机。", ["弦"]], "10098": ["主病", "脉浮弦，浮主表、主风，弦主肝、主饮。浮弦相合，多示外风引动肝气，或风邪挟痰饮为患，病位偏表而涉肝木，故以浮弦提示风邪与肝郁相兼之证候。", ["浮", "弦"]], "10099": ["兼症", "脉涩主血少气滞、脉络不畅。咳嗽而背凛，涩脉示肺气不利、营血运行滞涩，背凛为阳气不布之兼症，故涩脉在此反映气血涩滞、肺失宣降而兼寒象之候。", ["涩"]], "10100": ["病机", "脉沉迟，沉主里、迟主寒，阳气殊虚可知。阳虚则湿痰内阻经隧，右眶跳跃乃痰湿阻络、虚风内动之兆，原文称为类中之萌，沉迟正示阳虚寒湿内盛、络脉不畅之病机。", ["沉", "迟"]], "10101": ["主病", "脉弦数，弦属肝、数主热。咳嗽头胀而见弦数，示肝火偏亢、木火刑金，气火上逆则头胀，犯肺则咳嗽，弦数相合正应肝经郁热、上扰清窍与肺金之证。", ["弦", "数"]], "10102": ["主病", "脉数主热，梦泄咳嗽并见，数脉示相火偏旺、阴虚内热。火扰精室则梦泄，虚火上炎犯肺则咳嗽，故数脉在此提示阴虚火旺、心肾不交之病机。", ["数"]], "10103": ["预后", "病后脉数不复，数脉本主热，病后久数不退，示阴液耗伤、虚热内生，原文断为三阴亏矣。数而无力属虚数，反映真阴亏损、虚阳不敛，故诫谨慎调理，弗致重损，数脉在此主预后之阴虚难复。", ["数"]], "10104": ["病机", "脉细数，细为阴血亏虚，数为虚热内生。咳嗽音哑乃肺金受灼、金水不能相生所致，故曰“此属阴损”。阴损及金水，治当金水同治，滋水清金，以复肺肾相生之机。", ["细", "数"]], "10105": ["病机", "久嗽腰痛、行动气逆，显系肺肾两虚，气不归元。脉细为阴血不足之征，失血则阴血更亏，脉道不充。此脉细主阴血虚损，与久嗽伤肺、腰痛肾虚、气逆不纳诸症相应，病机在肺肾阴亏、气失摄纳。", ["细"]], "10106": ["预后", "温邪脉小，小为脉道收敛、邪气内陷之象。温邪本应脉浮数，今反脉小，说明正气不足抗邪，邪热有内闭心包或内陷营血之势，故“怕其内闭”。此脉小主邪陷正虚，预后当警惕热闭神昏之变。", ["小"]], "10107": ["病机", "脉弦涩，弦主气机郁滞，涩主血行不畅。肢麻痰多乃阴血亏虚、筋脉失养，兼痰浊阻络所致。原文“阴血颇亏”点明病本，虽有痰阻，但“以末治之”，示人痰为标、阴血亏为本，弦涩脉正合阴亏血滞、痰阻气郁之机。", ["弦", "涩"]], "10108": ["病机", "脉数无序，数主热，无序为热扰脉道、躁动不宁。上焦肺气燥矣，燥热灼津，肺失清肃，故胸臆隐隐痹痛。燥热伤肺络，最怕咳吐痰血。此脉数无序主肺燥热盛、络伤血溢之机，与胸痹、咳痰血诸症相应。", ["数"]], "10109": ["病机", "脉弦腹痛，弦主气机紧张、阴寒内结。便泄不爽乃下焦阳微，阴浊僭逆，气机不通所致。阳微不能温运，阴浊乘虚上逆，故腹痛而便泄不爽。此弦脉主阴浊内盛、阳气式微之病机，与腹痛、便泄不爽相应。", ["弦"]], "10110": ["病机", "脉歇即歇止，为脉气不续、阴阳不相接续之象。阳伤则气不运，阴干则血不濡，故便泄腹膨。阳伤阴干，中焦失运，水湿内停，故腹膨；脾阳不升，故便泄。脉歇主阴阳两伤、气血不续，宜节食物以护中焦。", ["歇"]], "10111": ["病机", "食下拒纳，左脉弦数。弦主肝气郁结，数主热，左脉候肝，肝郁化热，横逆犯胃，胃失和降，故食下拒纳。此属噎格，病机在肝郁化火、胃气上逆，弦数脉与噎格之食入即拒相应，示肝胃不和、气火内郁。", ["弦", "数"]], "10112": ["病机", "温邪郁于肺卫，本应脉浮数，今反脉微，说明邪郁气机不畅、正气不足以外达，肺失宣降故咳嗽音嘶。脉微主阳气虚衰或气血不足，此处与温邪郁肺并见，提示正虚邪郁、宣透无力，非单纯表实证。", ["微"]], "10113": ["病机", "脉弦为肝气偏旺，涩为血少阴亏，弦而涩并见，说明肝阴颇亏而中气亦弱，肝木失养则弦，血行不畅则涩。故治以肝胃同治，既养肝阴又健中气，脉象反映虚实夹杂之候。", ["弦", "涩"]], "10114": ["病机", "左脉数，左候心肝肾，数主热。单言左脉数，提示阴分有热或肝心火旺，热扰血分则脉数。原文仅此一句，未及兼症，当从数脉主热、左部候阴血之热理解其病机。", ["数"]], "10115": ["预后", "脉微不耐按，说明正气虚极、真元已惫，按之更弱则根本将脱。此时邪气虽在亦无暇顾及，正虚不能胜邪，故症危不易图治。脉微不耐按为元气败绝之象，主预后不良。", ["微"]], "10116": ["病机", "脉弦滑，弦主饮癖气结，滑主痰湿，合之说明痰饮内阻。疟后伏湿未净，升降之机失司，湿酿为浊邪，流注经络则左肢麻木。脉象与痰饮内阻、浊邪酿生之病机相应。", ["弦", "滑"]], "10117": ["病机", "脉来弦涩，弦主气结，涩主血瘀。喜饮热酒致胃络积热血瘀，中脘痹痛、谷食渐减。年近五十营血渐亏，弦涩示营枯气结，日久恐成关格之患，脉象反映血瘀气滞、营阴耗伤之机。", ["弦", "涩"]], "10118": ["病机", "形寒咳嗽而脉小，小脉主气血不足、阳气虚弱。形寒为阳虚外寒之象，咳嗽为肺气不宣，脉小说明正虚不能抗邪，肺卫阳虚。脉症合参，属虚寒咳嗽、阳气不足之候。", ["小"]], "10119": ["病机", "哕逆脉弦，弦为肝木之象，哕逆由胃气上逆所致。脉弦说明肝木乘虚犯胃，胃虚木乘使然，胃失和降则气逆为哕。脉弦在此标示肝木偏亢、乘侮胃土之病机。", ["弦"]], "10120": ["病机", "脉小为阳气微弱之象，阳微则失于卫护，故见肢麻；阳气不运，痰饮内阻，阻滞经络，日久气血不能濡养肢体，有类中之患。原文以“脉小肢麻”点明阳微失护、痰饮内阻之病机，脉小正是阳气不足、推动无力之征，与肢麻、类中风险相应。", ["小"]], "10121": ["兼症", "久利伤阴耗液，脉道不充，故脉涩；腰为肾之府，久利及肾，肾精亏虚，腰府失养，故腰酸。原文“久利。脉涩腰酸”以脉涩示阴血不足、脉道不利，腰酸为肾虚之兼症，涩脉与久利、腰酸相应，主阴伤血少之病机。", ["涩"]], "10122": ["病机", "脉微为阳气衰微之象，阳伤则气不充脉，故脉微；三疟久发，阳气耗伤，形浮者乃阳虚不能化气行水，水气浮溢肌肤。原文“脉微阳伤。三疟形浮”以脉微点明阳气损伤之病机，形浮为阳虚水泛之症，脉微与阳伤、形浮相应。", ["微"]], "10123": ["病机", "脉细涩为阴精亏少、脉道不利之象。肺卫虚则易感客邪，少阴肾精亦亏，精血不足，脉道不充故细涩。原文“脉细涩。少阴肾精亦亏”说明细涩脉主肾精亏虚，与肺卫虚易感客邪相应，故当培补、滋养柔金、清肃卫热。", ["细", "涩"]], "10124": ["病机", "左脉弦涩，弦为气机不畅，涩为血行不利。心营暗耗，阴血不足，脉道不充故涩；心阳不宁，气机郁滞故弦。原文“左脉弦涩。心营暗耗。心阳不宁”以弦涩示心营亏耗、心阳不宁之病机，与寤多寐少、心悸怵惕相应，故静养为主。", ["弦", "涩"]], "10125": ["其他", "原文仅载“左脉弦”三字，未附症候与病机论述。弦脉主气机郁滞、肝胆不和，亦主饮邪、痛证。此段信息简略，仅记录左脉弦象，未明言所主何病，故归为其他，脉弦为唯一要素，不作过度推断。", ["弦"]], "10126": ["其他", "原文仅载“脉微”二字，未附症候与病机说明。微脉主阳气衰微、气血不足，为虚损之象。此段信息简略，仅记录脉微，未明言所主何病何机，故归为其他，脉微为唯一要素，不编造原文所无内容。", ["微"]], "10127": ["病机", "脉弱为气血不足、真元亏虚之象，带数则为虚热内扰。原文“脉弱带数。真元颇亏。内热咳呛”以弱数脉示真元亏损、内热内生之病机，弱主正虚，数主内热，与咳呛相应，说明虚损基础上兼有内热之候。", ["弱", "数"]], "10128": ["病机", "脉弦为肝木偏旺之象，弦主气机郁滞、木来克土。原文“胁痛绕脘”正是肝气横逆、犯及中焦之症，“得饮食则缓”说明中气尚能暂扶，然“营气困耳”点出营血被郁遏。弦脉在此标示肝郁乘脾、营气受困之病机，治以辛甘，辛以散肝、甘以缓急。", ["弦"]], "10129": ["病机", "脉细主气血不足、阳气衰微。原文“疟伤脾阳”明言疟邪久延损伤脾阳，脾失健运则“脘闷少运”，脉细正是脾阳不振、气血生化乏源之征。细而无力，非实邪壅滞，故法宜温理中焦，温复脾阳以运化。", ["细"]], "10130": ["病机", "脉弦数为木火偏亢、阴营受损之象。弦属肝，数主热，热灼营阴则“色萎”，故原文断为“营损之象”。弦数并见，说明肝热内扰、营血被耗，非单纯虚损，治“益以甘缓”，以甘药缓肝之急、养营之损。", ["弦", "数"]], "10131": ["病机", "脉微为阳气衰微、气血俱虚之候。原文“久泄瘕聚”，久泄伤脾，脾阳虚衰则运化失职；瘕聚乃气机凝滞、阴寒内结。脉微正说明正气已衰、阳不胜阴，久泄与瘕聚并见，属虚寒夹积之病机。", ["微"]], "10132": ["预后", "左脉弦劲，为肝木偏亢、失于柔和之象。原文“有年气弱，食下少运”示脾胃已衰，而肝邪僭逆，木来克土，弦劲不缓则胃气受戕。故断“将来恐有关格之患”，即肝逆犯胃、升降将废之预后，弦劲在此为病情进展之警。", ["弦"]], "10133": ["病机", "脉涩主气滞血瘀、脉道不利。原文“嗽逆不得卧，短气”，乃肺气壅逆、宣降失司；气机痹阻则血行不畅，故脉见涩。涩脉在此标示气逆而兼血滞、肺络不畅之病机，短气与嗽逆并见，说明气机郁滞为关键。", ["涩"]], "10134": ["病机", "脉弦数为温邪化热、木火偏旺之象。温邪犯肺作咳，热郁气逆则咳；弦属肝、数主热，热邪内炽易灼伤阳络。原文“恐咳伤阳络失血”，正是从弦数之脉预判热伤血络之病机转归，弦数在此标示温邪化热、有动血之虞。", ["弦", "数"]], "10135": ["病机", "脉软为正气不足、气血渐衰之象。原文“肝风痉厥”之后“色萎脉软”，说明风阳虽平而正气已馁，脉失刚劲乃气衰不能鼓动。故断“气渐馁矣”，治宜甘缓益之，扶养正气，不必见病治病，软脉在此标示正虚当补之病机。", ["软"]], "10136": ["主病", "脉数主热，热邪灼肺，肺失清肃则咳嗽；热伤血络，血不循经而失血。数脉为火盛之象，失血咳嗽并见，说明热迫血妄行、肺络受损，病机属热伤肺络、气火上逆，故以数脉统括失血与咳嗽二症。", ["数"]], "10137": ["病机", "脉涩为血少气滞、脉道不利。左肢麻、胁痛不能左眠，乃肝血亏虚、络脉失养；大便溏泄为木不疏土、阳明失阖。原文断为「肾真空虚，木少涵养，厥阳冲扰」，涩脉正应精血空虚、血行艰涩之机，故主肾虚肝失涵养、厥阳上扰之证。", ["涩"]], "10138": ["治法", "脉细为阴血不足、脉道不充。咳嗽音嘶，乃少阴阴液亏虚，不能上承咽喉，声门失润所致。细脉主虚，说明病本在少阴精血内损，非外邪壅肺。原文「宜摄少阴」，即针对细脉所现的阴亏之本，以固摄少阴为治，故归治法。", ["细"]], "10139": ["病机", "原文未出脉名，以「少阴空虚」立论。少阴之脉循喉咙，阴精亏少不能上承，则咽干隐隐燥痛、音声不润；冲气上逆，卧则气壅于肺而咳呛。此段说明阴少阳亢、冲气上逆之病机，咳呛咽干皆由少阴空虚、阴不制阳所致，与脉象无直接对应。", []], "10140": ["预后", "脉带歇即歇止不匀，为正气虚衰、心阳不振之象。阳伤挟邪，形凛发热咳嗽，正虚而邪恋，脉见歇止说明阳气亏败、鼓动无力。原文「恐喘急」，是预判正不胜邪、肺气欲脱而喘，故本段主旨在于提示病情转归之险，属预后判断。", ["歇"]], "10141": ["预后", "脉微为阳气衰微，按之数则阴分亦损，虚数无力，是阴损及阳之候。咳嗽、食下便溏，脾肺俱虚，纳运失职。原文谓「殊不易复，须胃强能纳，庶可撑持」，说明微而数之脉反映阴阳两伤、胃气衰败，恢复取决于胃气能否渐强，故属预后之论。", ["微", "数"]], "10142": ["其他", "原文仅存「脉弦」二字，无症可参。弦脉为肝之主脉，主气机郁滞、木旺克土，亦见于饮邪内停、痛证。因上下文缺失，不能确指所主何病，仅能就脉论脉，故归其他，不作具体病机推断，以免附会原文所无之症。", ["弦"]], "10143": ["预后", "络伤失血而脉弦虚，弦为肝木偏亢、虚为血去正伤，脉证相合则示阴血亏耗、肝阳不敛。原文「恐其难耐夏热」，因夏热助阳耗阴，虚弦之脉本已阴血不足，逢暑热更易动血伤正，故预判难支，属预后之论，紧扣弦虚与失血并见之机。", ["弦", "虚"]], "10144": ["病机", "脉弦主噎格，因胃气空虚，弦为气机不畅、胃气不足之象。胃气空则受纳失常，食入格拒，故脉弦而乏力，用参补虚，然胃气已空，图功不易。", ["弦"]], "10145": ["兼症", "精浊日久，阴精耗损，咽干脉细。细脉主阴血亏虚，精浊久则肾阴不足，虚火上炎故咽干，脉细为阴精内亏之征。", ["细"]], "10146": ["主病", "脉细而涩，细主血虚，涩主血行不畅。脘痛食下拒纳，乃血格之候，因血虚气滞、瘀阻胃脘，故食入即拒，症情较重。", ["细", "涩"]], "10147": ["病机", "少阴阳虚，饮逆喘急不得卧，脉微为阳气衰微之象。阳虚不能化饮，饮邪上逆迫肺，故喘急不得卧，法宜温纳以复阳气。", ["微"]], "10148": ["病机", "脉涩火升，食下不适即漾漾欲呕，究属下焦空虚，气冲无制。涩脉主虚滞，下焦空虚则气失摄纳，冲逆而上，故见呕恶，法宜填摄。", ["涩"]], "10149": ["治法", "虽属瘀血，上吐下泄，中焦气暗伤，色萎脉涩，耳鸣神倦，行动气逆。涩脉主血虚气滞，瘀血虽存而正气已伤，当治以甘温益虚，不宜攻瘀。", ["涩"]], "10150": ["治法", "脉涩，少腹症积攻逆作痛，心中嘈杂，症积痹在血分。涩主血瘀，然营血颇虚，只宜养之和之，不可峻攻，攻则伤正。", ["涩"]], "10151": ["病机", "脉弦饮也，饮阻则阳郁，是以背痛形凛。弦脉主饮，饮邪阻遏阳气，阳郁不达故背痛恶寒，宜以温药和之，化饮通阳。", ["弦"]], "10152": ["病机", "血止而身痛，左脉尚弦，弦为肝脉，主气机郁滞、络脉不和。血虽止而肝郁未解，气滞血瘀，不通则痛，故身痛。脉弦提示病机重点在肝郁气滞，与出血后络脉未和相应。", ["弦"]], "10153": ["病机", "食下气噫胸痛而脉涩，涩主血少气滞、血脉瘀阻。血阻气痹，胃气不降，故食下气噫胸痛。高年噎格之渐，正因瘀血阻络、气机不通所致，脉涩为瘀血内阻之征。", ["涩"]], "10154": ["病机", "胁痛失血，左脉弦，弦为肝脉。气逆欲喘、背恶寒心中热，乃少阴不藏、肝阳扰络，络瘀而血外溢。脉弦主肝阳亢扰，非单纯瘀血，故切勿攻瘀，重虚其虚。", ["弦"]], "10155": ["病机", "嗽不减而左脉弦，弦主肝木偏亢。肝气上逆犯肺，肺失肃降，故咳嗽不减。脉弦提示病机在肝郁气逆，与咳嗽持续相应，非单纯肺脏本病。", ["弦"]], "10156": ["病机", "脉弦劲，弦而劲急，主肝阳亢盛、气机劲急。肝阳上扰，络脉紧张，故脉来弦劲有力。此脉象提示肝阳偏亢、内风欲动之病机，与眩晕、抽搐等症候相应。", ["弦"]], "10157": ["病机", "形丰而脉小，小脉主阳气不足。形丰本应脉大，今脉反小，的是阳气外越、阴湿下著。腿浮酸痛，湿邪下注。脉小示阳气虚浮不敛，温药不宜，恐助阳外越。", ["小"]], "10158": ["病机", "梦泄盗汗而左脉弦数，弦主肝阳，数主热。脏真内亏，阴不制阳，阳浮不潜，故脉弦数。梦泄盗汗为阳浮不潜、阴液外泄之征，脉象与脏真内亏、虚阳上浮相应。", ["弦", "数"]], "10159": ["病机", "复胀色萎，脉弦气急，弦为肝脉，主气机劲急。非胃府病，乃下焦阳衰，阳衰不能温运，气机逆乱，故脉弦气急。与前胀满迥异，提示病本在下焦阳虚。", ["弦"]], "10160": ["病机", "久嗽用肺药不应而脉数，说明病非独在肺，数脉主热，热灼金水，肺肾同病。单治肺无效，故须金水同治，兼顾肾阴以制虚热。数脉在此提示内热未清、阴液受灼，与久嗽不愈相应。", ["数"]], "10161": ["病机", "脉长主气机有余、阳热偏盛，长而太过则阳升不降，血随气上溢而为鼻衄。原文直言「阳升使然」，说明此长脉反映阳气升腾、血热妄行之机，鼻衄是阳升之果，非单纯鼻窍局部病变。", ["长"]], "10162": ["病机", "脉动搏且长，动主惊动不安，长主火气有余，合而示相火偏炽、阴分失固。火扰阴伤，故咳呛痰血，最易成损。原文归因于欲念动心、精摇于下，强调相火妄动为损证之根，脉象正是火动阴亏之征。", ["动", "长"]], "10163": ["病机", "梦泄而脉虚尺微，虚为气血不足，微为阳气衰微，尺部候肾，尺微尤显肾气亏虚、封藏失职。精关不固故梦泄，脉虚尺微正说明下元虚衰、不能固摄，病机重在肾虚不藏而非实火扰动。", ["虚", "微"]], "10164": ["主病", "脘痛脉弦，弦为肝脉，主气机郁滞、筋脉拘急。肝气犯胃、木郁克土，则脘部作痛，脉象应之而弦。此段以脉弦点明脘痛之因在肝郁气滞，非单纯胃腑虚寒，弦脉正是肝木偏旺、气机不畅之反映。", ["弦"]], "10165": ["病机", "右脉尚弦，右部候肺与脾胃，弦为肝木之象。右脉尚弦说明肝气仍未平复，木邪尚犯中上二焦，病机为肝郁未解、气机尚滞。原文着一「尚」字，示弦象未除、病情未尽，须继续调畅肝气。", ["弦"]], "10166": ["病机", "脉弦而头旋恶心，弦主肝旺气逆，肝风上扰清窍则头旋，肝气横逆犯胃则恶心。脉弦正是肝木偏亢、风阳上旋之征，头旋恶心为肝胃同病之外候，病机关键在肝气上逆而非单纯痰湿。", ["弦"]], "10167": ["病机", "腿软头眩而脉细，细主阴血亏少、脉道不充。精血不足，下不能充养筋骨则腿软，上不能奉养清窍则头眩。脉细正说明虚损在阴分精血，病机为肝肾亏虚、精血不能上荣下养，非实邪为患。", ["细"]], "10168": ["主病", "原文仅言「脉弦」，弦为肝脉，主气机郁滞、木旺乘土或饮邪内停。弦脉端直以长，如按琴弦，反映脉道拘急、气血收敛不畅，故主肝胆病、痛证、痰饮。此段未兼他脉，提示以肝郁气滞或饮停为基本病机，临证当结合症候辨其属气、属饮、属痛。", ["弦"]], "10169": ["病机", "原文作「脉弦虚」，弦为肝旺，虚为不足，二者并见，说明肝气偏亢而中气或阴血已亏，属本虚标实之象。弦而不任重按，是木郁土虚、气血不能充脉之征，主肝脾不和、虚风内动或久病体虚兼气郁，与倦怠、胁胀、食少等症相应。", ["弦", "虚"]], "10170": ["病机", "原文言「左脉数。按之无序」，左脉候心肝肾，数而无序是阴亏不能制阳、阳动躁扰之象，故断为「阴亏阳动」。阴不守则阳不藏，日久虚火灼络，恐致失血，故云「恐有失血之累」；鼻血、咳呛、项核皆上焦郁热之症，故先宜清理上焦，标本兼顾。", ["数"]], "10171": ["病机", "肝胃同治虽「颇应」，但「脉数」未平，说明内热未清；耳鸣、梦泄并见，是肾阴不足、相火不藏，虚热上扰清窍、下扰精室。数脉主热，此热属阴虚阳浮之虚热，故治法当由肝胃转向「填补下焦」，滋肾潜阳，使火归水中而脉数自减。", ["数"]], "10172": ["预后", "「左脉数」而见渴饮、晡热，是脏阴失守、阳浮外泄之虚损脉症。数脉本主热，此属阴亏阳越之虚数，阴愈亏则阳愈浮。原文断「虚损致此。最不相宜」，又虑「夏气泄越。阴愈耗也」，指出时令升泄更耗其阴，预后堪忧，属虚损危候之警示。", ["数"]], "10173": ["预后", "「脉数无序」言数而参差不齐，非实热之数，乃脏阴亏损、虚阳躁动之象；合色萎、形瘦、身热，正《内经》所谓阴损及阳、形神俱衰之候。原文断「脏阴损矣」，并戒「急急防维。勿忽视之」，明示此脉此症预后险恶，当及早固护真阴，防其虚脱。", ["数"]], "10174": ["兼症", "原文「久嗽。左脉弦」，久嗽伤肺，左脉候肝，弦为肝旺。久咳不愈而左脉弦，提示肝木偏亢、木火刑金，或气郁化火上逆犯肺，属肝咳、木叩金鸣之机。此段以脉带症，说明久嗽之因不独在肺，当兼调肝气，与胁痛、咳引胸胁等症相应。", ["弦"]], "10175": ["预后", "温侵嗽盛，清之为适，然「脉微涩」则阳气衰微、阴血涩滞，气血俱不足；合形瘦食少，是脾胃衰而真元亏。原文断「真元颇亏」，又叹「年未及五。乃未老先衰之象」，以微涩之脉与形症相参，示正气大伤、早衰之预后，非单纯清嗽所能挽回。", ["微", "涩"]], "10176": ["病机", "原文言食下格拒、痰涎泛溢而脉来歇，歇为脉来中止、不能接续之象。痰浊上阻，胸阳不宣，气机升降被遏，故脉道不利而歇。此歇非虚寒之代，乃实邪壅塞、阳气不宣所致，主痰浊阻膈、食入即拒之证，与痰涎泛溢、格拒不下相应。", ["歇"]], "10177": ["病机", "原文仅载左脉弦数。弦为气机郁滞、木失条达，数为郁而化热之象。左脉候肝，弦数并见，说明肝郁化火、气火内扰。此脉主肝经郁热之病机，可与情志不遂、胁胀、口苦、烦躁等肝火症候相应，属病机判断而非单主一病。", ["弦", "数"]], "10178": ["平脉", "原文仅载脉缓。缓为脉来从容和匀、不快不慢之象，无弦紧数涩之偏，是胃气充足、气血调畅之常脉。此段以缓为平，说明脉象和缓有神，主脾胃健运、正气未伤，与病脉之缓弱、缓滑不同，故归平脉，不作病机论。", ["缓"]], "10179": ["病机", "原文脉弦劲而见咳嗽，并指出宜摄脏阴。弦劲为脉来挺直有力、少柔和之气，是肝阳偏亢、阴不涵阳之象。脏阴亏虚，不能濡养肝木，肝阳上逆犯肺，故咳嗽。此脉主阴虚阳亢、肝肺不调之病机，与咳嗽、阴亏症候相应，故治宜摄脏阴。", ["弦", "劲"]], "10180": ["病机", "原文仅载左脉弦。左脉候肝，弦为肝之主脉，亦为气机郁滞、木失柔和之象。单弦而不兼数、劲，说明肝气郁结、疏泄不利，尚未化火伤阴。此脉主肝郁气滞之病机，可与胸胁胀满、情志抑郁、嗳气等症候相应，属病机层面的判断。", ["弦"]], "10181": ["病机", "原文仅载脉小。小为脉体细弱、不大不充之象，主气血不足、正气亏虚，亦可见于邪退正衰之际。脉小说明营血不充、脉道失盈，脏腑功能偏弱。此脉主虚损之病机，可与形瘦、乏力、气短、纳少等气血不足症候相应，须结合形症辨其虚实。", ["小"]], "10182": ["兼症", "原文载左脉弦数而见咽痛如梗。弦为肝郁，数为化热，左脉候肝，说明肝郁化火、气火上炎。火性上灼，结于咽喉，故咽痛如梗，非外感风热之咽痛。此段以脉弦数映证咽痛之病机为肝火郁结、上扰咽喉，脉与症相兼而见，故归兼症。", ["弦", "数"]], "10183": ["病机", "原文形盛脉微，明言阴浊内盛、阳困不宣。形盛而脉反微，是形体虽丰而阳气困顿，阴浊壅遏，脉道鼓动无力。食下䐜胀、中脘胀痛，皆阳不通运、阴浊上干之象。原文强调阳以通为运，久痛非寒，不宜辛热刚愎，惟当和之，故脉微主阳困阴盛之病机。", ["微"]], "10184": ["主病", "脉细涩，细为营血不足、脉道不充，涩为血行不畅、滞而难行。带下赤白，赤属血分、白属气分，细涩之脉提示气血两亏而兼瘀滞，冲任不调，湿浊下注。脉细涩与赤白带下相应，说明病机在血虚夹滞、营卫不和，非单纯湿热下注可比。", ["细", "涩"]], "10185": ["病机", "左脉弦，弦为肝脉，左候心肾阴分。原文谓「少阴空虚，阳浮不潜」，阴亏于下则阳无所附而上浮，故见不时神烦、头旋；腰为肾府，阴虚无以充养则腰酸；食下少运乃中气亦弱。弦脉在此非实邪，乃阴不制阳、肝阳浮越之象，故药饵弗宜偏于温热，恐助浮阳。", ["弦"]], "10186": ["病机", "脉小为阳气不振、气血不足之象。原文言「阳未振动」，阳气微弱不能鼓动脉道，故脉小；肺开窍于鼻，主一身之气，气弱阳微则鼻失温煦，自觉鼻孔凉生。脉小与鼻凉相印证，说明病机为肺气虚弱、阳气不充，属气虚阳微之候。", ["小"]], "10187": ["病机", "脉小为正气不足、阴血亏少。原文谓「水涸阳乃浮矣」，阴液枯涸于下，阳气失所依附而浮越于上，故咽痛暮盛、午后形凛；痰多乃虚阳上扰、津液不化所致。脉小与咽痛、形凛并见，说明本虚而阳浮，病机在阴涸阳浮，非实热壅盛。", ["小"]], "10188": ["主病", "脉数为热，阳热内盛则脉行急迫。原文「内热背痛」，热郁于内，气血壅滞，背部经络不畅故痛。数脉主内热，与内热背痛相应，说明病机为里热内蕴、气血失和，热邪鼓动血脉而现数象。", ["数"]], "10189": ["治法", "脉涩为血行不畅、营卫涩滞。身痛而脉涩，非外感表实，乃营卫不和、气血痹阻，不通则痛。原文「宜和营卫」，正针对涩脉所反映的营阴不足、卫气不谐，治当调和营卫以通血脉，使涩滞得行而身痛自解。", ["涩"]], "10190": ["其他", "原文仅载「脉数」二字，无数脉所兼之症可参。数为热象，主阳热亢盛或阴虚内热，脉行急迫而逾常度。因缺乏具体症候，只能就脉论理：数脉提示有热，或实或虚，须结合他诊辨析，本条仅存脉象，未及主病与兼症。", ["数"]], "10191": ["病机", "冲疝里急腹痛，法宜温养，然脉来弦涩。弦主气滞、亦主肝急，涩为营阴亏少、血行不畅；原文谓「寤多寐少，营阴颇亏」，阴亏则脉道不充而涩，气机不畅则弦。弦涩并见说明虽有寒滞，但营阴已亏，故偏于辛热不宜，恐耗阴助燥。", ["弦", "涩"]], "10192": ["主病", "久嗽而见形寒身痛，是外寒引动宿饮、肺卫失宣。脉浮主邪在表，弦主饮邪内伏、气机不和；浮弦并见，说明表寒未解而里有痰饮，故久嗽不愈兼形寒身痛，当从外寒内饮解。", ["浮", "弦"]], "10193": ["病机", "原文仅言脉细，细为营血不足、脉道不充之象，主虚主湿。此段以脉细提示正气亏虚、阴血不能充盈脉道，病机重心在虚，而非实邪壅盛，故辨证当着眼于补养，不可妄施攻伐。", ["细"]], "10194": ["病机", "络痹、右胁癖积而脉涩，涩主血行不畅、脉络瘀阻。积块阻于胁络，气血不得流利，故脉来艰涩；原文点明法宜通泄，正说明涩脉所主为瘀滞实证，当通络化积，使气血畅行则脉自和。", ["涩"]], "10195": ["病机", "脉弦而来去不调，是肝气失疏、营卫不和之象。营卫失调故不饥，气机郁滞故胸臆时痛时止；弦主气机劲急，来去不调示气血运行失其常度，原文谓法宜和之，即调和营卫、疏畅气机。", ["弦"]], "10196": ["病机", "原文仅存左脉尚弦一句，左脉候肝，弦为肝气偏旺、气机不和之征。尚字示弦象未除，说明前证虽减而肝郁气滞之机仍在，病机重点在肝失条达，当继续疏肝和营，不可因症减而骤停调治。", ["弦"]], "10197": ["病机", "脉弦数，弦主肝郁气滞，数主热盛。弦数并见，说明肝郁化火、气分有热，病机为郁热内扰、肝火偏亢。此脉提示热由郁生，治当疏肝清热并举，单清其热而不解其郁，则热易复起。", ["弦", "数"]], "10198": ["病机", "晡热而右脉弦大，右脉候肺脾，弦大为邪盛气壅之象。原文谓阴弱伏温，是阴分不足而温邪内伏，至晡时阳入阴分则热作；弦大示伏温鼓动、正气尚能抗邪，故治以养阴和阳，透解伏温。", ["弦", "大"]], "10199": ["病机", "五志内燔致心悸舌糜，本属火郁阴伤，宜存阴泄阳。然脉弦涩，弦主气郁，涩主阴血不足、脉络不畅，说明郁火内灼已伤阴血，脉道不利；故原文告诫不宜过于苦寒，以免更伤阴血、遏抑气机。", ["弦", "涩"]], "10200": ["病机", "形丰而脉微，是阳气自薄，不能外充形体。前用六味地黄纯阴碍阳，致心悸阳痿，乃阴翳蔽阳之候。脉微为阳虚之征，故议通阳以消阴翳，紧扣“阳气自薄”之机。", ["微"]], "10201": ["主病", "冷物伤中，脘痛而脉沉。沉脉主里，寒伤中阳，气机凝滞，故痛而脉应之沉。此寒邪直中，里阳受困，非表证之比，主病在里。", ["沉"]], "10202": ["病机", "脉弦长为木火偏亢之象，嗜酒更助胆热，故口糜味甜。弦主肝，长主火，木火循经上炎，法宜苦辛泄之，紧扣“木火偏亢”与“胆热”之机。", ["弦", "长"]], "10203": ["预后", "高年病后脉歇，知饥而营血枯矣。脉歇为气血不续之兆，高年病后阴血亏耗，虽便艰不可攻涤，恐更伤营血。此示预后当顾营血，勿妄攻下。", []], "10204": ["病机", "食下少运便泄，少腹气坠，脉细。细为气血不足，命门火虚则清阳下陷，运化失职，故食少便泄、气坠。日久恐腹满气急，乃火虚陷下之机。", ["细"]], "10205": ["预后", "嗽逆脉数，数为热，肺阴耗耳。阴虚生内热，肺失清润则嗽逆，脉数应之。恐延肺痿，乃阴耗日久，肺叶焦枯之虞，示预后当早顾肺阴。", ["数"]], "10206": ["病机", "脉涩不利，梦泄食少内热。涩为阴亏血少，少阴阴亏则虚火内扰，谷气水湿下注，乃阴亏湿热之候。涩脉不利，正合阴亏湿滞之机。", ["涩"]], "10207": ["病机", "脉弦劲为木火偏亢之象，逼络血溢，血失反能食，阳明亦热矣。弦劲主肝火亢盛，火迫血妄行，阳明热则消谷，故议苦降法以折木火。", ["弦", "劲"]], "10208": ["病机", "血虽止而脉尚弦数，弦为阳动不潜，数为阴亏生热。晨起咳呛乃阴虚阳扰、肺失清肃之象。脉象未随血止而平，说明阴亏未复、阳动不潜，故以静养为主，使阴阳渐归和平。", ["弦", "数"]], "10209": ["病机", "失血后脉涩，涩为血少阴伤、脉道不充；咳呛乃肺胃阴亏、虚火上逆。失血伤阴，肺失濡润则咳，胃阴不足则津亏。脉涩与咳呛并见，主肺胃阴虚，故宜养肺胃之阴以复其津。", ["涩"]], "10210": ["病机", "脉弦主肝、主饮。身热从汗泄而解，说明湿郁在里、得汗外透，此属伏湿。弦脉示湿阻气机、肝脾不调，湿郁未清恐转疟。原文以脉弦合汗解身热，辨为伏湿，非单纯表证。", ["弦"]], "10211": ["病机", "劳伤肝阳，阳亢则络松失血；左脉弦为肝阳偏亢之应。左脉候肝，弦乃肝气失柔、阳动不潜。劳伤耗阴，肝阳上扰，络脉不固而血溢。脉弦与失血并见，主肝阳络松，非虚寒失血。", ["弦"]], "10212": ["病机", "右关沉涩，主阳明络脉泣涩；左脉弦劲，主木火内亢。木火亢则灼津，阳明络泣则脘痛嘈杂；火升风动则头旋。弦劲为肝火亢盛之象，沉涩为络脉不畅之征，合示木火内亢、阳明络泣之病机。", ["沉", "涩", "弦", "劲"]], "10213": ["病机", "脉弦腹膨，弦主肝邪，腹膨为气机壅滞。气逆动怒致此，说明肝邪冲逆阳明，胃气不降而胀满。原文明言“肝邪冲逆阳明”，脉弦正是肝气横逆之应。切勿嗔怒，恐肝阳暴动、病情变幻。", ["弦"]], "10214": ["病机", "咳而呕逆，脉虚弦。虚为肝胃气阴不足，弦为肝气偏旺。肝胃不和，气逆上冲则咳呕并作。脉虚弦示正虚而肝旺，故宜益肝胃，使肝柔胃和、气逆自平，非单纯降逆止咳。", ["虚", "弦"]], "10215": ["病机", "脉细神倦，细为气血不足，神倦为气弱之征。气弱则不能统摄，精浊不已，说明气虚失固、精微下泄。原文以“气弱也”点明病机，先宜调益心脾，使气血渐充、统摄有权，精浊自止。", ["细"]], "10216": ["病机", "左脉弦数，弦为肝木亢盛，数为火象，木火顺乘脾土。原文谓“脾阳困顿，木火顺乘，阳明少降”，故见头重、味酸、肢冷。病后脾阳未复，肝木乘虚犯胃，胃气不降，火性炎上则头重味酸，阳气不达四末则肢冷。此脉象揭示肝胃不和、本虚标实之机。", ["弦", "数"]], "10217": ["病机", "脉细虽属少阴空虚，然原文更强调“中焦有伏饮”，饮邪内伏，阻滞气机，故见嗽逆呕恶。细脉主虚，亦主饮阻脉道，此虚中夹实之候。先宜理中焦伏饮，饮去则呕恶自止，不可纯补少阴而碍饮邪。", ["细"]], "10218": ["治法", "脉涩主气血滞涩，淋浊乃湿热蕴结下焦，阻滞脉络，故脉见涩象。原文“法宜导火”，即清利湿热、通导火邪，使涩滞得通，淋浊自愈。涩脉在此非纯虚，乃邪阻脉道之征，故治以通导为法。", ["涩"]], "10219": ["预后", "疳积腹痛而形瘦脉虚，虚脉主气血不足，脾胃衰败。疳积日久，脾胃受损，气血生化无源，故脉虚形瘦。原文“勿忽视之”，警示此虚象提示正气已伤，病情深重，预后堪忧，当及早顾护脾胃。", ["虚"]], "10220": ["病机", "音嘶咽痛而脉细涩，细为阴血不足，涩为脉道不利。原文谓“少阴肾真空虚，无以上承”，肾阴亏虚，不能上濡咽喉，故音嘶咽痛；阴精不足，脉道不充，故细涩。此肾阴涸竭之候，宜静养避暑，切勿烦劳。", ["细", "涩"]], "10221": ["病机", "寒热胁痛而脉弦，弦为肝脉，主气机郁滞。原文谓“温邪袭于肝络”，温邪郁于肝络，枢机不利，故寒热胁痛。吐血犹可，最怕成痈，乃温邪与气血搏结，久则肉腐成痈。弦脉揭示肝络郁热之病机。", ["弦"]], "10222": ["病机", "咳嗽失血而左脉犹弦，左脉候肝，弦为肝气偏亢。原文谓“努力络伤为病”，努力负重，损伤肺络，血溢脉外，故咳血；肝气上逆，木火刑金，故左脉弦。此肝逆络伤之机，弦脉示肝气未平。", ["弦"]], "10223": ["病机", "左脉弦，嗽血气逆，酒客动怒致此。弦为肝脉，酒客湿热内蕴，动怒则肝气上逆，木火刑金，肺络损伤，故嗽血气逆。原文“当理肝胃”，弦脉揭示肝胃不和、气逆血溢之病机，治在平肝和胃。", ["弦"]], "10224": ["病机", "脉涩为血少气滞、血行不畅之象。咳嗽失血后见涩脉，说明血去阴伤、络脉不充，气机涩滞；下焦不纳，是肾失摄纳、气不归元，故咳而失血。原文归因于“春深气泄使然”，春升之气外泄，下元不固，血随气动，脉涩正应血虚气滞、摄纳无权之机。", ["涩"]], "10225": ["病机", "脉长弦数为阴亏阳亢之象：弦主肝旺，数主热，长则气火有余。原文谓“阴亏阳不宁静”，阴不制阳，肝阳偏亢，故脉长弦数。食下便溏，是肾阳亦弱、胃关不固，“肾为胃关”失职，脾运不健。脉象反映阴虚阳扰于上、脾肾不固于下之病机。", ["长", "弦", "数"]], "10226": ["病机", "脉弦而濡，弦为肝木偏旺，濡为湿滞而气弱。原文谓“气分殊弱，湿热不能尽泄”，正气不足则湿浊留恋，肝木乘脾，故不饥少寐、神倦痰多。治宜健脾和胃、佐以远木，即培土以御木、化湿以复运。脉弦濡正示土虚木乘、湿热未清之病机。", ["弦", "濡"]], "10227": ["病机", "脉沉小为阳气衰微、水饮内停之象。沉主里、小主虚，久嗽足浮腹膨，是肺脾肾阳气不足，水饮欲泛。原文谓“少阴之阳已伤”，肾阳不能化气行水，故水饮上逆为嗽、外溢为浮、内聚为膨。脉沉小正应少阴阳虚、水气泛滥之病机。", ["沉", "小"]], "10228": ["病机", "右脉尚弦，右关候脾胃，弦为肝木之象。此段仅存一句，说明肝木之气仍偏旺，木乘土位，脾胃受制。虽未言症，然“尚”字示弦势未减，提示肝旺未平、脾土未复，病机重点在木亢乘土、中焦气机不和。", ["弦"]], "10229": ["病机", "脉细数为阴血亏虚、虚热内生之象。细主阴血不足，数主虚热，原文谓“脏阴下夺，虚损已露”，阴精耗损于下，虚火扰动，故脉细而数。此为虚损已成之候，阴亏不能涵阳，脏真日削，脉象已显劳损之机。", ["细", "数"]], "10230": ["病机", "脉仍弦数，“仍”字示前证未减。弦主肝旺，数主热，肝阳偏亢、虚热内扰之象持续存在。阴亏未复，阳不宁静，故脉象依然弦数。此段提示病机未变，肝阳亢盛、阴不制阳之势仍在，需继续育阴潜阳。", ["弦", "数"]], "10231": ["病机", "舌黄脉缓，缓为脾胃之气呆钝、湿邪留恋之象。舌黄示湿郁化热未净，脉缓非平和之缓，乃湿阻气机、脾运不健。原文谓“脾胃之气呆钝，湿邪未净，故不饥”，湿浊中阻则纳呆。脉缓正应湿困脾土、气机呆滞之病机。", ["缓"]], "10232": ["病机", "脉细数，细为阴血不足，数为热邪内扰。原文“咳呛脘闷”乃暑热犯肺、湿阻中焦之象，脉细数说明暑邪内郁化热，灼伤阴津，故治宜清暑邪，兼护阴液。此脉主暑热伤阴、肺胃不和之病机。", ["细", "数"]], "10233": ["病机", "脉象模糊，乃暑湿秽浊上蒙清窍、阻滞气机所致。原文“头重脘闷”为湿邪困阻之征，“病势正在方张”说明邪气亢盛，脉模糊反映湿浊弥漫、脉道不清，主暑湿上阻、清阳不升之病机。", []], "10234": ["病机", "脉细主阴血亏虚，胃阴不足则食道失润。原文“食下格拒”乃噎膈之象，因阳明津枯、胃气不降所致。脉细说明阳明阴液亏耗，不能濡润通降，故宜理阳明以复其和降之机。", ["细"]], "10235": ["病机", "脉大乍小，大则邪气盛，乍小则邪伏不显，乃邪伏于中、正邪交争之象。原文“邪伏于中”点明病机，脉象忽大忽小反映伏邪内郁、气机紊乱，故宜括痧以透邪外达，再服药调治。", ["大"]], "10236": ["病机", "脉数主热，数为阳亢之征。原文“阴亏阳亢，气逆失血”说明阴虚不能制阳，阳热亢盛迫血妄行，气逆上冲而致失血。脉数正是阳热亢盛、阴不敛阳之反映，主阴虚阳亢、气逆动血之病机。", ["数"]], "10237": ["病机", "脉微数，微为阳气衰微，数为阴血亏虚、虚热内生。原文“脏阴伤矣，冲气不纳，作为劳嗽”说明脏阴耗损，冲脉之气上逆不纳，发为虚劳咳嗽。脉微数反映阴损及阳、虚热上浮之病机。", ["微", "数"]], "10238": ["预后", "脉细数，细主阴精亏耗，数主虚热内扰。原文“阴精不夺乎”“虚损已露”明言阴精已伤，虚损之象显露于脉。脉细数正是阴精亏虚、虚热内生之征，故断为虚损已成，预后当以保真为要。", ["细", "数"]], "10239": ["病机", "脉细数，细为阴气不足，数为暑热内逼。原文“阴气颇弱，夏暑外逼”说明素体阴亏，复感暑邪，致食减神倦咳呛。脉细数反映阴弱热扰、暑伤气阴之病机，故宜存阴清暑法。", ["细", "数"]], "10240": ["病机", "嗽减而鼻衄，左脉弦。咳嗽本属肺气上逆，衄血为阳络受伤；左脉候肝，弦为肝气偏旺、木火刑金之象。咳减而衄作，是气火未平、由肺转伤血络，弦脉正示肝旺失柔、血随气逆，故主此病机。", ["弦"]], "10241": ["预后", "久嗽脉数。久嗽肺气已伤，脉宜缓弱；今反见数，数为热、为阳动，示虚火内扰、阴液耗伤，正气不能敛藏。久病见数脉，是邪热未清而本元已亏，故属病情进展之兆，非单纯外感咳嗽可比。", ["数"]], "10242": ["病机", "阴亏内热，左脉弦数。弦为肝旺，数为热盛；左脉候肝肾，阴亏则水不涵木，木火内炽，故脉弦而数。乙癸同治者，正因肾阴亏而肝阳亢，须滋水涵木、肝肾并调，弦数脉即示此阴虚火旺之机。", ["弦", "数"]], "10243": ["兼症", "暑湿下利而左脉弦，又见鼻衄。暑湿伤中则下利，左脉弦为肝木偏旺、乘脾犯胃；木火上升、迫血妄行则鼻衄。弦脉在此示肝气不舒、湿热内郁而血络受扰，故下利与衄并见，属兼症之候。", ["弦"]], "10244": ["病机", "脉弦数，三阴颇亏。弦为肝木失柔，数为阴分有热；三阴亏虚则水不涵木、虚火内动，故脉象弦而兼数。法宜填摄，正是针对下元亏虚、肝阳不潜之机，弦数脉说明阴亏火旺、封藏失职，而非实热外邪。", ["弦", "数"]], "10245": ["治法", "暑湿成疟，脉虚。疟邪本应脉弦或洪，今脉虚，示暑湿虽留而正气已伤、脾胃虚弱，不能鼓脉。虚脉主不足，故不宜峻攻截疟，宜用和法调和营卫、扶正祛邪，使邪去而不伤正，脉虚正是选和法的依据。", ["虚"]], "10246": ["预后", "失血色夺，脉弦。失血之后阴血亏耗，脉宜细弱；今见弦，是阴血不足而肝失所养、肝气偏强，弦为木旺之象。血夺而脉弦，恐木旺克土致食减，故原文特言恐其食减，示弦脉主肝强、预后须防脾胃受损。", ["弦"]], "10247": ["病机", "脉弦数。弦属肝木偏旺、气机不舒，数属内有热象、阳动不静；二者并见，示肝郁化火、阴分受灼之机。原文仅存脉象，未列症候，然弦数相合，主木火内炽、虚热扰动，为辨证之脉象依据。", ["弦", "数"]], "10248": ["病机", "脉弦为肝阳不潜，涩为阴血亏少，弦涩并见，是阴伤不能涵阳、阳浮于上之象。原文点明“体质阴伤，阳浮不潜”，故见咳嗽内热，乃虚阳上扰、肺失清肃所致。法宜填摄藏真，即滋填下焦真阴以摄纳浮阳，正合弦涩所主之阴亏阳浮病机。", ["弦", "涩"]], "10249": ["预后", "脉数本主热，然“无序”则至数杂乱、毫无胃气，是阴阳俱伤而邪气夹杂之候。数而失序，说明正气不能约束邪气，阴阳相争而脉行躁乱，故原文断为“阴阳挟邪难治”。此非单纯实热之数，乃正虚邪扰、预后不良之象。", ["数"]], "10250": ["病机", "原文未出脉名，专论冲脉为病。冲脉起于胞中，上循咽嗌，其气逆上则“逆气至咽”。此段以冲脉气逆上冲为病机核心，脉象虽未明言，然冲气上逆多伴弦急之象。所主为冲脉病，症见气从少腹上冲咽喉，与冲脉循行部位相应。", []], "10251": ["主病", "脉沉主里、主气机郁滞，弦主肝木偏旺、气失调达。疟后余邪未清，肝胃气滞，故脘痞不饥、味觉酸苦。沉弦相合，说明病在里而属肝胃不和、气郁化火，故宜苦辛开泄以疏肝和胃、宣通气机，正合沉弦所主之里实气滞病机。", ["沉", "弦"]], "10252": ["预后", "吐血之后脉见空大，空为血去而脉道不充，大为气浮于外、阴不敛阳。失血本应脉静，今反空大，是气随血耗、虚阳有外脱之势，故原文谓“最不为宜”，恐其暴涌气脱。此脉示正气不守、预后险恶，当静养以固气摄血。", ["空", "大"]], "10253": ["病机", "芤脉中空，主失血伤阴；数脉主热，示阴亏而虚热内生。原文言血自阳明而来，然脉芤而数、色痿少彩，说明失血之后少阴之阴已伤，虚热扰于血脉。芤数并见，正是阴血亏虚、虚热不宁之病机，故当葆真静养以扶阴。", ["芤", "数"]], "10254": ["预后", "原文未识脉名，仅言“脉糢糊”。模糊者，脉体不清、至数难辨，是邪正交混、三焦气机壅滞之象。三焦为决渎之官，邪郁三焦则脉道不清，故断为“欲成三焦疟”。此以脉象模糊预示疟邪将成、病位涉三焦，属预后判断。", []], "10255": ["兼症", "左脉候肝，弦为肝气偏旺，数为肝阴不足而虚热内生。原文明言“肝阴不足”，戒其动怒，恐肝阳化火、灼伤血络而致失血。近症妨食恶心，是肝木犯胃、胃气上逆。弦数之脉既示肝阴亏虚之本，又应和肝胃、防其失血之兼症。", ["弦", "数"]], "10256": ["预后", "咳嗽失血而见脉大数，大为阴虚阳浮，数为热迫血行。原文谓“湿邪未净，延及少阴之损”，湿郁化热伤及少阴肾阴，阴损及肺，故断“将来有音哑之变”，脉大数为阴伤热炽之征，非外感实热。", ["大", "数"]], "10257": ["病机", "原文未出具体脉名，仅言“参色脉”而断“皆营阴不足，虚风萌动使然”。色脉合参见营阴亏虚，不能濡养筋脉，故虚风内动。法宜“甘缓益阴”，以甘药缓肝之急、益营阴之虚，脉象当见细弦之类，属病机判断。", []], "10258": ["病机", "嗽久不已，病不在肺而在少阴，左脉弦数。左脉候肝肾，弦为肝木失柔，数为阴亏生热，肾阴不足则肝木偏亢，虚火上灼于肺而嗽久不愈。原文“法宜摄阴”，正针对少阴阴亏、肝阳偏亢之机，弦数即阴亏气热之象。", ["弦", "数"]], "10259": ["病机", "肢麻肉𥆧偏左，脉涩。涩为血少精亏、脉道不充之象。原文断“虚风萌动，良由肾精肝血不足使然”，精血亏虚不能荣养筋脉肌肉，故麻木𥆧动；偏左属肝血不足，涩脉正应精血虚少、血行不畅之机。", ["涩"]], "10260": ["病机", "下利半月而脉涩，涩主血少气滞、湿阻脉道。原文断“阴暑伤中”，阴暑为暑湿伤于脾胃，湿邪内阻，中阳受困，气血运行不畅故脉涩；下利日久亦伤阴血，脉道不充。涩脉在此示湿伤中焦、气血不畅之病机。", ["涩"]], "10261": ["病机", "左脉弦数，原文直断“阴亏气热，咳嗽口燥”。左脉候肝肾，弦为肝阳偏亢，数为热象；阴亏不能制阳，气分有热，虚火上炎灼肺则咳嗽，耗津则口燥。弦数并见，正是阴亏于下、气热于上之病机反映。", ["弦", "数"]], "10262": ["病机", "脉沉细而胀渐甚、溺赤。沉主里、主水，细主阴血不足。脉沉细示病在里而正虚，水湿内停不化，故胀渐甚；湿郁化热下注则溺赤。此属正虚水停、湿郁化热之机，沉细为里虚水湿内阻之脉。", ["沉", "细"]], "10263": ["病机", "疟虽止而色黄、脉呆钝，原文断“湿未净耳”。脉呆钝指脉来不流利、少神采，为湿浊内阻、气血运行不畅之象；色黄亦湿郁之征。疟后湿邪留恋未清，故脉不灵动，属湿浊未净之病机，非虚损之候。", []], "10264": ["病机", "络伤嗽血而脉弦，弦为肝脉，主气机郁滞、木火刑金。肝络失和则血不循经而嗽血，弦脉示肝气偏亢、络脉拘急，故诫“切勿动怒”，怒则气逆火升，更伤血络，与嗽血之症相应。", ["弦"]], "10265": ["主病", "脉弦呕恶，弦主肝木偏旺、气机横逆。肝气犯胃，胃失和降则呕恶，故治以“肝胃同治”。此脉此症示病机在肝胃不和、木乘土位，弦脉正是肝气郁逆之征，与呕恶相应。", ["弦"]], "10266": ["病机", "脉数阴亏，数主热，阴液亏虚则虚热内生，脉行加速。阴虚不能润肺，气燥失养故作咳。数脉在此非实热，乃阴亏火动之象，与气燥作咳之症相应，示病本在阴亏。", ["数"]], "10267": ["病机", "脉涩胃痛，涩主血少气滞、脉道不利。原文明言“营阴枯槁，络气不疏”，营阴亏则脉失濡养而涩，络气滞则胃痛由生。涩脉正示营阴枯、络气阻之病机，与胃痛之症相应。", ["涩"]], "10268": ["主病", "脉小咳嗽背冷，小脉主气血不足、阳气偏衰。阳气虚则背冷，肺气弱则咳嗽。脉小示正虚，与咳嗽背冷之症相应，说明此咳非实邪，乃阳气不足、肺失温养所致。", ["小"]], "10269": ["病机", "劳伤为嗽而脉来弦大，弦主肝木、大主虚劳气张。劳伤正气亏虚，木气失制而脉弦大，食减则剧示脾胃受克、化源不足。弦大之脉与食减嗽剧相应，示劳伤而肝脾失调之病机。", ["弦", "大"]], "10270": ["病机", "头风数载，左脉沉细，沉主里、细主阴血不足。原文谓邪已入脑俞，且断“隶在少阴”，沉细示病在里属少阴，非三阳表证。脉沉细与久病头风相应，说明邪深入阴分，故戒“弗至厥阴为妙”。", ["沉", "细"]], "10271": ["病机", "脉涩而背痛咳嗽，涩主气滞血少、脉络不畅。背痛因络气不通，咳嗽因肺气不利，涩脉示营血滞涩、络脉失疏。此脉与背痛咳嗽相应，说明病机在气血涩滞、络道不利。", ["涩"]], "10272": ["治法", "呕恶而脉弦，弦为肝木之象，木旺则乘胃土，胃气上逆故呕恶。此处脉弦提示肝胃不和、胃失和降，非单纯胃虚。原文\"先宜降胃\"，正针对胃气上逆之机，降胃则肝木不得犯土，呕恶可平，是凭脉定治法。", ["弦"]], "10273": ["预后", "肿满病而形羸脉微，微为阳气衰微之象，形羸示阴血亦损，故曰\"二气交衰\"，阴阳气血俱败。肿满本水湿内停，脉当沉实，今反见微，是正气不能胜邪，故断言\"治之岂易\"，所赖年富强，尚存生机，属预后判断。", ["微"]], "10274": ["病机", "单言脉涩，涩为血行不畅、脉道不利之象，主气滞血瘀或血少精伤。原文仅存\"脉涩\"二字，未系症候，然涩脉总由气血运行受阻、脉道失于濡润所致，提示血瘀或血虚之病机，为凭脉辨证之提纲。", ["涩"]], "10275": ["病机", "经来腹痛而脉涩，涩主血行涩滞，经期气血不畅、瘀阻胞宫，不通则痛。脉涩与腹痛相应，说明痛由气血瘀滞而非虚寒。原文\"宜两和气血\"，正合涩脉气血不和之机，调和气血则瘀滞得通，腹痛自止。", ["涩"]], "10276": ["主病", "脉浮主表，浮为邪在肌表、正气趋外抗邪之象。身热头痛乃外感表证常见症，脉浮与身热头痛相合，说明邪袭卫表、正邪相争于外。浮脉举之有余，按之不足，正是表证之凭，故以脉浮统身热头痛之表病。", ["浮"]], "10277": ["病机", "腹胀腿麻、二便不利而脉沉细，沉主里、细主虚，肾病阳气不足，阴寒内盛，气化失司故二便不利，阳不温煦故腿麻腹胀。原文\"法宜温纳，理阴中之阳\"，正针对沉细所示肾阳衰微、阴中无阳之机，温纳则气化复常。", ["沉", "细"]], "10278": ["病机", "燥侵作咳而左脉弦数，左脉候肝，弦为肝旺，数为热象，燥邪伤肺，肝木偏旺化火，木火刑金则咳。弦数并见，提示肝经郁热、络脉受灼，故\"恐络动失血\"，是防燥热伤络、血随咳出之病机转归。", ["弦", "数"]], "10279": ["病机", "脉数而少阴空虚，数为阳热之象，然少阴空虚则阴精不足，虚热内生，数脉非实热乃阴虚阳浮所致。原文\"葆真为要\"，正因少阴根本空虚，当固护真阴，勿使虚火耗精。数脉在此提示阴虚内热、根本不固之病机。", ["数"]], "10280": ["预后", "痛止而脉仍弦，说明痛虽缓解，但弦脉未去，提示病根未除。弦为肝脉，主气机郁滞、筋脉拘急，痛止脉弦表明气血郁滞尚存，不可因痛止而放松调治，当继续疏肝理气，防其复发。", ["弦"]], "10281": ["主病", "单言脉弦，弦为肝之常脉，又主痛、主饮、主气郁。此段以脉弦为纲，提示病位在肝，病机为气机郁滞或筋脉拘急，临床当结合兼症辨其属痛、属饮或属气郁，不可仅凭一弦字定病。", ["弦"]], "10282": ["兼症", "左脉弦，左候肝，弦为肝郁化火之象。瘅热知饥，热在中焦，消谷善饥；色黄为脾湿外露。肝郁化热，木火刑土，故见瘅热知饥而色黄，脉弦正是肝郁化热、木土不和之征。", ["弦"]], "10283": ["病机", "咳嗽身热而脉弦数，弦主肝郁，数主热盛。阴虚之体，挟外邪为患，虚热与邪热相合，故脉弦数。原文明言阴虚挟邪、勿轻视之，提示本虚标实，弦数为阴虚阳动、邪热内扰之象，不可单纯治咳。", ["弦", "数"]], "10284": ["病机", "右脉弦而有力，右候脾胃。肾为胃关，肾病则食少形倦，本属虚候，而右脉反弦而有力，是虚中挟实、土虚木乘之象。原文称虚之实，先宜疏胃益脾，说明弦而有力非纯实，乃脾虚肝乘、气机壅滞所致。", ["弦"]], "10285": ["病机", "左脉弦数，左候肝。内热咳嗽痰血，脏阴暗耗，阳动不潜，故脉弦数。弦为肝阳偏亢，数为内热炽盛，阴亏不能涵阳，阳动化火刑金，灼伤肺络而痰血，弦数正是阴虚阳动、木火刑金之征。", ["弦", "数"]], "10286": ["主病", "脉弦数，先寒后热，头胀脘闷，属伏暑成疟。弦主少阳枢机不利，数主暑热内盛。伏暑之邪郁于少阳，正邪交争，故寒热往来；邪阻三焦，气机不畅，故头胀脘闷，当分三焦辨治。", ["弦", "数"]], "10287": ["治法", "伏邪下利而脉弦，弦主气机郁滞、木邪犯土。伏邪内陷，下迫肠道而利，脉弦说明邪郁未解、肝木乘脾。原文法宜和之，即调和肝脾、疏解伏邪，使气机通畅，则利自止，弦脉可解。", ["弦"]], "10288": ["主病", "左脉弦，弦为肝脉，主肝气偏旺、气机郁滞。左脉候肝，弦象独见于左，说明肝失疏泄、气机不畅，常见胁胀、情志不舒等症。原文仅言“左脉弦”，未及兼症，当以肝郁气滞为基本病机，弦而有力多实，弦而无力多虚。", ["弦"]], "10289": ["预后", "脉弦数，弦主肝旺，数主热，肝火内郁之象。原文谓“咳嗽虽缓，尚宜谨慎调摄”，说明咳势虽减而脉仍弦数，肝火未清、余热未净，恐其复燃，故当慎调摄，不可遽补，亦不可劳复。", ["弦", "数"]], "10290": ["病机", "脉弦涩，弦为肝郁，涩主湿滞血行不畅。原文言“湿邪阻于中焦，木火不能疏泄，湿火内蒸，升降之机失职，为之胀满”，正合弦涩之象：湿阻则涩，木郁则弦，升降失职故胀满，法宜疏之，疏肝化湿以复升降。", ["弦", "涩"]], "10291": ["主病", "脉沉弦，沉主里、主水气内停，弦主肝郁、气机不畅。原文“腹膨不饥”，乃水湿内停、肝脾不调，气滞水阻于中焦，故腹胀而不思食。沉弦并见，说明病在里而气机郁滞，水气与肝郁相合为患。", ["沉", "弦"]], "10292": ["兼症", "左脉弦数，弦主肝旺，数主火。原文“嗽逆气急盗汗”，乃肝火犯肺、木火刑金，肺失肃降则嗽逆气急；火盛迫津外泄则盗汗。左脉候肝，弦数独见于左，正说明肝火内炽为病之本。", ["弦", "数"]], "10293": ["主病", "脉弦数，弦为肝脉，数主热。原文“咳呛失血”，乃肝火犯肺、木火刑金，肺络受损则咳呛失血。弦数之脉反映肝火内盛，火性急迫故咳呛，灼伤血络故失血，病机重在肝火迫肺。", ["弦", "数"]], "10294": ["病机", "脉软，软为无力之象，主虚。原文“心悸不耐烦，营虚气怯甚矣”，营血虚则心失所养而悸，气虚则不耐烦劳。脉软正合气血营虚之候，非湿邪之濡软，乃虚软无力，故断为营虚气怯。", ["软"]], "10295": ["主病", "脉弦，弦主肝郁、气逆。原文“哮逆不得卧”，乃肝气上逆、痰气交阻于肺，肺失肃降，故哮逆而不得平卧。弦脉反映气机郁逆，与哮逆之症相应，病机重在肝肺气逆、痰阻气道。", ["弦"]], "10296": ["兼症", "子后咳逆嗽甚、汗多而脉细，子时阳气初生，咳逆汗多耗伤气阴，脉细为阴血不足、气阴两伤之象，正虚不能敛汗，故汗多而脉道不充，主气阴亏虚、肺失清肃之候。", ["细"]], "10297": ["病机", "脉细而形神疲倦，显是命门真火式微，火衰不能温煦，水湿不化，故为瘅胀肿满。脉细主阳气衰微、气血不足，与王宇泰“益火之源，以消阴翳”之论相合，正属命门火衰、阴翳内盛之候。", ["细"]], "10298": ["治法", "脉象平和而热退头晕，脉平示邪已退、正气渐复，热退则外邪已解，唯余头晕，乃肝胃未和、清阳不升所致，故宜调肝胃以善其后，属病后调理之候，非主病之脉。", []], "10299": ["主病", "身热头痛、身疼无汗而脉弦，弦为外邪束表、经气不利之象，寒邪客于太阳，营卫郁滞，故身疼无汗；脉弦而非浮紧，示邪正交争、气机郁滞，主外感风寒表实之候。", ["弦"]], "10300": ["主病", "三疟色黄而脉弦偏右，弦为疟邪郁于少阳、气机不和之象，偏右示病位偏于脾胃，疟久脾虚湿郁则色黄，脉弦主邪留少阳、脾胃受困，属三疟正虚邪恋之候。", ["弦"]], "10301": ["病机", "仅言脉右数，右脉候肺与脾胃，数为热象，右数示热郁于气分或肺胃有热，气分热盛则脉数，主里热之候，然原文过简，仅可断为右部有热、气分热郁之机。", ["数"]], "10302": ["病机", "脉弦数而少腹气冲、映背交痛，弦主肝郁、数主热，高年阴血槁枯，少阴肾气不摄，冲气上逆欲作奔豚，弦数为阴亏火动、气逆之象，法宜温养下焦以摄纳肾气。", ["弦", "数"]], "10303": ["病机", "脉弦而不饥少纳，弦主肝郁克脾、气机不畅，湿痰阴于中焦，脾运失司故不饥少纳，脉弦示痰湿阻遏、肝脾不和，主湿痰困阻中焦之候。", ["弦"]], "10304": ["病机", "脉数不宁，数主热，不宁示躁动不安，为热扰心神或阴虚阳浮之象。原文仅言脉数不宁，未及具体症候，然数而躁动多主里热或虚阳上扰，心神不宁，故脉来急数而失从容之态。", ["数"]], "10305": ["病机", "脉弦劲而长，弦为肝脉，劲为阳亢，长为气盛。原文谓肝阳化风，冲激阳明，致心悸嘈杂；又言少阴不充，无以涵木，是肾水亏虚不能养肝，肝阳化风上扰，故脉弦劲脉长，主肝阳化风、水不涵木之病机。", ["弦", "长"]], "10306": ["病机", "左脉弦，左关候肝，弦为肝之主脉。单言左脉弦，示肝气偏旺或肝郁不舒，气机失于条达。原文未及兼症，然左脉独弦，多主肝病，或为肝阳偏亢、或为肝气郁结，当结合他症辨之。", ["弦"]], "10307": ["主病", "脉浮弦，浮主表、主阳浮，弦主肝、主饮。原文以身热、头痛、渴饮与脉浮弦并见，是外邪袭表、少阳枢机不利，或风热上扰清窍。浮为邪在表，弦为邪郁少阳，故脉浮弦主外感发热头痛之证。", ["浮", "弦"]], "10308": ["病机", "时病伤阴，阳浮不潜，故神识时清时昏；脉来弦数，弦为阳亢，数为热盛。阴伤不能制阳，虚阳上浮扰及神明，故脉弦数而神识昏蒙。原文以益阴和阳为治，正合阴虚阳浮之病机。", ["弦", "数"]], "10309": ["病机", "脉不宁静，陡然失血，原文断为阳升扰络使然。脉不宁静示躁动失和，阳升则血随气逆、络脉受损而骤血。此段以脉之躁动说明阳气升腾、扰动血络之病机，非单纯失血，乃阳亢迫血妄行。", []], "10310": ["病机", "脉弦，饮逆作咳。弦主饮、主肝，饮邪内停，气机不利，上逆犯肺则咳。原文以脉弦点明饮逆之病机，弦为水饮内动之象，饮邪上逆故咳，脉症相应，主痰饮上逆之咳。", ["弦"]], "10311": ["预后", "色脉皆不妥，言望色与切脉均失和顺，示正气已伤、病势未平；然胃强能纳，庶几望其痊可，是胃气尚存、纳食如常，后天之本未败，故预后尚有转机。此段以色脉与胃气并察，判断病之吉凶。", []], "10312": ["病机", "脉涩为血行不畅、脉道不充之象，兼见心悸，说明营血亏虚、心失所养，或瘀阻心脉而悸。原文又言「内热」，热灼营阴则血少而涩，故涩脉在此主阴血不足、内有郁热，心悸为其相应症候，病机属虚中夹热。", ["涩"]], "10313": ["病机", "伏暑瘅疟本属暑湿内伏、邪正交争，汗多则津液外泄，脉道不充，故脉细。细脉主气阴两伤，此段以「汗多脉细」点明暑热耗气伤津之病机，脉细正是正虚液夺之征，与伏暑瘅疟汗多之症相应。", ["细"]], "10314": ["病机", "胃痛便艰而脉涩，涩主血少气滞、脉络不利。原文断为「营虚络痹」，即营血亏虚不能濡润，络脉痹阻不通，故胃痛、便艰并见。涩脉在此反映营虚络痹之病机，久延恐成关格，属虚实夹杂之候。", ["涩"]], "10315": ["病机", "脉涩下利、少腹啾唧，涩为阳气不运、积滞内著之象。原文谓「阳微积著使然」，阳微则血行迟涩，积著则脉道不利，故脉涩而少腹作响。此涩脉主阳虚积滞、寒凝气阻，法当温通，与下利、少腹啾唧相应。", ["涩"]], "10316": ["预后", "阴损及阳、寒热日加，而脉数形瘦，数脉本主热，然阴亏阳损之际脉反数，是虚阳外浮、阴不敛阳之象。形瘦示阴精耗竭，脉数与寒热并见，说明阴阳两伤而虚热内扰，原文叹「其何以理」，寓预后不良之意。", ["数"]], "10317": ["预后", "利止本为邪退之兆，然脉小、食少并见，小脉主气血不足、正气未复。下利虽止而脾胃虚弱、气血亏耗，故脉形细小、纳食减少。此段以脉小食少说明利后正虚未复，属病后调养之候，脉小反映气血两虚之病机。", ["小"]], "10318": ["病机", "失血每入秋而发，秋令肃降，阴亏之人气不收肃，扰及血络故血外溢。脉细涩为阴血亏少、脉道不利之征，细主阴亏，涩主血滞络伤。原文明言「属阴亏，气不收肃，扰络致此」，细涩脉正合阴亏络扰之病机。", ["细", "涩"]], "10319": ["预后", "客邪发热作咳，脉来细小无力，细主阴血不足，小主正气虚弱，无力更示正虚。外邪虽在而脉不鼓，说明正气不足以抗邪，故原文判为「淹缠之候」，即病程缠绵难愈。此脉反映正虚邪恋之病机，预后迁延。", ["细", "小"]], "10320": ["病机", "脉弦为肝木失柔，涩为阴血亏少、脉道不充。原文谓「体质阴亏，阳易外浮」，阴不敛阳则不时寒热；阴虚木火刑金，故咳嗽失血。弦涩并见，正示阴亏阳浮、肝肺同病之机，故治宜益阴和阳，使阴复则阳藏、血宁咳止。", ["弦", "涩"]], "10321": ["病机", "沉主里、弦主郁，沉弦相合，为阴邪郁于里而肝木不疏。原文言「阴邪内郁，厥阴阳明不能疏泄」，厥阴肝失条达、阳明胃失和降，故下利与泛泛虚寒下利不同，乃邪郁气滞所致。脉沉弦正是里郁不疏之征，主疏泄失常、阴邪内结之病机。", ["沉", "弦"]], "10322": ["其他", "原文仅存「脉尚弦」三字，无症可参。弦为肝脉，主气机郁滞、木旺乘土，亦见于痰饮、痛证。着一「尚」字，示前此脉象已有变化而弦未全退，属病势未净、肝木未柔之象。因上下文缺失，仅就脉弦本身言其肝郁气机偏胜之意，不作具体主病推断。", ["弦"]], "10323": ["预后", "原文「神识虽清，脉象殊数」，神清似属佳象，而脉数异常则内热鸱张、阴液受灼。脉数为热，殊数则热势不宁，虽神识暂清，恐邪热内陷、正不胜邪，故列于预后之辨：脉与症不相符，当防热盛伤阴、神机骤变，不可仅凭神识清而谓病轻。", ["数"]], "10324": ["病机", "湿从下受，肿起于足，延及腹满食胀、便溏不爽，显系湿浊内壅。脉来弦涩，弦主气郁、涩主血滞，示湿阻三阴、募原腑络痹而不疏，气血流行不畅。原文明言「其源起于三阴，而募原腑络痹不疏」，故弦涩为湿痹络脉、气血壅滞之脉，治从先治标之旨。", ["弦", "涩"]], "10325": ["病机", "原文未出具体脉名，仅言「脉不流利」，即脉来艰涩不畅之象。脉不流利则气血运行受阻，故直断「气血痹矣」。痹者闭也，营卫气血不能宣通，可致痛、肿、麻木诸症。此段以脉之流畅与否判气血痹阻，属由脉测病机之论，故归病机。", []], "10326": ["病机", "下利而脉小而迟，小为阳气不足、脉道不充，迟为脏寒阳微。原文谓「食物不节，脾阳戕矣」，饮食不节损伤脾阳，运化失职则下利，阳虚不能鼓脉故小而迟。此脉正示脾阳受戕、中焦虚寒之病机，非实热下利之比，主温运脾阳为治。", ["小", "迟"]], "10327": ["病机", "脉迟主寒、主阳气不振。便血而心中嘈杂，原文断为「操劳使然，伤在心脾」：劳伤心脾，心气虚则运血无力、脾虚则统血失职，故便血；中焦虚寒、心神不宁则嘈杂。脉迟正应心脾阳弱、血失统摄之机，非热迫血行之便血，故以迟脉为辨。", ["迟"]], "10328": ["病机", "脉长而尺部垂，长主气盛，尺垂则下焦藏真不固，阳不潜藏而浮越，血随气溢，神倦乏力。此属虚损，非瘀血实邪。脉长本为有余，然尺垂无力，正是下元亏虚、阳浮于上之象，故断为虚损而非瘀滞。", ["长"]], "10329": ["预后", "脏阴暗耗，气浮于外则肤热，脉数而腹膨，是阴亏渐及阳位，虚阳外越之候。数脉本主热，此则阴亏不能涵阳，气浮而数，非实热可比。原文谓「最不易治」，以阴损及阳、虚损已成，故属难治之预后。", ["数"]], "10330": ["病机", "客邪咳嗽，脉右弦数，右脉候肺，弦主饮邪、数主热，嗽盛汗泄则肺气耗散，上病延及下焦，金不生水，故音渐失。弦数见于右寸，是邪郁肺络、热蒸津泄之象，由肺及肾，故曰上病延及下焦。", ["弦", "数"]], "10331": ["其他", "原文仅存「脉细如丝」四字，无上下文可据。细如丝主气血两虚、脉道不充，或阴精亏耗、阳气衰微。然此段文义残缺，仅能就脉象本身言其主虚，不能确指所主何病，故归入其他，存脉待考。", ["细"]], "10332": ["病机", "脉弦胃减，脘闷食下䐜胀、便溏不爽，是脾阳呆钝，不能点运水谷湿滞。弦脉主木克土、气机郁滞，脾主升胃主降，升降失宜则湿滞内停。原文戒「莫谓体弱即投腻滞补药」，正恐补涩碍运，当先宣通湿滞、复其升降。", ["弦"]], "10333": ["病机", "色亮、脉弦涩，弦主饮、涩主滞，饮邪阻于肺络，肺气不利故咳嗽不已。原文谓「如以虚论，饮愈阻矣」，明言此非虚证，若误作虚补，则饮邪愈壅。弦涩相合，正是饮停络阻、气机不畅之脉，故主饮阻肺络。", ["弦", "涩"]], "10334": ["病机", "脉数无序，数主热，无序则热邪内扰、脉行失其常度，故曰里热甚矣。数而失序，非单纯虚数，乃邪热炽盛、气血奔迫之象。原文戒「勿忽视之」，正提示里热深重，当审其传变，不可轻忽。", ["数"]], "10335": ["预后", "形瘁脉数，形瘦而脉数，是阴枯气燥，阴液枯涸不能濡养，气失所附而燥扰，络松失血。以形脉论之，形瘁脉数本为脉证相失，阴枯难复，故曰病不易治，属虚损重候之预后判断。", ["数"]], "10336": ["病机", "原文未识别出脉名，仅言「脉黄发热。咳呛脘闷。其开上焦」，以发热、咳呛、脘闷定病位在上焦。咳呛为肺气不宣，脘闷为气机不展，故治法主开上焦、宣肺透邪。脉象缺如，不能据脉论虚实施治，只能从症测机，属病机与治法并见之条。", []], "10337": ["病机", "脉虚软而晨起恶心，虚为阳气不足，软为胃气无力，故断为「胃阳薄也」。晨起阳气初升，胃阳薄弱则浊阴不降，发为恶心。脉虚软正合胃阳虚衰、运化无力之机，非实邪阻滞，故以温养胃阳为要。", ["虚", "软"]], "10338": ["病机", "左脉弦数，左候肝与血分，弦主肝郁气逆，数主阳动有热。弦数并见，示肝阳偏亢、郁热内扰之机，与阴弱阳动、络逆失潜之证相应。原文仅存脉象，未列症候，然弦数之脉已提示肝经郁热、阳不潜藏之病机。", ["弦", "数"]], "10339": ["预后", "寒热经阻而形瘦脉涩，涩为血少脉道不充，形瘦为阴血耗损之征，故断「此属耗血」。经阻由血枯而非瘀滞，寒热乃营卫失和。脉涩与形瘦相合，示精血难复，故言「最不易治」，属预后不良之判。", ["涩"]], "10340": ["病机", "脉弦数，弦主肝阳亢逆，数主阳动化热。原文言「禀赋阴弱。阳动不潜。络逆吐血」，阴弱不能涵阳，阳动上扰，络脉逆乱而血溢，故脉见弦数。此脉正合阴虚阳亢、络逆动血之机，治宜摄阴和阳，使阳得潜藏。", ["弦", "数"]], "10341": ["预后", "久嗽痰浓属胃中伏湿，然形神憔悴而脉微，微为阳气衰微、气血俱虚之象。症见湿痰而脉反微，是正虚不能化邪，形神与脉俱败，故言「最不易治」。此条以脉微断预后，示久病正衰、攻补两难之局。", ["微"]], "10342": ["病机", "脉涩主营血不足、脉道不利。经事先期而脘痛引腰髀、不时寒热，原文断为「二维为病」，二维指冲任带之维络，由营血不足、络脉失养而病。涩脉正合血虚络滞之机，故以养营血、调维络为治。", ["涩"]], "10343": ["预后", "脉细为阳气阴血俱不足，脘痛暮盛、吐出未化食物，是肾阳受戕、失宣降之司，痛则不通。细脉示正虚而运化无力，日久阳衰浊聚，恐成关格大患，故戒「蚤为图之」。此条由脉细推及关格之预后。", ["细"]], "10344": ["病机", "尿血而脉微，年已花甲，肾阴下夺，阳失其化，血从小肠而下。脉微为阳气衰微、鼓动无力之象，肾藏失封固之本，阴不内守，阳不化气，故血下夺而脉微。此脉主肾阳衰微、封藏失职之尿血，与年高肾亏、阴损及阳相应。", ["微"]], "10345": ["病机", "督虚背凛，脉来微细。微细为阴中之阳伤，阳气不能温煦督脉，故背凛。脉微细主阳气虚损、阴寒内盛，督脉失养。此脉说明阴中之阳伤，法宜柔温养之，与背恶寒、阳虚证相应。", ["微", "细"]], "10346": ["预后", "吐血脉歇，二气惫矣。脉歇为脉来歇止，气血两败，阴阳二气疲惫，不能接续。吐血脉歇，示正气衰惫，预后谨慎调理。此段以脉歇判断二气惫，属预后不良之象，与吐血后气血耗伤、脉道不续相应。", []], "10347": ["其他", "原文仅载左脉弦，未附症候。左脉候肝，弦为肝脉，主肝气郁滞或肝阳偏亢。此段以左脉弦提示肝病机，可能涉及肝郁、气机不畅，但原文简略，仅从脉象要素言，弦主肝、主痛、主饮。", ["弦"]], "10348": ["妇人", "娠五月，足太阴司胎，太阴与阳明为表里，阳明隶乎冲脉。冲脉空虚，是以易于堕胎。脉空虚示冲任气血不足，胎失所养。此脉主冲脉空虚、胎元不固，法宜固之升之，与妊娠堕胎相应。", ["虚", "空"]], "10349": ["病机", "胃痛数载，脉虚而涩，经事先期。虚为营气虚，涩为气痹血行不畅。营虚气痹，故胃痛日久，经事先期。此脉说明营虚气痹之病机，不宜过于辛燥，与胃痛、经期异常相应。", ["虚", "涩"]], "10350": ["病机", "咳嗽盗汗鼻衄，脉数，阴亏气浮使然。数脉主热，阴亏则虚热内生，气浮不敛，故盗汗、鼻衄。脉数说明阴亏气浮之病机，葆真为要，否则延怯。此脉与阴虚内热、气不归元之症相应。", ["数"]], "10351": ["病机", "脉弦，嗽逆不得卧，属下虚不纳，乃虚症也。弦脉主肝，亦主饮、主痛。下虚不纳，气逆上冲，故嗽逆不得卧。脉弦说明下元虚衰、气不摄纳之病机，属虚症，与肾不纳气、冲气上逆相应。", ["弦"]], "10352": ["病机", "脉长而弦，长主气火有余，弦为肝木亢盛，相火内炽，扰动精室，故不时梦泄；火盛灼阴，脏阴失守。入春木气升发，大气发泄，火升血动，最虑失血。此脉示相火偏旺、阴不制阳之机，与梦泄、失血相应。", ["长", "弦"]], "10353": ["病机", "左脉候肾与肝，弦数并见，弦为肝木偏亢，数为火热内动。劳伤肾者，肾阴亏耗，水不涵木，相火不藏，故左脉弦数。此脉主肾劳而肝火内扰，与虚劳、梦遗、烦热等症相应，属阴亏火旺之机。", ["弦", "数"]], "10354": ["病机", "左脉涩，涩主血少精亏，按之跃则阴虚无以恋阳，虚阳有浮动之势。原文断为肾阴空虚甚矣，故急急葆真，勿见咳即投清润肺药，恐更伤下焦。此脉示肾阴大亏、虚阳不潜，与咳嗽等症相应，治当固本保真。", ["涩"]], "10355": ["预后", "湿郁蒸热，恶心舌白，脉来弦数，弦为湿郁气滞，数为热蒸。湿遏热伏，脾胃不和，故恶心；转疟为顺，言邪从少阳外达，较之内陷为佳。此脉示湿郁化热、枢机不利，与恶心、舌白相应，其转归以疟为顺。", ["弦", "数"]], "10356": ["病机", "左脉弦，弦为肝木失柔，阴亏则木旺，阳浮不潜。阴虚于下，阳越于上，肺失清肃则咳嗽，卫外不固则盗汗。此脉主阴亏阳浮、肝木偏亢，与咳嗽盗汗相应，治当滋阴潜阳，不可徒清肺金。", ["弦"]], "10357": ["病机", "脉弦主肝木偏旺、气机郁滞。胃痛年久，病在于络，久痛入络，气血瘀滞，肝木犯胃，络脉不和，故脉弦。此脉示肝胃不和、久病入络之机，与胃脘久痛相应，治宜通络和营，非单纯理气可效。", ["弦"]], "10358": ["病机", "脉涩主血行不畅、气血窒痹。胁肘痹痛，乃营络不宣使然，气血痹阻于络脉，不通则痛。日久瘀滞化热，有失血痈疡之患。此脉示气血窒痹、营络不宣，与胁肘痹痛相应，治当宣通营络、行气活血。", ["涩"]], "10359": ["病机", "脉涩主精血亏少、脉络不利。腿痛艰于步履，溺后如膏，小溲易癃，皆肾虚精亏、下元不固之象。肾主骨，精亏则骨弱，延久恐成痿躄。此脉示肾虚精亏、脉络失养，与腿痛、膏淋、癃闭相应，治当补肾固精。", ["涩"]], "10360": ["病机", "脉数为阳热之象，然此处不独言实热，原文点明“脏阴内虚，气亦少附”，是阴亏不能涵阳、虚阳浮越而数。阴虚无以养气，气失所附，故脉数而虚。最虑食减喘急，乃胃气将败、肾不纳气之兆，病机为阴亏气浮、脾胃衰惫，预后堪忧。", ["数"]], "10361": ["主病", "湿郁成疟，脉见弦小。弦主疟邪伏于少阳，气机郁滞；小为湿邪困阻、脉道不畅之征。湿郁化疟，邪正交争，故脉弦；湿性黏滞，气血运行不利，故脉小。治宜辛温和之，以辛散湿、以温和中，使湿化疟解，弦小之脉自平。", ["弦", "小"]], "10362": ["病机", "脉涩为血少气滞、络脉不畅之象。原文言“阴弱，气郁络痹”，阴血亏弱则脉道不充，气机郁滞则血行涩滞，故胸臆不爽、失血。涩脉既主阴弱，又主络痹，治以养阴佐辛润，使阴复络通，与胃无碍，正合涩脉虚实夹杂之机。", ["涩"]], "10363": ["病机", "脉歇即歇止之脉，属结代之类，主气血虚衰或邪阻脉道。原文言“饮邪内阻，咳嗽气逆”，饮邪停聚，阻遏胸阳，气机升降不利，脉气不相接续故歇。饮阻于内，肺失肃降则咳逆，脉歇正是邪阻正虚、脉道不利之反映，病机在饮邪内阻、气机不畅。", []], "10364": ["病机", "脉弦涩并见，弦主气结，涩主血少。原文谓“阴液渐次枯槁，清阳势欲上结”，阴枯则脉道失润而涩，气结则脉气劲急而弦。脘膈不利、咽喉如梗，乃噎格之象，正是阴亏气结、清阳上结所致。弦涩合参，示阴液枯槁而气机郁结，故戒动怒以防火升。", ["弦", "涩"]], "10365": ["主病", "复疟舌黄脉弦，弦为少阳主脉，疟邪伏于少阳，枢机不利故脉弦；舌黄为邪郁化热之征。复疟乃疟邪反复，肝胃不和，气机郁滞。治宜和肝胃，使少阳枢机得转、肝胃气机和畅，则弦脉可缓，疟邪可解。此段以脉弦定病位在肝胆，主疟疾反复之病。", ["弦"]], "10366": ["预后", "脉细如丝，为气血衰微、脉道不充之极。疟转下痢，暑邪入里，正惫不能泄越，故脉细如丝而神倦不食。细如丝示正气已惫，无力抗邪，邪陷于里而正不能托，症险恐脱，是预后不良之兆。脉细如丝与神倦不食并见，正虚邪陷，有虚脱之虞。", ["细"]], "10367": ["兼症", "脉弦数，弦主肝胆气郁，数主热。利后发热、咳嗽头胀，乃下利伤阴，余邪化热，肝阳上扰，肺气不利。弦为肝旺，数为热盛，热郁于内则发热，肝阳上扰则头胀，肺失清肃则咳嗽。脉弦数示肝经郁热、邪热未清，症见发热咳胀，为利后余邪兼症之象。", ["弦", "数"]], "10368": ["病机", "脉数无序，数主热，无序则非实热之整，乃少阴阴液不足、虚阳躁动之象。原文紧接“少阴颇虚”，明言数脉由阴亏不敛、心肾失交而致，非外感实火。故所主为少阴虚损、虚热内扰，可见心烦、口干、夜寐不安等症，治当养阴敛阳，不可苦寒直折。", ["数"]], "10369": ["病机", "舌白而脉弦，弦为肝木之象，主气机郁滞、饮邪内停。舌白提示寒湿或痰饮未化热，脉弦则示肝气不疏、木来克土。此段以脉弦合舌白，说明病机在肝郁脾困、寒饮内阻，主中焦气滞、水湿不运，可见脘闷、纳呆、泛恶等症，治宜疏肝运脾、温化寒饮。", ["弦"]], "10370": ["病机", "左脉独弦，左关候肝，弦为肝脉，独见于左，说明病位在肝胆。原文“耳鸣偏左”与左脉相应，乃少阳经脉循耳，木火循经上扰清窍所致，故断“木火无疑”。此脉主肝火偏亢、少阳郁热，症见偏左耳鸣、头胀、口苦，治当清泄肝胆木火。", ["弦"]], "10371": ["病机", "脉数而舌红苔黑、咳嗽渴饮，数脉主热，然原文点明“阴液内耗，气燥化热”，说明此数非实火，乃阴亏液耗、燥气化热之虚数。阴液不足则舌红，燥热内灼则苔黑、渴饮，肺失濡润则咳嗽。故脉数主阴亏燥热、肺津受灼，治宜滋阴润燥，不可妄投苦寒。", ["数"]], "10372": ["病机", "脉弦涩而嗽逆，弦主气机紧张，涩主血少津亏、脉道不利。原文断为“阴亏气浮使然，非客邪可散”，说明弦涩非外邪束表，乃阴液亏虚、虚气上浮，肺失肃降而嗽逆。故主阴亏气浮、肺络不畅，治当先以胃药培中，使阴液得复、浮气自敛，不可发散。", ["弦", "涩"]], "10373": ["兼症", "左脉弦，左关属肝，弦为肝脉，主肝气偏旺、少阳不和。原文“疟来头胀”，疟邪伏于少阳，肝气随邪上逆，故疟发时头胀。此段以左脉弦说明疟疾发作与肝木气逆相关，脉弦为少阳枢机不利、肝阳上扰之征，头胀即其兼症，治当和解少阳、平肝降逆。", ["弦"]], "10374": ["预后", "原文仅言“脉尚弦”，承前文病程而言，“尚”字示弦脉未解，病机仍在。弦主肝郁气滞或饮邪未化，脉尚弦说明邪气未退、气机未畅，前证尚未向愈。此段以脉象判断病情转归，提示肝郁或饮停之势仍在，需继续调治，不可因他症缓解而松懈。", ["弦"]], "10375": ["病机", "原文未识脉名，仅言“参之色脉，正气殊虚”。湿邪内阻则腹痛下利，然色脉合参显示正气大虚，说明湿浊困阻而中气已伤，属虚实夹杂之候。正虚则无力化湿，湿盛又更伤正气，故告诫“勿忽视之”，主脾虚湿阻、正虚邪恋，治当扶正与化湿兼顾。", []], "10376": ["病机", "脉细涩，细为营阴亏少、脉道不充，涩为血行不畅、络脉瘀滞。便血二十余年，络血下渗，营阴暗耗，故脉细涩；阴不制阳，厥阳化风内煽，则头眩耳鸣、身若浮云、肉𥆧肢麻。此属脏病，脉象反映阴血亏虚、虚风内动之机，非实邪为患。", ["细", "涩"]], "10377": ["主病", "三疟脉弦，弦为少阳之脉，主疟邪伏于半表半里、枢机不利。疟久不愈，邪搏少阳，气机郁滞，脉道劲急故弦。此以脉弦点明三疟病位在少阳，主疟疾反复发作之病，与寒热往来、定时而作之症相应。", ["弦"]], "10378": ["病机", "脉数主热，亦主虚。努力劳伤失血，血去则阴伤，阴不制阳，阳气浮越，故脉数而气浮咳逆。此数脉非实热，乃阴损阳浮之象，渐延阴损劳怯。原文以脉数提示血去阴伤、气浮不敛的病机转归。", ["数"]], "10379": ["主病", "复疟脉弦数，弦主少阳疟邪，数主邪热内盛。疟邪复作，伏于少阳，枢机不利则脉弦；邪正交争，热势偏盛则脉数。弦数并见，说明复疟属少阳郁热、邪势未衰，主疟疾再发之病，与寒热阵作、热多寒少相应。", ["弦", "数"]], "10380": ["兼症", "左脉弦数，左候肝胆，弦为肝气郁滞，数为郁热内扰。肝郁化热，木火刑金则咳嗽；气机不舒则脘闷；少阳不和则寒热。此段以左脉弦数统摄咳嗽、脘闷、寒热诸症，说明病机在肝胆郁热、气机失调，脉象与兼症相合。", ["弦", "数"]], "10381": ["病机", "脉弦主肝、主痛、主气机郁滞。胸胁痹痛引背，乃肝气郁结、络脉不通；曾吐瘀食下拒纳，为瘀血内阻、胃气上逆。此属血格，脉弦反映肝郁气滞、瘀阻血络之病机，与胸胁痛引背、吐瘀拒纳之症相应。", ["弦"]], "10382": ["预后", "脉涩为血少气滞、脉道不利。失血之后阴血亏虚，血行不畅故脉涩；血虚不能养肺则咳嗽，不能濡养胃气则妨食，阴虚盗汗。脉涩与失血咳嗽并见，提示正气渐亏，渐延劳怯之途，故原文告诫勿忽视、须静养，属预后判断。", ["涩"]], "10383": ["治法", "暑风上受，首先犯肺，逆传心包，肝阳化风，神昏谵语，而脉虚。虚脉主正气不足，邪热内陷而正不胜邪，故神魂失摄。脉虚说明不可苦降消克以伤正，急宜辛凉开热疏痰、治上焦，使神魂复摄。此段以脉虚定治法，属治法范畴。", ["虚"]], "10384": ["病机", "脉虚为元气亏馁之象。原文述黏痰咳呕外出、神识颇清，示邪有外达、正有渐复之机，然筋惕脉虚，则显系元气实馁，筋脉失养而惕动。此脉主正虚未复，虽邪退而本元已伤，故须扶过秋分大节，防其变幻，属病机判断。", ["虚"]], "10385": ["病机", "阳脉涩为气滞血少，阴脉弦为寒饮内结、木克土。原文谓「法当腹中急痛」，正合弦脉主痛、涩脉主滞之机；今复沉郁暴寒，则寒邪更束，阳气不伸，故宜更进一筹。此段以脉释腹中急痛之病机，兼及寒邪外束。", ["涩", "弦"]], "10386": ["病机", "上脉浮大而空，为发散升提太过、阳气浮越于上而中空；两尺沉细欲绝，为寒凉屡进、下元虚衰欲竭。面红头痛苦近，乃虚阳上浮，非实热。此脉示上盛下虚、阴阳将脱之危候，故心尚明了而气微弱，病势沉重。", ["浮", "大", "空", "细"]], "10387": ["病机", "脉来洪数而滑，为盛夏时邪、实热内盛之象；惟右寸见沉，右寸主肺，沉则示热邪内郁、肺气不宣。壮热口渴而渴欲热饮、虽热嫌冷，乃热郁于内、阳不外达之假寒象，非热极似寒。此脉主实热内蕴、肺气郁滞之病机。", ["洪", "数", "滑", "沉"]], "10388": ["病机", "六脉弦数，全无和柔之意，按尚有根。弦为木旺、数为热盛，瘅疟单热不寒两月，壮热伤阴，阴不化汗，邪无出路；素好内而肝肾俱亏，故脉失和柔。按尚有根，示胃气未绝，尚可为。此脉主肝肾阴亏、邪热内炽、阴不化汗之病机。", ["弦", "数"]], "10389": ["病机", "肺脉独大而数，肺主通调水道，大数为热。患者素嗜烧酒，酒热伤肺，肺热叶焦，水道不利，故小溲不通、腹膨急胀。前医连进通利不通愈甚，乃病本在肺而不在膀胱。此脉主肺热壅盛、水道失调之病机，故用清肺之品而愈。", ["大", "数"]], "10390": ["病机", "左关尺数，左关属肝、左尺属肾，数为热。牙痛缠绵月余，乃肾水太亏、肾火上浮，故脉数见于左关尺。用六味补泻，加升柴透达浮热，阴能潜阳则火不复上。此脉主肾阴亏虚、虚火上浮之病机，非实火牙痛。", ["数"]], "10391": ["病机", "脉象数而甚虚，数为暑热，虚为气弱；后言脉散，散则气欲外脱。患者年少当事太早，先天气弱，暑又伤气，故发热倦怠少气、天柱倾欹。此脉主暑伤元气、气不敛摄之病机，非参不可，且必佳参，以固其散越之气。", ["数", "虚", "散"]], "10392": ["预后", "脉来洪数无伦，按之空象，为阴亏于内、阳浮于外之象。洪数无伦示热盛而失柔和，按之空则阴液已竭，虚阳外越。外似恶寒、内烦躁热、舌赤无苔、溲黄白浊，皆阴虚热淫之候。脉证相参，攻补两难，故断为不治，预后凶险。", ["洪", "数", "空"]], "10393": ["病机", "脉弦劲疾数，不辨至数，为邪热炽盛、阴液耗伤、肝风内动之象。弦劲主邪实，疾数主热极，按之尚未无根，示胃气未绝。症见燥热非常、人事昏沉、耳无闻、目无见、舌卷囊缩，皆热陷厥阴、风火相煽之危候，故死象已具。", ["弦", "劲", "疾", "数"]], "10394": ["病机", "脉来上部大、下部小，为肾虚气逆、上下不交之象。上部大示虚阳上浮，下部小示肾气不足。肾虚之人过散伤肺，母不荫子，子来就母，致肾气上冲而喘不能卧。脉症相合，故以都气全方纳气归肾而愈。", ["大"]], "10395": ["其他", "本段未识别脉名，述疟后精神大减、忽发狂疯、喊骂掷物持刀，属阴虚痰火、神志错乱之候。前疟少汗，治以和解透汗而解，知其好内嗜饮、阴虚居多。虽无脉象可凭，然症情狂乱，显系痰火扰心、神明失主，非外感实邪。", []], "10396": ["病机", "脉象或大或小、或疏或密、或结或促，乍大乍小、节律不齐，为邪祟干犯、气血逆乱之象。大示邪盛，小示正虚，结促示脉气断续。症见忽大疯、持刀自戕，神志失常，故知其邪祟无疑，且久病气血暗伤，先以参地两补。", ["大", "小", "结", "促"]], "10397": ["病机", "诸脉皆平，肺脉独大，按之见数，为肺移热于大肠之象。右寸属肺，肺与大肠相表里，独见数大，故知热泻。症见泄泻四月、天未明泻起，虽值冬寒，脉象实为热泻，非寒泻也。脉症相参，当以清热止泻为治。", ["大", "数"]], "10398": ["病机", "脉则十分弦数，为暑热内蕴、邪郁少阳之象。弦主邪郁，数主热盛。症发时邪，医误用辛温发散及桂枝、柴胡加桂，致邪不能达、热转加而成热疟，寒少热多。脉弦数正合暑热郁于少阳，治宜辛凉透达。", ["弦", "数"]], "10399": ["预后", "脉来数大而空，甚数而仅空大，为热盛阴竭、正气溃散之象。数大示邪热未退，空大示阴液已涸、脉无根柢。症见仅一丝游气、半日不知人事，脉证相参，正虚邪陷，故病已垂危，预后不良。", ["数", "大", "空"]], "10400": ["主病", "脉滑数而大，滑主痰，数主热，大主邪盛。患者痰涌气急、坐伏茶几、不能言语，显系痰热壅盛、蒙蔽清窍之候。脉滑数应痰热内盛，气机壅滞，故见痰涌气急、不得卧。此脉主痰热实证，与昏沉不语相应，非虚寒可比。", ["滑", "数"]], "10401": ["病机", "脉浮而弦甚，浮主表，弦主痛、主饮，亦主阴虚。患者头痛项强背板、一身尽痛、恶寒不发热，为太阳伤寒表实证；然脉弦甚，知素来阴虚，不能作汗。弦为阴脉，浮而弦甚，示表邪外束而阴血不足，故发散无汗。此脉主表实兼阴虚之病机，与头痛项强、无汗相应。", ["浮", "弦"]], "10402": ["病机", "脉沉细如无，沉主里、主虚，细主阴血不足。患者眩晕非常、头不能抬、面色浮红，显系虚阳上浮、下元虚寒之候。脉沉细如无，为阳气衰微、不能鼓动血脉之象，故用真武汤重用附子温镇北方而效。此脉主虚阳上浮、下元虚寒之病机，与眩晕、面浮红相应。", ["沉", "细"]], "10403": ["病机", "脉皆沉，按之至骨略见疾数。沉主里，疾数主热。患者周身畏寒，医投温剂热剂而寒愈甚，乃伏热在至深之地，热药相引而入，卫阳亦随之而入，故外反憎寒。脉沉为热伏于里，疾数为伏热内郁之征。此脉主热深厥深、同气相求之病机，与身寒、脉沉相应。", ["沉", "疾", "数"]], "10404": ["病机", "脉皆弦数而大，右关数疾之中尤见和柔。弦主痛、主肝，数主热，大主邪盛。患者目赤痛、头痛难忍、大渴饮浓茶，乃肝经郁热上攻，胃液干枯。右关和柔示胃气未败，故非白虎汤实热症。此脉主肝热上攻、胃液干枯之病机，与目赤头痛、渴饮相应。", ["弦", "数", "大"]], "10405": ["预后", "原文仅言「脉象大为不好」，未详述具体脉形。大为邪盛或虚阳外越之象，此处示病深正衰、预后不良。患者阴癣蔓延，本不足忧，然误用紫荆皮、白芨敷治，戒伐太过，脉象转大，示正气受损、邪毒内陷。此段主旨为预后判断，脉大为不好，与误治后病情恶化相应。", []], "10406": ["病机", "脉来沉象，沉主里、主气滞。患者疟后寒不能转热，气从少腹上冲，疼痛异常，胸次饱闷，饮食不进，乃气机郁滞、寒热错杂之候。前医屡用白虎汤，寒凉抑遏，致气机沉滞。脉沉示病在里，气郁不达。此脉主气滞里实、寒热错杂之病机，与少腹上冲痛、胸闷相应。", ["沉"]], "10407": ["病机", "脉象洪数之中更兼躁急，洪主热盛，数主热，躁急主阴亏阳亢。患者暑疟后昏厥、抽搐、善笑、身热如炭、烦躁，乃热中厥阴，肝经抽搐、心包善笑。洪数为阳邪热盛，躁急为素本阴亏、孤阳外越之象。此脉主热中厥阴、阴亏阳亢之病机，与抽搐、善笑、烦躁相应。", ["洪", "数", "躁", "急"]], "10408": ["病机", "脉皆沉象，两关左弦数、右滑数。沉主里，弦为肝郁，数为郁而化热，滑为湿热内蕴。左关弦数示肝气郁而肝阴亏，右关滑数示脾气郁而湿热不宣。脾主健运、肝主调达，木郁克土，湿热郁脾不化；梳头则两手举而脾气上升，湿热随升，故胸乳间发紫斑、心中难过，皆郁热上扰之征。", ["沉", "弦", "数", "滑"]], "10409": ["病机", "脉象三日以来大小疏数不能一致，即脉来大小不匀、疏数错杂，为气血逆乱、神志不宁之象。患者胆怯多疑，因见郁结误服桂附致烧烂下血而伤怀疑惧，遂间日不寐，昼则头晕头痛、腰腿疼、心跳肉𥆧、腹胀腹痛变幻无常。脉无定体，正合情志郁结、心神失主、气血失调之病机。", ["大", "小", "疏", "数"]], "10410": ["病机", "脉大小疏数不一，即脉来大小参差、疏数不匀，主气血紊乱、心神不宁。患者心虚胆怯，独宿空房生疑惧，梦入黑暗地狱、绳捆石压，醒后神情恍惚、饮食不甘，或寒或热、或笑不自知。此情志先伤，神不守舍，气血随之乖乱，故脉无常数，非外感实邪之比。", ["大", "小", "疏", "数"]], "10411": ["预后", "脉来不甚细数，而大小疏数不一。病者年近二十、肥白不瘦，吐红不多已止，惟食入必吐、久不纳谷、神情疲惫。脉不细数，似非阴虚火旺之常；然大小疏数错杂，正气已乱。其父与长兄皆死于瘵，今及次子，故断为传尸症，内有劳虫，历代相传，预后凶险，非寻常虚症可比。", ["细", "数", "大", "小"]], "10412": ["其他", "本段未载脉象，述鼻渊症浊涕鼻秽、鼻塞不通、头昏而痛，前医拘守古方两月无效。张兄情形恍惚来诊，予断为「症非难治，但治不得法」，服药三帖涕减塞通，再诊加减七帖痊愈。全段主旨在于辨证立法、知古方须合今病，非以脉断病，故脉象要素从缺。", []], "10413": ["病机", "脉之寸关弦紧。弦主风、主痛，紧主寒，寸关见之，为风寒客于肌肤，故日晡蒸蒸发热、盗汗达旦；久则津液渐亏，日渐黄瘦、食少肢倦，已从外感转内伤。前医误作童痨辞治，若用地骨皮、花粉、知母则抱薪救火。当从内伤治而散其表邪，弦紧正是表邪未解之据。", ["弦", "紧"]], "10414": ["其他", "本段仅存「六味合生脉黄耆饮方治验案」标题，无脉象描述，亦无症候、病机文字可据。既为方治验案之目，主旨归于治法一类，然原文过简，无从分析脉与病机之对应，故脉象要素从缺，谨就题名所提示之方药略识其属。", []], "10415": ["病机", "脉之右寸浮而不敛，左脉涩。右寸候肺，浮而不敛为阳气外浮、卫表不固，故自汗如雨、手足厥逆；左脉涩为阴血亏少、脉道不利。面不赤而虚火上炎，日四五发，正是阳虚阴亏、阴阳不相维系之象。法当大补，与六味合生脉黄耆饮，六剂而愈，脉症相合。", ["浮", "涩"]], "10416": ["病机", "右关微紧主中焦气机郁滞，左细而涩为营血亏少、脉道不利。原文谓“营分数亏，兼之少阳之气又下陷于肝肾”，郁者当达，故脉见紧涩。傍晚发热、手心热乃阴血不足、郁热内扰之象，与脉细涩相应。", ["紧", "细", "涩"]], "10417": ["病机", "左弦数主少阳热盛，右弦而豁然空为脾胃之气骤虚，正虚邪陷。原文见“目上视”“慢脾风证”，弦数示热未清，空脉示中气已败，故法当用参附救逆。此脉象反映痧毒未净而脾阳欲脱之危候。", ["弦", "数", "空"]], "10418": ["病机", "脉实而有力主邪热内结、正气未衰。原文牙关紧、目上视、舌缩、舌心黄厚，皆阳明热邪聚胃之征。脉实有力说明热结在里，可下之证，故用凉膈散加石膏、大黄取大下而愈。", ["实", "有", "力"]], "10419": ["病机", "脉沉细主里虚，阳气不足。原文久疟后耳聋、咽肿，乃少阳邪未尽、虚火上炎；腹泻、不思食为脾肾阳虚。沉细脉示虚火非实热，故用姜附温补，若误用薄荷、牛蒡等清散则愈甚。", ["沉", "细"]], "10420": ["病机", "右关稍弦紧主少阳兼太阳，兼伤于食。原文疟后复发、间日寒热、七日不更衣，脉弦紧示邪郁少阳、表气不畅，紧又主食滞。故法当和解，用桂枝汤加减取微汗，非虚证可补。", ["弦", "紧"]], "10421": ["病机", "左寸实主心包络火郁。原文笑时泪出、必大恸后快、口苦，皆心火内郁、神志失司之象。左寸候心，实脉示火性上炎、变动百出，故用清心泻火之品而愈。", ["实"]], "10422": ["病机", "右关沉细而无力主脾胃虚寒、中阳不振。原文赤痢腹痛、后纯下血水、畏寒、手足厥逆，脉沉细无力示虚寒内盛，非实热痢。故用炮姜、木香温中，若误用芩连则危。", ["沉", "细", "无", "力"]], "10423": ["病机", "右三部俱洪主阳明经气独盛、热邪上炎。原文齿衄、四肢无力、饮食日减，洪脉示阳明热盛迫血妄行，故用大剂六味加骨碎补、麦冬、川斛滋阴降火而止。", ["洪"]], "10424": ["预后", "原文未明言脉象，但述“正虚邪实，非下不生，下则恐脱”，且疳症日久，脾胃虚弱，肝木失养而槁。此示正气已衰，邪热内结，下之则恐胃气不复，故断“法庚日死”，强调正虚邪实、胃气难复之危候，预后不良。", []], "10425": ["病机", "脉左寸关沉弦而横，沉为水亏，弦为肝阳亢逆，横则气机横逆。结合“头痛颈脉动，肝阳上冒至巅为厥”，此脉象反映水亏营弱、龙雷之火并发，肝阳化风上冒，故见厥证、舌生芒刺，治宜滋水潜阳。", ["沉", "弦"]], "10426": ["病机", "右寸忽起忽伏，示气机升降逆乱；左寸涩而郁，涩为血少，郁为气结。血少不荣肝，肝火上炎冲膈；气结不宣，木克脾土，脾运失职。故见胸膈痞闷、心中时痛、不寐、食则䐜胀，病机在肝脾不和、气血郁滞。", ["涩", "郁"]], "10427": ["治法", "原文未及脉象，主述张子和治目疾用针刺出血及吐下二法，作者以下法愈婢目赤肿痛，印证“暴赤肿者”宜泻其实。此段重在治法，示目赤肿痛属热实者，可针可下，以泻火解毒、导热下行取效。", []], "10428": ["病机", "脉右尺弱，两关皆弦，络脉空虚。右尺弱为命门火衰，两关弦为肝风内动，络脉空虚则贼风易乘。阳邪乘阳，虚风入胃，故食如饥、耳中金鼓声、烦重苦晕，此将成风痱之兆，治当峻补命门。", ["弱", "弦", "空虚"]], "10429": ["病机", "原文无脉象，以易理喻人身藏象，强调肺主气如天、脾主灌溉如地，土不生金则肺气先绝，外见毛发憔悴、形容枯槁、咳嗽气促等症。此段阐发脾肺相生之病机，主张培补后天以滋化源，属论病机与治法。", []], "10430": ["病机", "血症而胃脉鼓指，右胁痛，此肝叶抵胃，木横克土，胃气受迫。鼓指为胃气尚存而肝邪亢盛之象，势必妨食。治宜乘胃气未散，滋肝阴、运脾精，使胶痰渐化，示病机在肝胃不和、木亢侮土。", ["鼓"]], "10431": ["病机", "原文无脉象，以坎卦阳陷阴中喻肾中水火，水腾为精液，火蒸则关门利；水聚上泛为痰饮，火衰则关门阻。注下为白浊梦遗，移膀胱为淋闭消渴，壅内为水肿胀满。强调无火者居大半，补火为急，法当两建水火以培本原。", []], "10432": ["病机", "左寸搏指，右关微实，原文虽标‘脉之左寸结’，然所述实为搏指微实。左寸候心，搏指为少阴之火不降，上焦气壅；右关候脾胃，微实为阳明之路塞，太阴运化滞。惊则气乱，火不降而气壅，故痞闷气逆、自汗、嗌干。此脉示火郁气壅、脾胃滞塞之病机。", ["结"]], "10433": ["病机", "经水适来而脉微结，微为阳气衰少，结为脉气时一止复来，主气血虚滞、运行不畅。经行之际，血海空虚，阳气不足，故脉微；血虚气滞，脉道不利，故结。此脉示气血两虚、寒滞胞宫之病机，多见于经行不畅或虚寒痛经之证。", ["微", "结"]], "10434": ["预后", "脉迟而少胃气，忽断忽续，迟为阳气虚衰，少胃气则谷气不充，脉失柔和；忽断忽续乃胃气将绝、脉气不相接续之象。询知一日只饮米汤两杯已三月，胃气匮乏，化源告竭，故脉迟而断续。此脉示脾胃虚败、阳气衰微之危候，预后堪忧，非参不可挽回。", ["迟"]], "10435": ["病机", "右关尺滑弦，右关候脾，尺候肾。滑为水湿痰浊，弦为肝木乘土。原文谓‘脾邪传子’，即脾病传肾，肾本寒，龙雷不安，肝挟肾邪乘衅而动；寒邪中太阳，内外合邪，水聚上泛，肝盗母气冲胁，土衰木克，水气乘之，酿蒸发黄。此脉示脾肾虚寒、肝木挟水湿泛滥之病机。", ["滑", "弦"]], "10436": ["病机", "右滞而缓，左关微弦。右候脾胃，滞为气机壅滞，缓为湿困中焦；左关候肝，微弦为肝郁。原文谓‘怒动肝火，阴络内伤，兼之中焦挟食’，故脉右滞缓、左微弦。滞缓示中焦食湿壅滞，弦示肝火内郁，灼伤阴络则便血，肝火犯胃则胸热口干。此脉示肝郁化火、中焦挟食之病机。", ["滞", "缓", "弦"]], "10437": ["治法", "原文未识脉名，纯论喉痹治法。引《经》‘一阴一阳结，谓之喉痹’，谓肝与心主、胆与三焦之脉并终于喉，火性急速，直犯清道，闭而不通则死。故治法总在膈上著意，辛开苦泄为大纲，祛邪、凉肺、救败，攻补温凉并施。此段主论喉痹火郁闭阻之病机与治法，非凭脉断病。", []], "10438": ["主病", "脉洪数有力，洪为阳明热盛，气血燔灼；数为热邪亢盛，鼓动血脉；有力为实热内炽。症见热渴大汗，乃阳明气分热盛，迫津外泄，耗伤津液。洪数有力之脉与热渴大汗相应，主阳明实热证，故以加味白虎汤清泄阳明、生津止渴。此脉示实热炽盛之病机。", ["洪", "数"]], "10439": ["病机", "左关沉细而紧，左关候肝，沉为病在里，细为阴血不足，紧为寒邪内束。症见目赤如鸠、梦泄不禁、足冷如冰，乃厥阴肝经寒凝，相火不藏，虚阳上浮。沉细紧示下焦虚寒、肝经凝滞，故桂附不效，治以温养厥阴、固涩下元。此脉示厥阴寒凝、阴阳不相顺接之病机。", ["沉", "细", "紧"]], "10440": ["病机", "右脉弦紧，弦主气滞、紧主寒凝，右关候脾胃，故知中焦寒凝气滞，脾失温运则胃脘痛、脾泄；寒凝下元、肾气不固则梦遗。弦紧并见为寒邪内结、阳气不伸之象，故治法取温中固肾，以术、附、姜温中，益智、龙牡、菟丝固肾涩精，药后诸症悉愈，正合弦紧所主之寒凝阳虚。", ["弦", "紧"]], "10441": ["病机", "右关弦滑而紧，关候胸膈脾胃，弦紧主阳气不舒、阴寒内结，滑主痰湿阴邪。原文断为“胸中阳气不舒，阴邪微结”，即仲圣胸痹之机。阴邪痹阻胸阳，故胸中常闷、饮食少进。治以瓜蒌薤白白酒汤通阳散结加半夏化痰，五剂而瘳，正说明弦滑紧所主为阳微阴结之胸痹。", ["弦", "滑", "紧"]], "10442": ["病机", "原文未明写脉形，仅言“心小而胆伏”，心脉小为心气不足，胆脉伏为气机郁伏。气从少腹上冲至心下、痛不可忍、惊恐即发，是冲脉气逆、二厥阴失调之冲疝。心胆之脉如此，说明病涉手经神明与足经冲脉，故治统二厥阴兼安神镇冲，二剂愈，可见脉小伏所主为气逆里急、心神不宁。", []], "10443": ["病机", "原文未列具体脉名，只言“少和润之致”，即脉失和润、津液不足之象。患者善咳病噎，又因郁甚而水浆下咽即吐、艰涩异常、腹微痛、大便秘结，皆由肠胃津液干枯、传道下秘、浊气上升所致。脉少和润正应津枯血燥，故断非大养营血不可，说明此脉所主为阴血亏虚、肠燥气逆之机。", []], "10444": ["病机", "原文未出具体脉形，仅言“奇脉不司统摄”，指奇经失于统摄之脉象。脾虚则运化无权而泄泻，奇经不摄则气逆上冲而不得卧。病机在脾虚不运、奇经失约、气逆不降，故治法议从中焦脾胃着手，兼理奇经，以复统摄之权。此段脉象虽略，主旨仍在阐发脾虚及奇经不摄之病机。", []], "10445": ["预后", "脉不浮不沉而数，不浮则邪不在表，不沉则邪未全入里，数主热盛。身热下痢、干呕而渴、胸中痞闷，为风温之邪乘虚内陷，热扰胃肠、上逆胸膈。数脉示邪热鸱张而正气受困，故原文断为“深为可虑”，议从阳明升举透邪。此段以数脉言邪陷之危，主旨属预后判断。", ["数"]], "10446": ["病机", "脉象虚数，虚主正气不足，数主风阳频动。中气亏虚则肝阳易动，风阳上扰故不食而眩晕；肝犯脾及胃，中焦失于砥柱，虚风有上逆厥脱之势。原文“中无砥柱”正点明脾胃虚弱、不能镇摄之机，故用四君子汤补中以固本，加镇摄之品以防厥逆，说明虚数脉所主为脾虚风动、中气不支。", ["虚", "数"]], "10447": ["病机", "脉滑多痰，滑为痰湿内蕴之象。原文谓“痰即湿邪之出路”，说明湿郁化痰、痰湿外现于脉，宣通湿郁则痰有去路，痹证不成。此段以滑脉言痰湿内郁之机，指出治当宣通湿郁而非单纯止痰，脉滑与多痰、湿郁相互印证，主湿痰阻络、痹证将成之病机。", ["滑"]], "10448": ["病机", "原文以“脉浮头项痛恶寒”为寒邪初犯太阳之证，浮脉主邪在表，太阳主一身之表，故寒邪袭表则脉浮，伴头项痛、恶寒。传至阳明则太阳证罢而变胃家实，身热汗出、不恶寒反恶热，说明邪已离表入里。此段借伤寒传变之界划昭然，反衬少阴伏温“在一经不移”、不即传变之特点，脉浮在此标示表邪初犯之病位。", ["浮"]], "10449": ["病机", "原文谓暴感温邪“所见之证，不外肺胃两经”，头痛咳嗽、气逆痰多、寒热痞闷、烦渴呕恶皆肺胃外感之象，故“脉象不外浮弦数大”。浮主邪在表，弦主风邪外袭，数主温邪化热，大主阳邪亢盛，四者合见，正说明温为阳邪、暴感初起邪郁肺胃、表里俱热之病机，故用药以辛凉散风、清泄温邪为主。", ["浮", "弦", "数", "大"]], "10450": ["病机", "原文言伏气发温乃“少阴阴气先伤，而寒邪袭之，至春夏化热而发”，热在骨髓故骨节烦疼、昏昏欲寐，“脉象愈按愈数，尺部不静，尺肤燥热”。愈按愈数说明热郁于里而深伏，非表邪之浮数；尺部不静、尺肤燥热正应少阴伏热内郁之象，舌苔如平人、或渴或否，皆热内郁而未外达之征，与外感迥殊。", ["数"]], "10451": ["预后", "原文论治痧疹后“邪恋正虚，将成劳者”，用四物加杏仁、苏叶、桔梗，并明言“倘神识脉情已脱者，无益也”。此处未出具体脉名，以“脉情已脱”言脉气败绝、神气涣散，属正虚邪恋、精气将竭之候，故虽拟方调治亦难挽回，主旨在于判断痧疹后邪恋正虚者之预后吉凶。", []], "10452": ["病机", "原文以“口渴、汗多、脉大”六字尽石膏证，脉大主阳明热盛、邪热蒸腾于外，与口渴汗多相应，故用石膏清泄气分实热。过其时口不渴而脉细，说明热邪已入血分，脉由大转细，是气分热退而血分受病之象，故“便入血分，是犀角证”，以脉之大小转变标示邪之在气在血。", ["大", "细"]], "10453": ["病机", "原文辨胁满胁痛为半表半里之证，表邪传里必由胸至胁。无汗脉浮恶寒胁痛，浮主表邪未解，故先用羌活、柴胡、防风发散表邪；脉浮紧、脉浮无汗者皆表寒束闭之象；脉沉数则邪已入里化热，脉沉里热者当从里治。浮沉数三脉并举，正说明胁痛一证须辨表里寒热、邪之深浅而分途施治。", ["浮", "沉", "数"]], "10454": ["病机", "原文述“胁下偏痛发热，其脉紧弦，此寒也，以温药下之，大黄附子汤”。紧主寒、弦主痛，紧弦并见说明寒邪内结、阳气被遏，故胁下偏痛而发热，此非热邪而是寒实内聚，故用温药下之。前文瘀血胁下刺痛、湿痰攻注等证，亦须凭脉与症合参以定攻补温下之法。", ["紧", "弦"]], "10455": ["病机", "原文述霍乱“上吐下泻，肢冷转筋，脉伏螺瘪”。脉伏说明吐泻交作、津液暴脱，阳气不能外达，气血内闭，故脉沉伏不显；螺瘪指指螺凹陷，为津液枯竭之征。肢冷转筋亦由吐泻亡津、筋脉失养、阳衰不达四末所致，故谓朝发夕死、不及延医，示此证危重。", ["伏"]], "10456": ["病机", "脉伏汗淋，四肢厥冷，看似阳气欲脱，然原文分三证：阴寒逼阳外越、虚阳外脱、热邪深闭致外厥。脉伏为阳气内闭或外脱之象，汗淋为阳泄，故须细辨寒热虚实，毫厘之差死生反掌。", ["伏"]], "10457": ["病机", "暑邪重者，舌燥苔起沙、边尖绛，脉必弦数。弦主暑热内郁、气机不畅，数主热盛。此脉象说明暑热炽盛，兼外感形寒无汗，故治宜开太阴肺气，透表清暑。", ["弦", "数"]], "10458": ["病机", "脉滑不数，汗出热不解，唇焦不燥渴，为食积下焦、挟食阻遏之象。滑主食滞痰积，不数说明热未炽盛。原文强调挟食致误，寒凉胶结不化，故脉滑不数主食积内阻，非单纯六淫。", ["滑", "数"]], "10459": ["病机", "原文未提脉象，专论肝风虚实。木郁化火生风为实，血虚木燥生风为虚。肝风上扰则巅痛头晕耳鸣目眩，内燔胃口则烦扰不寐嘈杂呕酸，外感经络则四肢痉掣麻木。此段主在阐发肝风病机与治法。", []], "10460": ["病机", "痢垢数日不止，状如休息，脉象软数。软为脏真暗伤、脾气虚弱，数为积垢未净、邪滞肠腑。清晨气滞，故脉软数说明正虚邪恋，当温补为主佐以疏通，不可纯攻。", ["软", "数"]], "10461": ["病机", "由疟转痢，所下垢腻如痰，神倦肢清，脉弱舌滑苔白燥。脉弱主脾阳虚弱，舌滑为痰湿内阻。脾阳与胃阴两伤，痰气尚阻，故脉弱说明正气已虚，邪滞未畅，治仿理中法加味。", ["弱"]], "10462": ["病机", "瓜积伤中，腹痛泄泻近月，气坠不爽微有红垢，舌苔白腻，脉象细数。细主气弱营虚，数主邪恋化热。脾营下陷欲作痢疾，气弱邪恋，故脉细数说明正虚邪滞，恐其淹缠，姑与温通。", ["细", "数"]], "10463": ["病机", "腹痛滞痢，得冷则剧，脉左弱右弦。左弱主脾气虚寒，右弦主中宫暑湿、气机不畅。气弱邪恋，故脉左弱右弦说明脾虚寒而暑湿内阻，最易淹缠，拟方温中疏邪。", ["弱", "弦"]], "10464": ["病机", "脉虚细弱数，虚细弱为肝脾营气受伤、正气亏虚之象，数则示营分余邪未清。久痢不已，肝失疏达、脾少健运，故当脐及脘左块痛、纳少不畅，气机阻窒滞陷。正虚邪恋，故脉数非纯热，乃余邪扰动。", ["虚", "细", "弱", "数"]], "10465": ["病机", "脉细弦弱，细弱为气阳虚寒、营血不足，弦主痛及木郁。中气虚寒由气分伤及血分，故痢下瘀紫血水、肢冷腹痛。脉细弦弱正合虚寒入血、肝脾不和之机，故拟建中法佐温营畅气。", ["细", "弦", "弱"]], "10466": ["病机", "脉虚细，为肝脾营气大伤、气血不足之征。便血颇多，阴血耗损，气随血弱，故神倦乏力。脉虚细紧扣营气大伤，主肝脾清摄失职，当从肝脾清摄以复其统血之能。", ["虚", "细"]], "10467": ["病机", "脉象弦数，弦主肝郁，数主热，合舌苔黄浊，显系湿热内踞、肝脾受病。先患便血，温涩后湿热未化，中气受伤而脘腹胀满。脉弦数说明湿热伤营、肝脾不和，故法当清泄肝脾，勿容温补助邪。", ["弦", "数"]], "10468": ["病机", "左脉弦数，左关候肝，弦数为肝经湿热留恋之象。便血肛脱虽属气虚下陷，但腹中未和、舌苔带浊，浊痰上壅，说明湿热未清。脉弦数揭示邪未净，故宜先疏化，不可骤用升补。", ["弦", "数"]], "10469": ["病机", "左手弦长，关部独大，弦长为肝木自郁于本宫、气盛有余之脉。肝木犯胃，气侵及胃，故痛呕而胀、发必五日，甚则形寒汗出。脉象说明肝郁气逆为主，胃受其累，故先泄木安胃。", ["弦", "长"]], "10470": ["病机", "脉象左弦右弱，左弦为肝气上逆，右弱为胃气下降、中气不足。寒热虽退，而撑痛呕胀、舌中黄厚、时或吐红，皆胃气不得下行之征。脉象揭示肝逆胃弱、升降失司，故当泄肝和胃。", ["弦", "弱"]], "10471": ["病机", "脉象细弦，细为营血不足，弦主肝木郁逆。撑痛当脘及左胁、呕吐酸浊，病缘肝木犯胃，挟中焦痰浊上逆不降。营卫相忤则形寒里热，风木浮扰则耳鸣头眩。脉细弦正合肝病为主、痰浊内阻之机。", ["细", "弦"]], "10472": ["预后", "关格已久，正气已亏，又见肝气横逆、撑痛作呕，脉细弱无神，是脾胃衰败、气血两虚之象。细为阴血不足，弱为阳气衰微，无神则胃气将绝，故曰病象已深。虽用疏木降胃，然脉证不符，攻伐更伤正气，预后堪忧。", ["细", "弱"]], "10473": ["病机", "肝营窒塞化火生风而眩运，血络不调而瘀阻，脾气不运而腹闷色黄、舌浊肢冷。吐瘀后咳逆喉鲠、胸膈板滞，肝气逆于肺络。脉虚数为脏损之征：虚为气血亏耗，数为火动于内，正虚邪实，调治颇难。", ["虚", "数"]], "10474": ["主病", "肝木郁陷，气机不畅则腹痛；郁而化火，风阳上扰则头晕。脉弦为肝郁之象，数为郁热之征。弦数并见，说明肝郁化火、气机失调，故用养肝调气法，使木得条达则痛晕自止。", ["弦", "数"]], "10475": ["病机", "前诊和肝通络后胀痛攻窜减而未止，脉弦中带数，弦主木郁气滞，数主郁而化热，故断为木郁无疑。痛偏于右，是木邪侵于肺胃之界，气机壅滞。于前法加推气散意，正为疏达肺胃之气、解木郁之横。", ["弦", "数"]], "10476": ["病机", "新产奇脉不充，冲脉上逆，致胸脘撑胀上及于嗌。左关候肝，浮弦而数，是风木化火、郁而上升之象，故巅痛项强。弦为肝郁，数为火盛，浮则升越。治当泄木和胃，兼平冲脉之气，使上逆之势得降。", ["浮", "弦", "数"]], "10477": ["病机", "肝气上逆则胀闷，肝风内动则眩晕。脉弦硬，弦为肝郁，硬则木失柔和、郁而不达，气机刚劲失和。此脉象反映肝木郁滞、风阳内动之机，故用药以和肝为主，使木气条达柔和，则胀闷眩晕可平。", ["弦", "硬"]], "10478": ["病机", "肝木犯胃，胃失和降，故呕吐酸苦浊涎；舌红为热象。脉细弦，细主阴血不足，弦主肝气郁滞，是肝郁化火、气火上逆，肺金失于肃降。法当苦辛泄降，苦以降火，辛以开郁，使气火下行、肺胃得安。", ["细", "弦"]], "10479": ["预后", "肝木犯胃，脘痛日作，属气分病。然脉细数右弦，细为阴血亏少，数为内热，右弦主肝气偏亢；兼内热咳嗽，是肝营窒损、阴血有干涸之虑。气分病而见阴血不足之脉，说明病势由气及血，故预后当虑阴亏。", ["细", "数", "弦"]], "10480": ["病机", "右弦主木旺克土，左数主肝火内郁。原文谓“气虚木旺，中气输运失常，湿热留恋，阻窒气机”，故脘腹胀闷、天阴则甚；经水淋沥先期乃“木火内郁，肝血不藏”。脉象右弦左数正合肝郁化火、脾虚湿滞之机，病偏气分，舌苔厚浊为湿浊之征。", ["弦", "数"]], "10481": ["病机", "左脉尚数，说明肝经郁热未清。原文谓“内热虽减，左脉尚数，肝经络气未和”，故胁左板窒作声。数脉主热，左关候肝，热郁肝络则气机不和，虽内热减轻而脉数未除，提示肝火余焰未息，络气仍滞，故续以和络清肝佐滋养。", ["数"]], "10482": ["病机", "左脉细数，细为阴血不足，数为内热；右寸关浮弦，浮主肺气不降，弦主木郁克土。原文谓“肝木郁陷，脾土受伤”，咳呛属肺、疝坠属肝，皆木气为患；泄泻内热、神瘁少纳则中气被戕。脉象反映肝郁化热、脾虚中馁，故泄木培中以防损途。", ["细", "数", "浮", "弦"]], "10483": ["病机", "濡软主肝肾内虚，中带弦为寒邪乘袭、肝邪上犯。原文谓“痛由少腹上掣及脘”，乃肝肾内虚、寒邪侵及中部，中阳亦虚。弦脉应肝，肝寒犯胃则痛掣；濡软示正虚。脉证合参，肝邪上逆易变冲厥，故痛势暂平即须调理预防。", ["濡", "软", "弦"]], "10484": ["预后", "脉象细数，左尺浮数，细为阴血耗损，数为肝火蒸灼，浮为火逆上炎。原文谓“血行清道而为衄血”，肝火蒸灼营阴，血络沸腾，阴血日耗，木火愈甚，上克肺金则喘逆鼻煽，下及肾阴则纳少跗肿便溏。病见于上而根坏于下，故称损症最深之候，预后堪忧。", ["细", "数", "浮"]], "10485": ["病机", "左细右数，左细为肝阴不足，右数为阳明热盛。原文谓“病因肝火窜于阳明之络，火随血泄”，吐血止后牙床又肿，乃肝火循经上窜阳明，火虽随血外泄而脉数未平，阴血已伤故左脉细。脉象示肝火未清、营阴受损，故用清营泄肝法。", ["细", "数"]], "10486": ["病机", "脉象滞数，滞主气机壅塞，数主木火内郁。原文谓“肺气稍平，胃气尚未顺降，而病原实由于肺气之不平”，滞数示木火不化、气机不畅。肺失肃降则胃气不降，木火郁而化热故数。脉象反映肝肺气滞、木火未清，故以煎剂疏胃气、丸剂疏肝木。", ["滞", "数"]], "10487": ["病机", "弦为肝脉，数主火盛。原文谓“肝火不平，挟冲任之血上升为衄”，弦数并见，说明肝火亢盛、冲任之气上逆，迫血妄行而为衄。色黄内热亦为火象。脉证相合，故用清火泄木之法，使肝火平而血不上溢。", ["弦", "数"]], "10488": ["病机", "脉弦细为肝郁阴伤，右浮示余邪未尽、肝火上浮。原文谓\"余邪内伏，肝火上浮\"，故痛由左胁及脘、掣及胸背、上引太阳，皆肝经循行部位受扰。弦主肝病，细为阴血不足，浮为火性上炎，合而示饮邪内伏、木火升腾之机，故治法蠲饮与泄木并用。", ["弦", "细", "浮"]], "10489": ["病机", "脉细涩不畅，细为脾虚气血不足，涩为湿浊郁滞、脉道不利。原文\"脾虚湿郁，面色黄浮\"，又\"近感新邪，兼增寒热\"，苔晦亦湿浊之征。脾虚失运则湿郁，湿阻气机则脉涩不畅，新邪外袭故寒热并作。此脉示本虚标实、湿浊中阻之机，故治以和中泄浊。", ["细", "涩"]], "10490": ["病机", "左脉弦细而数，弦为肝郁，细为阴虚，数为化火；右寸关浮搏而数，示肺胃之气为木火冲激。原文\"木气为湿土所郁，渐至化风生火\"，故呕吐痰沫、气逆头痛、内热口渴。脉象反映肝胃同病、寒热错杂，兼阴虚木火易燃，故温中蠲饮须防劫阴，拟肝胃两调、寒热互用。", ["弦", "细", "数", "浮"]], "10491": ["病机", "右脉弦硬，弦主肝气，硬为气郁坚结、胃气不柔。原文\"嗳哕硬噎，纳谷撑胀\"，皆肝胃气郁、逆而不降之症。右脉候脾胃，弦硬见于右，示肝木犯胃、胃气壅滞不能通降，故见噎嗳撑胀。此脉主肝胃气郁、逆而不降之病机，治当疏肝降胃。", ["弦", "硬"]], "10492": ["病机", "脉形滑为痰浊内盛之象，\"神不爽\"示痰阻气机、神明不展。原文\"肝气上逆，肺气不降，胃气被其搏激，失其通降之常\"，故嗳哕不已、纳谷哽噎。前医谓\"痰气相搏\"，脉滑正合痰征。然治痰必先理气，故拟通降肺胃、疏肝化痰，脉象示痰气交阻、肺胃失降之机。", ["滑"]], "10493": ["病机", "本段未识脉名，纯以症候论病机。原文\"肝胃不和，久则胃气空虚，痰浊内阻\"，故谷纳胀闷作呕、不得下降、大便坚少，渐有膈证之象；又\"肝气窜入络脉\"，腰腹撑痛，气病及血，癸水不调。此示肝胃不和、痰浊阻隔、气滞及血之机，治以通降胃气为主，兼和营泄肝。", []], "10494": ["病机", "左弱右弦，左候肝血不足故弱，右候肝气偏旺故弦。原文\"大便通降，胃气得以下行，故纳谷渐增\"，示胃气渐复；然\"腹中撑痛，头眩耳鸣，癸水愆期\"，皆肝气不和、气病营窒、化火生风之征。脉象左弱右弦，正示肝血虚而肝气横，故治法以疏肝畅营为主。", ["弱", "弦"]], "10495": ["病机", "脉弦细而数，弦为肝郁气结，细为胃阴渐涸，数为木火内燃。原文\"肝气不和，久而气瘀交阻\"，故脘痛当心、肢厥、呕水不安谷、大便艰涩；舌红亦火象。脉示气瘀交阻、木火灼阴、胃阴耗涸，已属关格重候，故治以泄肝养胃、疏畅气瘀，并须宽怀调理。", ["弦", "细", "数"]], "10496": ["病机", "脉弦软无力，弦为木火久逆之象，软而无力则示胃中气液两伤，不能安寐乃胃不和则卧不安。痰瘀所阻，脉道不畅，故虽痛呕较减而病根未除，主胃腑气液两伤、木火未靖之病机。", ["弦", "软"]], "10497": ["病机", "脉象弦数，弦为肝气横逆，数为木火内燃。脘痛胀、朝食暮吐、酸浊，皆肝气犯胃、中阳不运所致。四末不温乃阳郁不达，由肝气而成反胃，正属难治，主木火内燃、中阳不运之病机。", ["弦", "数"]], "10498": ["兼症", "脉象左虚右弦，左虚为胸气痹窒、肺气不足，右弦为肝气偏亢。舌苔黄腻，虽属宿病而兼挟新邪，故以疏降肺气为主。此脉示本虚标实、肝肺气机失调，主胸痹兼新邪之兼症。", ["虚", "弦"]], "10499": ["病机", "脉象弦数，弦为肝气逆行，数为木郁生火。当胸气窒状如胸痹，由肝气逆行肺络、不能清降所致。木郁生火，火性急数，故脉弦数，主肝火犯肺、肺络不清之病机。", ["弦", "数"]], "10500": ["病机", "脉数舌黄，数为有热，黄为热象。痰气阻结，清阳被郁，兼有浊热蒙扰，故脉数舌黄。当宣痹泄浊，以开痰气之结、清浊热之扰，主痰气阻结、浊热蒙扰之病机。", ["数"]], "10501": ["病机", "脉象弦细滑数，弦为肝气窒而不化，细为寒湿内著，滑数为痰涎浊沫随气而结。舌苔白腻，脘腹胀满半载，来无因亦无苦，病情与单腹无异，主寒湿内著、肝脾之气窒而不化之病机。", ["弦", "细", "滑", "数"]], "10502": ["误治", "原文未识脉名，但据脉象是气阴两伤所致，非必定有浊热。先生用姜附，是从证不从脉，此乃脉证不符时舍脉从证之例。脉象示气阴两伤，而证见浊热，故用药虚实兼到，主误治辨析之旨。", []], "10503": ["预后", "脉象软细而不弦，软细为气液两亏，不弦则肝气郁陷之象不显。舌乾红少润，泄泻转腹胀，木陷土郁，气液两亏，药难著手，预后堪忧。主肝脾两疏、气液两亏之预后判断。", ["软", "细"]], "10504": ["病机", "脉涩数不畅，涩主气滞血瘀，数主热，合之则气血两窒、肝脾积热。肝木犯土，脾运失职，故脘腹胀满、时吐清水；积热内壅，气血瘀阻，经水亦停。此脉象直接反映肝脾积热、气血壅滞之病机，与胀满、停经等症相应。", ["涩", "数"]], "10505": ["病机", "脉细弱舌白，细弱主气血不足、中阳式微，舌白为阳虚寒湿之征。土虚则木乘，肝气横逆，故左胁撑胀；中阳不能鼓运，气阻痰凝，久则易成单胀。此脉示中阳虚弱、木乘土位之病机，与胁胀、痰凝等症相应。", ["细", "弱"]], "10506": ["病机", "脉细软而弦，细软为脾虚气弱，弦为肝木偏旺，合之乃肝木侮中之象。舌苔黄浊，浊壅气阻，故撑痛胀闷。木旺克土，气机壅滞，恐延腹胀之候。此脉象揭示肝强脾弱、浊气壅阻之病机，与撑痛胀闷、苔黄浊等症相应。", ["细", "软", "弦"]], "10507": ["病机", "脉软细不畅，软细主气血两虚，不畅为气机阻窒。咯红虽止而脘胀不减、不能纳谷，乃肝脾之气阻窒不化，疏泄与运化失职。老年病久，正气已衰，故脉见软细。此脉示肝脾虚滞、气机阻窒之病机，与脘胀、纳呆等症相应。", ["软", "细"]], "10508": ["病机", "脉形虚数，虚主正气不足，数主阴分亏虚、虚热内生。胀减而仍痛，脾气未舒；形寒晚热少汗，乃肝脾阴气内亏，营卫失调。此脉象反映肝脾阴亏、虚热内扰之病机，与形寒晚热、少汗、胀痛等症相应。", ["虚", "数"]], "10509": ["病机", "左脉微弦，右脉细弱，弦为肝气偏旺，细弱为脾气虚衰。肝气下陷，脾气不能输运，浊积停阻，故脘右结痞、纳谷则脐下作胀，舌苔浊腻。此左右脉象对比，揭示肝陷脾虚、浊积内停之病机，将成腹胀之候。", ["弦", "细", "弱"]], "10510": ["病机", "脉象细涩不畅，细主气血不足，涩主气机涩滞、血行不畅。病后气机不化，脾肺通降失职，肝木疏泄无权，故肢面浮肿、脘腹胀甚。此脉象反映脾肺肝三脏气机壅滞、水湿不化之病机，与浮肿、腹胀等症相应。", ["细", "涩"]], "10511": ["病机", "脉弦细而数，弦为肝郁，细为阴血不足，数为郁热内盛。肝木郁陷，脾气阻结，湿郁化热，木郁化火，阻窒不达，中阳抑遏，故腹胀筋青、胁左结瘕。虽在髫年而病挟情志，此脉象揭示肝郁脾结、湿热化火之病机。", ["弦", "细", "数"]], "10512": ["病机", "脉象虚弦无力，虚为中气受伤、脾土无自立之权，弦为木气乘土、肝木未疏。前用疏木清湿腹胀减而复作，正因脾土本虚，药力一过则病势旋平旋发。故非单纯湿滞，乃中阳不足、木郁乘土之本虚标实证，须参培益中阳、标本兼治。", ["虚", "弦"]], "10513": ["病机", "左关不和、右按弦数而硬，弦主肝郁，数硬为气聚血凝、木邪乘土。曾吐瘀便黑，是肝郁气聚则血凝之征；腹胀如鼓、小水不利，乃脾伤湿壅，与痹病湿热不同。所虑脏气内窒、行动无权，说明病机在肝气内郁、气血壅窒，非外湿可比。", ["弦", "数", "硬"]], "10514": ["病机", "经阻数年而腹胀如鼓，脉细而数。细为营气内窒、血脉不充，数为肝阳浮越、郁热内扰。经阻则瘀血内停，瘀阻气机则腹胀如鼓，营窒阳浮故脉细数。原文断为瘀胀重证，正说明瘀血内结、肝阳浮越之病机，非一般水胀。", ["细", "数"]], "10515": ["预后", "前与畅肝疏瘀，大解频见紫黑，瘀从下出，渐得脉软胀松。脉软则弦硬之势已减，胀松则气机渐通，故云于病情尚有转机。然瘀未全化，即病根未动，脉软胀松仅示一时缓解，不可视为痊愈，仍须以前方增损续化其瘀。", ["软"]], "10516": ["病机", "疟后周身肤肿数月不愈，右寸关浮数而硬。右寸关候肺脾，浮为气失舒运、病位在表分，数为郁热，硬为气机壅滞不柔。疟后肺脾两经之气失于舒运，水湿不化而肤肿。故用五苓五皮合香苏法，以运脾宣肺、化气行水。", ["浮", "数", "硬"]], "10517": ["病机", "浊热蒸郁，脾病及肺，咳痰带红、气逆面浮肢肿，脉象细数。细为营阴不足、脾肺气虚，数为浊热内蒸。脾病及肺则宣降失职，气逆而咳痰带红；水湿不化则面浮肢肿。故当肺脾两调而以清降为主，清其浊热、降其气逆。", ["细", "数"]], "10518": ["预后", "病起产后已历两年，气血两窒而周身浮肿，脉虚少纳，内热无汗。脉虚为正虚不足，少纳则中气衰败，气血两窒则水湿不化。正虚而肿满日甚，故势必陷成肿满，属虚中挟滞之重候。姑与和中法，先扶中气以图缓治，示预后堪虑。", ["虚"]], "10519": ["病机", "中气不化，浊邪下注，肿从足跗上延脘腹，脉弦数，舌光白。弦为气机郁滞、木不疏土，数为浊热内郁。中气不化则水浊下注而肿起足跗，渐延脘腹；舌光白示气阴已伤。故宜和气泄浊，疏其郁滞、泄其浊邪，使中气自化。", ["弦", "数"]], "10520": ["病机", "左软右弦，左候血、右候气，右弦为气机郁滞、木不疏土，故中气失于调畅；左软示湿邪偏胜、脉道不实。面浮略退而湿邪留滞，正合软脉主湿、弦脉主气郁。治当疏畅气机以化湿，脉象反映湿滞与气郁并存之病机。", ["软", "弦"]], "10521": ["病机", "脉细为经气不旺、阴血不足，数为寒湿久郁化热之象；细数不鼓，说明正气虚而邪气附于阴经，故跗肿上及腿腹。原文谓“病底颇深，经气不旺”，细数正示正虚邪恋、寒湿附经，故拟培土温经，从本图治。", ["细", "数"]], "10522": ["病机", "腹块撑痛半载，气窒血阻，瘕痛历久化热，脉细数正合久病阴伤、郁热内壅之机。细为营血不足，数为热象，故形寒内热并见。原文虑其“壅而成脓”，细数脉示正虚而热郁，故治以畅气通瘀、疏调营络。", ["细", "数"]], "10523": ["病机", "脉弦主肝郁气滞、痛证，迟主寒凝阳弱。脘右瘕撑作痛、宿病剧发，弦迟并见，说明气分寒凝、阳气不运，瘕块因寒而痛剧。原文“法当温通气分，佐以泄降”，正针对弦迟所主之寒滞气阻病机。", ["弦", "迟"]], "10524": ["病机", "瘕疼略减而足热头晕，乃中虚木火浮注；脉仍弦迟，弦为肝木偏旺，迟为脾阳不足、寒湿内滞。弦迟并见，示土虚木乘、寒热错杂之机。原文用建中泄木法，即温中以复脾阳、泄木以平浮火，脉象未变说明病根未除。", ["弦", "迟"]], "10525": ["病机", "脉弦长为肝木亢盛、气机横逆，数为木火化热。脘中瘕痞攻冲作胀，病由肝木乘土，胃虚则汗出头晕，此木火化风。弦长而数正示肝旺乘土、化风化热之机，故于泄木中兼培土，标本兼顾。", ["弦", "长", "数"]], "10526": ["病机", "脉浮弦搏指而不耐重按，浮为阳气外浮，弦为肝郁气结，搏指不耐按示中阳已耗、根本空虚。脘左痞结数年，发则寒热痛胀，正合正虚邪结之机。原文谓“不堪攻伐”，故姑与疏中化气，缓图其治。", ["浮", "弦"]], "10527": ["病机", "再诊脉浮搏较和，说明前法已使浮越之气稍敛、搏指之势渐缓，故痞痛较减。惟宿瘕不化、中气久伤，脉虽较和而根本未复，仍不耐攻伐。原文再与两和肝脾法，渐渐疏化，示脉象好转而病机仍属正虚邪恋。", ["浮", "搏"]], "10528": ["病机", "脉虚数示气病久结，阴液渐伤，正气渐削。虚为正气不足，数为阴液亏虚生内热。脘右瘕痞不化，舌红，皆阴伤正削之象，故未便攻伐，当畅气调营，扶正为要。", ["虚", "数"]], "10529": ["病机", "脉仍虚，示胃气虽略醒而正气未复。脘中瘕结不化，势难攻消，因虚不耐攻伐。当先养胃畅气，以扶正为主，待正气渐复再议消瘕。", ["虚"]], "10530": ["病机", "脉细涩而数，细为营血不足，涩为血行凝滞，数为瘀久化热。唇舌紫暗、爪甲色青、癸水不通、便下瘀紫黑血、少腹绞痛，皆营阻血瘀之征。冲气上逆，非温养疏通不能奏效。", ["细", "涩", "数"]], "10531": ["病机", "左手弦硬，右手细数，弦硬为肝气火旺，细数为阴伤内热。瘀血上吐下泻，气火上逆，目红喘促，爪甲唇舌紫黑，血之壅滞尚未流通。仍当和营导瘀，佐通降使下行为顺。", ["弦", "硬", "细", "数"]], "10532": ["病机", "脉软数，软为气血不足，数为内热。腰俞延及左胁掣刺作痛，难于转侧，此血络瘀伤。时有内热，阴气暗伤，故当兼滋养，和络化瘀之中佐以养阴。", ["软", "数"]], "10533": ["病机", "脉数主热，热久阴亏。少腹偏左注痛引腰脊，寒热连绵，舌红，此血络瘀阻，邪机下注，郁而化热。热久伤阴，故脉数舌红。治当和络畅营，疏通邪滞。", ["数"]], "10534": ["病机", "脉左弦右弱，左弦为肝木不调，右弱为营血不足。漏血不止，血不归经，腹中撑坠，皆肝木失调、奇脉不固所致。法当条木摄营，兼固奇脉，使血归经。", ["弦", "弱"]], "10535": ["病机", "脉细软带数，细软为营血亏虚，数为虚热。经漏数月，瘀紫转鲜淡，腹痛止而腰脊酸，病象由实转虚。当滋养营血，固摄奇脉，以复其虚。", ["细", "软", "数"]], "10536": ["病机", "原文未出脉名，以“经水淋沥不断，腰脊酸疼，奇脉不调，经络不畅”立论。经漏日久，奇经失约，血络瘀滞，故痞块撑痛；兼见虚窒，是络虚与瘀结并存。病机属奇脉不调、血络不畅，主经漏、痞块撑痛，治以调畅奇经兼疏血络。", []], "10537": ["病机", "右关脉弦数壅结，弦为肝旺，数为火动，壅结示气火郁于中焦。原文谓“肝火内扰，血不能安”，故崩漏屡发；又述起由经阻、营络先不畅，是火迫而络瘀。脉象主肝火扰血、营络不畅，治当熄肝和营，勿遽用涩。", ["弦", "数"]], "10538": ["病机", "原文未出脉名，以“血漏未止，稍劳即发，下部经络不舒，奇脉不畅，肝火不平”为据。劳则气耗，奇脉失摄，故漏血易发；肝火不平，下扰冲任。病机属奇脉不固兼肝火，主漏血、下部经络不舒，治以摄营清肝和奇，上部痰浊另化。", []], "10539": ["病机", "脉数疾微弦，右寸关尤觉锐快，数疾为营血大伤、虚热内动，微弦示肝脾失调；锐快见于右寸关，是痰浊阻壅、脾阳不振之象。原文谓“营血大伤，脾阳不振，而痰浊因之阻壅”，故纳谷不旺、形寒发热。主失血后营损脾弱、痰阻虚热。", ["数", "疾", "弦"]], "10540": ["病机", "原文未出脉名，述“先经停而后崩漏，腰脊酸痛，奇脉不调，冲任不固，头晕少纳，肝胃不和”。经停后崩漏，是冲任失约、奇脉不固；腰脊酸痛应奇经；头晕少纳属肝胃不和。病机为奇脉不调、冲任不固兼肝胃不和，治当固摄奇脉兼和肝胃。", []], "10541": ["病机", "原文未出脉名，为崩漏后再诊。崩漏之后肝血必虚，头晕嘈绞乃肝阳上扰；脘块攻撑为木气不和；带下腰酸属中气虚陷。三症合观，病机在肝脾两虚、奇脉失固，主崩漏后眩晕、脘胀、带下腰酸，治以调补肝脾、固摄奇脉为主。", []], "10542": ["病机", "原文未出脉名，谓“奇脉不固，为木火所冲激，经漏不止，腰酸色瘀”。木火冲激，奇脉失约，故经漏不止；腰酸色瘀，是络中留瘀、血行不畅。病机属肝火冲激奇脉、营络瘀滞，主经漏、腰酸色瘀，法当清肝固奇、疏畅营络。", []], "10543": ["病机", "脉象细数而弦，细为营阴亏，数为虚热，弦主肝郁。崩漏后晚热盗汗，是阴亏热扰、微邪乘虚袭于营分，留恋日久即为营损；舌心黄厚兼食滞。脉症合参，主营阴亏损、虚热恋邪，兼食滞不化，治以养阴泄邪稍兼化滞。", ["细", "数", "弦"]], "10544": ["病机", "左脉浮数，右脉虚细，浮数为肝经风热浮动，虚细为营血亏虚。经漏淋沥、腰酸嘈运，乃血不养肝、木燥生风、血不能藏之象，愈漏愈虚。脉症合参，病机为肝热风动、营阴耗损，故当清肝摄营，用滋熄法。", ["浮", "数", "虚", "细"]], "10545": ["病机", "脉象虚细数碎，虚细为营阴不充，数为虚涩生热，碎则示枯涩之机。癸水停阻而内热不腹痛，由营阴本亏，复值酸敛，致虚涩生热。病虽初起而根蒂颇深，脉象已露枯涩，故先宜疏营撤热，冀得畅调。", ["虚", "细", "数", "碎"]], "10546": ["病机", "脉象虚细弦数，虚细为气血两虚，弦数为肝阳上越、瘀湿化热。癸期迟而淋沥、少腹气滞，奇经不疏；脘闷头晕偏痛，肝阴虚而阳越；小便坠痛兼血丝，气淋血淋之间；腰酸带下，脾虚湿陷。脉症示气虚而窒、血虚而瘀，虚实纷错。", ["虚", "细", "弦", "数"]], "10547": ["病机", "脉软细而数，右手带弦，脐右瘕痛，舌尖红苔黄，泄泻少纳，脉浮。软细数为邪陷伤阴、营损化热，弦为肝郁瘕痛，浮为邪未全陷。统观脉证，因邪陷而伤阴，因阴伤而营损，刻已损及中焦，不能多进滋浓，用药殊难。", ["软", "细", "数", "浮"]], "10548": ["病机", "脉象虚数，虚为阴血被耗，数为木郁化火。晚热盗汗、气撑胁痛、足冷颧红、气促不卧，乃肝气上逆于肺，木火刑金，阴血日耗，月事不通即其验。证属郁损，脉虚数正合郁火耗阴之机，故姑与熄肝肃肺。", ["虚", "数"]], "10549": ["病机", "脉象细弱，左手微弦，细弱为先天营气本弱，微弦为肝木失调。停经一载而无块痛，纳少胀闷，乃气窒而血液不畅，与瘀阻者不同。脉不涩不牢，故非瘀血实证，先拟畅肝和脾，纳谷渐旺，乃可渐进营分。", ["细", "弱", "弦"]], "10550": ["病机", "脉象虚，左弱右弦，虚弱为营阴亏耗，右弦为肝火偏甚。肝不藏血，癸水淋沥，时复逆行为衄，遇节发热，皆木火烁阴、阴血日亏、肝阳日亢之征。脉虚而弦，正合营损阳亢，有延及营损之虑，故拟养血熄肝。", ["虚", "弱", "弦"]], "10551": ["病机", "左脉涩数，右脉弦数，涩为营血不充，数为营热未清，弦为肝火不静。衄血虽止而营热未清，脉仍涩数弦数，知营阴未复、肝火未平。再与养血潜肝，苟得营阴充足，则经自调而痛自止，脉象可期转和。", ["涩", "数", "弦"]], "10552": ["病机", "左脉弦数，弦为肝气不和、木郁之象，数为郁而生热之征。肝主藏血，木郁化热则血不能藏，故经水先期而下。原文明言「肝气不和，木郁生热，故血不能藏」，脉弦数正合肝郁化热之机，治以凉肝泄木、清养营分，使热清则血自藏。", ["弦", "数"]], "10553": ["病机", "原文未载脉象，专论寒湿之邪乘虚袭于奇脉，致腰脊酸疼、癸期愈甚。奇脉隶于肝肾，寒湿客之则气血凝滞，经行时冲任气血变动，故疼痛加剧。病机为寒湿乘虚入奇脉、络气不通，法当温调奇脉，温散寒湿以通奇经。", []], "10554": ["病机", "原文未出脉象，述经来腰脊酸疼、上引头痛，断为寒湿之邪乘虚陷于奇脉。奇脉上行头脊，寒湿陷络则经气不利，故腰脊痛而牵引头痛。病机属寒湿陷奇脉、营络不和，兼肝气失调，故治法温经调营兼和肝气。", []], "10555": ["病机", "脉象虚数，虚为肝脾受伤、营血亏耗，数为内热之征。癸水逾期不通、少腹块痛，本属奇经实病，屡经攻克致肝脾受损，故内热少纳而转见营损。原文谓「实病未除，而虚证复起」，脉虚数正示虚实夹杂，治当循经和络、通调奇脉，不可再专事攻削。", ["虚", "数"]], "10556": ["病机", "原文未载脉象，述通调奇脉后少腹痛坠较甚、肢冷气秽，断为下焦营气不通，更兼肝木横克。肢冷气秽示下焦阳运不畅、营络窒塞，肝木横克则痛坠加剧。病机属营气不通兼肝郁横逆，故再与温畅奇经、疏肝和气，温通与疏达并施。", []], "10557": ["病机", "脉数色浮，数为内热，浮示营血不足、虚阳外浮。少腹痛减而癸水未通、块坠不化，虽有瘀血内阻，然内热少纳、血之来源本少，脉数色浮正是营虚内热之象。原文戒「专与消克，更伤正气」，故参增水行舟之法，养营中兼和瘀畅气。", ["数", "浮"]], "10558": ["病机", "原文未出脉象，述经来少腹滞痛、营气窒塞、奇脉不调。经行之际营血下注，奇脉失于温运则络气窒滞，不通而痛。病机为营气窒塞、奇脉不调，属寒滞络阻之候，故用温通法，温畅奇经以行营气而止痛。", []], "10559": ["病机", "脉象虚软带弦，虚软为营血不足、络脉失养，弦为肝木气陷之征。奇脉隶肝而主血，经来少腹滞痛、周身经络牵掣，皆木气下陷、营络窒滞所致。原文以「肝主血」「肝主经」立论，脉虚软带弦正合肝虚气陷、营络不和，故以和肝为主，佐温通营络。", ["虚", "软", "弦"]], "10560": ["病机", "原文未出脉名，以“肝木郁结，下陷于奇脉”立论。肝气郁而不达，反陷于冲任等奇经，致经行时少腹撑痛、小便不爽，是气郁下陷、奇经失和之病机。治法清泄木火、通调奇经，正针对郁结化火与奇脉阻滞，故本条主旨为病机而非凭脉断病。", []], "10561": ["病机", "重身六月而胎漏，右脉浮数。浮为邪在表、气机上浮，数为热，右脉候气分，浮数相合示胎元受热扰而受伤，故腰腹坠痛。原文“以右脉论，当兼凉胎为是”，说明此浮数非单纯外感，而是胎热内动、胎元不固之病机，故以凉胎为治。", ["浮", "数"]], "10562": ["预后", "产后发热咳嗽、色黄盗汗，脉虚细而数。虚细为阴血亏耗、正气不足，数为虚热内扰，合之产后邪恋致虚，正不胜邪。原文断为“将及蓐损之候”，即虚劳损怯之渐，故本条主旨属预后判断：脉虚细数示阴亏热恋，病情有转蓐损之势。", ["虚", "细", "数"]], "10563": ["病机", "产后感邪，咳逆气促、音破，肺气不能疏通，浊痰阻窒，脉细不畅。细为气血不足、脉道不充，不畅示痰浊壅阻、气机不利。脉细不畅正合“浊痰阻窒”之实中夹虚，故以疏化泄邪为治，本条重在阐明痰阻气窒、肺失宣通之病机。", ["细"]], "10564": ["病机", "原文仅言“脉不和”，未出具体脉名。少腹响痛由下而上、形寒内热，起于产后，断为寒气袭于下焦、营分阻窒、奇脉不和，兼大解滞痛涉及肠腑。脉不和即营气阻滞、奇经失谐之反映，故以温通营气为主，本条主旨为病机分析。", []], "10565": ["病机", "原文未识脉名，述小产后瘀血未净，寒气窒于奇经，少腹撑痛，近增寒热。瘀血与寒气交阻奇脉，营气不畅，故撑痛；寒热并见示营卫失和。治法畅气和营、通调奇脉，正对瘀寒窒塞奇经之病机，本条属病机论述而非凭脉主病。", []], "10566": ["病机", "脘腹久痛不愈，面黄脉弱，舌嫩红。弱脉主气血不足、脾气虚弱，久痛则脾运不舒，湿积交阻。原文谓“不特脾阳受困，而胃阴亦伤”，脉弱正应脾阳困顿、中气不足，舌嫩红则示胃阴受伤，故调治颇难，本条重在阐发脾阳胃阴两伤、湿积交阻之病机。", ["弱"]], "10567": ["病机", "脉象弦搏，右手较硬。弦为肝脉，搏硬示肝阳亢盛、气机劲急，右手较硬则木旺侮及肺胃。肝阳内动之气厥而不和，故四肢时冷、夜寐不安。原文以“潜肝和阳，兼清肺胃”为治，说明弦搏硬脉主肝阳内动、厥气不和之病机。", ["弦", "硬"]], "10568": ["病机", "左脉弦数，弦主肝郁气滞，数主邪热内扰。原文谓“经络瘀阻，营气壅窒”，故少腹酸痛牵引腰脐腿足；又见“寒热绞闷，恶心头痛”，乃肝气与时邪同时挟发，脉弦数正合肝郁化热、邪正交争之象，病机错杂，故用药殊难。", ["弦", "数"]], "10569": ["病机", "脉细弦右浮，细为阴伤，弦主肝郁，浮示余邪外扰。原文谓“余邪内伏，肝火上浮”，痛由左胁及脘，掣及胸背，上引太阳，乃肝火循经上逆、饮邪内伏之象。弦细为肝郁饮停，右浮为余邪未清，故当蠲饮泄木两法并用。", ["细", "弦", "浮"]], "10570": ["病机", "脉虚细而数，右手尤甚，虚细为气阴两亏，数为邪热内炽。原文谓“邪由肺俞袭入骨节”，故心痛彻背、脊骨外凸、痛连两胁、咳嗽；近日胸脘刺痛，乃络气不通。正虚邪痼，脉症相符，故不易得效，先与和络肃肺。", ["虚", "细", "数"]], "10571": ["病机", "脉数恶热，数为热盛，恶热为阳热外蒸。原文谓“肝火乘脾”，故咯血胁痛、项下有核、咽痛便溏；火乘脾土，脾求助于食而能食，然不能胜则痞。脉数正合肝火内炽，治在制肝益脾，以平木扶土。", ["数"]], "10572": ["预后", "脉弱而数，弱为根本虚衰，数为虚热内扰。原文谓“肝藏失调，侵脾则腹痛，侮肺则干咳”，病从内生，非外感客邪。形瘦色槁、上热下寒，根本已漓，脉弱数正示脏气内亏、虚阳上浮，故恐难全愈，宜内和藏气。", ["弱", "数"]], "10573": ["病机", "原文未识脉名，然“形盛脉充，两尺独虚”已明言尺脉虚。两尺候肾，独虚则根本不足；下体麻痹、火浮气急，乃肾虚不摄、虚阳上浮之象。形盛脉充为枝叶虽盛，两尺独虚为根本不固，故未足恃也。", []], "10574": ["治法", "此段为诒按，未出脉象，然承上段“两尺独虚”而言。脉症合参，似可参用肾气法以温摄之。肾气丸温补肾阳、摄纳浮火，正合下体麻痹、火浮气急之根本虚衰、虚阳上浮病机，故为温摄之法。", []], "10575": ["病机", "原文谓“阳脉则缓，阴脉则急”，阳脉缓为阳气弛纵，阴脉急为阴血拘急。类中偏左，指节能屈不能伸，乃阴急阳缓、筋脉失养所致。经云“肝苦急，宜食甘以缓之”，故于前方增进阴药之甘润者，以缓其急。", ["缓", "急"]], "10576": ["病机", "脉虚为气血不足，涩为血行滞涩，虚涩并见，说明气血两亏、运行不畅。左半手足麻痹、食不知味，正是气血不能周流肢体、濡养脾胃所致，故断为类中之渐，强调虚涩之脉反映本虚络滞的病机。", ["虚", "涩"]], "10577": ["病机", "脉浮数动，浮为阳浮于外，数为热，动为阳动不宁，合齿疼舌赤、精浊，显系肝肾两虚、水不涵木、肝风暴动之象。虽纳谷如昔，卒然右偏肢痿、舌强口㖞语謇，脉症相参，正合河间肝肾气厥、舌喑足痱之论。", ["浮", "数", "动"]], "10578": ["其他", "此段为诒按，言古法化裁、参详脉症、斟酌尽善，属医论评述，非具体脉象主病。原文未出脉名，仅强调临证须脉症合参、灵活化裁，故脉象要素为空，主旨归于其他。", []], "10579": ["病机", "脉濡为湿，按之则弦为肝风内动，濡弦并见，正合脾饮肝风相合为病。右肩及手指麻木、两腿酸痒难以名状，乃饮湿阻络、肝风窜扰所致，故断为类中之渐，提示濡弦之脉反映脾虚饮停、肝风暗动之机。", ["濡", "弦"]], "10580": ["病机", "脉虚为阴气不足，数为湿热内蕴，虚数并见，说明湿热乘阴气之虚而下注。两膝先软后肿、不能屈伸，正是湿热下注膝胫、久则成鹤膝风之候，脉虚数恰反映正虚邪恋、湿热留着之病机。", ["虚", "数"]], "10581": ["病机", "原文言脉不弱数，即脉不弱而反见数象，数主痰火内扰。惊悸易泄、腰疼足软虽似虚象，然脉不弱、形不枯瘁，说明并非真虚，实因痰火为患，故不可遽与补益，脉数为辨痰火之关键。", ["数"]], "10582": ["预后", "脉弱为正气已虚，色悴为气血不荣，而肝风与痰饮相搏、内壅脏腑、外闭窍隧，致不寐不饥、肢体麻痹经年。脉弱色悴示正虚，邪实又须攻，攻则正益虚，故原文叹最为棘手，脉弱在此提示攻补两难之预后。", ["弱"]], "10583": ["病机", "原文以久嗽脉不数、口不干为辨，说明未成损症。脉不数则非阴虚火旺，口不干则非津伤，故知此为肺饮郁伏不达，饮邪内停而非虚损。脉象要素原文仅言不数，无具体脉名可取，主旨辨肺饮之病机。", []], "10584": ["病机", "脉弦而细，弦为邪郁气滞，细为体虚阴血不足，合之即「体虚邪滞」。肺络不清，咳逆由邪滞络脉、肺失清肃所致。幸不数者，数主热盛，今脉不数，说明邪未化热深入，尚可缓图。弦细并见，虚中夹实，治当养正兼疏邪滞，不可纯补纯攻。", ["弦", "细"]], "10585": ["预后", "原文未出具体脉名，仅言「脉象与前无异」，即脉仍如前，无恶化之象。肺病以中气健旺、能食便坚为佳，今喘咳已久而大便易溏、能食难运，是脾运不健、中气不足，本非所宜。然脉象未变，说明病势尚稳，故曰能节饮食、慎寒暖犹可无虞，属预后判断。", []], "10586": ["病机", "久嗽伤肺，便溏伤脾，脉虚为正气不足，数为虚热内扰，故断「脾肺俱病」。脾虚失运则便溏，肺虚气逆则久嗽，虚数之脉正是中气亏虚、阴火上浮之征。治以培补中气为要，若中气不复，后泄不食，则肌肉瘦削日增，预后堪忧。", ["虚", "数"]], "10587": ["病机", "脉细数促，细为精血亏少，数为阴虚内热，促为气机急促不续，故断「肝肾精血内耗」。精亏于下则冲脉气逆，自下及上，气不收纳，故咳吐清涎浊沫、喘而汗出，是「根本先拨」。若见血为热、见咳治肺，则诛伐无过，速其凶矣，明示病本在下焦肝肾。", ["细", "数", "促"]], "10588": ["病机", "脉虚数为阴亏阳浮之象，颧红、声低、晡热、烦躁皆阳浮于上、阴不恋阳之征。咳甚吐食，是下焦不摄、冲气上逆。精液变化痰沫，非实痰可比。病已三年，是为内损，故非消痰治嗽可愈，当固摄下焦、绝欲保精，饮食如故则胃气尚存，经年可望其愈。", ["虚", "数"]], "10589": ["病机", "脉微小为阳气衰微、气血不足之象，形寒是阳不温煦，久嗽失音是肺气馁弱、金失所养，故断「气馁阳损」。声由气发，气馁则音不出；阳损则形寒。治议固胃阳，取甘温之属，以胃为阳气生化之源，培土生金，阳复则气充而音自出。", ["微", "小"]], "10590": ["治法", "本段未出脉名，述复脉甘润法后呛止音出，得益水濡润之力，是甘润养阴之效。然胃弱便溏，甘润滋腻碍脾，故不宜再用。仿金匮麦门冬汤，取养土之阴以生肺金，即培土生金、养胃阴以润肺燥之法，属治法调整，非脉象主病之论。", []], "10591": ["预后", "久咳便溏腹满，脾肺同病，已属难治。脉数主热，合口干潮热，知非独脾肺，肝肾之阴亦不足，阴虚生内热故脉数。脾肺既病于上中，肝肾复亏于下，三焦俱损，故预后不良。原文以「况脉数」进一层，强调数脉示阴亏热炽，病势深重。", ["数"]], "10592": ["病机", "寸关大而尺小，寸关主上焦中焦，尺主下焦肾。寸关大示阳气浮越于上，尺小示下焦阳虚不能潜藏，故见口干、上气不下、足冷不温，正是阳气不潜、上盛下虚之象。治用阴中阳药，引阳归阴，使虚阳得潜。", ["大", "小"]], "10593": ["病机", "脉数减、咳亦缓，是数脉渐退、咳势稍缓，然仍浮气不得全归根本，说明虚阳虽减而未全潜藏，下焦摄纳无力。故宜补益下焦，使气有所归，以为吸受之地，而非徒治其咳。", ["数"]], "10594": ["病机", "脉虚小为正气不足、肾阳虚衰之象。气喘足冷至膝、唇干鼻塞，是下气上逆、虚阳上浮，病在根本。原文戒勿以结痰在项而漫用清克，正恐更伤下焦，故用肾气丸盐花汤送下以温纳肾气。", ["虚", "小"]], "10595": ["病机", "脉小数而吐血因劳怒即发，微呛，是肝心阴血不足、虚火内扰。思虑劳心耗伤阴血，劳怒引动肝心之火，迫血上溢。病在肝心，宜早图之，勿使延及肺家，示当先治未传之脏。", ["小", "数"]], "10596": ["病机", "肝脉独大，失血咳逆、心下痞满、暮则发厥、血色黯、大便黑，是瘀血积留不去、肝血瘀滞之候。血色黯、便黑为瘀血明证，脉独大示瘀阻而脉道壅盛。故勿治其气，宜和其血，使瘀去而血自安。", ["大"]], "10597": ["病机", "寸静尺动，寸主肺而静，尺主肾而动，屡经失血后气从下焦上冲则呛、劳动气促，是病不在肺而在肾，肾阴亏虚不能摄纳，虚气上逆。故治嗽无益，宜滋肾阴以固根本。", ["动"]], "10598": ["病机", "心脉独大，口干易汗、善怒血逆，是心阴不足而心阳独亢。阴不制阳，阳亢则脉大，迫津外泄则汗，迫血上行则逆。故宜犀角地黄汤清心凉血、滋阴制阳。", ["大"]], "10599": ["预后", "劳伤失血、心下痛闷，本非纯阴虚之证，然脉数而咳嗽潮热，数脉主虚火内动，潮热咳嗽示阴液渐耗。原文恐其渐入阴损一途，是警示此脉此症有向阴虚劳损传变之势，当及早图治。", ["数"]], "10600": ["病机", "脉数主阳热有余，与「阴不足而阳有余」相合。肝善逆、肺多郁，气火上逆则气喘咳逆，灼伤血络则见血，胁痛为肝郁气逆之征。数脉在此示阴虚阳亢、气火内动之机，故治宜滋降，静养以制阳，否则血随气逆不已。", ["数"]], "10601": ["兼症", "热渐减而脉数不退，说明余热未清、阴分未复。头中时痛为余热上扰清窍，喉中痰滞不清为热灼津液成痰、痰热阻咽。数脉在此不主新感，而示余邪留恋、阴伤未复之兼症，故仍须清养并进。", ["数"]], "10602": ["病机", "体虽不热而脉仍细数，细为阴血不足，数为阴虚内热。外热已退而脉象未复，说明阴气未充、虚热内伏，故曰「宜养阴气」。此细数脉紧扣原文，示病本在阴亏，不可因体不热而忽视养阴。", ["细", "数"]], "10603": ["病机", "面黧形瘦、咳嗽气促、腰膝无力、大便时溏，合脉虚而数，显系先后天俱虚。虚为气阴不足，数为虚热内扰；脾虚则便溏，肾虚则腰膝无力，肺虚则咳促。故虑其延成虚损，且戒清润治肺之品戕中气，脉虚数正示虚损之机。", ["虚", "数"]], "10604": ["病机", "原文未出脉名，以「络脉空隙」言病机。络虚则气无所附而游行作痛，阴虚阳升之令血随气溢，故虑春末夏初阳气上升之时。此段重在阴虚咳嗽、他脏累肺，治当填精益髓，若清凉则胃伤食减而成虚损，非脉象可拘。", []], "10605": ["病机", "脉来不柔、时自歇止，不柔即失和缓之常，歇止为脉气不续。原文断为肝阳有余、胃阴不足，稠痰浊火扰动壅滞。脉不柔示肝阳偏亢，歇止示胃阴亏而脉道不利。虽目前安和，见微知著，当加意调摄，属治未病之机。", ["缓"]], "10606": ["预后", "四诊大便已通，脉和，为邪去正复、气机通畅之象。脉和即脉来从容有胃气，示病势向愈，故惟宜滋养以善其后。此段以脉和判断预后转归，紧扣「大便通」「脉和」二语，说明攻邪之后当以养正收功。", ["和"]], "10607": ["治法", "下既不通，浊气上逆而为呕，法当疗下；然脉小目陷，小为正气不足，目陷为津气大伤，示中气大伤。若径投通下，恐更伤中气，故先安中止呕，呕定再商。脉小在此主中气大伤，决定先扶正后攻邪的治法次序。", ["小"]], "10608": ["病机", "痛呕后脉本当和缓，反见搏大，是胃气未复而肝木偏亢。搏大者，胃土受克、肝阳上逆之象，故见头运欲呕、胸满不食、神倦欲卧。原文虑其“土𬯎木张，渐致痉厥”，正说明此脉主木旺乘土、肝风内动之机，法当安胃清肝以先事豫防。", ["搏", "大"]], "10609": ["预后", "气郁痰凝阻隔胃脘，食入则噎，脉见涩象。涩为血少气滞、脉道不利，痰气交阻则营血不能畅行，故脉涩。原文直言“脉涩难治”，是因噎膈本属气痰胶结，涩脉又示正气已亏、血行滞涩，攻补两难，故预后不佳。", ["涩"]], "10610": ["病机", "此段承噎膈正方而论加减。食入则噎，肺气先郁，故加郁金、贝母、枇杷叶以宣降。惟脉涩者，涩为营血虚少、脉道不充，故知“正虚”，可加人参以扶正。涩脉在此不主痰滞，而主正气虚弱，与食噎之肺胃气郁相应。", ["涩"]], "10611": ["病机", "脉疾徐不常，即至数忽快忽慢、节律不匀，是胃中气机升降失度之征。食格不下，中气大衰，则脉气不能自持，故疾徐无常。原文以“中气大衰，升降失度”点明病机，此脉主脾胃虚败、气机逆乱，与食格不下之症相应。", ["疾", "徐"]], "10612": ["病机", "中气叠伤，不能健运，故朝食暮吐、完谷不腐。诊得脉虚，是脾胃之气不足；色黑、腰脚少力，则肾亦病矣。脉虚主正气亏虚，原文由脉虚色黑推知“不独胃病，肾亦病”，说明此脉主脾肾两虚、火不暖土之病机。", ["虚"]], "10613": ["病机", "本段未出脉名，而言肝阴素亏、温邪扰之，发为痉病，神昏骱齿、瘛疭不定。病机在肝阴亏虚、筋脉失荣，兼痰热蒙蔽神明。原文“滋养肝阴以荣筋脉，清涤痰热以安神明”，正说明痉病由阴虚邪扰、痰热内闭所致，脉象虽未明言，当从证测之。", []], "10614": ["预后", "热邪伤津耗液，脉道不充，故脉细；津不上承，故口干。原文直言“难治”，是因热盛而津液已伤，细脉示阴液亏耗、正气不足，清热则碍虚，养阴则恋邪，故预后堪虑。此脉主热伤津液、正虚邪恋之病机。", ["细"]], "10615": ["病机", "此按语申明前段存阴泄热为正治，而所云难治，推想正因脉细之故。细脉主阴血亏少、脉道不充，热伤津液则脉细，正虚难以胜邪，故为难治。原文以“脉细之故”点出难治根由，说明细脉在此主津亏正虚之病机。", ["细"]], "10616": ["病机", "舌干脉数，为热盛伤津之象。热邪内隔，汗不得发，故虽发之亦不得；津液亏耗，惟宜甘寒养液以滋化源。待足温而后热退，是阴液渐复、阳气通达之吉兆，说明此脉数主热郁津伤，而非表实可汗之证。", ["数"]], "10617": ["兼症", "风温郁于肺胃，咳而胸满痰多、胁下痛，脉数口干，是风热内郁、肺胃气壅之候。脉数主热，口干为热灼津伤；痰多胸满乃肺失宣降，胁痛为气机郁滞。此段以脉数口干点明风温化热伤津之兼症。", ["数"]], "10618": ["病机", "脉右大，舌黄不渴，呕吐黏痰，神躁语言不清，身热不解，此劳倦内伤更感湿温之邪。右大主气分邪壅，湿温郁蒸则舌黄；不渴、呕黏痰为湿浊内阻；神躁语言不清是湿浊蒙蔽清窍。脉大而症见湿郁，故须防变端。", ["大"]], "10619": ["病机", "脐中时有湿液腥臭，按脉素大，此少阴有湿热也。脉素大主肾间湿热壅盛，湿浊下注则脐中湿液腥臭；六味能除肾间湿热，宜加减用之。此脉大非虚大，乃湿热内蕴之象，故以滋肾清利为治。", ["大"]], "10620": ["预后", "面黑目黄，脉数而微，足寒至膝，皮肤爪甲不仁，其病深入少阴，邪自酒湿及女劳得之。脉数而微，是邪热未清而正气已衰；面黑目黄、足寒至膝、爪甲不仁，皆少阴精血亏败之危候，故脉微主正虚，预后堪忧。", ["数", "微"]], "10621": ["病机", "诒按言寒袭于肾而气上逆，故用温养；胀及腰背者，督阳不用也。鹿茸温通督脉，麝香开泄浊阴，故以为君。此段无脉象描述，主旨阐发寒袭少阴、督阳不用之病机，以温养通阳为法。", []], "10622": ["病机", "脉弦小腹痛，食后胃脘痛上至咽嗌，是肝火乘胃。脉弦主肝郁气滞，肝火横逆犯胃，故痛自少腹上及胃脘咽嗌。宜泄厥阴、和阳明，说明此脉弦主肝病及胃之病机。", ["弦"]], "10623": ["主病", "心腹痛而脉弦，色青，是肝病也。弦为肝脉，色青为肝色，心腹痛由肝气犯心乘脾所致。此段以脉弦色青断为肝病，说明脉弦主肝病，与心腹痛症候相应。", ["弦"]], "10624": ["病机", "脉虚数为营血不足而兼郁热之象。色白不泽，营血不荣于面；左胁块大，肝经积滞成形。二便自利示非实热内结，故断为虚中有实、营血不和。虚为本、块为标，故治法补必兼通，不可纯补亦不可峻攻。", ["虚", "数"]], "10625": ["主病", "大腹右侧有形为聚，属六腑病位。脉大者，邪气壅盛于腑，气机不畅，故食入即作胀满。聚而有形、食后胀甚，说明腑气不降、传导失职。脉大主邪实，治在六腑即从通降腑气着眼，与五脏积证之脉沉细者不同。", ["大"]], "10626": ["病机", "脉迟为阳气不振、胃中寒冷之征。胃冷则腐熟无权，故腹胀、恶心少食、泄泻；寒气攻冲，则气攻胸胁。诸症皆由脾胃阳虚、阴寒内盛所致，故治法宜振脾胃之阳，阳复则寒散、运化自复，胀泄可止。", ["迟"]], "10627": ["病机", "脉微迟为阳气衰微、阴寒内盛之象。左胁宿痞、腹渐胀大，是浊阴凝聚上攻；便溏溺少，示阳不化气、水湿不行。微迟之脉正合阳虚阴盛，故断为浊阴上攻，治当通阳，使阳气宣通则阴浊自化，胀满可消。", ["微", "迟"]], "10628": ["病机", "脉弦为肝木偏旺之象，中满为脾胃受克、气机壅滞之征。弦脉见于中满，说明肝气横逆犯脾，木郁土壅，故病在肝脾两脏。此以脉弦定病位在肝、以中满定病位在脾，肝脾同病，治当疏肝运脾。", ["弦"]], "10629": ["病机", "原文未出具体脉名，以脉症合参立论。气结在上、津不运行，遂蒸变浊痰，由无形渐成有形，说明病机由气滞而痰凝。既属轻清可去之实，非胶固阴药所宜，故治法当取轻可去实，忌用滋腻阴药壅遏气机。", []], "10630": ["病机", "寸大尺小，示风火壅盛于上而下元不足。头疼偏左、耳重听、目不明，皆风火上扰清窍之症。寸主上焦，寸大则风火在上；尺小则下虚不能制火。故断为风火在上，姑为清解，以清上焦风火为急。", ["大", "小"]], "10631": ["病机", "脉当迟缓而小促，迟缓为脾肾虚寒之常，小促则示中气衰而脉行不畅。脾肾寒湿下注，故右膝肿痛而色不赤；食少辄呕，中气之衰已甚。病本在中气，故以和养中气为要，中气不复则膝肿难愈，肿痛姑置勿论。", ["缓", "促"]], "10632": ["病机", "原文未出脉名，但言“风冷乘之，脉不得通”，指督脉为风冷所客，阳气不通，故恶寒而痛。背脊为督脉所过，寒性收引，气血凝滞，脉道不利，治宜通阳以散寒。此段重在阐明风冷致督脉不通的病机，非以脉象主病。", []], "10633": ["病机", "脉数主阳升，耳鸣、吐痰、天柱与腰膝酸痛，两足常冷，乃阴亏于下、阳浮于上之象。数脉为阳热，然足冷知非实火，是阴不恋阳，虚阳上越。故病属阴亏阳升，法当填补实下，引火归元。", ["数"]], "10634": ["病机", "原文未出脉名，述少阳经脉循耳外走耳中，经有风火则耳脓而鸣。风火循经上扰，壅滞耳窍，故脓鸣并见。治宜清散，清少阳风火。此段以经络病机为主，非凭脉断证。", []], "10635": ["病机", "形伟体丰而脉得小缓，外似有余，内实不足。小缓为阳气发泄、运化无力之象，水谷不得阳运，酿湿下注为浊病，气坠。此非少壮阴火自灼，乃中阳不运、湿浊下趋，故宜升阳为法。", ["小", "缓"]], "10636": ["病机", "恼怒伤中，湿热乘之，脾气不运，水谷并趋大肠而为泄，腹中微疼，脉窒不和。脉窒示气机壅滞、湿热内阻，中焦升降失司。治在中焦，以调气运脾、清化湿热为要。", []], "10637": ["其他", "此段为案语按注，言“案中脉窒句不甚明了”，属对前案脉象描述的存疑说明，非独立脉诊条文，故无脉象要素可录，亦不主具体病机。", []], "10638": ["病机", "气郁不行，津枯不泽，饮食少，大便难，形瘦脉涩。涩脉主气滞血少、津枯不润，脉道不利。此非实积可下，乃液亏气郁，故未可概与通下，宜养液顺气之剂。", ["涩"]], "10639": ["病机", "下血后大便燥闭，继而自利白滑胶黏，日数十行，形衰脉沉。沉脉主里，形衰脉沉示久伏水谷之湿内蕴，府病宜通，以温下法。此湿滞下焦，非虚寒单纯温补所宜。", ["沉"]], "10640": ["主病", "脉小而数，形瘦，大便下血数年，鼻痒心辣。小为阴血不足，数为热，血虚生热，热迫大肠则下血；鼻痒心辣为热扰心肺。脉症合参，主阴血亏虚、肠热下血之病机。", ["小", "数"]], "10641": ["病机", "脉虚细数，原文明言“阴不足也”，鼠漏未愈，热在大肠。虚细为阴血亏虚，数为阴虚内热。阴亏则脉道不充，故虚细；虚热内扰，故数。主肝肾阴亏、虚热客于大肠之病机。", ["虚", "细", "数"]], "10642": ["预后", "诒按指出肛门漏名为鼠漏，脉症已属损象，故以滋补肝肾为主。虽未出具体脉名，但“脉症已属损象”提示脉现虚损之象，主病机为肝肾亏虚、正气耗损，预后不佳，故治以滋补。", []], "10643": ["病机", "胎前子肿，产后大泄，泄已一笑而厥，厥回后左胁痛满，形瘦脉虚，食少少腹满足肿小便不利。脉虚为脾病传心、心不受邪传肝、肝病传脾之五藏相贼，脾虚失运，肝气横逆，故攻补无效，宜泄肝和脾。", ["虚"]], "10644": ["其他", "此段为同龢追忆其母欧血谒曹先生事，先生切脉问其曾否坠下、努力，未录具体脉象。从脉测因，知欧血由坠仆努力伤腰膂所致，属外伤络损、血溢脉外之病机，非内伤虚损。", []], "10645": ["病机", "心营与肾水交亏，肝气挟肝阳上逆，胸中气塞，口内常干，手震舌掉，心烦不寐，便溏纳少，脉形细小无神而有歇止。细小无神为气血两亏，歇止为脏气衰微、神不守舍，主心肾肝脾俱虚、魂魄不安之病机。", ["细", "小"]], "10646": ["兼症", "再诊脉之歇止向和，便溏不作，气塞稍平，手震亦定，但寤多寐少，胸痞脘闷，浊痰未降。脉歇止向和示脏气渐复，然痰浊上壅、魂魄未安，故仍从通阳镇逆、参入前方为治，属兼症调治之段。", []], "10647": ["病机", "三诊夜半得寐，心肾已交，但心易烦动，神疲气短，胸痞，脉仍细小，两足不安，脉虚症虚，是谓重虚，兼湿痰为患。细小虚为气血阴阳俱亏，重虚之候，痰为有形之火，故法当固本为主、消痰佐之。", ["细", "小", "虚"]], "10648": ["病机", "脉息细小带弦，细为气血两亏，小属气弱，弦则肝经有余之象。原文谓风火痰留滞肝经，卧血归肝而魂不能俱归，故筋惕肉𥆧；又起于有年病后，气血亏虚，脉虽无止歇之形，然弦细不静，正示肝邪未靖、风波难免，未可以能食为恃。", ["细", "小", "弦"]], "10649": ["病机", "原文未明言脉名，仅谓脉亦随之变异。少寐在子时后，知肝胆余邪未清；痰火阻气，气逆时面赤心悸、肉𥆧筋惕、烦热不安，脉随气逆而变，正是心火一动、相火随之之机，故调治之外须静养以凝心火。", []], "10650": ["病机", "本段未载脉象，以寐寤非时论病机。心阳太旺，神气外驰，卫气独行于阳，阳跷脉满则不入于阴，故寤多寐少；阴分之虚由此可知，故拟于前方参入滋阴之品，使阳有所恋而渐复。", []], "10651": ["其他", "此系诒按评语，非论脉。指出前案不寐乃肝胆痰火所致，而引内经阳跷脉满之文属强为牵合；又以经言阴虚指为阴血之虚，尤非经文本旨。全段旨在辨正前人引经之误，故归其他。", []], "10652": ["病机", "本段未出脉象，以眠食论病机。寐醒不宁，昭卫气不得入阴而独留行阳，阳跷脉满，营血不能充肌肉；营血既不生之于心，乌能藏之于肝、统之于脾。兼痰火易烦、虚风内动、筋惕肉𥆧、便难，故叹草木难为力。", []], "10653": ["病机", "脉形细小而兼滑数，原文自解：数为有火，滑为有痰，细属阴虚，小属气弱。虚弱之中兼痰火，故有时面红咳嗽、气痞而短、烦热不安，兼便燥溺短、筋惕肉𥆧、肢体动摇、神倦语弱，诸症未平，虽彻夜好眠亦须谨慎。", ["细", "小", "滑", "数"]], "10654": ["预后", "脉数而身热，阳络重伤，咳无虚日而五更为甚，口干盗汗、溺赤便溏，一派阴亏火旺之象。脉数主热，身热不退则阴液日耗，原文断为欲成损症；咽中已痛，虑其加喘生变，故权以清热存阴，属预后警示之论。", ["数"]], "10655": ["病机", "溏泄已止而咳嗽未除，咽痛盗汗仍在，脉数则肺经尚有热邪未清。数脉主热，热邪恋肺故咳不止、咽痛；热迫津泄则盗汗。泄止示脾运渐复，而肺热未解，故仍当清肺为治，属病机未罢之候。", ["数"]], "10656": ["病机", "脉小带数，小为气阴两亏，数为风热递减之余热未清。原文谓“风热递减。气阴两亏”，又见“咳嗽腹鸣。神疲纳少”，乃脾虚湿困之象。脉小示正气不足，数示余邪未净，故病机为气阴两亏、脾湿内蕴，属虚实夹杂之候。", ["小", "数"]], "10657": ["病机", "脉弱无力，为元气虚衰之征。原文列脾虚便溏、肺虚咳嗽、肾虚虚火上炎咽干痛，三脏俱虚，脉弱无力正合“元气伤矣”。弱脉主气血不足，无力鼓动，故急宜补气育阴，以复元气。", ["弱"]], "10658": ["病机", "原文未出脉名，然述“湿热禀于先天者，与元气混为一家”，又“阴精内耗”“风火相煽”致耳鸣头晕面赤。病机为先天湿热挟阴虚，肝经之火与督脉之阳上冒。脉象虽缺，据症当见弦数或细数，主湿热伤阴、风火升腾之候。", []], "10659": ["病机", "脉濡主湿、主脾虚。原文“身热。手心热。少力神倦。澼利脉濡”，乃脾阳下陷，阴火上乘。濡脉示湿困中焦、阳气不振，故见便溏、身热、神倦。甘温除热法正为此脾阳下陷、阴火上升之证而设。", ["濡"]], "10660": ["病机", "右脉濡小，左脉浮弦。濡小主脾虚湿困，浮弦主风邪外袭。原文“劳倦而招风湿”，见舌苔薄白、溺赤便溏、肢体酸楚、神倦嗜卧、少纳口干，乃劳倦伤脾、风湿外袭、脾失健运之病机。", ["濡", "小", "浮", "弦"]], "10661": ["病机", "脉形软弱，为脾虚营卫不足之象。原文“肌肉暗消”“脘痞纳少。力乏嗜卧”，皆脾虚见症。脾主肌肉，营卫不调则肌肉消，脉软弱正昭脾之营卫虚。八八已过，阳气必衰，故当健脾兼壮元阳。", ["软", "弱"]], "10662": ["病机", "心脉宜大反小，肾脉宜沉反浮。浮则为伤，小则为虚。原文谓“读书攻苦。心肾不交。失其封藏之职”，心火不能下交，肾水不能上济，故脉失其常。病机为心肾不交、封藏失职，治当补中宫以媒合心肾。", ["大", "小", "沉", "浮"]], "10663": ["病机", "脉从内变而为细弦。细主阴虚，弦主饮邪。原文“阳虚则恶寒于日，阴虚则发热于夜”，疟后余邪未清，脾不运化，生饮生痰，肺咳足浮腹满。形瘦色黄舌白，阳分更亏，极易致喘。病机为阴阳两虚、饮痰内停。", ["细", "弦"]], "10664": ["病机", "尺脉无力、阴阳并弱，是肾中阴阳两虚、下元不固之象。足不任身、手难举物，正因肾主骨、肝主筋，下虚则筋骨失养、肢体无力。此为类中之余，标症虽在肢体，本在阴阳并弱，故拟河间地黄饮子法，从补肾填精、阴阳双补立法，非祛风通络所能治。", ["虚", "弱"]], "10665": ["病机", "脉息迟弦，迟为阳虚、弦主痰饮气逆。怒则气上、痰随气升，故语言謇涩、口角流涎；小水甚多、肢麻无力，皆阳虚不能温运之征。原文明言痰气为标、阳虚为本，脉迟弦正合本虚标实之机，故法宜扶阳为主、运中化痰佐之，非单纯治痰可解。", ["迟", "弦"]], "10666": ["病机", "脉形弦迟，迟属中阳不足，弦主风痰内动。中虚湿胜之体，湿聚生痰、痰动风生，故见左肢痿而不用、口歪流涎、舌苔起腻、便溏溺少。内风既动则招外风，原文点明中虚湿胜为本、痰风为标，脉弦迟正示虚寒夹痰风之机，治当温中化湿、息风化痰。", ["弦", "迟"]], "10667": ["病机", "脉形细小，是日久正虚、气血不足；左关独见弦数，为风寒湿三气渐化热之象。膝骨日大、上下渐细，乃鹤膝风重症；腰脊突出、肌肉暗削、行步无力，皆正虚之征。三气痹阻日久化热，故脉细小中独见弦数，拟羚羊角散加减，扶正与清热通痹并施。", ["细", "小", "弦", "数"]], "10668": ["病机", "脉形小滑，小为正气不足，滑主痰涎内盛。神识不清、自言自语、起坐无常、寤寐失度，是痰热内郁心包、无路可出而作心风；舌苔白腻亦痰湿之征。脉小滑正合正虚痰郁之机，原文谓久久归入癫痫，故当及早化痰清心、开郁透邪，不可忽视。", ["小", "滑"]], "10669": ["病机", "脉弦滑数，弦属肝火冲激，滑主痰涎，数则为热。唇起红筋、牵动而厥、厥醒吐沫、咳血鼻衄、二便失调，显系胃有积热、动血生痰，又被肝火冲激所致。阳明之脉环唇，故症见于唇口。脉弦滑数正合胃热肝火夹痰之机，为痫症之根，不可忽视。", ["弦", "滑", "数"]], "10670": ["病机", "脉芤带滑，芤主心血本虚、阴血不足，滑主痰涎内袭。心悸初从惊恐得之，经年不愈，手振舌糙、不耐烦劳，皆心血亏虚之征；痰涎乘虚袭入心包，故脉见滑。此虚中夹痰之候，原文明言心血本虚、痰涎袭入，治当养心安神兼化痰，不可纯补或纯攻。", ["芤", "滑"]], "10671": ["病机", "左寸脉息上浮，关部独带弦数，右寸与关小而带弦，是脾经湿痰被肝火冲激、上累心包之象。神蒙善忘为包络受病，白苔满布、大便久溏、肢体无力、倦怠嗜卧，皆脾湿内盛之征。脉浮弦数示肝火冲激，小则正虚，合湿痰肝火扰心之机。", ["浮", "弦", "数", "小"]], "10672": ["病机", "脉滑主痰，数主热。曾失血则阴亏，阴虚生内热，灼津为痰，故内热吐痰；夜来大魇亦因痰热扰及心神。滑数并见，正合阴虚挟痰之机，非单纯实热，亦非纯虚，乃虚中挟实之候。", ["滑", "数"]], "10673": ["病机", "脉细弦，细为阴血不足，弦为气机不畅。鼻血遗精、寒热盗汗，肺肾俱病、营卫并伤，本属虚损；然舌苔满布、二便失调、饮食不舒，又见脾湿痰患。细弦之脉应虚，而苔满便失调则实，故先化湿健脾，再商补剂。", ["细", "弦"]], "10674": ["病机", "中部太弦，关脉候脾胃。弦为气机郁滞、痰饮内阻。动则气喘、言则亦然，虽属下虚，然脘中拒按、隐隐作疼、筑筑而跳，显系湿热痰浊交阻于胃，失下行为顺之常。脉弦与拒按疼跳相应，故未便独以虚治。", ["弦"]], "10675": ["病机", "年逾古稀，肾气下虚，生痰犯肺而咳喘。脉微为阳气衰微之象，正合肾虚不纳、痰饮上泛之机。微脉主虚，此处非外邪实喘，乃本虚标实，故当与峻补，补火生土以绝生痰之源。", ["微"]], "10676": ["治法", "脉散为气耗不收、肺肾两虚之象。金水六君煎治脾肾，生脉散养肺，加桃肉补命门，皆针对脉散所主之虚损。散脉提示元气涣散，故用峻补固摄之法，使金水相生、命火归元，则咳喘自宁。", ["散"]], "10677": ["病机", "原注补命门之火以生土，清其生痰之原，则肺之咳喘自宁。此段虽未出脉，然承前脉散之虚，说明病本在命门火衰、土不生金。金水六君煎治脾肾，生脉养肺，桃肉补命门，丸药常服以奠安下焦，皆从虚损病机立法。", []], "10678": ["病机", "右脉濡数，濡主湿、数主热，为湿热内蕴；左脉浮弦，浮为风邪、弦为肝旺。交冬咳嗽延及夏间，跗肿腹满、口燥舌剥、火升气逆，显系风邪湿热由上及下、由下及中，三焦受之。脉与咳而腹满之三焦咳相应，故用药棘手。", ["濡", "数", "浮", "弦"]], "10679": ["病机", "脉数主热。寒热后咳嗽痰浓、头疼口渴、舌红，皆冬温之邪郁于肺分，从燥化热之象；大便溏泄则热邪下迫。数脉与舌红口渴相应，说明邪已化燥化热，故当泄之清之，非虚寒咳喘可比。", ["数"]], "10680": ["病机", "脉紧为寒，数则为热，寒邪伤营化热，故见咳嗽、呕吐紫血、咽干痛。苔白边青示表寒未罢，紧数并见说明寒郁化热、肺胃失降，病机为寒热错杂、郁咳成劳。", ["紧", "数"]], "10681": ["病机", "左关浮弦且数，浮为风邪在表，弦主肝木偏亢，数为热象。伤风不醒，咳嗽呕恶、痰带血色、小有寒热，乃风邪入肝犯肺，木火刑金，为损症之根。", ["浮", "弦", "数"]], "10682": ["病机", "脉弦细数，弦为风邪未尽，细为阴血不足，数为余热未清。咳嗽大减而痰仍青黄、身热虽轻、咽中苦痛，示风邪留恋、中下两虚，虚热上灼咽喉。", ["弦", "细", "数"]], "10683": ["病机", "左关脉息弦硬不和，弦主肝郁，硬为邪结。咳嗽大减、红痰已无，但痰色青黄，示肝胆留邪未净，木郁化火，容易犯肺胃，故须防其传变。", ["弦", "硬"]], "10684": ["病机", "右脉弦滑而数，滑主痰，弦主风，数主热。风郁为热，热郁为痰，痰热阻肺，清肃不行，故咳嗽自作。脉象直接反映风、热、痰交阻之病机。", ["弦", "滑", "数"]], "10685": ["病机", "脉息细弦而紧，细为脾虚，弦为湿郁，紧则为寒。劳倦伤脾，积湿生痰，久则金水两虚；今身热口干苔白，紧脉示寒风新感，故先治新邪，权以疏化。", ["细", "弦", "紧"]], "10686": ["预后", "原文未识脉名，仅言“脉未促”，强调不可因脉未促、气未喘而轻视。火逆上气、咽喉不利，最易成劳，示病机为火郁上焦，虽脉未促亦当防其成劳。", []], "10687": ["病机", "右寸浮弦，浮主肺气不降，弦主痰饮。肺虚不能通调水道，聚液为痰、积湿为饮，诵读烦劳则咳嗽发作。脉象示痰饮阻肺，病机为肺脾两虚、痰湿内生。", ["浮", "弦"]], "10688": ["主病", "原文以“左脉浮弦”起，继言“感寒者恶寒体痛发热脉紧”，浮主表、弦主风、紧主寒，故脉象揭示外感风寒之邪束于肌表。浮弦为风邪伤卫之征，紧为寒邪收引之象，与恶寒、体痛、发热相应。后文分述四季风邪伤及不同脏腑，皆由此风寒外袭之基本病机展开。", ["浮", "弦", "紧"]], "10689": ["病机", "本段未识脉名，以“咳血、梦遗、畏火”三症立论。原文谓“天符之火行于夏时”，外火引动痰火，肺金久伤失于清肃下降，则不能生肾水，肾水不生则相火上炎，故咳逆梦遗。又引《内经》阳明脉解篇，谓畏火乃“肝火乘胃”。全段重在阐发火淫伤肺、金水不交、肝胃火乘之病机链。", []], "10690": ["病机", "原文言“脉形滑数，独见肺胃两部”，滑主痰湿，数主热，见于肺胃，正合“肝经湿热之邪大半归于阳明”而“逆克于肺者犹未尽平”。湿热酿痰，故吐青黄绿痰或带血点；右胁隐痛为肝经余邪。脉象揭示湿热痰浊壅于肺胃、木火刑金之病机。", ["滑", "数"]], "10691": ["病机", "原文引“脉数虚者为肺痿”之训，左寸脉数而小，正合肺虚有热、津伤成痿之机，故咳臭痰络血、难卧、便结。右关独大独弦独滑且数疾，则示阳明胃经湿生痰、痰生热，熏蒸于肺，母病及子。一虚一实并见，点明肺虚胃实、虚实夹杂之病机。", ["数", "小", "虚", "大"]], "10692": ["预后", "原文“诸恙向安，右脉亦缓”，缓为胃气调和、病退之象。前诊脉数疾弦滑，今右脉转缓，说明药已应手，湿热渐化，胃气来复。故曰“药能应手，何其速也”，并嘱“再守之，观其动静”，此段以脉缓判断向愈之预后。", ["缓"]], "10693": ["病机", "原文谓“右关之大脉已除，弦滑未化，数之一字与寸相同”，大脉去而弦滑数仍在，说明湿热痰三者尚有熏蒸之意。弦主痰饮、滑主湿痰、数主热，右关应脾胃，寸应肺，故知胃中湿热痰浊上蒸于肺，肺气难以自振，病机未全解。", ["大", "弦", "滑", "数"]], "10694": ["病机", "原文“脉数，右寸空大，阴气必虚”，数主热，空大主阴血不足、脉道不充，右寸应肺，故断肺阴亏虚。又言肺虚易招风，偶咳加剧。然阳明胃经湿热熏蒸之气仍在，故治法“养阴为主”而“兼理”胃中湿热，示肺虚与胃实并存之病机。", ["数", "大", "空"]], "10695": ["病机", "原文“右脉小中带数”，小主阴血不足，数主热，右脉应肺，故断“肺阴不足，肺热有余”。然原文紧接“其所以致此者，仍由胃中之湿热熏蒸也”，说明肺之阴虚热余源于胃中湿热上蒸，病本在胃，病标在肺，揭示土病及金之病机。", ["小", "数"]], "10696": ["病机", "脉来芤数，芤主失血，数主热。原文述昨日溢血盈盆成块，今仍上吐、火升颧红、咳逆、便黑，显系阳明胃府伏热未清，热迫血溢，血去阴伤则脉芤，热盛则脉数。故脉象提示伏热内炽、血络再伤之机，防其再冒再厥。", ["芤", "数"]], "10697": ["病机", "脉数左弦，数主火盛，左弦应肝。久嗽失血鲜而且多，苔黄心𩠎，乃金受火刑、木寡于畏，肝火亢盛无制，灼伤阳络而血外溢。弦为肝旺之象，数为火迫之征，故脉示肝火刑金、阳络被伤之病机，防冒。", ["数", "弦"]], "10698": ["病机", "脉形弦数，弦主郁、数主热。阳络频伤、胸前窒塞、咳逆不爽、舌红苔黄，皆瘀血内阻、郁而化热之候。瘀阻则气机不畅而脉弦，郁热内蒸则脉数，肺胃受伤，极易成损，故脉象示瘀热内郁、肺胃受损之病机。", ["弦", "数"]], "10699": ["病机", "脉细主阴血亏虚。痧后咳嗽四月、颈旁疬串、咳甚则呕、纳少形瘦、肤热，乃余邪内恋、阴分大虚之象。阴血不足则脉道不充而细，正虚邪恋，久延欲成损症，故脉细示阴分大虚、余邪未清之病机。", ["细"]], "10700": ["病机", "脉弦带数，弦主肝旺，数主热。温邪发痧后咳嗽失血、痰黄白稠稀不一、舌深红苔满白、喉痒嗌干，乃温邪余热未清，肝火偏亢，金受其刑，阴液暗耗。弦为肝火，数为热炽，故脉示肝胆火旺、肺金受刑、阴分渐亏之病机，渐作痧劳。", ["弦", "数"]], "10701": ["病机", "脉形弦数，弦应肝胆，数主火。子后咳嗽、天明而缓、声音不扬，乃肝胆之火未清，木火刑金，金伤则水必暗亏。弦为肝火亢盛之象，数为火热内迫之征，故脉示肝胆火旺、肺金受刑、阴水暗亏之病机。", ["弦", "数"]], "10702": ["病机", "脉浮促而数，浮主表、促数主热。咳嗽失血、音烁咽干为肺阴久伤，近增寒热头痛喉疼，乃燥气外袭。浮为邪在表，促数为燥热内迫，故脉示肺阴久伤、燥气加临、表邪未解之病机，治当补肺中参辛散。", ["浮", "促", "数"]], "10703": ["病机", "脉芤数，左关独弦。芤主失血，数主热，左关弦应肝火。阳络频伤后咳嗽痰浓、内热嗌干，乃肝火刑金、金气不清之候。芤为血去阴伤，数为火盛，弦为肝旺，故脉示肝火刑金、阴血受损之病机，容易成损。", ["芤", "数", "弦"]], "10704": ["病机", "脉数主火，左关弦急为肝火亢盛之象。失血后阴血已亏，肝火内炽，上刑肺金则咳嗽，下泄肾气则梦遗。原文明言“必有肝火在里，既犯肺金，又泄肾气”，指出火旺阴亏、肺肾两伤，久延势必成劳。", ["数", "弦", "急"]], "10705": ["病机", "脉数左弦，唇干苔白、色滞溺黄、咽痛，皆阴亏火旺之征。原文谓“水不涵木，阴火上冲，胃气不清”，肾水不足则肝木失养，阴火循经上灼，故咽痛久不愈；火扰胃腑则苔白溺黄。势欲成劳，静养以冀脉不促、气不喘。", ["数", "弦"]], "10706": ["预后", "浊痰虽少而咳逆仍然，知阴火未平。原文虑“脉促气喘”，因肺金受火刑，水之生源将绝。脉促为真元衰惫、气不接续之危候，与气喘并见，示肺肾气竭，故属预后不良，劝人静养以延。", ["促"]], "10707": ["病机", "脉数左弦，咽痛，原注指为“水不涵木，阴火上冲”，肾阴亏虚不能涵养肝木，阴火循经上炎。苔白为胃气不清之症，头绪虽繁，总属阴虚火旺、木火刑金、胃气失和之病机。", ["数", "弦"]], "10708": ["预后", "脉形细数，细属阴亏，数为有火。原文谓“火上刑金，水即绝其生源”，阴亏火旺灼肺，肾水之源将竭。幸气息未喘、脉象未促，尚非危候，静养可图保全，故列预后，示人勿以咳嗽小恙视之。", ["细", "数"]], "10709": ["病机", "右脉弦滑主痰饮内聚，左关坚急为肝气郁结，寸部独小示心气不伸。原文断为“心气下郁于肝经，脾弱生痰为膈”，肝郁乘脾，脾弱生痰，痰气交阻胸膈，故食则右胁下痛、痰升得吐而安。", ["弦", "滑", "急", "小"]], "10710": ["病机", "脉象弦滑，弦主气结，滑主痰浊。舌苔满白、胸前常闷、食则噎痛，皆痰浊内阻之征。原文谓“阳气又结，阴液与痰浊交阻上焦，胃脘狭窄”，阴血本亏之人，痰气交阻，久则防膈。", ["弦", "滑"]], "10711": ["病机", "脉形细涩，细为阴血不足，涩为血行不畅。得食而噎、胸前隐隐作痛，原文断为“瘀血内阻，胃络不通”，瘀血阻滞胃络，气机不通，故噎痛并见，此膈症之根，属瘀血内结之病机。", ["细", "涩"]], "10712": ["其他", "原文为诒按，未直接描述脉象，仅言“脉症均合”，强调瘀血膈的脉症与病机相符。瘀血膈以瘀血阻于胸膈为主，脉当见涩或弦等，但此段未出具体脉名，故脉象要素为空。所主病机为瘀血内阻膈间，属血瘀实证，与呕吐、食痛等症相应。", []], "10713": ["病机", "右脉涩数，涩主瘀血，数主痰热，瘀血挟痰阻于胸膈，故食则作痛、痛则呕吐；左关独大且弦，左关候肝，大弦为肝经气火亢盛。痰瘀之外更有肝火冲逆，故为膈症重候。脉症合参，病机为痰瘀交阻、肝火犯膈。", ["涩", "数", "大", "弦"]], "10714": ["病机", "脉弦苔白，弦为肝脉，主气逆；苔白、便溏溺清为湿痰内胜之征。食已即吐，乃湿痰内蕴，被肝经淫气冲逆所致。肝气犯胃，胃失和降，故脉弦而苔白。病机为湿痰内胜、肝气冲逆，主呕吐。", ["弦"]], "10715": ["病机", "脉迟为阳气不足，鼓动无力；舌白、少纳多胀，皆脾阳不振、湿浊内停之象。脾阳不足则运化失职，湿浊有余则气机壅滞，故见少纳多胀。脉迟与舌白相应，病机为脾阳不足、湿浊内困，主纳少腹胀。", ["迟"]], "10716": ["病机", "脉形细涩，细为阴血不足，涩为瘀血内阻。胸痛彻背、得食梗痛、便坚且黑、紫血上吐，皆瘀血交阻膈间之征；口燥不欲饮亦瘀血内停、津不上承。痰浊与瘀血交阻，胸阳不旷，故脉细涩。病机为痰瘀交阻胸膈，主胸痹。", ["细", "涩"]], "10717": ["预后", "脉形细小，细为阴血亏少，小为脉道不利。胸痹久而不化，又值燥气加临，更增咳嗽咽干、痰中带红，显系阴伤燥扰。脉细小与燥伤阴血相应，正虚邪恋，故言“治之不易”，示预后难期。病机为胸痹日久、阴伤燥扰。", ["细", "小"]], "10718": ["病机", "左脉太弦，弦为肝木亢盛之象；右脉不畅，右候脾胃，木乘土位则右脉不畅。痛极而厥，厥发不因痛极而因小便之余，手足牵动、头项强直，乃龙雷之火挟痰涎上升。弦脉主木乘土位而痛，又挟阴火上冲而厥，病机为肝木亢盛、阴火挟痰上逆。", ["弦"]], "10719": ["病机", "再诊厥已全平而痛犹未止，便黑溺黄，右脉反弦。右脉本候脾胃，弦为肝木之象，今右脉反弦，说明诸邪都合于胃，肝木乘土，胃府壅滞。便黑为瘀，溺黄为热，邪合于胃，胃失通降。病机为邪聚于胃、肝木犯土，主痛未止。", ["弦"]], "10720": ["病机", "原文指出“诸邪都合于胃。从右脉之弦看出”，右脉候脾胃，弦脉主邪气郁滞、胃气不和。诸邪合胃，气机壅滞，脉道紧张故见弦。此脉象揭示病机关键在于胃受邪扰，主胃脘痛、胀满等症，与“病机紧要处”相应。", ["弦"]], "10721": ["病机", "脉形细数，细主阴血不足，数主火热内扰。原文谓“肝肾阴虚。气滞火升”，阴虚不能濡养，火升则脉数，气滞络脉不畅故细。此脉主肝肾阴虚、气火升浮之病机，与背部隐疼、腰部亦疼、气逆咳呛等症相应。", ["细", "数"]], "10722": ["病机", "脉形弦细，弦主肝郁气滞，细主阴血亏虚。原文谓“阴虚而挟湿热”，阴虚则脉细，湿热郁滞肝络则脉弦。此脉象说明阴血不足而湿热内蕴，主腰脊疼、咳嗽不止、苔白底红等症，病机为虚实夹杂。", ["弦", "细"]], "10723": ["病机", "脉小左弦，小主脾虚气弱，左弦主肝木郁滞。原文谓“脾气素虚。湿郁难化。而木之郁于内者。更不能伸”，脾虚湿困则脉小，肝郁不达则左弦。此脉主脾虚湿郁、肝木内郁之病机，与酸水酸味、灰白苔、脘胁胀痛相应，为臌胀之根。", ["小", "弦"]], "10724": ["病机", "脉形弦细而数，弦主痛、主肝，细主血虚，数主热。原文谓“血病无疑”“痛后所瘀者”，瘀血内阻则脉弦，血虚则细，瘀久化热则数。此脉说明血瘀兼虚热之病机，与胃脘痛、午后剧、头汗出、便下紫色等症相应。", ["弦", "细", "数"]], "10725": ["病机", "脉弦数，弦主肝、主痛，数主热。原注谓“肝家之血。必有瘀于胃脘者”，肝郁血瘀则脉弦，瘀滞化热则脉数。此脉象说明脾虚气滞兼肝血瘀热之病机，与便紫、胃脘痛得食则缓等症相应，故治当消补兼施。", ["弦", "数"]], "10726": ["病机", "脉形弦数，弦主肝木乘土，数主热。原文谓“寒热错杂之邪。郁于中焦。肝属木。木乘土位”，肝郁化热则脉数，木乘土位、气机逆乱则脉弦。此脉主寒热错杂、肝木犯胃之病机，与胃脘痛、少腹气升、呕吐酸苦痰涎相应。", ["弦", "数"]], "10727": ["病机", "脉形弦数，弦主肝气上逆，数主火热。原文谓“一派火热之象。气从少腹上冲于心。岂非上升之气。自肝而出。中挟相火乎”，肝火挟相火上冲则脉弦数。此脉主肝火冲逆之病机，与胃脘痛、舌绛苔黄、口干苦、小便赤等症相应。", ["弦", "数"]], "10728": ["病机", "脉弦为肝郁气滞，数则化火之征。脘痛下及于脐、旁及于胁，正是肝气横逆、郁而不达之象；口干心悸、便栗溺黄，皆火郁伤津、内扰心神、下迫膀胱所致。弦数并见，说明气郁日久已从火化，故断为郁气化火，非单纯气滞可比。", ["弦", "数"]], "10729": ["病机", "此段以脉数配口干、溺黄为肝有实火之的症。数脉主热，肝火内炽则脉行急迫而数；火灼津液则口干，火移小肠则溺黄。原文强调必肝有实火者方可用化肝煎，正说明数脉在此非虚热，而是实火亢盛之凭据，脉症合参方可攻伐无过。", ["数"]], "10730": ["病机", "脉形细小而数，细小为阴血不足、中气亏虚，数为伏热内蕴。当脐胀痛按之则轻、得食则减，显系中虚作痛而非实积；舌左黄右剥、质深红，左黄为热，右剥为胃阴伤。脉症合观，乃中气虚弱而伏热内藏，虚中挟热之候，故曰中虚伏热使然。", ["细", "小", "数"]], "10731": ["病机", "脉象弦急，弦主肝病，急则拘挛不畅，为寒湿痰浊壅阻肝经之象。少腹久痛、手足挛急而疼，正是肝脉抵少腹、主筋，邪壅于内而外攻经络；舌苔灰浊、面色不华、四肢厥冷，皆寒湿痰凝、阳气不达之征。故以当归四逆汤温经散寒、通阳化滞。", ["弦", "急"]], "10732": ["病机", "右弦左紧俱兼数，弦紧主痛主邪实，数则为热。少腹作痛甚则呕吐、舌苔浊腻、口干苦、头胀溺赤，是湿热之邪内犯肝经，挟痰浊上逆所致。弦紧示邪壅气滞，数示湿热化火，故治以泄之化之，防其湿热痰浊上蒙而致厥逆。", ["弦", "紧", "数"]], "10733": ["病机", "再诊呕吐减、苔稍化、头胀身热缓，而腹痛下利、脉紧数、口干苦、小水短赤未平。紧主寒主痛，数主热，紧数并见正是寒热错杂之脉；肝经之邪未清，又挟食滞痰浊为患，故诸症缠绵。脉象未和，说明邪未尽解，仍须小心调治，不可遽补。", ["紧", "数"]], "10734": ["病机", "此段未出脉名，纯以症测机。肝脉布两胁、抵少腹，两处同时作痛，故断肝病无疑。肝旺必乘脾土，脾失健运则痰浊湿热内生，与肝气相合为患。原文以经络循行定位、以五行乘侮推演病机，说明胁腹同痛之根在肝，而痰浊湿热乃其继发之果。", []], "10735": ["病机", "脉形弦数，弦属肝郁气结，数属火盛。气结于左、自下盘上、胀而且疼、发有形解无迹，是气聚为瘕、聚散无常之象；甚则脉弦数、口舌干燥，正是气有余便是火之见症。脉症相合，说明气结日久化火，故急须化肝以解郁清火。", ["弦", "数"]], "10736": ["病机", "左脉细涩、右部小弱，细涩为血少脉道不充、涩滞不畅，小弱为气衰鼓动无力，合而示气血久虚，营卫失于流行。原文直言“气血久虚，致使营卫失流行之象”，故非攻邪所宜，须“大建其中”以复中气，属虚损病机而非外邪实证。", ["细", "涩", "小", "弱"]], "10737": ["病机", "狐疝本属肝经湿邪随气下陷，脾阳先衰，又因夏月多食冷物，阳气再被遏抑。指冷脉小，小为阳气不振、脉道失充之象，与苔白不干、右睾丸胀大相应，皆寒湿内盛、阳遏不伸之征，故治“当以温散”，以温复脾阳、散寒化湿。", ["小"]], "10738": ["病机", "寒气客于肠外，与血沫相搏，结为脐下瘕块，胀大下坠、痛则气升自汗。脉弦主寒主痛、主气机收引，涩主血行滞涩，弦涩相合正合寒与血沫搏结、气血不畅之机。原文称“此为鼓胀之根”，示瘕积日久可致气滞水停而成胀，故戒“毋忽”。", ["弦", "涩"]], "10739": ["病机", "脉来细而附骨，细为气血不足、脉道不充，附骨沉伏则病位深在里，主积。原文谓“积也，已经半载”，偏于胁下“牢不可破”，乃寒食挟痰阻结气分，日久成形。气行作响而积块不移，正虚邪结并存，故称“每为胀病之根”，提示积久可演为胀。", ["细", "牢"]], "10740": ["病机", "食入而痛，是有积也。脉弦数，弦主气滞、数主热，合二便黄热、干咳不爽、面黄苔白，知湿热痰食互相阻滞，经年累月无路可出。数脉示郁热内蒸，弦示积滞不化，故痛因食入而发；原文强调“无力以消”，示正虚邪实、攻消两难之病机。", ["弦", "数"]], "10741": ["病机", "寒热之后脘左隐癖作疼，脉形弦细，舌苔浊厚。弦主气机郁滞、癖块内结，细主湿浊久蕴、气血不充；苔浊厚为湿热痰食交阻之征。原文断为“湿热痰食，交相为患”，故脉弦细与隐癖作疼相应，示邪结未散而正气已伤，非单纯攻下所宜。", ["弦", "细"]], "10742": ["病机", "脘腹膨胀、二便失调、经络酸痛、四肢无力，脉形弦细，苔白腻而厚。弦主气滞湿阻，细主湿郁正伤，苔白腻厚为湿浊内盛之据。原文断“此湿邪内郁”，湿阻气机则胀、外溢经络则酸痛、困脾则四肢无力，故“当用苦辛宣泄”，以苦燥湿、辛通气。", ["弦", "细"]], "10743": ["预后", "身热时作而脉息弦细，弦为气机郁滞、细为阴血不足，热势时作时止，示邪郁未透而正已渐伤。原文断“极易成臌”，即气滞血涩、水湿渐停，日久可致腹胀之变。此段重在警示转归，故脉弦细与身热并见，当及早调治，防其演为臌病。", ["弦", "细"]], "10744": ["病机", "原文以“脉数多渴”点出火郁作痛之机。数主热，渴因热灼津伤，故脉数多渴并见，说明气、火、湿、食、血五郁之中以火郁为急，热扰中脘则痛发寒热。越鞠丸加姜、连、橘、枣，正是针对无形湿热郁结、火性急迫之病机，非单纯虚寒可比。", ["数"]], "10745": ["病机", "“脉形弦数”与“溺黄口干”并见，弦主气阻，数主热，说明湿热之邪因气机阻滞而壅盛，又因食积而加剧。大腹胀满四十余日、气促足跗浮肿，是湿热壅遏、气机不通、水湿下溢之象，故原文叹“理之不易”，示湿热夹气食交阻之病机复杂。", ["弦", "数"]], "10746": ["病机", "“脉息沉弦”见于经期落后之体，沉主里、弦主气郁，合腹大脐突、胀无虚日、痛又间作，说明血虚不能敛气，气郁于中，寒加于外，脾湿因而不消。舌苔薄白亦示寒湿未化热，故病机重在血虚气郁、寒湿内阻，而非单纯实胀。", ["沉", "弦"]], "10747": ["治法", "本条仅列“生脉散”方名，脉象写作“脉散”。散脉主气耗不收，生脉散以人参、麦冬、五味子敛气生津，正对气阴耗散之机。原文以方代论，提示脉散而见气短、口渴、汗多等症时，当从气阴两伤、脉气不敛论治，非一般实散可比。", ["散"]], "10748": ["病机", "“肤热脉数”而便溏、舌苔冷白、干喜热饮，数脉在此非实热，乃脾阳大虚、虚阳外浮之象。脾阳无力运化湿浊，湿浊内壅而成臌，故大腹胀满；肤热为阳气外越，脉数为虚性代偿。原文断为“脾阳大虚”，示真寒假热、本虚标实之危候。", ["数"]], "10749": ["病机", "“脉弦”与太阴腹满、下体不温、干不欲饮、妨食气短并见，弦主寒饮气郁，说明寒湿有余、真阳不足，脾阳不运则腹满食少，阳不达下则下体不温。干不欲饮、气短更示寒湿内停而非热伤津液，故原文拟温通化湿法，脉弦在此为寒湿内盛、阳气受困之征。", ["弦"]], "10750": ["预后", "“脐平脉迟之候”是臌胀危候，脐平示脾败水溢，脉迟主元阳衰微、阴寒内盛。原文谓“阳之衰也极矣”，虽用温补而浮肿胀满有增无减，下泄更伤肾阳，故断为非温非补不可而温补亦不见长，脉迟在此提示阳气衰败、预后不良。", ["迟"]], "10751": ["病机", "“脉细小”与脘痞纳少、舌白便溏并见，细小主气血不足、阳气衰微，说明中阳不足、寒湿有余，脾失健运则痞满食少，寒湿下注则便溏。原文谓“法当温化，即平为妙”，示脉细小在此为虚寒湿阻之机，治当温运中阳、化散寒湿，不可峻攻。", ["细", "小"]], "10752": ["病机", "脉弦细而数，弦主肝郁，细主脾虚，数主湿热。患者素有隐癖，肝脾不调，血痢后痞结腹胀，溺赤舌黄，显系湿热内聚，脾虚无力运消。脉象揭示肝郁脾虚、湿热壅结之病机，极易成臌，故告诫毋忽。", ["弦", "细", "数"]], "10753": ["病机", "脉弦数大，弦为肝胆，数为热，大为阳明热盛。苔厚中黄，头痛及旁，乃阳明湿热挟胆经风阳上逆。脉象反映湿热内蕴、风阳上扰之病机，主头痛等症。", ["弦", "数", "大"]], "10754": ["病机", "右脉弦滑，弦主肝郁，滑主湿痰。左关沉小带弦为肝气郁而不升，右脉弦滑示湿痰内阻。舌苔薄白、喜饮热汤，皆湿痰之征。脉象说明肝气郁结与湿痰内阻并存之病机，当兼治之。", ["弦", "滑"]], "10755": ["病机", "脉沉弦滑，沉主里，弦主肝，滑主痰。腿骱刺痛、腰酸背脊作响、舌苔白浊，乃风湿痰三者著于肝肾之络。脉象揭示风湿痰浊痹阻肝肾经络之病机，主诸节疼痛。", ["沉", "弦", "滑"]], "10756": ["病机", "左尺浮而不静，由肾气下虚；关部独弦独大独数，舌苔黄燥，乃厥阴肝经湿热助相火，火动摇精。脉象说明肾虚肝实、湿热相火扰动之病机，主胫酸体倦、口苦耳鸣、便坚等症。", ["浮", "弦", "大", "数"]], "10757": ["预后", "再诊大便畅行，口苦愈，左关大脉渐小，惟弦数仍然，尺亦未静。脉象示肝火湿热未清，虽症减而病根未除，故弦数仍在，尺脉未静，说明预后需继续调治，不可松懈。", ["弦", "数"]], "10758": ["病机", "脉形弦数，数为有火，弦主乎肝。肝经伏火，顺乘阳明，且易摇精。虽大便已和，精四日未动，然脉象揭示肝火内伏、疏泄太过之病机，主梦遗等症，故须小心调摄。", ["弦", "数"]], "10759": ["病机", "左脉弦数，弦主肝，数主热。热伏肝家，动而不静，势必摇精。有梦而遗为实，由肝疏泄太过，肾封藏不固。脉象说明肝经热伏、疏泄失常之病机，主梦遗之症。", ["弦", "数"]], "10760": ["病机", "左关独见沉弦且数，左关候肝，沉为气郁于里，弦为肝气劲急，数为郁而化热。三诊封髓秘丸而仍不主蛰，说明封藏失职非虚损一端，实由肝经疏泄太过、郁热内扰，致精关不固。故以脉测机，归咎于肝之疏泄显然，而非单纯肾虚不藏。", ["沉", "弦", "数"]], "10761": ["病机", "失血遗精并见，精血暗伤，当脐动气攻筑、肢体脱力、语言轻微、饮食减少，皆虚象。脉息芤而无神，芤主血虚失守、中空不敛，无神则胃气已衰，正合精血耗伤、虚已甚矣之机；然舌苔腻浊，中宫湿邪尚存，故虚中夹实，治须兼理。", ["芤"]], "10762": ["病机", "白浊久而不痊，久病及肾，肾失封藏，故梦遗更甚；少寐少纳为脾肾两亏、心神不宁，面痿为气血不能上荣。原文仅言脉少，未著脉形，故脉象要素从缺。其机要在肾失封藏、精关不固，兼脾运不健，属虚损之候。", []], "10763": ["病机", "阴虚之体，心火下郁小肠，传入膀胱之府，热伤血络则尿中带血、时作时止；左脉沉数，沉为热郁于里，数为火盛，左脉候心与小肠，正合火郁下移之机。小水不利亦由热结膀胱、气化受碍所致，故脉沉数主里热。", ["沉", "数"]], "10764": ["病机", "淋证再诊，所下薄少而便时不利、便后隐痛，肢膝不温，脉小弦，唇红嗌干。脉小为正气渐虚，弦为余热未清、气机不畅；热未全消故唇红嗌干，虚已渐著故肢膝不温、淋下薄少。此虚中夹热、正虚邪恋之机。", ["小", "弦"]], "10765": ["病机", "淋转癃闭，少腹硬满、小便肿胀、苔白不渴，脉小而沉。小为气化无力，沉为病在里、寒遏于下；下焦本有湿热，被外寒所遏，膀胱气化不行，故溺闭不通。原文断为急症、恐其喘汗，正因水气上逆、气机闭塞，脉沉小示正虚邪闭之危。", ["小", "沉"]], "10766": ["病机", "飧泄不由胃滞即系阳弱，此则兼而有之；脉迟嗳腐脘痛。迟为阳气不足、运化无力，故主阳弱；嗳腐脘痛则食滞中焦、胃气不和。脉迟与嗳腐并见，说明脾阳不振而兼宿食内停，虚寒与积滞并存，故飧泄由阳弱与胃滞兼致。", ["迟"]], "10767": ["病机", "肠澼便血，时重时轻、或痛或否，饮食少，脉形细小。细小为气血两虚、脉道不充，正合下血日久、脾胃虚弱之候；饮食少则化源不足，故断为虚。虚而下血不止，恐气随血耗、水湿泛溢，故原文戒其增浮喘，示虚损有转危之虞。", ["细", "小"]], "10768": ["病机", "脉小而数为气阴两虚之象。小者脉体细小，主营血不足；数者脉率偏快，主阴虚内热。原文先述盗汗便血，盗汗由寒热所致，寒热虽解而盗汗便血不除，说明病已由外感转入内伤，气阴耗损。气虚不能固摄则便血，阴虚不能敛阳则盗汗，脉小数为气阴两虚之直接反映。", ["小", "数"]], "10769": ["病机", "左脉细涩主营血亏虚兼瘀滞，右脉芤主气分虚而血失所摄，寸大尺小示上下气机失调。原文言湿热伤营、腹臌便血久不愈，气分亦虚，既不能摄血又不能清化湿热。细涩为营虚血滞，芤为气不摄血，浮肿为气化失司，故防喘，乃气逆上脱之兆。", ["细", "涩", "芤", "大"]], "10770": ["病机", "右脉细主中气久虚，左脉弦主肝气横逆。原文明言肝逆故胸脘阻塞攻冲，中虚故营卫不和寒热，大便溏饮食少为脾虚之征。右细左弦正是土虚木旺、肝脾不和之脉象，故用四君子合逍遥加左金，健脾疏肝清火，脉症治法相应。", ["细", "弦"]], "10771": ["病机", "脉细数弱为气血两亏之象。细主营血不足，数主虚热内扰，弱主元气衰微。原文述骨格瘦小、先天元气不足，夏秋寒热至今不已，身痛口沃清水，断为胃阳虚惫。细数弱说明气血亏耗而胃阳不振，不能温煦，故当商温补，仿东垣法。", ["细", "数", "弱"]], "10772": ["病机", "左脉空大，空为脉中空虚无力，大为脉体阔大不收，合之主肾水亏虚、阴不敛阳。原文并述倦怠无力为脾气弱，食少则阴虚生内热，症属内伤。左脉候肾，空大乃肾阴亏耗、虚阳外浮之象，与脾弱食少相合，属内伤虚损之候。", ["空", "大"]], "10773": ["治法", "此段为诒按，评补中益气补脾气、六味补肾阴立法切实，惟左脉空大，方中升柴尚宜斟酌。左脉空大主肾水亏而虚阳有上浮之势，升麻柴胡升提发散，恐助虚阳上越，故提出斟酌。虽论治法，实以左脉空大之病机为据，脉象决定用药取舍。", ["空", "大"]], "10774": ["病机", "两手关脉见一粒厥厥动摇之象，即动脉，主土虚木胜、内风动跃。关候脾胃与肝，土虚则木乘，风阳扰动故脉动摇。原文述左半肢体麻木不仁、头眩面麻，病属偏枯，虑延仆中。动脉在此示肝风内动、脾土虚弱，为中风先兆之脉。", ["动"]], "10775": ["预后", "再诊动摇之脉大减，即动脉之势已减，示内风有暗熄之机。原文述左手屈伸稍安，左足麻木未和，说明风阳渐平而经络未全通。脉大减为邪势衰退之象，故判断预后向好，拟补肾生肝以治本。此段以脉象变化测预后，脉减则风熄可期。", ["大"]], "10776": ["病机", "脉细而数，细为津液亏耗，数为燥火内灼。肺热叶焦，津液不能灌输经脉，故见痿躄卧床、形肉消削；燥火灼津，则咳嗽痰臭、舌红无苔。此脉象揭示津液消耗、燥火内灼之病机，主肺痿足痿，与咳痰臭、舌红无苔相应。", ["细", "数"]], "10777": ["病机", "脉空虚，乃病后络脉空虚之象。相火内风走窜入络，故见心中𩠎热、胸前跳跃、气攻背脊如火灼。络虚则风火易入难出，非清镇填窍不可。此脉主络脉空虚、相火内风，与经络脊脉中灼热走窜之症相应。", ["虚", "空"]], "10778": ["病机", "原文未识脉名，然述久患肝风眩运，复感秋风成疟，疟愈后周身筋脉跳跃发厥。此乃血虚不能涵木，筋脉失养，虚风走络，痰涎凝聚所致。病机为血虚风动、痰阻络脉，主筋脉跳跃、发厥，与眩运、疟后虚风相应。", []], "10779": ["病机", "脉浮小弱，浮为风邪外入，小弱为心气不足。风入心经，蕴热蒸痰，故神呆语乱、哭笑不常、舌心红苔薄白。凭脉论之似属心风，乃风邪蕴热蒸痰蒙蔽心神。此脉主心风，与语言错乱、哭笑不常之症相应。", ["浮", "小", "弱"]], "10780": ["病机", "两脉模糊难以捉摸，乃惊动肝阳、神魂扰乱、血随气逆之象。猝遭惊恐，阳升于上，故神糊语乱、口吐紫血、腹胀不食，两足常冷。此即薄厥之属，病机为肝阳上逆、气血并走于上，主厥证，与神乱、吐紫血、足冷相应。", []], "10781": ["病机", "脉小弦滑沉，小弦为少阳之象，滑沉为痰火内蕴。疟后多饮烧酒，酒助火生痰，痰火内扰神明，故如醉如狂、语言妄乱、昏昏默默。此少阳阳明同病连及厥阴，邪并阳明弥漫心包。脉主痰火内扰，与狂乱、便闭、渴饮冷相应。", ["小", "弦", "滑", "沉"]], "10782": ["病机", "脉细，为元气渐虚之象。手足太阴二经有寒饮积滞，阻遏清阳之气，不能通达，故咳嗽口不渴、当脐痛、头常眩运，一月必发寒热数次，乃郁极欲达。此脉主寒饮内停、阳气被遏，与咳、脐痛、眩运、寒热相应。", ["细"]], "10783": ["病机", "脉沉取之数，沉为热在里，数为阴内亏。病延日久，劳损之候，症见咳唾白痰、脘腹时痛、痛则气满、得矢气稍宽。病由肝郁而成，根有痰饮。此脉主阴亏内热、痰饮气郁，与咳痰、腹痛、气满相应。", ["沉", "数"]], "10784": ["治法", "此段为方治，六味地黄丸滋肾填精，生脉散益气敛阴，加青铅重镇纳气。脉散提示气阴耗散、肾不纳气，故以丸剂补阴、散剂敛气，佐青铅沉降，使浮散之气归元。原文以脉散为眼目，示虚散之脉当用收敛镇纳之法，非单纯补益可效。", ["散"]], "10785": ["病机", "原文未出脉名，以“暑风从背俞内薄于肺，湿热从胃脉上熏于肺”说明外内合邪、气并于胸中而不得通，因而上逆作咳。舌苔薄白、口腻不渴，示湿饮内蕴，故“治属饮家”。病机重在邪气交阻、肺胃气逆，非虚非火，乃饮邪上泛之候。", []], "10786": ["病机", "脉形细数，细为阴虚，数为虚热。原文明言“下焦阴虚，中焦痰盛，上焦肺弱”，肺弱故畏寒，阴虚故脉数，喘哮频发由痰盛随感触而作。病分三层，治分三法，层层护卫，示虚实夹杂、上中下三焦同病之机，非单纯攻补可了。", ["细", "数"]], "10787": ["病机", "脉形空大，空为肺气虚馁，大为邪恋不散。原文谓“邪恋肺虚”，又云得汗则身体轻快，想由“肺气虽虚，留邪未净”。咳久正虚而表邪未彻，故降气化痰、保肺涤饮俱少效，当补虚兼化邪，用钱氏法。此脉示虚中夹实、正虚邪留之病机。", ["空", "大"]], "10788": ["病机", "脉虚软而似数，虚软为气虚不足，似数非真热，乃虚阳浮动之象。原文引“邪之所凑，其气必虚”，谓咳嗽虽由外感，实则因于气虚，虚处受邪则病实。既不可纯作风寒，亦未必可作虚损，故以玉竹饮子养阴润肺、兼化留邪，示虚人感邪之机。", ["虚", "软", "数"]], "10789": ["预后", "咳四年、曾失血、今音哑，脉形细弱，细弱为真阴元气皆亏。音哑示金破不鸣，劳损根深，故断“药难见效”。犹幸胃气尚可、大便未溏，姑拟甘润养阴，希图苟安。此脉此症示劳损日久、精血枯竭，预后不良，仅以胃气未败为一线生机。", ["细", "弱"]], "10790": ["治法", "再诊咳止而失血音哑，津液枯槁，劳损已成，脉形细弱示精气两亏。原文引《内经》“针药所不及者调以甘药”，遵《金匮》用黄芪建中汤急建中气，俾饮食增而津液旺，精血渐充。此脉示中气亏败、化源不足，故舍建中别无良法，属虚劳从脾胃论治。", ["细", "弱"]], "10791": ["病机", "脉弦滑数，弦为风温郁于肺络，滑为痰涎壅盛，数为化火之征。原文谓“风温久恋，化火蒸痰，灼金耗液”，症见痰腥带血、气升呛逆，断为肺痈。此脉示热壅血瘀、痰热腐肺之病机，非轻候，当清肺化痰、解毒排脓。", ["弦", "滑", "数"]], "10792": ["病机", "脉形弦硬，为木火亢盛、肝阳上逆之象。咳热痰腥带血，乃木火刑金，肺失肃降，灼伤血络所致。面色暗晦，提示气火郁蒸、血行不畅。弦硬脉主肝旺，木火上逆，肺气不降，故防喘急之变。", ["弦", "硬"]], "10793": ["病机", "脉数而血不止，然胃气大虚、胸痞便溏，此数为虚数，非实火之数。咳血三月忽冲溢，唇白面青，断非实火。虚火吐血宜补宜和，血久不止以胃药收功，脉数在此示虚阳浮越、胃气不固。", ["数"]], "10794": ["预后", "再诊脉数退、血少止，药病相当。然恶寒汗出，乃血脱气无所依，气属阳主外卫，虚则不固。脉数退示虚火渐敛，但气随血脱，卫外不固，最怕喘呃暴脱。胸痞已宽，稍能容纳，仿血脱益气，阳生阴长。", ["数"]], "10795": ["其他", "此段为诒按，仅言以后方均是复脉加减，未及脉象与病机。原文无脉象描述，故脉象要素为空。主旨属方药加减之按语，归为其他。", []], "10796": ["病机", "脉细而迟，细主阴血不足，迟主阳气不运。素患呕血，血止复发，胸痛嗳气，舌苔白腻，此胃中有瘀血，挟痰浊为患。瘀阻气机，痰浊内蕴，故脉道不利而见细迟，非单纯虚寒之候。", ["细", "迟"]], "10797": ["病机", "脉弦形瘦，弦主饮邪内停、气机不畅。始由寒饮咳嗽，继而化火动血，血症屡发而咳不已，饮邪未去。弦脉示水饮留伏，形瘦为阴血耗伤，饮邪未去则咳血难愈，病机在饮与火交织。", ["弦"]], "10798": ["预后", "脉沉细涩，沉主里，细主阴亏，涩主血少津伤。真阴大亏，虚阳上亢，肺金受烁，脾胃伤戕，津液日耗，元气日损。口腻而干，虚极成劳，脉沉细涩示气血俱衰、脉道不利，故难为力矣。", ["沉", "细", "涩"]], "10799": ["治法", "原注论生脉散、六君子去术加扁豆，培养脾阴，土旺生金。不用养阴退热，恐滋滑肠、凉妨胃。久病以胃气为本，有胃则生。脉散虽未明言，然治法紧扣保肺清金、调元益气，以胃气为枢。", ["散"]], "10800": ["治法", "原文以“脉不数”作为辨证眼目，说明吐血虽多而热象不著，身不热、口不渴，皆非实火迫血。脉不数则内无热邪，故“切勿见血投凉”，当从益胃立法，用理中加味温中摄血。此脉象在此处用于排除热证，指导治法选择。", []], "10801": ["病机", "原文未出脉名，以“阴虚有火”与“寒邪深袭”并论，又兼三疟，病延数月，疟来心口酸痛、胸腹空豁难通。引阳维、阴维为病，说明阴阳营卫偏虚，故拟黄耆建中法和中藏之阴阳、调营卫，复合生脉、复脉保肺肾之阴，属病机分析。", []], "10802": ["病机", "脉虚弱而形容消瘦，年方十七，精未充而早泄，阴失守而火升，血症屡发。脉虚弱主气血不足、阴精亏虚，不能充脉养形，故见消瘦；阴亏火升则血不守而屡发。治当滋水降火，兼自保养，属虚损病机。", ["虚", "弱"]], "10803": ["病机", "脉微形瘦，阴阳并损，损及奇经。阳维维于阳，阳气弱则腹痛便溏；阴维维于阴，营阴虚则心痛舌红。脉微为阳气衰微之象，形瘦为阴营亏耗之征，故曰阴阳并损。当以甘温扶阳，兼顾奇经。", ["微"]], "10804": ["病机", "便溏脉细，肢体面目俱浮，悉属阳虚见象。脉细主阳气虚衰、无力鼓动，故便溏而浮肿；惟舌红无苔为阴伤之候，口不干渴乃君火之色外露，属虚阳上浮。治当引火归元，温阳以摄阴。", ["细"]], "10805": ["病机", "左寸关搏指为心肝阳亢，右脉小紧为脾胃虚寒，故腹中常痛、大便不实。病延四月，身微热属虚阳外越，口舌碎痛亦虚火上炎。右脉小紧主中焦虚寒，与左脉搏指之阳亢并见，形成上热下寒、虚阳外越之机。", ["小", "紧"]], "10806": ["其他", "此段为诒按，评述前案阴亏虚火上炎之症，以理中合生脉法温中清上，两面都到。所云“土厚则火敛，金旺则水生”，说明通过温补中土、滋养肺金以敛虚火、生肾水，属对治法方义的评按，非直接脉象主病。", []], "10807": ["病机", "脉沉细数涩，沉细为血虚，数涩为气郁化火。血虚气郁故经事不来；五志郁极从火化，则饥而善食、小水澄脚如脓，为三消之渐；胸痛吐酸，肝郁无疑，郁甚生虫从风化。脉象反映血虚气郁、郁火内生的病机。", ["沉", "细", "数", "涩"]], "10808": ["病机", "脉仍数涩，数主郁热，涩主血虚。原文谓“究属血虚而兼郁热”，郁热日甚则藏阴日铄，故见舌红而碎、口渴消饮；血日干而火日炽，则月事不至、头眩目花带下。此脉象揭示阴虚阳亢、血虚郁热之病机，属虚实夹杂之候。", ["数", "涩"]], "10809": ["病机", "两手脉沉，沉主气郁。原文谓“是气郁也”，因胃中素有酒湿，又因斗殴恼怒引动肝胆之火，与胃痰相搏，致心跳少寐、食入则呕。脉沉反映气机郁滞，痰火内扰，胆胃不和之病机。", ["沉"]], "10810": ["病机", "脉沉细，原文谓“盖重阴之象也”。三阴三阳俱结，阴独盛于内而阳气不通，阴气凝涩，膀胱不化而水成，故反胃兼浮肿。沉细为阴寒内盛、阳气衰微之征，主水气内停、阴阳俱结之病机。", ["沉", "细"]], "10811": ["病机", "左脉沉数不利，沉主气郁，数主火，不利为肝血少而不濡；右关及寸按之滑搏，滑搏为痰火。原文谓肝气郁而不舒、肝血少而不濡，肺胃之气失降，肝木上逆，津液蒸酿为痰，阻塞气道，故咽嗌胸膈若有𪱥塞、纳谷呕噎。脉象揭示气郁痰火、肝逆犯肺胃之病机。", []], "10812": ["病机", "右脉沉滑，左脉细弱。沉滑主痰浊内阻，细弱主血虚。原文谓瘀血挟痰浊阻于肺胃之络，下焦相火随冲脉上逆，鼓动其痰而呃作。脉象反映瘀血痰浊阻络、相火上逆之病机，属虚实夹杂之候。", ["沉", "滑", "细", "弱"]], "10813": ["病机", "脉象细数，细主阴伤，数主热。原文谓无形邪热熏蒸膻中，有形痰浊阻塞肺胃，津枯液燥，正气内虚。细数为阴虚内热之征，主痰热闭阻、津枯正虚之病机，恐有闭厥之变。", ["细", "数"]], "10814": ["病机", "脉形洪大，洪大为阳明邪火有余之象。原文谓少阴阴津不足，阳明邪火有余，火载气上逆，肺不降而为喘，故头汗淋漓、痰喘不止、面青舌红干涸。洪大脉主邪火亢盛、阴津亏耗之病机，症势险危，深防厥脱。", ["洪", "大"]], "10815": ["预后", "脉散为气血耗散、阴阳离决之象。原文以玉女煎合生脉散救阴为急，脉散提示温病后期阴液耗竭、正气涣散，预后堪忧。散脉主脏气衰败、阴阳不相维系之病机，属危重之候。", ["散"]], "10816": ["病机", "脉大稍敛，较前之脉大已减，示痰喘稍平、头汗稍收，然仍大而未和，说明虚阳未熄、津液未回。气促烦躁、舌红干涸、齿垢唇焦，皆少阴阴亏、阳明热炽、虚阳上逆之象。脉大为病进，稍敛为邪有外出之机，故曰“逾险岭未涉坦途”，仍须救少阴、清阳明。", ["大"]], "10817": ["病机", "脉由弦硬转为小而涩数，小为元气渐馁，涩为阴津暗伤，数为热邪未清。温邪袭肺、痰火载气上逆，故喘息痰嘶；舌干口腻、阴津耗伤，脉失充润而涩。正虚邪恋，颇有喘汗厥脱之虑，故治以清肃肺气、化痰降火为先。", ["小", "涩", "数"]], "10818": ["预后", "原文未出具体脉名，仅言“先大而后渐小，先强而后变弱”，此脉由大强渐小弱，反映邪正相搏后正气日馁。热不退而病反增，是正不胜邪、病日进而正日亏，故断为死症。脉象由实转虚而症不减，为预后不良之征。", []], "10819": ["病机", "初病脉硬大，为邪正相搏、邪气盛实；转为弱小，则正气已馁。脉由大硬而弱小，示正虚不能敌邪，而病象不退反增，故曰“病日进而正日亏，不死何待”。此以脉之强弱大小测邪正消长，说明脉硬大主邪实，弱小主正虚。", ["大", "弱", "小"]], "10820": ["治法", "脉微者，阳气衰微之象。葶苈子苦寒峻猛，专泻痰水，适用于痰喘实证。若身不热而脉微，则非实热痰喘，乃正虚阳弱，妄用葶苈则更伤阳气，故忌之。此以脉微辨虚实，示峻下之剂须避虚证。", ["微"]], "10821": ["预后", "原文未出具体脉名，仅言“脉静身凉”。战汗后脉静身凉，是邪随汗解、正复安和之象，故曰“邪已解矣”。舌黄未去，为胃中余浊未清，尚需和化。脉静在此主邪退正安，与躁急之脉主邪陷者相对。", []], "10822": ["治法", "原文未出具体脉名，仅言“脉静身凉”。战汗后脉静身凉，示邪已外解、正气渐复，故用方大法以和胃气、化湿热为主，清余邪而扶胃气。脉静在此为邪退之征，故治法从峻攻转为和化。", []], "10823": ["病机", "脉细滑数，细为阴亏，滑为湿蕴生痰，数为热蒸。得汗得便后多进谷食，邪恋心胃，湿蕴生痰、热蒸液烁，故见烦躁、恶心、错语；两尺少神，舌边干红、心苔黄腻，皆湿热郁蒸、将燥未陷之象。脉细滑数正合阴亏湿热内郁之机。", ["细", "滑", "数"]], "10824": ["病机", "脉洪为胃火极甚之征，火盛鼓动气血故脉形宽大。原文“口臭喷人”“目赤神糊”“口渴”皆阳明热炽、上熏清窍之候；斑疹“透而未足”示热毒未得尽泄。脉洪与胃火相应，故急以白虎化斑、犀地清营解毒，兼存阴液。", ["洪"]], "10825": ["病机", "左脉细小为少阴阴津大伤，右脉洪数为阳明燥火未退，合舌黑苔剥、舌质深红，正是“阴伤火旺、少阴不足、阳明有余”之象。脉之细与洪数并见，示虚火交炽，故用玉女煎一面泻火、一面存阴，守过三候待阴复。", ["细", "洪", "数"]], "10826": ["病机", "原文未出脉名，然“耳聋无闻、舌干难掉”显系阴津大伤、不能上承清窍濡养舌本。此与复脉法所主之阴液亏耗、脉道不充病机相合，故用复脉法以滋阴复脉，虽无脉象可录，其病机自明。", []], "10827": ["病机", "脉象耎而小数，耎为湿邪困阻、脉道弛缓，数为热郁于内，小示正气略伤。原文“呃声徐而未除”乃胃浊未化、气逆上冲；“寤则神清”知邪未深陷。脉耎数正合湿热未清、营卫不和之机，故清营泄卫、理气化浊恰如其分。", ["耎", "数", "小"]], "10828": ["病机", "脉象耎数，耎主湿、数主热，合舌苔白腻、神蒙嗜卧而呼之则清，知非热陷膻中，乃湿热弥漫上焦、肺气失宣。呃逆未除为胃浊未化。脉耎数正是湿热交蒸、气机不展之征，故从肺胃立法，宣化湿浊。", ["耎", "数"]], "10829": ["病机", "肢冷脉细似阴，然小便热痛则属阳；便泄臭水、中脘按痛为实，音低神倦似虚。脉细在此非纯虚，乃痰火郁闭、气血不畅之假象。原文“痰蒙火郁”“虚中夹实”点明病机，故主张先治其实，从下夺邪。", ["细"]], "10830": ["病机", "右脉洪大数疾，左亦弦数，洪大为阳明热盛，数疾为邪热急迫，弦数应肝。合舌灰唇焦、便黑坚硬，显系湿温挟积、肠胃实热燥屎内结；渴喜热饮乃湿居热外之象。脉与唇舌互参，断为湿温挟积，非蓄血、非真寒。", ["洪", "大", "数", "疾"]], "10831": ["预后", "原注以“汗出而脉躁疾”为一忌，躁疾者脉来急迫躁动，乃邪热不退、正气欲溃之兆，故为逆。又值经来恐热陷血室，亦一忌。脉躁疾与战汗后复热并见，示正不胜邪，预后堪虑，故用豆豉、黑栀等宣泄表里，兼通血滞以防变。", ["躁", "疾"]], "10832": ["预后", "原脉数大，为邪热亢盛之象；服药后便下黑栗溏粪、脘痛大减、舌霉唇焦稍退，是邪有出路。然脉转为虚小无力，且心中觉空，说明邪热虽减而正气亦伤，正虚不耐，故防神糊痉厥等变。脉由数大转虚小，正是邪减正虚之候，须延过两候正气得复乃吉。", ["数", "大", "虚", "小"]], "10833": ["病机", "大解后热平、脉转弱小，若伏邪已净或余热不甚，则脉随病退，只须清养。若伏邪再炽，脉可仍转数大。若热势盛而脉反虚小，是邪盛正虚之重候，脉不任邪，当随症施治，不可以日数两候为凭。此段辨脉之进退以测邪正消长。", ["数", "大", "虚", "小"]], "10834": ["病机", "得汗得便后安然两日，旋又发热神糊、两目上视几至厥脱，热时舌乾红、退时黄腻，显系湿遏热炽。然脉沉不起，阳症而见阴脉，脉不与症相应，故曰相反堪虞。沉为邪陷不达、阳气不伸，议甘露饮子涤热燥湿，佐桂通阳、苓通阴，草果祛太阴寒湿，知母清阳明燥热。", ["沉"]], "10835": ["病机", "年过花甲，病逾旬日，又经舟舆跋涉，正已亏虚。刻诊脉象沉糊，神识蒙昧，舌强色白而中心焦燥，身热不扬，手足寒冷，气短作呃，便泄溏臭。脉沉糊为正气内溃、邪陷不达之征，合之诸症，属伏邪挟积、正虚邪陷，故深恐有厥脱之虞。", ["沉"]], "10836": ["预后", "伏暑化燥，劫津动风，舌黑唇焦、鼻煤齿燥、神识昏糊、手指牵引，皆阴津消涸、邪火燎原之象。今早便通、病热略减，似有转机，然两脉促疾无伦，促为阳盛搏急，疾为热极躁动，脉不与症俱减，是邪火未衰而阴津已涸，仍属险象。", ["促", "疾"]], "10837": ["病机", "伏暑湿热为病，阴虚之体邪不易达。症见耳鸣眩悸、苔浊胸痞、微寒微热，脉形弦数。弦主邪郁少阳、气机不畅，数主热，合之知虚不甚、邪亦不多。故立方不宜大补，攻邪亦须轻剂，但得脉情无变即可保无虞，勿徒自惊惶。", ["弦", "数"]], "10838": ["病机", "伏邪挟积阻塞中宫，疟发日轻日重，重则神糊烦躁、起卧如狂，是食积蒸痰、邪热化火、痰火上蒙，故怕风动痉厥。脉沉实而舌苔黄，沉主里、实主积，明示邪积聚于阳明，法当通下，仿大柴胡例以荡涤积热。", ["沉", "实"]], "10839": ["其他", "此段为诒按，纯属评述，未出具体脉名。其意谓脉、舌与症三者合参，症见疟发神糊烦躁、起卧如狂，脉沉实、舌苔黄，邪积阳明，故大柴胡为的对之药。强调凭脉舌症相合以定方，非单凭一脉。", []], "10840": ["病机", "脉细为太阴脾阳不振、痰湿内阻之象。原文述疟后手足寒冷、腹中气胀上塞咽喉，几至发厥，此少阳疟邪挟痰浊下乘脾土，致腹胀、舌白、脉细，病机偏在太阴。脉细主阳气不足、湿浊内蕴，故法当辛温通阳、转运中枢，与阳明昏狂之可下夺者不同。", ["细"]], "10841": ["病机", "脉缓大为脾阳渐通之象。服药后喉中汨汨有声、上逆之气即平、腹胀遂松，知阳气虽通，然寒湿痰涎未化，故腹中微觉胀满、痰多黏腻。脉缓主湿，大主虚，合而示脾藏阳气来复而痰湿未尽，仍从前法轻减其制，以化余邪。", ["缓", "大"]], "10842": ["病机", "脉空虚为营卫两伤、下焦八脉空虚之征。三疟久延，复因产后，气血亏耗，疟邪留于血络、聚于肝膜而成疟母，腹中结块偏左。脉空虚说明正虚邪恋，淹缠不止，虑成疟劳。夏至阴阳剥复之际，瘦人久病最怕阴伤，故和阳生阴、佐搜络以杜疟根。", ["空虚"]], "10843": ["病机", "脉弦数主痰饮内伏、表里同病。素有痰饮咳嗽，复感凉风外薄，食积内停，寒热似疟，额角痛、胸脘痞胀、大便不通，是有表复有里。弦为饮邪、为少阳，数为热，合示外邪与内积相搏，故拟疏里解表，表里双解。", ["弦", "数"]], "10844": ["病机", "再诊脉弦数，两手掌心独热，大便五日不通，舌苔薄白不黄，燥屎尚未全结。弦数仍主痰饮内停、热郁于里，掌心热为里热之征，然苔不黄、屎未全结，故欲通其腑以缓法为宜，不可峻下，免伤正气。", ["弦", "数"]], "10845": ["预后", "脉细为气血不足、湿郁发黄之象。三疟止而复作，腹满平而又发，目黄面黑溺少，脉细示正虚湿滞，防延黑瘅。原文谓瘅而腹满者难治，脉细更显脾阳不振、湿浊难化，故姑与分消，以观进退，预后堪虑。", ["细"]], "10846": ["病机", "脉沉而细主脾胃阳虚、水湿内停。面色黧黑、腹满足肿，沉为病在里，细为阳气衰微，脾阳不化则水湿阻滞于中，泛溢肌肤。原文谓证防增重，故与通阳渗湿，以振脾阳、利水湿，防其肿满日甚。", ["沉", "细"]], "10847": ["病机", "脉细为胃阳不布、痰饮内阻之征。胸痹痰饮，脘痛甚则呕酸，细脉示阳气虚弱不能运化，痰饮停聚胸脘，胃阳不布则痛呕由生。故先以通阳为治，阳通则痰饮自化，胸痹可缓。", ["细"]], "10848": ["病机", "脉小紧数，小为阴血亏少，紧主气郁血凝，数因郁热内蒸。原文谓吐血后\"血去阴伤\"，而\"气分之郁热仍阻于肝胃之络\"，故脉见小紧数而舌红无苔。此非纯实热，乃阴伤兼郁热阻络，痛发于午后亦郁热定时而作之征，治取辛通不耗液，正合脉小忌峻攻之意。", ["小", "紧", "数"]], "10849": ["病机", "脉双弦者，两手皆弦，弦为饮为痛，原文断为\"寒饮在胃\"。寒饮内停，木气乘土，故脘痛吐酸，是\"木克土\"之象；得食痛缓则中气暂充，知病本属中虚。弦脉不独主肝，亦主饮邪，双弦并见，正寒饮与肝木相兼之候，故以建中汤和中泄木祛寒。", ["弦"]], "10850": ["预后", "脘痛而肢冷脉伏，伏为阳气闭郁不出，肢冷乃阳不达于四末，头汗淋漓则虚阳有上越之势。原文断曰\"防厥\"，是知脉伏非寻常气滞，乃阳气欲脱之危兆。痛证见脉伏肢冷头汗，为正不胜邪、阴阳将离之候，故不主病而主预后险恶，当急救回阳以防厥脱。", ["伏"]], "10851": ["病机", "脉细为阳气不足，弦为肝木偏旺，细而弦并见，正是\"肝木挟下焦水寒之气乘于脾胃\"之象。水寒之气上逆，木乘土位，故脘痛攻胁、呕吐酸水。胁为肝之分野，酸为木味，脉弦应肝，细应阳虚，合而观之，病机在土虚木横、寒水内挟，故拟温中御寒、扶土抑木。", ["细", "弦"]], "10852": ["病机", "脉沉弦而紧，沉主里、弦主痛主饮、紧主寒主结，三象合见，是寒积深结于里之候。原文谓\"素有肝胃气痛兼有寒积\"，脘胀痛及腰、舌白腻、渴不欲饮、大便似利不利，皆阴寒凝聚、阳气不通之征。按症\"恐属藏结\"，故曰险候，非温不能通阳，非下不能破结，脉象正示寒结之实。", ["沉", "弦", "紧"]], "10853": ["预后", "屡投温下而便仍不通，胸腹高突、汤下辄呕，是脾阳受戕、清阳失运，结愈结而中愈败。肢渐冷、脉渐细，细为阳气衰微之渐，更见鼻煽额汗，乃虚阳上浮、元气欲脱之危象。原文谓\"厥脱堪忧\"，脉由紧转细，正是邪未去而正已溃，故主预后凶险，取理中转运中阳以图挽回。", ["细"]], "10854": ["病机", "脉迟为阳气不足、寒从中生之应。便通而痛未止，痛在当脐后连及腰，喜食甜味，身常懔懔恶寒，皆中虚阳弱、寒积内停之征。迟脉不主热而主寒，正合\"益火以破沉寒\"之法。痛止而脉仍迟，说明积寒未化、阳气未复，故不以通便为愈，而当续通阳消阴。", ["迟"]], "10855": ["病机", "脉极细而沉紧，细为阳微，沉紧为阴寒内结，合面色晦滞，原文断为\"阳气郁伏，浊阴凝聚\"。久痢伤脾，脾积结块偏右，气攻板痛、上下不通，皆阴浊盘踞、阳气不能转输所致。脉不见浮大而见沉细紧，正知邪结在里、阳郁不伸，故当温通以破阴凝，非攻下所宜。", ["细", "沉", "紧"]], "10856": ["病机", "脉沉弦而紧，沉主里，弦主痛主饮，紧主寒主痛。大便虽通而脘腹之块未化，面色晦滞，乃阴寒凝滞、阳气渐回之象。脉紧为阴凝未散，弦为块结不化，沉为病在里。阳光一𪾢，阴凝渐通，故仍以温通为法，脉象反映寒凝内结、阳气来复之病机。", ["沉", "弦", "紧"]], "10857": ["主病", "脉迟细，迟主寒，细主虚。脘中有块、纳食撑胀、腹中漉漉有声、嗳腐吞酸、大便坚结，此脾胃有寒积也。寒积内阻，阳气不运，故脉迟；积久伤正，气血不足，故脉细。寒积内结，当以温药下之，仿温脾法，脉象正合寒积内结之病机。", ["迟", "细"]], "10858": ["病机", "右关滑动，舌苔黄白而腻，是痰积在中焦；左关弦搏，肝木气旺，故左肋至脐下有梗一条，按之觉硬，乃肝气入络；尺寸脉俱微缓，泄痢一载，气血两亏。滑主痰，动主痛，弦主肝旺，缓主正虚。脉象反映痰积湿热肝气交阻而气血两亏之病机。", ["滑", "动", "弦", "缓"]], "10859": ["主病", "风湿相搏，一身悉肿，咽痛发热，咳而脉浮。浮脉主表，风湿之邪袭于肌表，肺气不宣，通调失职，故一身悉肿；风邪上受，故咽痛发热而咳。脉浮为邪在表，拟越婢法发越水气、清宣肺热，脉象正合风湿在表之病机。", ["浮"]], "10860": ["预后", "痢后阳虚，水湿不化，腹满面浮足肿，色青黄，脉细。细脉主阳虚气血不足。痢久伤阳，脾肾阳虚，水湿泛滥，故浮肿；阳虚不能温运，故色青黄。脉细为阳虚水湿不化之征，虑延鼓胀重症，拟温通脾肾之阳、疏利决渎之气，脉象示预后堪忧。", ["细"]], "10861": ["病机", "病由肝郁，木横克土，湿热不化，先有淋浊，愈后渐渐腹胀，左胁隐痛，身微有热，脉象细弦。细主阴伤，弦主肝郁。肝郁不达，木横克土，湿热内蕴，气机不畅，故腹胀胁痛。脉细弦为肝郁不达之象，虑延鼓胀，勿轻视之。", ["细", "弦"]], "10862": ["预后", "气郁于胸为膈，气滞于腹为鼓，饮食不纳，形肉顿瘦，阴气凝聚，阳气汨没，脉细如丝。细如丝为阳气衰微、阴气凝聚之象。气郁气滞，升降失常，故膈鼓并见；阳衰不能纳食长肉，故形瘦。脉细如丝示正气衰败，姑与扶正培土、通阳化气为法。", ["细"]], "10863": ["病机", "痞块由大疟日久而结，水饮痰涎与气相搏而成，久则块散腹满，变为臌胀，所谓癖散成臌也。脉细如丝，重按至骨乃见弦象，是肝木乘脾；口干、小便短少，是湿热不运。细主正虚，弦主肝乘。脉象示肝木乘脾、湿热不运之病机，急宜疏通水道、泄木和中。", ["细", "弦"]], "10864": ["病机", "脉沉而滑数，沉主里，滑主积滞，数主热，合为积滞内阻、湿热蕴结之征。原文谓“暑湿挟积，阻滞肠胃，中州不运”，故大腹骤满、时痛、便黏色红似痢、小水短少，皆积热阻滞、传化失常所致。脉症相合，故以“积之征”断之，治用大橘皮汤送木香槟榔丸以行气导滞、清化湿热。", ["沉", "滑", "数"]], "10865": ["治法", "此段为诒按，评述“养阴柔肝之正法”，与复脉、定风、阿胶鸡黄等法用意相合。原文未出脉象，纯论治法，故脉象要素为空。其主旨在于肯定养阴柔肝为治疗阴虚风动之正法，与诸滋阴息风方剂一脉相承，属治法范畴，非主病或病机专论。", []], "10866": ["病机", "脉极细，主阴血亏虚。原文谓“少阴肾水不足，阳明胃火有余”，牙宣出血、晡时微寒壮热，脉极细正是素体阴亏之征。阴亏不能制火，胃火循经上炎则牙宣；晡时属阳明，正邪相争则寒热。脉细与症合，故“凭症论治”，用玉女煎清胃滋阴。", ["细"]], "10867": ["其他", "此段诒按讨论脉细之辨，认为“此症之脉细，想系素禀如是”，未必尽属阴虚。强调“须见症确有可据，乃可舍脉从症”，不可冒昧。原文以脉细为素禀，非主病之脉，故主旨属临证取舍之论，归入其他，示人脉症合参、勿拘一格。", ["细"]], "10868": ["病机", "脉形濡，主湿。原文谓“暑雨潮湿，湿从下受，入于经络”，两足腿股酸楚、不能屈伸，此脚气之候。濡脉为湿邪困阻、气血不充之象；湿热自气伤营，故舌苔白底绛、身微寒热。虑气逆冲胸，拟防己饮加减以化湿通络，脉濡正合湿滞经络之机。", ["濡"]], "10869": ["病机", "左尺极细主肾阴亏，寸关微而似数主虚热，右三部弦滑主湿热相火。原文谓“肾阴下亏，而湿热相火，下淫上混”，故下见遗精、肛门痒出水，上见头眩耳鸣、舌苔粉白。脉症合参，断为阴亏火旺、湿热蒙窍，法当补肾阴、清相火、清金和胃、分利膀胱。", ["细", "数", "弦", "滑"]], "10870": ["病机", "左脉虚细主肾阴亏虚，右脉洪大主相火亢盛。原文谓“肾虚精关不固，湿热混于坎宫，精从溺后而出”，左虚细右洪大正是“阴亏而相火胜”之象。阴虚不摄精，相火挟湿热下扰精关，故精浊并见。治用凉八味补肾阴、化湿热，脉症相应。", ["虚", "细", "洪", "大"]], "10871": ["病机", "两脉虚濡，主脾胃元气大弱。原注谓“此病嫌其两脉虚濡，脾胃元气大弱”，似宜扶正；然下痢“起于湿热居多”，早补早敛往往受累，故从河间苦辛宣通府滞之法。脉虚濡示正虚，而痢疾湿热积滞未去，故宁落轻浅、不用深重之剂，体现行远自迩之意。", ["虚", "濡"]], "10872": ["病机", "原文引“脉经云、代则气衰。细则气少”，并言“多指阳气而言”。下痢见代、细脉，是脾肾阳气衰微之象，故曰“脾肾之阳微特著”。形衰畏冷、小便清长皆阳虚外候。下痢赤者属血分，腹痛为有积，提示虚中夹实，立方当通补兼施。", ["代", "细"]], "10873": ["病机", "脉弦紧而不数，弦主痛、紧主寒，不数则非热。便痢白腻如水晶鱼脑色、小便不利、少腹偏右板窒，皆寒湿积滞之征。面色青而不渴更证实为寒积，故断非肠痈之热证，宜温通。", ["弦", "紧"]], "10874": ["病机", "休息下痢延及半载，色红而黏，脉弦。弦为风木之象，久痢营分受伤，风邪羁留肠藏营分而不能出。近日畏风身热，又感新风于外。故治法补中升阳兼凉血，以疏风透邪。", ["弦"]], "10875": ["病机", "红痢匝月，腹痛后重，先曾发疟，表邪传里。脉细肢寒，细为阳衰，肢寒为阳虚不达四末，故曰“中焦阳气已弱”。小便艰难，膀胱气化亦钝。拟连理温中兼化湿热，柴苓解表，表里两解。", ["细"]], "10876": ["病机", "痢减而腹中犹痛，脉弦，值经来而寒热。弦为肝脉，主木郁；经来血虚，肝失濡养，木郁不达，故寒热。此肝胃不和、血虚木郁之病机，治以养血疏肝。", ["弦"]], "10877": ["病机", "便血肠燥而脉大，大脉主气病，此非邪实，乃气虚不敛，故曰“脉大气虚”。气虚则清阳不升，下陷而便血。补气则清阳自升，清阳升则便血自止，明示病机在气虚下陷。", ["大"]], "10878": ["病机", "肠痔脱肛便血已久，脉象细数。细为营阴不足，数为虚热内生，故曰“营阴大伤”。面黄少神、腹中鸣响，脾气大困，脾阳不运。苦寒止血更碍脾，故拟黑地黄丸法，滋阴健脾。", ["细", "数"]], "10879": ["病机", "湿毒流注，左足前臁腐烂，上及缺盆，疼痛木肿，口苦带腻。脉缓而小，缓主湿，小主不足，故断“湿胜于热，热伏湿中”。湿得热而蔓延，循经窜络，病在阳明，治仿防己饮法。", ["缓", "小"]], "10880": ["病机", "脉不甚虚，说明痰疬虽溃久，但正气未大虚，饮食尚可，胃气未败。病由气郁而起，肝胆三焦之火循经上走，结为疬核，溃后色黑脓稀、外软内坚，为痰火郁结、络脉瘀滞之象。脉不虚提示实证为主，故收功虽难，尚可攻邪。", ["虚"]], "10881": ["病机", "脉实能纳，说明胃气尚强，正气未衰，能任攻伐。此病与失营症相类，但脉实能纳，故用药专从痰火著想，以攻邪为主。脉实为邪气盛而正气不虚之征，纳可则化源不绝，故可专力治痰火。", ["实"]], "10882": ["治法", "本条为诒按，论方药加减。方以六味滋肾、生脉保肺、柴芍清肝，立方周到。愚意拟去温肝之萸肉，再加清胆之菇、芩。虽未言脉，但治法从肝肾肺胆着眼，示人调补与清泄并行，以平为期。", []], "10883": ["病机", "脉轻按虚微为元气之虚，重按细数为营阴之损，左尺细弱为肾水亏。经来热甚、舌布白苔，乃胃中湿浊因里热熏蒸上泛。少腹块痛聚散无常，名为瘕，属无形之气，隶乎肝肾。病由目疾过服苦寒，戕伐生生之气，胃寒阳郁生湿，肝寒阴凝结瘕，故内热腹痛。", ["虚", "微", "细", "数"]], "10884": ["病机", "血虚木横，两胁气撑胀痛，腹中有块，心荡寒热，病根日久损及奇经。引经云冲脉为病逆气里急，任脉为病男疝女瘕，阳维苦寒热，阴维苦心痛，合参之知为奇经之病。虽未言脉，然血虚木横、奇经受损之病机昭然，调之不易。", []], "10885": ["其他", "诒按论奇经病之渊源，谓古无专属奇经之病与专入奇经之药。十二经气血有余则溢入奇经，有病亦必日久病深由正经侵入。故用药治病仍以正经为主，学者须明此意，勿为近贤议论所蒙。此条为医论，非言脉。", []], "10886": ["病机", "内热日久经停，投养阴调血通经剂得热减经行，然脉数不和、舌仍光赤，乃阴津未充、虚阳未敛。脉数为虚阳外浮之象，舌光赤为阴伤未复，故虽效犹未愈，仍宜小心安养，不可遽补，亦不可再攻。", ["数"]], "10887": ["预后", "再诊脉数已和，舌色光红已退，但有时尚觉微热。脉数和则虚阳渐敛，舌红退则阴津渐充，为向愈之征。然微热尚存，余邪未清，仍以前法增损，守方缓图，不可停药过早。", ["数"]], "10888": ["病机", "脉沉而数，沉主里，数主热，热伏营血之中。忧愁抑郁耗损心脾之营，肝木僭逆，胸中气塞，内热夜甚，经事两月不来。脉沉数反映热郁营血，木郁不达，故拟柴胡四物汤和营血以舒木郁。", ["沉", "数"]], "10889": ["病机", "脉之凝涩，涩主血行不畅，络脉凝滞。经后少腹痛连腰股，肛门气坠，大便不通，小便赤涩，乃肝经郁热，络脉凝涩所致。拟泄肝经郁热，通络脉之凝涩，脉涩正是络瘀之征。", ["涩"]], "10890": ["病机", "原文未识脉名，然年将五十，经事频来且多，是冲脉不司收摄，防其崩决。此属冲任不固，气血失摄，故补之摄之，以固奇经。脉象虽缺，病机在冲脉失约。", []], "10891": ["病机", "脉象虚微，气血大亏。两次血崩后赤带连绵半载，头眩心跳腰酸足软，皆虚象。近日腹痛食减，恐复崩决。虚微之脉主气血亏耗，奇经失固，故拟固摄奇经。", ["虚", "微"]], "10892": ["病机", "脉弦数者，肝胆郁热之候。咳嗽发热日久，热交寅卯而盛，少阳旺时。肝胆郁热戕伐生生之气，肺金失清肃，脾胃失转输，相火炽阴津涸。弦数应肝胆郁热，故拟酸苦法清泄。", ["弦", "数"]], "10893": ["病机", "脉细肢寒，细主虚，寒主收引。寒气客下焦，瘀凝少腹，阻塞胞门，膀胱阳气失化，致产后癃闭。腹中觉冷，恐气逆上攻发厥。脉细肢寒示下焦阳虚寒凝，故温通化瘀利水。", ["细"]], "10894": ["病机", "诊脉弦搏，肝阳有上亢之象。小产恶露止，腹痛结块，心神妄乱言语如颠，血风病也。血凝动火，火炽生风，胞络上系心胞。弦搏主肝阳亢盛，防加吐血，故化瘀为先佐清火。", ["弦", "搏"]], "10895": ["病机", "脉虚数，虚为气亏，数为热。体气素亏，产后悲伤咳嗽，背寒内热，气逆痰多，便溏百日成蓐劳。冲脉为病逆气里急，阳维为病苦寒热。虚数示气血虚而虚热浮，故通补奇经镇摄冲脉。", ["虚", "数"]], "10896": ["病机", "原文未出脉名，以“乳房属胃，乳汁血之所化”立论，谓无子而乳胀下汁，非血有余，乃血不循常道下归冲脉为月水，反随肝气上入乳房变为乳汁。病机在肝气逆而血随气上，如风激水作波澜，故主张顺气清火熄风使之下行，反对堵截涩源。", []], "10897": ["病机", "疟痢三年，脾胃元气大伤，而“脉数舌红”，数主热，舌红主阴伤，是虚中挟热、阴液受灼之象；腹满足肿、小溲短少，为脾虚不运、水湿内停。前投升阳益胃热势略减，今拟补益脾阴兼化浊，因童稚阴亏、病延日久，夏令防其增剧。", ["数"]], "10898": ["病机", "诒按小儿虚症以脾胃为主，然“脉数舌红”，数则为热，舌红为阴液不足，故谓“阴液亦损”，当稍参养阴之意。此段承上案而申明：小儿久病虽重后天脾胃，脉数舌红已露阴亏之机，不可纯事温补，须兼顾养阴。", ["数"]], "10899": ["病机", "病经匝月，表热解后杳不思纳，而“脉静舌净”，脉静则无邪热内扰，舌净则无浊苔，故知既无外感留恋，又非老景颓唐；神倦言懒、睛光流动、面色开旷，乃胃气为苦寒沉降之药所困，非病非衰，故进和中醒中以悦脾胃，令纳谷乃昌。", []], "10900": ["病机", "再诊胃气乍醒而“脉形软弱”，软弱为气血未充、脏腑之气尚微之象，故谓久饥之后胃气虽醒而力薄。纳谷以匀为稳，用药宜轻灵，须俟胃气日隆方可峻补，因补剂必藉胃气敷布，经云“百病以胃气为本”“安谷则昌”。", ["软", "弱"]], "10901": ["病机", "竟日悲思半载纳减，脉“右寸细数而小滑”，右寸属肺，细为阴伤，数为伏火，小滑为痰，故断为伏火挟痰；悲哀属肺，寝则气窒醒则流通，乍醒应通犹窒故特甚。或更有所惊恐，惊则气结，结则成痹，升降失常，胃气日馁，故拟开结通痹为先。", ["细", "数", "滑"]], "10902": ["病机", "两进开结通痹后悲哀顿释，咯痰黄厚，胃纳稍思，而“脉之滑数亦缓”，滑数为痰火，缓则邪势退，故明证其为痰火痹结。痰火既减，继以清泄通降，补不可投，因余邪未清，早补恐壅滞复结。", ["滑", "数", "缓"]], "10903": ["病机", "眩晕多年，每发于湿蒸之令，今年潮湿过重发亦频频，诊“脉濡细”，舌苔腻白。濡细主湿、主虚，腻白苔亦湿浊，故不从诸风掉眩概作风阳上旋，而断为湿郁上泛、挟浊痰腻膈所致，拟辛香运中以化湿化痰。", ["濡", "细"]], "10904": ["病机", "脉濡主湿，便溏为湿邪下注。患者体肥、嗜酒、卧地、饮冷，皆伤太阴脾土，湿浊内停。眩晕虽止，舌白依然，脘中较爽，说明湿邪未净，仍阻中焦。脉濡与便溏并见，正是太阴阳明湿滞之征，故治守太阴阳明，燥湿运脾。", ["濡"]], "10905": ["病机", "脉濡主湿，神糊为湿痰蒙蔽清阳。形凛汗渍、舌如傅粉、沉睡痰迷，皆湿痰弥漫之象。素嗜酒，湿痰内生，蒙遏清阳，扰乱神明，非邪陷心包，亦非闭证。脉濡与神糊并见，说明湿浊蒙窍，故拟达原饮意，化湿祛痰。", ["濡"]], "10906": ["病机", "脉濡细主湿邪未净而正气渐伤。汗渍已收，神志转清，呕痰盈碗，舌苔白腻弥漫之势虽除，但脉仍濡细，说明湿痰虽减，太阴脾运未复，湿浊余邪留恋。故尚宜燥湿祛痰，从太阴阳明主治，以复中焦运化。", ["濡", "细"]], "10907": ["病机", "脉数寸关尤甚，主阴亏内热，厥阳化火上逆。鼻衄成流三日，面赤足冷，血去过多，心荡神驰，皆火升血溢之象。脉数与面赤足冷并见，说明虚阳上浮，扰动络脉，血行清道。故仿志火升腾治例，用凉血滋降法。", ["数"]], "10908": ["预后", "脉虚而数，主气血两虚而虚阳浮动。鼻衄虽止，面唇㿠白，额汗心悸畏明，舌光而颤，皆气乏血涵、血无气护之象。脉虚数为阴阳离脱之兆，气血有涣散之险。故急进双补法，佐咸降酸收以摄之，庶几有所依附。", ["虚", "数"]], "10909": ["病机", "左脉弦硬，右脉细软，主肝木犯胃，胃气已惫。恼怒伤肝，木火犯胃入膈，呕吐血块痰涎，不纳不便，舌白苔腻。左弦硬为肝气横逆，右细软为胃气虚弱。谷不沾唇五日，中无砥柱，故治以苦寒制肝、苦辛通胃，兼奠安中气。", ["弦", "硬", "细", "软"]], "10910": ["预后", "左脉弦硬固平，右脉歇止渐见，主土德大残，中气亦竭。呕逆止、胀痛缓，而右脉歇止，说明胃气衰败，脾土将绝。歇止脉为脏气衰微之兆，故急进补中立中，参约脾制肝之法，惟望胃纳能醒。", ["弦", "硬", "歇", "止"]], "10911": ["病机", "脉俱濡细，主湿邪渐化而胃气来复。胀痛大减，呕逆未平，稍能纳粥，说明中焦气机渐通，但湿浊未净，胃气尚弱。脉濡细与纳粥并见，为胃气渐复之机，经云“纳谷则昌”，故仍守太阴阳明调治。", ["濡", "细"]], "10912": ["病机", "左关脉数，右关细软，舌白口苦，寒热往来，是邪蕴少阳，胃被邪克，气不通达。脉数主热，细软主虚，左关候肝胆，数则少阳郁热；右关细软，胃气受抑，故得食则呕，形神疲乏，宛如膈症。此非真噎膈，乃少阳邪郁致胃气上逆，故宜先泄少阳之邪。", ["数", "细", "软"]], "10913": ["预后", "服小柴胡后壮热大汗，思纳粥，今已吃饭，惟力不充。诊左关已软，右脉尚细。左关软是少阳邪退，右脉细乃胃气未复，故续与和中。此段以脉象变化示邪去正虚，预后向愈，但力不充，细脉主气血不足，软脉主邪衰，故当调补。", ["细", "软"]], "10914": ["主病", "发热恶寒，头项强痛，无汗胸痞，脉浮紧细，症属正伤寒。浮主表，紧主寒，细为寒邪束表、营卫郁滞。太阳表症悉具，宗仲圣不汗出而烦躁者，大青龙汤主之。脉浮紧细说明寒邪闭表，阳气不得宣发，故无汗而烦躁，当发汗解表。", ["浮", "紧", "细"]], "10915": ["预后", "三诊汗畅热解，烦躁已除，脉转细小，形疲体酸嗜卧，思纳谷。脉由浮紧细转为细小，是邪退正虚之象。细主气血不足，小主脉道收敛，故形疲体酸。此段言质弱者易感易达，退亦易易，现脉细小示邪去而营卫未和，拟和营卫法调之。", ["细", "小"]], "10916": ["病机", "表热九日，有汗不解，舌绛起刺，烦渴引饮，脉洪无力。洪为阳明热盛，无力为津液灼伤、正气已虚。此非大柴胡症，乃正虚津竭，府滞未通。洪而无力的脉象说明热盛而津气两伤，故不可香开，不可遽下，必俟津回液复，拟人参白虎汤意。", ["洪", "无", "力"]], "10917": ["病机", "再诊汗热烦渴已减，舌绛淡而尖刺已少，津液稍回，正气较振，脉数未平，神志已爽。数脉主热，虽减而未平，是少阳阳明余热未清，府滞尚待清润育阴而下。此段强调切勿因滞而遽投荡涤，脉数未平说明余邪未尽，当审症慎治。", ["数"]], "10918": ["病机", "表热四候，额汗如淋，汗时肤冷，汗收热灼，诊脉虚细，惟尺独滑。虚细主正气不足，尺滑主肾经有邪。此湿温余邪流入少阴之阴分，由少年肾气不藏所致。脉虚细说明病邪不在三阳而在三阴，尺滑示肾中伏邪，故拟补肾阴、泄肾邪。", ["虚", "细", "滑"]], "10919": ["预后", "再诊热解已净，自汗亦收，脉滑已和，纯乎软弱，神情向倦，而虚象旋著。滑脉已和是邪热尽退，软弱为气血未复之象。此段以脉象转和示病退，但虚象明显，故拟转用补养，以复正气。滑去软现，说明邪去正虚，当补养为要。", ["滑", "软"]], "10920": ["病机", "脉数大而混糊无序，为疫毒内炽、秽浊蒸蕴之象。壮热神糊、舌垢腻、脘腹痞硬、气粗痰鸣，皆邪毒壅盛于里；矢气频转、小溲自遗，示腑气不通而气机下陷。脉数主热，大主邪盛，混糊无序则非寻常外感，乃疫毒急症，故主张早议下以逐秽存阴。", ["数", "大"]], "10921": ["病机", "脉数略有次序，较前混糊无序为转机，然腹犹拒按、矢气尚频、便下黏腻极秽未畅、小水点滴如油，舌苔层布垢浊，显系胃中秽浊蒸蕴之势尚形燔灼。脉数主热，略有次序示正气渐复而邪未尽，故须再下，俟里滞渐楚方可退就于表。", ["数"]], "10922": ["病机", "脉数较缓，为腑中蒸变乍平、邪热渐退之征。大腑畅通、腹软神爽、舌苔半化，皆里滞已去之象；表热壮而汗反艰，则病已退出表分，当从表分疏通。脉数较缓说明里热已减而余邪未清，故先里后表之论信不诬也。", ["数", "缓"]], "10923": ["病机", "脉转细，为病去正虚、气血不足之象。表热随汗就和、舌苔又化一层，邪已渐解；神倦脉细，示正气耗伤。此时当和养中气、佐轻泄以涤余热，慎勿以虚早投补剂，补之则反复立至，因余邪未净，补则壅滞。", ["细"]], "10924": ["病机", "脉沉而细，为久疟伤阴、阴损不复之候。间疟复发不归期，寒战热甚而无汗泄，形瘦骨立、胃纳式微，皆阴亏不能托邪外出。沉细主里虚，阴伤则脉道不充，故为劳疟显然。现届夏令可汗之时，拟少阳少阴并治，冀汗泄于表、阴复于里。", ["沉", "细"]], "10925": ["病机", "脉沉转出，为邪有向外泄化之机。药后寒战依然而热势转短，热退汗畅、神爽食有味，皆从汗后转轻，究由外感乘虚蕴伏，愈伏愈深延为怯象。脉沉转出说明伏邪渐达于表，仍宗前议加减，必得转为间疟乃安。", ["沉"]], "10926": ["病机", "脉形细小，为久疟阴伤、正气未复之象。疟准日作、解后有汗、寒热大减，症属转机；舌不生苔，示阴液亏耗。脉细小主阴血不足，故拟清养法参以泄化，复其阴可耳。凡腥膻鲜发及麦食等均须慎禁，以防助邪。", ["细", "小"]], "10927": ["病机", "脉弱神疲，为肾脏伤残太甚、肾阳不举之候。肌肤舌质尽黑、手指映日俱黯，腰软不耐久坐、纳减足冷，皆肾气过损之征。脉弱主虚，神疲示元气衰惫，显属女劳黑瘅，非风毒外袭。现届深冬姑先治本，需春暖阳和再商他法。", ["弱"]], "10928": ["预后", "原文未识脉名，仅言「形神色脉，俱属平善」，是脉证相安之象。阴黄较黑瘅浅一层，脾肾药进四十余剂后形神色脉俱平，说明脾肾渐复、湿浊渐化，故可乘惊蛰春暖开泄腠理以涤肤斑。脉平善为可治可透之凭，黑色退尽当在夏初，属预后推断。", []], "10929": ["病机", "脉沉实，沉主里、实主邪结。腹痛拒按、便三日未行、舌垢腻，是湿痰食滞团结于内，故脉应之沉实有力。然脾肾之阳素亏、自汗如雨，又属阳虚之体，非下不通、非温不动，故取许学士温下法，脉沉实正是可下之据。", ["沉", "实"]], "10930": ["病机", "再诊大府畅行、痛止汗收，邪滞已去而脉转虚细。虚细为气血不足之象，与神思倦相应，说明攻下之后中气受损、胃气未复，故不再言下而言养胃和中，脉由沉实转虚细即邪退正虚之机转。", ["虚", "细"]], "10931": ["病机", "脉浮紧，浮主表、紧主寒主痛。遍体肿而肤色鲜明、身热无汗、气喘促、小便闭、舌白不思饮，是水湿之邪藉风气鼓行经隧，风水相搏于表，故脉浮紧。治以开鬼门、洁净府，正合浮紧在表之机；喘甚气塞则属至危。", ["浮", "紧"]], "10932": ["病机", "脉细舌白，细为阳衰阴伤、白为湿浊未化。腹痛下痢昼夜无度、汗冷肢冷，是暑湿热挟滞互结而中阳先馁，邪不能化热外达，多汗伤阳、多痢伤阴，故脉见细。里急后重宜通、溲秘宜清渗，然虚波已至，故温清并进。", ["细"]], "10933": ["病机", "脉沉细，沉主里、细主虚。下痢减半、肢冷较和、汗亦稀少，是阳稍回而邪未尽；舌白苔腻不化、里急后重已缓、腹中犹痛，究属中虚湿胜、暑积阻结，阳气不能运动，故脉仍沉细，尚非坦途，再拟温中运邪。", ["沉", "细"]], "10934": ["预后", "原文未识脉名，只言「脉象起矣」，指前之沉细已渐起复。痢下大减、舌苔渐化、腹痛除而宿垢通、小溲赤而两三度、谷食思，皆中阳既得运动、邪滞渐化之征，故脉象起为向愈之凭，尚当和中以善其后。", []], "10935": ["病机", "脉微神倦，微为阳气衰微、气血俱虚。三诊血下缓而大减，邪虽退而气阴并乏，故脉微而神倦，与堵塞存阴之药不可撤相应，说明阴血耗伤、正气难支，须于昨方加立中意以扶正固本。", ["微"]], "10936": ["病机", "脉弦数，弦主气郁痰凝，数主内火炽盛。原文谓“内火犹炽”，大便五日不行，左项痰核虽软而余络未窜，说明痰火郁结络脉，气机未畅。脉仍弦数，表明郁火未清，故再议化痰通络，理气开郁。", ["弦", "数"]], "10937": ["病机", "脉弦小软，弦为气郁未解，小软示痰核渐消而正气略伤。原文“痰核已消三粒，所剩四粒亦软而小”，大便已畅，说明痰势已减，络脉渐通。脉象由弦数转弦小软，反映郁火渐平而痰凝未净，故再拟消痰，兼藉怡养。", ["弦", "小", "软"]], "10938": ["预后", "脉微虚软，微为阳衰，虚软为气血大亏。原文“暴崩属虚，虚阳无附”，见额汗头震、闻声惊惕、多语神烦，乃虚阳浮越、二气将脱之兆。脉证相参，势将脱离，其危至速，故急拟回阳摄阴以安气血。", ["微", "虚", "软"]], "10939": ["病机", "脉犹濡细，濡主气血不足，细主阴血亏虚。原文“脱象既除，经漏较稀”，神思尚怯，说明暴崩后气血乍得依附，但未复常。脉濡细反映气血两虚、冲任未固，故再宗暴崩属虚之例，拟温补法以固本。", ["濡", "细"]], "10940": ["病机", "两脉弦细，弦主邪郁少阳，细主正虚。原文“久痢脾肾两亏，复感新凉转为三阴疟疾”，脾肾久亏则脉细，新凉引动伏邪、少阳枢机不利则脉弦。脉象示正虚邪恋，故拟合和解扶正，速解为吉。", ["弦", "细"]], "10941": ["预后", "原文“脉象空虚无神”，纯为描述，故脉象要素不取。空虚无神示胃气衰败、阴伤正竭。症见口干舌赤、胸闷哕逆、谷食懒进，胃阴伤而虚热上逆。脉无神则预后堪虑，故“虑增昏呃歧变”，拟方以尽人力。", []], "10942": ["病机", "原文“两脉按之无力”，未识脉名，故脉象要素不取。按之无力主阴阳二气俱伤。症见肛坠无休、腰胯酸痛、肢末厥冷、哕逆自汗、谷食懒进，乃脾肾阳衰、中气下陷。脉证合参，虚损难骤效，故拟参附六君子汤温补。", []], "10943": ["病机", "两脉数大，数主热，大主邪盛。原文“暑湿下痢，红多白少，腹痛后重”，暑湿蕴结肠道，气血壅滞，热伤血络则红多。脉数大示暑湿热邪方炽，正气未衰，故仍宜清利治之，以祛邪为要。", ["数", "大"]], "10944": ["病机", "原文谓积湿成饮、积饮成痰，痰饮伏于肺胃，兼火不生土而五更泻利。脉弦主饮邪内停、气机被阻，滑主痰湿壅盛，故弦滑并见，正合痰饮内伏、脾肾阳虚之病机，主痰饮及五更泄泻，治以姜附六君温运。", ["弦", "滑"]], "10945": ["病机", "肝肾素亏，肠澼日久，中土亦虚，饮食减而纳亦不运，胸脘腹闷、利带红水、脐腹㽲痛、乍寒乍热。左脉弦为肝木偏旺，右脉濡为脾土虚弱湿困，故虑土败木贼之虞，脉象揭示肝强脾弱、营卫俱虚之病机。", ["弦", "濡"]], "10946": ["病机", "立秋湿热蕴于肠胃，日久未解而成肠风，血或紫或鲜。关脉候中焦肠胃，滑主湿热蕴结、血分有滞，数主热邪内盛，故关脉滑数，说明湿热下迫肠腑、灼伤血络之病机，仍当清理湿热，慎口避风以防肿胀歧变。", ["滑", "数"]], "10947": ["病机", "素本体虚，气虚肛坠，宿饮射肺咳逆气喘，肝木侮土，胃强脾弱，湿热下注酿翻花痔，漏血如箭，气不摄血，两腿酸软抽搐，肌肤痿黄。脉弦为肝旺，沉细为阴阳交虚、阳虚特甚，血不荣筋，久则防成肿胀，脉象总括虚损夹饮之机。", ["弦", "沉", "细"]], "10948": ["病机", "嗜酒伤中，肝胆湿热下移膀胱，致成痛淋十余年，时作时止，小便秘结。脉弦主肝胆气郁，细为久病阴伤，滑主湿热蕴结下焦，三象合参，说明湿热下注、气化不利而阴分已伤之病机，故防其久延成血淋。", ["弦", "细", "滑"]], "10949": ["其他", "此段为书札复函，述贵恙原责在水虚，木失涵养，火无所制，幻出诸症，拟加育阴潜阳之品再服，并约脉症相参。原文未识别出脉名，亦无脉象描述，故脉象要素为空，主旨属书信往还之其他类，不涉具体脉诊判断。", []], "10950": ["病机", "肺经湿热内蕴，致咳脓痰、色红味腥、胸胁隐痛。右脉候肺，濡主湿邪偏盛、肺气不宣，数主热邪内郁，湿热蒸腐肺络则脓痰腥红，故右脉濡数，说明湿热壅肺、渐欲成痈之病机，虑成肺痈。", ["濡", "数"]], "10951": ["病机", "风伤皮毛，热伤血脉，渐积成脓，酿成肺痈大证，身热自汗，谷食少进。脉数主热盛，实主邪壅正未大虚，然谷食少进已露人虚，故谓人虚证实、调治殊难，脉象数实正示热毒壅肺成痈而正气渐伤之病机。", ["数", "实"]], "10952": ["病机", "脉象滑数，滑主痰热，数主热盛，此风温犯肺，郁而化热，热伤脉络，痰热壅肺，故咳吐臭痰。肺痈已溃，脉仍滑数，示痰热未清，正虚邪恋，难以挽回，拟方以尽人力。", ["滑", "数"]], "10953": ["病机", "脉象虚数，虚为气阴不足，数为虚热内扰。客冬肺痈未收口，咳嗽吐瘀，寒热往来，梦寐不安，天癸渐少，气短汗少，皆气阴两伤、虚热内炽之象。再延防成肺痈，当益气养阴清虚热。", ["虚", "数"]], "10954": ["病机", "两脉细数，细主阴血亏虚，数主虚热。春季咳嗽，入秋操劳愤郁，燥气内侵，津液内竭，咳吐脓痰，声哑咽痛，骨中烧热，肌肉消瘦，皆肺阴亏耗、虚火灼肺之候，肺痿之势已露，拟喻氏法养阴清肺。", ["细", "数"]], "10955": ["病机", "脉象滑数，滑主痰湿，数主热。肝邪入肺，咳久化热，痰热壅肺，灼伤肺络，故右胁痹痛、痰中带血。虑其成痿，即肺痿，因痰热久蕴，肺阴耗伤，宜清肺化痰、凉血止血。", ["滑", "数"]], "10956": ["病机", "脉象弦细而滑，弦主肝胆，细主阴血不足，滑主痰涎。自幼多惊，痫症屡发，痰涎藏于肝胆，发则犯心包而神呆痉厥，上凌肺胃则吐涎沫血水。新婚发紧，肝肾乙癸同源，精血亏耗，痰风内动，拟方徐图。", ["弦", "细", "滑"]], "10957": ["病机", "脉象弦细，弦为肝胆气郁，细为阴血不足。喉痛宜凉，腹痛宜温，症情矛盾，兼惊痫痉厥频作，乃肝胆郁热、阴血亏虚、风动痰扰之机。拟方兼顾，凉温并施，养血柔肝，熄风化痰。", ["弦", "细"]], "10958": ["病机", "脉象弦滑，弦主肝胆，滑主痰热。抑郁惊恐伤肝胆，气郁化火，灼津为痰，痰热内扰，蒙蔽心窍，致成痫症，延多年。当自开怀抱，解郁化痰，清肝熄风，药饵方可与情志调摄兼功。", ["弦", "滑"]], "10959": ["病机", "脉象弦滑，弦为肝胆风动，滑为痰热内壅。惊恐伤肝，肝胆痰热已深，稍有悒郁则风火并起，人事不省，气阻痰壅，手足抽搐，口角流涎，良久方苏。癸水先期，热扰血海。药难霍然，徐图缓治。", ["弦", "滑"]], "10960": ["预后", "惊痫未作、哕吐未来，说明病势已退；脉象弦缓，弦为肝气渐柔，缓为胃气来复、营卫向和，故曰“营卫渐次向和”。此非主病之脉，而是治疗后向愈之象，提示慎口调养可渐入佳境。", ["弦", "缓"]], "10961": ["病机", "郁怒伤肝，肝气郁而化热，胆失清净，热化为厥，故心志不灵、言语失序、身热舌黄尖绛。两脉滑数，滑主痰、数主热，正合痰热内生之机，故诫“安闲开怀”以免痰热互胶生变。", ["滑", "数"]], "10962": ["病机", "操劳郁怒致肝气直犯心包，气阻喉间、心中嘈杂，脉象弦滑。弦为肝气郁逆，滑为痰热内壅，故断为“肝胆痰热内闭之征”，并虑痫厥乘举，属病机与预后并见之论。", ["弦", "滑"]], "10963": ["病机", "素多湿痰，内风鼓动，风中血脉而右肢不遂、苔白腻。脉弦滑，弦主内风，滑主湿痰，正合风痰阻络之机，故戒怒远烦以助药力，属主病兼病机之段。", ["弦", "滑"]], "10964": ["病机", "右脉滑数，滑主痰、数主热，故曰“痰生热也”；左脉浮大，浮为风、大为热盛，故曰“热生风也”。合湿痰瘀血凝结筋络、流于心包之症，脉症相参，示痰热生风之病机。", ["滑", "数", "浮", "大"]], "10965": ["病机", "原文未识脉名，故脉象要素为空。全段以肝肾素亏、多湿多痰之体立论，春间风中阳明脉络致口眼歪斜、肢末作麻，入冬面皮强急，湿痰犹存，说明正虚痰阻、风邪入络之病机，并虑仆中歧变。", []], "10966": ["病机", "阳明脉虚，则周身脉络失养而不和；更兼肺受风邪，气痰内郁，一身之气不利。脉虚为气血不足之征，故立宣肺和络之法，属因脉论证、以脉定治之段。", ["虚"]], "10967": ["病机", "内风鼓动，痰凝经络，故右肢麻痹、头眩心悸、神识不安。两脉弦滑，弦主风动，滑主痰凝，风痰相搏阻于经络，故断“有偏枯之患”，示病机并寓预后之虑。", ["弦", "滑"]], "10968": ["病机", "脉弦数少神，弦为肝郁气滞、风寒湿三气乘虚外袭，数则郁而化热，少神示正气已伤。原文谓“欲按为虚，邪在为实”，正虚邪实相搏，营卫壅滞，故脑后痛入骨；邪郁日久有化热酿毒之势，故虑转痈疽，治当扶正却邪。", ["弦", "数"]], "10969": ["病机", "脉浮濡而数，浮为暑湿风邪上犯头元，濡主清阳致虚、湿邪黏滞，数则郁而生热。原文“操劳太过，清阳致虚”，虚体受邪，湿郁化热，故舌苔黄腻。邪郁清窍有昏厥之变，故拟青空法增味速解。", ["浮", "濡", "数"]], "10970": ["病机", "脉弦滑，弦属肝阳化风，滑主痰热内蕴。原文“痰热扰乱，肝阳化风”，痰火随风上扰，故心悸头眩、神思恍惚；痰热内踞中焦则嘈杂易饥。上虚下实，风痰有升腾之势，故虑类中之渐，值夏至节令尤须提防。", ["弦", "滑"]], "10971": ["病机", "脉来强数，强为肝阳亢盛、火气有余，数为化火生风之象。原文“郁损肝阴，化火生风”，肝阴亏则血不养筋，故筋脉酸胀；风火循经上逆，气逆阻隔，故头眩面热、愈逆愈眩。治拟和阳熄风，使肝阳平而风自息。", ["数"]], "10972": ["病机", "脉弦滑，弦主肝郁气逆，滑主痰浊内盛。原文“肝郁夹痰，生火生风”，痰火随风煽动，故左胁肝垂内煽、头眩目眩；气逆痰升则吐沫，风痰走窜肢末则作麻，营卫失和则乍寒乍热。痰火升腾有昏厥之虑。", ["弦", "滑"]], "10973": ["病机", "两脉弦滑而数，心脉较大。弦为木火体质肝气易升，滑主痰郁，数则火旺。原文“肝阳亦失其清净”，风火挟痰上扰，故头目眩、心悸作烦；血虚风动则手足蠕动。心脉大示火盛于上，须戒怒远烦，免酿痰歧变。", ["弦", "滑", "数"]], "10974": ["病机", "本段未识脉名，以症测机。原文“肝肾两亏，夹湿夹痰”，又加馆课劳心、营分暗耗，血不荣筋，故左边肢体酸软无力、手足不耐久用；痰湿上泛则咳吐痰涎、头目时眩、左耳时轰。年过五旬，久则虑其仆中，仿络热则痿治之。", []], "10975": ["病机", "本段未识脉名，从症析机。原文“操劳太过，血水内泛”，寒湿乘虚入于脉络，成为筋痹，日久卫营失和，故手指筋强而肿、伸屈不利。寒湿痹阻、营卫不通，非旦夕可解，故谓药难霍然，宜徐图缓治。", []], "10976": ["病机", "原文未载脉象，然述暑湿伏邪内郁致周痹，身热不寒、筋脉酸痛、舌白口苦、入暮热重、神昏谵语，显系暑湿深伏、蒙蔽心包、痹阻筋脉之机。势属重候，虑其昏陷生变，正合湿温邪陷心营之危。", []], "10977": ["病机", "脉沉弦而细，沉主里，弦主木旺乘土，细为阴血不足。始由木乘土位，久则火不生土，谷食不运，嘈杂嗳气频仍，二年时作时止，正合肝郁脾虚、土衰木贼之机。脉较前稍平，故曰缓图可绪，然反复深虑反胃。", ["沉", "弦", "细"]], "10978": ["病机", "关脉数急，关候中焦，数急为火盛阴亏之象。产育后阴亏未复，操劳恚怒，风伤内扰，胃阴内耗，脘中嘈杂，易食易饥，火生面热，已入中消之势。数急之脉正合胃火炽盛、阴液受灼之病机。", ["数", "急"]], "10979": ["病机", "脉虚弦而滑，虚为阳明脉虚、气血不足，弦主肝胆不和，滑为郁痰内扰。肝胆不和，心肾不交，郁痰内扰，心神恍惚，善食易饥，善性多疑，肉𥆧筋剔，头眩耳鸣，正合虚风夹痰、内扰心神之机，延久防成中消。", ["虚", "弦", "滑"]], "10980": ["病机", "脉沉弦而滑，沉主里主肾，弦主肝郁，滑主痰饮。肝肾乙癸同源，肝郁不舒则筋疝下坠，肾气虚寒则绕脐作痛，肝阳夹饮上腾清窍则头目不清、时咳凉痰。沉弦滑之脉正合肝郁肾寒、痰饮内停之病机。", ["沉", "弦", "滑"]], "10981": ["病机", "原文未载脉象，述肝虚气滞、癸水不调，经或至或否、来时暴涌、经过带下绵绵、腹痛腰酸、少寐多汗，冲任督带奇脉交伤。此系肝虚气滞、奇经失养、统藏约束无权之机，若不调理，恐经漏成崩、经闭成蛊。", []], "10982": ["病机", "脉象弦数，弦为肝郁气滞，数为郁热内扰。女以肝为先天，月水赖肝经条达，此时肝虚气滞，胸脘胀痛，营卫不和，乍寒乍热，腰膂酸楚。弦数之脉正合肝郁化热、营卫失调之病机，速宜静养，再延有损怯之虞。", ["弦", "数"]], "10983": ["病机", "脉象弦滑，弦主肝胆，滑主痰热。经频带下，肝脾失统藏，任带疏约束，心落落，头目眩晕，肉𥆧筋剔，左肢麻痹，梦寐不安，其为肝胆内蕴痰热、奇经不和可知。弦滑之脉正合痰热内蕴、奇经失和之病机。", ["弦", "滑"]], "10984": ["病机", "原文未载脉象，然由“产育”后“赤白带下不止，腰脊酸楚”，可知下焦八脉已伤，冲任不固，精血滑脱。腰为肾府，脊属督脉，带脉失约则带下不止。病机为产后正虚，奇经损伤，久则虑成损怯。", []], "10985": ["病机", "脉伏寒者，冲脉伏寒也；脉象虚弦，虚为产后正阴交伤，弦为肝木不主疏泄。伏寒内踞，肝失疏泄，则脘腹胀痛、痛甚肠鸣便泄、谷食不运，得嗳方舒。总由下焦空虚未复，寒凝气滞，故拟温通奇脉。", ["伏", "虚", "弦"]], "10986": ["预后", "原文未出脉，然“带下如注，方书谓之白崩”，乃八脉交伤、冲任不摄、阴精暴脱之候。病势急重，故曰“治之不易，徐图可也”，示预后缠绵，难求速效，当缓图固摄奇经。", []], "10987": ["预后", "原文未载脉象，然“漏久仍防暴行”，是久漏阴血耗伤，八脉无权，冲任不能约束，有暴崩之虞。故虑难调治，再拟益气摄阴，得效乃吉，明示病机为气虚不摄、奇经失约，预后当以能否摄固为断。", []], "10988": ["病机", "脉弦而带滑，弦主肝气结聚，滑主痰浊阴凝。肝气结瘕于少腹，状如鹅卵，夹冲脉之气上冲，则胸脘胀闷、谷食难下。浊阴凝互，气结痰阻，故虑有单腹胀之虞，病机在肝郁气结、浊阴不化。", ["弦", "滑"]], "10989": ["病机", "两脉弦涩，弦为气结，涩为血滞。脘中气结成痞，少腹血聚成瘕，从产脾伤，肿胀时轻时重，乃气血交病、脾运不健之候。弦涩并见，示气滞血瘀互结，故虑其增剧生变。", ["弦", "涩"]], "10990": ["病机", "脉象虚数，虚为血分不足、气虚带下，数为骨中烧热、五心作热。天癸先期而少，懊恼作烦，皆阴血亏虚、虚热内生之象。虚数并见，正虚而热浮，再延则防成损怯。", ["虚", "数"]], "10991": ["预后", "脉象细数无神，细为阴分大伤，数为热自内生，无神则正气亦伤。胎前咳逆带红，延及产后，又新加暑邪泄泻，邪少虚多，脾土亦亏。细数无神示胃气衰而虚热炽，故虑由暑盛而成损怯。", ["细", "数"]], "10992": ["病机", "脉虚弦而滑，虚为产后真阴未复、气血不足；弦主肝阳化风，故头眩耳鸣、心摇如悬、惊恐忧惧；滑主脾湿化饮，故多食善饥。三脉并见，说明产后虚损基础上肝风与脾湿交杂，证情变幻无常，治当缓图。", ["虚", "弦", "滑"]], "10993": ["病机", "脉弦数，弦主肝胆，数主热。热入血室而身反不热，是邪热内陷血分，与血相结，故神志不清、口苦、舌白。弦数之脉反映肝胆热盛、血室瘀热，谨防热陷心包而昏痉暴变。", ["弦", "数"]], "10994": ["病机", "脉数主热盛。内热未尽退而癸水适至，热入血室，故神志模糊、面赤谵语、入夜尤甚；中焦结痞拒痛、口苦而渴、舌干白苔淡黄、大便秘结、尿赤，皆热结阳明、血室瘀热之象。脉数示邪热鸱张，殊属险候，谨防昏厥暴变。", ["数"]], "10995": ["病机", "左右寸关脉数，寸关候心肺与脾胃，数主热。喉疳日久不愈，脉数显见心脾积热，从辛苦劳力而来，热毒上攻咽喉。故以黄连凉膈法清心脾积热，外用珠黄散掺之，以观进退。", ["数"]], "10996": ["病机", "脉数主热。温邪表尚未解，平素积劳伏火，因表邪沸腾而发，致舌本破烂、口干作臭、身热。脉数反映表邪与伏火相合，热势炽盛上炎。拟辛凉开泄法，使表解热清乃吉。", ["数"]], "10997": ["病机", "脉象沉细无神，沉主里、细主虚，无神为阳气衰败。肝旺胆怯、脾虚胃强，阴伤及阳，故两腿浮肿、腰下亦然、脘中懊𢙐、舌干而痛、大便不实、形气消索。此水溢高原、阳气式微之候，暂拟水火既济法以冀舌和。", ["沉", "细"]], "10998": ["病机", "脉弦细且滑，弦主肝郁，细主肝肾不足，滑主痰凝。素本肝肾不足，肝郁不舒，气滞痰凝，故两乳结核，左乳新起。脉象反映肝郁痰凝、本虚标实之病机，治当疏肝解郁、化痰散结，并嘱自开怀抱。", ["弦", "细", "滑"]], "10999": ["病机", "脉象浮虚，浮则为风，虚则气虚。脑漏多年，辛苦劳碌，风寒乘虚入骨空，故头元偏痛、筋脉牵掣、鼻窍渗涕；清阳不升、湿浊愈重，则舌本强硬、精神疲困、谷食减纳、苔腐腻。此气虚感风、清阳不升之候，宜安闲慎风。", ["浮", "虚"]], "11000": ["病机", "脉弦数，弦为肝旺，数为火炽。素本水不涵木，肝火过旺，外风触动，风火交煽，上攻头目，故右目红瘀、白翳满黑睛，右头角眉棱痛、不能安卧；口中作苦亦胆火之征。脉象弦数正合肝火风热之病机。", ["弦", "数"]], "11001": ["病机", "两脉弦数，弦主癖积内结、肝气不舒，数主热盛。癖积日久，劳倦引动，寒热往来、大便秘结，为少阳阳明合病，邪郁化热。脉弦数应解表通里之大柴胡法，通则不痛。", ["弦", "数"]], "11002": ["病机", "脉象弦涩，弦为肝郁，涩为营血亏少、络脉不畅。疟母多年，郁怒动肝，络血外溢，去血颇多，营分大亏，故心悸头眩、身倦肤黄。弦涩并见，示肝郁血亏、络瘀未清，治宜柔肝和营。", ["弦", "涩"]], "11003": ["病机", "脉象弦滑，弦主肝郁气滞，滑主湿凝痰聚。七情郁勃，肝失调达，脾失上升，胸脘阻塞，气滞湿凝。弦滑之脉正合肝郁夹湿之机，故宜安闲勿劳，佐药饵以疏肝运脾。", ["弦", "滑"]], "11004": ["病机", "两脉弦滑，弦为肝郁，滑为痰凝。肝郁夹痰，互凝中焦，上下不交而痞象成，胀痛并见，须哕吐痰涎或嗳泄方舒。脉弦滑主痰气交阻，若再操劳郁怒，有中满痰膈之虞。", ["弦", "滑"]], "11005": ["病机", "原文未识脉名，然述肝郁日久，气贯膈冲喉，湿痰凝互，项间瘰如串珠，气火化风上扰，阳明脉络不利。病从志内伤而起，肝郁气火夹痰为患，非旦夕可图功，戒怒远烦为宜。", []], "11006": ["病机", "两脉虚弦，虚为脾土不足，弦为肝木乘之。脾虚肝乘，致胸脘胀闷、时而热炽、寒热往来。脉虚弦正合土虚木郁之机，故用逍遥散加味，木郁达之。", ["虚", "弦"]], "11007": ["病机", "脉象弦细，弦为肝木侮土，细为营血不足。支饮入络，左胁痹痛，脘腹膨胀，面色痿黄，谷食少进，土败木贼之虞。弦细示肝郁脾虚、饮阻络脉，治宜徐图，戒怒远烦。", ["弦", "细"]], "11008": ["病机", "脉沉弦而滑，沉主里、弦主肝木乘土、滑主湿痰内蕴。原文谓「火不生土，木来乘之，土湿内困」，肝病善痛、脾病善胀，胀痛并见为肝胃不和；大便间或溏泻乃湿气下行。脉象正合肝郁乘脾、湿浊内困之机，故曰怡情善调可愈。", ["沉", "弦", "滑"]], "11009": ["病机", "两脉弦滑，弦为肝气横逆，滑为痰涎内聚。原文述肝气横久克脾犯胃，胸胀胁痛、脘中聚痞，遇烦劳悒郁则痛，哕吐酸水痰涎，皆肝胃气逆、痰浊上泛之候。脉弦滑正应气郁痰凝之机，故须戒怒远烦，以免阴枯阳结歧变。", ["弦", "滑"]], "11010": ["病机", "右脉细濡、左脉弦劲，细濡为脾土虚弱、气血不足，弦劲为肝木偏横。原文谓操劳郁怒，肝木克脾犯胃，土受水制而阳明脉虚，故肩臂酸痛引胁脘、嘈杂自汗、食入胀闷。左弦右濡正是肝强脾弱、虚实夹杂之象，宜安闲静养以免增剧。", ["虚", "细", "濡", "弦"]], "11011": ["病机", "脉象沉细，沉主里、细主血少，合原文「血不养肝，肝气横逆，脾土受侮」，脘痛作哕乃肝脾不和、血虚失养所致。延及年余，痛久入络，瘀血内阻，故脉沉细而不畅。此脉示血虚络瘀、肝横脾弱之机，故拟柔肝和脾合消瘀法治之。", ["沉", "细"]], "11012": ["病机", "脉象沉弦，沉主里、弦主痛主肝，原文谓湿郁化热袭入奇经，季腹下及腿胯渗入大肠，肛门裂痛后坠，痛甚肢冷，皆湿浊下注、气机郁滞之候。沉弦示湿郁于里、肝经气滞，痛甚肢冷为阳郁不达。再延防胃气大伤，致生枝节。", ["沉", "弦"]], "11013": ["病机", "脉弦自汗，弦主肝木、主寒湿内郁，自汗为阳气外泄。原文谓寒湿内伏，腹痛虽稀而寒热不清，舌黄口渴，乃寒湿郁久化热、邪踞少阳厥阴之界。脉弦应寒湿内伏、枢机不利之机，故拟乌梅丸温清并施，速解乃吉。", ["弦"]], "11014": ["病机", "脉象沉滑，原文自释「滑主多痰，沉主多郁」。抑郁伤肝，肝旺克脾，脾虚生湿，湿盛成饮，饮盛成痰，由肝传肺，痰气凝于右胁，故呼吸不利、困倦嘈杂。沉滑正合气郁痰凝之机，属肝旺脾虚之证，温凉皆不可，故兼而治之。", ["沉", "滑"]], "11015": ["病机", "脉浮滑带芤，浮为邪在肺卫，滑为痰湿内盛，芤主阴血受伤、脉道中空。原文谓操劳恚怒，肝气入肺，左胁痹痛、呼吸不利、寒热往来，兼烟热酒湿内发、咳痰味腥。浮滑示痰热壅肺，芤示络伤血动，故虑血涌肺胀暴变。", ["浮", "滑", "芤"]], "11016": ["病机", "淋浊日久伤肾，肾气不和，心肾不交则心烦不寐，络脉不通则腰间作痛、起坐方适。脉弦主气机郁滞、络脉不和，涩主精血亏耗、血行不畅，两脉合见，说明肾虚络阻、气血涩滞之病机，故以青娥丸补肾合宣络为治。", ["弦", "涩"]], "11017": ["病机", "颓疝虽轻而水饮留连奇经，肝肾受饮，痛自腰胯上攻关元，上攻则吐，阳气愈亏则水饮愈甚。脉沉主病在里、阳气不足，滑主水饮痰湿内停，沉滑并见，正合阳虚饮聚、肝肾受困之机，故拟方再进一筹以温阳化饮。", ["沉", "滑"]], "11018": ["预后", "寒邪直中厥阴，少腹作痛、囊缩茎短、厥逆上视，皆阴寒内盛、阳气欲绝之象。脉沉主病在里，迟主阳虚寒凝、气血运行无力，沉迟见于厥逆神昏之际，说明阴寒痼结、真阳衰微，故断为势属不治，姑拟四逆法以希万一。", ["沉", "迟"]], "11019": ["病机", "肝木横行克土，土虚不能制水，水饮痰热交致于中，故悸而未平、胀而尤甚，肢腿浮肿已有单腹之虞。脉滑主痰饮水湿内盛，弦主肝木亢逆、气机不畅，滑而弦正合肝旺克土、痰饮内聚之病机，故再拟方以冀挽回。", ["滑", "弦"]], "11020": ["预后", "休息痢三载，脾肺肾交亏，咳逆肿胀百余日，水臌已著。脉沉主病在里、脏气亏虚，弦主气机郁滞、水饮内停，涩主血少精伤、脉道不利，三象合见，说明脾肾衰败、气血涩滞、水湿泛滥，故断难以挽回，拟方以邀天相。", ["沉", "弦", "涩"]], "11021": ["病机", "由利而痢，里虚气分受伤，面浮肢肿、肚腹膨大、漉漉有声，乃水湿不从小肠分泄，内困脾土、外袭肌腠，兼暴怒伤肝、肝气上逆。脉弦主肝郁气逆、水湿内停，涩主气分壅滞、血行不畅，弦涩并见，说明肝脾不调、水湿内困，故有水膨之虞。", ["弦", "涩"]], "11022": ["病机", "挹郁伤肝，肝气犯胃，胃失下行，水饮停中，有升无降，故形气消索、面浮肢肿，已历载余，肝胃气血皆瘀。脉沉主病在里、气机郁滞，滑主水饮内停，沉滑并见，说明肝胃气滞、水饮停聚之病机，故恙有肿胀之虞，拟方尽人力而邀天相。", ["沉", "滑"]], "11023": ["预后", "饮食失节、寒温失宜致伤脾土，转输失其运用，浊阴内踞，已成腹胀大证。两脉俱弦，弦主气机郁滞、木旺克土，脾土既伤而肝木乘之，浊阴不化，故腹胀日甚。脉弦见于腹胀大证，说明土败木贼、浊阴内踞，故断难以挽回。", ["弦"]], "11024": ["主病", "脉弦为肝木乘脾之象，结合溺短、黄肿、脘腹膨胀，说明水湿不运、气机壅滞，已由产后失调、饮食失节致血稽留成瘕、聚痞，进而周身黄肿，属肿胀重症。弦脉主痛、主饮、主肝郁，此处提示肝失疏泄、脾不运湿，水谷之湿内停，故见溺短、肿胀。", ["弦"]], "11025": ["病机", "脉弦为肝气升而不降，涩为暑湿困脾、营卫不畅。原文谓“肝气上升，胃鲜下降，兼之暑湿困脾，中州痞塞”，弦涩相合，反映气机郁滞、湿浊内阻，故谷食不思、脘痞少纳。治以泻心法降阳和阴、佐宣湿，正是针对弦涩所主之肝胃气滞与湿困。", ["弦", "涩"]], "11026": ["病机", "脉弦主肝气郁滞，涩主营卫不畅。原文“肝胃气滞，滞久聚痞，脘中作痛，营卫两虚，为寒为热”，说明气滞日久，营卫失和，故见寒热、脘痛。弦涩并见，提示气结血滞、虚实夹杂，故曰“治之不易，徐图可也”，非急攻所能取效。", ["弦", "涩"]], "11027": ["预后", "原文未识脉名，仅言“脉象略起”，属动态观察。结合气短咳逆、足跗肿、脘痞结、三焦不通，灸后得痰咳平而脉略起，说明痰湿暂开、气机稍通；然“上下皆虚，中空独实，攻补两难”，脉起仅为暂效，证势岌岌可危，预后堪忧。", []], "11028": ["主病", "脉弦主邪滞互结、气机不畅，数主邪热未清。原文“由利而痢，表邪未清，胸痞已著，按之触手而痛，邪滞互结”，弦数反映表邪入里、滞热相搏，故胸痞拒按。法当先治外邪，即从弦数所主之邪热壅滞着眼，先解表清邪。", ["弦", "数"]], "11029": ["预后", "脉细弱如丝，为气血大虚、阳气欲脱之象。原文“肺脾两伤，气短似喘，胸次结痞，按之拒手，两胁作痛，足跗皆肿”，人虚病实，攻补两难；细弱如丝提示正气衰微，有外脱之虞，故勉拟灸法，并嘱小暑加意提防，预后险恶。", ["细", "弱"]], "11030": ["病机", "原文脉象“左大于右”，左脉候肝、右脉候肺脾，左大于右提示肝气偏亢、气结于中。结合七情不适、吸受新凉引动伏邪，身热不清、脘腹痞痛拒按、思饮作哕，说明气郁化热、邪滞中焦，正虚邪盛，故深虑“正不敌邪，致生歧变”。", []], "11031": ["病机", "脉弦为肝气横逆，滑为痰湿内蕴。原文“肝肾不足夹湿之体，肝气横逆，克脾犯胃，致清阳莫续”，故脘闷食阻、哕吐酸沫、痰涎上泛；弦滑相合，正示气逆痰阻、湿浊中阻，肌肉日瘦、精神日疲为久病耗伤，故虑入神思间病。", ["弦", "滑"]], "11032": ["病机", "脉沉弦者，沉主里、弦主肝，为肝气郁结、肺气不降之象。原文谓升降失常、食入作阻，阴络受伤便血，久则液枯气结，有关格之虞。沉弦示气机郁滞于里，肝木失疏，肺金不肃，故食阻、便血，进而津枯气结，格拒不通。", ["沉", "弦"]], "11033": ["病机", "脉弦细而滑，弦为肝郁，细为阴血不足，滑为痰聚。原文谓命火不足不能生土，抑郁动肝，肝木侮土，饮食不归正化，蒸变为痰，痰与气搏，升降失常，食入则阻，兼脾泻肌瘦。弦细滑正合肝郁脾虚、痰气交阻之机，久则气结津枯。", ["弦", "细", "滑"]], "11034": ["病机", "脉细滑，细示胃气不足、阴血偏少，滑主湿痰内蕴。原文谓肝胃不和，胀痛呕吐，甚则食入反出，有反胃之虞。细滑说明胃虚而痰湿中阻，肝气犯胃，胃失和降，故胀痛呕逆，食入反出，为反胃之渐。", ["细", "滑"]], "11035": ["病机", "脉细滑，细为营卫不足，滑为湿痰内困。原文谓肝阳扰胃、湿痰困脾，营卫不和，时寒时热，哕吐频作，头目不清，身倦神疲。细滑正示脾虚湿痰内盛、肝阳上扰，营卫失和，故寒热哕吐并见，当徐图调治。", ["细", "滑"]], "11036": ["病机", "脉弦滑，弦主肝气偏旺，滑主痰涎内盛。原文谓肝气犯胃，胃失下行之顺，哕吐涎沫，若不速图有反胃之虞。弦滑说明肝木横逆、痰浊中阻，胃气上逆而不降，故哕吐涎沫，久则恐成反胃。", ["弦", "滑"]], "11037": ["病机", "脉细濡，细为阴阳两虚，濡为脾弱湿滞。原文谓体质素虚，脾虚胃弱，夏秋感受外邪，吐泻不已，风寒虽解而呕吐未止，手足蠕动。细濡示脾胃虚衰、津液耗伤，虚风内动，故防呕久胃伤而生枝节，用附子粳米汤温中降逆。", ["细", "濡"]], "11038": ["病机", "本段未识脉名，纯论病机。原文谓肝强脾弱，脾不能为胃行其津液，蓄而为饮，食入不运，脘中嘈杂，哕吐苦水；又脾脉连肾，肾为胃关，遗滑频见，怠惰嗜卧，日晡潮热。此示肝脾不调、饮停中焦，兼肾关不固，故先理肝脾佐以摄肾。", []], "11039": ["预后", "两脉虚弦，虚为营卫两亏、肺肾俱虚，弦为肝木偏旺。原文谓久咳不已，肺虚不能下荫于肾，肾虚子盗母气，寒热往来，遗泄频频，劳瘵已著。虚弦示正虚而木旺，金水不能相生，故劳瘵已成，预后堪忧，拟金水同治。", ["虚", "弦"]], "11040": ["病机", "脉虚弦而数，虚为营卫两亏、亡血过多，弦主肝木失养、气机郁滞，数示虚热内生。子嗽延及产后，下损从阴，上损从阳，寒热不止、咳逆食减、肌肉消瘦，皆由营卫两亏、虚风内动所致。脉象虚弦而数，正合损怯之势已著，故拟金匮麦冬法以养阴清热。", ["虚", "弦", "数"]], "11041": ["病机", "脉象虚弦，虚为心脾两虚、中气不振，弦主悲郁伤中、肝木乘脾。先后天不足，经营操劳，悲郁伤中，致心悸肉𥆧、食入易汗、卧不安眠，皆情志两伤、气血失和之候。脉虚弦应其虚而兼郁，故曰情志两伤之病，须自开怀抱、安闲静养，药饵方能兼功。", ["虚", "弦"]], "11042": ["病机", "脉象虚数，虚为营卫交亏、阴不内守，数主虚热内扰。郁怒伤肝，木扣金鸡，致乍寒乍热、癸水淋漓，乃肝郁化火、阴血暗耗之象。脉虚数而损怯根基已露，说明正气已虚而虚热未清，故当安闲静养，佐以药饵，方可化凶为吉。", ["虚", "数"]], "11043": ["病机", "脉象弦数，弦主木扣金鸣、肝郁化火，数主热伤肺络。络伤血溢日久，营卫失职而为寒热，肺阴不降则咳吐涎沫、谷食减纳、面热颧赤。弦数并见，示肝火灼金、阴液渐亏，故曰欲入损怯之途，当及早清肝保肺、养阴和络。", ["弦", "数"]], "11044": ["病机", "脉弦细而数，弦主肝木肆虐、顺侮土位倒克肺金，细为营卫两虚、诸虚毕集，数示虚热内扰。居经三月，血不养肝，痰饮内扰，致懊𢙐难名、咳逆气促、痰中带血、胸胁胀痛、寒多热少、自汗心悸头晕。脉弦细数，久虚不复防成损怯，然此际不可遽作怯证治。", ["弦", "细", "数"]], "11045": ["病机", "两脉细数，细为水亏于下、阴血不足，数主火炎于上、虚热内炽。水不济火，则咳逆失红、音哑侧眠、骨中蒸热，皆阴亏火旺、肺肾两伤之候。脉细数而劳怯之基已著，说明下虚上盛、真阴耗损，故拟方多酌高明，以图救阴清热。", ["细", "数"]], "11046": ["病机", "脉弦细而数，弦主肺肾两虚、宿饮上干，细为形气消索、脾亦受累，数示虚热内动。阳络先伤、阴络后继，致大便不实带血、脱肛痔疮、面目痿黄、谷食减少。脉弦细数，说明虚损及脾、饮热交织，再延日久防成虚劳肿胀，故慎之。", ["弦", "细", "数"]], "11047": ["病机", "脉象弦数，弦主木火凌金、肝郁化火，数主热多寒少、虚热内扰。小产后正阴未复，脾虚湿甚，致咳逆频来、面色痿黄、心悸，诸虚毕露。脉弦数示阴虚火旺、脾弱湿滞，难以痊愈，故勉拟一方尽其人力，以养阴清肝、健脾化湿。", ["弦", "数"]], "11048": ["病机", "右脉虚数，虚为津液不足、脾胃虚弱，数为虚热内扰。痰饮年多耗伤津液，脾胃不降则咳哕、谷少；虚数之脉反映气阴两伤、虚热内生，故身热潮热，已属损怯之象，需安心静养防变。", ["虚", "数"]], "11049": ["病机", "脉象弦数，弦主肝木偏横、气机郁滞，数主化火生风。先后二天不充，操劳悒郁致心肾不交、精关不固；肝郁化火则脘痛嘈杂、面热头晕。弦数并见，示肝火内动、阴精耗损，虑延损怯。", ["弦", "数"]], "11050": ["病机", "脉象滑数，滑主痰热内蕴，数主火盛。肝郁化火，热伤阳络则络血外溢；营卫致虚故日晡寒热、头眩心悸；火升面热、谷食不运，皆痰火内扰之征。滑数脉示热炽痰壅，损怯之象已见。", ["滑", "数"]], "11051": ["病机", "脉象弦数，弦主肝郁阴伤，数主伏邪化热。小产后伏邪伤阴，咳逆吐沫、骨中烧热，恶露淋漓、少腹胀痛，皆阴亏热扰、肝郁不疏之候。弦数示邪热内炽而阴液耗损，由外感成内损，难以调治。", ["弦", "数"]], "11052": ["病机", "脉象弦细，弦主气滞血瘀、络脉不和，细主阴血不足。素本气滞血瘀，暑湿伤络致络动血溢，弦细反映瘀滞与阴伤并存，络脉受损而血不循经，故需徐图调治。", ["弦", "细"]], "11053": ["预后", "脉尚细软与症相合，细软为气血不足、络脉受损之象。阳络受伤，血随火溢，咳逆二年，肺气受戕，时有梦遗，示气阴两亏。脉症相符，预后尚可，惟近夏至大节，需预为防之。", ["细", "软"]], "11054": ["病机", "脉象滑数，滑主痰热壅肺，数主火邪内炽。肝邪入肺，咳久化热，右胁痹痛、痰中带血，皆痰火伤络之征。滑数脉示热痰胶结、肺络受损，虑其成痿，当清化痰热以保肺金。", ["滑", "数"]], "11055": ["病机", "脉象沉弦而数，沉主病在里，弦主肝郁气滞，数主热伤血络。二天不足，酒伤肺络，咳血频来，肺肾交亏则气短；咳血前脘痛，乃肝郁化火、气逆动血。沉弦数示里热郁结、阴血耗伤，防成虚劳。", ["沉", "弦", "数"]], "11056": ["病机", "脉弦为肝郁化火、木火凌金之象，数则阴亏内热。原文述惊恐伤胆、抑郁动肝，木火刑金致咳逆作哕、痰中带血，肺阴交亏而侧眠于右，心悸头眩。弦数并见，示肝火未息而阴分已伤，久虚不复，故虑成损怯；然又不可遽以损怯实治，正因虚中夹火、本虚标实。", ["弦", "数"]], "11057": ["预后", "脉细为阴血亏少、形气消索之征，数为火旺内热之象。原文木火凌金、咳逆不已，阳络受戕而血随火溢，阴分日亏则脉道不充故细，火势内炽故数。细数并见，正合形气消索之候，故断延久恐成损怯，示阴亏火旺之势难以骤复。", ["细", "数"]], "11058": ["病机", "脉细主阴分受伤，数主内热频来，弦则木扣金鸡、肝气上逆之象。原文络伤血溢、肾不纳气、动则气短，皆阴亏于下、肝火扰于上所致。细数而弦，示虚火未清而气逆血溢之势尚存，故防其涌溢生变，即防血随气火上冲更甚。", ["细", "数", "弦"]], "11059": ["治法", "脉细为阳气素亏、气血不足，濡主脾经多湿、阳不卫阴。原文哕血颇多、入暮尤甚，乃阳虚不能摄血、湿浊内困之候。细濡并见，正合阳亏湿盛之机，故虑其外脱，拟仲圣柏叶汤温阳摄血以冀挽回，是凭脉定治法之例。", ["细", "濡"]], "11060": ["病机", "脉弦滑主肝胆郁而痰饮内聚，沉细则示阳虚于里。原文惊恐伤胆、抑郁动肝、思虑伤脾，谷食不化变蒸为痰，痰饮袭奇经溢四末，致肩井如折、肢体麻木、咳逆气促。弦滑沉细正合始于肝胆、中于痰饮、终于阳虚之论，体虚症实，攻补两难。", ["弦", "滑", "沉", "细"]], "11061": ["病机", "脉沉主水饮停中、阳气不布，弦为木来乘土、肝气攻冲之象。原文火不生土、水饮停中、痞结攻冲、吐痢并见，皆阳虚而肝木犯胃所致。沉弦并见，示病本在阳虚水停而标在肝逆，故云症属阳虚气不虚，转机系于夏至一阳初生，拟柔肝和胃以候时令阳生。", ["沉", "弦"]], "11062": ["兼症", "脉浮在此非表证，乃假火浮于上之象。原文烦劳伤气、急躁伤肝，命门火衰而火不生土，湿痰入络、水饮停中，致肠鸣漉漉、攻冲作痛、哕吐清涎；真阴亏于下故小溲不多，假火浮上故时而嘈杂。舌白脉浮，正合虚阳上浮、胃虚食少脾虚神疲之兼症，故拟方速退乃吉。", ["浮"]], "11063": ["病机", "脉弦为肝气易升、木火体质之征，数为胆腑失清、火郁于内，心脉较大则火扰心神。原文善怒多郁，致头目眩痛、心悸作烦、手足蠕动，皆肝阳化火、风动于内之候。弦数而大，示木火偏亢、风阳上扰，故务宜安闲静养，以免酿痰歧变。", ["弦", "数", "大"]], "11064": ["病机", "脉弦滑，弦主饮邪内结，滑主痰湿壅盛。原文谓“积湿成饮，积饮成痰”，痰饮伏于肺胃，故每早痰涎出方适；痰饮流窜肌肤则瘾疹屡发，上蒙清阳则头眩身倦。脉象弦滑正合痰饮内伏之机，主病为痰饮，与咳痰、瘾疹、头眩身倦相应。", ["弦", "滑"]], "11065": ["病机", "脉滑数异常，按之舞指，滑主多痰，数则为热，故主痰热内蕴。原文谓“痰热窠囊已固”，服十枣丸未效，虚里穴动而应手，面色鲜明为饮，皆痰热胶结之征。此脉象说明痰热深伏难化，主病为痰热窠囊，与虚里跳动、面色鲜明相应。", ["滑", "数"]], "11066": ["病机", "脉弦滑，弦为肝旺，滑为痰热。原文谓“肝旺胆虚，痰热内忧”，痰热扰于胆腑，故喉间不利、胸中懊𢙐、多疑善虑、梦寐不安、神思恍惚。脉象弦滑正反映肝旺痰热之病机，主病为痰热内扰、肝胆不和，与情志不宁、睡眠障碍相应。", ["弦", "滑"]], "11067": ["病机", "脉沉滑，沉主里主虚，滑主痰。原文谓“上实下虚”，痰热内扰，故胸中懊𢙐嘈杂、头目眩晕、舌蹇便数、少腹膨胀、睡卧不安。沉滑之脉说明痰热深伏于里，心肾不交、肝胆不和，主病为体虚痰热内扰，与类中之虞相应。", ["沉", "滑"]], "11068": ["病机", "脉弦滑而数，弦主气火，滑主痰，数主热。原文谓“气化为火，液化为痰，痰热内扰，蔓延经络”，故遍身脉络酸楚、头目时眩、胸中嘈杂、寤不成寐、癸水愆期色紫。脉象说明痰热化风上腾之病机，主病为痰热内扰、冲任失调，与不孕、肢痛、失眠相应。", ["弦", "滑", "数"]], "11069": ["病机", "脉弦细而滑，弦主肝郁，细主营虚，滑主痰凝。原文谓“操劳过度，内郁生痰，痰凝清道”，故右肢麻痹、肩臂不适、寤不成寐、思虑纷来、天癸未期而至。脉象说明痰凝络阻兼营虚之病机，主病为痰凝清道，与肢麻、失眠、月经先期相应。", ["弦", "细", "滑"]], "11070": ["病机", "脉沉弦而滑，沉主里，弦主饮，滑主痰。原文谓“素有支饮咳喘”，产后百脉空虚，饮邪乘虚留连经络，故指臂腰腿痛；痰中带血丝，络中有热。脉象说明饮邪深伏、虚实夹杂之病机，主病为支饮留络，与咳喘、肢痛、痰血相应。", ["沉", "弦", "滑"]], "11071": ["预后", "脉弦软无神，弦主饮邪，软主正虚，无神为胃气衰败之象。原文谓“宿饮射肺，咳经日久，饮邪入络”，故遍身麻痹、两臂作痛。脉象说明饮邪未去而正气已衰，防成类中，主病为饮邪入络、正虚邪恋，与麻痹、臂痛及类中风险相应。", ["弦", "软"]], "11072": ["病机", "两关弦细，弦主肝郁，细主血虚。患者痰饮多年，肺脾肾虚，情怀挹郁，肝失调达，血不荣络，湿痰乘虚袭入，故见四肢麻、肤肿筋痛、右胁气逆。脉弦细正合肝郁血虚、湿痰阻络之病机，虑有仆中之虞。", ["弦", "细"]], "11073": ["病机", "脉象细滑，细为气虚，滑为湿痰。体丰气虚多湿多痰，阳明脉虚，虚里穴动，四肢酸软，气虚不能传送则大便难、谷食不甘。脉细滑反映气虚痰湿内蕴之病机，所虑类中。", ["细", "滑"]], "11074": ["病机", "脉浮而数，浮主邪在表，数主热盛。症见齿垢舌黄、热壮汗少、腹硬而痛、屡圊便少，为伏邪为患，邪热郁于表里。脉浮数说明邪热有外达之势，故可汗；腹硬痛便少，可下。治以辛凉开表、微苦通里。", ["浮", "数"]], "11075": ["病机", "脉形细数，细为阴伤，数为热盛。暑湿伏于募原，盘踞阳明，随卫气出入，故汗出不快、神倦懒语、有时谵言。脉细数反映暑湿未化、阴液已伤之病机，病经十七日，正虚邪恋。", ["细", "数"]], "11076": ["病机", "左部见弦，右手濡数。弦主少阳，为转疟之势；濡主湿，数主热，湿滞于胃。暑湿内伏，秋凉引动，病于少阳则疟，病于阳明则呕哕烦闷胸痞。脉象示邪踞少阳阳明，湿遏热伏之病机。", ["弦", "濡", "数"]], "11077": ["病机", "六脉濡数而浮，濡主湿，数主热，浮为虚阳外越。暑湿内陷，中阳式微，砥柱无权，故神识昏迷、谵语无音、面色青晦、热不外扬、渴不多饮。脉象反映正虚邪陷、湿浊蒙蔽之病机，危笃之候。", ["濡", "数", "浮"]], "11078": ["病机", "脉来濡滑而数，濡主湿，滑主痰，数主热。伏暑内蓄，邪与卫气并居，随卫气出入，故热仍夜甚、烦闷干哕、脘腹板痛、遍体透斑。脉濡滑数反映暑湿痰热内蕴、邪伏募原之病机，斑色晦青不泽非佳兆。", ["濡", "滑", "数"]], "11079": ["病机", "脉象仍带滑数，滑主痰积，数主热盛。昨用大黄黄连合犀角大青法后，便已数行，腹硬较软，斑色红稍退，但脉仍滑数，舌淡黄露底、红刺密布，说明肠胃积滞下而未清，阴液日伤，邪热未净之病机。", ["滑", "数"]], "11080": ["病机", "左手弦数，右部濡滑。弦为肝脉，数主热，濡滑为湿痰。原文谓“脉见弦数者，肝脏病也”，又见“腹撑便泄，火升面赤”，乃木克土位，胆脾不能，故脉象反映肝胆气火偏旺、脾湿内蕴之病机。", ["弦", "数", "濡", "滑"]], "11081": ["病机", "左关独弦，右寸微滑，右关软濡。原文谓“肝胆气火有余”“肺经素有贮痰”“脾胃运纳无权”，弦主肝火，滑主痰，濡软主脾虚。诸脉合参，示心肾不足、肝火脾虚、痰贮于肺之病机。", ["弦", "滑", "濡", "软"]], "11082": ["预后", "脉来细弦，右尺虚散。细弦为脾肾两伤、阴血不足，虚散为肾阳衰微、元气不固。原文谓“泄之不休，将及两月”“已有药不胜病之忧”，又见咳嗽气促，肺金再伤，故脉示脾肾两亏、肺金受损之预后不良。", ["细", "弦", "虚", "散"]], "11083": ["预后", "六脉细数不耐重按。细为元正不足，数为邪热内郁，不耐重按示虚象显著。原文谓“正元素乏”“邪内郁而不得外达”“从虚而恐致内陷”，脉象反映正虚邪陷之机，预后堪忧。", ["细", "数"]], "11084": ["预后", "脉缓而胸次开展。缓为胃气调和之象，原文谓“无一不是佳景”，示暑湿渐解、气机舒展。惟“腑道日久未通，脐间自觉阻滞”，脉缓主病退，但宿垢未去，故为佳景中寓有里实未通之机。", ["缓"]], "11085": ["病机", "脉象滑数。滑主痰，数主热，原文谓“暑湿入里，湿为热蒸成痰，暑为痰遏难解，痰热迷窍，秽浊上蒙，直迫心包”，故脉滑数反映痰热内闭心包之病机，症见神识不慧、糊语不休。", ["滑", "数"]], "11086": ["预后", "脉来浑滑而带数。滑主痰，数主热，原文谓“暑邪发于募原”“积滞内阻”“痰蒙宫城”，脉象示痰热积滞内闭。又见面色青晦，厥阴所主，故预后险恶，恐有“非常之变”。", ["滑", "数"]], "11087": ["病机", "脉数已和，滑象未退。数脉渐和示邪火渐息，滑象未退示痰滞未清。原文谓“邪火渐息，痰滞未清”，故脉象反映经热渐解而腑积痰滞尚存之病机，症见神迷好卧、脐右按痛。", ["数", "滑"]], "11088": ["病机", "脉象小数，数主热，小主虚。患者年高气液本虚，暑湿成瘅疟，热势虽衰未清，脉小数示虚多实少、正负于邪。舌光红、神识不清、口渴喜饮，为液亏暑化、胃气不振之象，故脉小数为气液两伤、余邪逗留之病机。", ["小", "数"]], "11089": ["病机", "脉浑滑而数，滑主痰湿内蕴，数主热。瘅疟由暑湿内伏募原，新寒新积触发，暑湿化热蒸痰，故脉滑数。胸闷烦躁、呕恶、苔黄厚腻、数日未便，皆暑湿内蕴、胃受病而气血不得流之征，脉象正合邪伏募原、郁而化热之机。", ["滑", "数"]], "11090": ["病机", "六脉沉而微形弦数，沉微主阳气郁伏，弦数主热动肝风。小儿纯阳之体，误捂受热，惊则气乱阳升，闭则气窒阳伏，故脉沉微；热甚动风，故弦数。惊搐、气升痰鸣、肢冷面青、目直视，皆惊闭之候，脉象示热闭于内、阳不外达之病机。", ["沉", "微", "弦", "数"]], "11091": ["病机", "脉弦数而带滑，弦主风、数主热、滑主痰。风温日久，浊邪未清，余烬复焰，邪积夹痰互阻肺胃，郁蒸化热，蒸痰动风。风藏于肝，痰生于胃，胃气不降，风火上升，故脉弦数滑。惊厥、手搐目窜、神识未清，正合痰热动风、蒙蔽机窍之病机。", ["弦", "数", "滑"]], "11092": ["病机", "原文未识脉名，仅言气阴俱伤。乳儿痃疟延久，又染风温顿咳，热甚发惊厥，搐搦反张。气伤则络脉空乏，阴伤则木失涵养，化风火夹痰浊蒙窍袭络。所谓邪行如水，虚处则受，脉象虽缺，病机为气阴两伤、虚处受邪、痰火蒙络。", []], "11093": ["病机", "脉细数无神，左手搏指。细主虚，数主热，无神为正气衰败。多病多虚之体患风温，热退咳平而面红转白、神识不慧、糊语，分明邪乘虚陷、痰蒙内窍。脉细数无神示正虚邪陷，左手搏指为邪实内搏，势属至危，故云虚人善变。", ["细", "数"]], "11094": ["预后", "脉细若无，舌光泽不红，言语声气不续，此名脱。脉未躁疾、汗未全冷，示阳气虽欲离阴飞越，阴精尚有涵养交纽。脉细若无为阴精耗竭、阳气欲脱之兆，然未至躁疾，犹存一线生机，故曰本无治法而勉拟敛摄补益，终归于脱。", ["细"]], "11095": ["病机", "六脉濡数而浮，濡主湿，数主热，浮主邪在表。伏暑夹湿，湿伤气，暑伤寒，中阳式微，砥柱无权，暑湿不能达外反致内陷。神识昏迷、谵语、面青晦、苔灰黄似腐、热不外扬，皆暑湿内陷、阳气不支之候，脉濡数浮正合湿遏热伏、正虚邪陷之机。", ["濡", "数", "浮"]], "11096": ["病机", "脉形濡滑浑数，重按无力，为暑湿积滞内蕴、正气已伤之象。濡主湿，滑主痰积，数主热，重按无力示正虚。原文谓“暑、湿、积三者已属鼎足之势”，热恋不退、汗不通体、咳嗽痰黏、脘腹板硬，皆暑湿积滞化热、壅阻气机所致，脉症相符。", ["濡", "滑", "数"]], "11097": ["病机", "脉来郁涩而数，左部带弦，为浊邪化热、情怀悒郁、木不条达之象。涩主气滞血郁，数主热，弦主肝郁。原文谓“浊邪交蒸化热，兼之情怀悒郁，木不条达，亦易化火”，充斥肺胃，蒸浊成痰，消灼阴液，故见热恋不退、咳嗽痰黏、舌底光红干碎，脉症相应。", ["涩", "数", "弦"]], "11098": ["病机", "脉来弦滑而数，为暑湿内蕴、新寒新积触发、邪伏募原之象。弦主邪遏气机，滑主痰湿积滞，数主热。原文谓“邪伏募原，气为邪遏不得外越”，故寒热起伏、烦闷胸躁、渴难多饮，舌苔厚黄而腻，脉症合参，示暑湿积滞交阻、气血不得流畅。", ["弦", "滑", "数"]], "11099": ["病机", "脉来弦滑而数，为暑邪内伏募原、寒滞盘踞阳明、元海不藏之象。弦主邪郁，滑主痰湿积滞，数主热。原文谓“夏令之暑邪内伏募原，新伤之寒滞盘踞阳明”，又谓“当脐乃少阴地位，显系元海不藏”，故见热势起伏、烦懊胸闷、当脐跳跃，体虚症实，脉症相符。", ["弦", "滑", "数"]], "11100": ["病机", "脉象右手沉实，为暑湿壅积、中焦运化失司、浊气在上之象。沉主里，实主邪壅。原文谓“邪湿既不能达，自然壅积为内伤脾土，中焦运化之机乃息”，故腹胀、得食脘痛、手按辄拒、舌苔浊腻、大便艰行，右手沉实正合邪实内壅之机。", ["沉", "实"]], "11101": ["病机", "脉来滑数而弦，为暑湿伏邪归入阳明、与积合病之象。滑主痰湿积滞，数主热，弦主邪郁。原文谓“胃腑伤积，所以甫发即阳明与积合病”，故入暮肢寒继热、烦懊头晕、腹满硬、便行稀水，舌苔黄腻，脉症合参，示暑湿积滞交蒸阳明。", ["滑", "数", "弦"]], "11102": ["病机", "右脉濡小，为暑湿伤气、肺胃气分受困之象。濡主湿，小主气弱。原文谓“体肥则中气必弱，暑湿亦伤气分”，又谓“暑欲化火化燥而不果者，湿遏故也”，故鼻窍霉黑、胸痞烦闷、舌苔灰霉、渴饮脘痞，右脉濡小正合气分湿遏之机。", ["濡", "小"]], "11103": ["预后", "左脉弦数，右手更甚，为暑湿积滞虽分化而中土气阴已败之象。弦主肝木乘土，数主热，右手更甚示脾胃受病尤重。原文谓“中土气阴已具败变之象”，又引叔和“胃见肝脉，木假”，故纳不加、急重不除、四肢牵振、遍体汗出、时见呃忒，脉症示预后堪忧。", ["弦", "数"]], "11104": ["预后", "脉象仍见弦数，说明痢久阴伤、元气未复，弦主肝郁土虚，数主阴亏内热。虽便行成粪、腐苔化去，但阴液难复、元气难回，故自觉烦躁、口渴喜饮，尚在险津。脉症合参，中土弊败，药力难施，预后堪忧。", ["弦", "数"]], "11105": ["病机", "脉细数少力，细为阴血不足，数主邪郁生热，少力示本质素亏。停饮内伏，外感风邪，表气束缚，邪郁络阻，左胁作痛；邪热与痰积交蒸，扰乱神明，故言语错乱、大便不解。此风温夹积夹痰，将显伤阴劫液之象。", ["细", "数"]], "11106": ["病机", "脉象过数，数主热盛，风燥阳邪自伤肺经，热势重而脉数，咳嗽甚而舌苔黄浊。肺病毕具，鼻窍扇动、但坐难卧，痰积相互而闭，里痹表郁则动风生惊，气升喘促，此夹惊肺胀之候，脉数正示邪热鸱张。", ["数"]], "11107": ["病机", "脉形濡数而实，濡主湿滞，数主热，实主积滞内阻。湿热食积阻于回肠屈曲之间，伤血则痢红胜于白、竟有形块，脾土无消运之权，肠金乏传导之官。脉实示邪实急，故先治其实，假法于一下，湿滞分消则痢止痛停。", ["濡", "数", "实"]], "11108": ["病机", "吐血虽止，脉尚带数，数主气火未熄。阳络伤则血外溢，所动之由气与火也，阴络固静而气火未熄，故脉数。宜安养以待其复，倘经营操持，必致由伤而损、自损成痨，脉数正是气火未平之征。", ["数"]], "11109": ["病机", "脉来滑数，滑主痰浊，数主热。痧从风温而成，肺居上焦首先受邪，气道愤郁，浊聚成痰，逆而不降，故喉间痰声漉漉、气粗如拽锯，舌苔黄腻而厚，已成肺胀重症。滑数之脉正示痰热壅肺、邪浊内盛。", ["滑", "数"]], "11110": ["病机", "脉形小而无力，小为气血不足，无力为脾胃虚弱。便泄气滞溲清、舌淡面色无华，皆中焦为贼蹂躏、仓廪久乏积贮之故。五谷入胃磨运在脾，脾虚则清浊不分，诸经失灌，故脉小无力，主脾胃虚衰。", ["小", "无", "力"]], "11111": ["病机", "脉象濡数，濡主湿浊，数主伏暑之热。平素痰浊与积为伍，伏暑之邪喜入心，心经神血虚则内走尤易，脾脏浊痰不化则窒塞益甚。故神识糊涂、呃逆频频、舌苔黄霉、大便溏薄，痰湿蒙蔽上中清旷之地，脉濡数正合湿浊伏热之机。", ["濡", "数"]], "11112": ["病机", "脉象糊闷而数，糊闷示湿浊痰热蒙蔽清窍，数主邪热内盛。原文谓汗后热势已解大半，而左胁胸膺呼吸皆痛，舌苔淡黄而厚，是邪热因汗稍达而气闪于肝络不和，故脉数应邪热未清，糊闷应痰湿阻络、气机不畅，与言语糊涂、胁胸痛相应，属温邪在肺、闪气在肝之病机。", ["数"]], "11113": ["病机", "右寸弦涩，右寸候肺，弦主气郁、饮邪与痛，涩主血行不畅、痰浊阻滞。原文述伏气暑湿夹积，神识昏糊、不语、热势内炽、腹板硬拒按、咳嗽不扬而声被痰黏，是痰热积滞壅阻肺胃、气机闭郁，故右寸弦涩，与肺气不宣、痰黏咳声不出相应，示邪实内闭之病机。", ["弦", "涩"]], "11114": ["病机", "脉弦而右实，弦主肝郁气滞、痛证，右实主里实积滞。原文疟变痢，腹痛攻撑、里急后重、舌淡黄厚浊、纳少哕恶，又加郁怒与食物不谨，是伏暑湿浊夹积滞壅阻肠腑、肝气攻撑，故脉弦而右实，与腹痛后重、寒热未罢相应，示里实壅滞、恐有猝变之险。", ["弦", "实"]], "11115": ["病机", "六脉虽一尚嫌弦大，弦大为阳亢不潜、阴不敛阳之象。原文述得食腹胀、交寅虚火上炎、晨咳甚汗泄，断为阴分日虚、阳不潜藏；年逾五旬脏气渐衰，时届秋冬，阴竭于下则阳炎于上。脉弦大正是阴虚阳浮、肝阳不藏之征，与虚火、咳汗相应，故治法主阴充阳潜。", ["弦", "大"]], "11116": ["病机", "脉来濡滑而数，濡主湿、滑主痰、数主热，合为湿热痰浊内蕴之象。原文谓久居湿地，湿阻脾络，两足酸重、上举无力、舌厚白腻、咳嗽痰沫、小溲浑浊，是湿浊困脾、肺气不宣，湿郁化热故数。脉与湿阻脾络、清旷失司之病机相应，尚未成痛痹。", ["濡", "滑", "数"]], "11117": ["病机", "原文仅言脉象似大于前，未识具体脉名，故脉素从缺。脉大于前示邪势未衰、正气尚能抗邪。述湿浊内阻，营卫失于流利，经络窒痹，牵掣转侧维难，咳不扬痰黏，脘痞便未行，舌苔化半而烦懊得汗不畅，是湿浊踞中脘、脾胃通运失权之病机，脉大与浊滞未化相应。", []], "11118": ["病机", "脉来细弦，细主阴血亏少、正气不足，弦主肝脾不和、痛泄；右尺按之虚散，右尺候肾，虚散为肾气不固、命火式微。原文泄及两月、饮食日减、心荡颧赤、舌淡红布白疳，又增咳嗽气促，是脾肾两伤、土不生金，故脉细弦而尺虚散，与久泄纳减、虚风内动相应，示药不胜病。", ["细", "弦"]], "11119": ["预后", "脉来细数，细为阴血不足，数主虚热或郁热。原文闺秀十四，肝气常郁、肺气不宣，藏统失职，冲任贮少，致一潮即止，大腹旋满，已见忌款，药恐难图。脉细数应阴血亏虚、郁热内生，与经少腹满相应，示冲任虚损而郁热未清，故断为难图之预后。", ["细", "数"]], "11120": ["病机", "原文“右脉稍扬，左关尚弦”，左关候肝，弦为肝脉，故“肝阳未平”；右脉稍扬提示肺气少宣。肝木无制则风阳上腾，肺金不能制木则子气亦衰，病非六淫外感，乃脏腑气机失调，故效不能速。", ["弦"]], "11121": ["病机", "吐血大势虽定，而“脉来数大不靖”，数主热，大主邪盛，脉不靖为火热内扰之象。舌苔淡黄亦属热征。五志之火内炽，蒸灼肺经，肺络受损则吐血，此脉示火未清、病本在脏志化火。", ["数", "大"]], "11122": ["病机", "大疟五旬，脘胀痞痛而呕、汗少不便，脉数舌黄，为邪积阻痹气机，郁而化热。数脉主热，邪积内阻则气机不通，故见胀痛呕逆；热郁于里，汗少便艰，防其昏闭之变，乃邪热内陷心包之虞。", ["数"]], "11123": ["病机", "左手细小，右手带数，舌苔黄腻，无梦而遗。细为气虚，数主湿热，黄腻苔亦湿热之征。气虚不摄则精关不固，湿热浑窍则肾关失守，故无梦而遗。此脉示虚实夹杂，以气虚为本、湿热为标。", ["细", "数"]], "11124": ["病机", "病后热又一旬，两脉数大，数主热盛，大主邪实。邪受于表，积蒸于里，表里俱热，热势鸱张。小儿热盛易动风惊搐，热闭心包则昏闭，故曰“惊闭最易”，此脉示邪热炽盛、有内陷惊闭之势。", ["数", "大"]], "11125": ["病机", "淋浊似有若无，肛门作痛，脉来滑数，舌质光红。滑主湿，数主火，滑数相兼为湿热之象。湿火下注，攻走不定，故淋浊时作时止、肛门疼痛。舌光红示热伤阴液，湿热未清而阴已受损。", ["滑", "数"]], "11126": ["病机", "原文未出脉象，以症测机。月信前后腹胀且痛，乃冲脉有寒，寒凝气滞，肝脾之气违和。冲为血海，寒客冲脉则经行不畅而胀痛；肝主疏泄、脾主运化，二脏气机失和，故症见于经期前后。", []], "11127": ["病机", "肝风夹痰，头晕舌黄，时觉烘灼，脉来弦滑。弦为肝脉，主风；滑主痰。弦滑相兼，乃肝风内动、痰浊上扰之象。风痰上蒙清窍则头晕，痰热内郁则舌黄、烘灼。宜从肝胃并治，即平肝熄风、化痰和胃。", ["弦", "滑"]], "11128": ["病机", "脉滑数而带弦，滑主湿痰，数主暑热，弦属少阳。原文谓产母感暑、内胎应之、蕴于少阳，暑必夹湿，湿为水类侵入囊中，故阴囊肿如晶球、大腹微膨；热盛则身热、哕恶。弦数并见，示暑湿郁于少阳之间，恐热甚暴风鸱张，牵引经络为瘛疭之变。", ["滑", "数", "弦"]], "11129": ["预后", "原文脉至不扬，即脉来沉滞不显，为伏邪夹湿蒸遏气分、阳气不得伸达之象。症经十二日，起伏发热、糊语不寐、便泄数次、舌淡黄厚，皆湿浊蒙蔽心神、邪未尽入中焦。脉不扬而中焦尚健，故云未尽入内；然恐延久而变昏陷，去生远矣，是辨脉以决预后。", []], "11130": ["病机", "脉数微热，数主热，微热示热势不甚。原文风温袭肺，酿浊成痰，以致咳嗽痰白、脘痞气逆。风温犯肺，肺失宣降则咳；痰浊内阻、气机不畅则脘痞气逆。脉数与微热相应，说明风温在肺、痰浊内酿，热未炽盛而肺气已壅，主病在肺之痰热轻证。", ["数"]], "11131": ["预后", "脉象濡数，濡主湿、主虚，数主热。由疟变连热，疟本传脾，劳碌亦传脾，脾运失司则湿生，湿郁化热，故肤色萎黄、力乏、舌色浊腻。濡数并见，示脾虚湿蕴兼热，正虚邪恋。原文最恐淹缠入损，是据濡数之脉判其久延伤正、转为虚损之虞。", ["濡", "数"]], "11132": ["预后", "左脉弦数，弦为肝旺，数为火炽，故痰中见红，是肝火炽也；右手濡滑，濡滑主胃中痰湿，故不咳而嗽、胃痰为患。血虽止而嗽未平，弦数之肝火未戢，濡滑之痰湿未化，脉象与症不符于平，原文恐其久延为损，是凭脉判其缠绵伤正之预后。", ["弦", "数", "濡", "滑"]], "11133": ["病机", "脉象左手数大，左候肝心，数主热，大主邪盛。先咳后热，风热外入，宿伤在络，热迫血溢而呕血；舌色光红、有汗，皆热盛伤阴、迫津外泄之征。左手数大示风热内炽、络伤未宁，故原文恐其冲，谓热势上冲、血可再溢，主风热入络、迫血之病机。", ["数", "大"]], "11134": ["病机", "脉数主内热。原文面黄力乏，是郁伤脾，脾不运湿，湿化为热也。脾郁则运化失职，湿浊内停，久郁化热，故脉见数、症见内热而面黄力乏。数脉在此非外感实热，乃湿郁化热之象，说明病机重点在脾郁湿滞、郁而化热，主脾运不健、湿热内蕴之证。", ["数"]], "11135": ["病机", "脉形弦滑而数，弦主邪郁少阳，滑主瘀滞痰湿，数主伏热。大产两旬正虚，伏邪内发，留瘀结癖，故寒热、汗出半体、衃血不多、脐下极痛、便泄，舌苔淡黄而腻。弦滑数并见，示正虚而伏邪瘀热互结，似疟非疟，当从疏泄，主产后伏邪留瘀之病机。", ["弦", "滑", "数"]], "11136": ["预后", "疟势不退而脉小，色晦，为正虚邪陷之象。脉小者气血不足，抗邪无力，故疟久不退；色晦乃阳气衰败。慢惊、肺胀即在交睫之间，言其变证危殆，预后不良。脉小在此非和平之象，乃正虚邪盛之危候。", ["小"]], "11137": ["病机", "呕吐攻撑从下至脘，为肝木犯胃；脉已数，呕沫带酸，知内郁化热。数脉主热，此因肝气郁久化火，胃失和降，故温方中参以苦降，清泄郁热。脉数在此提示病机由寒转热，非单纯胃寒呕吐。", ["数"]], "11138": ["病机", "因伤见血，血止纳少作呕，脉濡，舌浊，为痰湿内蕴，阳明气不宣降。濡脉主湿，湿浊中阻，胃气上逆则呕，脾运不健则纳少。舌浊亦湿浊之征。脉濡与舌浊相参，确指痰湿为患，非血虚所致。", ["濡"]], "11139": ["病机", "咳久舌黄，脉仍右大，为风燥外袭，湿热内恋。右脉大主肺胃热盛，湿热内蕴，故舌黄；风燥外袭，肺失清肃则咳久。脉右大提示邪热壅盛于气分，与舌黄相应，非虚证之脉大。", ["大"]], "11140": ["病机", "病经五月，气郁生火，火盛生痰，痰火蒙蔽清灵，故喉中如痹、夜不能寐。左脉如无，右手弦滑而数，弦主气郁，滑主痰，数主火，右脉弦滑数正合痰火内盛之机。舌色渐减，亦痰火伤阴之象。", ["弦", "滑", "数"]], "11141": ["兼症", "滞下两季，仍见里急，脉舌相参，虚实各半。虽未明言脉象，然从脉舌合参知虚实夹杂，故仿古散法，攻补兼施。此段重在凭脉舌辨虚实，非单一脉象主病，故脉象要素从略。", []], "11142": ["病机", "疟止复来，因劳而然，即劳复。脉小而数，小为正气不足，数为邪热未清，故虚实各半。劳伤正气，余邪复炽，正虚邪恋，故拟小柴胡法和解枢机，扶正达邪。脉小数为虚实夹杂之征。", ["小", "数"]], "11143": ["预后", "疟已五月，寒热依然，舌光脉小，咳嗽气逆，纳减，为正虚阴伤、脾胃衰败之象。脉小主气血亏耗，舌光为阴液枯涸，故有成损之险，无向愈之象。脉小在此示正气日削，预后堪忧。", ["小"]], "11144": ["病机", "脉象数主热，本案寒热并见、力乏、舌黄灰，为邪浊内蕴化热之征。原文明言“邪浊因劳而发，误食滋腻所致”，劳倦伤脾、滋腻碍运，邪浊郁而化热，故脉数。数脉在此反映邪浊化热之病机，非单纯外感，故断为“非轻恙也”。", ["数"]], "11145": ["治法", "原文“脉象未清”属描述性表述，未出具体脉名，故脉象要素从缺。本案以脉未清为据，仍从手太阴肃降立法，取辛凉甘润为主。肺为干天属金，辛凉可清透，甘润能保肺津，说明脉象未清提示肺经余邪未净，治当续守前法，属治法范畴。", []], "11146": ["病机", "脉浮而数，浮主表、数主热。原文咳嗽虽爽而喉燥嗌干、身热不退，显系风邪未散，留于肺卫，郁而化热蒸痰。浮脉示邪仍在表，数脉示热已内生，故曰“风邪未散，犹然化热蒸痰也”，脉症合参，病机在表邪化热、痰热交蒸。", ["浮", "数"]], "11147": ["预后", "脉象沉数，沉主里、数主热。怀妊患瘅疟十二日，夜分神糊、舌黄满布、烦闷无汗，乃伏暑与湿皆重，邪郁于里化热。沉数脉正合里热壅盛之机。原文“最怕动胎神昏等变”，示脉沉数而症见神糊，预后堪忧，故列预后。", ["沉", "数"]], "11148": ["病机", "脉缓为平和之象，非病脉。原文辛凉甘寒治肺胃后“热退脉缓”，说明风温内蕴之热已得清解，脉转和缓，故曰“非无征也”。然咳痰尚多，余邪未净，前贤治其一面，脉缓在此反映热退而痰湿未化之病机转归。", ["缓"]], "11149": ["病机", "脉象濡数，濡主湿、数主热。疟久脾土受伤，运化失职，湿聚蒸痰，湿郁化热，故独热不寒、舌黄满布、小溲混赤。濡数脉正合脾伤湿聚、湿热内蒸之机。原文“恐入损境”，示湿热久羁、脾土日伤，有虚损之虞。", ["濡", "数"]], "11150": ["预后", "脉象渐见细数，细主阴血不足，数主虚热。经行而停、寒热日久、得食脘腹不舒，乃邪浊内恋、元正日虚，阴血渐耗而虚热内生，故脉由渐细数。原文“颇有成损之险”，脉细数示正虚邪恋、阴血亏耗，预后不良，故列预后。", ["细", "数"]], "11151": ["病机", "脉浮主表、主风。寒热咳肿、汗少，乃风水之邪阻于肺脾，肺失宣降、脾失运化，水气泛溢而为肿。浮脉示风邪在表，肺卫失宣，故曰“风水阻于肺脾，二经合病也”。原文“恐变喘促”，示水气上逆之虞，脉浮正合风水在表之机。", ["浮"]], "11152": ["病机", "脉细为阴液不足，弦为肝气有余，二者并见，示肝气偏旺而阴血亏虚，本虚标实。案中言“补阴之药，味胜于气，疏气之品，辛多于甘”，正虑单顾一边则顾此失彼，故以酸甘辛芳之品兼顾养阴疏肝，说明此脉所主为肝郁阴亏、气机不畅之病机。", ["细", "弦"]], "11153": ["病机", "原文谓“脉象扬抑不齐，中气为痰所阻，阳不入阴”，脉来扬抑不齐反映气机升降受阻、痰浊中阻，致阳气不能入于阴分。引《内经》“胃不和”以明病本在中焦，痰阻胃气，故仿黄连温胆法化痰和胃，此脉所主为痰阻中焦、阳不入阴之病机。", []], "11154": ["病机", "脉濡主湿，数主热，濡数并见示湿郁化热。原文言“脾属土，湿为土气”，劳倦伤脾则纳多消迟，湿浊内停；“阳动则湿蒸为热”，故稍劳即溲赤。此脉说明脾虚湿蕴、郁而化热之病机，与劳倦伤脾、湿蒸为热之症相应。", ["濡", "数"]], "11155": ["病机", "原文未明言具体脉象，仅云“脉舌参之，元正固虚，邪浊尚恋”，示脉舌合参而知正气已虚、邪浊未清。月事不行兼寒热，乃正虚邪恋、气血不畅所致。此段主旨为元正虚而邪浊恋之病机，故有“鞭长莫及”之叹，强调正虚邪恋、攻补两难。", []], "11156": ["治法", "右脉大者，示邪气偏盛于气分，经事愆期兼寒热攻痛，为标急之候。原文提出“先治其标”，即先祛邪调气以解寒热攻痛，再图调经。此脉大说明当前以邪实为主，故治疗当先治标，与经事愆期、寒热攻痛之症相应，体现急则治标之旨。", ["大"]], "11157": ["预后", "右脉涩而不畅，示肺气郁滞、痰浊内阻，气血运行不畅。寒热咳嗽本涉于肺，似可假汗一达，然脉涩不畅，恐汗之无力透邪，反致痰壅气逆，故原文诫“诚恐昏喘之变”。此脉说明肺气郁滞、痰阻气机之病机，并预示昏喘之变，属预后判断。", ["涩"]], "11158": ["预后", "恶寒已罢而脉数亦静，示表邪已解、正气渐复，脉数渐趋平静。原文以“贼到蹂躏，贼去自然修葺完固”为喻，说明邪去正伤乃势所当然，脉静为邪退正复之兆。此段以脉数转静判断邪去正伤、渐趋康复之预后，与恶寒罢、脉静之症相应。", ["数"]], "11159": ["预后", "脉形滑数，滑主痰湿，数主热，示痰热内蕴。寒热咳逆、胸胁脘痛腹板、痰不爽而见红、舌灰黄，皆痰热阻肺、伏暑为新风引发之象。原文虑“防其昏喘之变”，因滑数之脉示痰热鸱张，易蒙蔽清窍、壅塞肺气，故属预后警示，与痰热内盛之症相应。", ["滑", "数"]], "11160": ["病机", "脉常带数，数为热，热从火生，血之动由乎火，故经漏虽渐止而火未清。火扰血海则漏下，热灼阴血则脉数。治以清养佐益气，气足脾固摄，针对火动血溢之机。", ["数"]], "11161": ["病机", "脉形左大于右，左主肝，右主脾，左大右小示肝气肆横、升多降少，脾乏统摄。脘痞气逆、苔淡黄腻为浊阻胃中，肝木乘脾，统摄失职，故经漏后甚。", []], "11162": ["病机", "脉见滑数，数有热，滑有湿浊，显系所蕴湿浊未尽化。湿浊蕴热，虽漏红止而余邪未清，虚则肌表失护，易辐辏新邪。脉象反映湿浊内蕴、热邪未清之病机。", ["滑", "数"]], "11163": ["其他", "原文仅言脉症稍佳、立方似合，未载具体脉象，故脉象要素为空。此段属诊治过程记录，示前法有效，病势向愈，仍守前意出入，非专论脉理病机。", []], "11164": ["病机", "脉数而郁，数主热，郁主气滞。经行落后、色殷而痛、苔黄腻，是气滞血热，蒸湿成痰。气郁血热则脉数而郁，湿痰内蕴则苔腻，脉症合参示气滞血热痰湿之机。", ["数"]], "11165": ["预后", "伏邪晚发，独热不寒，舌干白，脉濡数。濡主湿，数主热，湿热内蕴阳明。原文强调阳明之症逆传最易，脉濡数示湿热未清，正虚邪恋，故预后当防逆传。", ["濡", "数"]], "11166": ["病机", "寒热既系外邪，脉反左大，非外邪典型之浮紧。良由劳碌伤气，湿滞朋比，气分不舒，脉道不扬，故左大。左大主肝气郁滞，湿阻气机，脉道不利。", ["大"]], "11167": ["病机", "脉沉尺大，沉主里，尺大主下焦火盛。血淋已减而白浊未止，痛必有火，病日已久，中气不足，溲便为变。脉沉尺大示下焦湿热未清，兼脾胃气虚，故当参脾胃。", ["沉", "大"]], "11168": ["病机", "脉滑主痰湿内蕴，数主热，滑数相合为痰热内扰之象。原文先胃痛，近寒热呕恶、汗少，乃少阳枢机不利，厥阴疏泄失常，痰热郁于肝胆脾胃，故从少阳厥阴疏和。滑数脉提示病机为痰热郁结、气机不畅，与寒热呕恶相应。", ["滑", "数"]], "11169": ["预后", "原文“两脉似丝”即脉细如丝，主气血大虚、脾元衰败。头摇目窜为虚风内动之兆，便泄五次、哭声呀呀示脾元大伤、中气下陷。脉细如丝与脾元大伤相应，正气欲脱，故断“恐猝然风动厥脱”，属危重预后。", ["细"]], "11170": ["病机", "脉沉主里、主气郁，原文直言“脉沉属气郁浊聚”。脘腹撑胀痞痛乃肝失疏泄、胃失和降，浊气壅聚中焦。女子以肝为先天，肝郁则胃气不降，故脉沉与气郁浊聚相应，治以温通疏达，使气机畅而浊降。", ["沉"]], "11171": ["病机", "脉浮主风邪在表，滑主痰湿，浮滑并见为风邪久蕴、化热蒸痰之象。咳久加甚、痰色带紫，示风热郁肺、痰浊内阻。原文“风邪久蕴化热蒸痰”正合浮滑之脉，故从肺胃清泄，以解风热痰浊。", ["浮", "滑"]], "11172": ["病机", "脉数主内热，原文“脉数内热”明示热邪内蕴。痢成休息、咳嗽痰白、得汗不畅，乃湿热未化，复感新风，表里同病。数脉与内热相应，湿热郁蒸故脉数，新感外风则汗出不畅，病机为湿热夹风。", ["数"]], "11173": ["病机", "脉数主热，原文“脉数，内热，苔黄纳少”示营亏未复而浊邪复聚，郁而化热。左肩膊不利为浊邪阻络，苔黄纳少为热郁中焦。数脉与内热相应，病机为营虚浊聚、郁热内蒸，故脉数而见内热之症。", ["数"]], "11174": ["预后", "原文未明言脉象，仅云“论其脉象舌苔，内蕴之毒火尚炽”。疮已结痂而倦怠嗜卧太过、不欲吸乳，示元气大伤而毒火未清。毒火迅速易生反复，故预告预防。此段重在凭脉舌判断毒火尚炽之预后转归。", []], "11175": ["预后", "原文未出具体脉象，仅“细以脉舌合参”。神识颇安、痂脱疕，示毒火可外越；但不食乳、粥食减，乃脾胃不运、生气不振。脉舌合参判断毒火无内窜之理，预后向好，法当清解兼扶正，属预后与治法并论。", []], "11176": ["病机", "脉象数实，数主热，实主邪盛。原文谓“邪积极甚，充塞于内，闭而生风”，热炽于内故脉数，积滞充塞故脉实。惊后四肢反冷，是热郁于内、阳气不达四末之象，舌苔黄厚亦为实热积滞之征。此脉此症，主阳明腑实、热极生风之病机，险重可知。", ["数", "实"]], "11177": ["病机", "脉来浮滑而数，浮主邪在表分，滑主痰湿，数主热。原文谓“伏邪归入阳明，郁蒸化热”，邪热与痰湿交蒸，故脉滑数；邪有外达之势，故脉浮。舌光红而干、烦躁不安，皆热灼阴伤之象。此脉主伏邪化热、阳明热盛之病机。", ["浮", "滑", "数"]], "11178": ["病机", "原文未识脉名，仅言“脉象不静”，结合腹痛时作、脐下膨满、舌苔黄腻中心光裂，可知湿温化热、热灼阴分，久则木横乘土。脉不静者，邪热未清、肝木乘脾之象。此段主旨在阐发湿温化热、肝脾不和之病机，故归为病机。", []], "11179": ["病机", "原文未识脉名，仅言“脉象宣扬”，结合得畅便数次、宿垢顿下、腹痛大减、黄苔半化，可知寒滞阻气已得温通，阳明腑气以通为用。脉宣扬者，气机得畅之象。此段主旨在说明寒滞阻气、温化通三法并行后气机宣畅之病机转归。", []], "11180": ["病机", "脉濡滑数，濡主湿，滑主痰，数主热。原文谓“邪不外达，积难下化，化热蒸痰，由肺胃而下趋大肠”，湿痰积滞化热，故脉濡滑数。舌尖布刺、满口碎腐、烦躁神糊，皆邪热蒸痰、内扰之象。此脉主邪痧内陷、痰热积滞之病机。", ["濡", "滑", "数"]], "11181": ["病机", "脉形沉濡滑数，沉主病在里，濡主湿，滑主痰，数主热。原文谓“有形之痰积仍与无形之邪火相蒸于表里，充斥于上下”，痰热积滞深踞于里，故脉沉濡滑数。壮热烦闷、喉间痰声如拽锯、口唇舌色如猪肝，皆痰火壅盛之征。此脉主痰热积滞、邪火充斥之病机。", ["沉", "濡", "滑", "数"]], "11182": ["病机", "脉象濡数不持，濡主湿，数主热，不持者脉来无力。原文谓“暑必挟湿，伤人气分”，暑湿内蕴，故脉濡数；怀孕八月，胎为热迫，气血不足，故脉不持。苔黄腻、胸次痞窒，皆暑湿阻气之象。此脉主暑湿内蕴、胎热不安之病机。", ["濡", "数"]], "11183": ["病机", "脉来滑数而浑，滑主痰，数主热，浑者脉象不清。原文谓“夹积阻气蒸浊成痰，内扰肺胃，上迫膻中”，痰热积滞交蒸，故脉滑数而浑。舌苔腻而心绛、从脘至腹按之板痛，皆痰热积滞之征。此脉主伏邪夹积、痰热内扰之病机。", ["滑", "数"]], "11184": ["病机", "脉仍滑而带数，滑主滞积未清，数主热邪未净。原文谓“滞积下而未清，胃中之津”已伤，舌质乾红刺密布，说明伏暑内蕴、气分热炽，虽经大黄黄连法便行腹减，但邪未尽撤，滞积与热相搏，故脉象仍见滑数，提示病机为积滞未化、胃热未清。", ["滑", "数"]], "11185": ["病机", "脉来沉濡而滑，沉主里，濡主湿，滑主痰积。原文谓“寒积夹湿，交阻中宫，升降失度，水谷不分”，上吐下泻而指臂不温，舌苔淡黄而腻，正合寒湿积滞阻于中焦、阳气不达之机，故脉沉濡而滑，主寒积夹湿、中宫格拒之霍乱。", ["沉", "濡", "滑"]], "11186": ["病机", "脉象小数，小为气液不足，数为暑热未清。原文谓“湿因液亏而化，暑由气虚尚逗”，年高古稀，暑湿成瘅疟，热势虽衰未清，舌光红、神识不清、口渴喜饮，皆气液两虚、余邪逗留之象，故脉小数，主正虚邪恋、虚多于实之病机。", ["小", "数"]], "11187": ["病机", "左部见弦，右手濡数。弦主少阳，故原文谓“弦则必有转疟之势”；濡数主湿与热蕴于胃。暑湿内伏，秋凉引激，病于少阳阳明，胸痞烦闷、夜不安寐，正是湿浊上腾、胃土不肃之机，脉象示邪踞少阳阳明、有转疟之势。", ["弦", "濡", "数"]], "11188": ["病机", "脉来濡滑而数，濡主湿，滑主痰热胶锢，数主热盛。原文谓“热由气胶锢不化”，遍体透斑而色红紫晦涩，舌苔淡黄而垢，脘板而痛，烦闷干哕，皆湿热胶结气分、不得透化之象，故脉濡滑而数，主湿热胶锢、斑毒内蕴之病机。", ["濡", "滑", "数"]], "11189": ["病机", "脉来濡滑而数，濡主湿，滑主痰，数主热。原文谓“湿仍留恋中土”，舌苔积白如粉，自汗溱溱，热退不清，兼素来心力纷劳，肺液胃津受伤，故脉见濡滑而数，主暑湿留恋中土、气液暗伤之病机，湿浊未化而热未清。", ["濡", "滑", "数"]], "11190": ["病机", "脉濡沉细，濡主湿，沉主里，细主虚。原文谓“肠胃中之积滞早已随痢而去”，而口舌糜腐、呃逆、下痢，症情属“上为实热，下为虚寒，上下宛如冰炭”，脉濡沉细正示湿热虽减而中下虚寒、胃火充斥之复杂病机，故曰幸而脉濡沉细。", ["濡", "沉", "细"]], "11191": ["病机", "脉象濡数右大，濡主湿，数主热，右大主邪盛于阳明。原文谓秽湿痹气触自口鼻，致寒热起伏、腹痛板硬、便泄似痢，经邪未达、腑积未通，脉右大示阳明募原邪势壅盛，濡数示湿热内蕴，故主湿热秽浊阻于募原、经腑同病之病机。", ["濡", "数", "大"]], "11192": ["病机", "脉浮滑而数，浮主风温在表，滑主痰浊内蕴，数主热盛。原文谓“风温化燥，浊未成痰与积交蒸，伤阴烁液”，正合脉象。风温袭肺，故咳嗽身热、汗泄不畅；浊热交蒸，迫近心包，故烦躁狂起、神糊乱语；脘腹板硬而痛、便溏，为肺胃同病。脉数示热势鸱张，滑为浊聚，浮为邪未全入里。", ["浮", "滑", "数"]], "11193": ["病机", "脉滑而数，重按少静，滑主痰浊，数主热，重按少静说明邪积化热蒸痰，伤阴烁液。原文谓“所存之邪积仍然化热蒸痰”，虽得汗透㾦、已大便，但脐上板痛、咳痰不爽、口渴舌干，皆邪积半留半化之征。脉象未转缓和，提示里热未清，当以凉膈散通里达表。", ["滑", "数"]], "11194": ["病机", "脉来闷滑而数，闷者郁而不扬，滑主痰浊，数主热。原文谓“风温为浊所恋，浊未成痰，欲化热而未化火，互蕴肺胃”，故见咳不扬、痰如沫、神糊语乱、当脐膨满、大便欲解不行。脉闷滑而数，正合浊热互蕴、肺胃同病、迫于心包之机。", ["滑", "数"]], "11195": ["病机", "脉来细涩而弦，细主阴血亏，涩主血行不畅，弦主木旺克土。原文论间日疟久发伤脾，脾统血无权而便血后发，脾病则木乘。细涩为营血内亏、脉道不利，弦为土虚木贼之象。疟邪深蕴营卫之间，久则伤脾，脉象反映正虚邪恋、肝脾不调之病机。", ["细", "涩", "弦"]], "11196": ["病机", "脉象右小左大，右小主肺气不展，左大主肝热内炽。原文谓伏暑夹湿夹积，起伏太甚，谵语不已，四末乍寒乍热，舌苔满黄，大便直泄，有“不得外达辗转入里之险”。暑湿伤气，肺气不展则右脉小；热扰心肝则左脉大。脉象示邪热内陷、气机壅滞之机。", ["小", "大"]], "11197": ["病机", "脉来细弱无神，细主阴液亏，弱主阳气衰，无神为胃气败。原文谓“胃经气阴俱伤，脾阳衰而不运”，故杳不思食、便泄如痢、里急。病后胃气索然，脾阳不运，气阴两伤，脉象细弱无神正合此机。", ["细", "弱"]], "11198": ["病机", "脉来小数无神，小主气血亏，数主热，无神为胃气将竭。原文谓疟痢久延、复又大产，气血早已受伤，阴液被燥，邪热与湿浑合由胃入肠，故痢仍不止、后重依然、杳不思食、小溲艰涩。脉小数无神，示正虚邪恋、胃液告竭之危候。", ["小", "数"]], "11199": ["病机", "脉来郁滑而数，郁主气机壅滞，滑主痰积，数主热。原文谓经事甫净即发伏邪，阴分本虚，邪乘虚入，阳明邪积交蒸化热，肺胃阴液受烁，故热势夜甚、脘腹板痛、大便难行、舌干白而心灰。脉郁滑而数，正合邪积化热、气机郁滞、阴伤液烁之病机。", ["滑", "数"]], "11200": ["病机", "脉沉濡而数，沉主里、濡主湿、数主热，合为湿遏热伏之象。伏暑夹湿交七日，又逢经事下行，气血并病，湿浊蒙蔽心包故神糊谵语，热扰胸膈故心中烦闷不已，苔灰亦为湿浊内蕴之征。脉证相参，示暑湿充斥、正虚邪盛之险候。", ["沉", "濡", "数"]], "11201": ["病机", "脉数弦，数主火、弦主木旺，合示木火凌金、气逆不降。原文谓阴分不足、木火凌金致吐血咳逆，又感风邪入太阴，咳剧气升胸闷，痰结攻劫而实非痰乃气。弦为肝脉，数则火象，正合气但出而不纳、肾气日乏之机。", ["数", "弦"]], "11202": ["病机", "二诊脉犹带数，数主内热未清。重镇后气升减退什五、喉痹宽展，然呼吸仍入少出多、内热虽轻而不能静，说明逆气稍平而火热未靖、纳气未复。脉数不去，正是热未尽、气未归根之据，故仍需镇堕以冀喘平。", ["数"]], "11203": ["病机", "脉细数而关部带滑，细主阴亏、数主热、关滑主痰湿。原文谓肾亏于下、肺壅于上，胃中痰湿为热气所激复注于肺，致肺胃下降之权全失，故食入脘中不舒、舌红咽腻苔白。细数示本虚热扰，关滑示中焦痰湿壅滞，脉证相符。", ["细", "数", "滑"]], "11204": ["病机", "右脉细涩、左脉弦数，细涩主血虚，弦数主火旺。经停七日而汗多如雨、内热不退，原文断为经因病而不至者虚也、汗出非虚也火也。左弦数示肝火迫汗，右细涩示阴血不足，故主张苦寒益水灭火，不可攻瘀亦不可纯补。", ["细", "涩", "弦", "数"]], "11205": ["病机", "脉中空边实、来往不利，即芤涩并见。原文自释涩则有瘀、芤则血虚，胃络震动、诸经失养。芤为血虚失充，涩为血行滞涩，二者相合示血虚兼瘀、络脉不和，故不可堵截，宜用和络之法，使血行而不伤正。", ["芤", "涩"]], "11206": ["病机", "脉数舌红，数主热盛、舌红为热象。风温蕴肺，咳热并重，两感之症非轻，肺病逆传必至心胞。脉数示温邪内炽，舌红示热入营分之渐，故以辛凉佐甘寒，清透肺热兼护心胞，与春令风温病机相合。", ["数"]], "11207": ["病机", "脉来濡数，濡主湿、数主热，合为湿热蕴结之象。便下极少积滞未尽、脘右按痛、哕恶稍减而汗未得，所蕴之邪未外赴，故午后寒热仍起、烦闷更甚，舌苔黄腻亦湿热之征。脉证示邪踞中焦、湿热未化，九日之势不剧即为退机。", ["濡", "数"]], "11208": ["病机", "原文谓“脉来数而中止为促，促为阳甚阴虚之病”，数主热，中止示气机不续，阳热炽盛而阴液亏耗。咳热痰红见此脉，推因外风入肺化火内炽，火盛灼津，水源日涸，故为痨瘵之兆，脉象与咳热痰红症候相应。", ["数", "促"]], "11209": ["病机", "久咳见血，咳则诸络皆震，肺络受伤血溢于上。左脉弦数，弦为肝旺，数为火盛，有木火刑金之势，肝火循经上灼肺金，迫血妄行，故咳血所忌，脉象正示肝火犯肺之病机。", ["弦", "数"]], "11210": ["病机", "风入于肺，身热咳嗽两月，脉数而滑，数为热盛，滑主痰湿，舌红而光示阴伤。邪不外达，势欲内传，痰热内蕴而阴液渐耗，久咳不已有成劳损之虞，脉症合参示邪郁化热内传之机。", ["数", "滑"]], "11211": ["病机", "血败之后淋沥不净，脉数内热，舌苔黄腻。数主热，内热由气虚血热所致，黄腻苔示夹浊内阻，气虚不能摄血则淋沥，血热夹浊互结，脉数正应内热之机，与舌苔黄腻共示虚实夹杂之候。", ["数"]], "11212": ["病机", "寒轻热甚，头痛无汗，腰疼项强，脉形紧数，紧主寒束，数主热盛，宛如巨阳初症。然时当暮春舌渐干黄，温邪为新邪所伏，紧数之脉示外寒束表而内有温热，故不宜麻桂，宜葱豉煎透解伏邪。", ["紧", "数"]], "11213": ["病机", "花后气血两伤，外邪易入，咳热半月，右脉数大。右脉候肺，数主热，大示邪盛而正气受损，气血两伤之际外邪乘虚袭肺，乳儿脏腑娇嫩，喘惊极速，脉数大正示邪热壅肺、正虚邪盛之危候。", ["数", "大"]], "11214": ["病机", "花后元虚火盛，玄府易开，卫不固，风温凑袭，咳热痰鸣，脉数舌干。数主热，舌干示津伤，元虚火盛而卫外不固，风温之邪乘袭肺卫，痰热内蕴，脉数正应风温化热伤津之病机，故辛凉佐微苦取效。", ["数"]], "11215": ["病机", "寒热无序，咳久不已，左脉大，舌黄腻，邪尚在肺。左脉候肝，大示肝横，肺胃为卫气之主，卫虚则邪易出入，肝横则腹满胀痛。脉大与舌黄腻共示邪恋肺卫、肝木偏亢之机，前方既应再当扩充而投。", ["大"]], "11216": ["病机", "脉左手细涩，细为血虚，涩为血行不畅。原文谓足大指麻属肝脾二经气衰血耗，血虚火旺致齿痛牙痈，心悸不寐、闻响惊跳，皆血不养肝、肝风内舞之象。细涩正合阴血亏耗、脉络失充之机，故主风痱之患，治以养血滋肝。", ["细", "涩"]], "11217": ["病机", "脉左大右软，左大者心肝阳浮不敛，右软者脾肺气虚不运。原文述谷纳渐减、步履如蹈空，为下焦衰乏、中气不足之征。左大右软反映上盛下虚、心脾两亏，故断恐成类中之病，宜补心脾以固本。", ["大", "软"]], "11218": ["病机", "脉浊右手如促如动，往来如有阻滞。原文谓内有积痰、肝风鼓动、上蒙清窍，左手麻木、午后神昏，痰血郁于隧道。促动之象示痰浊阻络、气血不畅，故脉往来涩滞，主痱中之机，宜补气血以疏通。", ["浊", "促", "动"]], "11219": ["病机", "脉细为气血不足、脉络失充。原文述头眩、左肩臂麻而无力，是中风之兆。细脉主虚，气血不能上荣头目、外充肢体，故见眩麻无力，属正虚风动之渐，治宜补以散之，扶正兼疏风。", ["细"]], "11220": ["病机", "脉左弦右滑，弦主风邪、滑主痰湿。原文谓当风淋浴致口眼㖞斜，风邪散入手足太阳阳明之经，近加吐痰、肋时痛。左弦示风扰肝经，右滑示痰滞脾胃，风痰阻络故病根三载未除，宜大追风散加减。", ["弦", "滑"]], "11221": ["病机", "脉右大，右属肺脾，大为邪实气壅之象。原文述脘中爽、口渴、肠风，脘爽口渴示热郁气分，肠风乃风热迫血下注。右大脉反映肺脾热盛、气机壅滞，故主肠风之病，热邪伤络而血下。", ["大"]], "11222": ["病机", "原文未识脉名，然述木火形体、善动少静、操持拂郁频多，阳虚失卫，怕风畏寒，气塞不行，脉络痹痛。此由情志郁勃、阳气亏虚，卫外不固而经络痹阻，病机在阳虚气滞、络脉不通，故议补益阳气、疏通经络。", []], "11223": ["病机", "原文未识脉名，仅言验脉是经络气分之阻。述鼻塞用力屏气则耳窍失聪、左胁骨高突，气辛开泄暂用不得除根。此乃气机壅滞于经络气分，清窍不利、胁络不和，病位浅在气分，故当以轻清之品宣通为治。", []], "11224": ["病机", "左手脉浮，右手略小而重按有力，说明邪在表分而正气未虚，非阴症虚寒。躁扰不宁乃湿痰挟伏邪胶黏难达，致宗气别气隔塞，耳听不聪、目无神采。脉浮为邪混三焦、出入靡常之象，重按有力则示邪实可吐，故用栀豉汤涌吐得效。", ["浮", "小"]], "11225": ["病机", "脉象沉弦，沉主邪陷于里，弦主痰饮与伏邪胶结。体丰好饮，伏痰必多，暑湿之邪蕴结已久，又感外邪，痰与邪俱郁闭不通，故昏沉躁扰、神气蒙混、中脘痞硬、面黄带浮。沉弦示邪陷未透，不可遽视为坦途，治当利湿消痰兼透达伏邪。", ["沉", "弦"]], "11226": ["病机", "左脉弦大有力，右脉细软无神，乃伏痰与邪胶黏不散，占据清阳之地。弦大为痰邪结聚之象，右脉细软无神则正气不能流通，故胸口板硬如结胸，神色如昏如清，舌苔如灰如白。必得胸中宽松、面色红活，方无反复。", ["弦", "大", "细", "软"]], "11227": ["病机", "右关脉滑，关候中焦，滑主痰湿。体素丰肥，痰与伏邪合，风暑为患，邪毒未透，故赤斑白疹密布、口渴发厥、躁扰不宁而唇淡舌白。滑脉示痰浊内蕴，与伏邪相合，治宜化斑解毒佐以消痰，使邪毒外透。", ["滑"]], "11228": ["预后", "脉右洪数，洪为邪盛，数为热象，然舌苔极薄、唇齿不燥、不作渴，则非阳明实热。噫嗳呃逆、略有谵语，乃里虚邪不能达。洪数之脉与里虚症候相左，清补两难，养阴和胃为妥，原文断为不治，示预后不良。", ["洪", "数"]], "11229": ["病机", "身热、口渴、烦躁、舌干，显系阳症，而脉细乃体质素虚所致，非阳症见阴脉之比。细脉主虚，说明正气不足，虽属阳症却不可过于攻击，宜养正清热为主，使虚体得扶而邪热自解。", ["细"]], "11230": ["病机", "左手弦数，右关滑大。弦数为邪在少阳，滑大为痰热壅于阳明。寒热如疟、中脘痞结，正是邪踞阳明少阳之征。脉象与症相应，故宜和解之法，使少阳枢机得转、阳明痰热得清。", ["弦", "数", "滑", "大"]], "11231": ["主病", "脉弦滑，弦主少阳，滑主痰湿。午后热重、口干、便赤、目黄、胸满、多汗，皆少阳湿热郁蒸之象。弦滑并见，说明邪在少阳而兼痰湿内蕴，故直断为少阳症，治当和解少阳、清化湿热。", ["弦", "滑"]], "11232": ["主病", "脉小而滑，小为正气不足，滑主痰湿食积。身热两月无汗，舌黑齿燥，泄泻，显系热邪久羁，阴液耗伤，而痰湿内阻。脉小提示正虚，滑示痰食未化，故虽危候，仍可姑与双解散以解表清里，冀邪去正安。", ["小", "滑"]], "11233": ["病机", "右脉滑数，滑主痰食，数主热。身热不退，舌白腻滑，胸中按之作痛，无汗不渴，此表邪未解，中焦痰食壅滞化热。右脉候脾胃，滑数反映阳明痰热内结，故宜清理阳明，以祛痰食之滞。", ["滑", "数"]], "11234": ["病机", "脉弦细且急，弦主少阳，细为阴伤，急示邪郁化热。少阳邪郁不解，内走厥阴之络，胁下支结，内热无汗，脉弦细急正是肝络郁滞、邪热内迫之象，故宜宣达肝邪，透解郁热。", ["弦", "细", "急"]], "11235": ["病机", "脉象尚带弦数，左手空软，右关滑大。弦数示客邪郁伏未净，左空软为营阴已亏，右关滑大主阳明痰气阻滞。胃脘左畔结硬成块，即仲景所谓心下有支结，痰气不除则寒热不止，故宗柴胡桂枝干姜汤加减以和解兼化。", ["弦", "数", "滑", "大"]], "11236": ["病机", "脉象左弦右细，左弦主少阳邪郁，右细为营阴虚少。每夜热发，舌黄口苦，显系少阳邪热未解，营阴亏虚，夜热加重。脉象左右合参，正合营阴虚而少阳邪未解之病机，治当和解少阳，兼养营阴。", ["弦", "细"]], "11237": ["病机", "左脉犹弦，弦主少阳余邪未清。汗不出至足，营卫未和；热退而谵语，邪留心络。脉弦示肝胆郁热尚存，故宜清养之，清解余邪，滋养营阴，使营卫调和，神志自安。", ["弦"]], "11238": ["预后", "脉虽细，尚带滑数，细为阴液耗伤，滑数主痰热内蕴。齿燥舌干，神昏口渴，热邪内陷，蒸灼津液为痰，痰迷心窍，诸药不应，危候也。脉细而滑数，正虚邪实，故断为不治。", ["细", "滑", "数"]], "11239": ["治法", "脉右滑数实，滑主痰，数主热，实为邪壅。痰虽吐出，神犹昏愦，齿燥舌干，燥而不烦，皆至危之候。右脉滑数实，示阳明痰热结实未去，故宜再下之，以图侥幸，攻下痰热以存阴。", ["滑", "数", "实"]], "11240": ["病机", "左手弦细而类数，弦主肝郁，细为阴伤，数则邪火内燔；右手滑实而数，滑主食积痰湿，实为邪盛。脉象反映邪火炽盛、肝阴耗伤、痰食内结之病机，与热久不退、痢下如蟹黄、胸前痞闷、嗳呕、咽痛、口渴、肝叶胀痛等症相应，故宜血药加苦寒下之。", ["弦", "细", "数", "滑"]], "11241": ["预后", "脉数稍缓、脉大稍平，重按尚觉有力，说明邪热渐退而正气未衰，为佳象。数脉主热，大脉主邪盛，今二者皆减，提示喉痹、痢疾、身热三病虽兼，但病势向愈，故仍宜养阴清热、化痰解毒，可望渐安。", ["数", "大"]], "11242": ["病机", "左手弦大带数，弦主肝郁，大数主邪热内炽；右手大而柔软，大而无力为气阴两虚。此本虚标实之候，真阴久衰，客邪内陷，故身热不退、舌干苔黑、气急咳频、斑点未透、耳聋齿燥，非提斑清火所能愈，惟滋肝润肺使木不燥、金渐清。", ["弦", "大", "数", "软"]], "11243": ["病机", "脉象沉细模糊，沉主里，细主虚，模糊为阳气不振、阴寒内盛之象。此夹阴伤寒，阴邪入于阴分，虚象火象合并，故手足厥冷、躁扰不宁、舌红无苔、神昏谵语，补之不可，清之不应，殊为危险。", ["沉", "细"]], "11244": ["兼症", "左脉弦软带数，弦为肝郁，软为阴伤，数则余热未清；右寸数而关尺未详。此热病后余邪未净、阴液耗伤之象，故口糜虽退而喉内白点、痰盛声嘶、起坐不宁，仍宜养阴清热以善后。", ["弦", "软", "数"]], "11245": ["病机", "本段未识脉名，专论暑湿热久蕴，入卫营壅塞而为痈疡，热毒燎灼络中，烦躁腹胀、不食不便，热邪充斥三焦。久热从燥化，苦寒化燥未可轻投，宗玉女煎法，说明病机为暑热伤阴、络痹毒蕴。", []], "11246": ["治法", "右脉无神，未及具体脉象，然无神即胃气虚弱之征。症见恶寒发热咳嗽盗汗，为表虚营卫不和，故姑与建中汤以温中补虚、调和营卫，脉无神正是用建中之据。", []], "11247": ["病机", "左手弦急，弦主肝郁，急为邪气留连；右手细软，细软为正气亏乏。此脾肾两衰、元气大虚而余邪未清之候，故寒热反复、口苦无味、唇燥舌苔、小便涩痛、精漏不固，治宜先清理后补养。", ["弦", "急", "细", "软"]], "11248": ["病机", "原文未明确脉名，仅言“左尺斜出脘侧，是为阳维脉”，结合《内经》“阳维为病，苦寒热”，指出阳维脉病机为维系失司、寒热不调。今舌不退、呕呃臭水，乃阳维脉气上逆、胃失和降，故为难治之候，用镇降法以平冲逆。", []], "11249": ["病机", "脉左弦细，右寸软。弦细为阴血亏虚、肝木失养，软为气分不足。下痢、寒热无定期、舌苔蓝红相兼，显系气血两伤；咳嗽盗汗咯血，乃虚火灼肺、络伤血溢。脉症合参，主气血双亏、肝肺同病之病机。", ["弦", "细", "软"]], "11250": ["病机", "脉弦带数，弦主风、数主热。身热、呕吐、泄泻、发风饼，乃暑热夹风袭于阳明，致胃失和降、脾失健运，风热外透肌肤则为风饼。脉象与症相符，主暑风袭于阳明之病机。", ["弦", "数"]], "11251": ["病机", "脉细，右手带滑。细为阴血不足，滑为痰湿内蕴。身常寒热、汗出如旧，乃外寒束其内热，营卫失和；夏安春秋发，与时令相关。脉细主内虚，右滑主痰，合之外寒内热、痰湿阻遏之病机。", ["细", "滑"]], "11252": ["病机", "脉带弦，弦为肝脉。病后微有寒热、盗汗、干咳、胁胀、溺赤，皆肝阳上扰、疏泄太过、灼伤阴液所致。胁胀为肝经布胁，溺赤为肝火下移。脉弦与症相应，主肝阳上扰之病机。", ["弦"]], "11253": ["病机", "左脉细涩难寻，细为血少，涩为血行不畅、阴精亏耗。仲夏疟疾后复发热、心忡耳鸣、不食，乃疟邪耗伤气血，心失所养则忡，耳失充则鸣，脾失运则不食。脉症合参，主气血两衰之病机，高年重症。", ["细", "涩"]], "11254": ["病机", "左脉弦细而数，右脉细软。弦细数为阴虚火旺、虚热内扰；细软为气阴两虚。素体阴虚，发寒热、夜热、舌干耳聋、泄泻，乃虚损本病兼外感客邪，正虚邪恋。脉象示真阴亏而客邪未解，故论治当扶正托邪。", ["弦", "细", "数", "软"]], "11255": ["病机", "阳明脉大，大为阳热亢盛之象。体质阴虚，夏秋暑热内侵，客于膜原，致寒热、不欲纳谷。脉大与暑热内盛相应，主阳明热盛、阴分受伤之病机，故用养阴清暑方。", ["大"]], "11256": ["病机", "脉来小缓、按之不数，说明积劳既久、阳气受伤而伏热内蕴，非外感风寒之邪。小为正气不足，缓为胃气尚存、邪未化燥成实，故二便颇通、略能纳谷，无停聚滞积。此脉证实为虚人伏热、膜原流布三焦之候，治当甘寒滋养胃阴，忌表散辛温与苦寒沉降消滞。", ["小", "缓"]], "11257": ["病机", "病后咳嗽、背恶寒而脉弦数，舌苔微黄。弦主气机郁滞、少阳不和，数主热，说明表寒未罢而里有郁热，属表寒里热之候。背恶寒非纯虚寒，乃热郁于内、阳气不达于表所致，故法宜清解，透达郁热而非温散。", ["弦", "数"]], "11258": ["病机", "脉不软而弦细带数，右脉独弱。弦细带数为阴亏火郁，丹溪所谓恶寒非寒是火郁；右脉独弱则下焦根柢衰，卫阳出于下焦，藩篱既撤故汗多寒甚。此阴不涵阳、阳不固阴，寒热之虞由此而生，治当救阴固阳，防阳越阴枯。", ["弦", "细", "数", "弱"]], "11259": ["病机", "右脉尚大而恶寒，大脉主热盛于内，恶寒非表寒，乃火郁于里、阳气不能外达，故仍属火郁之候。火郁发之，宜桂苓甘露饮清利郁热、通阳化气，使内热得泄而恶寒自解，不可误作表寒而温散。", ["大"]], "11260": ["病机", "病后畏风、精神疲倦，右手气口脉大于人迎。气口主脾胃，脉大而倦怠畏风，说明中气不足、清阳不升，卫外不固，正合东垣补中益气汤症。此非外邪有余，乃脾胃气虚、元气下陷之候，故以补中升阳为治。", ["大"]], "11261": ["病机", "原文未载脉象。咳嗽而头巅作痛连于脑后，乃下焦龙火因督脉上逆，金受火刑不能生水，故目光昏花、骨节酸痛。此虚阳上浮、水不涵木之病机，法当潜纳虚阳，引火归元，非清肺止咳所能治。", []], "11262": ["病机", "原文未载脉象。足少阴脉循喉入肺，足厥阴支脉贯膈注肺，肾气充足则声音高爽，肾气亏损则声音低飒。此说明声喑不独金实、金破二义，尚有肾精亏虚、脉不上循喉咙之机，故治当补肾填精而非专治肺。", []], "11263": ["病机", "右脉衰于左脉，六脉俱带微数。烦劳后声喑，足冷面热、脚膝无力、口干咽燥，全是下焦衰乏、阴精不主上涵，心肾不交、金受火刑。微数为阴亏虚火，阳药难投，故以壮水固金为主，补肾而非治肺。", ["微", "数"]], "11264": ["病机", "原文未出脉名，仅言肾脉上循喉咙。所论便结、咽痛、精滑三症，皆由肾阴不足、相火内扰所致：阴亏则肠道失润而便结，虚火上灼咽喉而咽痛，相火扰动精室而精滑。三症虽异，病机同出一源，即肾阴亏虚、相火不藏，故以肾脉循行部位统摄诸症。", []], "11265": ["预后", "脉细而数，细为阴亏，数为火动，正合水不涵木、木复生火之机。火刑金则面手渐肿、清肃不行，凌脾则谷纳日减；丙夜气升烦热、癸汛频来甚少，乃子午不交、阴竭阳孤之候。脉细数示阴液已竭而虚火独亢，故清补俱难收效，属至危至险之预后。", ["细", "数"]], "11266": ["病机", "左脉弦数，弦为肝旺，数为火盛，正应肝阳亢极、火盛水不能济之机。火升未降故内热、呕吐酸水、目赤唇红、左乳缩小；木火交煽，脾伤肾涸，犯及奇经，故大便溏泄、经频带下。脉弦数紧扣肝火亢盛，故依前法加直折肝火之品。", ["弦", "数"]], "11267": ["病机", "脉象弦劲且大，弦劲为肝阳亢逆，大为虚阳浮越，正合肾中真阴耗竭、真阳无所依附随脉逆行之势。火起九泉，虚阳上越故面红舌糜、咽燥肺焦而声不朗；阳不下潜故两足冰冷。幸不快数，示火尚未炽，故主以甘寒滋养收摄，耐性静镇。", ["弦", "劲", "大"]], "11268": ["预后", "脉软而数，软为肾水亏乏、脉道不充，数为虚火内动。肾脉络肺循喉，水亏则坎中之火直犯肺金，肺热叶焦而脓血交出，火升不降而为咽痛。脉软数示阴亏火旺而正气已馁，故滋清无益，勉与猪肤汤以图侥幸，属致险之候。", ["软", "数"]], "11269": ["预后", "原文未出脉名，以足三阴之脉起于足立论。脚软足痿且麻，为三阴脉绝；声喑咽痛，为金为火烁、清降失司；蒂丁下坠，为元气耗败、脾肾两衰。三者皆脏气败绝之征，今诸症兼见，故断为不治，药力难挽，属危重预后之论。", []], "11270": ["病机", "脉数象稍和而右寸仍然数大，右寸候肺，数大为肺热之征。水亏则肺热，肺热则痿，故知病本在肾水不足、虚火上灼肺金。数象稍和示虚火略敛，然右寸数大未除，肺热仍在，故尚当以补肾为主，补脾药温燥、补肾药凉润，脾肾两虚尤难兼顾。", ["数"]], "11271": ["病机", "左脉细软无神，细为阴血不足，软为气衰无力，左脉候心肾，故断为心肾两虚。虚阳上扰则头眩体麻，下焦不能吸纳则腹痛如欲泻状。用阴药则碍脾，故仿潜阳法变通，使虚阳下潜而不伤中土，正合细软无神之脉所主心肾亏虚、阳不潜藏之机。", ["细", "软"]], "11272": ["预后", "脉数无神，数而无力无胃气，是阴枯液涸、壮火食气之象。原文谓“最非佳兆”，体倦食减由元虚脾惫，然补之犹恨其晚，说明虚火内燔、真阴难复，故预后不良，只可重补轻投、姑与调停，非纯虚可补之证。", ["数"]], "11273": ["主病", "脉细无力，细为血少、无力为气虚，合手战不能持物、舌痿难言、饮食大减，显系气血大虚、筋脉失养。右手痹痛、右足无力有风痱之象，脉细则内虚为本，宜补，说明此非外风实邪，乃虚风内动之候。", ["细"]], "11274": ["预后", "梦泄后咽窒足弱，原文谓肾脉不上循喉咙、内夺而厥，已成痱象。纳减作胀为后天又衰，脉带数则虚阳不敛、真阴难复，故断“非药所能奏效”，数脉在此非实热，乃阴亏火动、生机难续之兆。", ["数"]], "11275": ["病机", "左寸尺细软为心肾两虚，关独弦为肝阳易亢，右三部洪滑、关尤甚为阳明痰火未清。原文以水衰不能滋养肝木、坎水不制离火解释背偻胁痛吐瘀，又因烦劳五志化火炼液成痰，值暑令发如狂，属本虚表实，脉象正合虚中夹痰火之机。", ["细", "软", "弦", "洪"]], "11276": ["病机", "背筋牵急、冷彻于背、饮食著背而下，原文归为积痰变幻。今脉象渐和而右关独大，右关候脾胃，独大为阳明痰热未净之征，故仍宜清阳明。脉渐和说明大势已缓，独大提示余邪稽留中焦，与积痰病机相应。", ["大"]], "11277": ["病机", "脉细而弦劲，细为阴血不足，弦劲为肝木失柔、劲急无胃气。原文断为水不涵木、肝木动摇，故见神昏如、牵掣如痉。此非实症，乃虚风内动，阴亏为本、风动为标，故谓非比实症易治，预后较实痉为差。", ["细", "弦"]], "11278": ["病机", "寒热如疟后神识迟钝、盗汗，脉左细右弦滑。左细为血虚，右弦滑为痰浊内阻，原文直断“血虚而夹痰为病”。血虚则神失所养，痰阻则清窍不利，故神识迟钝；盗汗亦血虚阴不敛阳之象，脉象与症相符。", ["细", "弦", "滑"]], "11279": ["主病", "病后目黄脚麻、神识呆钝而饮食如常、肌肉不瘦，原文谓湿热生痰为患。脉滑主痰、大主湿热壅盛，滑大有力说明邪实而正气未衰，故断“清理可愈”，与虚证脉细弱者预后迥异，此脉主痰湿实邪可清。", ["滑", "大"]], "11280": ["病机", "左脉数大、右脉略小亦数，数主火，大为阳亢，前用清火消痰不应，原文断为「水亏无制火」，即肾水亏虚不能制火，虚火上炎故数大。右脉略小亦数，示火灼阴伤。此脉主阴虚火旺之病机，与口渴、痰火等症相应，故议养阴兼渗湿，标本兼顾。", ["数", "大", "小"]], "11281": ["病机", "脉沉弦数，沉主邪伏于里，弦主疟邪搏结、枢机不利，数主邪热内郁。原文谓「邪伏于内，以渐外达」，故疟发前口渴、发后渴退，恶寒汗冷乃营卫不和。沉弦数正合邪留半表半里、营卫失和之病机，故宜和营卫以达邪，使伏邪外透。", ["沉", "弦", "数"]], "11282": ["病机", "脉象虚数，虚为正气不足，数主热。疟邪内传，发而不退，面目黄色、饮食不进，原文断为「温热为风阳煽动」，即温邪挟风阳鼓动，正气已虚而邪热未清。虚数之脉示正虚邪恋、伏邪未解之病机，故法宜清理伏邪，兼顾正气。", ["虚", "数"]], "11283": ["病机", "脉象弦迟，弦主疟邪留于募原、气机不畅，迟主寒。原文谓「邪留募原，不能与卫气偕出」，故间日发而不移时，寒多热少。弦迟正合寒湿痰浊阻遏募原、阳气不伸之病机，故用桂苓甘术汤温化水湿，加清散药以透邪。", ["弦", "迟"]], "11284": ["病机", "左脉弦大，右脉细软。弦大为邪留血分、肝血瘀滞而阳浮，细软为营血不足、正气偏虚。原文谓疟频发「邪留血分」，左主血，故左脉弦大；右脉细软示气分不足。此脉主血分伏邪兼气血不调之病机，故治以和血托邪则愈。", ["弦", "大", "细", "软"]], "11285": ["病机", "脉弦，弦主肝胆、主气机郁滞。但热不寒、胁痞、盗汗，皆邪郁少阳、营卫不和之象。胁痞为少阳枢机不利，盗汗为营阴外泄，弦脉正应肝胆郁热、营卫失调之病机，故法宜和营，使营卫调和则郁热自解。", ["弦"]], "11286": ["病机", "脉细，细主气血两虚、脉道不充。疟病频作，久疟耗伤气血，故身痛而「小劳即诸病皆来」，原文明言「虚故也」。细脉正合气血亏虚、正气不足之病机，身痛非外邪，乃虚不荣养所致，故当以补虚为要。", ["细"]], "11287": ["预后", "脉细数无力，细为阴血亏虚，数为虚热，无力示正气衰。原文谓「虚象显然」，三阴疟久、因劳连绵，身热咳嗽喉痛，断为「肺脾两伤，势必发肿」，示正虚邪恋、脾肺俱损，有发肿之虞，故以避风静养为主，属预后判断。", ["细", "数"]], "11288": ["病机", "脉细为阴血不足，右寸关沉滑则示暑湿伏于募原、渐传肺胃。原文言久疟成劳怯、咽痛干咳、恶心欲呕，正合暑气内伏、肺胃受困之机。脉细而非洪大，说明邪未化燥而正气已伤，故宜清理而勿骤滋补，恐滋腻碍邪。", ["细", "沉", "滑"]], "11289": ["病机", "本段未出脉名，以症测机。午后咽中如有物升、燥痒欲呛，原文断为肾脉络肺、水亏火旺循脉上冲，乃损症机关；心嘈属火烁胃阴。此皆阴虚火炎、虚火上逆之病机，故治以固本为主，与上段清理法形成对照。", []], "11290": ["病机", "脉数带弦，数主热、弦主木旺，合面浮色淡、全不纳谷之脾败象，说明正虚而邪热未清，故难投温补。原文谓营卫两伤、虚候而非变轻，病势殊深；年未冠属纯阳之体，姑与清养以望转关，脉数弦正是不可骤补之据。", ["数", "弦"]], "11291": ["病机", "左脉弦大为肝木偏旺、阴不敛阳之象，故寒热仍归三疟而咽喉尚痛。原文以寒热复归三疟为好处，说明邪有出路；然弦大之脉示肝阳未潜、虚火循经上灼咽嗌，故治宜滋肝补肾，以柔肝滋水制其弦大。", ["弦", "大"]], "11292": ["病机", "脉象细软无神，细为阴血亏少，软为气弱不鼓，无神则胃气衰败，合三疟两次发而病势虽轻，实属大虚之候。原文直断大虚，正因脉失神气，提示正气难支，不可因疟轻而忽视补虚。", ["细", "软"]], "11293": ["病机", "脉象细弦，细主正虚、弦主木旺，合疟疾四作、顿然形瘦腹胀，原文断为土败木贼。脾土衰败则腹胀形瘦，肝木乘之则脉弦，细为土虚不能充脉，故此为虚实夹杂、肝脾同病之候。", ["细", "弦"]], "11294": ["病机", "脉象左大右小，左候心肝、右候肺脾，左大示阴不足而火扰，右小示中气偏弱。原文谓疟后心中冲悸、元气阴不足、阴为火扰，正合左大之脉；故治宜补中寓清，既培中气又清虚火，使阴阳相济。", ["大"]], "11295": ["病机", "脉软为正气虚弱、营卫俱伤之象，合三阴疟久、汗多，原文谓正气不能主持。汗多则气随液泄，脉失鼓动故软；素有梦泄、下焦亏损，虽补不能速效，说明虚损深及下焦，软脉正是正虚难复之征。", ["软"]], "11296": ["病机", "脉右大少神，右候脾胃，大而少神为阳气不振、胃气虚弱之象。原文谓太翁'阳虚体质'，症见汗出肢冷、溺频便溏、嗳噫如呃，皆阳微少振之征。疟发寒热因脾胃营卫二气受邪，脉大少神正示中阳不足、不能鼓脉，故治以温理脾胃之阳为主。", ["大"]], "11297": ["病机", "脉数、舌赤，为疟热乘中、胃津被耗之象。原文言'疟热乘中，胃津被耗，理必烦渴，嗳噫，气逆上冲，皆劫津所致'，数脉主热，热盛伤津故脉数而舌赤。虽高年本有阳微，然客邪未除、气从热化，故不敢温补沉降，姑与生津养胃、酸甘化阴。", ["数"]], "11298": ["病机", "两手脉来虚数，虚为胃气不足，数为热邪内扰。原文谓'是胃中不和，津被热燥'，症见寒热减半、舌心微黄、渴饮嗳气，皆胃津受灼、胃气不和之候。虚数并见，示正虚而热未清，故用麦门冬方养胃汁以供肺，兼治痰气蒙神。", ["虚", "数"]], "11299": ["病机", "脉濡缓带涩，与昨之虚数互异，濡缓为湿困中焦、胃气不和，涩示气机不畅。原文谓'寒热稍退之象'，然脘痞、食无味、便泻滑不自主，'五窍不和，都属胃病'，寒热交会中宫，胃当其冲。脉症渐平而湿痰未清，故进温胆法通胃府。", ["濡", "缓", "涩"]], "11300": ["病机", "脉形小弱，小弱为阳气不足之象。原文谓诊时'正寒热初来，脉形小弱，是阳为邪郁，寒退自当复耳'，说明小弱非纯虚，乃邪郁阳气、脉道不畅所致。又思中下皆虚，虚则邪陷难解，故以茯苓饮培扶脾胃、露姜饮壮气攻邪，分时而治。", ["小", "弱"]], "11301": ["病机", "右脉虚软，左微弦而涩。右候脾胃，虚软为脾胃气弱；左候肝，弦涩为气机郁滞、血行不畅。原文谓两日通补'已有小效'，歇亦少减，说明虚软弦涩示脾胃未复、肝郁未舒，故仍以茯苓饮理脾运阳，通补兼施。", ["虚", "软", "弦", "涩"]], "11302": ["其他", "本段未识脉名，原文仅言'诊脉验症颇安'，重点在告诫病后调摄。谓操持萦思、积劳致损，须潜静旷达方得生阳充沛，否则心气愈伤、脾营更耗，病端蜂起。药饵以后天脾胃为主，勿多歧纷缕。此属病后调养与情志致病之论，非脉象主病。", []], "11303": ["病机", "本段未识脉名，据色脉症而论。面黄、苔白、脘中格拒、汤水都呕，三日疟一至，原文断为'足太阳阴微饮结'，即阳气式微、饮邪凝结于中。饮阻胃脘故格拒呕吐，苔白面黄皆寒饮之征，故'当以温药和之'，以温阳化饮为治。", []], "11304": ["病机", "本案少阴疟两月，胃关衰不纳谷，神消形瘦，攻补不应，显系八脉阳虚、邪陷少阴。原文未出脉名，然从“举八脉之阳，阳壮邪可托出”可知脉当沉细微弱，主阳衰邪伏。病机为少阴阳虚，不能托邪外达，故见纳呆形瘦，治当温壮八脉之阳。", []], "11305": ["病机", "三疟日久，奇经损极，邪乘攻络，血从便出，病为伏邪。原文未出脉名，从“救逆汤……重镇之中引以飞走”及“柴葛泄阳”可知脉当虚浮无根，主阳亡外越、奇经不固。病机为奇经亏损，伏邪伤络，血溢便出，治宜固束经脉、镇摄浮阳。", []], "11306": ["病机", "劳倦阳气先伤，营卫皆损，疟无止期，天暖可缓，阴晦病加，身中阳微已著。原文未出脉名，从“壮脉护阳”可知脉当细弱无力，主阳微营损。病机为劳倦伤阳，营卫俱损，阳虚不能御邪，故疟久不止，治当温壮护阳。", []], "11307": ["主病", "邪伏于阴而成三疟，表散不应，脉缓，中焦痞闷。脉缓主太阴脾土虚弱，湿邪内蕴，故中焦痞闷。邪伏阴分，非表散可解，治在太阴，健脾化湿以托邪。脉缓在此示脾虚湿滞，与痞闷相应。", ["缓"]], "11308": ["病机", "疟日发既而间日，寒多无汗，食进不运，诊脉缓濡。缓濡主阳微湿滞，脾运不健，故食进不运；阳微邪陷于阴，寒起四末。脉缓濡与寒多、不运相应，病机为太阴阳微，湿邪内陷，治从太阴温运。", ["缓", "濡"]], "11309": ["预后", "阴疟经年，寒热必喘逆痰升，左脉已结疟母，病在厥阴、少阴，邪混气血为难治。脉结主气血痰瘀互结，疟母成形，络脉不通。结脉与喘逆痰升、疟母相应，示邪深混气血，故为难治。", ["结"]], "11310": ["兼症", "三疟屡止屡发，时见右臂、肩背、胸胁肿凸，旬日自散，络脉不和。脉不和示络气壅滞，营卫失调，故肿凸随起随散。此非府病，乃络脉不和，宜安间静养，药难速效。脉不和与肿凸相应，主络滞。", ["不和"]], "11311": ["病机", "疟久邪结必成疟母瘕，邪深客于阴络，道路深远，肌肤无汗，能食便溺通调，病不在府，从腹下升逆贯膝腰。原文未出脉名，从“八脉中病”“转旋下焦痹阻”可知脉当沉弦或涩，主阴络痹阻。病机为邪结阴络，下焦痹阻，治以通阳。", []], "11312": ["病机", "脉右沉濡，左弦，沉濡主湿浊内蕴、脾阳不运，弦主邪郁少阳、木气偏亢。疟经两月，止而复来，食入便出，腹中隐痛，乃正馁邪陷，脾运失职，湿浊困阻，故脉见沉濡；左弦为邪郁少阳、肝木乘脾之象。正虚邪陷，有延入三阴之虑，故曰谨慎食物。", ["沉", "濡", "弦"]], "11313": ["病机", "脉右小弱，左空弦，小弱主阳气虚馁，空弦主阴血亏虚、肝风内动。形色枯槁不华，舌白不渴饮，病及一月，寒热干呕，神气欲昏，微呃烦不欲寐，汗出，此伏邪久而伤正，阳气日漓，邪陷入阴，胃虚客犯，肝逆乘胃，故见昏烦呕呃。议温胃阳益虚镇肝逆，用旋覆花代赭石汤。", ["小", "弱", "空", "弦"]], "11314": ["其他", "原文未载脉象，仅述三疟，背寒骨束，并无汗战呕逆，治在少阳督脉。三疟为疟邪深伏三阴，背寒骨束乃督脉阳虚、邪客少阳督脉之象；无汗战呕逆，说明邪未从表解，亦未犯胃。治从少阳督脉，以疏达枢机、温通督阳为法。", []], "11315": ["病机", "脉来濡弱，濡主湿浊，弱主脾虚。太阴脾土性畏寒湿，暑湿既在深阴，疟三日一至，饮酒再助其湿，疟痢兼作，肛坠而肠胃不痛，乃湿浊内蕴、脾阳不运，清阳下陷。濡弱之脉正合脾虚湿盛之机，故当理湿以生阳，用桂苓甘露饮分利湿浊。", ["濡", "弱"]], "11316": ["病机", "脉久空，主阴血亏虚、经脉失充。失血数载，经脉久空，瘅寒无热为牝疟，每发于阳气不足之人。柿味甘寒，蟹味咸寒，阳失行宣，寒懔日加而血络并逆，皆因久失血后阴血亏虚、阳气不足，寒从中生，疟邪乘虚而发。脉空正是阴血不足、脉道不充之征。", ["空"]], "11317": ["误治", "脉弱小促，小弱主气血两虚，促主数而时止，为虚中夹滞之象。疟不肯止，皆辛散过投，卫伤则寒，营伤则热，此误治伤正，营卫俱损，故脉见弱小促。用补中益气汤补益中气、升举清阳，使营卫调和，数日可愈。", ["小", "弱", "促"]], "11318": ["病机", "脉濡，主湿浊内蕴、气分窒塞。阳虚之体，迫受暑湿，气分窒塞，故脉濡；舌白、头胀、心悸、口渴，皆暑湿阻遏气机、清阳不宣之象。治以桂苓甘露饮，通阳化湿，分消暑湿，使气机宣畅。", ["濡"]], "11319": ["病机", "脉缓濡，缓主湿浊，濡主湿滞，皆湿邪内蕴之象。夏季过饥，吸受暑湿，膜原浊痹，清气不宣，脘胀腹满，阴囊、足跗皆肿，得泄气少舒，湿与热传至经腑。脉缓濡正合湿浊痹阻气分之机，当分消其气分，使湿去热清。", ["缓", "濡"]], "11320": ["误治", "本案未识脉名，原文以“刮痧震动经脉，体虚不耐”言体虚，又谓“暑湿皆伤气分，气无形质，流行则邪解”，指出暑湿在气分当以流动宣解为法；今用六味填阴，滋腻滞浊，反使暑气壅遏，故断为方法不当。脉象虽缺，病机重在气分邪滞与误补致闭。", []], "11321": ["病机", "脉左小坚劲，小为不足，坚劲为邪郁内搏，合色苍、形肿、午热灼渴、晨微寒、食减，知暑邪乘虚内伏，营卫失和，状如疟；又因吐血屡发，阴伤络损，表散非宜。坚劲非纯实，乃虚中夹暑热郁结之象，故以玉女煎清养为治。", ["小", "坚", "劲"]], "11322": ["病机", "脉小示气分不足而邪郁不宣，舌白、小溲淋闭、大便不爽，皆暑湿著于气分、气阻窍窒之征。原文明言“暑湿著于气分，气阻窍窒”，气化不行则二便不利；治上以“水出高源”，即宣肺气以通水道，脉小正合虚中夹湿、气机壅滞之机。", ["小"]], "11323": ["病机", "脉沉主里，阳虚不喜凉食、气阻膈间，目黄，原文断为“必有冷湿之气内著”。冷湿阴邪内踞，阳气不运，故脉沉而膈间气阻；目黄乃湿郁之征。治用辛温补通，正针对沉脉所主之里寒湿著、阳微气滞病机。", ["沉"]], "11324": ["病机", "左细右滑，左细为心肾不足，右滑主痰湿内蕴。原文谓“心肾虚弱，外受暑湿之邪，暑为火，湿生痰，故病形如类中”，眩晕仆厥、目黄口干溺赤皆暑湿痰火蒙扰之象。细滑并见，正虚邪实，故先清理暑湿痰火，继以补养心肾。", ["细", "滑"]], "11325": ["预后", "病后发厥，神昏口噤、痰响涎流，形似五厥之类；脉细无力，原文直断“乃虚也，补之则愈”。细为阴血不足，无力为气虚不鼓，虚风痰浊因虚上扰而厥。脉不实不数，知非实闭，故预后可补而愈，强调凭脉辨虚实以定吉凶。", ["细", "无力"]], "11326": ["病机", "脉细，右手尤微渺，细为气阴不足，微渺主阳气衰微。头重欲晕、冷汗大出、手足厥逆、小便不利，正值夏月劳苦，暑热耗气，清阳不升，阳随汗泄而厥。原文作“暑厥治”，正因脉细右微示气分虚陷、暑伤元气之机。", ["细", "微"]], "11327": ["病机", "脉虚为胃气不足之象。原文谓“厥阴气冲昏厥，都因阳明脉虚”，阳明虚则土不制木，厥阴风阳上冲而昏厥；通泄和阳不能却病，因虚风非实邪可折。议填胃土以熄虚风，即补土培中、使木得所养，脉虚正是辨治眼目。", ["虚"]], "11328": ["病机", "脉浮数属阳热扰气，细涩为血菀成瘀之征。原文谓\"午后气并于血，升降清浊为厥\"，劳烦拂郁致肝血瘀聚脘腹，故脉浮数而细涩，主瘀热内阻、清浊升降失常之暴厥。面黄唇白、胸腹隐痛非停滞，乃瘀聚；目荒舌缩为肾水竭绝，瘛疭为肝虚风动，脉象正合瘀郁兼虚之病机。", ["浮", "数", "细", "涩"]], "11329": ["预后", "原文以\"脉大易愈，脉细难痊\"立论，今脉细而目睛无神、交夜糊涂、口渴，是病在重阴。脉细为气血衰少、阴分受困之象，神失所养故目睛无神、夜则糊涂；阴伤津不上承故口渴。脉细与神衰并见，说明癫疾根深难拔，故断为不能去根，属预后判断。", ["细"]], "11330": ["病机", "恼怒则肝火炽盛，惊恐则肝胆俱病，木火交亢致癫妄神昏。脉左弦为肝火郁勃之象，右滑为痰浊内蕴之征，故原文断为\"火郁生痰\"。痰火煽动肝风，故筋惕而胀。左弦右滑并见，正说明肝火与痰浊交结为患，法当抑肝清痰，脉象紧扣火郁生痰之病机。", ["弦", "滑"]], "11331": ["治法", "原文谓风为难愈之候，脉数带滑。数为热盛，滑为痰聚，数滑并见说明痰热内壅、风火相煽。风病日久难愈，而痰热不除则风无从息，故治法\"宜先清其痰\"，以清痰热为治风之先着。脉数带滑正是痰热内盛之据，故本段主旨落在治法。", ["数", "滑"]], "11332": ["兼症", "原文言势稍轻、未能脱体，左弦脉尚存。弦为肝木之象，病势虽减而弦脉未去，说明肝郁气逆之机尚存，故未脱体。左弦独存提示病根在肝，当佐以圣惠三丸续治。本段以脉象判断病情进退与余邪未清，属兼症层面的辨析，脉弦为肝病未愈之征。", ["弦"]], "11333": ["主病", "足麻至心即神昏痉搐、喉有痰声，脉细而沉弦。细为气血不足，沉弦为肝郁风动、痰气内阻。血虚不能荣筋则足麻，肝风挟痰上扰则神昏痉搐、喉中痰声。脉细沉弦正合虚中挟风痰之机，故主归脾汤以养血健脾，脉象说明病本在虚、标在风痰。", ["细", "沉", "弦"]], "11334": ["病机", "原文未识脉名，纯以症候立论。肝风内舞、痰因火升，左边头顶手足肩腹俱有牵绊之象，乃厥阴经脉所过之处为痰火缠扰。痰火不清则症必复发，故强调清心戒怒、静养可痊。本段主旨在于阐明痰火缠扰厥阴、风动致牵绊的病机，并指出情志调摄为防复关键。", []], "11335": ["病机", "原文引仲景\"短气不足以息者，实也\"，指痰饮逆气而言，尊恙恰合此条。舒气稍长即胸脘作痛，为痰饮阻遏气机之象；而右脉细弱，右主气分，细弱示气分不足、脾运不健，故痰饮得以内生。脉症合参，说明本证属本虚标实，法当温通以化饮行气，脉细弱正是虚寒之据。", ["细", "弱"]], "11336": ["病机", "脉左小右（原文仅标左小），左小示心血不足、生阳不舒，右未言大，合参“气馁则痰滞”，是心脾气馁、升降出入废弛。少年郁症、惊病肝胆，至六旬血衰痰生，胸膈右不融畅、便燥臂痛、鼻不知香臭，皆营卫不流之征，故曰恐为厥中根基，治宜补心脾、化痰利气。", ["小"]], "11337": ["病机", "脉弦带数，弦为肝木郁滞、气郁中焦，数为郁则成火。五更寅卯木旺，肝阳上冲，故喝喝如太息、间有腐臭。怀抱不舒致少阳生气不伸，郁火内扰，故宜清理肝肺。此脉此症，主肝郁化火、木火上逆之病机，非单纯外感。", ["弦", "数"]], "11338": ["病机", "脉细左弦，细为阴血不足，左弦为肝郁化火。心热汗出不得寐、舌苔黄厚而不作渴，是心肝郁火内扰、阴不制阳。病始齿痛，亦火自肝经上炎之征。细弦并见，说明火郁而阴已伤，故理宜壮水以制火，不可纯用苦寒。", ["细", "弦"]], "11339": ["病机", "脉右沉左弦，原文自释“沉则气滞，弦则木郁”，郁则少阳生气不伸。腹鸣气上冲心，属厥阴症；怵惕忧虑不能自禁，是肝病及心肾。沉弦并见，示气滞于内而木郁不达，故宜开宜镇，开其郁滞、镇其冲逆。", ["沉", "弦"]], "11340": ["病机", "头眩脉弦，弦为肝阳偏亢之象；清晨呕痰，是肝阳上扰、痰随气逆。又兼酒之湿热，湿生痰、痰助火，故痰火相合而眩呕并作。此脉此症，主肝阳挟痰湿上扰之病机，非虚眩可比。", ["弦"]], "11341": ["病机", "头眩心跳而脉软，软为气血不足、脉道不充之象。头眩属清阳不升，心跳属心气不足，脉软正合虚象。此段脉症简略，主旨在于以脉软辨其眩悸属虚，非痰火实扰，故所主为气血亏虚、心脾不足之病机。", ["软"]], "11342": ["病机", "左脉细而弦，细为肝肾阴血亏虚，弦为肝木失养而劲。头重眩是虚阳上浮，足软弱是下元不充，正合“肝肾虚症”。细弦并见，说明虚中夹郁，非实弦可比，故主肝肾亏虚、木失滋荣之病机。", ["细", "弦"]], "11343": ["病机", "原文未识脉名，故脉象要素从缺。操持烦心则阳气多升，肝胆相火内风震动莫制，遂眩晕惊惕；湿热由胃脉下注跗足而脓水，是痿厥中风之萌。全段以病机推演为主，示阳升风动、湿热下注，治当秋冬藏聚、温养经脉佐温通。", []], "11344": ["病机", "脉小紧数，小为阴伤，紧主内风升举，数为阳越。原文谓“阳气内风升举，眩晕肢麻，遗泄颇频，阴气先已暗伤”，下虚上实，二气失交，故脉小紧数。中年以后痱中厥仆至矣，治在藏阴，正合脉小紧数所主之阴亏阳浮、内风欲动之机。", ["小", "紧", "数"]], "11345": ["病机", "脉得动博，动为阳升，数为热迫。原文谓“劳心烦剧，阳易升越，内风陡起，遂致眩晕欲仆”，又言“冬季少藏，不耐天暖气泄”，皆阴不敛阳、风阳上扰之象。动博之脉正应阳升风动，故法当填阴收纳，以培风蛰，非二陈汤治痰眩所能摄纳。", ["动", "数"]], "11346": ["病机", "脉小涩，小为脾阳衰微，涩为气血不流。原文谓“脾阳衰微，食入不运，汤饮更易壅积，脾恶湿也”，湿浊内壅则脉道不利，故见小涩。此非实邪壅塞，乃阳气不运、清浊相干，故曰“非破气所宜”，当薄味令清气流行，以复脾运。", ["小", "涩"]], "11347": ["病机", "脉右虚数，右候脾胃，虚为胃气少谷，数为热蒸。原文谓“质薄胃弱”“中乏谷气坐镇少权”，又言“日加热蒸，斯震动之气上翔，胃气不安其位”，故寒热未止而频加呃逆。虚数之脉正示胃虚少谷、阳土失润、虚热上扰之机，法当甘缓益胃。", ["虚", "数"]], "11348": ["病机", "脉弦而细，弦为肝木亢逆，细为肾阴亏少。原文谓“气上冲心，心内热疼”，又辨“暴病为邪热内陷，久病为水不涵木”。久病弦细并见，正是水不涵木、肝阳上逆之征，故宜滋肾以生肝，使阴充则木得柔，冲逆自平。", ["弦", "细"]], "11349": ["病机", "脉象左弦大，左候肝，弦为肝阳亢盛，大为气火有余。原文谓“咽喉如有线牵引，不便俯仰”，此肝阳循经上射于肺，肺失清肃，咽络拘急。弦大之脉正应肝阳射肺之机，故以左脉候之，主病在肝肺气逆。", ["弦", "大"]], "11350": ["病机", "脉象左弦右细，左弦为肝阳内扰，右细为土气不足。原文谓“肾阴不足，肝阳内扰，筋跳强中，多食易饥，皆水亏木亢之故”，又言“木侮土则腹中如胀，气闭不爽”。弦细并见，正示水亏木亢、肝脾不调之机，故宜益木培木。", ["弦", "细"]], "11351": ["病机", "脉象左手弦劲，左候肝，弦劲为肝阳升逆、真阴不足。原文谓“先天真阴不足，水亏则火易上炎，加以肝阳升逆，背心烘热，倏作倏止，常时干呕，痰带微血”，皆水亏木亢、虚火上炎之候。弦劲之脉正应肝阳偏亢，故与清肝，勿据用滋腻药。", ["弦", "劲"]], "11352": ["病机", "脉细带弦，细为阴血不足，弦为肝气劲急。颤振不止乃肝风内动之象，肝血虚则筋脉失养，肝风扰则肢体震颤。此脉细弦并见，正合肝风为害、血虚风动之机，故主颤振之症。", ["细", "弦"]], "11353": ["病机", "脉沉弦，沉主里主郁，弦主肝胆气机不畅。嘈杂心悸、畏人、夜梦纷纷，皆心神受病之症。沉弦之脉提示痰浊滞于胆经，胆郁痰扰，心神不宁，故见诸症。此脉主痰滞胆经之病机。", ["沉", "弦"]], "11354": ["病机", "原文未出脉名，然述寐中惊跳、目睛忽陷、筋脉挛钓，皆肝热内扰、魂不藏舍之候。肝开窍于目，肝热则目睛异常；肝主筋，热灼筋脉则挛钓。此段以症测机，主肝有热而魂不藏之病机。", []], "11355": ["病机", "左脉弦右脉细，左弦为肝气郁滞，右细为心脾两虚。忧愁悒郁伤神，肾不上交，故应酬无意绪、行动气促。弦细并见，知非痰火实邪，乃归脾汤、宁志膏所主之心神受伤、气血不足之机。", ["弦", "细"]], "11356": ["病机", "脉细弦而重按觉有力，细为阴血不足，弦为肝阳亢逆，重按有力说明邪实非虚。前用补不应，症兼口燥、左胁胀，皆肝阳上亢、郁热伤津之象。此脉主肝阳上亢之病机，故暂进清肝法。", ["细", "弦"]], "11357": ["病机", "左脉尚沉弦，沉主里，弦主肝。用清肝法后觉外寒，乃气血久虚之故，然左脉仍沉弦，说明肝经郁滞未解。脉症合参，仍当从肝论治，此段以脉定治，主肝郁未罢之病机。", ["沉", "弦"]], "11358": ["病机", "左脉弦细为心肾阴血不足，右脉滑大为痰涎壅盛。神气模糊、夜不能寐、心忡腰痛、舌苔黄垢，皆痰涎沃胆、心肾两虚之候。弦细与滑大并见，虚实夹杂，故宜先清后补。", ["弦", "细", "滑", "大"]], "11359": ["病机", "脉之滑大虽减，犹带数象，滑大为痰热壅盛，数主火旺。心忡稍缓而心膈仍热、脊腰时痛、夜寐未安，乃水衰不能制火，肝胆厥阳上冒。滑大减而数象存，说明痰减而火未清，故去痰药佐潜降。", ["滑", "大", "数"]], "11360": ["病机", "右寸脉弱，左寸关弦滑。右寸候肺，弱主心气不足，劳心太过则心不摄肾，故梦泄；左寸关弦滑，弦为肝郁，滑为痰滞，思虑伤脾，脾虚生痰，痰停心包，故不寐嘈杂。脉象反映心脾两虚、痰郁扰神之病机。", ["弱", "弦", "滑"]], "11361": ["病机", "原文未识脉名，但引《灵枢》论阳气暮当交于阴，阴𫏋脉满则寐。今阳动于外，神识不归著于里，故不寐。用半夏秫米汤，藉半夏由阳入阴，秫米奠安脾胃，使气不升浮。此段论不寐病机为阳不入阴、脾胃气弱。", []], "11362": ["病机", "脉沉细带数，沉细为阴血不足，数为有热。患者肝火抑郁，扰精房而梦遗，误用温补，壅塞肠胃，气道不行，故饮食少进、嗳气便结、胸腹板硬。脉沉细数示郁火内伏、阴伤液耗，非虚脱之候，乃补药太过致壅塞之病机。", ["沉", "细", "数"]], "11363": ["病机", "左手沉弦带数，沉弦为肝郁，数为肝火不静；右手滑大，关部尤甚，滑主痰，大为热，关候胃，此胃中痰饮不清。因久服桂附甘草，热性留恋胃中，煅炼津液成痰，痰火内伏，得外风触发，故胸膈不宽、呕吐痰涎、汗出。脉示肝火胃痰交阻之病机。", ["沉", "弦", "数", "滑"]], "11364": ["病机", "左手弦细带数，弦为肝火，细为阴伤，数为火旺；右手虚大滞滑，虚大为肺气不足，滞滑为痰滞。肾水不足，不能荣养肝木，肝火升腾烁金，故咳久痰中带血。脉象示肾亏肝旺、肺金受灼之病机，即东方实西方虚。", ["弦", "细", "数", "虚"]], "11365": ["病机", "脉息弦细带数，弦为肝木亢盛，细为肾水亏损，数为相火上炎。患者曾患血症，误进热药，火来乘金而咳，咽喉痛，火流肛门发毒。脉示肾水不足、相火灼肺之病机，反用桂附炮姜燥剂，耗水烁金，故难愈。", ["弦", "细", "数"]], "11366": ["病机", "脉息弦滑，弦主肝火，滑主痰瘀。因酒伤胃，胃中血凝滞不散，随气上升而吐黏腻紫色瘀血；误用滋阴，痰瘀不清，上干肺家而咳，胸膈不舒。脉象示胃中痰瘀不清、肝家有火之病机，故治以理气消瘀清热和胃。", ["弦", "滑"]], "11367": ["病机", "脉息沉涩，沉主郁伏，涩主血滞。平素善饮，酒热贮胃，燔灼津液而渴，恣啖寒凉，致火郁遏不得发泄，流于经络则环跳痛，入肠胃则血痢，达肌表则肤痒干燥。脉沉涩示郁火内伏、气血壅滞之病机，未经发越故也。", ["沉", "涩"]], "11368": ["病机", "脉息沉而带数有力，沉主里，数主热，有力为实。原文谓“感冒暑热之邪”“暴注下迫，皆属于火”，热邪内蕴，故脉沉数有力。热邪上冲，肝为相火，两火相煽，血随火沸上逆；肝气郁而不舒则腹不宁、嗳气、蹇于语言；肝火上升则头眩，下降则腹鸣；扰精房则梦遗，神不宁则卧不安。脉象反映实火热郁之病机。", ["沉", "数"]], "11369": ["病机", "脉息短小，短主气损，小主虚。宾老嗜酒，酒性湿热积于胃，薰灼于口而舌糜碎，下注膀胱而小便浑浊，绵延已久，脾气大虚，饮食减少无味。脉短小正是脾虚之征，然湿热未清，故原文断为“脾虚而湿热未清”，治以健脾气、清湿热，加味六君子。", ["短", "小"]], "11370": ["病机", "脉息洪大，洪大为火盛之象。阴虚火炎而吐血，上烁肺金，腠理不密，外邪乘虚袭肺，咳嗽入于大肠，腹中作痛，下利见血。原文谓“此火得风而炽也”，风火相煽，火势愈炽，故脉洪大。治宜先疏风理气，俟咳嗽稍平，再以滋阴降火培本。", ["洪", "大"]], "11371": ["病机", "脉息弦细带数，弦主肝火，细主阴亏，数主火动。劳力过度伤胃络，血瘀胃中，肝火上升而吐，所来之血厚而黏腻为瘀血。补之太早，余瘀未尽，今春复吐。既吐之后阴血亏，肝火上烁肺金而咳。原文断为“肾水亏损，肝火妄动，肺金受困之象”，脉弦细数正合阴虚火旺之机。", ["弦", "细", "数"]], "11372": ["病机", "脉息弦数，弦主肝郁，数主火。肝火郁于胃中，不得条达通畅，以致作胀攻卫作响，注于大肠则为泄泻，经事不至。原文谓“此乃木郁土中”，木郁化火，横逆犯土，故脉弦数。治宜扶脾疏肝，使木达土安。", ["弦", "数"]], "11373": ["病机", "脉息弦滑，右手关部尤甚。弦主肝郁，滑主痰湿，关部候脾胃。胃中湿痰随火下注精房而遗滑，误以补肾涩精，致湿痰纠结于胃，饮食少进，难以运化。原文断为“胃中有湿痰，肝家有郁火”，脉弦滑正是痰火郁结之象，治宜豁痰清肝。", ["弦", "滑"]], "11374": ["病机", "脉息沉小滑而有力，关部尤甚。沉主里，小主气结，滑主痰，有力为实。劳心思虑，气结痰凝于胃，春三月得不寐，夜间胃中如焚，烦躁不宁，饮食无味。原文谓“肝火郁而不舒，胃中胶痰固结而不通”，引“胃不和则卧不安”，脉沉小滑有力正是痰火内结之实象。", ["沉", "小", "滑"]], "11375": ["病机", "脉息左手弦，右手弦且滑大。弦主肝郁，滑主湿滞，大主邪盛。平昔嗜酒，湿热蕴胃已久，夏令热邪内敛，至一阳和动之时发为痢，邪气流注经络而支节肿痛，俗名痢后风。原文断为“湿热滞于肠胃，失于推荡，以致流注经络”，脉弦滑大正是湿热壅滞之征。", ["弦", "滑", "大"]], "11376": ["病机", "脉洪大而弦滑，洪大为胃中痰热壅盛，弦滑为肝郁化火、痰气交阻。原文谓“胃中有痰，肝家有郁火”，肝火郁于胃中不得疏泄，故寒热如疟、胃脘时痛。弦主肝郁，滑主痰，洪大主火盛，四象合参，正合痰火郁结之机，治宜豁痰理气疏肝。", ["洪", "大", "弦", "滑"]], "11377": ["病机", "左手弦数，原文断为“肝火妄动”；右手洪大，断为“胃中之火不静”。弦数乃肝郁化火之象，洪大为胃火炽盛。火来烁肺则痰中带血，火扰胃血则便红、血随火升。脉象与“余邪未清”“酒热助火”相合，示肝胃火盛、气逆血上之病机。", ["弦", "数", "洪", "大"]], "11378": ["病机", "左手弦数主肝火郁而不舒，右手滑大主胃中痰浊壅盛。原文谓“郁痰郁火症”，肝火煅炼津液成痰，随火上升则咽噎结形、头眩耳鸣，降下则两足麻痹而热。弦数应肝火，滑大应痰浊，脉症相合，示痰火郁结、升降失常之机。", ["弦", "数", "滑", "大"]], "11379": ["病机", "脉息弦数，原文谓肾水不足不能荣养肝木，肝气郁久化火。弦主肝郁，数主火盛。火不下降则两足冰冷，火上蒸于头则发堕目下；产后空虚火易上冲作晕。脉弦数正应肝火郁而妄动，恐扰血分而有堕胎之虑，故宜扶脾疏肝清火。", ["弦", "数"]], "11380": ["病机", "左手弦而带数，原文断为“肝火妄动”；右手滑大，断为“胃中有痰”。弦数应肝火，滑大应胃痰。恼怒伤肝、伤及胃络则吐血，去血过多阴伤，肝火上烁肺金则咳嗽痰多。脉象与“阳络伤则血外溢”相应，示肝火犯肺、胃痰内蕴之机。", ["弦", "数", "滑", "大"]], "11381": ["病机", "脉息弦数，原文断为“水衰火亢，肺金受困之症”。肾水不足不能荣养肝木，肝火上升，又误用发散升提其火，致吐血咳嗽不止、痰涎颇多。弦主肝木，数主火亢，弦数并见正合水亏火旺、木火刑金之病机，故治宜滋阴降火保肺。", ["弦", "数"]], "11382": ["病机", "左手沉弦，原文谓“肝气郁而不舒”；右手滑大，谓“胃中积滞纠结不清”。沉弦主肝郁气滞于内，滑大主痰食积滞壅盛。疟后饮食不节，脾伤不运而成积滞，故胸腹胀满按之坚实、大便不爽、面黄。脉象与积滞内结、肝胃不和之机相合。", ["沉", "弦", "滑", "大"]], "11383": ["病机", "脉息弦数，原文断为“胃不和而余火未清”。胃脘痛呕吐本由肝火郁胃而成，误服热药后虽经清火和胃呕吐已平，但郁久未清、有时上逆。弦主肝郁，数主火未清，弦数并见正示肝胃余火郁而未净、胃气未和之病机，故当和胃清火。", ["弦", "数"]], "11384": ["病机", "脉沉弦而涩，沉主里，弦主肝郁气滞，涩主瘀血阻滞。患者多思多郁，肝火郁于胃中，煅炼津液成痰，阻滞气道，怒伤肝而血郁，故脉见沉弦而涩，此瘀血阻滞胃中作痛之病机，与左胁作痛、按之亦痛、饮食作胀等症相应，久则虑成噎膈。", ["沉", "弦", "涩"]], "11385": ["病机", "脉弦大带数，弦主肝郁，大主火气发泄，数主热。服酒蒸大黄丸后，郁与瘀血从大便去，火气得以发泄，故脉转弦大带数。此内火郁而不舒，三阳结则反之于上，致胸膈不能宽畅、背心作痛，虑成噎膈之症，与大便结粪黑色、肛门觉热相应。", ["弦", "大", "数"]], "11386": ["病机", "左手沉弦，右手关部独见沉滑。沉弦为肝家有郁气郁火，沉滑为胃中有胶痰纠结。恼怒抑郁于胃中，煅炼津液成痰，随肝火上升结于结喉，皮里膜外结成痰块，气滞而日渐以大，故脉见沉弦与沉滑，与痰块肿硬、气滞等症相应。", ["沉", "弦", "滑"]], "11387": ["病机", "脉洪大而弦，洪大为内火郁而不舒，弦主肝郁。冬感寒邪，寒束其火，不得疏泄，流注胸胁，攻冲于胃，误用参耆白术闭其腠理，邪气内伏，故寒热虽止而不清，肺家咳嗽。此内火郁而不舒之病机，与背脊恶寒、寒热似疟、咳嗽等症相应。", ["洪", "大", "弦"]], "11388": ["病机", "左手弦数，右手洪大有力。弦数主肝火不静，洪大有力主胃中余瘀未尽、火势炽盛。幼时梦遗，医以桂附助火，火愈炽而上升，血随火沸而衄血，今纯阳之月，内外火交煽，胃中血大吐不止，胸膈不宽，喉中作痒，此胃中余瘀未尽、肝火不静之病机。", ["弦", "数", "洪", "大"]], "11389": ["病机", "左手弦大带数，右手滑大带数。弦大数主肝家有火，滑大数主胃中有痰。饥饱不时，外邪袭肺而咳嗽，误作劳症吐血医治，郁其血邪在内，郁久乘夏令火气发越，肺家之火流注大肠而为滑泄，并非脾虚作泻。此胃中有痰、肝家有火之病机，与咳嗽、呕、胸膈不舒、滑泄、肛门发热相应。", ["弦", "大", "数", "滑"]], "11390": ["病机", "脉弦滑有力，弦主火郁，滑主痰凝，有力为实。胃中之痰随火升降，昼则随火上升滞于胸膈而作胀，按之有形，饮食难下；夜则随火降下，胸次舒适，注于精房而为梦遗。此胃中痰火随火升降而为患之病机，与胸膈胀满、梦遗等症相应。", ["弦", "滑"]], "11391": ["病机", "两手弦急，弦主肝木亢盛，急主气逆。当春令肝木旺之时，木火垂金，致胁痛气喘不得卧，面青，两胁作痛，不能合眼。无痰声、鼻不煽、无汗出，示非绝症。此肝火犯肺、木火刑金之病机，与胁痛气喘、面青等症相应，治以平肝清火降气。", ["弦", "急"]], "11392": ["病机", "脉息数大，数主热，大主邪盛，与胸中痰火郁结、头面烘热而红相应。原文谓桂附太多积热于胃，煅炼津液成痰，郁火不能外达，故脉数大而大便燥结、胸腹如燎。数大之脉正示胃中郁火炽盛、痰热内结之病机，非虚寒可比。", ["数", "大"]], "11393": ["病机", "脉息虚大，虚为元气不足，大为邪气犹盛之假象。原文述发狂谵语、痰声齁齁似实，然身无大热、胸腹和软、大便滑泻、小便清利，脉虚大不能安卧，正合暑热伤元气、清热药过用致虚。虚大之脉说明元气已伤而痰热未净，故以人参扶元化痰取效。", ["虚", "大"]], "11394": ["病机", "左手弦而带数，右手滑大有力。弦数属肝火炽盛，滑大属胃中痰盛。原文谓肝火上冲于胃，胃中之痰扰心肺之窍，致眩晕瘛疭、不省人事、面红，脉象正示肝火挟胃痰上蒙清窍之病机，故用二陈加黄连、钩藤、胆星等清肝豁痰而胎堕。", ["弦", "数", "滑", "大"]], "11395": ["病机", "脉息甚大，大主邪实痰盛。原文述咽痛已除而胸膈满闷、痰涎上壅、饮食不进、不得安卧，口亦不渴，此胃中有痰而不得卧。脉大与痰涎壅盛相应，说明实痰结于胃胸，非阴虚火旺，故用滚痰丸下顽痰即能安寝，复以二陈加味而愈。", ["大"]], "11396": ["病机", "脉息弦大带数，弦属肝郁，大数属郁火。原文述寡居劳心抑郁，肝气不能条达，致滞下腹痛后重、肛门如火、口干气急、胸膈不宽而恶心。弦大带数正示肝家郁火下注为滞下、上升为呕恶之病机，故用黄芩芍药汤加山栀、黄连、木通等清肝泻火而愈。", ["弦", "大", "数"]], "11397": ["病机", "脉息虚大，继诊虚无力。原文述奔走百里、兼之饥饿，发热自汗不止、倦怠乏力、语言难出，此热伤元气、饥饿劳倦所致。虚大无力之脉说明元气耗散、气不敛汗，非冒暑实证，故以黄耆、人参、白术、麦冬、五味子补气敛汗而汗敛神复。", ["虚", "大"]], "11398": ["病机", "脉息虚大，虚为火衰气弱，大为虚火上炎之象。原文述三消之症，口内干燥、小便如膏、足痿乏力，乃虚火上炎、肺金受灼，诸痿皆属于肺热。虚大之脉说明火衰不能蒸津上腾而虚火浮越，故以生脉散治水之上源、八味丸补火为要。", ["虚", "大"]], "11399": ["病机", "左手沉弦带数，右手沉滑有力。沉弦数属肝火郁于小腹，沉滑属胃中痰饮。原文述肝火为寒凉所遏不得伸越，结成有形之象，攻冲呕逆。沉弦带数示肝郁火伏，沉滑有力示痰饮内结，故宜清肝火、疏肝气、和胃豁痰。", ["沉", "弦", "数", "滑"]], "11400": ["病机", "脉息弦数，弦主肝郁气滞、痛与瘀阻，数主热。患者饥饱不时伤胃络，血瘀于胃，吐黍腻之血，胸膈不宽，乃胃中痰瘀纠结不清。弦为瘀滞不通之象，数为瘀久化热之征，故脉弦数正合痰瘀互结、胃络受损之病机，治以消瘀理气豁痰。", ["弦", "数"]], "11401": ["病机", "左手带弦，右手滑大有力。弦主肝郁气滞，滑主痰湿积滞，大而有力主邪实热盛。暑湿之邪加饮酒太过，蕴蓄于胃，湿热积滞未清，故胸膈不宽、饮食不进、面黄、小便短赤、大便燥结。右关滑大有力正是胃中湿热积滞之明证，治当清湿热和胃理气。", ["弦", "滑", "大"]], "11402": ["病机", "脉息细数无神。细主阴血不足，数主火热，无神示正气已衰。水衰火亢，虚火上升烁肺，故咳嗽吐血、胸腹如燎；下注肛门发毒、大便不实，乃肺虚因热而致，非脾虚。细数无神正合水亏火旺、肺金受困之象，故不宜燥脾，当滋阴保肺清热。", ["细", "数"]], "11403": ["病机", "脉息弦数。弦主肝火亢盛，数主热。患者善怒躁急，内有肝火，外触风寒上干于肺，咳极则血随火沸而出。肾水不足不能荣养肝木，肝火上炎烁肺，肺金受困，故脉见弦数。弦为肝旺之象，数为火炎之征，治宜滋阴降火、清金保肺，并戒恼怒。", ["弦", "数"]], "11404": ["病机", "脉息虚大，两尺尤甚。虚主正气不足，大而无力主虚阳浮越。血症之后肾水不足，虚火上炎烁肺，肾虚不能纳气归源，故稍动作言语即气升而咳。两尺候肾，虚大尤甚正示肾虚气不归源之本质，治宜补肾纳气。", ["虚", "大"]], "11405": ["病机", "脉息弦滑。弦主痰饮气滞，滑主痰湿壅盛。胃中痰火纠结不清，干于清虚之府，致不得安卧、神魂不宁。弦滑并见，正是痰火充塞于胃、痰浊内盛之象，故先以滚痰丸下痰，后用豁痰清火之药，并忌醇酒厚味。", ["弦", "滑"]], "11406": ["病机", "脉息弦数。弦主肝火，数主热盛。先天肾水不足，相火妄动上烁肺金，外邪乘虚袭肺致咳，疏解后外邪已去，惟火气上炎而干咳。弦数为火亢之征，示肺金受困，治宜滋阴清火清肺。", ["弦", "数"]], "11407": ["预后", "脉息不数。前段脉弦数示火亢，今服滋阴清肺药后咳嗽稍减、夜可安寝，脉由数转不数，是火热渐退之征。数脉主热，不数则火气已平，故为渐愈之佳兆；但仍需煎丸并进、静养调摄，方可免劳瘵之疾。", ["数"]], "11408": ["病机", "脉弦大带数滑，弦主痰饮，大数主火，滑主痰积。原文谓“胃中痰积未清”，又因饮食不节郁而化热，胃火上升致鼻衄。此脉象反映痰积与暑邪互结、胃中火热未清之病机，故治宜豁痰疏理清热。", ["弦", "大", "数", "滑"]], "11409": ["病机", "脉洪数，洪为火盛，数为热急。原文谓“食入即吐，是有火也”，又言“肝火上冲于胃而吐”。洪数之脉正合肝胃火盛上逆之机，火性急迫故食入即吐，治当和胃清火。", ["洪", "数"]], "11410": ["病机", "脉虚大带数，虚为阴亏，大为火亢，数为热炽。原文谓“先天肾水不足，相火上炎，销烁肺金而咳嗽，午后发热”，此水衰火亢之象。虚大数脉反映真阴亏损、虚火浮越，故治宜滋阴降火保肺。", ["虚", "大", "数"]], "11411": ["病机", "脉沉滑带弦，沉主里，滑主痰湿，弦主积滞。原文谓“饮食过饱，停滞胃中，纠结成疾，胸膈胀满，按之坚实有形”，此胃中湿热所积、纠结不清之病机。沉滑弦脉正合积滞内结之象，恐成黄疸鼓胀，治宜清湿热豁痰。", ["沉", "滑", "弦"]], "11412": ["病机", "脉虚大带数，虚为气阴亏虚，大为虚火浮越，数为热。原文谓“血证之后，阴分已亏，虚火灼肺而咳”，又言“真阴亏损，肺金受困之象”。虚大数脉反映阴亏火旺、脾肺气虚，故治以补肾纳气、生脉散地黄丸。", ["虚", "大", "数"]], "11413": ["病机", "脉沉伏，沉主里，伏主气机闭阻。原文谓“喉间锁定，不能出声，不知痛痒，手足冰冷，面色白而带青”，此因郁怒而食生冷，气机壅闭、关隘不通之病机。沉伏脉正合气闭于内、阳气不达四末之象，故先以开通关隘为要。", ["沉", "伏"]], "11414": ["病机", "脉数软，数为虚热，软为气虚。原文谓“大病之后，脾肺之气已虚，所以大便作泻，而肛门下坠，四肢倦怠乏力”，此气虚下陷之病机。数软脉反映气分亏虚、中气不足而下陷，故治宜加味补中益气汤升提补气。", ["数", "软"]], "11415": ["病机", "脉滑大，滑主痰积湿热，大主邪盛。原文谓痢下“血积稠黏，里急后重，肛门如火”，又言“烦躁内热，饮食绝然不进”，此湿热积滞壅盛于肠之病机。滑大脉反映邪实内盛，故用大黄、槟榔等峻下积滞，清火而愈。", ["滑", "大"]], "11416": ["病机", "脉大而数，大主热盛，数主火急。痢下泻血水、肛门如火、里急后重，皆火邪暴注下迫之象。火盛耗津，故小便不利。原文“暴注下迫，皆属于火”正合此脉，火邪充斥脉道故大，火性急迫故数。", ["大", "数"]], "11417": ["病机", "左手弦数，右手滑大。弦数属肝火郁勃，滑大为胃中痰饮壅盛。恼怒动肝，火升痰随，闭窍则舌音不清、语言蹇涩、口流痰涎。原文“肝家有郁火，胃中有痰饮”正是弦数滑大之由，乃类中之基。", ["弦", "数", "滑", "大"]], "11418": ["病机", "脉沉弦带滑，沉主里，弦主郁滞，滑主痰湿。暑热之邪未尽，留于肠胃经络，故小便黄赤、腹中不舒似乎有形。原文“暑热之邪未尽”致气机郁滞，脉道不畅故沉弦，湿浊未化故带滑。", ["沉", "弦", "滑"]], "11419": ["病机", "脉息带弦，弦主气机郁滞、饮邪内结。伏邪三载，浊气攻冲为患，虽用疏通清火，脉仍带弦，说明郁滞未解。原文恐“复感暑邪而为疟”，弦脉亦主疟邪内伏，故宜疏理清热。", ["弦"]], "11420": ["病机", "脉弦数带滑，弦属肝火，数主热盛，滑为痰涎。产后感邪，胃中痰火上干于肺，咳久呕涎，口燥疳疮。原文“胃中有痰火，得外邪触动”致弦数滑并见，久则成蓐劳之症。", ["弦", "数", "滑"]], "11421": ["病机", "左手弦大，右手滑大有力。弦大为肝郁火旺，滑大为痰火壅盛。寒邪郁遏胃中痰火，误服滋阴凝滞，肺窍闭而声哑。原文“郁痰郁火为患”，面色红亮、痰不易咳，皆痰火胶结、脉道壅实之征。", ["弦", "大", "滑"]], "11422": ["病机", "脉滑大，滑主瘀血痰浊，大主邪实。胃中瘀血未尽，误用补涩，肝火下注肛门，后重逼迫。原文“胃中余瘀未尽，肝火郁而不舒”，瘀热内壅故脉滑大，补药断不可服。", ["滑", "大"]], "11423": ["病机", "左手带弦，右手滑大带数。弦为肝火妄动，滑大为痰火壅盛，数主火燔。误服温补，闭窍助痰，咳久火炎吐血，肌肉销烁。原文“肝火妄动，胃中痰火燔灼肺金”，舌苔紫色知伏火在内，脉证相合。", ["弦", "滑", "大", "数"]], "11424": ["病机", "脉弦为肝火亢盛，大为湿热壅遏。患者暑热为风寒郁遏，加之恼怒动肝火，上干于胃则呕吐，湿热郁于胃中则腹肿，肝火上升则头面肿痛。弦大脉象反映湿热肝火蕴于脾胃，不得发越，故治宜清湿热、疏肝火、利小便。", ["弦", "大"]], "11425": ["病机", "左手弦大为肝郁火旺，右手滑大有力关部尤甚为胃中痰火壅盛。肾水不足不能荣养肝木，肝火郁于胃中，煅炼津液成痰，外为风寒所触，痰火上干肺家而喘嗽不得卧。脉象揭示肝郁火、胃痰之病机，故治宜豁痰理气疏肝。", ["弦", "大", "滑"]], "11426": ["病机", "脉虚细为真阴亏虚，数为虚火内炽。风寒袭肺日久伤肺，痰中带红，真阴受伤，虚火烁肺而咽痛。稍有语言动作气即上逆而咳，此肾气虚不归原。虚细带数脉象反映肾虚不纳气、虚火烁肺之病机，故治宜滋阴补肾纳气保肺。", ["虚", "细", "数"]], "11427": ["预后", "脉数大无神为元气外脱、虚阳浮越之象。血症后肾虚肺伤，耳聋为肾绝，自汗为气脱，大便不实为脾虚，皆属不治之症。数大无神脉与肾绝气脱相应，表明正气衰败，故虽以补肾纳气之药，仅安病者之心，预后不良。", ["数", "大"]], "11428": ["病机", "脉弦滑带数为肝火郁而化火、痰热内结之象。肝火郁于胃中不得疏泄，胸膈不宽，分娩后肝火上冲于胃而呕吐，食即吐是有火。脉按之和软、流走不定，说明肝气郁结化火，结成有形之象。故治宜和胃清肝。", ["弦", "滑", "数"]], "11429": ["病机", "脉数带弦为水衰火亢之象。先天肾水不足，不能荣养肝木，肝火上升，血随火沸而吐。今春木气升腾，吐血又作。数脉主火亢，弦脉主肝旺，反映肾水亏虚、肝火亢盛之病机，故治宜滋阴降火。", ["数", "弦"]], "11430": ["病机", "脉滑而有力为痰食内滞、胃中壅实之象。食物停滞胃中，以致恶寒，胃火上蒸而为汗，似乎有疟之状。滑主痰食，有力主实滞，反映食停胃中、痰火内蕴之病机，故治宜豁痰疏理胃中之滞，使胸膈舒畅。", ["滑", "有力"]], "11431": ["其他", "脉息调和为正气渐复、病势向愈之象。胸次黄瓜之形已无，惟胸膈作胀不舒，舌色带黄，嗳气不减，此浊气欲散而不能下降。脉调和说明整体病情好转，但余邪未清，故以疏理浊气清肝火之药丸服，以善其后。", ["调和"]], "11432": ["病机", "脉息弦大，弦主肝郁，大主火盛，故断为内有郁火。郁火内伏，阳气不达外，故至晚凛凛似寒，此疟之基也。胸次作胀，乃胃中余瘀未清、浊气壅滞，脉弦大亦应肝胃气壅、郁火未清之机。", ["弦", "大"]], "11433": ["病机", "脉息滑大有力，滑主痰，大主热盛，有力为实，故知痰与瘀血互相纠结于胃。痰热内壅则胸膈不宽，热极伤络则大小便下血，脉象正应痰瘀胶结、邪实有余之病机。", ["滑", "大"]], "11434": ["病机", "左手沉弦，右手滑大，沉弦为肝郁火伏，滑大为胃中痰壅。素有疮疾乃脾虚湿热，暑邪乘虚而袭，痰火内郁，故胸膈不宽、外畏风寒，脉象示肝胃痰火交阻，恐发疟而咳嗽。", ["沉", "弦", "滑", "大"]], "11435": ["病机", "脉息数大无力，数主火，大而无力为虚，乃水衰火亢、相火上炎干胃之象。肾阴不足则虚火浮越，故唇口时肿、眼目多眵；值十六成人之时精气不足，脉症相合，若不静养滋阴，恐酿成劳瘵。", ["数", "大"]], "11436": ["病机", "脉息沉弦带数，沉弦主肝郁，数主火，乃肝火郁于胃中不得疏泄之故。肝郁化火，横逆犯胃，则嘈杂作酸；气郁血滞，则经事不调。脉象紧扣肝火郁而不舒之病机。", ["沉", "弦", "数"]], "11437": ["病机", "脉息数大无力，数大为邪热未清，无力为阴已耗伤。因滋阴太早，邪热凝滞不得发越，上干肺家而咳嗽痰红；日久阴为邪热所耗，脉象示正虚邪恋，故有酿成劳瘵之虞。", ["数", "大"]], "11438": ["病机", "左手弦，右手滑大，关部尤甚，弦主肝，滑大主痰积，关候脾胃，故知胃中痰积胶固不清。痰积阻其道路，饮食不得下达，复感外邪则疟疾窃发，脉象正应痰积胶固、胃气壅滞之机。", ["弦", "滑", "大"]], "11439": ["病机", "左手沉弦，右手滑涩有力，沉弦为肝气郁滞，滑涩为痰瘀互结。肝藏血，气滞则血不流行，停滞于中，随火上升而吐，故夏令咳嗽瘀血些少。脉象示肝郁气滞、血瘀痰凝之病机。", ["沉", "弦", "滑", "涩"]], "11440": ["病机", "左手弦为肝胆郁火上升，右手滑大有力为胃中痰饮壅盛。原文谓“心事怫郁，肝胆之火上升，充塞耳窍”，误补则窍愈塞、眉棱作痛，正合《内经》“九窍不利，肠胃之所生”，故脉弦主肝郁、滑大主痰饮，病机为肝火胃痰交阻，治当和胃豁痰、开郁清火。", ["弦", "滑", "大"]], "11441": ["病机", "原文谓出痘失于清火解毒，致“颈间结积累累而起，脉大而火旺，肾水为之耗消”。脉大而火旺，是热毒炽盛、耗伤肾水之象，火毒留结颈间成毒，故脉大主火旺、主毒盛，病机为火毒未清而阴液已耗，治以滋阴清火解毒。", ["大"]], "11442": ["病机", "左手沉弦为肝家郁火内伏，右手滑大为胃中痰饮壅滞。原文谓“胃中湿热痰饮，气滞不行，郁而为黄”，湿热不清则胸膈不宽、食不消化，脉沉弦滑大正合肝郁胃痰湿热之机，故主黄疸，治宜理气豁痰清湿热。", ["沉", "弦", "滑", "大"]], "11443": ["病机", "左手沉弦带数为肝胆郁火内炽，右手滑大有力为胃中痰饮壅盛。原文谓酒热贮胃、煅炼津液成痰，致夜卧不安，并虑“痰随火升而颠仆，为类中之疾”。脉沉弦数主火郁，滑大主痰，病机为肝火胃痰相搏，治宜豁痰清火。", ["沉", "弦", "数", "滑"]], "11444": ["病机", "左手沉涩有力为瘀血内结，右手洪滑有力为湿热壅盛。原文谓吐下瘀血后“左边结成有形之块”，目黄溺黄，乃“瘀血湿热，互相纠结，郁而为黄”，脉沉涩主瘀、洪滑主湿热，病机为瘀热互结，虑成鼓胀，治宜清瘀行滞清湿热。", ["沉", "涩", "洪", "滑"]], "11445": ["病机", "脉弦滑有力，原文谓“饮酒过度，湿热薰蒸之故”。弦主肝郁气滞，滑主湿热痰浊，湿热郁于胃日久则胸膈不舒、目溺皆黄，成黄疸之疾，并虑实而为鼓胀。脉象与湿热薰蒸、气机壅滞之机相应，治宜清湿热利小便。", ["弦", "滑"]], "11446": ["病机", "脉弦滑有力，原文断为“胃中之痰，与肝家之郁火”。饱食用力致胃络损、瘀血留中，误补则痰郁愈甚，梦遗日甚。弦主肝郁，滑主痰浊，郁火痰浊交阻，故遗滑属郁者居大半，治宜开郁豁痰清火，澄源而流自清。", ["弦", "滑"]], "11447": ["病机", "左手沉弦而小，为肝木郁于胃中、不得条达之象。原文谓思虑抑郁，木火发越则胃脘痛、头面肿胀出水，春令升腾则呕逆大汗，痛则便闭、胸胀作酸，皆肝郁不得疏泄所致。脉沉弦小正合肝郁气滞、木火冲胃之机，主胃脘痛及类中之变。", ["沉", "弦", "小"]], "11448": ["病机", "左手沉弦主肝郁气滞，右手滑大主胃中痰火郁结。原文谓“胃中郁痰郁火，纠结不清”，痰火阻滞道路，故胸膈不宽、食难运化而胀；流于四肢则麻痹，达于肌肉则发红瘰、肌肉跳动。热极反寒、反兼水化，故胸中冷气上升。脉象反映痰火内郁、气机不畅之病机。", ["沉", "弦", "滑", "大"]], "11449": ["病机", "左手沉弦主肝气郁滞，右手寸关沉滑有力主肺胃痰火壅盛。原文谓“肺中有伏火，胃中有痰饮”，火为寒闭，触则伏火上升而喘急，胃痰随火上逆则夜不得安寐。脉沉滑有力，正是痰火内伏、气逆不降之象，故当清肺降气豁痰。", ["沉", "弦", "滑", "有力"]], "11450": ["病机", "脉洪滑主湿热蕴盛。原文谓“湿热蕴蓄于胃，发于肌肉而为红瘰，遍身搔痒”，误以风治则多汗、两足麻痹。洪为热盛，滑为湿痰，湿热郁于胃，火上升而不下降，故脉见洪滑。此脉象说明湿热内蕴、胃火上炎之病机，治宜清湿热凉血。", ["洪", "滑"]], "11451": ["病机", "脉弦滑主暑热蕴胃、痰食阻滞。原文谓“热而不寒者，瘅疟也”，暑热之邪蕴蓄于胃，食物阻滞而为热。弦主气机不畅，滑主痰食内蕴，故脉见弦滑。此脉象反映暑热与痰食交阻于胃、发为瘅疟之病机，治宜清暑热和胃气。", ["弦", "滑"]], "11452": ["病机", "脉弦滑，右关尤甚，主痰食气滞。原文谓“木郁于土中久矣”，肝火抑郁，津液聚而为痰，胃中纠结不清，得外暑热互相为患而成疟。小腹动气知木郁不条达，面白带青、胸膈不宽知胃痰未清。无痰无食不成疟，脉象正示痰食气滞、肝郁不舒之病机。", ["弦", "滑"]], "11453": ["病机", "左手沉弦带数主肝气郁而不舒，右手滑大有力主胃中湿痰。原文谓“抑郁不舒，气道不通，外为寒邪所郁，郁久生痰，阻滞经络”，故周身肌肉麻木、头眩晕、冷汗时出。沉弦数示肝郁化火，滑大示痰湿内盛，脉象反映肝郁痰阻、气机不畅之病机。", ["沉", "弦", "数", "滑"]], "11454": ["病机", "左手沉弦主肝郁，右手滑大有力、关部尤甚主肺胃痰火瘀滞。原文谓“肝抑郁，肺胃间痰火瘀滞不清”，痰与瘀血纠结上焦，凝滞不通故不能嗳气；得暑热煽动则吐紫黑黏腻瘀血。脉象反映肝郁气滞、痰火瘀血互结之病机，治宜消瘀理气豁痰。", ["沉", "弦", "滑", "大"]], "11455": ["病机", "左手沉弦主肝郁，右手滑大有力主肺胃痰火。原文谓“肺胃中有郁痰郁火，纠结不清，稍有动触，即时窃发”，外邪触动痰火，上干肺家则喘急不得卧、嗽出黄痰。脉象反映痰火内伏、气逆不降之病机，此痰火之哮喘，治宜豁痰降气清火。", ["沉", "弦", "滑", "大"]], "11456": ["病机", "脉息虚大，两尺尤甚，虚为正气不足，大为虚阳外浮。先天肾水不足，不能荣养肝木，肝升而心神不宁，故脉虚大；两尺候肾，尤甚说明肾精亏虚为本。兼脾胃衰弱则饮食少进、四肢倦怠，脉症相合，皆属虚损之象，故治以归脾、地黄培养心肝、补肾益精。", ["虚", "大"]], "11457": ["病机", "左手沉弦带数，右手沉滑。沉弦带数为肝郁化火之象，肝火郁于内故脉沉弦而数；右手沉滑主胃中痰饮。痰随火升，头额作痛、痛极呕吐酸水，火越则痛止，正是痰厥头痛之机。脉象与痰火纠结之症相应，故治宜清肝火、化痰饮。", ["沉", "弦", "数", "滑"]], "11458": ["病机", "脉息滑大有力，滑主痰，大主邪盛，有力为实。膏粱厚味积久，郁痰郁火胶固于中，无从出路，致喘急喉锯、吐黄黑黏痰、腹胀坚实、四肢头面皆肿而成鼓胀。脉滑大有力正应痰火壅盛、积聚坚结之实象，故用滚痰丸逐之，非虚证可比。", ["滑", "大"]], "11459": ["病机", "左脉弦细而数，右脉寸关滑大。弦细而数为肝家有火、阴分受灼；右寸关滑大为肺胃痰浊壅盛。饮食阻滞郁而为火，煅炼津液成痰，外触风寒上干于肺而咳，痰带粉红系咳伤肺络。脉象分见左右，正合肝火与肺胃痰浊纠结不清之病机，故治宜豁痰降气清火。", ["弦", "细", "数", "滑"]], "11460": ["病机", "脉息数大，两尺尤甚。数为火，大为热盛，两尺候肾，尤甚说明相火妄动于下。先天肾水不足，水衰火亢，相火上炎烁肺则咳嗽，下流肛门则发毒。时令炎威，肺金受制，脉数大正应火亢之机。故先宜静养，再以滋阴保肺、纳气降火之药，防酿成劳瘵。", ["数", "大"]], "11461": ["病机", "左手脉息虚软，右手滑大。虚软为肺气耗散、水之上源已绝，肾水因之亏损；滑大为胃中臭秽之痰壅盛。醇酒生冷夹杂入胃，酿痰烁肺，咳而出痰似肺痈而实由胃来。左虚软右滑大，正合水衰火亢、肺金不足而痰浊未清之机，故治以豁痰清肺兼补肾降火。", ["虚", "软", "滑", "大"]], "11462": ["病机", "脉息沉小，沉主里、小主虚。多思气结、多郁肝木不疏，脾土受困，饮食不化而泄泻；湿胜则濡泄，诸湿肿满皆属于脾，脾不运化，湿聚为肿，腹皮渐大、头面四肢阴囊阳道俱肿。脉沉小正应脾虚湿困、阳气不伸之机，故暂用风能胜湿，继以胃苓汤缓治。", ["沉", "小"]], "11463": ["病机", "脉息数大，数为热，大为火盛。童年小便浑浊乃疳积，热久则腹胀、肌肉消瘦，即幼科所谓疳火。内火消烁，故善食而形瘦，脉数大正应内火炽盛之机。此脉主疳火积热，与善食、腹胀、消瘦诸症相应，故理宜清火消积之药治之。", ["数", "大"]], "11464": ["病机", "脉息弦数，弦主肝胃气滞，数主火热。原文述酒热伤胃，胃脘作痛，血热妄行而吐血，火来烁金而咳嗽，久嗽伤肺，不能清肃下降，小便不利，足跗浮肿。此脉象反映胃热伤肺，火逆上炎，故烦躁咽干。弦数为热盛气逆之征，与吐血、咳嗽、浮肿相应，治宜清肺胃之热，降气豁痰。", ["弦", "数"]], "11465": ["病机", "脉息沉弦而数，沉主气滞于里，弦主肝郁，数主火。原文述抑郁不舒，肝气不得疏泄，血为气滞而停蓄，血大下后肝火升腾，肺金受烁，咳嗽气急，小便不利而为胀满，气喘不得安卧。此脉象示肝金郁火烁肺，气逆不降，故喘急不得卧而肿，治当清肺为主。", ["沉", "弦", "数"]], "11466": ["病机", "脉息洪大带数，两尺尤甚，洪大主火热亢盛，数主火，尺甚示肾虚。原文述去夏水衰火亢而吐血，今夏令炎威，其气上逆不能下降。此脉象为肾虚而气不归元，火不降而上逆，故吐血复发，酿成劳瘵。治宜滋阴降火，纳气归元，习静调摄。", ["洪", "大", "数"]], "11467": ["病机", "脉息弦数，两尺尤甚，弦主肝火，数主热，尺甚示肾水衰耗。原文述平素善饮，酒热贮胃，薰蒸烁肺，扰血分而吐血，吐后肾水衰耗，相火上炎，咳嗽梦遗。此脉象乃水衰火亢，肺金受困之象，故咳嗽、梦遗并见，治宜纳气补肾清火保肺。", ["弦", "数"]], "11468": ["病机", "脉息滑大有力，滑主痰瘀互结，大主邪实。原文述用力过度伤胃络，阳络伤则血外溢，所来之血不鲜明，乃瘀血阻滞胃中，加之醇酒扰血沸腾。此脉象示瘀血互相纠结于胃，实邪壅盛，故血出不鲜，治暂用豁痰理气消瘀之药。", ["滑", "大"]], "11469": ["预后", "脉息细数无神，细主阴血亏虚，数主虚火，无神示胃气困惫。原文述血症多年，滋阴降火或愈或发，今夏令肺金受烁，咳嗽不已，血随火沸，上气喘急，午后发热，饮食少进无味。此脉象为肾虚兼脾胃气困惫，故目下当以胃气为主，滋阴寒凉暂作缓图。", ["细", "数"]], "11470": ["病机", "脉息左手沉弦带数，右手稍大于左而带滑。沉弦数主肝火郁于内，滑主痰瘀。原文述用力过度兼饮食太过伤胃络，阴络伤则血内溢，停蓄肠胃而成便血，肝火下注发为痔疮血痢，瘀血逆上而吐，胸膈咽噎窒塞。此脉象示肠胃瘀郁未清，气滞痰凝，郁久成火，故手足心烦热，胃中纠结坚硬而痛。", ["沉", "弦", "数", "滑"]], "11471": ["病机", "脉息弦细而沉，弦主肝郁，细主湿滞，沉主里。原文述三月木旺脾土受制，目疾为肝火上炎；四月胃脘为物所触，服消瘀行血药后胸腹反满闷作胀，小便黄赤短少。此脉象乃肝木郁于脾土之中，湿热聚而为胀，故治宜疏肝散湿热。", ["弦", "细", "沉"]], "11472": ["病机", "脉息虚弦，虚为脾土不足，弦为痰饮内停。脾虚不能运行津液，聚而为痰，故咳嗽痰多、胸膈不舒、饮食少进；土不生金，肺虚不能固表。值夏令湿热，暂以豁痰健脾保肺治标，待胸次舒畅再补肾固本，脉象正示脾虚痰滞之机。", ["虚", "弦"]], "11473": ["病机", "脉息细数，两尺尤甚。细为真阴亏损，数为相火内动。因奔走劳动伤肾，肾水不足，相火炎上烁肺而咳；今咳减而阴亏未复，故劳倦乏力、两足痿软。尺部尤甚，正合肾水不足、相火上炎之病机，治当滋阴保肺。", ["细", "数"]], "11474": ["病机", "脉息弦急，弦主肝郁，急主痛。少腹右边结块日渐以大，上干胃家而呕吐寒热，此瘕聚借气成形，即子疝；近散至左边作痛不宁。弦急之脉正应肝气郁结、气聚成形而作痛，故治以疏肝和胃，使气疏则块散痛止。", ["弦", "急"]], "11475": ["病机", "脉息弦数，弦为肝气郁结，数为郁而化热。病起肝气不舒而成胀满，行药通便虽减，然肝气郁于脾土之中复胀。原文谓木旺火衰之象，实指肝木横逆、脾土受困，郁热内蕴，故脉弦数，治宜和胃疏肝以解郁泄热。", ["弦", "数"]], "11476": ["病机", "脉息滑大，滑主湿，大主热盛。湿热郁蒸于胃中而为黄疸，故作胀、作酸、作肿，并有带下。滑大之脉正应湿热纠结不清、壅滞中焦之机，故治宜清湿热之药为主，湿热去则胀、酸、肿及带下自减。", ["滑", "大"]], "11477": ["病机", "左手沉弦，为肝气郁结；右手滑大有力，为胃中痰火纠结不清。郁则气结，津液聚而为痰，阻滞食物不得下达，随肝家郁火上升则呕吐而出，合噎膈之症。脉象分见两关，正示肝郁痰火交阻之病机，故治以豁痰降气清火润肠。", ["沉", "弦", "滑", "大"]], "11478": ["病机", "脉息左弦右滑，左弦为肝木偏旺，右滑为脾湿内盛。平素善饮，胃中湿热纠结，湿胜则濡泄而大便泄泻，湿伤筋则手足牵引，湿热生风上干于目则左右目大小不等。弦滑并见，正示肝木乘脾之机，故治宜扶脾疏肝。", ["弦", "滑"]], "11479": ["病机", "脉息虚小无神，虚为脾胃气弱，小为正气不足，无神则肾气亦衰。咳嗽之后脾胃两虚，五更泄泻，乃肾虚不能闭藏、脾虚不能健运之故。脉象虚小无神正应脾肾两亏之机，故先以健脾和胃之剂调治，忌生冷油腻以助运化。", ["虚", "小"]], "11480": ["兼症", "原文未识出脉名，仅言“尺脉不宁”，指尺部脉动不安。尺候肾与下焦，咳嗽吐痰带血而尺脉不宁，提示下焦不固、虚火扰络，血随咳逆而上；夜卧不宁、梦寐颠倒，乃肾阴不足、心肾不交、神不守舍之象。脉象模糊，故脉素从缺，主病机为下焦虚火、心神不宁。", []], "11481": ["病机", "脉息弦数而细，弦为肝郁，数为火，细为脾土虚。产后饮食少进、胸膈不宽、作酸作胀、大便不实，显系脾土虚弱、肝木郁而乘之；肝火烁肺则久咳。原文断为“脾土虚而肝木郁，肝火来烁肺金”，脉与症合，故先扶脾疏肝，后滋阴培本。", ["弦", "数", "细"]], "11482": ["病机", "脉息弦而带数，右手滑大。弦主肝郁，数主火，滑大主痰饮壅盛。胃中痰饮积聚，上泛于目则目睛昏瞀，胸膈不舒、饮食不化。原文谓“肝木郁于胃中，随火上泛”，右手滑大正应胃中痰火，故治以和胃豁痰、燥湿清肝。", ["弦", "数", "滑", "大"]], "11483": ["病机", "脉息弦数，弦为肝火煽动，数为热。胎前内热，肝火不得疏泄，下注为泄泻，经云“暴注下迫，皆属于火”；产后未清之血停滞下焦，发为肠痈、痢疾后重；肝火上升则目眵，煅炼津液则为带下。面色白而带红，亦肝火之征，故治宜清肝疏肝。", ["弦", "数"]], "11484": ["病机", "脉跳动、左手弦大。弦大主肝火亢盛，跳动为火气冲动。先天肾水不足，不能荣养肝木，肝火上冲于胃，胃中津液煅炼成痰，痰火闭塞鼻窍而生瘜肉；胃脉环唇口，肝火冲动则肌肉牵引而动；肺气壅塞，注于手而寸口鱼际跳动。脉症合参，皆肾虚肝火痰郁之机。", ["弦", "大"]], "11485": ["预后", "脉息数大无伦，数主热，大主邪盛，无伦为脉失和缓之序。形寒饮冷，肺受水注，郁而发热咳嗽；瘀血凝滞胃家，反用地黄凝滞，壅塞道路，气愈逆。数大无伦示邪壅正溃、内败之兆，故虽用疏理亦不取效，原文议其“内败”，属预后不良。", ["数", "大"]], "11486": ["病机", "脉息沉细而数，沉主里，细主阴伤，数主热。夏受暑热，秋患痢，下药行之，积物不忌，壅塞胃中，火邪不得发越，致呃逆、面赤目红、舌黑苔、后重尿赤。沉细数正合热邪为食物郁遏、不得条达之机，故暂用疏其胃中壅滞。", ["沉", "细", "数"]], "11487": ["病机", "脉息反大而不伏，大而显为伏火外发之象。前因暑邪郁遏于内，寒凉太早，食物壅滞，火不得宣；经疏理肠胃、清火凉药、西瓜六一散逐火下行后，舌退黑、呃止、面红退、二便清利，脉由沉细数转为大而不伏，示郁火已透、壅滞已通，故进粥饮调胃。", ["大"]], "11488": ["病机", "患者年五旬，忍饥劳倦，面红脉大，汗出如雨，神思倦怠，口不渴。脉大非实火，乃热伤元气、劳倦内伤，肺气不能固表，脾虚而倦，故脉大而虚。诸医误作实火清之，反伤正气。此脉大主气虚发热，与面红、汗出、倦怠、不寐相应，属内伤劳倦之病机。", ["大"]], "11489": ["病机", "休息痢二载，脉息洪大带数，腹皮如络，小便黄赤而不禁，有时梦遗。久痢伤肾，肾阴亏虚，阴不制阳，虚火内动，故脉洪大带数；肾司二便，失于固摄则小便不禁、梦遗。洪大数脉非实热，乃久痢伤肾、阴虚火旺之象，恐酿劳瘵，治宜补肾为主。", ["洪", "大", "数"]], "11490": ["病机", "久痢伤肾，酿成阴虚之症，阴火上冲，饮食不得下达而呕逆，脉息细数，声音不出。细为阴血不足，数为虚火内亢；水衰火亢，肺金被烁，金破不鸣故声音不出。此脉细数主阴虚火旺、肺金受灼，与呕逆、声哑相应，治宜滋阴保肺降火。", ["细", "数"]], "11491": ["病机", "肾水不足，相火上炎，血随火升，继之咳嗽半载，脉息虚大带数，尺部尤甚。虚大为阴亏阳浮之象，数为相火内动；尺部尤甚，直指肾水亏虚、相火不藏。此脉主劳瘵之基，与咳血、咳嗽相应，乃阴虚火旺、本元亏损之病机，治宜滋阴降火、静养调摄。", ["虚", "大", "数"]], "11492": ["病机", "血症之后，肺金受火燔灼而咳，本原病也；目下感受暑风之邪，咳嗽头痛，脉息浮大而虚。浮主外邪在表，大而虚为肺气本虚、外邪乘虚侵肺。此脉非实邪壅盛，乃本虚标实之候，与咳嗽、头痛相应，治暂用清肺理气疏散，俟症减再进补剂。", ["浮", "大", "虚"]], "11493": ["病机", "尊体肥厚，丹溪云肥人多湿痰；四月纯阳之月，热气薰蒸，下流右足底，右属脾胃，湿胜则肿。脉息沉滑有力，沉主里，滑主痰湿，有力为湿痰壅滞、气血不运。四肢骨节疼痛、头项不能转动、手指不能举捧，皆湿痰流注、经络壅塞之象，脉与症合，主湿痰内盛之病机。", ["沉", "滑"]], "11494": ["病机", "因饮酒伤胃，酒性大热，扰其血分而吐血；抑郁不舒，胸膈不宽，气上冲逆而咳浊痰。脉息沉弦带数，两关尤甚。沉主里，弦主气滞，数主热；两关候脾胃，尤甚则病在胃。此脉主气滞血凝于胃、郁热上升之病机，与吐血、胸膈不宽、咳逆相应，治宜消痰降火理气。", ["沉", "弦", "数"]], "11495": ["病机", "受病之源得之恼怒郁结，肝火升腾，上干肺金而咳，咳极致血，血随火升。脉息左手带弦，此肝火妄动也；右手滑大，关部尤甚，此胃中痰瘀纠结之象。左弦主肝郁火动，右滑大主痰瘀壅胃。此脉主肝火犯肺、痰瘀互结之病机，与咳血、胸膈不舒相应，治先豁痰降气消瘀。", ["弦", "滑", "大"]], "11496": ["病机", "脉沉弦带数，沉主里，弦主肝郁，数主郁火。原文谓“肝气郁于脾土之中，不得疏泄”，郁火扰血则下注发痔、梦遗，夜卧口干烦躁乃“郁火薰蒸”之征。脉象与多思多郁、肝火妄动之病机相合，故主肝气抑郁、郁火内扰之证。", ["沉", "弦", "数"]], "11497": ["病机", "脉弦数，弦主气逆，数主火热。原文谓暑热之邪“蕴蓄于内”，分娩后内伏之火“乘机外达，上干肺金”，致咳嗽气急、呕吐痰涎、小便不利而肿。诸逆冲上皆属于火，脉象正合暑热内伏、肺胃薰灼、气逆不降之病机。", ["弦", "数"]], "11498": ["病机", "左手微弦主肝，右手滑大有力主胃中郁痰郁火。原文谓“胃中有郁痰郁火，稍有所触即窃发”，痰火上干心窍则神不宁、不得卧，阳明之热薰蒸肺金则痿软无力。脉象与“胃不和，卧不安”“诸痿皆属于肺热”之病机相应。", ["弦", "滑", "大"]], "11499": ["病机", "脉洪大有力，洪主热盛，大主邪实。原文谓平素嗜酒，肠胃湿热蕴蓄，加夏令暑热外袭，湿热乘机而发为痢，绵延连岁，腹中作痛，后重逼迫，所下赤白，面色痿黄，两足浮肿。脉象与湿热内蕴、邪实有余之病机相合。", ["洪", "大"]], "11500": ["病机", "脉沉弦而数，两关尤甚，沉主里，弦主肝，数主火。原文谓“肝火郁于胃中，煅炼津液成痰”，痰随肝火上冲而呕吐，食物入胃至晚作酸，大便燥结。白沫而冷乃“热极似冷”，非真寒。脉象主肝火郁胃、痰热上逆，为噎膈反胃之基。", ["沉", "弦", "数"]], "11501": ["病机", "左手弦大主肝火妄动，右手滑大有力主胃中湿痰湿火。原文谓平素嗜酒多怒，湿火上蒸则多汗，怒伤肝则血随火升而见红，湿痰下流大肠则为痔疮。脉象与肝郁化火、胃中湿痰湿火之病机相应。", ["弦", "大", "滑"]], "11502": ["病机", "脉弦滑带数，弦主肝火，滑主痰，数主热。原文谓“胃中有郁痰，随火上升，闭其心窍”，则神昏而咽喉塞碍；肝火薰灼津液则口干舌燥，上蒸为汗。脉象主痰火内郁、上蒙心窍，原文明言“乃类中之基”，即中风先兆之病机。", ["弦", "滑", "数"]], "11503": ["病机", "两关沉滑带弦，沉主里，滑主痰，弦主肝郁。原文谓肾水不足不能荣养肝木，肝火妄动则血随火升；又忧思抑郁，胃中津液煅炼成痰，痰随气逆而咳嗽。脉象主肝气郁于胃中、痰火内结，虑其肺受火灼，故治以凉血清火开郁。", ["沉", "滑", "弦"]], "11504": ["病机", "脉弦大带数，弦为肝火升腾，大为水衰火亢，数为积热窃发。原文谓“水衰火亢，肺金受伤”，肾水不足不能荣养肝木，肝火上冲则呕吐、颈间结核，火气上炎则汗出发热、痰中带红、寒热如疟、经事不来，脉象正合阴虚火旺之机。", ["弦", "大", "数"]], "11505": ["病机", "脉沉数带滑，右关尤甚，沉主里，数主火，滑主痰。原文谓“胃中郁痰郁火，所以结成有形之物”，痰火郁于胃中，上升则眩晕，不得疏泄则嘈杂似饥，上烁肺金则痿软乏力，散于四肢则手足心烦热，脉象与症候相应。", ["沉", "数", "滑"]], "11506": ["病机", "左手沉弦，沉主里，弦主肝木郁滞。原文谓“肝火不得下达”“肝火上冲而呕吐”，因郁怒伤肝，交春令肝木用事，木性善胀，食后胃中胀满不得下达。误服资生丸闭气凝滞、八味丸香燥助火，致肝气愈郁，脉象反映肝郁化火、木不疏土之机。", ["沉", "弦"]], "11507": ["病机", "脉沉弦带数，沉主里，弦主肝，数主火。原文谓“少阳之火，郁于胃中，不得疏泄”“乙木郁于坤土无疑矣”，至春发陈之月内伏之邪应时而外达，故右半唇与发际牵引作痛至春则发，脉象正示肝火郁于胃土、木郁化火之病机。", ["沉", "弦", "数"]], "11508": ["病机", "脉弦数，弦主肝火，数主热。原文谓“肝火郁于膀胱，煅炼津液，而成黏腻之物，瘀塞溺道”，因少年多饮火酒，余毒流注膀胱，结为沙石，小便淋漓作痛，交君火司天之年其发频甚，小腹胀满，脉象反映肝火郁于下焦、煎熬津液成石之机。", ["弦", "数"]], "11509": ["病机", "脉沉弦带数，沉主里，弦主郁，数主火。原文谓“郁火煅炼津液成痰，阻滞胃中，所以不饥不食”，平素多思多郁，郁久成火，得风则炽而发寒热，火无从疏泄则皮肤流走作痛，郁于内则胸膈胀满、口干气急、大便燥结，脉象正合郁火痰阻之机。", ["沉", "弦", "数"]], "11510": ["病机", "右手弦数，左手沉滑，弦数主肝火，沉滑主痰瘀。原文谓“肝火妄动，胃中之痰，与瘀血互相纠结，上干肺家而咳嗽”，因醇酒厚味积于胃中扰其血分，值君火司天之年血随火升而吐，脉象反映肝火夹痰瘀互结、上干肺金之病机。", ["弦", "数", "沉", "滑"]], "11511": ["病机", "脉沉涩，沉主里，涩主郁滞不畅。原文谓“邪气未尽，而误补之故也”，暑邪下流两足作痛，服补药后胃中痰郁遏不清，至春内伏之火窃发，上升则齿痛，清晨痰随火升则语言不能，脉沉涩正示邪郁于里、痰火内伏、气血不畅之机。", ["沉", "涩"]], "11512": ["病机", "原文未出脉名，以“肝家有郁火”“肝火扰其血分，血得热而妄动”立论。肝主疏泄藏血，火扰血分则血妄动，故易堕胎、小腹攻冲；胆为肝表，火升则头痛昏沉；胃痰随少阳火上升则食少无味；肝火消烁肌肉即“风消”；午后火升因肝肾阴不荣。诸症皆由肝胆之火郁而不舒，脉象虽缺，病机在郁火。", []], "11513": ["病机", "脉息沉弦带数，沉主里、弦主痛主瘀、数主热，合“瘀血凝滞胃中，结成有形之象，按之而痛”。饥饱劳役伤胃络，瘀血与食物阻滞，郁而作酸嘈杂，大便艰涩、小便黄赤，皆瘀热内结之征。脉沉弦数正应瘀血纠结于胃、郁而化热之病机，故治宜消瘀行滞，逐瘀从大便出。", ["沉", "弦", "数"]], "11514": ["病机", "左手弦大、右手滑大，弦大为肝火妄动，滑大为胃中痰壅。景老胃有痰、肝有火，误用温补涩精，痰火无从发泄，下注精房则梦遗，薰灼血分则便血，上冲则眉发脱落，下注则小便频数。值相火司天、夏令炎热，火得时助，故脉象如此。种种诸症皆属痰火郁于胃中，误补致变。", ["弦", "大", "滑"]], "11515": ["病机", "脉息弦数不静，弦为肝郁，数为火盛，不静示郁火搏击不安。胃中食积与肝火郁滞不通，发为胀满；肝火薰蒸于上则两目昏暗。原文明言“肝火郁于脾土之中，湿痰食积，互相为患”，脉之弦数正应肝火郁滞、食积湿痰交阻之机，故治宜清湿消导。", ["弦", "数"]], "11516": ["病机", "脉息两关滑大，关候脾胃，滑主痰、大主火盛。久疟之后胃中顽痰未清，郁而为火，上炎于面则红，下注手足则肿，闭其经络则麻。原文断为“郁痰郁火为患”，两关滑大正应痰火郁结中焦之象，故治以豁痰清火，痰火去则诸症自解。", ["滑", "大"]], "11517": ["病机", "脉息细数而侧眠，细为阴血亏少，数为虚热内扰；侧眠者，咳吐血而气逆不得平卧之状。疟疾日久兼咳嗽吐血，阴伤肺损，虚热灼络，故称“劳疟”。细数之脉正应阴虚内热、肺络受损之病机，非实疟可比，故治宜滋阴保肺，不可徒治疟邪。", ["细", "数"]], "11518": ["病机", "左手弦大不静为肝火妄动，右手滑大有力、关部尤甚为胃中胶痰、肺气壅滞。肝火上升则头角多汗、头晕耳鸣，旁流则两手多汗，下流阴囊则肾子胀痛；痰流四肢则手指麻痹；畏冷乃“热极似寒”。脉象正应肝火胃痰交郁之机，故胸膈胀闷，得气展舒则适。", ["弦", "大", "滑"]], "11519": ["病机", "原文以“脉大汗出者”“脉弦不解者”辨疹之转归：脉大汗出，热势已达，疹点淡红稍大；脉弦不解，则邪郁未透。少阴君火、少阳相火司令，火郁胞络膻中，故郁郁不乐、寒热不甚、口干烦冤、目泪颧红、四肢微厥；热薰肺主皮毛，发为赤疹，无汗而毛燥。脉象所主在火郁不透之病机。", ["大"]], "11520": ["其他", "此段为医案序文，述沈菊人先生精研岐黄、用药当而效神，未涉具体脉象与病机。文中强调「经络、脉理、药性、病情」讲求熟习，又勖弟子「明辨慎思」「知之明而处之当」，旨在说明临证须脉理精熟、辨证确切，非论某脉主某病，故无脉象要素可录。", []], "11521": ["病机", "痃疟延及半年，真阴被劫，精摇乎寐，阴精日夺，复感温邪，致虚焰之火升腾，口糜滋腐。脉虚数而两尺空，虚为阴精亏乏、脉道不充，数为虚火内燔；两尺候肾，空则根本先拨。故主真阴重伤、虚火上炎，与神疲、妨谷、自汗、身热不尽相应，有虚脱之虞。", ["虚", "数"]], "11522": ["病机", "温邪劫烁阴津，阴乏上承，少火化为壮火，虚火上焰，蒸为口糜牙疳。脉虚数无神、两尺全不耐按，虚数示阴津耗伤而虚火未熄，无神及尺部不耐按则根本未固。神倦嗜寐即仲圣少阴病但欲寐，为肾经见证。故主阴伤火炎、肾根本虚，法当救阴护阳。", ["虚", "数"]], "11523": ["预后", "进救阴护阳法后，阴气似乎稍复，脉象略有精神，惟两尺仍不耐按。原文未明指脉名，仅以「略有精神」「两尺不耐按」描述脉之起色与尺部虚象。尺候肾，不耐按示积虚之阴骤难恢复；已亢之阳仍上腾，故口糜龈腐未退。此段重在判断药后脉象转机与未复之根，仍宜毓阴泄化。", []], "11524": ["病机", "虚炎之火得滋而熄，久涸之阴得补而复，口糜渐退，胃气稍苏。惟咳嗽痰稠、小溲短赤，脉见右寸独数，左尺尚不耐按。右寸候肺，独数乃肺有余热；左尺候肾，不耐按为肾乏阴精。故主上实下虚，金水同源，法当清上实下，与咳痰稠、溲赤相应。", ["数"]], "11525": ["病机", "肾司二便，小便频数、腰酸且痛，脉左尺独弱，右关独大。左尺候肾，弱为肾阴亏虚；右关候胃，大为胃有余热。故主肾阴亏而阳明客热，与溲频、腰酸痛相应。法当壮水之原，兼泄阳明客热，正合脉症。", ["弱", "大"]], "11526": ["病机", "温邪挟湿，病来五日，神昏呓语、寒战肢冷囊缩、口渴不嗜饮、饮下即吐，脉沉数。沉为邪陷于里，数为温邪内郁；因病前夺精，阴气先伤，阳邪乘虚内陷阴经，营卫不和，邪不达表。故主阴道虚而阳邪内陷，以黄连汤两和阴阳。", ["沉", "数"]], "11527": ["病机", "肢温寒热稍轻，咳嗽气急、苔白舌红、呕恶面赤、呓语夜重日轻，脉右浮数，疹点隐隐，便溏。右脉候肺胃，浮为邪欲外达，数为温邪未清；疹点隐隐正是邪欲达未达之象。故主肺胃温邪欲达未达，仍以和之，使邪从表解。", ["浮", "数"]], "11528": ["病机", "脉左弦沉数，右细。弦为肝阳亢盛，沉主里，数主热，细为阴伤。原文谓“心肝之阳未平，肝肾之阴已虚”，温邪消烁阴津，火升气逆，故脉象左弦沉数，右细则示阴亏。痰稠溺赤、寐后神识模糊，皆心阴虚而神不内守之象，脉症相符。", ["弦", "沉", "数", "细"]], "11529": ["病机", "脉浮数，浮为邪在表，数为热。原文谓“里热外寒，郁表络伤”，冬温始起，寒后发热，无汗，脉浮数，乃寒邪束表，里热不得外达。呕吐痰涎、食物带血、咳嗽胁痛，为肺胃热郁络伤之症，脉浮数正合表寒里热之病机。", ["浮", "数"]], "11530": ["病机", "脉沉弦数，沉主里，弦主肝，数主热。原文谓“邪火逼烁阴津”，温邪两候无汗，咳嗽痰稠，口糜牙疳，午后火升气逆，夜则呓语，皆阴气空虚、肺失清肃，邪火内炽之象。脉沉弦数反映邪热内郁，阴津受灼，慎防喘脱。", ["沉", "弦", "数"]], "11531": ["病机", "脉浮数，浮为邪在表，数为热。原文谓“温气内伏，被寒邪所遏”，形寒无汗，口渴舌灰白，乃寒遏于表，温邪内伏化热。老年胃津阴液皆虚，脉浮数示表邪未解而里热已萌，恐液涸，故脉症合参为外寒内热、阴液易伤之机。", ["浮", "数"]], "11532": ["病机", "脉来浮数，浮为邪在表，数为热。原文谓“温邪十六日，从未有汗，表邪因而不达，逆传入里”，神昏谵语、脘中拒按、舌红苔白，乃肺胃温邪蒸灼气营。脉浮数示表邪未解，里热已炽，表里同病，故法当表里同治。", ["浮", "数"]], "11533": ["病机", "脉沉数，沉主里，数主热。原文谓“肺胃温邪煽烁阴津，风阳化燥”，温邪十六日，咳嗽不畅，舌白苔干，口渴自汗，神志乍有昏蒙，皆热邪内传，阴津受灼之象。脉沉数反映邪热内郁，防其风动，脉症相符。", ["沉", "数"]], "11534": ["病机", "脉软数，软为阴伤，数为热。原文谓“热灼阴伤，厥阳化风上扰，胃虚挟饮，阴涸风生”，患者素梦泄精虚，又感秋温，头痛眩晕、耳鸣惊惕、风动肢牵、呕吐酸苦，脉软数全不拒按，示正气已虚，热灼阴津，势有痉厥汗脱之险。", ["软", "数"]], "11535": ["病机", "脉象虚弦，左寸涩，右尺空。虚弦为肝风内动而中下虚，左寸涩示心虚血少，右尺空主肾阳衰微。原文谓“中下虚，肝风冲侮阳明，胃虚积饮，肾水上泛”，故见惊惕肉𥆧、肢搐、吐蛔吐水、痰黑味咸，木火烁液，舌赤津涸，脉症合参为肾阴虚馁、木失水涵之危候。", ["虚", "弦", "涩", "空"]], "11536": ["病机", "脉虚弦，虚为阴液亏耗，弦为肝风内动。原文“水亏木旺，内风未靖”，水不涵木则风阳鼓荡，故见肢牵、头晕目花；神明涣散、呓语、自汗乃阴阳撒失乖离之象，舌光液涸更证阴亏。脉虚弦正合阴亏阳浮、内风未息之机。", ["虚", "弦"]], "11537": ["病机", "脉弦数，弦主肝风，数主热盛。原文“阴气素虚，肝阳化风挟痰火上逆”，故痉厥、鼻煽、神识模糊；阳明热炽则寒热咳嗽、胸闷、便溏溲少。弦数并见，示厥阴风动与阳明热炽交炽，症势颇重，治以和阳熄风、辛泄上焦。", ["弦", "数"]], "11538": ["预后", "脉象虚弦无神，虚为阴气拖虚，弦为热邪内炽、风阳扰动。原文“热邪内炽，肺胃津伤，阴气拖虚”，故耳聋、舌干苔灰、口渴；白㾦屡布未透，寒热蒸灼，阴气重伤。脉无神乃胃气衰败之兆，故曰“告变在迩”，预后凶险。", ["虚", "弦"]], "11539": ["病机", "脉弦数按之豁然而空，弦数为热炽风动，空为阴液耗竭。原文“热炽伤阴，液涸风动，肢搐”，舌红光亮、口干渴饮；茎缩、口生糜疳乃“阴尽阳升之征”。脉空示泉源欲竭，神不内守，故呓语，症势濒危。", ["弦", "数", "空"]], "11540": ["病机", "脉浮弦数，浮主邪在表分，弦主湿郁气分，数主热。原文“伏邪内蕴，感冬温触发”，寒短热长、头痛咳嗽、溲赤舌白口腻、渴不多饮，皆湿郁气分未泄之象。浮弦数并见，示外邪引动内伏，湿与热郁于气分，治以分泄。", ["浮", "弦", "数"]], "11541": ["病机", "脉数主热盛，原文“暑湿热兼感温邪”，热邪乘虚陷入营分，发为紫斑；舌红苔黑、神识昏蒙、沉沉欲寐，乃邪灼心包、势将昏蔽之征。数脉示热邪鸱张，气营两燔，非轻候，治从肺卫、心营清解。", ["数"]], "11542": ["病机", "脉数，热邪虽得腑通暗泄，而蒸灼之余胃液受劫，舌红苔黑而干；呓语、神志沉倦，乃热扰心神。原文“气血两燔治法”，数脉示气营邪火未清，阴液已伤，病情如旧，尚在险途。", ["数"]], "11543": ["病机", "脉来数疾，数疾为热邪亢盛、阴液劫烁之象。原文“气营邪火仍未清泄，以致劫烁胃津阴液”，故肌肤燥灼、口渴、胸闷、神识尚蒙；痰咯不易，乃热挟痰上薰。数疾脉示邪火未衰，阴津受灼，治以承阴撤热。", ["数", "疾"]], "11544": ["病机", "脉濡数，濡主湿，数主热，为湿热内蕴之象。温邪七日，神志或轻或浑，唇燥齿血，目赤舌绛，苔黄口渴，便溏，遍体赤斑，乃温邪由气入营，燎原之势，内逼膻中，势将昏闭，涸液之机已著。脉濡数反映湿热交蒸，邪热炽盛，阴液受灼，故见斑疹、神昏之候。", ["濡", "数"]], "11545": ["病机", "脉来外数内柔而不鼓指，数主热，柔为阴津亏耗、脉道不充之象。清解后斑点较透，色带紫，神识略清，舌绛苔黑，便溏，乃邪火劫烁阴津，不能御邪外出，而致内陷膻中。脉外数内柔，正合邪热未清而阴津已伤，无力鼓邪外达之机。", ["数", "柔"]], "11546": ["预后", "脉来细数无神，细为阴伤，数为热炽，无神则胃气衰败。温病八日，蓝赤斑并布，目赤龈血，舌红苔黄，口渴，频频呃逆，便溏色赤而热，阳明温热内逼营分。虽外得斑点、内得便泄，似表里热邪已得分泄，而脉细数无神，阳病见阴脉，古称不治，故最为可虑，涉险何疑。", ["细", "数"]], "11547": ["病机", "脉沉细迟滞，沉细为阳虚，迟滞为寒湿内阻。酒客中虚湿胜阳微之体，感受暴寒，形寒身热不甚扬，呕吐苦水，饮积中宫，寒郁反从热化，逼无根浮游之火发为虚斑，色淡不绽。舌黑苔，干渴喜暖饮，胃寒客气上逆，呃忒频频，便紫尿赤，阳明湿热内蒸。脉沉细迟滞正合阳虚湿胜、寒郁化热之机。", ["沉", "细", "迟", "滞"]], "11548": ["病机", "脉左细不耐按，右部弦细，细为阴伤，弦为寒湿化热、气机郁滞。昨投重镇法后呃忒减半，苔转黄腻垢浊，斑点较繁，四肢仍冷，便溏咳嗽不畅。此寒湿化热，蕴蒸无形之邪，逼虚阳无根之火上泛，元气津液业已两亏。脉细不耐按、弦细，正示正虚邪恋、阴阳两伤之险候。", ["细", "弦"]], "11549": ["病机", "脉数主热，温邪旬日，咳嗽神烦呓语，舌苔灰黄，渴不多饮，斑点汗少，肺胃风温挟湿，内蒸阳明，气营交病。数脉为热邪内炽之征，热蒸营分则斑点，热扰心神则烦而呓语，肺胃受邪则咳嗽、渴不多饮。脉数与证合，示风温挟湿、气营两燔之病机。", ["数"]], "11550": ["预后", "脉弦数而空，弦为热郁，数为热炽，空为真阴已伤、脉道不充。休息利后阴气内伤，又夹湿热，发斑色紫，舌尖干口渴不寐，呃忒。此真阴已伤，恐其劫津，正不敌邪，虚脱可虑。弦数而空之脉，正示邪热未清而阴精耗竭，预后堪忧。", ["弦", "数", "空"]], "11551": ["病机", "脉软数，软为津液亏虚、脉道不充，数主热炽。温邪十三日，斑疹仍然，咳嗽气急，便泄，夜烦少寐，口渴舌红，肺胃津液两虚，热炽阴空。软数脉反映热邪未解而津液已伤，正虚邪恋，故法以泄热救阴，若再迁延转虚，可虑。", ["软", "数"]], "11552": ["病机", "脉浮数，浮为邪在表分未解，数为温邪化热之征。原文谓“阳明温邪乘阴之虚陷入厥、少两经”，故脉浮数反映温邪炽盛而阴分已虚，热势鸱张。症见斑点未化、气促似喘、口渴，皆热郁气分、阴液受灼之象；便泻腹痛、里急后重、痰沫，为温邪下迫、湿热滞于肠腑。脉症合参，主温邪内陷、阴伤热炽之病机。", ["浮", "数"]], "11553": ["病机", "脉浮虚数，浮为邪未尽解，虚为正气已伤，数为余热未清。原文谓“肺胃温邪，乘虚陷入阴经”，下利虽减而里急后重、肛热且痛，咳嗽气逆、苔白口渴，皆温邪挟湿热下迫、阴分受损之候。脉虚数正是邪热未净而正阴已亏之象，故从厥阴热利论治，主湿热内陷、正虚邪恋之病机。", ["浮", "虚", "数"]], "11554": ["病机", "脉沉数，沉为邪热内入营分，数为热邪化火之征。原文谓“暑湿热浑蒸阳明，由气入营，直逼膻中”，神昏聩乱、目窜鼻衄、舌红苔灰黄、渴饮，皆热邪化火、劫烁阴液之危候。脉沉数正合热邪深入、燔灼营阴之机，故断为“热邪化火，势如燎原”，主暑热内陷营血、阴液将涸之病机。", ["沉", "数"]], "11555": ["病机", "脉迟细、尺微，迟为阳虚寒凝，细为营血不足，尺微为真阳衰惫。原文谓“寒湿内郁营分，真阳自虚”，身热不扬、胸闷咳嗽、痰咸、渴不多饮、四肢逆冷、溲清，皆寒湿困遏、阳气不布之象。浮游无根之火发为阴斑，色淡而微，正合阳虚寒郁之机。脉迟细尺微，主寒湿内郁、真阳亏虚之病机。", ["迟", "细", "微"]], "11556": ["病机", "脉来浮数，按之细弱，浮数为暑湿外蒸、热邪未清，细弱为热久正虚、阴津耗伤。原文谓“热久正虚，不能使邪尽出”，疹㾦色不光泽、点不畅达，便泻而病不甚退，日暮热甚，皆邪欲出不尽、阴气灼伤之候。脉浮数按之细弱，正合“正虽虚而邪亦渐退”之判断，主暑湿留恋、气阴两伤之病机。", ["浮", "数", "细", "弱"]], "11557": ["预后", "脉沉细涩，沉为邪郁于里，细为阴血不足，涩为气机滞涩。原文谓“病属阳邪，反见沉细涩之阴脉，于法为逆”，风温燥邪外遏而见阴脉，是邪不从表解而内陷，且“邪从里泄，不经汗解”，故断为逆候，恐有猝变。脉症相悖，主阳邪内陷、正不胜邪之预后不良。", ["沉", "细", "涩"]], "11558": ["病机", "脉浮数，浮为风温之邪欲达未达，数为热邪内郁化火。原文谓“风温欲达不达，而致乘虚内陷”，疹透渐回而神识模糊、呓语喃喃、昼轻夜重，咳嗽痰鸣、舌白尖红、便泻、风动肢牵，皆风温内陷、热扰心神、风阳煽动之候。脉浮数正合邪热未清而内陷之机，主风温乘虚内陷、热盛动风之病机。", ["浮", "数"]], "11559": ["病机", "脉软数，尺部独弱，软为气阴两伤，数为温邪内炽，尺弱为肾阴亏虚。原文谓“温邪内炽伤阴，风阳煽烁，水不济火，心神浮越”，神识不清、夜烦不寐、呓语遗尿、肢搐、心神不安，皆阴亏火旺、风阳内动、心神不守之候。脉软数尺弱，正合“有内闭外脱之象”，主温邪伤阴、风阳煽烁、心神浮越之病机。", ["软", "数"]], "11560": ["病机", "脉沉弦数，沉主里，弦主郁，数主热，合之则暑湿风邪内蕴肺胃，气分郁滞化热。原文谓“邪郁气分，不能畅泄”，故脉见沉弦数，症见咳嗽痰多、舌白口腻、白㾦式微，病经十八日不解，正因邪郁气分，不得外达，淹缠难愈。", ["沉", "弦", "数"]], "11561": ["病机", "脉左虚数、右沉数，虚为正气不足，数为热，沉主里。原文谓“伏邪五日，热势暮甚”，邪伏肺胃气分，渐入阴分，正虚邪恋不化，故左脉虚数，右脉沉数，舌白溲赤，布白㾦，乃正虚邪恋之象。", ["虚", "数", "沉"]], "11562": ["病机", "脉浮数，浮主表，数主热，风温挟湿郁伏肺胃，邪热在气分，故脉浮数。原文谓“病已五十日，肺胃津伤，邪不外达”，症见咳嗽身热、咽梗音闪、溲赤、白㾦不多、口干，乃津伤邪恋，故以辛凉轻泄。", ["浮", "数"]], "11563": ["病机", "脉弦数，弦主郁主痛，数主热，湿热下移阳明，三焦湿热郁滞，故脉弦数。原文谓“三焦湿热，白㾦不透，伏邪为病，最属淹缠”，症见泄泻咳嗽、舌白腹痛，乃湿热郁阻三焦，气机不畅所致。", ["弦", "数"]], "11564": ["病机", "脉细数，细主阴伤，数主热，伏邪郁于三焦气分，久则伤阴，故脉细数。原文谓“邪郁三焦气分，白㾦未畅”，症见身热咳嗽、便泄、舌白，乃邪郁气分，阴分已伤，故治以分泄。", ["细", "数"]], "11565": ["病机", "脉来洪数，按之虚细，洪数为邪热有余，虚细为正虚不足。原文谓“蕴伏之湿与既衰之元不能两立”，中气既虚，脾胃不运，湿胜濡泄，元气日羸，故脉洪数而按之虚细，症见倦怠嗜卧、神识模糊、渐渐蒸热，乃正虚邪恋之候。", ["洪", "数", "虚", "细"]], "11566": ["预后", "脉转沉细，沉细为正气渐复、邪气退舍之象。原文谓“昨进益气化邪，神清、泻减、呃稀、脉转沉细，正复邪退之机也”，此前脉洪数，今转沉细，说明中气渐复，邪势已衰，故为向愈之征，拟戊己法健运脾胃。", ["沉", "细"]], "11567": ["病机", "脉沉数而滞，沉主里，数主热，滞主气机壅塞。原文谓“暑湿内伏，兼夹秽邪”“秽湿内著也，最易昏闭”，秽湿壅遏气分，故脉沉数而滞，症见形寒身热、舌白带灰、头疼气闷、便溏溲赤、神识稍有不清，乃秽湿内闭之危候。", ["沉", "数", "滞"]], "11568": ["病机", "脉沉数，沉主里，数主热，合之外寒内热之病机。原文谓“外寒而内热也”，寒湿束表则形懔自汗、头痛，暑湿内蕴则胸闷欲呕、舌白。脉沉数正是寒湿外束、暑热内郁之征，故治以两顾，外解寒湿，内清暑热。", ["沉", "数"]], "11569": ["病机", "脉沉弦数，沉主里，弦主郁主痛，数主热。原文谓“邪郁脾胃，游行中道，过膜原而寒热作矣”，暑湿内伏，触凉风外发，邪郁脾胃，故见寒战鼓栗、先寒后热、头痛胸闷、呕吐泄泻、口渴。脉沉弦数正是邪郁脾胃、欲作疟之机。", ["沉", "弦", "数"]], "11570": ["病机", "脉尚弦滞不前，弦主郁，滞主涩滞不畅。原文谓“暑邪虽从汗泄，湿邪亦得便泄。而究其蕴伏，尚恋未尽也”，虽寒止热存、吐泻已除，但舌仍白、脉弦滞，说明湿邪蕴伏未净，气机尚欠流畅，故仿吴又可法继续透邪化湿。", ["弦", "滞"]], "11571": ["病机", "脉象右数于左，右主气分，数主热。原文谓“时邪浑淆中宫，当芳香宣窍，分泻三焦，以防内闭”，暑湿秽邪混扰中宫，分布三焦，故形寒身热、胸闷头痛、神烦不安。右脉数于左，说明邪热偏重于气分中宫，有内闭之虞。", ["数"]], "11572": ["病机", "脉数主热，原文谓“暑湿风热杂感溷淆中宫，分布三焦气分”，热阻中焦则胸闷，越外则身热头疼，上为呕吐，下为泄泻，舌白腻、口渴不多饮，皆暑湿风热混杂之象。脉数正是热邪内郁之征，故以芳香宣泄分解中宫浑处之邪。", ["数"]], "11573": ["病机", "脉迟涩，迟主阳运不健，涩主血少气滞。原文谓“身热吐泻之后，脾胃已伤，中阳运化之机不健，气道转输之枢亦钝”，吐泻伤中，阳气亏虚，运化无力，故神疲而脉迟涩。此非热邪内结之迟，乃中阳不足、气血不畅之象，故宜节食以护脾胃。", ["迟", "涩"]], "11574": ["预后", "脉小数、左寸伏，小主正虚，数主热，伏主邪闭。原文谓“暑湿热邪内闭心包之象，就脉论证，危如朝露春冰”，邪热内陷心包，神昏闭阻，自利赤水、四肢逆冷，脉小数为正虚邪盛，左寸伏为邪闭心包，故预后凶险，勉拟幽香宣窍法。", ["小", "数", "伏"]], "11575": ["病机", "脉数主热，原文谓“暑、风、湿三气杂感，身热自汗，口渴舌黄，体酸胸闷”，泻止而小便不利，说明邪郁太阴、阳明，气分热盛，水湿不化。脉数正是三气杂感、邪郁气分之征，故治从分法，宗河间法以分利湿热。", ["数"]], "11576": ["病机", "原文谓暑风湿热转疟，寒从背起、舌白腻、口渴喜饮、小便赤痛，脉来关数。关候中焦，数主热盛，暑湿热邪郁于阳明，故关脉数；热灼津伤则口渴喜饮，湿热下注则小便赤痛。脉数与阳明郁热之症相应，法宗仲景即从阳明湿热论治。", ["数"]], "11577": ["病机", "暑风湿热杂感十三日，神昏呓语、舌白苔垢、口渴、布白㾦、咳嗽不畅，脉数。数脉主热，暑湿热邪在肺胃气分，痰热内阻膻中，故脉数而症见神昏咳嗽。原文称病已涉险，脉数正示邪热鸱张、痰热蒙窍之势，故拟幽香宣窍、辛苦寒燥湿清热。", ["数"]], "11578": ["病机", "暑湿伏邪身热五十日，形懔、胸闷、舌白、渴不多饮、白㾦屡发未曾畅透，脉数。数主热，然渴不多饮、苔白，是湿遏热伏之象；暑湿浑蒸三焦气分，邪欲外透而不得畅，故脉数而身热缠绵。脉数与伏邪内蕴、湿热交蒸之病机相应，治当分泄。", ["数"]], "11579": ["病机", "淋雨后身热，渐至形消骨立、少纳、四肢浮肿、舌白，脉细弦。细为气血不足，弦主气机郁滞，合而示气虚湿郁不化：气虚则形消少纳，湿郁则浮肿舌白。脉细弦正合虚中夹湿之候，故恐难支撑，拟东垣清暑益气法益气化湿。", ["细", "弦"]], "11580": ["病机", "复热、头痛、舌白、脉弦，因劳力耕耘而发，原文断为劳复病。弦脉主气机郁滞、邪正交争，劳倦伤气，余邪乘虚复起，故复热头痛；舌白示邪未化热入里。脉弦与劳复之邪郁气滞相应，非单纯外感，故以劳复论治。", ["弦"]], "11581": ["病机", "伏邪为疟已止，早食荤腥，湿遏不化，神疲力乏、溲赤，脉弦数。弦主郁滞，数主热，荤腥碍脾，湿浊内遏化热，余邪未清，故脉弦数而溲赤；湿困则神疲力乏。原文断为食复，脉弦数正示湿遏化热、食滞复动之病机。", ["弦", "数"]], "11582": ["病机", "霍乱吐泻转筋、四肢逆冷、音闪舌白，脉细微。微细为阳气衰微、气血俱虚之象，暑湿浑淆中阳，吐利伤阳，邪陷三阴，故脉细微而四肢逆冷、音闪。原文称证属危险，脉细微正与中阳衰败、邪陷三阴相应，勉拟一方以图侥幸。", ["微", "细"]], "11583": ["病机", "投转运清浊、通阳撤阴后霍乱吐泻转筋皆止，脉转弦细而数，身热。由细微转为弦细数，是邪出三阴转入阳分之兆：弦主气机未畅，细为吐利后阴伤，数主身热。骤然呃忒乃中阳因吐利受戕，故法当和平调治，不可峻攻。", ["弦", "细", "数"]], "11584": ["病机", "脉伏微有一线，是暑湿寒邪直入三阴、阳气被遏不能外达之象。伏为邪闭，微为阳衰，一线之微示生机尚存。吐泻交作、肢冷音哑，正合三阴虚寒、清浊相干之重证，故脉不见浮起而沉伏难寻，主病深在里、阳气欲绝。", ["伏", "微"]], "11585": ["病机", "脉细弦迟，细为阴伤阳弱，弦主痛与气机郁滞，迟属寒。吐泻虽止而泻势未定，肢冷温而复清，是阳气乍回未固；神烦口渴乃阴津耗伤、虚阳上扰。脉象示寒湿未净、阳气未复，故云尚有变态。", ["细", "弦", "迟"]], "11586": ["病机", "脉伏而吐泻、四肢逆冷、腹痛麻木，是邪入阴经、阳气闭阻不达四末之候。伏脉主邪闭于里、气血不能外鼓，与肢逆、腹痛相合，说明寒湿阴邪深踞三阴，阳失温运，故脉沉伏不起，属霍乱之阴寒重证。", ["伏"]], "11587": ["病机", "右关尺脉微续、细、弦，余部不起，是服药后阳气渐有来复之机。微续示胃气稍回，细弦为寒湿未净、气机尚滞。吐泻稍止而神烦口渴、舌白腹痛瘕攻，说明阴寒未散、阳未全回，故云病情略有转机，仍当通阳。", ["微", "细", "弦"]], "11588": ["病机", "脉右三部软、左手微见一丝若无若有应指不清，是清浊浑淆之后气阴不和、阳气未全回之象。软为气弱，微细若无为阳衰血少，左手不温正合左脉不起。口渴不多饮、神烦，示阴未复而阳未振，故拟撤阴回阳。", ["软", "微"]], "11589": ["病机", "脉细而霍乱吐泻、肢冷音闪、自汗，是暑湿浑淆肠胃、气阴两伤之候。细为气血不足、脉道不充，自汗更耗阳气，肢冷音闪示阳弱不能温达。原文谓疟势非轻，脉细正说明正虚邪恋、气阴俱损，病情不轻。", ["细"]], "11590": ["病机", "脉迟而转筋霍乱、胸闷吐泻腹痛头痛，是寒湿入三阴之象。迟脉主寒，寒性凝滞，阳气不能温运，故吐泻交作、筋脉失养而转筋。胸闷头痛为寒湿上蒙清阳，诸症合参，脉迟正应寒湿内盛，故治法当以温之。", ["迟"]], "11591": ["病机", "脉象迟弦，迟主寒、弦主气滞筋急。霍乱之后寒邪未散，头晕足酸，是余寒留滞、清阳不升、筋脉失养所致。迟弦并见，说明寒凝未解而气机不畅，故治法以疏补兼施，疏其寒滞、补其虚损。", ["迟", "弦"]], "11592": ["病机", "脉迟弦细，迟主寒，弦主痛主风，细主湿滞。原文“风来胜湿，湿胜濡泄，火窜筋挛”，说明风、湿、火交争，湿胜则濡泄，火窜则筋挛，脉迟弦细反映寒湿内滞、筋脉失养，病邪未尽，故以疏和分利为法。", ["迟", "弦", "细"]], "11593": ["病机", "脉尚带数象，数主热，说明伏暑伏湿之邪内郁，虽因瓜梨寒凉致阳气被遏、肢冷呕逆神昏，但脉数提示邪热未清，湿遏伏里而身热不扬。急通阳气、泄湿气，使神清热壮，否则昏闭可危。", ["数"]], "11594": ["病机", "脉数而空，数主热，空主虚，此因伏邪内踞，又被西瓜寒冷遏伏其阳，湿踞中宫，寒凝湿阻痞结，中焦漫无出路。脉数而空反映邪热未清而阳气大伤，故神昏、肢冷、呕恶，病已转剧转危。", ["数", "空"]], "11595": ["病机", "脉弦，弦主水饮、主痛。原文“真阳大虚，脐中动气筑筑，舌白积粉”，肾中真阳虚而水气凌心，水火相激，水寒之气壅遏中宫，以致肢冷、胸中懊𢙐。脉弦正是水寒内盛、阳气虚衰之象。", ["弦"]], "11596": ["病机", "脉迟弦，迟主寒，弦主痛。寒湿鸣聚中阳，腹痛绕脐，因入水捕鱼，寒湿之邪十年蕴蓄，沉寒锢冷非辛热之剂不能除。脉迟弦反映寒湿内盛、阳气被困，故师仲景法以辛热通阳。", ["迟", "弦"]], "11597": ["病机", "脉迟，迟主寒。进辛热通阳后，沉寒锢闭之邪不泄，少腹仍痛，十年之病蒂固根深，非至刚气雄之剂不能破其深伏之邪。脉迟说明寒邪深伏、阳气未复，故反佐苦寒以向导。", ["迟"]], "11598": ["预后", "六脉皆伏，伏主阳衰寒凝，脉道不通；脉得微续者生，微续为阳气渐回之兆。原文“阳微寒湿凝聚”“阳衰浊聚，病情极险”，故以通脉四逆辈救之，脉复则生，暴撤则不治。", ["伏", "微"]], "11599": ["预后", "脉渐微续，为阳气渐回；脉虽复而虚弦兼数，虚弦主阳衰水寒，数主虚热或邪未清。右寸未起，说明肺气未复。原文“一派阴霾之气，尚未消除”，病虽转机，仍守前法以离照当空。", ["微", "虚", "弦", "数"]], "11600": ["病机", "脉迟弦，迟主寒，弦主痛、主厥阴。原文述厥阴寒浊上潜清阳，胸痛嗳噫，卒然寒厥后音哑，肢冷，少腹胀痛。寒浊循厥阴经脉上阻喉咙，故音哑；寒凝气滞，故胸痛、少腹胀痛、肢冷。脉迟弦正合寒浊内踞、阳气不宣之病机，主厥阴寒厥证。", ["迟", "弦"]], "11601": ["病机", "脉细迟，细主虚、迟主寒。原文述脘胀呕恶、泛清水，寒邪内踞，阳明得热饮即泛，寒热格不相入。寒邪内踞，阳气不振，故脉迟；细为阳衰血少。寒饮内停，胃气上逆，故呕恶泛清水。脉细迟主寒邪内踞、胃阳不振之病机，与脘胀呕恶症候相应。", ["细", "迟"]], "11602": ["病机", "脉迟浮虚，迟主寒，浮主邪在上，虚主正气不足。原文述暑湿寒挟秽邪内蕴中宫，头痛胸腹痛，神迷痉厥，口涌血沫，吐黑水，神昏舌缩，苔白。邪入厥阴，挟痰上蒙神明，内风鼓动。脉迟浮虚示邪陷正虚、寒浊蒙窍，病情危险，主邪闭心包、内风鼓动之病机。", ["迟", "浮", "虚"]], "11603": ["病机", "脉迟弦，迟主寒，弦主痛、主厥阴。原文述新婚欲后受寒，少腹作痛，舌白，呕吐酸水。寒湿乘虚入厥阴络脉，寒凝气滞，故少腹作痛；寒湿犯胃，故呕吐酸水；舌白为寒湿之征。脉迟弦主寒湿入厥阴络之病机，与少腹痛、呕吐酸水症候相应。", ["迟", "弦"]], "11604": ["病机", "脉细迟，细主虚，迟主寒。原文述夏日阴气在内，阳气在外，自饮梅酱冷水后，阳气为酸寒所收缩，腹痛，病近半载。酸寒伤阳，阳气收引，寒凝气滞，故腹痛；脉细迟为阳气虚衰、寒凝于里之象。脉细迟主寒伤阳气、阴寒内凝之病机，与腹痛症候相应。", ["细", "迟"]], "11605": ["病机", "脉弦尺细，弦主气滞、主痛，尺细主下焦肝肾不足。原文述日薄西山，阳光衰歇，阳衰则寒浊凝聚少腹，入暮膨满，腑气不爽。阳衰寒凝，气机不畅，故少腹膨满；病在下焦肝肾，故尺脉细。脉弦尺细主阳衰寒浊凝聚下焦之病机，与入暮膨满症候相应。", ["弦", "细"]], "11606": ["病机", "脉沉细弦数，沉主里，细主虚，弦主疟、主气机不和，数主热。原文述温疟八月，寒热羁縻，营卫偏损，自汗，胸闷，上热下寒，阴阳两气不和，腹大坠满，食则䐜胀。久疟脾胃被戕，升降失职。脉沉细弦数示久病正虚、阴阳不调、脾胃升降失司之病机。", ["沉", "细", "弦", "数"]], "11607": ["病机", "脉弦数，弦主疟、主少阳，数主热。原文述湿遏膜原，膜原为阳明之半表半里、三焦之门户，过此而为寒热则成疟。舌白不渴，背胀头痛，溲赤，皆属风邪湿郁。湿遏膜原，邪正交争，故脉弦数。脉弦数主风邪湿郁、膜原不和之病机，与寒热、头痛、溲赤症候相应。", ["弦", "数"]], "11608": ["病机", "脉弦数，弦主少阳枢机不利，数主邪热内郁。原文谓“阴阳相争寒热交作”，邪伏太阴，溺赤为热象。失血之体阴亏，邪伏而化热，故脉弦数。此脉示邪在太阴而兼热，正虚邪恋，治当养阴化邪，宗何人饮。", ["弦", "数"]], "11609": ["病机", "脉沉细微弱，沉主里，细微弱主气阴两虚。原文谓“伏邪为疟”，正虚无力运邪外达，故见眩晕、胃呆、便溏、无汗。脉不浮而沉细，示邪伏于里，营卫不和，气阴两伤，久延恐有虚变。", ["沉", "细", "微", "弱"]], "11610": ["病机", "脉来弦数不和，弦主疟邪郁于少阳，数主热，不和示邪郁不达。原文谓“太阴伏湿郁而不达”，湿郁化热，扰及中州，故胸闷、便泄、腹膨。脉弦数不和，示邪势鸱张，脾伤腹满之虑，法当提邪外出。", ["弦", "数"]], "11611": ["病机", "诊脉弦象较前稍和，知邪势稍达而正气亦虚。弦主疟邪未净，湿伏太阴未化，留恋于中，故口渴喜暖饮、舌质微黄、疟来稍缓。脉弦稍和，示邪减正虚，欲疟止须正旺，拟扶正达邪。", ["弦"]], "11612": ["预后", "脉左沉细，右伏如有如无，沉细主阳气衰微，伏脉主邪闭阳郁。原文谓“阳气随泄，欲绝之象”，四肢逆冷、胸次痞闷，久疟陡然泄泻，阳气随泄而脱，脉伏不起，故断为危候，勉拟一方望其侥幸。", ["沉", "细", "伏"]], "11613": ["预后", "六脉沉微无力，似有若无，沉微主阳气虚衰，无力示正乏不能鼓动血脉。原文谓“久病正乏，不能鼓动其血脉”，肢冷腹痛、疟势错乱，总属邪退正虚、阳气不复之象，脉证相符，预后堪忧。", ["沉", "微"]], "11614": ["病机", "脉来细弦，细主正虚，弦主邪恋。原文谓“暑湿郁伏，未能宣化外达”，湿阻中焦，逼乱神明，故热时神志模糊、便溏溲赤。脉细弦示正虚邪恋，湿阻中焦，法当扶正化邪，从暑湿门主治。", ["细", "弦"]], "11615": ["病机", "脉象滑实而坚，滑主痰湿，实主邪积，坚示有形之滞。原文谓“表里之邪均无出路，挟痰气内蒸”，致腹满时肿、形浮气逆、便下痰沫。脉滑实坚，示痰湿积滞内结，虚实互见，拟助脾胃化痰湿、和营卫。", ["滑", "实", "坚"]], "11616": ["病机", "脉弦动为肝木亢盛、痰瘀交结之象。疟后口腹不慎，气血痰滞黏结成形，疟母胀痛，木邪贼脾致便溏䐜胀。弦主肝病，动主邪正相争，脉证合参，知邪未清泄，病属肝脾，故以煎丸并治。", ["弦", "动"]], "11617": ["病机", "脉弦滑为痰湿内盛之征。久疟伤脾，水谷不化精微，气血与湿相搏成痰，痰稠舌浊，囊湿畏寒，显系阳气衰微、坤土失运。弦主木贼，滑主痰湿，故法当崇土制湿，温运坤阳，阳旺则湿痰自消。", ["弦", "滑"]], "11618": ["病机", "脉仍滑而实，滑主痰，实主邪滞。三疟虽减而大腹膨满、起核坚硬、面浮足肿，乃久病气虚，内夹湿痰，痰随气流行所致。虚中夹实，故以煎剂益气和脾，丸药涤痰降气，标本兼顾。", ["滑", "实"]], "11619": ["病机", "脉沉数主里热湿蕴。三疟五月，疟伤脾胃，内蕴之邪外溢肌表，致一身浮肿；水气上凌犯肺则咳，气化不宣则溲短便溏。沉为在里，数为热，舌白口干，里湿颇甚，逆趋三焦，深虑增喘，故与分消。", ["沉", "数"]], "11620": ["病机", "脉弦迟为邪伏营卫、阳郁不达之象。伏邪三疟无汗，邪不外达，寒热不时，溲少舌腻，皆邪踞不达、营卫偏胜所致。弦主邪争，迟主阳郁，邪势尚盛，入冬阳气潜藏，更不易宣达，故难骤解。", ["弦", "迟"]], "11621": ["病机", "脉细为阴血亏虚之征。素患失血，阴气已伤，又经三疟三年，体虚邪恋，咳嗽痰绿涎沫，色㿠，皆中阳久困、脾虚生痰之候。细脉主虚，无痰不成疟，故先治中宫，崇脾以绝生痰之源。", ["细"]], "11622": ["病机", "脉象弦迟，弦主邪踞少阳，迟主正阳不足。三疟九年，正虚邪恋，邪伏不达，故脉见弦迟。此虚中夹邪之候，治当扶正化邪，使正复则邪自透，不可峻攻。", ["弦", "迟"]], "11623": ["病机", "脉象弦数，弦主伏邪客于少阳，数主邪热内蕴。伏邪为疟，营卫争胜，寒热休作，胸闷头眩心悸，带下腰酸引及环跳，乃阳陷入阴、伏邪未尽而正阴拖虚。弦数示邪热未清，故以何人饮佐提邪。", ["弦", "数"]], "11624": ["病机", "三疟半年，热轻寒重，显系阳衰。疟邪与痰血浑聚内结成疟母，邪郁不达而脾伤腹满。脉迟为阳气不振、阴寒内盛之征，正合阳衰邪郁之机，故以温药通阳逐邪，使阳气振奋则邪可透达。", ["迟"]], "11625": ["病机", "久疟伤阴，营虚湿郁，两足浮肿，兼肝气化风上逆致头眩耳鸣。脉小为营阴不足，滑主湿郁痰聚，正合虚中挟实之象。故养阴必佐理湿，标本兼顾，不可纯补纯清。", ["小", "滑"]], "11626": ["病机", "暑湿风邪为疟间作，头疼胸闷呕恶口苦，腹痛滞下赤白。脉沉主邪伏于里，弦主疟邪与痛，数主暑热内蒸。疟痢虽两途而邪则一，蕴伏肠胃之间，故先理疟邪，使邪从表解则痢亦轻。", ["沉", "弦", "数"]], "11627": ["病机", "入暮灼热头痛胸闷，脉涩为阴虚营亏、暑湿热内蒸阴分之象。阴气孤绝阳气独发，故为瘅疟。涩脉示阴分受灼、血行不畅，宗喻嘉言甘寒泄化之法以消息之。", ["涩"]], "11628": ["病机", "但热不寒、汗多脉数，为瘅疟之典型。数脉主热盛，热蒸于内迫津外泄故汗多，邪在卫营之间，故以泄卫透营为治，使热从表透而营卫调和。", ["数"]], "11629": ["预后", "泻后变痢，脾传肾为逆，痢下五色，形神俱夺。脉浮大虚而按之豁然空，为元气已衰、暑湿弥盛之候。《内经》谓肠澼身热脉大者难治，正虚邪盛故预后堪忧，拟扶正达邪以觇进止。", ["浮", "大", "虚"]], "11630": ["病机", "湿热邪滞蓄积肠胃，误用兜涩升提，邪滞未清仍腹痛下痢。脉左沉细为阴分不足、邪滞内伏，右弦主邪结肠胃、气机不畅。脉症合参，恐成休息痢之累。", ["沉", "细", "弦"]], "11631": ["病机", "久痢伤及脾肾，肾真之阳乏蒸腐之力，故痢下如鱼脑。脉沉细弱为脏寒阳虚、气血不足之征，沉主在里，细弱主虚，正合脏寒阳虚之机，法当升举以振阳气。", ["沉", "细", "弱"]], "11632": ["病机", "脉弦数，弦主气滞、数主热。痢久伤阴而脾虚不运，湿热无形之邪逗留不清，故脉见弦数。原文谓“邪不化而正气拖虚”，弦数为邪热未清之象，与䐜胀、滞下色赤黏腻、腹痛相应，恐邪恋正虚转为休息痢。", ["弦", "数"]], "11633": ["病机", "脉弦主气机郁滞。原文谓“脾寒痰滞，郁阻阳气”，阳不通运则食不运行，脘痛腹胀、便行带积黏腻皆由阳气失宣化所致。弦脉应此痰滞阻遏、阳气郁闭之机，非单纯寒象，故以宣化通阳为要。", ["弦"]], "11634": ["病机", "脉弦大按之细软，弦大主邪滞，细软示正虚。原文谓“寒邪挟湿内蒸”，邪滞不化则少腹痛、小便不利、滞下色白。弦大为邪实之象，细软为里虚之征，故从仲景温下之例，温通以化寒湿之滞。", ["弦", "大", "细", "软"]], "11635": ["病机", "脉弦迟，弦主厥阴气滞，迟主寒。原文谓“厥阴气不疏泄，阳明湿滞寒邪”，寒湿滞下故色赤腹痛、舌白根厚。弦迟正合寒湿内滞、气不疏泄之机，治以温通，使厥阴阳明气机得畅而寒湿自化。", ["弦", "迟"]], "11636": ["病机", "脉象缓大，缓主湿、大主邪盛。原文谓“暑湿无形之邪酿成有形之滞下”，暑湿内蕴阳明，故身热、恶心、腹痛、滞下澼澼不爽、舌白口干。缓大示湿邪弥漫而邪势方张，法当通泄阳明，使有形之滞从下而去。", ["缓", "大"]], "11637": ["病机", "脉左弦数、右细，左弦数主暑湿热壅滞阳明，右细示胃气不足。原文谓“暑湿热壅滞阳明胃口，干恶拒纳”，胃气不下行则口淡舌腻、滞下里急后重。弦数为邪势尚盛，细为胃虚，故初利当通其邪。", ["弦", "数", "细"]], "11638": ["病机", "脉缓大而滞，缓大主湿浊弥漫，滞示气机不畅。原文谓“暑湿酿成滞浊，窃据中宫，下行肠胃”，故身热头痛、胸闷腹痛、便泄转利而黏腻澼澼不爽。脉滞正应湿浊壅阻、气机不宣之机，病势初张，恐其增剧。", ["缓", "大", "滞"]], "11639": ["病机", "脉弦滞，弦主气滞，滞主湿阻。原文谓“湿邪夹滞夹寒内蒸”，寒湿滞下则腹痛、澼澼不爽、舌白口腻、溺赤。弦滞正合湿滞寒邪内阻、气机疏泄不利之机，故法以疏泄，使郁滞之邪得以外达。", ["弦", "滞"]], "11640": ["病机", "左脉细弦兼弱，为汗伤营阴、正气怯弱之象；右关独滑数，乃中焦暑湿风邪蕴蒸未清。细弱示营阴亏虚，弦主邪滞，滑数主湿热痰邪壅于胃关。原文'舌光液涸''神疲力倦'与左脉细弱相应，'下利虚坐努责'与右关滑数相合，故断为中焦邪未清澈、利久伤营。", ["细", "弦", "弱", "滑"]], "11641": ["病机", "休息利七年，腹痛脐下、色赤、澼澼不爽，脉迟。迟为寒象，寒湿伏于营分，凝滞气血，故利下赤而滞涩不爽。原文明言'寒湿伏于营分，宜温下之'，并告诫'无谓久病正虚，便投补剂'，说明此脉迟主寒湿实邪内伏，非虚寒当补之候。", ["迟"]], "11642": ["病机", "下利先红后白，为营分转出气分；腹痛自汗，脉弦。弦主伏邪内蕴、气机郁滞，邪在中宫不得疏泄，故腹痛而利。原文'伏邪内蕴中宫，法以疏理'，说明弦脉在此示邪郁气滞之病机，治当疏理透邪，非虚证之弦。", ["弦"]], "11643": ["病机", "先泄泻而利，脾传肾为逆，色赤腹痛、澼澼不爽，脉沉数，舌黄少纳。沉主邪在里，数主热，沉数相合为里实热邪。原文断为'风邪实热伤于营分'，热伤营血故利色赤，实热壅滞肠道故腹痛澼澼不爽，舌黄亦为里热之征。", ["沉", "数"]], "11644": ["病机", "暑湿寒邪浑蒸中宫，酿成滞下，色赤腹痛，脉大而迟，舌白干恶拒纳、脘闷。大示邪壅气机，迟主寒湿郁遏，邪郁胃阳、壅遏气机不能转运，故恐成噤口。原文告诫'勿以鸦片升提'，正因脉大迟属邪郁而非虚陷，升提则邪恋不泄。", ["大", "迟"]], "11645": ["病机", "便泄日久变为滞下，里急后重、痢不自禁，脉弦洪数。洪数主气分湿热风邪炽盛，弦主邪滞气机。原文'气分湿热风邪伤于肠胃，气陷不升'，洪数为邪热实象，气陷故里急后重，宗逆流挽舟法以升举疏邪。", ["弦", "洪", "数"]], "11646": ["预后", "幼童利下赤白、腹痛口渴，脉虚数。数主热邪未清，虚示正气已伤，虚数并见为邪热伤正、气阴两耗之象。原文'小质重载，恐其不耐支持'，明言此脉示小儿体弱邪盛、正不胜邪，故列于预后，虑其难以支撑。", ["虚", "数"]], "11647": ["病机", "休息利十年，终年滞下、腹鸣瘕聚，脉沉细迟弦。沉细迟主寒湿蕴蓄中宫、阳气不振，弦主凝滞肠胃、瘕聚有形。原文'寒湿蕴蓄中宫，凝滞肠胃''体虚邪实之象'，正合沉细迟弦并见，示久病正虚而寒湿实邪未去。", ["沉", "细", "迟", "弦"]], "11648": ["病机", "两关滑主内风痰阻，尺弱主肝肾两虚。原文谓“肝肾两虚，虚风煽络”，故见舌强肢麻、口眼㖞斜、溲多筋酸。滑为痰，弱为虚，痰随风动，络脉失养，左手不仁。治当益肾之阴，水壮木涵，肝风自熄，风定痰消。", ["滑", "弱"]], "11649": ["预后", "左寸细、关劲、右尺空，原文断为“少阴之虚，水不涵木”，阳气浮越，阴不涵阳，阴阳散失乖离。细为阴亏，劲为阳亢，空为肾虚，故见汗泄津津、中风复发、牙关紧闭。诘朝一候，喘汗可危，属绝症之候。", ["细", "劲", "空"]], "11650": ["病机", "产后营虚阳旺，内风上冒，脉弦缓。弦为风动，缓为气衰，故卒然厥中偏枯、手足软痿、舌蹇神钝。原文谓“气衰络热冲阳，亦少护持”，因产虚空窦多隙，畏风怕冷，乃营卫俱虚之象。", ["弦", "缓"]], "11651": ["病机", "脉数主心火妄动，相火随之，精空水不涵木。原文引“内夺而厥则为瘖痱”，见左手足偏废、缓纵不仁、口㖞头痛、肢麻。少年精血之损，春升阳变内风，卒然中厥。数脉示火盛阴亏，风火相煽，病非旦夕可愈。", ["数"]], "11652": ["病机", "脉来洪数，洪为火盛，数为热炽。体丰多湿多痰，痰随内风上扰，偏中于左，左臂无力，口歪舌强。原文谓“风火痰相煽中络”，洪数正示风火痰交炽，络脉壅塞，故不易脱体。", ["洪", "数"]], "11653": ["病机", "脉缓滑，缓为气虚湿滞，滑为痰涎内蕴。原文谓“烦劳阳气则张，精不养神，内风焮动”，左面部牵引。缓滑并见，示正虚痰伏，风动之根未除，故曰“中风之根也”，非单纯外风。", ["缓", "滑"]], "11654": ["病机", "脉实而大，实主邪壅，大主病进。中虚湿胜，脾阳自衰，口角流涎、口甜便溏，湿困不运。原文谓“水谷精微不化，气血而蒸作甜痰”，实大之脉示湿浊壅盛、气机呆钝，若不忌酒醴荤腥，恐猝然复中。", ["实", "大"]], "11655": ["病机", "脉形细弱，细为阴血亏少，弱为阳气不足。高年气血两亏，肝肾阴虚，阳化内风，右手麻木冷热不知，得热则指尖刺痛。原文谓“偏中之基也”，细弱正示正虚为本，风动为标，急宜和养肝肾。", ["细", "弱"]], "11656": ["病机", "脉数主内热，本案内风挟痰，营血内痹，四肢麻木不仁，不知痛痒，乃风痰阻络、血行不畅所致。脉数反映风痰化热之象，治以化痰养血，血行风自减，仿朱雀法，说明病机为营血痹阻兼风痰内扰。", ["数"]], "11657": ["病机", "脉弦数主肝阳偏亢、木火升动。患者质小体弱，阴虚木火素旺，阳易升动，鱼尾穴痛，厥阳化风旋动，脘痛胃呆，皆肝风犯胃之象。弦为肝脉，数为火旺，故治以平肝、熄风、和胃。", ["弦", "数"]], "11658": ["病机", "脉细结弦，细主阴虚，结主痰阻气滞，弦主风动。病后阴虚，阳气化风挟痰上旋，闭塞清窍，舌强不能言，痰声如锯，眩晕肢麻，乃内风挟痰闭塞虚窍。三阴脉循喉咙挟舌，故见舌强，脉象与证相符。", ["细", "结", "弦"]], "11659": ["病机", "本案未识脉名，然经行腹痛，头晕心嘈，饮甘草汤痛止，显系营液内虚，肝风戕贼。肝藏血，脾生化，经行血会冲脉，下血则血舍空虚，肝阳化风戕土，肝苦急，甘以缓之，故得甘痛缓。病机为营虚肝风乘脾。", []], "11660": ["病机", "脉细主阴血亏虚。肝血少藏，阳化内风上旋颠顶，痛风；木火上陵心阳，惊惕怔忡，彻夜不寐，火升足冷；肝木左升太过，右降不及，轰然上冒，眩晕肢麻筋掣，舌红咽燥，便燥。一派风阳煽动，营液被劫，脉细合证，治当潜阳熄风、养津安神。", ["细"]], "11661": ["病机", "脉滑数主痰火内盛。心风挟痰火上扰神明，错乱病发，烦扰不安，动则阳生，静则阴生。滑为痰，数为火，痰火扰心，故治当潜阳涤痰、镇摄神志。脉象与痰火扰神之病机相应。", ["滑", "数"]], "11662": ["病机", "寸关脉滑，滑主痰盛。痰火扰乱君心，病发则狂言詈骂，不避亲疏，此心风挟肝火上逆。寸关候心肺肝胃，滑脉见于寸关，知痰火壅盛于上焦，蒙蔽神明，故仍当镇摄神志，涤痰降火。", ["滑"]], "11663": ["病机", "脉大主邪气盛，风火痰上旋，壅塞灵机。卒然痉厥，不知所苦，涎痰上涌口沫，病属肝阳风火痰上旋。大脉为风火亢盛之象，火性急疾，故发突然，治宜潜阳熄风化痰，脉证合参，病机明确。", ["大"]], "11664": ["病机", "本案未载脉象，据症析机：肝营不足则木火失涵，火性炎上，凌心扰神，故语言舛错、少寐多梦；风阳上旋则眩晕耳鸣；筋脉失养则抽掣。总属营虚火郁，木火内炽，久则或化痫症，或发外疡，皆由郁火不得透达所致。", []], "11665": ["病机", "脉数牢实，数主火盛，牢实主邪结深痼。气从下逆，厥阳木火挟心胞之火上凌巅顶，故心悸项痛、头重眩晕、神志模糊、口涌血沫、四肢搐搦。火升气逆，溺则气降乃苏。脉证合参，病属痉厥重候，邪势鸱张，故曰重治。", ["数", "牢", "实"]], "11666": ["病机", "脉转弦数，弦为肝风，数为火炽。风气通肝，肝木化火，挟心火上充无制，故猝然神志模糊、口涌血沫、心悸眩晕，痉厥立至。溺得醒者，肝之疏泄犹存。前用咸苦直折，火势已退，脉转弦数，仍当乘其旗靡辙乱而逐之。", ["弦", "数"]], "11667": ["病机", "脉弦数，弦主肝郁，数主火生。失物气郁，木失条达，郁则生火，火生痰热，上凌心阳，扰乱神明，故言语舛错；溲赤为火下移。经来落后色淡，乃肝阴素虚。总属木郁化火，治从《内经》木郁达之。", ["弦", "数"]], "11668": ["病机", "两关弦滑数，弦主肝郁，滑主痰火，数主火盛。产后殇子悲哀，肝气逆郁，郁则生火，火挟痰上攻，故火升一团、郁结咽间、胸次不利；火降则二便通利。汗泄乃松，郁火得越。此木火无制，直上直下，故以咸苦直折其上腾之威。", ["弦", "滑", "数"]], "11669": ["病机", "左弦右数，左关候肝，弦为木郁；右寸候肺，数为火盛。肝郁化火，气火上逆犯肺，灼伤血络，故咳嗽痰中带血、血缕潮热；火扰心神则心悸眩晕。阴虚木火上充，久则恐成郁劳。", ["弦", "数"]], "11670": ["病机", "脉弦数，弦主肝郁，数主火盛。怒则气郁，郁则生火，木火横逆，犯胃则胁胀脘痞、噎塞、口腻舌黄；上灼肺津则鼻燥。阳明胃精不降，木郁不达，治在肝胃，当疏木清火、降胃和中。", ["弦", "数"]], "11671": ["病机", "脉弦数，弦为木旺，数为火炎。木火上冲犯胃，胃气不降，失循序之司，故呕吐酸苦、噫气便艰；津液无以润下，肠道失濡。老年关格大症，本虚标实，不易理也。", ["弦", "数"]], "11672": ["病机", "脉数主热，本案膈症食入脘中刺痛，乃热郁膈间、肺失清肃，气机不畅而痛。数脉为火热内扰之征，与食入刺痛、肺失清肃相应，说明病机重点在热郁气滞，而非虚寒。", ["数"]], "11673": ["病机", "脉迟延虚，迟主阳衰，虚主中气不足。病后动怒抑郁，木失条畅，横逆中宫，致瘕聚脘痛、得食则呕、苦酸痰涎、食物觉冷，翻胃半年。脉迟虚正合中阳挟饮、火衰气郁之机，说明中阳不振、饮邪内停为本。", ["迟", "虚"]], "11674": ["病机", "脉迟延主火衰气郁，脾阳不运。翻胃朝食暮吐、食则䐜胀，乃脾不磨谷、运用失常，火衰则气郁不降。迟脉应虚寒，与朝食暮吐、䐜胀相应，说明中焦火衰、气机郁滞、胃失和降为病机关键。", ["迟"]], "11675": ["病机", "脉迟细弦劲，迟细主虚寒，弦劲主饮邪内结、气机拘急。霍乱后中气被扰，胃虚气逆不降，干恶嗳噫，秋变翻胃，食入倾囊吐出，酸水痰涎，腹鸣便泄。原文明言“中有寒饮内积”，故脉迟细弦劲，正合寒饮内积、胃虚气逆之机。", ["迟", "细", "弦", "劲"]], "11676": ["病机", "脉细弦数，细主阴伤，弦主木旺，数主火盛。性躁多火，木火易动，上冲犯胃，呕吐泛恶。弦数乃木火内炽之征，细为火郁伤阴之象，说明肝木化火上逆犯胃、胃失通降，故以辛苦宣泄、通降阳明为治。", ["细", "弦", "数"]], "11677": ["病机", "脉弦数，弦主饮邪、气机不畅，数主湿热内蒸。酒客湿胜，湿蒸生痰，积饮中阳，入暮呕泛痰涎，舌黄。弦数应湿热痰饮内蕴，若不节饮，后月必成翻胃，说明湿痰积饮、中阳受困为病机，数脉示郁热。", ["弦", "数"]], "11678": ["病机", "脉象浮数，浮主热越于外，数主热盛。营分伏热，血汗染衣，心悸气逆，汗为心液，心阳热郁。浮数说明热郁心营、迫液外泄，与血汗、心悸气逆相应，病机为心阳热郁、营分伏热外蒸。", ["浮", "数"]], "11679": ["预后", "脉燥散乱，散为气散不收，乱为脉道失序。久病元气拖乏，卒然音闪，痰声漉漉，汗出如雨，此脱象也，旦晚可危。散乱脉与汗出如雨、痰声漉漉相应，说明元气涣散、阴阳离决，故断为危候，勉拟以尽来意。", ["散", "乱"]], "11680": ["预后", "卒然寒战、汗泄如雨、痰声如锯，属阳气暴脱、痰浊上壅之危候。左三部脉绝无，是阴血阳气不能充盈脉道；右寸关仅一丝沉数，沉为阳陷，数为虚阳躁动，非实热之数。肺主气，寸关候肺脾，脉微欲绝而见痰声，正合肺气大虚、阳气脱离，故原文断为危险、勉拟复脉冀侥幸。", ["沉", "数"]], "11681": ["病机", "此段紧承上案，明言“肺气大虚，阳气脱离之象”。左脉绝无、右寸关一丝沉数，是肺气虚极不能运血充脉，阳气浮散将脱，故痰声如锯、汗泄如雨。脉象模糊难辨，正属元气涣散、胃气将绝之征，故曰危险不待言，勉拟复脉法以冀侥幸，属回阳固脱之姑息治法。", []], "11682": ["病机", "肛漏久溃，滋水日渗，五液亏耗，下焦气阴日损，故脉息虚弦兼涩。虚为精气怯弱，弦为水气上泛、肝木失养，涩则阴伤精却，原文谓“涩则阴伤，阴伤则精却”。精耗气怯则神衰，痰胶气逆喘急、舌剥咽干、合目欲眠、喃喃呓语，皆阴阳离决脱象，故断为难治。", ["虚", "弦", "涩"]], "11683": ["病机", "营分伏热，迫血上溢而为鼻衄，八日不止，脉数主热盛，头汗足冷是热郁于上、阳不达下。原文断为“肝胃气火载血上溢”，数脉正应气火内炽、营热沸腾。热迫血妄行，故恐其狂出虚脱，数而兼虚脱之势，非单纯实热可比。", ["数"]], "11684": ["病机", "鼻衄如注，原文谓“少阴不足，阳明有余”，右脉数主阳明热盛。温热内蒸，熏灼营分，迫血上溢，故衄血如注；舌白腻为湿热内蕴之征。右数而左不数，说明热偏在气分阳明，渐及营分，故治以气营两顾，清泄与凉营并行。", ["数"]], "11685": ["病机", "童体纯阳，阴亏则内热，热郁气分迫动营分，故时常鼻衄。脉见细数，细为阴血不足、脉道不充，数为内热鼓动，正合“阴亏则内热，内热则营不足”之机。面黄形瘦、木火体形，皆阴亏火旺之象，故法以养阴，滋水以制木火。", ["细", "数"]], "11686": ["病机", "鼻衄三载，时作时止，久衄必耗阴血。脉形细涩，细主阴血亏少、脉道不充，涩主血行不畅、阴精耗伤，故原文直断“阴分伤矣”。长期反复出血，营阴日损，脉道失于濡润，故见细涩，非新病实热之数脉可比。", ["细", "涩"]], "11687": ["病机", "风邪郁于少阳、阳明，牙关不利、耳聋、鼻渊、头胀偏痛，皆少阳经脉不利、阳明风热上扰之症。脉弦为风郁气机、肝胆失疏之象，弦主少阳，亦主风动。原文以辛凉宣泄为法，正合风郁化热、宜疏宜清之病机。", ["弦"]], "11688": ["病机", "原文谓牙宣五年、营阴大夺，虚火日旺，故脉见寸关独数。数主热，独见于寸关，说明虚火扰于上焦心胃，与肾阴不足相合，即景岳所谓少阴不足、阳明有余。此脉不主实热，而主阴虚火旺之病机，与齿龈出血、营阴耗伤相应。", ["数"]], "11689": ["预后", "久病半载，湿热内盛，热伤营分，牙宣如注，脉象细数。细为营阴受损，数为热邪内盛，细数并见说明湿热久羁已伤营分，阴液渐耗而热势未清。原文又言自汗黏手，若不血止恐难支持，故本段以脉细数判断营伤热盛、预后堪忧，非单纯主病。", ["细", "数"]], "11690": ["病机", "厥阴浮阳上扰，阳化内风旋动，致头偏痛、牙宣，脉虚而细。虚细为营阴不足之象，营虚则不能涵敛浮阳，风阳因而上旋不潜。原文明言营虚风旺不潜，故脉虚细正说明本证以营虚为本、风阳上扰为标，与头痛、牙宣等上扰症候相应。", ["虚", "细"]], "11691": ["病机", "阴虚阳逆，牙宣频来，脉细而迟。细主阴血不足，迟主阳气不运或阴寒内滞，细迟并见说明阴亏而阳失潜降，虚阳上逆。原文以养阴为法，正针对阴虚阳逆之病机；脉细迟与牙宣频来相应，提示本证非实火，而是阴亏阳逆所致。", ["细", "迟"]], "11692": ["病机", "本段未识脉名，专论阳明经脉循行与牙漏成因。原文谓邪火相搏、蕴结不解而成牙漏，时或头胀脘痛，说明病机为邪火蕴结阳明，循经上扰。治法养血熄风，取治风先治血、血行风自灭之义，提示牙漏虽属火结，却需从血分调治，使风火自平。", []], "11693": ["主病", "阳明湿热内蒸，齿匿蠹牙痛，脉弦，舌黄腻。弦脉主痛、主气机郁滞，亦见于湿热蕴结、经脉不和；舌黄腻为湿热之征。脉弦与舌黄腻合参，说明牙痛由阳明湿热内蒸、气血壅滞所致，故以泄化法清化湿热，弦脉在此主湿热壅滞之牙痛。", ["弦"]], "11694": ["病机", "风热郁于少阳、阳明，耳胀流水，脉弦数。弦主少阳经脉郁滞，数主热，弦数并见说明风热之邪郁于少阳阳明，经气不利而化热。耳胀流水为风热上扰清窍之症，与脉弦数相应；故以微辛宣泄，透解郁于少阳阳明之风热。", ["弦", "数"]], "11695": ["病机", "心痛彻背、背痛彻心，病起背寒，寒邪挟饮，脉弦便溏。弦脉主饮、主痛，亦主气机不利；寒饮内踞中焦，阳气不布，故背寒而便溏。原文治在中焦，说明脉弦在此反映寒饮挟滞、中焦气机不畅之病机，与胸痹心痛及便溏症候相应。", ["弦"]], "11696": ["病机", "脉弦数，弦主气机郁滞、木失条达，数主郁而化热。原文谓“清阴结痹胸胁，痞胀彻背”，是胸阳不布、气机不司流利，郁滞日久生热，故脉见弦数；嗳噫、矢气稍松，正说明气结而非虚损，弦数应胸胁痞胀、气机壅塞之候。", ["弦", "数"]], "11697": ["病机", "脉滑主痰、主实。原文云“上焦痰热郁于阳位，气机失司”，咽间噎塞、胸中清阳结痹、少寐，皆痰热壅于阳位、肺失清肃所致。滑脉应痰热内郁，故以清肃化痰、通阳流气为治，脉滑正是痰热结痹之征。", ["滑"]], "11698": ["病机", "脉迟细涩，迟主阳郁不宣，细涩主寒凝血脉、气机不利。原文谓“心痛彻背，寒气结痹阳位，阳郁不宣”，寒邪结于阳位，阳气不能流布，故脉道迟细而涩；此脉应胸背痛、阳郁寒凝之候，治以清利通阳、流行气机。", ["迟", "细", "涩"]], "11699": ["病机", "脉数滑，数主郁热，滑主痰实。原文谓“胸痹胸中起痞，背痛”，又言“阳气结痹不宣”，是阳气郁结、痰热内壅，气机不得流通，郁而见数滑。数滑应胸痞背痛、阳结不宣之候，故以滑利通阳为法。", ["数", "滑"]], "11700": ["病机", "右关候脾胃，脉滑主饮。原文谓“阳微饮聚，结痹清阳”，病发于春夏阳气升动之时，胸痞泛水，是阳微不能运化，饮邪聚于中焦，上痹清阳。右关滑正应饮聚中焦、阳微结痹之候，故以辛滑流利开拨气机。", ["滑"]], "11701": ["病机", "脉细弦，弦主肝气横逆，细主阴血不足。原文谓“木失条畅，肝气横逆犯胃”，脘痛、呕吐酸苦、舌黄泛恶、少纳神疲，皆肝木犯胃、中土受侮之候。细弦应肝郁阴伤而胃受克，故先以泄肝和胃为治。", ["细", "弦"]], "11702": ["病机", "左弦右虚，左候肝、右候脾。原文谓“久疟致肝木阴亏阳旺，木旺则乘脾犯胃”，脘胁痛、呕吐少纳，左弦为肝旺，右虚为中伤；舌白口腻、面萎黄、便溏结不定，皆脾土失运。弦虚并见，正示肝旺脾弱、中伤之机。", ["弦", "虚"]], "11703": ["病机", "复诊脘胁痛止、纳谷稍增，而“脉象仍弦”，原文断为“肝木有余，脾土阴弱”。症减而脉弦不退，说明肝木亢旺未平、脾阴尚弱，弦为肝旺之象，故宗景岳法养肝阴以柔其刚，弦脉在此主肝木有余而非新感。", ["弦"]], "11704": ["病机", "脉见弦长，遇指按之软弱无神，外刚内柔，显系肝气有余而肝血不足。血虚不能培肝之气，气愈横扰，则脾愈困，水谷精华不运，升降失常。原文谓“脾受戕贼重伤其伤”，故脉弦长为肝旺乘脾之象，软弱无神示内虚，主痃疟后脾伤肝乘、痰气结瘕之病机。", ["弦", "长", "软", "弱"]], "11705": ["病机", "左关双弦如芤，左关滑大，知病在肝胃。弦为肝旺，芤主血虚，滑大为胃有积痰。肝不疏泄则木旺，胃有积痰则中伤，脘痛三月不止。原文谓“中伤木旺，理宜制木通胃”，此脉示肝胃同病、痰积气滞之机。", ["弦", "芤", "滑", "大"]], "11706": ["病机", "脉细弦，细为胃汁受戕、阴血不足，弦为肝木风阳亢逆。肝风戕胃，则脘痛胁胀、呕吐绿水蛔虫、舌干拒纳。原文谓“胃汁受戕，难投刚药”，故以柔剂缓肝之急。此脉主肝风犯胃、胃阴亏虚之病机。", ["细", "弦"]], "11707": ["病机", "脉弦劲不和，弦为肝旺，劲为气逆，示肝木乘脾犯胃。积饮中宫，木旺克土，胃气上逆，故脘痛吐酸水。前法制木病不减松，当进一筹以守之，安胃法。此脉主肝胃不和、饮停气逆之病机。", ["弦", "劲"]], "11708": ["预后", "脉象弦劲不和，状如新张弓弦，全无冲和之象。久病见此，乃肝木亢逆、胃气受戕，失其柔和之常。原文谓“究属不宜”，示病深正虚、脉无胃气，预后堪虑。仍守前法，以安胃制木为治。", ["弦", "劲"]], "11709": ["病机", "脉弦数，按之细，弦主厥阴气不疏泄，数主热，细主湿郁。寒浊内踞，瘕聚有形，攻逆胀痛，舌黄腻，此中阳湿郁不化，郁而化热。原文谓“治当疏泄肝脾”，脉示肝脾不调、湿浊郁热之病机。", ["弦", "数", "细"]], "11710": ["病机", "脉数大，数为热，大为邪盛。脘痛久延，肝木横逆犯中，胃气逆行不降，得食即吐，夜则寒热胁痛鸣响，胃虚积饮痹络。木火上冲于胃，久病正虚，脉数大示邪热亢盛而正已伤，主肝胃同病、饮热上逆之机。", ["数", "大"]], "11711": ["病机", "诊脉弦数，弦为厥阴气滞，数为郁热。厥阴浊聚气痹，无形之气似乎有形，攻逆不已，上至胸背脘宇，下腹坚结，噫气矢气，病情一派气滞。原文谓“疏理其气，佐以宣泄厥浊”，脉示肝经气滞、浊聚化热之病机。", ["弦", "数"]], "11712": ["病机", "脉弦为肝木之象，本案肝脾寒邪结瘕，脘痛延及三年，弦脉反映肝气郁结、寒凝营分，气血结聚成瘕。弦主痛、主寒、主气滞，与脘痛、瘕块相应，病在营分，故治当温通营络。", ["弦"]], "11713": ["病机", "脉弦数，弦为肝脉，数主热，左胁下瘕癖时常䐜胀，乃肝脏积聚日久化热之象。弦数并见，说明肝气郁结而内有郁热，病经有年，根深难拔，故难许除根。", ["弦", "数"]], "11714": ["病机", "脉弦主肝木气滞，痰血气滞凝聚为瘕，结于左胁下，大便滞下赤白黏腻，乃肝气乘脾、湿热积滞之候。弦脉应肝，反映气滞血瘀痰凝，乘其势而逐之，即借脉弦所示病势以攻逐瘕积。", ["弦"]], "11715": ["病机", "室女先天不足，营虚阴弱，脉数非热盛，乃阴血亏虚、虚热内生之象。脘痛收引、痛引两胁、腰楚如折，为肝木乘脾、脾胃不和所致。数脉在此提示营阴不足而肝气偏亢，故以泄肝和中为治。", ["数"]], "11716": ["病机", "脉弦虚数，弦为肝郁，虚为气营不足，数主郁热。右胁痛引脘、瘕攻，乃肝胃不和、气营两病之候。弦虚数并见，说明肝气横逆而正气已虚，郁热内扰，故以通络泄肝和胃为治。", ["弦", "虚", "数"]], "11717": ["病机", "脉大而虚，大为邪盛，虚为不足，此胃津不足、阴亏木旺之象。肝逆犯胃，脘痛呕吐倾囊而出色赤，乃肝火犯胃、胃失和降。脉大而虚说明阴津亏耗而肝阳偏亢，故以温中泄肝为治。", ["大", "虚"]], "11718": ["病机", "脉迟弦，迟主寒，弦主肝，寒湿鸠聚中肠，少腹痛、脘痛、瘕攻，乃肝木犯脾胃、寒湿内阻之候。迟弦并见，说明寒湿凝滞而肝气乘脾，故脉象反映肝木犯脾胃之病机。", ["迟", "弦"]], "11719": ["病机", "脉细弦，细为阴血不足，弦为肝气郁逆。素有肝逆，木乘风冷寒邪乘之，绕脐腹痛、便溏腹鸣，乃肝木乘脾、寒湿内盛之候。细弦说明肝郁而营阴不足，故拟刘草窗法以疏肝温中。", ["细", "弦"]], "11720": ["病机", "脉迟弦，迟主寒，弦主痛、主肝。厥阴寒浊锢蔽脏络，阳气不运故脉迟；寒凝气滞，络脉拘急故脉弦。腹痛、瘕攻绕脐，正是寒浊结聚、肝络不通之象。脉证相合，故治以温通，散寒化浊以通络。", ["迟", "弦"]], "11721": ["病机", "脉迟为寒邪内踞，阳衰不运。入暮阳衰痛甚，阳微之处即阴甚之处，饥不欲食、食则䐜胀，皆肝脾阳虚、寒浊内阻之候。病在肝脾，屡进温中泄肝不应，痛仍如故，说明寒邪深踞，非单纯治肝所能解，故治脾亦良。", ["迟"]], "11722": ["病机", "尺脉细微，主肾阳真火衰微。真火不能腐谷，胃气杳然，故入暮阳衰；绕脐痹痛，乃坎中真阳不能温煦所致。脉细微为阳气衰微之征，真阳不可任其汨没，故急宜益火生土，温补下元以复中焦运化。", ["细", "微"]], "11723": ["病机", "脉数主热，舌红亦为热象。肺消饮水小便多、下白垽，乃阴亏阳失其基，虚火内扰。脉数在此非实热，而是阴亏不能制阳、阳浮于外之象。故先与许叔微法，滋阴降火以固其本，使阳有所基。", ["数"]], "11724": ["病机", "脉弦而数，弦主肝、主气滞，数主火。消渴小溲多、吐白沫、心中窒塞，乃火邪上炎，求救于水。前法咸寒制火而病情未见所长，说明火势燎原，非咸寒所能制，当进一筹以熄燎原，直折火势。", ["弦", "数"]], "11725": ["病机", "脉象迟弦，迟主寒、主衰，弦主痛、主肝。厥浊无形之气结聚有形，大如鸡卵，卧则入腹，立则坠囊，睪丸胀痛，乃老年疝病，气血皆衰，寒浊凝滞肝络所致。脉迟弦正合寒凝气滞之机，故除根不易。", ["迟", "弦"]], "11726": ["病机", "脉迟弦，迟主寒，弦主肝、主痛。七疝皆属肝病，厥阴上逆，呕吐蛔虫，小腹胀痛，乃寒浊循肝脉上逆、胃气不和之候。脉迟弦反映寒凝肝络、气机逆乱，故以泄肝通胃为治，痛甚防厥，虑其气逆更甚。", ["迟", "弦"]], "11727": ["病机", "原文未识出脉名，然述厥阴寒浊一遇寒劳即作疝气，从少腹直攻肾囊，胀痛引脘。此因肝脉绕阴器环贯膈，寒浊乘虚循经上逆，气机壅滞所致。病机在厥阴寒凝气滞，劳则气耗寒动，故疝气随寒劳而发。", []], "11728": ["病机", "脉缓主湿，缓为湿邪内蕴、气血运行不畅之象。本案两足浮肿及腹、四肢麻木、干恶胸闷，皆湿浊阻滞、气机不宣所致；脉缓与便燥并见，说明风寒湿三气袭络日久渐次化热，湿中有燥、络脉不和，故病来由渐而不易理。", ["缓"]], "11729": ["病机", "脉弦主痛、主饮、主寒湿入络，数则为热。脚气肿势渐消而少腹䐜胀，脉转弦数，正是三阴寒湿渐化热之征，寒湿久郁化热，络脉壅滞未通，故仍以通络为治，弦数在此标示寒湿化热之病机转归。", ["弦", "数"]], "11730": ["病机", "原文未出脉名，仅言三阴寒湿、脚气麻木胸闷、病经五年屡发。久病邪已深入脉络，寒湿痹阻三阴，气血不能温煦濡养，故麻木胸闷反复发作；病程既久，非表浅之邪，故治法以搜剔脉络伏邪为主，属病机与治法并述之案。", []], "11731": ["病机", "脉弦细，弦主寒湿入络、脉络拘急，细主阴血不足。两膝麻木、肢痿不用、肌肤不仁，为寒湿袭三阴脉络、气血不荣所致；溲赤则示湿郁有化热之象。弦细相合，正说明寒湿痹阻而阴分已伤，故曰不易即愈。", ["弦", "细"]], "11732": ["病机", "脉迟细，迟主寒、主阳虚，细主气血不足。寒湿下著左足跗及指经，酸痛麻木，正是寒湿凝滞经络、阳气不能温运四末之象；脉迟细与寒湿下著相应，说明病属阴寒偏盛、气血运行迟缓，故断为脚气。", ["迟", "细"]], "11733": ["病机", "脉弦细，弦主寒湿痹阻、脉络拘急，细主阴血亏少。寒湿下著成脚气，酸楚、小便浑浊为湿浊下注；气急则示寒邪上逆、肺气不利。三阴寒邪乘之，脉弦细正合寒湿入络而阴分不足，故恐脚气上入少腹而致喘急。", ["弦", "细"]], "11734": ["病机", "脉沉主里、主水湿内郁。流火脚气肿势渐退，又生火丹红肿而痛、溲赤，是湿邪未尽而化火入血分，热毒壅于肌肤；脉沉说明病位在里，湿热郁蒸于内而外发为丹，故法以清泄里热湿毒为治。", ["沉"]], "11735": ["病机", "脉细带弦，细主阴血不足，弦主风邪入络、脉络拘急。风性善行数变，腿酸流走不定、上行环跳下至腿䟰，正是风邪袭三阳脉络之象；弦细并见，说明三阳邪袭脉络而三阴阴虚，故治法通络和阴、佐以搜风。", ["细", "弦"]], "11736": ["病机", "脉细主血虚，营血不足则脉络空虚，风邪乘虚袭络。原文“脉细血虚，风来袭络”明言血虚为风袭之因，风寒湿三气杂至成痹，四肢屈伸不利、肤痒风块皆风邪入络之症。治以疏通和阴，即养血以祛风，络脉得养则风自息。", ["细"]], "11737": ["病机", "脉细迟为营血不足兼寒邪凝滞之象。寒邪久袭脉络，锢蔽不泄，气血不得流通，故左肩髃酸痛不举。细主血虚，迟主寒凝，病经一载，邪深正虚，故不易速愈。原文“使气血流行，病自可复”点明针师宣导以通络行滞之法。", ["细", "迟"]], "11738": ["病机", "脉缓主湿，亦主气血两虚。老年气血不足，虚风煽动，风湿袭于肌肉，故皮肤瘙痒浮肿流水、发风块隐疹。原文“脉缓，不纳，老年气血两虚”示缓脉非平脉之缓，乃虚而兼湿之候，病来有年，正虚邪恋，故难许无事。", ["缓"]], "11739": ["病机", "脉沉弦迟，沉主里、弦主痛主饮、迟主寒，合为风寒湿邪入于脉络、久痹不宣之象。素体营虚，邪乘虚入络，气血痹阻，故肩髃、腰背、尻骨酸楚。原文“入络之病，化邪必佐养营”点明营虚为本、邪痹为标，治当祛邪兼养营血。", ["沉", "弦", "迟"]], "11740": ["病机", "脉细迟弦，细主营血衰少，迟主虚寒，弦主风动。近耄之年营血自衰，血虚生风，风生热，热灼肌干，故皮肤燥痒。原文“血虚生风，风生热”明示病机链条，细迟为血虚之据，弦为风动之征，法宜养血熄风，血充则风热自平。", ["细", "迟", "弦"]], "11741": ["病机", "脉弦细迟，弦主风、细主血虚、迟主寒，合为脾胃伏风兼营血不足之象。风疹屡发八年，发时寒热、腹鸣便泄，乃太阴、阳明伏风内扰，脾运失司。原文“脾胃伏风”点明病位，弦细迟示正虚邪恋，故与消风散祛风兼和营。", ["弦", "细", "迟"]], "11742": ["病机", "原文未识脉名，然述风寒湿三气流络，鹤膝风肿痛、伸屈不利、两臂筋脉痛楚，舌白尖红、便溏溲少，显系肝脾肾三阴邪痹脉络。三阴亏虚，邪乘虚入络，气血痹阻，故肿痛不利。原文“入络之病，岂易效哉”叹邪深正虚，难以速效。", []], "11743": ["病机", "脉弦细，弦主气滞、细主血虚。肠痹腑阳窒塞，二便不通、脘胀少纳干呕、少腹旁痛，皆血虚不能灌溉腑阳所致。原文“此属血虚不能灌溉其腑阳也”明言病机，大肠与肺相表里，故养血中佐开肺，以肺主气化，气行则腑通。", ["弦", "细"]], "11744": ["病机", "原文谓「脉见寸关弦象，按之细弱」，弦主肝郁湿热，细弱则示心肝脾三脏已虚。湿热下注大肠致痔坠下血，脉弦应湿热相激；按之细弱，正合「心不生血，肝不藏血，脾不统血」之血液已亏，故见心宕嘈杂、目眩便溏。脉象虚实并见，说明湿热尚甚而脏气已虚，故先清理湿邪、续商进补。", ["弦", "细", "弱"]], "11745": ["病机", "本段未识脉名，纯以症候推病机。原文言「失血之体阴气自虚」，咽燥舌红为肾阴乏上承；「得食䐜胀」乃脾阳滞运，饮食少化，精微变痰，流入脉络结为痰核于环跳。病机关键在阴虚与脾阳不运并存，痰浊流络，故拟养阴化痰以冀消散，并虑久延成痈。", []], "11746": ["病机", "原文径言「脉细以养阴化痰」，细脉主阴血亏少。阴虚则木火偏旺，炼液为痰，痰疬结于颈侧。脉细正应阴液不足、脉络失充之机，故治法以养阴化痰为主，使阴复则火降、痰消而疬散。此段脉象与病机、治法紧相呼应，非泛言虚损。", ["细"]], "11747": ["病机", "原文「肝逆挟痰，气痹胸膺，痰疬时痛，心嘈，脉滑」。滑脉主痰，肝气上逆挟痰阻于胸膺，气机痹阻故痰疬时痛；痰扰及心则心嘈。脉滑与痰疬、气痹相应，说明病机重心在肝逆与痰浊互结，故治以平肝化痰，使气顺痰消则胸膺自舒。", ["滑"]], "11748": ["病机", "原文「诊脉左部弦大，溲赤」，左部应肝，弦大为肝经邪盛之象。宿疾失血后复发胁痛、不得左眠，咳嗽痰臭脓血，溲赤，合而观之，乃内痈生于肝脏。弦大示肝络壅塞、热毒内蕴，故断为「非轻恙」，提示病深势重，非寻常胁痛可比。", ["弦", "大"]], "11749": ["预后", "原文「失血瘀凝下趋，黑粪自下，痰臭，脉浮大」，浮大之脉见于失血之后，为正虚而气浮不敛、血失所摄之象。肝络阴脏已伤，气不摄血，瘀血下趋见黑粪，故虑「尚虑狂溢」，即恐血再妄行外溢。此段以脉浮大断预后险，重点在气不摄血、血溢未止之忧。", ["浮", "大"]], "11750": ["病机", "原文「热郁肺金，皮毛焦热，咳嗽痰臭，脉细数」。细为阴伤，数为有热，热郁肺金、灼伤肺络故痰臭；肺主皮毛，热郁则皮毛焦热；缺盆下痛亦属肺热见证。脉细数与肺热阴伤之机相合，故治以甘寒清热、佐以辛苦，清金而不伤阴。", ["细", "数"]], "11751": ["病机", "原文「脉来右寸带弦而数」，右寸候肺，弦为木旺，数为火盛。久咳络伤咯血，肺虚失清肃、乏制木之权，木反侮金，气火浮肺故呛甚；亥戌寅卯木火用事之时症加，正应弦数之脉。此脉示肺虚而肝木火气上逆，故法当清金制木。", ["弦", "数"]], "11752": ["病机", "右寸关弦，右寸候肺、右关候脾，弦为肝脉。呛甚于寅卯木旺之时，痰不易咯，是肝木之气当令而亢，循经上逆犯肺，木入金乡，肺失清肃，故咳呛难已。脉弦与时辰相应，皆示肝木偏旺、肺金受侮之病机。", ["弦"]], "11753": ["病机", "酒客湿胜蒸痰，又感风邪，舌白口腻、溺赤便溏皆湿壅之征。脉弦数为肝木化火之象，呛甚于黄昏，正值肝阳用事，木火循经上扣肺金，故咳延两月不易即愈。弦数示木火内动，非单纯外感。", ["弦", "数"]], "11754": ["病机", "右部弦数甚于左部，右寸关属肺脾，弦数乃肝木化火之脉。咳嗽年余，甚于晨昏肝阳用事之时，是木火上扣金鸣，金虚不能制木，反受木侮，即《内经》反侮所不胜。脉弦数正示木火亢盛、肺金受侮之机，故宜清金平木。", ["弦", "数"]], "11755": ["病机", "右脉依然弦数，咳以寅卯为甚，弦数乃木火之象，寅卯木旺之时火升扣金。金无制木之权，木反侮金，故一载不愈。脉象未变，说明木火未平、肺金仍虚，故治法欲制木先清金，欲涵木先壮水，煎丸分治。", ["弦", "数"]], "11756": ["病机", "脉数虚弦，数为火动，虚为阴亏，弦属肝木。肺肾两亏，咳血甚于夜分木火升动之时，素有遗精，精遗则阴空，木失涵养而化火，上扣肺金。数虚弦三象合参，正示阴亏火动、木火刑金之病机，故治宜益水养木。", ["数", "虚", "弦"]], "11757": ["病机", "黄昏气火浮于肺，咳呛突甚，脉弦数。弦为肝脉，数为火象，黄昏阳气入阴、肝火易升，木火上犯肺金，肺失清降而咳呛骤作。脉弦数与症相应，明示肝木上犯肺金之病机，非外邪袭肺可比。", ["弦", "数"]], "11758": ["病机", "风寒郁肺，又食酸果收敛，咳嗽音闪，金实无声。脉迟细而涩，迟为寒凝，细为气少，涩主气机壅滞不畅，正合寒邪与酸收相合、肺气闭郁之实。脉证相参，示肺金实而气闭，故治法宜启之，开宣肺气。", ["迟", "细", "涩"]], "11759": ["病机", "邪感风池风府，脑后痛、咳嗽、便泄，脉迟弦。弦主风主痛，迟主寒湿凝滞，风邪挟湿内侵，上扰清窍则脑痛，犯肺则咳，下迫大肠则便泄。迟弦并见，示风邪兼湿、气机不畅之病机，故以泄风化湿消痰为治。", ["迟", "弦"]], "11760": ["病机", "脉数弦长，数主热，弦主肝郁，长主气火有余。原文谓“肝胃郁热，木火乘之”，木火刑金则干呛、眩晕，昏暮气火浮肺，故脉象弦长而数。此脉主肝胃郁热、木火犯肺之病机，症见干呛、眩晕，甚则络伤见血，慎防咳血。", ["数", "弦", "长"]], "11761": ["病机", "脉数主热，原文谓“风邪久郁成热，热复与湿交蒸，炼液成痰”，痰蕴中焦则胸闷窒塞，晨起呕痰、痰黄咽痒。此脉数说明风邪郁久化热，湿热交蒸，炼液成痰之病机，主咳嗽痰黄、胸闷等症，久病邪郁尚宜清泄。", ["数"]], "11762": ["病机", "脉数主热，原文谓“阳明旺于未午后，灼热脉数”，并见溲黄、咳嗽、苔灰，乃“肺胃湿郁热蒸不化”。此脉数说明湿郁热蒸之病机，热势于阳明旺时加剧，主灼热、溲黄、咳嗽等症，治以清泄。", ["数"]], "11763": ["病机", "脉细主阴血不足，原文谓“阴乏上承，肺气痹阻，少阴阴虚也”，故见上实下虚、咳嗽咽梗、腰痛如折。此脉细说明少阴阴虚、阴精不能上承之病机，主肺气痹阻之咳及肾虚腰痛，属阴虚不足之候。", ["细"]], "11764": ["病机", "脉弦数，弦主肝木，数主火，原文谓“木火上逆扣金，木入金乡之候”，故咳呛甚于天明、气逆无痰、舌黄溲赤。此脉说明肝木火旺、上逆犯肺之病机，主咳呛气逆，引《经》文说明五脏六腑皆令人咳。", ["弦", "数"]], "11765": ["病机", "脉细虚弦，细虚主阴亏，弦主气逆，原文谓“肺肾阴亏，咳呛气逆，肾阴虚不能上交心阳”，故心神恍惚、语言呆钝、似乎健忘。此脉说明肺肾阴亏、心肾不交之病机，主久咳气逆及心神不宁之症，治从肺心肾。", ["细", "虚", "弦"]], "11766": ["预后", "脉来数疾无绪，数疾主热盛，无绪示脉乱无根，原文谓“血脱气空，气不摄血，有汗脱之象”，症见狂溢盈碗、吸短、咳呛、溲赤。此脉说明气随血脱、气不摄血之危候，预后险恶，勉拟血脱益气以冀血止。", ["数", "疾"]], "11767": ["病机", "脉数主火，原文谓“肝胃气火载血上逆，狂溢，火升足冷，咳呛，咽痛”，乃阴空气逆之候。此脉数说明肝胃气火上逆、阴血亏空之病机，主咳血狂溢、火升足冷等症，法以降逆佐益气，培无形之气以生血。", ["数"]], "11768": ["病机", "脉来数疾，数主热，疾主急，为气火上载阳络、失血狂溢之象。血溢则阴空，阴不制阳则气逆，故脘闷、咳呛咯痰白沫。脉数疾正是阴气大伤、阳气独冒之征，法当潜阳育阴，以复阴阳之衡。", ["数", "疾"]], "11769": ["病机", "两关弦劲不和，关候肝胃，弦劲为肝气横逆、胃络受伤之象。气火上逆则咳呛胁痛，失血后肝营自虚，脉仍弦劲，示肝阴不足而气火未平。法当和养肝阴、通络理气，气和则血降火平。", ["弦", "劲"]], "11770": ["病机", "脉数主热，为肝胃气火上载、血溢频频之征。额热足冷乃阳浮于上、阴不敛阳；咳嗽溺赤亦火逆之象。脉数示气火内炽，迫血妄行，宗缪氏法清降气火，使火平血止。", ["数"]], "11771": ["病机", "脉沉数，沉主里，数主热，为阳明湿热蕴蒸、气火迫血上泛之象。吐泻后湿甚化热，咳伤血络，胸闷眩晕，血溢狂溢。上升之阳不降，下陷之阴已空，脉沉数正是湿热内蕴、气逆血溢之征，法当降气清营。", ["沉", "数"]], "11772": ["病机", "脉细数，细为阴伤，数为热，为气火上逆未平、营中余热未清之象。血溢稍止而咳呛痰多、咽痒，示阴液已伤而火未全降。脉细数正是营热阴伤之征，仍当降气并清营中之热。", ["细", "数"]], "11773": ["病机", "脉数，为血去阳升上冒、阴空阳越之征。眩晕耳鸣、面赤足冷、少寝，皆阳浮于上、阴不守下之象。脉数示阳气独升，最易血冒。忧思更助阳越，故宜静养，静则阴生而阳自守。", ["数"]], "11774": ["病机", "脉数，为夏至阳升、阴未复而失血复发之征。痰中缕缕、眩晕，皆阳升气逆、迫血上溢之象。年近弱冠，血气未定，脉数示阳升阴亏，务宜保真戒色，使阴复阳潜。", ["数"]], "11775": ["病机", "脉细弦迟，细为阴血不足，弦为肝气偏旺，迟为阳气不振，合之中虚气弱、气不摄血。痰血兼集、咳嗽气短，失血已多而阳气上逆，脉细弦迟正是中虚肝逆、气不摄血之征，再以养肝降气以期血止。", ["细", "弦", "迟"]], "11776": ["病机", "脉沉细紧，沉主里、细主阴血不足、紧主寒，合而示中焦虚寒、气不摄血。咳嗽痰秽咯血已多而吸短，是血去气伤、寒凝于里，气失统摄则血不循经。紧非表寒，乃里寒收引之象，故断为中寒、气不摄血，与金匮温中摄血法相应。", ["沉", "细", "紧"]], "11777": ["病机", "脉弦为肝木之象，主气机郁逆。气火载血上溢速行、震动阳络，咳嗽咽痒、舌黄气逆，皆气火上冲、肝络受伤之候。弦脉应肝，说明火由气升、血随气逆，故用缪氏降气清火法，使气降则血宁。", ["弦"]], "11778": ["病机", "脉芤为中空之象，主失血伤阴。屡次血发则气阴两虚，芤而兼下虚不纳，是阴亏于下、气不归元，故咳呛气逆。芤脉示血去而脉道未复，虚象显然，法以摄下，纳气归肾以固其本。", ["芤"]], "11779": ["病机", "脉数为热象。失血后痰咯黄脓而臭，是肺胃湿热熏蒸、蕴结成脓，热盛故脉数。数脉在此不主虚火，而主实热壅蒸，与黄脓臭痰相应，故法以清化，清肺胃湿热以除其源。", ["数"]], "11780": ["病机", "脉芤主失血。失血后狂溢、额热舌白，是气载血上逆、肝胃络热，血热妄行而脉道中空。芤脉示血溢于外而阴未充，气火仍逆，故恐其血冒，须防上冲昏冒之变。", ["芤"]], "11781": ["病机", "脉缓而芤，缓为胃气尚存、芤为失血中空。肝胃血泛狂溢之后，咳呛溲黄、气火未平，阳络乃伤，缓而不数说明火势未炽，芤则示血去阴伤。故宜养肝阴、佐降气，使气火平而络自安。", ["缓", "芤"]], "11782": ["病机", "脉弦数为肝阳上逆、火热内动之象。失血止而复作，头重足轻、咳嗽溲赤，是阳气不潜、升而不降，血随气逆。弦应肝、数主热，说明阳亢火动、络伤血溢，故防其狂溢，治当潜阳降逆。", ["弦", "数"]], "11783": ["病机", "脉形迟滑，迟为阳气不足、滑为痰湿内蕴。咳嗽失血月余未止、劳力即吐，是劳则气耗、中虚气不摄血，痰湿阻中故脉滑，阳弱故迟。此非热迫血行，乃气虚失统，故治以益气降气，以气为血帅。", ["迟", "滑"]], "11784": ["病机", "脉数而疾，数主热，疾乃数之甚，示气火内炽，迫血妄行。原文谓“气火载血上溢，失血鲜明”，血出鲜红为热伤阳络之征；阴虚不能制阳，热郁于内，故脉行急迫。此脉主阴虚热郁、气火上逆之失血证，与血泛、阴虚、热郁相应，治当清营降气，气降则血归经。", ["数", "疾"]], "11785": ["病机", "脉数大，数主热，大主阳动，合示肝火内升，气火载血上溢。原文谓“操劳血发阳动内升”，劳则伤阴，阳无所附而升动，肝火迫血，故脉数大。此脉主肝火载血之失血证，与血发、阳动内升相应，治宜养阴平肝，使肝有藏血。", ["数", "大"]], "11786": ["病机", "失血后咳嗽，脉数，数主热，示肺胃郁热未清。原文谓“阴气自虚，五心燔灼”，热郁于内，阴液耗伤，虚热外扰，故脉数。此脉主肺胃郁热、阴气虚弱之咳血后诸症，与咳嗽、五心燔灼相应，治以养营泄热。", ["数"]], "11787": ["病机", "脉数疾，数疾为阳热急迫之象。原文谓“冬至一阳萌动，失血复发，阴不主守，阳不潜藏”，阴亏不能内守，阳气浮越不藏，迫血妄行，故脉来急疾。此脉主阴虚阳浮、血不归经之失血证，治以潜阳育阴，使阳得潜藏。", ["数", "疾"]], "11788": ["病机", "脉弦动，弦主肝旺，动主阳升，示肝胃气火内动，阳络受伤。原文谓“肝胃血泛，咯血屡发”“素有便血，脾脏亦伤，阴络亦损”，病经有年，阴阳二气已困，土不生金，金火相刑。此脉主肝胃火升、脾络两伤之上下失血，治当培中土。", ["弦", "动"]], "11789": ["病机", "脉芤数疾，芤主失血，数疾主热，合示阴虚络热，气火上炎。原文谓“轰然背热，血即泛出，足冷，督脉阳升上载血溢”，阳升于上则血溢，阳不达下则足冷；舌剥苔黄、溲赤皆热象。此脉主阴虚络热、气火升腾之失血，慎防狂溢，治以潜阳。", ["芤", "数", "疾"]], "11790": ["病机", "脉细弦，细主阴血不足，弦主肝郁气滞。原文谓“素有便血，今又痰血”，上下交病，阴血耗伤，肝失柔养，故脉细弦。此脉主阴血亏虚、肝郁络伤之上下失血证，治当求中，以培中土为要。", ["细", "弦"]], "11791": ["预后", "脉来疾而转指，全乏冲和之气，原文断为“阴极阳亢之脉，太刚必折”。久咳肺不生水，肾不纳气，元海无根，阴空气怯，故脉疾急无和缓之象。此脉主肺脾肾三脏皆虚、肾不纳气之喘脱危候，与不能偃卧、痰咸、便溏少纳相应，恐喘汗而脱。", ["疾"]], "11792": ["病机", "脉弦为肝木亢盛之象。本案肋痛失血由木火上载、血泛狂溢所致，血脱气空则肝阳化风旋动，头痛胸闷、少腹痛皆厥阴脉络所过之地。火气上逆扣金为咳、咽痒，脉弦便溏示肝病及肺脾。弦脉主肝郁火旺、风阳旋动，与诸症相应，故谓入损。", ["弦"]], "11793": ["病机", "原文未识脉名，纯述积虚之阴不复、累及于阳，阳亦随之而虚。畏寒肢冷为阳气之本亏，筋骨酸疼、手足屈伸不利乃营虚不养筋脉、脉络机关不束，病属气血大虚。此段从阴阳偏衰论病机，非以脉断，故脉象要素为空。", []], "11794": ["病机", "脉细虚弱为营卫二气交虚之象。质薄体虚、易于感冒，由阳不外卫、营不内充，故面色枯槁、形容憔悴、舌白液干。经云卫虚恶寒、营虚发热，营卫俱虚则寒热并作。细虚弱脉主气血阴阳俱损，四体百骸仅存虚气，故议复脉汤救阳和阴。", ["细", "虚", "弱"]], "11795": ["病机", "脉数疾为阴虚阳旺、虚火内炽之象。失血后阴亏阳亢，故肤热灼手；虚火上灼肺金则咳嗽侧眠；火耗脾阴则便溏。数疾脉主热盛阴伤，肺脾肾三脏皆虚，怯象大著，与肤热、咳、便溏诸症相应，示虚劳损途。", ["数", "疾"]], "11796": ["病机", "脉数为阴伤火旺之征。失血后咽痒、咳呛痰多，是气火上烁、搏激肺金之液与胃土之津皆化为痰。夜寐侧眠稍可已见脏阴先亏，寒热则营卫亦偏，便溏溺赤、舌质微黄皆阴虚火动。数脉主热，阴气已伤，损途可虑。", ["数"]], "11797": ["病机", "脉数为阴虚内热之象。失血后阴气大伤，则生肌热、形憔肉削、肌肤甲错；虚火灼肺则咳嗽，火耗脾土则便溏少纳，溺赤亦火动。数脉主热盛阴亏，肺、脾、肾、三焦俱病，劳瘵如此，与诸虚症相应，其何以堪。", ["数"]], "11798": ["病机", "脉细数为阴亏火旺之象。入幕肌肤灼热、夜来汗泄而解，乃阴虚内热、营卫不和；细为阴血不足，数为虚火内动。咳嗽痰多、气急少纳、便溏，示肺脾肾三阴皆虚。细数脉主虚劳阴伤，与诸症相应，故谓虚劳大著。", ["细", "数"]], "11799": ["病机", "脉数而疾为虚火内炽、阴亏阳亢之象。呼吸气粗由肺气亏而肾气虚，水亏不能上交心阳，故少寐惊悸；胃少纳谷则化源不足。数疾脉主热盛阴伤，劳怯何疑，与呼吸气粗、少寐惊悸、少纳诸症相应，示虚劳怯症。", ["数", "疾"]], "11800": ["病机", "脉数主热，此案肝胆相火直上直下，上则失血，下则遗泄，火动于内故脉数。咳呛为肺肾阴虚，劳怯之根，数脉示阳亢阴亏，火性急迫，与失血、遗泄、咳呛相应，说明相火不藏，阴精被灼。", ["数"]], "11801": ["预后", "失血后阴亏阳亢，脉数疾为阴虚火旺、虚热内迫之象。咳呛、潮热、便溏、舌光咽干，示肺脾肾三焦皆损，劳怯已成。数疾脉反映阴液枯竭、阳气独亢，故预言冬至一阳生时恐其增重，属预后判断。", ["数", "疾"]], "11802": ["病机", "脉数主热，此案阴虚火焰烁金，龙雷不静，精摇乎梦，故脉数。喉痹、咽干、音嘶、肌灼皆阴亏火旺、肺肾阴伤之候。数脉示虚火内炽，灼津耗液，劳怯难免，说明火动精摇、阴不制阳之病机。", ["数"]], "11803": ["病机", "失血后肺肾暗虚，金不生水，少火悉成壮火，消烁阴津，故脉数。口糜舌干咽痛、溲赤皆阴虚火旺之症。数脉示壮火内炽，阴气正涸，当春令阳气极升之时，阴愈亏而火愈旺，故拟甘凉生津、咸寒益肾以制阳光。", ["数"]], "11804": ["病机", "寒热延久，营卫气偏，卫疏阳微，阳为之虚，阴为之弱，故脉虚数。虚为气弱，数为阴亏，梦泄、盗汗更耗阴阳。此脉示正气已虚而虚热内扰，恐其因病入损，说明营卫不和、阴阳两虚之病机。", ["虚", "数"]], "11805": ["预后", "温邪寒热兼利下，阴气重伤，肛疡成溃，咳嗽多痰，脉来数疾。数疾为阴虚挟湿热、虚热急迫之象，阴伤而热不退，故恐其见血成劳。此脉示热灼阴津、湿蕴化燥，预后不良，属劳损之兆。", ["数", "疾"]], "11806": ["病机", "露秋燥气郁肺，咳呛络伤失血，脉沉数。沉为病在里，数为热，舌黄腻、泛水示阳明不和、脾弱不运，液化痰涎上泛。脉象阴虚，按证论脉，有入损之虑，说明肺胃燥热、脾虚痰泛而阴分已伤之病机。", ["沉", "数"]], "11807": ["预后", "痧后咳嗽，肌肤如烙，脉数疾，便溏黏腻，温邪兼凉秋燥蕴伏肺胃，延及一载。阴气为热气消烁，汗泄乎寐际，炎蒸金不敌火。数疾脉示热炽阴伤，童子痧劳，理之不易，属预后不良之判断。", ["数", "疾"]], "11808": ["病机", "脉来数疾，数主热，疾主急，示热邪内炽、阴液耗伤。原文谓风寒袭肺，久热阴伤，盗汗，胃气渐呆，肺脾肾三焦同病，因病成劳。数疾之脉反映热盛阴亏，虚火内扰，与潮热、盗汗、咳呛、泄泻相应，为劳损之象。", ["数", "疾"]], "11809": ["病机", "脉虚数疾，虚为阴亏，数疾为虚火亢盛。原文述失血复发，呛逆侧眠，潮热盗汗火升，嗌干，肺肾阴虚。虚数疾之脉示阴不制阳，虚火上炎，迫血妄行，与失血、潮热、盗汗相应，有入损之虑。", ["虚", "数", "疾"]], "11810": ["病机", "脉弦大，弦主肝病，大主虚阳外浮。原文谓肾虚气不收摄，动则气舞，咳逆，溲多，肝肾两亏。弦大之脉示肝肾阴虚，阳不潜藏，气逆于上，与咳逆、气舞、溲多相应，治以纳气归肾。", ["弦", "大"]], "11811": ["病机", "左寸独弦，左寸候心，弦主火郁。原文引《经》「一阴一阳结，谓之喉痹」，君相二火纽结上熏，咽痛红丝，日晡潮热。左寸独弦示金水两虚，虚不制火，火郁上焦，与喉痹、潮热相应，损怯之根已深。", ["弦"]], "11812": ["病机", "脉沉细，沉主里，细主阴血不足。原文谓金水两虚，虚不制火，火炎金伤，发为喉痹，红肿嗌干，日晡潮热，少寐。沉细之脉示阴气久耗，元阳不潜，虚火内郁，与喉痹、潮热、少寐相应，法当滋水制火。", ["沉", "细"]], "11813": ["病机", "脉滑而数，滑主痰湿，数主热。原文述久咳肺肾阴虚，咽痛三载，烦劳为甚，经事乍停乍止。滑数之脉示少阳相火上煽，痰热内蕴，与喉痹、咽痛、经事不调相应，病入损途。", ["滑", "数"]], "11814": ["病机", "脉细，细主阴血亏虚。原文谓一阴一阳结，木火上逆，炎上冲肺，喉痹红丝缕缕，肺失清肃，湿郁不化，内蒸生热，舌苔灰黄，溲赤。细脉示阴分不足，火郁湿蒸，与喉痹、溲赤、苔灰黄相应，先以轻扬清上。", ["细"]], "11815": ["病机", "脉虚数，虚为气阴不足，数主虚热。原文谓病起卒然，决非虚证，但咳嗽痰多，咽鸣喉痒，脉虚数，肺失清肃，阴乏上承。虚数之脉示肺阴亏虚，虚热内扰，与咳痰、咽鸣、喉痒相应，病情渐恐入怯。", ["虚", "数"]], "11816": ["病机", "原文引《灵枢》「寒气客于会厌，故卒然无音」，脉迟紧大为寒邪外束、肺气闭郁之象。迟主寒，紧主痛主寒凝，大示邪实壅盛。寒客会厌则声门不利而卒然失音，故以清扬开肺法宣散寒邪、开提肺气，脉症相合。", ["迟", "紧", "大"]], "11817": ["病机", "原文谓「风寒郁肺，饮酸，酸能收敛，咳嗽失音」，右寸候肺，脉迟细而涩，迟为寒，细为虚，涩主气滞血少、肺气不宣。风寒郁闭、酸收太过致肺金实而无声，故称「金实无声」，涩滞正示肺气壅塞不通。", ["迟", "细", "涩"]], "11818": ["病机", "阴虚体质复感风邪，先咽痛滋腐，继发疟疾，疟止而肌肤灼热、咳嗽咯白沫。脉软弦而数，软示阴气拖虚，弦主风邪未净，数主热。肺胃两伤、阴液亏耗，虚热内扰，故渐延至怯，法取清肃上焦以冀热止嗽缓。", ["软", "弦", "数"]], "11819": ["病机", "肺有宿饮遇寒即发，咳逆气冲、痰中带血，脉弦不得卧。弦主饮主气逆，不得卧乃气逆上冲、肺肾出纳失司之征。原文谓「肺主出气，肾主纳气，气不收摄」，故气冲为病，属肺肾子母同病，治先清上治标，次培其本。", ["弦"]], "11820": ["病机", "原文谓「脾为生痰之源，肺为聚痰之器，肾气上逆，痰亦随之而升」，味咸、腹中觉胀。脉细沉数，沉主里、细主虚、数主热，示肺脾肾三脏同病，肾气上逆挟痰上泛。细沉数正合下虚上实、痰随气升之机，故暂与泄降法。", ["细", "沉", "数"]], "11821": ["病机", "下虚上实、积饮哮喘咳嗽、痰咯白沫，脉迟。迟主寒，原文断为「寒饮蓄积所致」，寒饮内停、上实下虚，故咳喘痰沫。脉迟与寒饮病机相应，法宗生生子温化寒饮，标本兼顾。", ["迟"]], "11822": ["病机", "阳明积饮，肝木乘之，脘中痛、呕吐痰涎、三年频发。脉来迟滑，迟主中虚有寒，滑主痰饮内盛。原文断为「中虚。痰饮，肝胃不和也」，迟滑正示虚寒夹痰饮、肝胃气逆之机，与脘痛呕吐相应。", ["迟", "滑"]], "11823": ["病机", "中阳积饮，心悸、脘痛、漉漉有声，脉弦。弦主饮主痛，亦主肝木偏旺。中阳不足则饮停不化，水饮上凌则心悸，饮走肠间则漉漉有声，弦脉正应饮邪内结、阳气不运之机，故以刚药劫胃水法温燥逐饮。", ["弦"]], "11824": ["病机", "脉迟弦，迟主寒，弦主饮、主肝。寒饮积中，漉漉有声，呕苦吐酸，舌白，气从少腹上升，显系肝木犯胃、寒饮内停。脉迟为阳气不振，弦为肝气横逆，故病由肝胃，泄木通降为宜。", ["迟", "弦"]], "11825": ["病机", "脉细沉数，细为阴血不足，沉主里，数主虚热。吐血后咳呛、呕吐白沫、动则气舞，乃肺肾两虚、积饮在肺。细沉数示肺肾阴亏而虚热内扰，故治痰在肺、治虚在肾。", ["细", "沉", "数"]], "11826": ["病机", "脉象迟弦，迟为阳衰，弦为木旺饮聚。土败木戕，阳衰不振，饮积中阳，漉漉有声，少纳䐜胀，食入蒸变酸浊腐秽，下午为甚，便溏，一派阴霾浊聚。迟弦正合脾胃阳虚、肝木乘土、饮邪内结之机。", ["迟", "弦"]], "11827": ["病机", "刚药劫饮复阳，病减，脉弦已退，迟细仍然。弦退示饮邪渐化、肝木得平；迟细为久病阳衰阴亏之本质。少纳䐜胀、漉漉有声，入暮阴甚时增剧，乃饮邪属阴、阴与阴合，故仍当通阳蠲饮、振复坤阳。", ["弦", "迟", "细"]], "11828": ["病机", "脉象见数，数为热，主肺气壅热。痰哮遇寒遇热皆发，痰鸣喘迫，肺为娇脏，寒热皆畏。数脉示痰热内郁、肺失清肃，故法当苦以降之、辛以泄之，以调肺气之壅逆。", ["数"]], "11829": ["病机", "脉迟虚细，迟为阳虚，虚细为气血不足。哮喘五年，越发越勤，发则寒热汗不解，喘渐除，显系风寒蕴伏肺底、正气已虚。迟虚细示本虚而邪伏，故宜先撤风寒，然后培补，如逐贼关门。", ["迟", "虚", "细"]], "11830": ["病机", "诊脉迟而弦劲，迟为阳虚，弦劲为邪伏搏结、肝肺气逆。哮喘五年，发时寒热，风寒伏于肺底不得宣达。弦劲示邪未撤而正气尚能抗争，若遽补之则反致邪蕴，故宜搜剔其邪以治病本。", ["迟", "弦", "劲"]], "11831": ["病机", "诊脉迟弦，迟主脾肾阳虚，弦主水饮内停。肾为胃关，关门不利，聚水而从其类，一身悉肿，便溏溲少，口干纳少，䐜胀，皆脾肾阳虚、湿困水气横溢肌肉之候。脉迟弦正合阳虚水泛，慎防喘逆。", ["迟", "弦"]], "11832": ["病机", "脉沉数，沉主里、数主热，合脾虚水谷之湿阻遏气机、湿蒸化热之机。湿郁化热氤氲伤脾，故筋青脐突、溲少便溏；土虚不能敌木，木火上冲犯肺而干呛。脉沉数正示湿热内蕴于里，与脾伤木亢之症相应，故治脾求本。", ["沉", "数"]], "11833": ["病机", "脉象迟弦，迟主湿阻阳郁、弦主木旺水停。脾胃湿热蕴蒸发黄，脾伤不运，水气不得下行，故腹大䐜胀、囊肿、小便涓滴、大便闭塞，水气流溢肌肉而一身悉肿。迟弦合见，示湿热壅遏、气化不利，故议开太阳一法以分清湿热。", ["迟", "弦"]], "11834": ["预后", "脉象沉细无神，沉细为阳气衰微、无神则胃气将绝。昔年三疟不忌荤腥，脾阳日困，湿痰瘀血结于腹左成肿满，放水三次而腹大依然、杳不思谷，脾胃生阳已败。脉沉细无神正应此阳败之候，故属难治，勉拟以慰望治。", ["沉", "细"]], "11835": ["病机", "脉虚弦，虚为正气不足、弦为水气未靖。开太阳小便得利、益肾阳水气渐消之后，脉见虚弦，示邪退而正未复、水气尚有余弦象。前法既合，故无庸更张，仍守开太阳益肾阳以竟其功，脉症相应。", ["虚", "弦"]], "11836": ["病机", "脉数主热，暑湿热浑蒸中阳，脾不化湿，水气逆趋肌肉，故自下肿上、囊大；舌红咽闷、咳嗽，示湿热蔓延三焦气分。脉数正应暑热内蒸之机，热势鸱张易内陷，故慎防厥逆，为病机与预后兼顾之论。", ["数"]], "11837": ["主病", "脉弦数，弦主木旺气结、数主热。暴腹胀大皆属于热，脾湿内蕴蕴蒸不化，腹胀溲赤便艰，脉弦数正合湿热壅结、肝木乘脾之机。臌胀已成，脉症相符，示湿热内蕴、气机壅塞之病。", ["弦", "数"]], "11838": ["病机", "脉弦主肝木乘脾。脾阳湿困，肝木乘之，故单腹胀大、脐突、背平、青筋已起，皆木旺克土、气血壅滞之象。脉弦独见，正示肝强脾弱、湿困阳微之病机，症已深重，故云理之不易。", ["弦"]], "11839": ["病机", "脉沉主里、主水气内停。肿胀久延，一身悉肿、小便不利，水气泛溢逆趋肌肉，气化不利，故脉见沉。沉脉应水湿内壅、阳气不化之机，症情缠绵，故云理之不易，示水气内盛而气化失司。", ["沉"]], "11840": ["病机", "脉数主热，此案水气不能下输膀胱，气化不宣，水湿内停而化热，故脉数。症见从下肿上、阴囊甚、小便不利、大便艰涩、咳呛、口渴，皆水热互结、气化失司之象。脉数与口渴并见，说明水停而热生，非单纯寒水，故曰不易理。", ["数"]], "11841": ["病机", "脉弦主水饮、主肝，数主热。风水为病，风邪袭表，肺失宣降，水气泛溢，故从上肿下、囊下为甚、便溏溲少。弦数并见，示风邪与水湿相搏，郁而化热，病势急，故曰勿轻视之。", ["弦", "数"]], "11842": ["病机", "脉沉弦细，沉主里主水，弦主饮主痛，细主虚。肿胀咳逆不得卧、气促溺少胸闷腹膨，乃肺风脾湿逆走肉里，水气内停，肺失肃降，脾失健运，肿胀已成之候。脉沉弦细正合水湿内盛、正气已伤之机。", ["沉", "弦", "细"]], "11843": ["病机", "脉沉数，沉主里，数主热。喘急稍平而不能右眠，肺气不降；小便稍利、大便溏薄，湿有下行之势；恶风、面部肿势依然，风邪未净。脉沉数示水湿内郁化热，肺气壅塞，故当实肝泄肺，以复肃降。", ["沉", "数"]], "11844": ["病机", "脉数实，数主热，实主邪盛。外疡未愈又感风邪，与内蕴之湿相搏，风袭于肺、湿伏于脾，致足浮囊大、身热咳嗽气逆、便溏溲赤。脉数实说明风、湿、热邪壅盛于表里，为水肿病之实候。", ["数", "实"]], "11845": ["病机", "脉数主热，风水一身悉肿、咳嗽恶风胸闷气急，乃风邪袭肺，肺失宣降，水气泛溢肌肤。病在肾本肺标，脉数示风邪郁而化热，水热互结，表里同病，故理之不易。", ["数"]], "11846": ["病机", "脉弦细，弦主肝主痛主饮，细主虚主积。昔年失血，腹满气胀，左右腹结癖，腹胀痛，曾下黑粪瘀血，系肝脾瘀凝、痰湿鸠聚互结。脉弦细正合瘀血内结、脾虚湿聚之机，病已有年，根深蒂固，恐成单腹血臌。", ["弦", "细"]], "11847": ["病机", "脉弦细，弦主饮主痛，细主虚。进温通疏补后中脘满势渐平、痛减，而䐜胀仍然，脉仍弦细，说明脾湿日踞、阻塞中焦，流运之机痞塞，升降不利，干运之阳不振。脉弦细示湿浊未化、阳气未复，必得阳通浊泄，痞气渐消。", ["弦", "细"]], "11848": ["病机", "脉弦滞而软，弦为肝郁，滞主气机不畅，软示脾虚不运。原文谓“肝之气不疏泄，脾之气不健运，肝脾两郁而不行”，致浊痹阳不通，脘中结痞胀痛，便溏。此脉象反映肝脾两郁、浊痹内阻之病机，主痞胀便溏，与“坚者削之”后痞气已消之佳兆相应。", ["弦", "滞", "软"]], "11849": ["病机", "脉沉迟弦，沉主里，迟主寒，弦主水饮。原文谓“脾阳不运，水湿无以运行，真阳火衰”，致腹满、背平、脐突、气急、囊肿、便溏、溺赤。此脉象说明脾肾阳虚、水湿泛滥之病机，主肿胀重证，与真阳火衰、水气太过相应，故曰“不易理”。", ["沉", "迟", "弦"]], "11850": ["病机", "脉细软滑，细软主虚，滑主湿。原文谓“三阴久疟伤肝”，肝伤运行失常，中焦湿渍不化，溢于肌肉为浮肿，朝宽暮急，病在营分。此脉象反映脾胃阳湿困阻、营血随病而虚之病机，主浮肿、便溏、寒热休作，与舌白浊、喜热饮相应，病情棘手。", ["细", "软", "滑"]], "11851": ["病机", "脉数心悸，数主热，亦主虚。原文谓“无形湿热困中，中虚脾不健运”，致少纳、胀满、大便溏结不定。此脉象说明湿热内困、中焦升降失常之病机，主肿满之象，与心悸相应，故仿朱丹溪法以调中化湿。", ["数"]], "11852": ["病机", "脉弦长不和，弦为肝旺，长为气有余。原文谓“条畅肝脾，依然腹满”，脉象弦长不和，断为“木旺土衰无疑”。此脉象反映肝木亢盛、克伐脾土之病机，主腹满，每晨必便、便后腹松，说明不但脾病，腑亦病矣。", ["弦", "长"]], "11853": ["病机", "脉数，数主热。原文谓“湿热肠红腹痛，澼澼不爽，紫赤兼行”，病经年余而饮食如常，非不足之症。此脉象说明湿热交逼、血渗下行之病机，主肠红腹痛，与紫赤兼行、澼澼不爽相应，为实证非虚。", ["数"]], "11854": ["病机", "脉弦，弦主肝郁湿阻。原文谓“暑湿风浑蒸中焦”，身热之下触发便血，腹鸣且痛，初淡后鲜红，乃“脾虚、营血为湿所逼迫而下渗”。此脉象反映脾阳呆钝、营血为湿迫下渗之病机，主便血腹痛，与口干舌白相应，法以养营化湿。", ["弦"]], "11855": ["病机", "脉弦，弦主肝病。原文谓“脾不统血，肝不藏血”，血液下渗而为肠红，或紫或鲜，其色不一。此脉象说明肝脾两伤、血失统藏之病机，主肠红下血，与脾不统、肝不藏相应，法以引血归经。", ["弦"]], "11856": ["主病", "脉弦为肝木之象，本案便血红紫不定、腹鸣痛、脱肛、疝气，皆肝失疏泄、脾不统血之候。弦脉主痛、主肝病，肝气横逆则腹痛肠鸣，脾虚气陷则脱肛，湿热下注则便血。治从肝脾，正合弦脉所主之肝脾不和病机。", ["弦"]], "11857": ["病机", "脉虚数，虚为营阴亏耗、脾损不运，数为阴不制阳、虚热内生。便血六年，营虚脾损，血紫舌光红，少纳溲赤，皆虚数脉所主之阴血不足、湿热内郁。面肿足浮、寒热似疟，乃伏邪乘虚而发，脉虚数正示正虚邪伏之机。", ["虚", "数"]], "11858": ["病机", "脉象虚弦，虚为肾精亏虚、下元不固，弦为肝失濡养、筋脉拘急。无梦遗泄属肾虚，腰臂酸痛乃精亏络空。虚弦并见，示肾虚肝郁、精关不固之病机，故治法不外固其精关，兼以柔肝养筋。", ["虚", "弦"]], "11859": ["病机", "脉象数大而疾，数主热，大主虚阳外浮，疾为阴火奔迫。本案心君一动相火随之，肾阴耗而阴火上炽铄金，咳痰壅肺，土衰便溏，厥阳化风上旋，头眩耳鸣。数大而疾正示阴火虚阳上逆，舌碎红裂纹为佐，病本在肾，他脏皆末。", ["数", "大", "疾"]], "11860": ["病机", "原文未识脉名，然述先天不足、肾阳暗亏、气不收摄，致小便淋滴、寐则遗尿。此乃肾阳亏虚、膀胱不约、督脉不升之病机。阳不化气则水液失摄，阴亏阳虚并见，故宜温补肾阳兼升督脉，以复气化收摄之职。", []], "11861": ["病机", "脉数为内热之征，本案先天禀赋质薄，内热遗尿，数脉示阴虚生内热、热扰膀胱而失约。遗尿虽多属虚寒，此则因内热逼津，故脉数。治以养阴固摄，清内热以复膀胱约束之能，脉数正是阴虚内热之凭。", ["数"]], "11862": ["病机", "脉象数疾，数主热，疾为热盛急迫。本案素体阴虚湿热，遗泄转甚，阳强不痿，病名强中，乃阳明湿热下流、阴精耗而阳火随之。数疾脉示湿热内蕴、虚中夹实，口燥盗汗足软为佐。阴精虽虚，湿热未化，故治当益气固精、通不固下。", ["数", "疾"]], "11863": ["病机", "脉来细数，细为阴精亏耗、脉道不充，数为相火内动、虚热扰精。少壮情念萌动，心君一动相火随之，精浊茎痛，正合细数脉所主之阴虚火旺、精室被扰。病情恐从露行蔓草而来，示湿热下注、精浊久延之虑。", ["细", "数"]], "11864": ["病机", "脉数主君相火煽惑，火动则精室不宁，梦泻后败精转浊，瘀浊阻窍而溺管痛楚。数脉在此非单纯表热，而是火邪内扰、精浊互结之象，故通利不效，须虎杖散直入血分以散瘀浊，火清则数脉自平。", ["数"]], "11865": ["病机", "脉数示湿热无形之邪下注阴分，久延十载，淋浊梦泄不止，溺滴茎管肿痛。数脉为湿热郁蒸、精关被扰之征，原文谓“涩愈甚精愈虚”，说明湿热久羁耗伤阴精，故取生生子法清渗湿热兼固精。", ["数"]], "11866": ["病机", "脉弦主肝郁气滞、败精阻窍。淋浊复发、茎管中痛、腰酸、水液浑浊，皆败精未清、气机不畅所致。弦为郁象，非虚象，故原文强调“法当宣通为主，无因虚而止涩”，以通利驱浊使弦脉得缓。", ["弦"]], "11867": ["病机", "脉沉弦数，沉主里，弦主肝火，数主火燔。离火下吸阴精转为赤浊，茎管溺痛，是君相火燔、心肾阴伤之候。火迫精室则浊赤，火灼溺窍则痛，故治当复心肾之阴，阴复火降则沉弦数渐和。", ["沉", "弦", "数"]], "11868": ["病机", "脉弦主气滞浊阻。触秽败精转浊，茎管痛、溺涩，皆秽浊壅塞窍道、气机不利之象。弦脉应肝，肝主疏泄，浊阻则疏泄失职，故以通利方法驱秽，浊去气通则弦脉自解，非虚证可补。", ["弦"]], "11869": ["病机", "脉弦数主肝逆火旺。素有肝逆，疏泄太过，精淋随努挣而淋滴，是肝火迫精下泄、气陷不固。原文谓“病在肝肾，久淋久浊皆属气陷”，弦数为肝火疏泄太过之征，非仅精关不固，故治在肝肾。", ["弦", "数"]], "11870": ["病机", "脉细主阴液亏耗。下白物如脂、小腹痛属膏淋，腰痛体酸、头疼且眩，是阴液消耗、阳气上冒之候。细脉为阴血不足、脉道不充之象，阴虚阳浮故眩冒，议潜阳摄阴，使阴复阳潜则细脉可充。", ["细"]], "11871": ["病机", "脉数主湿热未清。先血淋后膏淋，瘀块继下白物如脂膏，腹痛，是肝肾阴亏而湿热留恋。数脉为湿热郁蒸、阴亏火动之征，阴亏则脉数无力，湿热则数而兼滞，故清湿热兼养肝肾之阴。", ["数"]], "11872": ["病机", "脉数主君相二火不靖，阴气自虚。膏淋久延，精关不固，海底胀痛，腰痛溲多，皆精空气急、阴亏火旺之象。数脉为热，热扰精室则淋浊不止，火灼阴络则腰痛，故治以益阴清火，佐滑涩以固下通利。", ["数"]], "11873": ["病机", "原文仅言“脉滞”，未出具体脉名，故脉象要素为空。湿火下注，淋滴带浊带血，茎中痛，脉滞示湿热壅遏、气血不畅。湿热蕴结下焦，灼伤血络则带血，阻滞气机则茎痛，久则恐成癃闭，故以通利为治。", []], "11874": ["病机", "脉弦主阴气已空，肝失柔养。血淋两月不愈，溺塞而赤，腰酸，乃胞移热于膀胱，灼伤血络。弦为肝脉，阴亏则弦劲不柔，热结下焦则溺赤塞痛。宗猪苓汤从阴化以清热利水，冀血止而阴复。", ["弦"]], "11875": ["病机", "脉数主湿热化火伤营。胞移热于膀胱，则溺血精淋，茎管中痛，舌白示湿未化燥。酒客湿热内蕴，年逾古稀营阴已亏，数脉为火烁营阴之征，故不可渺视，当清湿热兼顾营阴。", ["数"]], "11876": ["病机", "脉数主膀胱湿热内蒸肝经，相火煽烁。湿热瘀腐化虫，小便混浊，溲出长虫，舌白示湿浊未清。数脉为热，湿热蒸变则生虫蚀，故当清理湿热，湿热去则虫自消。", ["数"]], "11877": ["病机", "脉象弦数，弦主肝火，数主湿热。火腑湿热下流膀胱，蒸变生虫，形如疳蚀，溲液混浊。弦为肝经相火煽烁，数为湿热蒸腾，故再以清湿分利，使湿热分消则虫蚀自愈。", ["弦", "数"]], "11878": ["病机", "原文未出脉象，故脉象要素为空。冲为血海，经行则诸经之血交会而下。经行骨节酸痛、趱前、色紫，属营虚伏热。营虚则骨节失养而酸痛，伏热迫血则经行趱前色紫，法当和营清热，佐理气以调冲脉。", []], "11879": ["病机", "脉滑数主营分有热，肝风煽络，挟痰所致。先起指麻，后筋脉掣痛，眩晕䐜胀，经事趱前。滑为痰，数为热，肝风挟痰热上扰则眩晕，窜络则掣痛，迫血则经行趱前，故病属营热风痰。", ["滑", "数"]], "11880": ["病机", "原文未明确脉名，仅言“脉见外刚内柔”，指脉象外显刚劲而内里柔缓，反映肝风上旋、心阴虚而神机失职之病机。厥后不语神呆、心中模糊、嘻嘻而笑，非邪陷心包，乃阴液乏上承、湿热无形之气未化，故舍标治本，先补后泻。", []], "11881": ["病机", "脉弦急为肝脉本象，弦主气滞，急主拘挛。经来一日即止，瘀凝未尽，少腹结瘕攻痛，呕吐酸水，胸闷，皆厥阴气不疏泄、肝木横逆之候。气滞血瘀，病甚防厥，故脉弦急提示肝气郁滞、瘀阻络脉之病机。", ["弦", "急"]], "11882": ["病机", "脉数疾主热盛阴亏。湿热伤脾，腹胀而饮食虽旺，经事不行，乃脾为湿困、生化之源已衰，营气虚而经闭。数疾之脉示阴气亏而热郁于里，故以清热养阴为治，脉象与阴亏内热之病机相应。", ["数", "疾"]], "11883": ["病机", "脉小滑，小主营虚阴亏，滑主内热或血结。经事后期腹痛、紫黑成块，腰酸背胀，足软筋掣，五心燔灼，皆肝脾血虚、营阴内亏、虚热内生之候。脉小滑正合营虚阴亏、内热之病机，故以胶艾汤法养血滋阴。", ["小", "滑"]], "11884": ["病机", "脉弦数，弦主气滞，数主热。经阻七月，食则䐜胀，腹满足浮，睡则腹足皆瘪，舌白，乃气阴两虚、湿热中阻、气机壅滞之候。弦数示湿热郁于里而气机不畅，故治以理气化湿和营，脉象与湿热中阻病机相应。", ["弦", "数"]], "11885": ["病机", "脉迟细，迟主寒，细主虚。经来受寒，寒客胞宫，气血凝滞，故腹痛。迟细之脉示阳气不足、寒凝血脉，与经来受寒、腹痛之症相应，病机为寒凝血滞、营血亏虚。", ["迟", "细"]], "11886": ["病机", "脉涩而速，涩主血瘀气滞，速即数，主热。营虚气滞，经阻，胃减，少腹痛，手足入暮烦热，阴气自虚，脾胃生阳不振，痰气流溢结于颊车。涩数之脉示营虚血滞、阴亏内热，与调气养阴之治相应。", ["涩", "数"]], "11887": ["病机", "左关弦滞，弦主肝郁，滞主气机不畅。肝木气滞不行，气为血帅，气滞则血瘀，瘀凝肝络，左胁下结聚有形，时时作痛，腹亦痛，室女经阻一载未行。近又恶心吐涎沫，厥阴寒浊上逆犯胃。脉象示肝留有凝瘀、气不宣泄之病机。", ["弦", "滞"]], "11888": ["病机", "脉来数疾，数主热，疾主虚，此脉见于淋带绵延一载，气阴久耗，八脉不司约制。阴虚湿热蕴伏，故脉数疾；久病入怯，阴亏气弱，虚热内扰，故脉来急疾。腰臂尻骨皆痛，乃八脉失养，湿热流注。脉症合参，病机为阴虚湿热，久延入损。", ["数", "疾"]], "11889": ["病机", "脉虚弦，虚为气血不足，弦为肝郁或痛。八脉𫏋维少护，腰酸带下，胫骨酸痛，乃下焦肝肾亏虚，奇经失养，虚而兼郁，故脉虚弦。虚主不足，弦主拘急，反映下焦固摄无权，筋脉失濡。治以固摄下焦，正合虚弦之脉。", ["虚", "弦"]], "11890": ["病机", "脉空虚，主气血亏虚。带下有年，腰骨节酸痛，下焦肝肾两虚，湿热留著，两足浮肿，小便频频，八脉空虚，阴亏气弱。脉空虚乃精血不足、奇经失充之象，虚而兼湿，故浮肿朝退夕甚。收摄下焦，针对空虚之脉而设。", ["空", "虚"]], "11891": ["病机", "脉涩数，涩主营血涩滞，数主热。经来腹痛，气滞营涩，带下，经行寒热，气营不和。涩为血少气滞，数为热郁，营涩则经行不畅而痛，气滞则寒热交作。脉症相合，病机在气营不和，血涩有热，冲任失调。", ["涩", "数"]], "11892": ["病机", "原文未识脉名，然述经事参差、色淡且少，营虚明征；带下腰酸，妨纳䐜胀，乃冲任不调，血虚气衰。冲脉隶阳明，脾胃为生化之源，营气所出。病机重在营虚气衰，冲任失养，中宫不运，故先治中宫以培生化。", []], "11893": ["病机", "未识脉名，述经来色淡，营虚何疑；䐜胀胃呆，腰酸带下，冲任督带奇经皆病。冲脉隶胃，胃为水谷之海，营卫所出。胃旺则气充，气旺则血长。病机为营虚气衰，奇经俱病，而根在胃弱，故仍注意于胃。", []], "11894": ["病机", "脉数阴虚，数主热，阴虚则内热。经事不调，常常趱前，腰酸带下，咳嗽痰中挟血，木火上扣金鸣，金受火刑。脉数乃阴虚火旺之征，八脉冲带为病。木火刑金，故咳血；阴虚阳扰，故经先期。著紧调治，免入损途。", ["数"]], "11895": ["病机", "脉数，主热。带脉不固，阴伤湿热内郁，带下腥秽，腰酸眩晕，心悸，肤热，胃呆。阴虚生内热，湿热郁蒸，故脉数肤热；带下腥秽乃湿热下注；眩晕心悸为阴亏阳浮。肝胃阴虚，咸苦坚阴，针对脉数阴虚湿热之机。", ["数"]], "11896": ["病机", "脉数疾为阴虚火旺之象，阴精亏虚，虚火内扰，故脉行急迫。本案经行紫色已止，带下、少腹胀、胃呆，乃阴虚挟湿，带脉不固，冲任失约。数疾之脉反映内热与阴伤并存，火动则血行失常，湿注则带下不止，故以通补奇经为治。", ["数", "疾"]], "11897": ["病机", "脉沉弦数，沉主里，弦主肝，数主火。肝肾阴虚，阴精为火所吸，虚火内炽，故脉沉弦而数。赤带、腰酸、心悸，皆阴亏火旺、下焦不固之候。弦为肝旺，数为火迫，沉为病在里，合示阴虚火动、下焦失摄之机。", ["沉", "弦", "数"]], "11898": ["病机", "原文未识脉名，然述湿困伤脾、脾不统血、湿邪迫血下行、冲脉气不收摄，致经淋两月、带下、心悸眩晕耳鸣、腹大足浮、胃呆䐜胀。病属肝胃，湿浊内蕴，脾失统摄，冲脉不固，血不归经，故以引血归经为治。", []], "11899": ["病机", "原文未识脉名，述经淋虽止而营阴过虚，浮阳上扰，头眩耳鸣心悸，带脉不固，带下频多。此营阴亏虚于下，浮阳逆扰于上，带脉失约，故治宜养阴固摄下焦，使阴复阳潜，带脉自固。", []], "11900": ["病机", "脉沉细涩，沉主里，细主阴血不足，涩主气滞血涩。冲任不调，气滞血涩，经来带下腹痛，乃气血运行不畅，冲任失和。沉细为阴血亏少，涩为血行迟滞，合示气营两滞、冲任失调之病机。", ["沉", "细", "涩"]], "11901": ["病机", "脉数主热，本案露秋崩冲，所下黄水臭秽而腥，淋滴溺涩，少腹痛，内热胃呆，乃肝胃湿热内蕴，误投温补温涩，致湿热壅滞，黄水淋沥延久。数脉为湿热内蒸之征，故宜清宜通，使湿热去而淋通。", ["数"]], "11902": ["病机", "脉滑数，滑主痰湿，数主热。肝阳上逆，心宕，即时头痛，体酸腰痛，带下，动则气逆，乃肝肾两虚，阳亢于上，湿热下注。滑数为阳热挟湿之象，故见头痛带下，动则气逆，虚实夹杂。", ["滑", "数"]], "11903": ["病机", "脉象数疾，为阴气已亏之征。三阴不足，心不生血，肝不藏血，脾不统血，冲脉失约，遂为经崩。崩后神色俱夺，头痛眩晕心悸耳鸣，营阴内亏，阳气逆升；腹胀食下䐜胀足肿便溏，脾阳不振。数疾示阴亏阳扰，故从阴引阳，佐转坤土。", ["数", "疾"]], "11904": ["病机", "脉迟细涩，迟为阳衰，细为血少，涩为血瘀。经停三月后崩冲瘀块如拳，下五六枚，乃瘀血内阻，血不归经。腹痛自汗面青，肝无藏血，血去过多则气随血脱，慎防阳升厥逆。此脉主肝血亏虚兼瘀滞，与崩冲、面青、自汗相应。", ["迟", "细", "涩"]], "11905": ["病机", "脉数主热，营分伏热，经来骤崩，色紫瘀块杂下，头痛眩晕耳鸣腰痛，皆热迫冲任、肝胃气虚所致。数脉为热邪内伏，冲任不调，血热妄行。此脉主肝胃气虚、冲任不调之崩漏，与紫块、头痛眩晕等症相应。", ["数"]], "11906": ["病机", "原文未出脉象，以症测机。肥人多湿多痰，茹素中虚气馁，脾失统血，胃气衰弱，冲脉不司约制，经崩直下，血脱气空，气随升逆，肝失营养，阳化风挟冲气直升为卒厥。耳鸣头眩自汗心宕，少腹痛便泄腰痛不寐，皆营虚气弱。深恐土不制水而为水肿。", []], "11907": ["病机", "脉沉细，沉为在里，细为血虚。经停五月，积瘀崩冲，紫块杂下，乃瘀血内积，冲任不调，血不循经。沉细脉主里虚兼瘀，与积瘀崩冲、紫块相应。以和营法调治，旨在化瘀和营。", ["沉", "细"]], "11908": ["病机", "脉细虚弱，细为血少，虚为气亏，弱为阳衰。年交花甲，经事崩冲连行数次，血去过多，气亦随虚，神疲心宕，眩晕耳鸣，彻夜不寐，一派气阴两虚、三阴交亏气象。此脉主气血两虚，与崩冲后神疲不寐等症相应。", ["细", "虚", "弱"]], "11909": ["病机", "原文未出脉象，以症测机。经停月余而崩冲淋漓不尽，腹痛，冲脉不司约束。冲脉隶乎阳明，阳明主束筋骨利机关，营虚则不仁，卫虚则不用，不仁不用而诸节皆痛。此属营卫俱虚，冲任不固，与崩漏、腹痛、诸节痛相应。", []], "11910": ["病机", "脉细沉数，细为阴伤，沉为在里，数为有热。经崩后溺痛，小便淋滴，近又经行紫色，乃肝经郁热下迫，热灼阴络。细沉数脉主里热伤阴，与溺痛淋滴、经行紫色相应。治以泄化肝经郁热。", ["细", "沉", "数"]], "11911": ["病机", "脉来弦数而涩，弦为肝旺，数为热，涩为血滞。重身努力负重，胎元受伤，少腹痛脘痛引胁背，胎气下坠，身热头痛脘闷舌白口干，此伏邪为病，邪热内迫，气血壅滞。弦数涩脉主伏邪化热、胎气受损，深虑邪迫胎元致小产。", ["弦", "数", "涩"]], "11912": ["妇人", "本案屡屡小产，八脉无有不损，此次怀娠又忽腹痛坠下、带多如崩，委中环跳酸痛，显系奇经八脉亏损、不能担任固摄，故见小产之象。原文未出脉名，仅言八脉无有不损，病机为冲任带脉虚损，急宜固胎。", []], "11913": ["妇人", "经阻三月，脉来动滑、停、匀，动滑为妊娠之常脉，故曰的是毓鳞之兆。然呕吐苦水痰涎、心下悸，乃饮停中脘，少阳木火相激上逆使然。脉动滑主胎，兼症则主饮停，当与驱饮。", ["动", "滑"]], "11914": ["妇人", "怀孕七月带脉不固，带下如崩，气怯，此奇经为病也。带脉失约则带下如崩，气怯为元气不足，若带不止则偏产堪虞。原文未出脉名，病机为奇经带脉虚损不固，法以养阴固摄。", []], "11915": ["妇人", "妊娠六月时常腹痛、胎动，气滞不和，脉右大。右大主气分壅滞，气机不和则胎动腹痛，故以安胎理气为要。脉右大在此非实热，乃气滞之象，与胎动腹痛相应。", ["大"]], "11916": ["妇人", "重身滞下色白，脉迟弦，胸闷纳少。迟为寒、弦主气滞，寒湿滞下伤及脾胃，气机不畅故胸闷纳少。恐利下伤阴，以致偏产。脉迟弦主寒湿气滞，与滞下色白、胸闷纳少相应。", ["迟", "弦"]], "11917": ["病机", "产后八脉交虚之际，适感寒邪致形寒身热，又早食荤腥致脘痛而胀、积聚成块，得食更甚。乃气血大虚之时与食滞瘀凝互结，阻于脾胃之络。脉交虚之际点明正虚，坚者削之佐和养营分，恐成膨胀。", ["虚"]], "11918": ["病机", "产后三朝身热头痛、恶露不下，得汗热减而脉象洪大，眩晕耳鸣、时有谵语、神不守舍、少腹胀、大便溏泄。洪大为营阴大夺、虚阳外浮之象，兼脾湿不化，病情虚实互见，带脉不固，腹痛带下。", ["洪", "大"]], "11919": ["病机", "产后恶露不通，三朝即止，继则神昏狂乱，少腹结块疼痛，痛连环跳，寒热咳嗽胸闷。脉弦数，弦主肝郁、数主热，乃瘀凝阻于肝脉，扰乱神明，蓄血如狂。法当通瘀，块消瘀下方可无虞。", ["弦", "数"]], "11920": ["病机", "脉来弦带数，弦主肝郁气滞，数主热。产后瘀凝未尽，流注肝经，肝气不舒则脉弦，瘀热内蕴则脉数。瘀阻少腹故痛，肝热下迫则小便赤，腑气不通则大便闭，瘀热上扰神明则狂诟不避亲疏。此脉象反映瘀热互结、肝经郁滞之病机。", ["弦", "数"]], "11921": ["预后", "脉亦散乱，散乱为气血耗散、阴阳离决之象。产后血崩如崩，去血过多，气随血脱，血晕不省人事，口噤风痉，频频昏厥，汗脱可危。脉散乱提示正气涣散，不能收摄，与汗脱昏厥相应，属危重预后。", ["散", "乱"]], "11922": ["病机", "脉数尺弱，数主虚热，尺弱主下元亏虚。产后暴虚，风阳上冒，下虚少收摄之权，故瘀块如崩、气逆上升、厥逆若痉、神志模糊。尺弱为肾虚不摄，数脉为虚阳浮动，深虑厥汗而脱，此脉象揭示下虚上实、阴阳不相维系之病机。", ["数", "弱"]], "11923": ["病机", "脉数，营阴大夺，风阳煽动逆升，头痛眩晕心悸耳鸣，皆属虚象。数脉在此非实热，乃阴血亏虚、阳气浮越之征。产后血去过多，阴不敛阳，虚阳上扰清空，故见诸症。脉数与虚象相应，说明病机为营虚阳浮。", ["数"]], "11924": ["病机", "脉细数，按之濡。细主阴血亏少，数主虚热，濡主气虚。新产营血下夺，血去阳升，头痛眩晕身热蒸灼，皆暴虚之象。细数而濡，说明营血虚于内，阳气浮于外，按之濡软为正气不足，法当镇纳空隙使阳静阴闭。", ["细", "数", "濡"]], "11925": ["病机", "脉弦细，弦主肝郁风动，细主营血虚少。产后营虚，风热上郁清空，耳窍流脓且胀，心宕头眩。营虚则脉细，风热上扰则脉弦，此脉象反映产后营血不足、风热上郁之病机，与耳窍流脓、头眩心悸相应。", ["弦", "细"]], "11926": ["病机", "脉洪数，洪主热盛气壅，数主热。产后营虚，惊则气乱，血郁于上，肝气自动与阳气相并，逆升致痉厥咬牙、自汗淋漓、头晕耳鸣心悸。洪数为虚阳上逆、气血并走于上之象，非实火，乃营虚肝风挟阳上扰之病机。", ["洪", "数"]], "11927": ["预后", "脉缓虚，缓为胃气渐和，虚为正气未复。产后败血冲心、肝风上扰之后，神志昏愦彻夜不寐，经交阴和阳镇摄，欲寐不寐热解，脉转缓虚。此阳气欲交于阴，病势向愈，缓虚之脉与佳境相应，属预后良好之征。", ["缓", "虚"]], "11928": ["病机", "左寸细弱，左关虚弦。产后营血亏虚，肝失濡养，肝风上冒，故见耳鸣、心宕、眩晕；神不守舍，神志稍清。细弱主营虚，虚弦为肝风内动之象，病机为产后营虚、肝风上扰。", ["细", "弱", "虚", "弦"]], "11929": ["病机", "脉数大，身热，恶露色淡且少，汗多口渴。产后营虚气弱，阴弱不振，膀胱素有积热与瘀相搏，水气相凝，故便难、小便不利。数大为营虚有热之象，非实热，故曰营虚何疑。", ["数", "大"]], "11930": ["病机", "未载脉象。产后营阴两虚，维𫏋少护，腰腹腿膝酸痛，形寒身热。病机为营阴亏虚，奇经失养，治从八脉。", []], "11931": ["病机", "脉数，身热，头疼胸闷，舌灰黄白，口渴且腻，体疼腹痛泄泻，阴脱，玉门不闭，恶露稀少。产后气营两虚，湿邪内蕴，虚实皆见。数脉主热，亦主虚，此营虚而湿热内郁，正虚邪恋。", ["数"]], "11932": ["病机", "脉弦，腹左旁痛，便泄澼澼不爽，舌灰已化，少纳。寒热之邪郁于肠胃，不得宣达，气机不畅，故脉弦主痛、主郁。法当温通疏泄，以解肠胃郁滞。", ["弦"]], "11933": ["病机", "脉浮洪数，按之细涩。产后营虚大夺，外感暑湿风邪因虚不达，内蕴气血精华随利而虚。浮洪数为表邪未解、虚阳外浮；按之细涩为营阴内亏。形浮舌光，口碎拒纳，咳呛形寒，病情棘手。", ["浮", "洪", "数", "细"]], "11934": ["病机", "脉浮数，按之细弱。下利五色渐减，腹尚微痛，转为间疟，咳嗽形浮胸闷。产后营虚，表邪里邪不得畅达，病延月外，真阴拖虚。浮数为邪郁于表，细弱为营阴内损，故拟扶正逐邪。", ["浮", "数", "细", "弱"]], "11935": ["病机", "脉缓中带滞，舌白。初受寒邪，寒邪内郁不化，胎气逆升，致产后瘀凝上扰，故神昏狂乱、牙关紧闭、目瞑、遗尿失便。缓中带滞主寒郁气滞、瘀血内阻，病情甚险。", ["缓", "滞"]], "11936": ["病机", "小产后恶露未尽、少腹痛瘀下，营血已虚；复感新风，身热头胀胸闷，脉数乃邪势乘虚而入、正邪交争之象。数脉在此非单纯实热，而是营虚邪扰、气血沸动，故原文强调“营虚之际，邪势乘之，小心为要”，示人勿峻攻。", ["数"]], "11937": ["病机", "偏产后受寒，厥气不泄，少腹痛攻逆不已。脉沉主里、主寒邪内束，数则内有郁热，寒外束而热内郁，气机不得疏泄，故见攻逆腹痛。原文“内有郁热，外束寒邪”正合沉数并见之理，法当疏泄以解郁散寒。", ["沉", "数"]], "11938": ["病机", "昔年产后早投补剂，营分伏热不泄，上冲致喉腐、蒂丁脱落、口鼻如火、咯红色臭痰。左三部洪数，洪为热盛气浮，数为火郁不泄，三阴伏火久病根深，故原文断“难许痊可”，法当清泄阴分之热。", ["洪", "数"]], "11939": ["病机", "产后恶露颇多，腹痛耳鸣，脉细。细为血少脉道不充，去血过多则营虚，虚阳失守欲越，故耳鸣。原文“去血过多，虚阳欲越”点明病机，治以和营潜阳，使阴血复而浮阳潜降。", ["细"]], "11940": ["病机", "产后两月恶露淋漓，腹痛腰酸，原文未载脉，直指“八脉气血不能相摄”。冲任带督失于统摄，气血耗散不固，故恶露久淋、腰腹作痛。此段以症推机，属奇经亏损、摄纳无权之病机。", []], "11941": ["预后", "怀孕七月劳力伤胎，下血盈桶，胎损胞破横逆，自汗神疲、耳鸣头晕、干恶，脉细欲绝。细欲绝乃阴血暴脱、阳气将散之候，气血两竭故危。原文“证在临危，药难挽救”明言预后凶险，勉拟一方尽人事。", ["细"]], "11942": ["病机", "偏产逆生，营血大下，头晕耳鸣心悸目暗自汗，阳气上冒，气随血虚。脉数而涩，数为虚阳浮动，涩为血少脉道不利，血虚不能濡养筋脉，势恐血虚风生发为痉厥，故拟和阴潜阳益气。", ["数", "涩"]], "11943": ["病机", "血崩偏产，营阴大夺，产虚不复，八脉亏损，赤白带下，阴空阳逆上冒则耳鸣眩晕，纳少食则䐜胀腹膨。原文“冲脉隶胃，阳明既伤”指出冲脉失养、胃气受损，故宜调胃气以复冲脉之源，属奇经虚损病机。", []], "11944": ["病机", "脉速涩者，数而涩也。产后正虚神疲、少纳，数为虚阳浮动，涩为血少脉道不充，正合气血两虚、中阳不振之机。虚则神疲少纳，涩则营血不充，故当以温中扶阳为治，脉症相参，非实热之数可知。", ["数", "涩"]], "11945": ["病机", "脉软数，软为脾阳不振、脉道弛缓，数为伏邪化热、营卫相争。产后感受伏邪而发寒热羁縻，头眩少纳、食则䐜胀，皆脾阳不运之征。软数并见，说明正虚而邪未清，营卫不和，故以脾阳不运、营卫不和立论。", ["软", "数"]], "11946": ["病机", "脉数而舌白，数主邪正相争，白苔主寒湿。产后五朝寒热休作不时，胸闷腹痛，当脐痛则必利、利色白脓，是风冷克于太阴，营卫不和，卫疏汗泄。脉数非纯热，乃邪实正虚、正邪交争之象，故云理之不易。", ["数"]], "11947": ["病机", "脉细而虚，细为阴血亏少，虚为正气不足。漏胎产后血虚，阴亏阳无依附，化内风上窜，致神昏口噤、言语低微不爽、神呆，晨便溏。细虚之脉正合心脾营虚、神无主宰，阴血不能荣养心神与筋脉，故见痉厥神昏诸症。", ["细", "虚"]], "11948": ["病机", "产后十朝恶露颇多而脉大，大脉在此非实热，乃湿郁太阴、冲脉不摄，气血外浮之象。舌白腻、纳少、腹痛，皆湿困中焦之征。恶露多而脉大，说明冲脉失于收摄，湿浊内郁，故以湿郁太阴、冲脉不摄为主病机。", ["大"]], "11949": ["病机", "脉沉速细，沉主病在里，细主正虚，数为邪郁化热。产后风寒袭肺，背寒且痛，晨起呛甚，是邪郁肺底、肺气失宣。沉细而数说明邪伏于里而正已不足，故断为邪郁肺底、恐难脱体，脉症相应。", ["沉", "细", "数"]], "11950": ["病机", "脉沉弦数，沉主里，弦主痛与肝郁，数主邪热。难产后阴器受伤致腐，虽愈而带下频频，寒热、腹痛、胸闷、便泄、少纳，是久虚不复、冲任带受损而易于外感。沉弦数正示正虚邪恋、肝脾不调之机。", ["沉", "弦", "数"]], "11951": ["病机", "原文未识脉名，故脉象要素从缺。所述产后阴器受伤致腐之后，脐旁腹痛四五日一发，发则如淋臭秽水下，即寒热，乃冲、任、带脉皆伤，而𫏋维亦少护持。此段重在阐明损伤奇经、护持失职之病机，非以脉断病。", []], "11952": ["病机", "脉细为营血不足、下元虚损之象。产后尿脬损伤，小便淋漓，纳少，乃因产时伤及膀胱，下焦虚惫，气化失司，故小便淋漓；纳少为脾胃气弱。脉细主下虚，与膀胱已伤相应，故曰“理之不易”，示其虚损难复。", ["细"]], "11953": ["病机", "脉弦数主风温郁于手太阴肺部，化热伤阴。产后感受风温，郁久化热，故咳嗽、寒热将及一年。弦为风邪郁结，数为热象，与《难经》“阳维为病苦寒热”相合，说明风温之邪留连肺卫，营卫失和而寒热作。", ["弦", "数"]], "11954": ["病机", "脉缓主营虚，冲任不司约束。产后恶露淋漓四月不止，腹痛、头眩、心悸，皆因营血亏虚，冲任失约，血不归经而妄行。缓脉为营虚不充之象，非平和之缓，故主冲任虚损，约束无权。", ["缓"]], "11955": ["病机", "脉左涩主新产暴虚，血少气滞，厥阳化风上旋。产后半日卒然风痉，厥逆频作，头肿呕逆眩晕，乃血虚风动，冲逆犯胃。所幸恶露仍通，脉涩示血行不畅而非闭绝，故可熄风潜阳以冀厥止风定。", ["涩"]], "11956": ["预后", "脉如奔泉外涌十里，数而浮越，乃产后暴虚，虚阳上冒，阴不涵阳，脱象大著。发热自汗、气逆心悸、惊惕舌红，皆虚阳浮越之候。急宜固摄，必得脉数渐退，方为佳境，说明脉数不退则脱势难挽，脉数为预后转归之关键。", ["数"]], "11957": ["病机", "原文未识脉名，然述病情起于产褥，营虚感受风邪，外风引动内风，阳气鸱张，风阳旋扰不息，致头痛遇风为甚、腹痛休作、带下。肥人多湿多痰，流注带脉。论证当养营熄风，佐以固摄其下，况怀麟三月，须根固蒂坚，勿损胎元。", []], "11958": ["病机", "脉弦数主脾肾阴虚，虚热内扰。产后下利脓血，久利清浊混淆，阑门水谷不分，直走小肠，阴阳易位而为交肠。病延十月，形瘦神夺，寒热舌光腰痛，皆阴亏液耗之象。弦数为阴虚阳亢，故曰“理之不易”，拟开太阳、堵截阳明以分清清浊。", ["弦", "数"]], "11959": ["病机", "脉大主邪气盛，面赤气粗、目瞪脉大，乃风痰火邪壅盛之象。卒遇恶风，口眼㖞邪，噤不能言，形如尸，是虚邪贼风中人，痰火闭窍。前医误用参桂附辛热刚燥，反助邪火。脉大示邪实，故治以祛风消痰清火，辛凉佐甘温，正合《内经》明训。", ["大"]], "11960": ["病机", "脉洪大有力，面赤气粗，乃痰火充实，诸窍皆闭之候。洪大为阳盛之象，痰火内壅，气血沸腾，故脉形洪大而搏指有力。此非虚寒，若误投参附，则痰火愈炽，立致危殆。原文以“洪大有力”断为痰火实证，与昏厥、遗尿、口噤手拳、痰声如锯相应，故治以清火豁痰，佐生军通腑。", ["洪", "大"]], "11961": ["病机", "脉弦滑洪大，乃湿痰注经传腑之证。弦主痰饮，滑主湿浊，洪大主阳盛气浮。素好饮酒，湿热内蕴，痰湿流注经络，故半身不遂、口强流涎。脉象与证相符，非虚寒可比。原文以“弦滑洪大”断为湿痰实证，治用豁痰驱湿，月余而起，惟肢体言语未能如旧。", ["弦", "滑", "洪", "大"]], "11962": ["病机", "脉洪而气旺，此元气强实之体，而痰火充盛耳。洪为阳脉，气旺则脉洪，年六十余而患风痹，脉不虚而反洪，知非虚证，乃痰火壅盛。原文以“洪而气旺”断为实证，故清火消痰以治标，养血顺气以治本。若误投温补，重药伤正，则速其死。此“人实证实”之候，脉象为辨证关键。", ["洪"]], "11963": ["预后", "脉已绝，痰声起，不知人，此卒中危候。原文未载具体脉名，仅言“脉已绝”，示正气暴脱、经络闭塞。虽用至宝丹灌之得苏，然脉绝为一时气不能纳之兆，若药不预备，则周时而死。此段重在辨卒中各类厥证之预后，脉绝与痰声、神昏并见，示病情凶险，非寻常脉象可拘。", []], "11964": ["其他", "此段叙牙紧不开、皮坚如革之奇症，未载脉象。原文细审病情，断为恶风所吹，二十年前曾受怪风，今复发。虽无脉可凭，然“皮坚如革”为外邪深入、气血凝滞之征。段中未及脉诊，故脉象要素为空，主旨属特殊病案之记述，非平脉死脉之论。", []], "11965": ["病机", "神昏脉数，不食不寝，医误投六味，烦热益甚。数脉主热，热邪留于胃，故脉数而神昏。原文以“脉数”断为热邪归阳明，非虚证。邪重有食则结燥矢，邪轻无食则凝热痰，治以泻心汤加减。数脉在此示热盛，与神昏、烦热、不食相应，误补则热愈炽。", ["数"]], "11966": ["病机", "脉滑数而按之虚软，不过湿热阻气，升降不调耳。滑主湿痰，数主热，按之虚软示湿热壅阻而正气已伤，非实结可下。原文以“滑数而按之虚软”断为湿热阻气，故用枳桔汤加味宣降湿热，一剂谵语止，二剂旁流止。若误作燥矢攻下，则虚其虚。", ["滑", "数", "虚", "软"]], "11967": ["其他", "脉无伦次，神昏谵语，身热不凉，此游魂证也。原文未识具体脉名，仅言“脉无伦次”，示脉律散乱、神不守舍。段中叙招魂安神之法，以安神镇魄之药加猪心尖、辰砂取效。脉无伦次与神昏谵语相应，属神志失常之候，非寻常病机脉象可概。", []], "11968": ["病机", "六脉细数不伦，细为阴伤，数为火炎，脉象不整，神不清爽，此消证日久，阴液耗损，虚火内炽，扰乱心神，故见昼夜食粥、气逆火炎、通夕不寐，似祟脉乃因火旺神昏所致。", ["细", "数"]], "11969": ["病机", "脉数无定，暑热疫毒内陷，热邪充斥，故身热神昏、闷乱烦躁；数而无定，示热邪鸱张，正气尚能抗邪，治以清凉芳烈，辟邪解毒，热退则神清。", ["数"]], "11970": ["预后", "脉绝而心尚温，皮色未变，此暑邪闭塞诸窍，气机骤阻，非真阳绝也，故未即死；暑邪内闭，脉道不通，治以清暑通气，窍开气通，则脉复身安。", []], "11971": ["病机", "脉微欲绝，遗尿谵语，寻衣摸床，此阳越之证，暑热耗气伤阴，阳无所附而外越，将大汗出而脱；急以参附回阳，阳回后阴竭火炽，转以西瓜清暑养胃。", ["微"]], "11972": ["病机", "脉微肢冷，面赤气短，大汗不止，此热甚汗出而阳亡，非热证也；脉微足冷，汗出舌润，为亡阳确征，急进参附回阳，误作热治则死。", ["微"]], "11973": ["病机", "脉尚微存，厥逆如尸，身未冷，此暑邪内结，闭塞诸窍，逼魂于外，尸厥之候；邪气充塞，脉道不利，故脉微，通窍辟邪，魂返则苏。", ["微"]], "11974": ["病机", "脉微而躁，肤冷汗出，热病忽手足拘挛、瞀乱昏迷，此阳将脱也；微为阳衰，躁为阴扰，阳脱于外，故见肤冷汗出，急以参附回阳，阳回则愈。", ["微"]], "11975": ["预后", "色夭脉微，动易出汗，体素弱而患久疟，此阳气虚衰，卫外不固，将大汗出而亡阳；脉微为阳微之兆，急进参附，阳未遽脱，迟则不及挽。", ["微"]], "11976": ["误治", "原文未载脉象，然述暑毒血痢，热毒蕴结，前医以黄连阿胶取效，后误进人参、干姜温补，致病情反复。此段主旨不在脉，而在示温补误治之害。热毒内蕴，当清解，反投温补，如抱薪救火，故病者怒目厉声，病益重矣。", []], "11977": ["病机", "脉微软无阳，乃过用散剂虚其表，复以补剂固其邪，致阳气不接，卫气不闭。微为阳衰，软为气弱，故畏风如矢，闭户深藏，见微风则寒热而晕。此非外风，乃阳气虚馁，卫外不固，故治以晒日接阳，药乃效。", ["微", "软"]], "11978": ["病机", "脉弦软而滑，弦主气郁，软为不足，滑主痰饮。积劳善怒，气逆痰阻，阳气上升而不能下降，故自汗凛寒、腕疼咳逆、呕吐苦水；痰阻阳道，宗筋失养，故阳痿匝月。形瘦面黧、苔黄溲赤便难，皆痰火内郁之征，非阳虚也。", ["弦", "软", "滑"]], "11979": ["病机", "脉滑而长，滑主痰涎壅盛，长主气逆有余。久患痰喘自汗，群医误补，致痰壅气逆，睛凸囟高、面浮颈大、胸前痞塞，此痰实壅塞，非虚脱也。又顾某脉滑不调，肥白多痰，屡补气逆欲死，苔黄溲赤，亦痰火内蕴，故以清肺涤痰取效。", ["滑", "长"]], "11980": ["病机", "脉洪大，手足不冷，喘汗淋漓，此亡阴而非亡阳。亡阴者阳热方炽，汗热不黏，舌干；亡阳则脉微，汗冷如膏，手足厥逆舌润。洪为阳盛，热迫津泄，故汗出不止；若误认亡阳投参附，则阳愈炽而阴愈竭。故先敛阳气，继清痰火。", ["洪", "微"]], "11981": ["病机", "脉滑不调，滑主痰，不调为痰火壅滞、气机失畅。面浮色赤、舌绛而干、音嘶胁痛，皆痰火为患，非损怯也。前医误补，酿为遍体之痰，腰间疼胀，抚摩嗽甚。此痰火胶固上膈，故以清肺化痰丸噙化，使胶痰渐吐，诸恙乃安。", ["滑"]], "11982": ["病机", "脉弦滑，苔满布舌边绛，乃冬温薄肺，痰热壅阻，失于清解，故喘不能卧。又脉弦软无神、沉弱，苔白不渴，面红汗冷，便溏肢冷，乃寒痰上实、肾阳下虚。弦软无神为阳衰，沉弱主里虚，故以真武汤温肾，加姜味参朴杏以化痰降逆。", ["弦", "滑", "软", "沉"]], "11983": ["病机", "脉弦而急，弦主气郁饮停，急为邪结化热。胸下痞闷、腹中聚块、气下行至指而惊寤，乃气郁饮停；误投温补，致神呆不语、目眩不饥、便闭不眠、寒热时作，块已累累，溺赤苔黄，皆饮郁化热、肝络不和之征，故以通降清络舒肝取效。", ["弦", "急"]], "11984": ["病机", "脉洪且数，洪为气分热盛，数为热象，合之见发热、舌干紫无苔、溲赤便闭，是津虚脾约、气滞痰凝而热郁于内。洪数非实火独盛，乃高年津亏、气不化津，热与痰气交阻，故轻肃宣濡得热缓胁舒，便行则脉静身凉，呃忒属气为痰阻、升降失调。", ["洪", "数"]], "11985": ["主病", "脉参错无常，非一脉可名，乃虫扰气机、痛剧气乱之象。原文见昏厥、舌咬破流血、唇白目直视，皆虫痛攻冲、气血逆乱所致。脉无定体，正合虫动痛作痛止、气机乍乱乍复之机，故断为虫痛而非寒食，杀虫后大痛不复作。", []], "11986": ["病机", "脉洪大有力，见于年近八旬、小腹高起、阴囊肿亮、昏不知人，是肾火郁勃、水气不行而脉反形有余。洪大为阳盛鼓动之象，然高年见此非真元充盛，乃欲火不得泄、相火挟湿下注，故以知母、黄柏泻肾而囊肿消、人得苏。", ["洪", "大"]], "11987": ["预后", "脉微目闭，面青唇白，奄奄待毙，是血脱之后气随血脱、脏腑经络俱空之候。微为阳气衰微、脉道不充，目闭面青唇白皆失血亡阳之征。前医误作阳虚温补加鹿茸，致血上冒尽脱，故脉微示危，急以生地汁养阴、少佐人参固气，方得渐复。", ["微"]], "11988": ["预后", "脉微声哑，面白带青，气喘不得卧，是脱血之后阴亏气弱、虚火上逆之危候。微为气血衰微，声哑由阴精不能上承，气喘不得卧乃冲气上逆。原文谓血来有声如沸、左胁气逆冲喉，正虚阳上浮、血随气脱，故危在旦夕，治当保阴止脱、降火纳气。", ["微"]], "11989": ["病机", "六脉似有如无，血已脱尽，是血脱气亦脱、脉道失充之候。原文谓血冒升余、昏不知人，气随血亡故脉几不可按。急加阿胶、三七少和人参以接其气，脉乃渐复，说明血脱者气亦脱，人参接气为权宜，气稍接即当用血药，否则孤阳独旺而阴愈亏。", []], "11990": ["病机", "六脉极洪大而时伏，面赤有油光，舌红不润，目不交睫旬余，是久服参附助阳、虚阳上浮、热郁于内之象。洪大为阳热鼓动，时伏则气机郁遏、阳不外达，面赤油光、舌红不润皆阴伤火旺之征。故以茅草根清凉平淡之品，与参附相反，使郁热得清而病愈。", ["洪", "大", "伏"]], "11991": ["治法", "原文未及脉象，主述血痢五年、日夜百余次、去血数石、骨瘦如柴、饮食不进。久痢失血则血枯脾败，大肠生漏管，故先用滋补养血脉，继用开胃滋化源，再以填补塞空窍，痢减食增而愈。此段重在治法次第，非凭脉断病。", []], "11992": ["妇人", "原文未载脉象，仅述产妇“浆水已涸，疲极不能出声”，稳婆令用力迸下。徐氏断为“试胎”，谓尚未产，劝勿强之，扶令安卧，处以养血安胎之方。其病机在于胎气未足、气血暂虚，非真临产，故脉象虽未明言，然从“疲极不能出声”可知气血已耗，当以养气血、安胎气为要，强用迸下则反伤胎元。", []], "11993": ["病机", "原文未出脉象，专论小儿流注之病机。徐氏谓“流注一证，由风寒入膜所致，膜在皮中，旁通四达，初无定处，所以随处作患，此真脉络之病”，故制大活络丹以通络逐邪。其脉虽未言，然病在脉络，气血壅滞，脉当见涩滞不畅，治以通络为法，非一般煎丸所能取效。", []], "11994": ["预后", "本案脉虚、脉微，色㿠，患虚痰流注，发无定处。脉虚为气血不足，脉微为阳气衰微，正虚而痰浊流窜，故病极危险。后疮孔“内膜干空，与皮不连，气促脉微”，脉微与气促并见，乃阳气欲脱之兆，故徐氏书“危在顷刻”，少顷气绝。此脉微主阳气衰败，预后不良。", ["虚", "微"]], "11995": ["病机", "初诊脉洪数而滑，经停数月，寒热减食，小腹右达环跳隐痛微肿，断为“瘀血为痈，已成脓”。洪数滑为瘀热壅盛、脓毒已成之象。脓溃升余后，脉转微而肤冷，乃“阳随阴脱”，气血骤虚，阳气外脱。同一病而脉由洪数滑转为微，反映脓毒去而正气亦脱，故急以参附回阳固脱。", ["洪", "数", "滑", "微"]], "11996": ["兼症", "原文未载脉象，述对心发疮证收口前忽“头痛身热，神昏谵语，疮口黑陷，六脉参差”。六脉参差者，脉来不匀、大小迟数错杂，乃邪毒内陷、正气散乱之象。细询知贪凉当风，疮口对风，膏药又落，风贯疮中，即破伤风。脉参差与神昏谵语并见，主风毒内攻、神明扰乱。", []], "11997": ["病机", "卒遇恶风，口眼㖞斜，噤不能言，形如尸，面赤气粗，目瞪脉大。脉大为邪气盛实、风痰壅塞之象，非虚大也。面赤气粗、目瞪与脉大相应，皆风火痰浊上壅清窍。前医误用参桂附辛热刚燥，反助邪火。徐氏以祛风消痰清火之剂，三剂而醒，证明脉大主实邪，不可温补。", ["大"]], "11998": ["病机", "体丰善饮，痰多麻木，忽昏厥遗尿，口噤手拳，痰声如锯，脉洪大有力，面赤气粗。洪大有力为痰火充实、邪气壅盛之脉，与面赤气粗、痰声如锯相应，诸窍皆闭。此非虚脱，乃实闭，故服参附立毙。徐氏以小续命汤去桂附加生军，泻火涤痰，三剂有声，五剂能言，脉证相符。", ["洪", "大"]], "11999": ["病机", "素好饮，卒仆口噤，半身不遂，口强流涎，脉弦滑洪大。弦主痰饮、滑主湿痰，洪大为邪热壅盛，合为湿痰注经传腑之证。酒客痰湿素盛，痰随风动，流注经络，故半身不遂、口强流涎。脉弦滑洪大与痰湿化热、壅塞经隧相应，徐氏用豁痰驱湿之品，调之月余而起。", ["弦", "滑", "洪", "大"]], "12000": ["病机", "脉洪而气旺，示元气强实、痰火充盛。洪为阳盛之象，气旺则血充，故虽年六十余患风痹，脉不虚而反洪，说明病机属实证，痰火壅盛于经络，非虚寒可比。治当清火消痰以治标，养血顺气以治本，若误投温补重药则伤正速死。", ["洪"]], "12001": ["预后", "原文未识脉名，但述“脉已绝，痰声起，不知人”，此卒中危候，脉绝示正气暴脱、经络闭塞，痰声起为痰壅气逆。虽用至宝丹灌服得苏，然脉绝乃一时气不能纳之兆，若更以参、附助阳，则痰火愈炽，周时而死，故列预后险恶。", []], "12002": ["其他", "原文未识脉名，述牙紧不开、皮坚如革，乃恶风所吹、经络凝滞之证。虽无脉象可凭，然“皮坚如革”示风毒深入肌腠，气血壅塞，故以蜈蚣、蝎尾等搜风通络、消坚散结。此段重在病因与外治，非脉诊主病。", []], "12003": ["病机", "脉数而神昏不食不寝，医误作虚投六味，致烦热益甚。数脉主热，外感之邪久归阳明，热邪留胃，故脉数、神昏、不食。邪轻无食则凝为热痰，治以泻心汤加减消痰开胃，两剂而安，说明脉数在此主实热而非虚火。", ["数"]], "12004": ["病机", "脉滑数而按之虚软，滑数主湿热痰浊，虚软示正气已伤。患者体丰善饮，湿热阻气，升降不调，故痞胀拒按、便旁流、溲不行。前医误投陷胸、承气，诛伐无过，致脉按之虚软。此脉说明病机为湿热壅阻而中气已馁，故以枳桔汤加味宣降湿热，不可再攻。", ["滑", "数", "虚", "软"]], "12005": ["其他", "原文未识脉名，述“脉无伦次”，神昏谵语，身热不凉，此游魂证也。脉无伦次示神气涣散、魂魄不守，非寻常外感。故用安神镇魄之药加猪心尖、辰砂，戒勿惊醒，熟寐则神合。此段主旨在招魂安神，脉象仅作神散之佐证。", []], "12006": ["病机", "六脉细数不伦，神不清爽，患消证昼夜食粥数十碗，气逆火炎不寝。细为阴伤，数为火旺，不伦示脉律不齐、神气失守。此似祟脉，必有他故，原文述床上有女盛妆危坐，乃邪祟干扰，致魂不守舍。脉细数不伦反映阴亏火旺而神乱，非单纯消渴。", ["细", "数"]], "12007": ["病机", "脉数无定，身热神昏，闷乱烦躁，乃瘟疫之邪由尸气触染，暑热秽浊壅遏气分。数脉主热，无定示邪热弛张、正气抗争。前医误用香燥升提，与证相反；余以清凉芳烈、辟邪解毒，渐知人事。此脉说明病机为秽浊热毒内扰，非表寒可汗。", ["数"]], "12008": ["其他", "原文未明确脉名，仅述“脉绝而心尚温，皮色未变”，此暑邪闭塞诸窍，非真死，故脉绝而心温，为暑闭心包、阳气内遏之象，非阳气外脱，故断为可治，与后文清暑通气方相应。", []], "12009": ["病机", "脉微欲绝，伴遗尿谵语、寻衣摸床，此暑热坏证，阳越于外，将大汗出而脱。脉微为阳气衰微欲绝之象，非热盛之脉，故急以参附加童便回阳固脱，后阳回火炽，转以西瓜清暑养胃。", ["微"]], "12010": ["病机", "暑病热极，大汗不止，脉微肢冷，面赤气短，此热甚汗出而阳亡，脉微足冷为亡阳确证。脉微主阳气衰微，肢冷为阳失温煦，故急进参附回阳；若脉不微、足不冷，则仍属热证，误用即死。", ["微"]], "12011": ["病机", "暑邪内结，厥逆如尸，身未冷，脉尚微存，此为尸厥。脉微存说明阳气未绝，邪气充塞诸窍，逼魂于外，故以紫金锭通窍，西瓜等汁清暑，窍通魂返而苏。", ["微"]], "12012": ["病机", "热病见手足拘挛、瞀乱昏迷，脉微而躁，肤冷汗出，此阳将脱矣。脉微为阳气衰微，躁为虚阳扰动，肤冷汗出为阳脱之兆，故急以参附回阳，后以消暑养阴收功。", ["微"]], "12013": ["预后", "久疟体弱，色夭脉微，动易出汗，脉微为阳气虚衰，不能固摄，故断为当大汗出而亡阳。急进参附挽回，汗出如膏、两目直视、气有出无入，赖参附阳未遽脱，终得汗止阳回。", ["微"]], "12014": ["误治", "原文未识脉名，述暑毒血痢，热毒蕴结，以黄连阿胶取效。后因更医误进人参、干姜，病者怒目厉声，病益重，此温补助邪之误，非脉象所主，故列误治。", []], "12015": ["病机", "过用散剂虚其表，继用补剂固其邪，风入营中，畏风如矢。诊脉微软无阳，微为阳虚，软为气弱，阳气不接，卫气不闭，故避风太过反致阳气不伸，治以日光晒之，使阳气得接，卫气自固。", ["微", "软"]], "12016": ["病机", "脉弦软而滑，弦主肝郁气滞，软为痰湿不坚，滑主痰饮内蕴。患者积劳善怒，肝气升腾，痰浊阻滞，阳气不能下降，故见自汗凛寒、脘疼咳逆、呕吐苦水；阳痿亦因阳气为痰所阻，非真虚也。治以化痰降逆，气降则阳通。", ["弦", "软", "滑"]], "12017": ["病机", "脉滑而长，滑主痰浊壅盛，长主气机郁逆。症见汗如雨下、睛凸囟高、面浮颈大、胸前痞塞，皆痰气上逆、壅塞清道之象，非虚脱也。故以导痰汤加味涤痰降逆，痰去则气降，诸症自平。若脉滑不调，亦属痰阻气机，清肺涤痰而愈。", ["滑", "长"]], "12018": ["病机", "脉洪大而手足不冷、汗热不黏，为亡阴阳炽之候，非亡阳也。亡阳则脉微、汗冷如膏、手足厥逆而舌润；此则阳气方炽，迫汗外泄，故脉洪大。治宜收敛阳气，不可即用阳药，否则助火耗阴。原文以脉微与脉洪对举，明辨亡阴亡阳之异。", ["洪", "大", "微"]], "12019": ["病机", "脉滑不调，滑主痰，不调为痰火壅滞、气机失畅。患者面浮色赤、舌绛而干，非肉不饱，显系痰火为患，非虚损也。前医误补，致痰愈壅，胶痰渐吐后诸恙乃安。原文强调不可因音嘶胁痛而疑为损怯末传，当从脉滑辨痰火。", ["滑"]], "12020": ["病机", "脉弦滑为痰饮内停、气机郁滞，苔满布舌边绛，乃冬温薄肺、失于清解，故喘不得卧。若脉弦软无神，则属寒痰上实、肾阳下虚，症见便溏肢冷、面红汗冷，治以真武汤温阳化饮。原文以脉之弦滑与弦软无神对举，辨痰喘之属实属虚。", ["弦", "滑", "软", "沉弱"]], "12021": ["病机", "脉弦而急，弦主气郁饮停，急为郁久化火、肝络不和。患者胸下痞闷、腹中聚块、气逆惊惕，本属气郁饮停，误投温补，致神呆不语、便闭不眠、寒热时作，块累溺赤苔黄。脉弦急示郁热内炽，故治以通气涤饮、清络舒肝。", ["弦", "急"]], "12022": ["病机", "脉洪且数，洪为气分热盛，数为热邪内迫。患者年高津虚脾约，气滞痰凝，感邪发热而左胁偏痛，舌干紫无苔，便闭溲赤，呃忒频来。脉洪数示热痰壅阻、升降失调，非虚呃也。故以轻肃宣濡、枳桔汤加味清化痰热，便行则脉静身凉。", ["洪", "数"]], "12023": ["病机", "脉参错无常，为虫扰气机、阴阳乖乱之象。患者腹痛昏厥、舌咬破流血、唇白目直视，皆虫动攻心、气逆血乱所致。原文以脉参错无常断为虫痛，非寒非食，故化虫丸下虫而痛缓，继以杀虫安胃补脾，虫根遂绝。", []], "12024": ["病机", "脉洪大有力，非虚寒脱证，乃肾火郁勃、欲念不遂而相火妄动，故阴囊肿亮、小腹高起、昏不知人。洪大为阳盛之象，与年近八旬而见实脉相合，说明病本在肾，火郁于下，非阳虚失血可比。用知母、黄柏泻肾，正合脉证。", ["洪", "大"]], "12025": ["预后", "温补误治，血上冒而连吐十余碗，一身之血尽脱，故脉微、目闭、面青唇白，奄奄待毙。脉微为气血俱空、脏腑经络皆虚之候，与血脱相应。此时非轻剂可治，故用鲜生地汁、人参徐徐进之，以救阴养血，脉证相符。", ["微"]], "12026": ["病机", "久患血证，左胁气逆冲喉，血来有声如沸，忽大吐数升，面色白而带青，脉微、声哑、气喘不得卧。脉微为脱血之后气血大虚、阳气衰微之象，与血脱气逆、阴不敛阳相应。故先保阴止血，再降火纳气，不可重用人参升气助火。", ["微"]], "12027": ["病机", "血冒升余，昏不知人，六脉似有如无，血已脱尽。脉似有若无，为血脱气亦脱、脉道空虚之候，与血脱相应。故少和人参以接其气，气稍接即用血药，否则孤阳独旺而阴愈亏。此段论血脱补气与补血先后主客之分。", []], "12028": ["病机", "下血斗余，晕倒不知人，日服参附，六脉极洪大而时伏，面赤有油光，舌红不润，目不交睫。洪大时伏为虚阳外浮、阴血亏耗、阳气不能潜藏之象，非实热。故用茅草根清凉平淡之品，与参附相反，以敛浮阳、清虚热。", ["洪", "大", "伏"]], "12029": ["治法", "患血痢五年，日夜百余次，去血数石，骨瘦如柴，饮食不进。原文未及脉象，主在治法：先用滋补养血脉，复用开胃滋化源，久痢大肠生漏管，以填补之品塞其空窍，痢减饭增而愈。示久痢虚损当补养化源、填补空窍。", []], "12030": ["妇人", "产二日不下，浆水已涸，疲极不能出声，稳婆令用力迸下。原文未及脉象，主在妇人试胎之辨：此试胎尚未产，勿强之，扶令安卧，处以养血安胎之方，胎气安和，一月后顺产一男。示试胎当安胎待产，不可强下。", []], "12031": ["小儿", "小儿九龄患流注，肩背腰胁十余处，百端医治无效。原文未及脉象，主在小儿流注之治：由风寒入膜，膜在皮中旁通四达，随处作患，为脉络之病，故用大活络丹，未破者消、已破者收口，更服补气血药而愈。示一病有一病之法。", []], "12032": ["预后", "本案初诊「色㿠脉虚」，虚痰流注发无定处，脉虚示正气亏虚、痰毒流窜；后疮孔内膜干空、气促脉微，脉微为阳气衰微、气血将绝之候，故断「危在顷刻」。脉由虚转微，反映正虚邪陷、元气败脱，与气促、疮口不敛相应，属死候。", ["虚", "微"]], "12033": ["病机", "初诊「洪数而滑」，洪数主热盛，滑主瘀血成痈，故断瘀血为痈已成脓；脓溃后「脉微肤冷」，脉微为阳衰，肤冷为阳失温煦，乃阳随阴脱之候。脉由洪数滑转为微，反映脓毒大泄、阳气暴脱，与脓出升余、人将脱相应，急以参附回阳。", ["洪", "数", "滑", "微"]], "12034": ["兼症", "本案对心发收口前忽头痛身热、神昏谵语、疮口黑陷，「六脉参差」。参差指脉来不齐、大小迟数错杂，非平和之象，示疮毒内陷、风邪乘虚入中，即破伤风之变。脉参差与疮口对风、膏药脱落相应，说明正虚邪陷、经脉紊乱，故病情骤重。", []], "12035": ["其他", "本条为校勘记，指出温病门案一「六脉洪大无伦」误写为「无论」。洪大之脉主热盛邪实，无伦谓脉来洪大失其常度、毫无伦序，为热邪亢盛、正气浮越之象。原文仅校字误，未涉具体病机，故脉象要素取洪、大，主旨属文字校勘之其他类。", ["洪", "大"]], "12036": ["其他", "本段为翟竹亭传记，述其家世、从游先耕习医、授方脉针灸术等事，全段未及具体脉象与诊病。原文「授方脉及针灸术」仅言医术传授，非脉象描述，故脉象要素为空，主旨属传记类其他，不涉病机分析。", []], "12037": ["其他", "本段为湖岳村叟翟竹亭小传，叙其祖籍迁徙、家世贫寒、父患瘫痪、幼年负贩等经历，末言其成国手。全段无脉象记载，「目为杰士」乃评其医名，非脉诊内容，故脉象要素为空，主旨属传记类其他，不涉病机。", []], "12038": ["病机", "疫病误服麻黄桂枝大剂，又进白虎，致「六脉洪大无伦，中取不见」。洪大无伦为热邪亢盛、脉失常度；中取不见示正气内溃、脉无胃气，故断「逼阳外越」。此脉与烦躁、大渴、发狂詈骂相应，属误治后阴寒内盛、虚阳浮越之危候。", ["洪", "大"]], "12039": ["病机", "本条按语重申「六脉洪大无伦，中取不见」为逼阳外越之凭，用桂附回阳得愈。洪大无伦示虚阳浮越于外，中取不见示里阳衰微、脉无根柢，故温疫中敢用桂附。脉与误治后阳越危候相应，说明凭脉辨证、回阳救逆之要。", ["洪", "大"]], "12040": ["主病", "六脉洪大有力，为疫邪入里、阳明腑实之征。原文见大渴饮水、心胸胀满、谵语狂躁、小便赤涩、大便闭结，皆实热结聚肠胃之象。脉洪大有力，说明邪盛正未衰，故断为应下实证，投大承气汤下燥粪秽物而病减，印证脉证相符。", ["洪", "大"]], "12041": ["病机", "六脉按至伏滑微细劲硬，伏滑为邪毒内结肠胃，微细为老人阴虚津枯，劲硬则邪毒锢结。原文满面通红、胸腹拒按、不饮不食，正合阴虚津竭、邪毒结聚之机。故用扶正攻邪，泻下秽便后以养阴退热解毒收功，脉象揭示正虚邪实之本质。", ["伏", "滑", "微", "细"]], "12042": ["预后", "脉细弦而神色已脱、如梦如醉，细为阴血衰少，弦为邪气搏结，正虚邪盛而神气已败。原文直言真绝证也，后殁，说明此脉非一般疫证可治，乃阴阳离决、正气溃败之候，故列于预后不良，与后文可治诸案形成对照。", ["细", "弦"]], "12043": ["病机", "尺脉沉数，沉主里，数主热，尺部应下焦胞宫。原文病势大热不止、日晡如见鬼神、狂言乱语，又值天癸刚过，故知热入血室。脉沉数正示热邪内陷血分，不可妄下，故用小柴胡汤加减和解少阳，后鼻衄而愈，热从血解。", ["沉", "数"]], "12044": ["病机", "此段承前案而申论，经脉适断又染疫邪，大热不止、日晡如见鬼神、狂言独语，为阳明病热入血室。原文未出脉象，故脉要素从缺。其病机在于热与血结，治宜和解少阳兼清热行血，使热从和解及鼻衄而解，与尺脉沉数案互参。", []], "12045": ["误治", "胃脉洪大无力、肺脉数而且虚，洪大数似实热，而无力且虚则示正气已伤。原文误用麻黄桂枝等汤求汗，致躁扰不宁、大渴谵语，故断为温疫邪热入胃腑而误作伤寒。脉虚说明脏腑已受药害，故用大承气攻邪，佐人参当归补气血，攻补兼施。", ["洪", "大", "数", "虚"]], "12046": ["病机", "肾脉细弱无力、心脉甚虚、脾肺脉涩，细弱虚涩并见，为阴虚血少之候。原文迁延十日，知阴虚不能作汗，故引吴又可养阴即是发汗之说，用六味四物汤加生津之品，服后得战汗热退。脉涩示血少行滞，正合阴亏汗源不足之机。", ["细", "弱", "虚", "涩"]], "12047": ["病机", "肺胃脉隐然有力、心脉急数，急数为热邪内扰，隐然有力示实邪结聚。原文问之不语、按胸腹似痛、大便六七日未解、午后潮热，合为温疫误治变成结胸之证。脉急数说明热结阳明，故非下不可，去芒硝加清温化毒，泻后神清热退。", ["急", "数"]], "12048": ["治法", "原文未出脉名，仅言“认脉明晰”，强调温疫误治结胸须下，下后和解调理。其脉当为实象可下之征，然文未明指，故脉素从缺。所主病机为疫邪内陷、结于胸膈，治当攻下，下后余邪未清则宜和解。", []], "12049": ["主病", "“六脉洪大”为疫毒炽盛、邪热内壅之象，与胸腹满痛、大便闭结、大渴饮冷、烦躁谵语相应。洪大主热盛，热毒传变速，故宜急攻，一日数下。原文以脉与腹痛为重，说明洪大脉在此提示阳明实热可下之机。", ["洪", "大"]], "12050": ["病机", "“胃脉实而滞涩，心肺脉俱洪数”，实涩主阳明胃腑邪实郁滞，洪数主心肺热盛。原文谓“土实肺燥，心火上炎，邪郁胃腑，因此发黄”，脉证相合，故以茵陈汤攻阳明实邪，泻下黑泥污水后脉证稍减。", ["实", "涩", "洪", "数"]], "12051": ["病机", "“六脉同等洪大已极”为疫热炽盛、邪流入大肠之候，故见挟热下利、便脓血、腹疼如锥刺、思饮冰水。洪大已极说明热毒壅盛，非大下不能存阴安胎，原文以“芒硝、大黄即是安胎良药”点明治法所本。", ["洪", "大"]], "12052": ["病机", "“六脉洪大己极”与腹痛如锥刺并见，为妊娠时疫热毒内结、邪实当下之征。洪大已极示热盛邪壅，故翟氏放胆用硝黄攻下，原文以“悬钟腐梁”为喻，说明邪盛不去则胎亦难安，攻下正是逐邪安胎。", ["洪", "大"]], "12053": ["死脉", "原文“六脉皆无”而腹疼如锥刺、大泻倾盆色如败血、神情如塑，为疫毒内陷、正气败绝之候。脉皆无说明胃气已竭，故断为“决无生理”。此段虽未出具体脉名，然以无脉主死，属死脉范畴。", []], "12054": ["主病", "“脉细如丝，幸而有神”，细主阴血不足，有神则胃气未绝。疫后潮热、强食呕吐、骨瘦如柴，似噎膈而实非，详察胃脘微疼，知燥粪结存胃脘。脉细有神说明正虚未败，故可润下燥粪，下后诸症若失。", ["细"]], "12055": ["病机", "“脉虽细而有神”与潮热、饮食难进、强食呕吐、胃脘微疼并见，细为阴血不足，有神为胃气尚存。原文指出疫病愈后燥粪结存胃脘，脉细有神说明可任润下，故宜调胃承气汤加蜂蜜润下，燥粪去则诸症自平。", ["细"]], "12056": ["病机", "寸脉洪数，洪为热盛、数为火急，示温毒燔灼上焦；关脉沉滑，沉主里、滑主实，示热毒与有形积滞壅遏中焦。头面肿如瓜瓢、身热烦躁，正是温毒壅遏上焦之候，故断非下不可，用大承气加犀连栀胆膏泻下，后脉势大衰即邪去之征。", ["洪", "数", "沉", "滑"]], "12057": ["预后", "六脉如丝，即细软欲绝之象，与头面肿大如斗、下至胸腹如抱瓮之实邪壅盛证候相违，故曰「证与脉违」。误服除风之品，病重药误，逆证已现，正气不能胜邪，脉不应证，预后凶险，未及用药遂殁。", ["细"]], "12058": ["病机", "初诊六脉不鼓、四肢微凉、神志昏愦，为老人气血俱亏、疫邪沉匿膜原不能托送之虚象；服药后疫邪显露，微渴微热，脉转稍洪滑，洪滑为邪由里出表、正气渐复之机，故继以六味汤扶正，终得战汗而解。", ["洪", "滑"]], "12059": ["病机", "六脉洪数、按之有力，洪为热盛、数为火急、有力为实，示疫毒化火壅盛于里。头面如斗、肿处水泡流清水，皆热毒挟湿上攻之候。禀赋厚故可任攻下，连投普济消毒饮加硝黄犀羚，泻下后脉势渐衰，证实邪得下而解。", ["洪", "数"]], "12060": ["死脉", "脉如鼎沸，形容脉来汹涌无根、躁疾杂乱，非平和之象。合大喘不息、身如被杖，为疫毒深入、孤阳浮越不能返本之危候，故断速备后事。此段以脉如鼎沸定死期，属死脉范畴。", []], "12061": ["病机", "此按语释前案：身如被杖因疫毒侵袭血脉、瘀血凝滞、流行不畅而遍身疼痛；大喘不息、脉如鼎沸则因孤阳不能返本、阳气浮越无根。脉如鼎沸为纯描述，示阴阳离决之死候，故命速备后事。", []], "12062": ["主病", "六脉沉滑有力，沉主里、滑主实、有力为邪盛，示疫毒内盛结于阳明。误服祛风药后头面胸腹两乳肿甚，为风药助邪、热毒壅滞之变，脉证合参属里实可下，故径用大承气汤攻之。", ["沉", "滑"]], "12063": ["病机", "此按语重申六脉沉滑有力为疫毒内盛之凭，沉则病在里，滑而有力则邪实结聚，非虚寒可比。故敢以大承气汤重剂连进，非有胆有识者不敢为，强调脉象是断然攻下之依据。", ["沉", "滑"]], "12064": ["病机", "胃脉洪数，为热盛于阳明；肾脉虚弱无力，为先天不足、津液枯槁。热盛而液亏，故不能作汗，即吴又可“夺液无汗”之旨。脉症合参，知非单纯表邪，乃正虚邪实、化源告竭之候，故以六味汤加清温化毒，滋水以助汗源。", ["洪", "数", "虚", "弱"]], "12065": ["病机", "此段重申前案：胃脉洪数主热盛，肾脉虚弱无力主液亏。热盛则津伤，液亏则无汗源，故见证明白。脉象直接揭示“津液枯竭，不能作汗”之病机，非表闭无汗可比，为滋阴化毒治法提供依据。", ["洪", "数", "虚", "弱"]], "12066": ["病机", "原文未识脉名，然“六脉闭绝”而见四肢厥冷、气喷如火、大渴便闭等，乃阳毒内闭、热深厥深之真热假寒证。脉闭绝非虚寒，是热邪壅遏、气血不通所致，故用大承气汤通下泄热，使内闭得开，厥逆自回。", []], "12067": ["预后", "下后厥回大半，脉现滑数，为邪热由内闭转为外达，滑主实热，数主热盛，脉证相应，故知险证渐退。后见鼻衄、红斑，是邪从血分透解之象，预后良好，调理可复。", ["滑", "数"]], "12068": ["病机", "六脉细数劲硬，沉取有力，细为阴伤，数为热盛，劲硬有力为邪毒胶结、壅滞大肠。虽泄泻日久，而脉不虚软，知非虚寒，乃“大肠胶闭证”，邪毒仍在，故用大承气汤加减通因通用。", ["细", "数", "劲", "硬"]], "12069": ["病机", "六脉细数，重取不见，细为阴亏，数为虚热，重按无力为根本虚衰。外见满面通红、躁扰冷饮等热象，乃阴极似阳、真寒假热之证。脉象揭示虚阳外越，故用左右归饮温补，冷服以从治。", ["细", "数"]], "12070": ["病机", "阳盛脉当洪大，极则反伏匿，是阳极似阴；阴盛脉当细微，极则反躁疾，是阴极似阳。此“过极者反兼胜已之化”，脉象从极而变，揭示阴阳格拒、真假疑似之病机，为辨寒热真假之要诀。", ["洪", "大", "伏", "微"]], "12071": ["病机", "六脉洪大无力，洪大为热盛之象，无力为正气虚衰，合之痰声如锯、面赤汗淋、渴欲热饮，乃孤阳外越、阴阳脱离之证。脉大而无力，非实热，是虚阳浮越，故用桂附八味汤冷服，引火归原。", ["洪", "大"]], "12072": ["病机", "原文“证似实而脉虚，知是假证”，指出脉虚是辨别假实证的关键。脉虚反映正气不足，虽外见实证，实为虚象，故用桂附回阳以扶正。此脉主正气虚衰，与假实证候相应，提示治疗当从虚论治。", ["虚"]], "12073": ["病机", "原文“诊肺胃二部脉，弦紧沉细，微带滑象”，弦紧主寒邪外束，沉细为里虚，滑象主有痰。结合“形寒饮冷则伤肺”，说明寒邪伤肺、脾土虚弱、痰湿内蕴。脉象反映肺胃虚寒兼痰，故治以大补脾土、固命门火。", ["弦", "紧", "沉", "细"]], "12074": ["死脉", "原文“脉见屋漏”，屋漏脉为七怪脉之一，脉来如屋漏残滴，良久一滴，主胃气已绝、生机将息。患者因误服烈酒致大汗吐血，阴血暴脱，形神已败，故见屋漏脉，预后极差，越二日果殁。", ["屋漏"]], "12075": ["预后", "原文“败脉已现，何生命之有乎”，虽未明指脉名，但结合前段“脉见屋漏”，可知败脉即屋漏脉。风雪严寒与辛辣药酒搏击肺脏，致血汗大下、形神已去，败脉现则生机已绝，故断为死候。", []], "12076": ["病机", "原文“肾脉虚细无力，脾肺脉微缓，少有滑象”，虚细无力主肾虚，微缓主脾肺气虚，滑象为痰。结合“胃为肾关，肾虚者，关不闭，痰饮泛上”，说明肾虚不纳气、脾肺气虚生痰，故治以阴阳双补、纳气归肾。", ["虚", "细", "微", "缓"]], "12077": ["病机", "原文“肺脉沉迟，脾胃脉细弱”，沉迟主寒邪内伏，细弱主气血不足。因禀赋不足，中气不能送出寒邪，寒邪久留肺经，渐成肺劳。脉象反映正虚寒伏，故治宜十全大补汤加减以扶正祛寒。", ["沉", "迟", "细", "弱"]], "12078": ["病机", "原文“肺脉微数，脾胃脉虚”，微数主虚热，虚主脾虚。产后体虚，寒化为热，金受火刑，故见午后恶寒、两颊发赤、潮热自汗。脉象提示肺热脾虚，恐成肺痿，治以大补脾土以生肺金，兼清金宁肺。", ["微", "数", "虚"]], "12079": ["病机", "原文“心脉微散，脾脉虚弱，少神”，微散主心气耗散，虚弱主脾虚。因操劳过度伤心血，心火虚不能生脾土，脾土虚不能生肺金，三经俱虚，故咳嗽吐痰短气。脉象反映心脾肺俱虚，治宜子母俱补。", ["微", "散", "虚", "弱"]], "12080": ["病机", "原文谓“心血暗耗，心脉微散”，脉微为心气不足，散为心血耗散、不能收摄，故主心脾肺俱虚。心脉微散反映心气耗散不收，形神失养，故“非佳兆”；后医泻心火更耗心气，致“形神日衰而告殁”，说明此脉主心气耗散、预后不良。", ["微", "散"]], "12081": ["病机", "肺脉紧数，紧主寒邪外束，数主邪郁化热；脾胃微细，为土虚不能生金。原文谓“土不能生金，乃元气大虚之兆”，故脉象反映寒邪犯肺、脾胃虚衰、元气大虚之病机。某医误用苦寒，更伤脾阳，致吐血虽止而音哑，说明此脉主虚寒夹邪、后天不足。", ["紧", "数", "微", "细"]], "12082": ["预后", "原文述风寒犯肺，脾胃受损，元气大虚；某医苦寒折之，“大败脾阳而洞泻，阳脱则虚汗似雨”，终致“脉见散乱、雀啄，形神、脉象死候俱现”。散乱脉为元气涣散、阴阳离决之象，雀啄为胃气已绝，故主死候，说明误治致阳脱、形神俱败，预后凶险。", ["散", "乱"]], "12083": ["预后", "脾胃二脉极细，为脾胃虚衰、气血不足；肺脉劲硬，为形寒伤肺、痰浊壅滞、脉失柔和。原文谓“此壮年当忌之脉”，故主元气大虚而肺脉劲硬，正虚邪实，预后不良。虽勉予固先后两天、宁肺之药，然脉象已示生机堪忧，属危重之候。", ["细", "劲", "硬"]], "12084": ["病机", "脾脉缓而无力，为湿伤脾土、运化失职；心脉虚细，为酒散心气、心气不足。原文谓“湿伤脾土，酒散心气，子母不能相生”，故脉象主湿浊困脾、心气亏虚之病机，与面红气短、足肿难移、小腹膨胀、小水赤涩等症相应，属虚实夹杂之候。", ["缓", "虚", "细"]], "12085": ["病机", "心脉微数代散，微为心气不足，数为虚热内扰，代为心气断续，散为心神涣散；肾脉虚细，为肾水亏虚。原文谓“肾水不能上潮，心火不能下降，坎离不交，水火未济”，故脉象主心肾不交、水火未济之病机，与游魂证、夜不能闭目、通身是汗等症相应。", ["微", "数", "代", "散"]], "12086": ["病机", "心脉散乱，为心气耗散、神不守舍；胆脉微细，为惊恐伤胆、胆气不足；脾脉沉滞，为脾气郁结、运化不畅。原文谓“操劳过度，惊恐伤胆，脾气郁结”，故脉象主心胆脾三脏俱伤、气机郁结之病机，与怔忡惊悸、怕见人、言语喃喃等症相应。", ["散", "乱", "微", "细"]], "12087": ["病机", "肾脉虚数，为肾气亏虚、虚火内扰；脾脉虚弱，为脾土不足、运化无力。原文谓“大补肾气，壮火以生脾土”，并引“寒者温之”“虚者补之”，故脉象主肾虚火浮、脾土虚弱之病机，与面现红光、色燥暗淡、少腹时疼、饮食大减、四肢困惫等症相应，属虚证深重之候。", ["虚", "数", "弱"]], "12088": ["病机", "原文谓「素患虚证，脉证皆虚，根深蒂固」，脉虚与证虚相应，说明正气亏虚日久、根本已损。虚证脉证相符，故用右归温补肾阳、兼益精血，纯补无泻，取「扶阳以配阴」之义。脉虚在此标示肾阳精血俱不足之病机，非邪实壅滞之候。", ["虚"]], "12089": ["病机", "肺脉细涩，脾胃脉沉滑。细涩示肺气不足、宣降失职；沉滑主寒痰结于胃脘。原文断为「寒痰结于胃脘之中，脾胃虚弱不能运化，土不能生金」，故气短食减、身肿面黄。脉象与「脾虚则肿」相合，痰非寻常痰药可除，故取吐法。", ["细", "涩", "沉", "滑"]], "12090": ["病机", "原文引经「脉坚大者，邪盛也。脉涩者，气虚而不流利也」，说明水臌虽多由脾肺肾三经亏虚，然脉坚大主邪水壅盛，脉涩主气虚不流利。故治多温补，仅于「脉实证实」时直决水口，攻伐之药不过治百人中三五人，脉象为辨虚实攻补之关键。", ["坚", "大", "涩", "实"]], "12091": ["病机", "肺脉沉滑、胃脉沉滞、肝脉弦急。弦急主郁怒伤肝、木旺克土；沉滞示胃气壅滞；沉滑为水湿内停。原文谓「郁怒伤肝，木旺克土，土伤肺弱」，肺气不能下降，膀胱气化不行，水留腹中而成臌。脉象正合肝郁脾弱、水湿停聚之病机。", ["沉", "滑", "滞", "弦"]], "12092": ["预后", "脾胃二脉虚细，肾脉劲弦。虚细示脾胃气弱、运化无权；劲弦为肾水泛滥、邪气劲急之象。原文按病状脉象合论，判为「二者俱在不治之例」，说明正虚而邪盛，脾肾俱败，水湿壅盛，故周身壅肿、囊肿如斗、小便极涩，脉证均属危候。", ["虚", "细", "弦"]], "12093": ["病机", "脾肺二脉沉滑有力。沉主里，滑主水湿痰饮，有力为邪实。原文因渴饮冷水、树下睡熟，寒湿内停，致腹胀、目下如卧蚕、腹有水声，断为「知系实证」，故以十枣汤加葶苈攻邪逐水，一剂而病去八九。脉沉滑有力正是水饮内结、正气未衰之实证依据。", ["沉", "滑"]], "12094": ["病机", "原文仅言「病因积水，脉证俱实」，未列具体脉象，故脉象要素为空。其意在说明积水为病，脉与证皆现实象，邪水壅盛而正气尚能任攻，故直用攻邪逐水而愈，无需它治。此条强调脉证俱实是施用攻逐之法的前提。", []], "12095": ["预后", "脾肺肾三部脉皆濡细无力，濡细主气血不足、水湿内停，无力为正气虚衰。原文谓「幸而有神，尚可缓图」，说明虽肿胀危迫、屡服峻药愈胀，然脉尚有神，生机未绝，故改用金匮肾气汤缓补，三十八帖后渐愈。脉之有无神关乎预后吉凶。", ["濡", "细"]], "12096": ["病机", "脉濡细无力，为脾肾两虚、水湿内停之象。濡主湿，细主虚，无力为气衰。腹腿肿甚乃肾虚水泛，屡用峻药攻伐更伤正气，故脉见濡细无力。翟氏以加减肾气汤两补脾肾、利水消肿，正合此病机。", ["濡", "细"]], "12097": ["病机", "肺脾肾三部脉皆虚细无力，示三脏气虚、水湿不化。虚细为气血不足之征，因饥饱劳役亏损而成水臌。先攻后补，用十枣汤攻水、肾气汤补虚，正合虚细无力之脉。逾年复发脉状更差，本气愈虚，故难治。", ["虚", "细"]], "12098": ["病机", "肝脉弦数，为郁怒伤肝、肝火偏亢；脾脉虚弱，为脾土受损、运化失职。肝失疏泄，脾失转运，肾气不化水，水势壅留腹中而成水臌。弦数主肝郁化火，虚弱主脾虚，脉症相合，故用肾气汤加减。", ["弦", "数", "虚", "弱"]], "12099": ["预后", "脾脉极细无力，为脾气衰败、气血大虚之候。少年水臌而见极细无力之脉，正虚邪盛，故曰「当忌之脉，恐非吉兆」。前服大攻大伐之剂更伤正气，脉象示预后不良。虽经肾气汤加减获安，然脉之凶险可见。", ["细"]], "12100": ["病机", "肺脉浮数，为风邪袭肺；脾胃脉缓滑，为湿滞中焦。浮主风，数主热，缓滑主湿。风湿交加，故头面肿如瓢、四肢肚腹皆肿。脉象揭示风湿相搏之病机，治宜利水祛风，用风湿两彻汤正合此脉。", ["浮", "数", "缓", "滑"]], "12101": ["病机", "肺脉浮数，示肺脏受风，风邪外袭；脾胃脉缓滑，示脾胃湿滞，湿邪内蕴。浮数主风热在表，缓滑主湿浊在中。风湿交加，故现水臌之证。祛风利湿，风湿两彻，故能从速告愈，脉象与病机相应。", ["浮", "数", "缓", "滑"]], "12102": ["其他", "此段论痢疾之名与分类，述湿热内伤、暑邪外感相合而成，初宜清热、久宜补气血，为普通治法。文中「脉症果虚、脉证果实」仅提脉症虚实之辨，未出具体脉象，故脉象要素为空。主旨为痢疾通论，非专论脉。", []], "12103": ["误治", "脾胃脉沉滑有力，肺脉沉数，示湿热邪毒壅盛于里。沉主里，滑主湿，数主热，有力为邪实。前医误用婴粟壳等涩肠止痢，致邪毒内闭，故心胸胀满、腹内痛甚、闻食则呕。此「实其实」之误治，脉象确系湿热邪毒正盛。", ["沉", "滑", "数"]], "12104": ["预后", "六脉微细无神，为真气衰败之象。患者素有烟瘾，又患休息痢，误服鸦片膏塞补，毒邪深入脏腑，正气已竭。脉微细无神反映脏腑功能衰竭，气血将绝，故断为不可救药，越三日而殁，周身皆青，乃毒瘀血滞之征。", ["微", "细"]], "12105": ["病机", "胃脉浮数有力，浮主风，数主热，此胃经风热传于大肠。所下白沫、便难、少腹刀割痛，皆风热壅滞肠腑之象。非寻常痢疾，故用羌活除风汤疏风散热，加月石涤秽而愈。", ["浮", "数"]], "12106": ["病机", "胃脉浮数有力，大便白沫而艰难，脉证相合，显系风邪客于肠胃。浮为风象，数为热征，风热搏结，故便下白沫、里急后重。用羌活除风汤疏风散热，加月石涤肠胃秽腻，使风热去而秽浊消，故获效。", ["浮", "数"]], "12107": ["预后", "脾肾两脉极细，为先后二天将败之候。患者年高久痢，所下如败血脂膏，骨瘦如柴，乃脏腑脂膏耗竭。脉细主气血虚衰，脾肾脉细尤显根本已亏，故辞不治，越十日而殁。", ["细"]], "12108": ["病机", "胃脉洪大有力，肺脉洪数，洪大为热盛之象，数主热。患者善饮酒，酒湿生热，又感酷暑，热邪内迫，血得热妄行，故下鲜血、腹痛下坠。此红痢由湿热蕴结、血热妄行所致，治宜凉血逐湿。", ["洪", "大", "数"]], "12109": ["病机", "肝脉弦数，脾脉细弱，弦数主肝旺有热，细弱主脾虚。大怒伤肝，木旺克土，肝不藏血，脾不统血，血流入大肠，故下鲜血、腹痛寒热。此木克土之证，治宜平肝健脾。", ["弦", "数", "细", "弱"]], "12110": ["病机", "肝脉弦数，脾脉微弱，木克土证甚明。弦数为肝旺，微弱为脾虚，大怒后肝气横逆，乘克脾土，致脾失统血，血下大肠。方以归芍柔肝，柴胡青皮疏肝，重用诸药以平肝健脾，切中病机。", ["弦", "数", "微", "弱"]], "12111": ["病机", "两尺脉细弱无力，脾脉更虚，细弱无力主虚寒。患儿久痢白脓，下坠腹痛，因中焦有寒，不能消化五谷，化而为白脓。脉证合参，属脾肾阳虚，故用右归饮温补下焦元气以健脾土，诸症痊愈。", ["细", "弱", "虚"]], "12112": ["病机", "两尺脉细弱无力，脾脉更虚，细弱为气血不足，虚为阳气衰微。尺部候肾，脾脉候中焦，脾肾阳虚则寒邪内生，下为白脓，故知是脾肾阳虚、寒邪作祟，治当温补兼助阳。", ["细", "弱", "虚"]], "12113": ["主病", "肺脉数而有力，为热邪壅盛；脾胃脉缓而滞，为湿浊积滞。数主热，缓滞主湿积，合之则为瘟痢，湿热积滞肠胃，故红白并下、腹痛非常、渴思冷饮，当通因通用。", ["数", "缓", "滞"]], "12114": ["病机", "肺脉数而有力，热邪上逆；脾胃脉缓而沉滞，沉滞主积垢内停。胃肠积垢不去，郁而化热，热邪上逆，故虽痢下必用通因通用之法，荡涤积垢方可取效。", ["数", "缓", "沉", "滞"]], "12115": ["主病", "六脉有力有神，年虽老确属实证。脉有力有神为邪气盛而正气未衰，如贼在室，理应驱逐，故用大承气汤泻下燥粪，不治痢而痢自止，此通因通用之效。", []], "12116": ["病机", "六脉细弱，为气血大虚之象。气虚则大肠脱出、冷汗如雨，血虚则面色晦暗，小腹奇疼亦因虚而痛。壮年可治，创补气固肠汤以益气固脱。", ["细", "弱"]], "12117": ["治法", "此段论霍乱治法，未及具体脉象。霍乱乃风寒暑湿饮食之邪糅杂，吐泻交作，生死存亡系焉。治分湿、干、温毒三种，湿则利湿，寒则温中，先用针止呕吐，后用药止泄泻，并强调脉实则泻、脉虚则补。", []], "12118": ["误治", "六脉欲绝，冷汗似雨，四肢如冰，满面浮红，声音已哑，大渴思饮，此元阳失散、真火飞越之证。前医误用止渴清热，更伤阳气。脉欲绝为阳气衰微，浮红为虚阳上浮，当引火归源、纳气归肾。", []], "12119": ["病机", "霍乱吐利后伤阴亡阳，是案乃阴竭，元阳浮越于外。引《灵枢》清浊相干乱于肠胃之论，与《伤寒论》338条证治相似。翟氏投参耆桂附纳气回阳之品，二剂而愈，可见阴竭阳浮之病机。", []], "12120": ["死脉", "原文以“屋漏”形容脉象，指脉来如屋漏水，良久一滴，断续不匀，是胃气已绝、真脏脉现之象。患儿霍乱而见二目直视、口张不合，为阴阳离决、神气将散之候，故脉见屋漏即主死，出门十余步而亡，正合此脉所主之危候。", []], "12121": ["病机", "脉细劲有力，细为阴血不足，劲为邪毒内郁、气血壅滞。原文断为“瘟毒蕴藏”，正因毒邪深伏，脉道被遏而现细劲有力，非虚细可比。故以刮痧、挑刺放黑血、针足三里内关、服解毒活血汤取效，脉证相合，主瘟毒内蕴之霍乱。", ["细", "劲"]], "12122": ["病机", "六脉沉迟，沉主里、迟主寒，合而观之，知“内有阴寒”困阻中焦，阳气不运，故上吐下泻、腹内疼痛非常。吐泻不能服药，先针尺泽放毒血、针三里调阴阳、针中脘止吐泻，继以藿香正气散温散寒湿，脉证相应，主阴寒内盛之霍乱。", ["沉", "迟"]], "12123": ["死脉", "原文“六脉按至附骨无有”，即脉沉伏至骨而不可得，是阳气败绝、脉气不通之象。见面色灰黄、指甲皆清、四肢抽搐、吐泻腹疼欲绝，皆阴阳将脱之危候，故断为“真逆症”，纵有良医亦无能为，去后遂殁，此脉主死。", []], "12124": ["病机", "六脉细弱而“幸尚有神”，细弱为气血两虚之象，原文断为“邪毒已尽，元气不复”，故无须用针，宜参术枣仁汤补益。又知此妇操劳过度、恸伤心血，脉细弱正合气血亏虚、心神失养之机，主霍乱后元气未复之虚证。", ["细", "弱"]], "12125": ["病机", "六脉微细而“幸而未绝”，微为阳衰，细为血少，合见冷汗如雨、四肢抽搐、精神昏愦、声音已哑，原文断为“邪尽正虚”“气虚血亏，不能荣养经络”。脉微细显然无邪，故主正虚阳衰，治以参耆桂附汤大补回阳，脉证相符。", ["微", "细"]], "12126": ["病机", "原文“六脉闭绝”，指脉气闭塞不通、按之若无，非真元已竭。干霍乱欲吐不能、欲泻不得，绞肠疼痛、面白唇青、冷汗如雨，乃邪毒壅塞、气机闭阻、阴阳不相顺接所致。故急以盐汤探吐、针刺放血开闭，脉闭绝正主邪闭气阻之实证。", []], "12127": ["病机", "六脉洪大，洪为邪热亢盛、气血沸涌之象，大则病进。原文断为“瘟毒正盛”，故吐泻交作、绞肠疼痛、两腿抽搐、指甲发青，皆毒热壅盛、内扰筋脉之候。针尺泽委中放毒血、针诸穴、服解毒活血汤而愈，脉洪大正主瘟毒炽盛之实热证。", ["洪", "大"]], "12128": ["病机", "原文谓霍乱三日，呕吐泄泻不止而脾脉虚细、肝肾脉濡弱，断为「邪尽正虚」。吐泻耗伤气血，脾虚则脉细，肝肾不足则濡弱，正虚已甚，故云「补犹恐不及」，不可再针。脉象与腹疼如故并见，是邪去而正未复，主虚证当补，与十全大补汤相应。", ["虚", "细", "濡", "弱"]], "12129": ["病机", "六岁小儿霍乱吐泻二日，脉皆细小，原文断为「气血双亏」。吐泻伤津耗气，脉道不充故细小；幸有神、面无败色，说明胃气未绝，预后尚可。细小之脉与吐泻不止相应，主正虚，故先针足三里、中脘行补法，继用参苓桂附汤温补。", ["细", "小"]], "12130": ["病机", "霍乱三日，二目天吊、角弓反张、冷汗、面唇青，六脉细濡，原文断为「虚证俱现」。吐泻太过，气血少而不能养筋，故筋急反张上视；细濡为气血两虚之脉，与诸虚候相应。原文斥作风治之误，主用十全大补汤补气血，脉复元则冷汗收。", ["细", "濡"]], "12131": ["病机", "霍乱吐泻已止，而虚汗淫淫、精神恍惚、四肢冰冷、饮食不进，六脉虚细。原文谓「吐泻太甚，元气大伤，非补不可」。虚细为元气亏虚、脉道不充之象，与冷汗、肢冷、神恍相应，主大虚之证，故用参苓桂附汤加减温补元气。", ["虚", "细"]], "12132": ["病机", "七十余老妇霍乱，泻止而吐不停，胃脉极细，原文断为「邪去正虚」。极细示胃气衰微、气血不足；吐不止、饮食不进，是气虚不能降下而反上泛，故前医降气之品无效。脉与呕吐不止、命如游丝相应，主虚，治当温补，用参苓桂附汤。", ["细"]], "12133": ["其他", "原文未载脉名，仅言「六脉皆无」，属脉象描述而非具体脉名，故脉要素从缺。面唇极青、四肢冷过时膝、六脉皆无，是急症气血闭阻、阳气暴脱之候。原文以针刺放血、吹丹灌散急救而愈，主旨记急症针法之效，故归其他，不涉平脉死脉之断。", []], "12134": ["病机", "喉证六七日，六脉洪数，原文断为「温毒正盛」。洪为邪热鼓盛，数为热象，与咽关结核如枣、几乎肿闭相应，是热毒壅结喉间、将成喉痈之候。脉证合参，主温毒实热，故以刀刺核放脓血，继用清温化毒而愈。", ["洪", "数"]], "12135": ["病机", "喉证初起，身如被杖、寒热如疟、疼痛、饮食锐减，六脉洪数浮沉有力。浮沉皆有力，示邪气盛实，非虚象；洪数为热毒内蕴，原文谓「感邪太深，内藏红痧之毒，最难透出」。脉与寒热、发闷极重相应，主实热壅盛，故用清肺汤透痧，后以承气下秽而愈。", ["洪", "数", "浮", "沉"]], "12136": ["病机", "原文载「六脉洪数浮沉有力」，洪数主湿热疫毒炽盛，然浮沉并见，作者指其「脉既浮不应沉，即沉不应浮」，认为脉象描述与「一阴一阳结谓之喉痹」之湿热疫毒纵贯三阳病机不符，故本条实为对脉象合理性的辨析，非直接主病。", ["洪", "数", "浮", "沉"]], "12137": ["病机", "肾脉虚弱、中取不见，肺脉虚极而数，乃肺受疫邪而肾水亏虚，母病及子、子不能救母。虚数之脉主毒气不能传送，故白喉缠绵不已，症见口干无津、舌生芒刺，皆肾水不能上潮救肺之验。", ["虚", "弱", "数"]], "12138": ["误治", "疫喉本属温毒，然六脉细微无力，乃因某医「用凉药太过，阳变为阴」，真阳衰微。脉微细无力主阳气虚衰，故舍证从脉，不敢再用凉药，以桂附汤加减冷服，温阳救逆而获效。", ["微", "细", "虚"]], "12139": ["病机", "六脉细微无力乃真阳衰微之象，满喉皆烂属虚火假热。脉症似相矛盾，翟氏「舍证从脉」，把握真阳衰败之本质，投桂附汤加减温补真阳，使假热自退，足证其识脉辨证之精。", ["微", "细", "虚"]], "12140": ["预后", "白喉败证俱见，诊得「六脉皆无」，痰声如锯，天庭黑暗，脉无胃气神气，乃正气溃败、阴阳离决之死候，故断为「不可救药」，当日而殁。此段以脉无神主预后不良。", []], "12141": ["主病", "肺胃脉洪大有力，年虽老而病属有余，洪大有力主邪热炽盛、正气未衰。白喉见肺胃实热，故用养阴清肺汤加大黄、连翘清热解毒通腑，一帖而满喉白膜退，继服而愈。", ["洪", "大"]], "12142": ["预后", "白喉五日，满喉皆白，呛食声哑，症似危重，然「幸脉有神」，脉有胃气神气则生机尚在，故守养阴清肺汤而病减，后以便燥难解，予小承气汤通腑收功。此以脉有神断预后可治。", []], "12143": ["主病", "肺胃二脉沉数有力，沉主里、数主热、有力主实，合参咽痛发闷、饮食难进、午后潮热，断为温毒喉症之里实热证，故非下不可，用调胃承气汤一服而愈。", ["沉", "数"]], "12144": ["病机", "原文谓肺胃二脉沉数有力，沉主里、数主热、有力为实，合而示温热之毒内陷阳明，燥实内结而津液受伤。故饮食难进、午后潮热，正是燥实内结、热毒伤津之候，投调胃承气汤泻下燥实而愈，脉证相合。", ["沉", "数", "实"]], "12145": ["预后", "白喉重证见满喉皆白、二目天吊、湿汗淫淫、痰声似锯，而六脉微细，是温毒炽盛而正气已衰、阴液将竭之象，故翟氏初诊即辞。后针十宣、尺泽出血泻毒，内服养阴清肺汤加大黄、芒硝、犀角、黄连，便下臭秽而减，脉微细示正虚邪实之危候。", ["微", "细"]], "12146": ["病机", "此段论腹痛有虚实、内伤外感、气滞血瘀、邪祟诸端，原文未出脉名，故脉象要素为空。其要在审病源、因势调治：内伤七情虚则补中带调，外感六淫实则去邪固本，虚中挟实攻补兼施，气血郁结则开瘀行滞，示腹痛当辨虚实而治。", []], "12147": ["病机", "六脉浮中沉皆无，推筋著骨指下劲硬、似有若无，是寒邪深伏、阳气闭阻之沉寒痼疾，脉伏而牢硬正示阴寒内结、气血凝滞。故冒雨受寒腹痛日久，饮食渐减、面黄肌瘦，非大热药不能破其沉寒，用祛寒温里汤而愈。", ["沉", "牢", "硬"]], "12148": ["病机", "此按引《素问·举痛论》寒气入经稽迟、泣而不行，客于脉外则血少，客于脉中则气不通，故卒然痛，说明冒雨受寒腹痛久之成沉寒痼疾之理。原文未出脉名，脉象要素为空，全段以寒凝血滞、经络急引释痛之病机。", []], "12149": ["病机", "诊其脉乱无统绪，古书云乱无统绪者虫积也，脉乱示气血为虫所扰、升降失序。证见腹大如盆、面黄肌瘦，饥时疼甚、饱时略减，正合虫积之候，故用杀虫汤下蛔虫近千条而痛减，后以八珍汤调理脾胃收功。", ["乱"]], "12150": ["病机", "六脉参差，又见唇现白点，饥时疼甚，参差之脉示气血不调、虫扰中焦，唇现白点亦为虫积之征。素有胃气疼疾二十年不除，实系虫疼而非单纯胃痛，故用雷丸扫虫汤泻下红虫尺余者六条而病如失，原文未明脉名。", []], "12151": ["病机", "肝肾二部脉极虚细，虚细示精血亏虚、肝肾不足。肾主少腹，肾虚不能养肝，肝亏多燥，燥则暴怒而痛，故少腹疼时四肢厥逆、冷汗如雨、唇口皆青。乙癸同源，宜母子两济汤肝肾同治，脉虚细正合虚证之病机。", ["虚", "细"]], "12152": ["病机", "原文未提脉象，专论少腹痛病机。指出“肾水亏不能涵养肝木，使肝脏暴燥”，肝失条达柔和之性，气妄行而致经脉所络少腹痛。此属子病窃母气、肝肾同病，故治以滋水涵木，不治疼而疼自止，体现治病求本。", []], "12153": ["病机", "肝脉弦紧，弦主肝病，紧主痛，乃木克土之证。原文谓“肝性最急，急则易于作痛”，肝急乘脾，故腹痛呕吐。治以补肺平肝，因肺金能制肝木，使肝平则腹疼自止，体现五行相制之法。", ["弦", "紧"]], "12154": ["病机", "脾胃两脉浮中不见，惟重按至筋骨沉滞有力，沉主里，滞主积，知是胸膈停食之故。更见食发呕、疼处拒按，皆实积内停之征。前服调气疏肝无效，正因未识停食之因，故用六神汤加减消导。", ["沉", "滞"]], "12155": ["病机", "脾胃脉沉滑，沉主里，滑主痰，此是湿痰郁结所致。湿痰内结，气机不畅故腹痛；痰郁化热，故先潮热；痰浊上逆，故吐痰不止。治用瓜蒂散加减涌吐痰涎，以去病源。", ["沉", "滑"]], "12156": ["病机", "脾胃脉沉滑，乃湿痰结于内无疑。涎郁气机不畅故腹痛，湿邪郁而作热故见潮热。治用瓜蒂散加味涌吐以去病源，后用八珍汤扶正，先攻后补，层次分明。", ["沉", "滑"]], "12157": ["其他", "六脉和平，无药可用，辞而不治，然患者腹痛雷鸣。后忆本草丹参一味能治腹疼如雷鸣，试用而愈。此案脉症不符，脉平而症急，提示不可仅凭脉断病，当参合症候，亦见丹参治雷鸣腹痛之效。", ["和平"]], "12158": ["病机", "肝脉弦急，脾脉滞涩，弦急主肝气郁急，滞涩主血行不畅，此系气郁血滞之故。气郁则寒热往来，血滞则少腹疼痛。治用归附调气汤，行气活血，气血调则痛止。", ["弦", "急", "滞", "涩"]], "12159": ["病机", "太阴脾脉郁滞，郁滞主积滞内停，确系实证。每日午后腹痛，呕吐酸水，皆食积化热、胃气上逆之象。初用枳实厚朴汤加大黄未效，加焦山楂、神曲消导，泻下燥粪而愈，证明积滞在肠胃。", ["滞"]], "12160": ["病机", "原文未明言具体脉象，仅述“诊其脉知系肝气郁结，木不条达”。肝气郁结，气机不畅，不通则痛，故见腹痛时作时止；气郁则阳气不达四末，故痛时手足皆青、冷汗淫淫。脉象虽未详，但据脉断为肝郁，当有弦象，主肝气不舒、木失条达之病机。", []], "12161": ["病机", "肾脉沉细无力、命脉极虚，沉细无力为肾阳不足、命门火衰之象。老人肾虚受寒，肾与膀胱相表里，肾经虚寒则膀胱津液不能化气，故小便艰涩、腹痛。脉沉细无力正合肾阳虚衰、寒凝气化不行之病机，非热传膀胱之实热证。", ["沉", "细", "虚"]], "12162": ["病机", "两尺脉洪滑有力，尺部候下焦，洪滑有力主湿热壅盛。湿热壅遏下焦，气机不通，故少腹疼、小便赤涩；热郁于内，阳气不达四末，故四肢厥逆；湿热伤津，故渴思饮水。洪滑有力为实热之脉，与行气散寒药不效相印证，主湿热壅遏下焦之病机。", ["洪", "滑"]], "12163": ["病机", "脾脉涩而中实，涩主宿血，实主邪结。右肋疼痛、痛不移处，为瘀血阻络之征；肌肤锐减，乃瘀血内结、新血不生所致。脉涩而中实，正合瘀血内停、络脉不通之病机，故断为病血作祟，主宿血瘀滞之证。", ["涩", "实"]], "12164": ["病机", "胃脉洪大有力，余脉和平，洪大有力主胃中实热。胃热炽盛，火炎土燥，故渴思饮冷、呕吐不止；热壅气滞，不通则痛，故腹痛。脉洪大有力独见于胃部，正合胃家实热之病机，主胃中积热、火炎土燥之证。", ["洪", "大"]], "12165": ["病机", "胃脉洪大有力，痛时呕吐不止，乃胃家实无疑。洪大有力为实热壅盛之脉，胃中实热，气机闭塞不通，故痛；胃气上逆，故呕吐。服大承气汤使胃气下行，塞者通、闭者畅，实热去则痛自止，脉证相合，主胃家实热壅滞之病机。", ["洪", "大"]], "12166": ["小儿", "原文未出具体脉象，专论小儿脉不可凭、问不可问，惟望诊可用。小儿啼哭则脉乱，故脉诊难据；当察气血刚柔、神情胜馁、禀赋厚薄，参以三关经纹。强调小儿脏腑娇嫩，无大实者不可妄攻，主小儿诊法之难与慎攻之旨。", []], "12167": ["小儿", "原文举脉之浮沉迟数，言大人病能望闻问切，小儿惟三关虎口。然作者认为小儿无七情之病，所病皆风寒暑湿燥火六淫，外感为客邪易治。浮沉迟数分表里寒热，小儿虽脉不可凭，然六淫之病仍有可辨，主小儿病多外感、治当别于成人之论。", ["浮", "沉", "迟", "数"]], "12168": ["其他", "原文未识脉名，仅言「脉不可凭」，强调小儿脉诊难凭、问诊又难，医者若捕风捉影则虚实颠倒。此段非论具体脉象所主，而是慨叹小儿脉证难辨，告诫不可单凭脉断病，须结合阅历与问诊，属医论杂感，故列其他。", []], "12169": ["病机", "原文「小儿脉如悬丝」，即细弱欲绝之象，主先天薄弱、元气虚衰。面黄身肿而脉细如丝、声音低馁，又服克伐药过多，显系虚证，非本实症。脉细为气血不足、元气散失之征，故用十全大补汤温补收散失之元气，服后肿消食增而愈。", ["细"]], "12170": ["病机", "原文以「脉细、声低、面黄」为虚证之据，脉细主气血不足，面黄身肿非实邪壅滞，乃虚不运化。又服消药不效，反证非实。故按虚证论治，用温补取效。此段紧扣脉细辨虚实，说明面黄身肿见细脉当从虚论，不可陡用消散。", ["细"]], "12171": ["病机", "原文「六脉沉紧，重取微滑」，沉主里，紧主寒主痛，滑为痰积。寒热往来、腹疼咳嗽吐痰，肉脱骨立，显系大寒积于肠胃，痰饮内聚。沉紧为寒邪深伏之象，重取微滑示痰积于中。故诊为大寒证，用桂附汤温中散寒，使元气复而病愈。", ["沉", "紧", "滑"]], "12172": ["病机", "原文从「脉沉紧著眼」诊为大寒证，沉主里、紧主寒，与《金匮要略》寒疝病「脉沉紧」同义。大寒积于肠胃，非温中散寒则元气难复，故取「寒者热之」之法，温补脾肾以复元气。此段以脉沉紧为辨证关键，说明沉紧主里寒积滞之病机。", ["沉", "紧"]], "12173": ["病机", "原文「六脉沉而有力，浮取不见」，沉主里，有力为实，浮取不见示邪结于内。外见四肢懒惰、腹大疼痛而似虚，实为「大实有羸状」。沉而有力说明积滞内结、外虚内实，故用补中消积汤攻补兼施，消积而不伤正。", ["沉", "有", "力"]], "12174": ["病机", "原文「六脉浮紧」，浮主表，紧主风主痛。破皮出血后口噤、握固、角弓反张，显系风邪乘破伤而入，引动肝风。浮紧为风邪在表、筋脉拘急之象，故诊为破伤风，证最凶险。用逐风丹祛风解痉，说明浮紧主外风袭表、筋脉紧急之病机。", ["浮", "紧"]], "12175": ["病机", "原文「脾脉滑数，它脉和平」，滑主痰湿，数主热，独脾脉见之，说明湿痰积热蕴于脾。泄泻日久、寒热药不效，正因脾有湿痰积热作泄，非单纯寒热。古云「五泄皆属于湿」「火泻者肠鸣」，故用化痰清热汤，二帖病减，四帖痊愈。", ["滑", "数"]], "12176": ["病机", "原文以脾脉滑数辨为湿痰积热作泄，滑主痰湿内蕴，数主热邪内迫，故脉滑数反映湿热痰积交阻于脾。然作者指出仅凭此脉理由不足，需以药测证，当伴泻而肠鸣、大便不爽、粪黄而臭、舌苔黄腻等湿热积滞之象，说明脉象须与症候合参方能确认病机。", ["滑", "数"]], "12177": ["病机", "六脉虚细欲绝，虚为元气不足，细为阴血亏少，欲绝示脉气衰微至极。患儿疟疾半载，腹块如碗，饮食日减，面目黄肿，消积破块之药屡服无效，反伤正气，故脉见虚细欲绝，反映元气亏损已极、正虚不能抗邪之病机，急当补养。", ["虚", "细"]], "12178": ["病机", "六脉离乱，毫无统绪，即脉来散乱无伦次，非正常脉序。王肯堂谓此乃客忤病，因秽恶之气闭塞心窍，神明昏乱，故脉气亦乱。患儿吐泻、指甲微青、精神昏愦如中鬼祟，正合秽浊闭窍、气机逆乱之病机，脉乱为邪闭神乱之征。", ["乱"]], "12179": ["病机", "本条重申六脉离乱毫无统绪，据此悟到客忤秽恶证。脉乱无统绪，反映秽浊之气闭塞心窍、气机逆乱，神明失主。结合患儿吐泻，药不能进，故用熏面法以香辟秽，说明脉象乱而症见神昏吐泻，当辨为客忤秽恶闭窍之病机。", ["乱"]], "12180": ["病机", "原文未识出脉名，仅言诊脉断为柔痉。患儿泄泻日久，瘦至肉脱骨存，二目上视，口紧不开，两手握固，湿汗淫淫，抽搐频作，此乃大病后津血亏耗、筋脉失养之柔痉，非风邪所致。脉象虽未明言，但结合症候，病机为吐泻伤津、虚风内动，误作风治则危。", []], "12181": ["病机", "六脉紧细，紧主积块内结、气机壅滞，细主气血不足。患儿痞块肚大青筋，午后发热，消积破块药过服而饮食渐少、形容憔悴，故脉紧细为虚中挟实之象：块积内结故紧，元气亏虚故细。攻之元气不支，补之块从何消，治当消补兼施。", ["紧", "细"]], "12182": ["病机", "脾肺脉有力，肝脉虚数。疟本属肝，肝脉虚数者，虚为肝阴不足，数为邪热内扰，反映疟疾日久，肝病及脾，脾母受伤，肾肺连带受累。骨瘦如柴、面目浮肿、腹块按疼，皆肝病传脾、虚实夹杂之候，故治以子母两援汤补脾母以益肾子。", ["虚", "数"]], "12183": ["病机", "肝肺脉均滑数，滑主湿浊内蕴，数主热邪亢盛，故断为湿热为病。小儿痿证卧床年余，湿热浸淫筋脉，气血阻滞，致肢体痿废不用。脉滑数反映湿热壅遏肝肺，非清热除湿不能瘳，故用起废汤清利湿热而愈。", ["滑", "数"]], "12184": ["病机", "肝肺脉均滑数，滑主湿、数主热，合为湿热内蕴。湿热伤津，宗筋失润，故成痿证。原文引《痿论》'阳明主润宗筋'，说明湿热伤津则筋脉失养，与筋痿、脉痿相应。治以清热利湿、柔筋养阴，湿热除则筋脉柔而痿自痊。", ["滑", "数"]], "12185": ["主病", "六脉洪盛有力，沉取亦然，洪盛主热盛，有力为实。参以便秘溲赤、渴欲冷饮、口气臭、痘色紫红板滞，脉证相参确系实热毒盛之证。故用二花解毒汤加大黄清热攻实，待热毒衰其半即止，恐伤元气。", ["洪", "盛", "有", "力"]], "12186": ["病机", "六脉洪盛有力为实热之脉，洪主热盛，有力主邪实。合便秘溲赤、渴欲冷饮、痘色紫红，知热毒壅盛属实。原文强调'确系实证无疑'，故清热凉血解毒，待热毒衰大半改用平淡之剂，始终顾护元气。", ["洪", "盛", "有", "力"]], "12187": ["妇人", "本段未出具体脉象，专论妇人病难治。原文谓妇人病情隐微难见，望闻问多不便，'惟凭切脉'，然不可尽凭，须'当从证从证，当从脉从脉'。指出妇人病多由思虑不遂、郁怒伤肝内伤所致，强调临证制宜、不拘纸上陈言。", []], "12188": ["病机", "六脉极细欲脱，细为血少，欲脱为气随血脱之兆。因郁怒伤肝，天癸不行，忽下死血成块十余枚，昏倒肢厥目闭口开，乃血脱气陷。故引张洁古'血脱者补气'，急用补气以摄血固脱。", ["细", "欲", "脱"]], "12189": ["病机", "六脉沉涩，沉主里、涩主血瘀。经水暴来昏晕，医用十灰散收涩止之，经虽住而少腹苦疼拒按、寒热谵语，显系瘀血不尽、补益收涩之害。原文引景岳'实其实而死者'，故用攻血汤下瘀血而诸症痊。", ["沉", "涩"]], "12190": ["病机", "六脉沉涩为瘀血内阻之脉，沉主病在里，涩主血行不畅。此案少腹拒按，乃炭类收涩止血后瘀血留滞之证。原文谓'凭脉识证，凭证处方'，改用养血活血剂，使瘀去血和，说明出血昏晕不可徒事收涩。", ["沉", "涩"]], "12191": ["病机", "六脉如丝，为气血衰微欲脱之象。因大怒后经停，急下败血臭物二十余块，昏晕欲绝，乃气随血奔、血脱气陷。故引时珍'血脱补气'，用黄耆补血汤补气以生血摄血，与脉如丝之虚脱相应。", ["如", "丝"]], "12192": ["病机", "六脉洪大且数，为脏腑多热之象；肝脉弦急，乃郁怒伤肝、肝叶开张、血不能藏之征。热迫血妄行，故赤带成矣。脉洪数主热盛，弦急主肝郁气逆，与“郁怒伤肝”“赤带”相应，说明病机为肝郁化火、血热妄行。", ["洪", "大", "数", "弦"]], "12193": ["病机", "六脉极虚无力，为气血大亏之候；幸脉神不脱，说明胃气尚存。白带如稀脓、少腹锥痛、潮热燥渴、日轻夜重，乃虚阳外越、脾湿不化之象。前服利湿清热药反伤正气，故脉虚无力，病机属虚寒夹湿、本虚标热。", ["虚"]], "12194": ["病机", "六脉极虚无力，反映正气大虚；潮热燥渴为虚阳外越，非实热可知。脾湿不化，故用术、苓、桂、附从治。脉虚无力与虚阳外越、脾湿不化相应，说明病机为脾肾阳虚、湿浊内停、虚阳上浮，故放胆温补而效。", ["虚"]], "12195": ["病机", "脾脉虚弱，肝脉沉滞而弦，为郁怒伤肝、木旺克土之象。肝气不疏，经水欲下而气机牵掣，故行经前寒热腹痛、经色深紫成块、经行七八日方净。脉沉滞主气郁，弦主肝旺，虚弱主脾虚，病机为肝郁脾虚、气滞血瘀。", ["虚", "弱", "沉", "弦"]], "12196": ["其他", "本段为按语，总结翟氏凭脉识病、凭证立法的诊治特点，未载具体脉象。原文强调脉证合参，先辨脉象以识病机，再据证候以定治法，体现脉诊与辨证相结合的原则，故归入其他类。", []], "12197": ["病机", "脾脉虚极，肝脉细急，为泄泻日久、脾肾两伤、肝木为贼之候。泻伤脾肾，肝木耗肾水而克脾土，饮食减则血无从生，故经水三五月一行。脉虚极主脾肾亏虚，细急主肝郁化火，病机为脾肾虚损、肝木乘脾、血源不足。", ["虚", "细", "急"]], "12198": ["病机", "六脉沉紧，为寒邪内侵、气血凝滞之象。行经遇雨，寒甚经止，腹疼寒热往来，正是血得寒则凝、经隧不通所致。脉沉主病在里，紧主寒主痛，与“寒甚”“经水遂止”相应，病机为寒凝血瘀、冲任阻滞。", ["沉", "紧"]], "12199": ["病机", "脾肾脉虚而兼缓，肝脉弦劲，为肾水不养肝木、木旺土衰之候。脾虚不化精微，湿浊下走膀胱，故白带三年不愈。脉虚缓主脾肾亏虚，弦劲主肝木偏亢，病机为脾肾两虚、肝木乘土、湿浊下注，治宜补脾养肾平肝。", ["虚", "缓", "弦", "劲"]], "12200": ["主病", "肝脉沉弦，它脉平和，沉主气郁于里，弦主肝郁气滞。气郁经闭五月，少腹时疼、寒热、鼻衄，皆肝郁化热、血瘀不行之象。脉沉弦独见于肝，说明病位在肝，气机郁结，血行不畅，故用开郁和血而愈。", ["沉", "弦"]], "12201": ["病机", "六脉沉滞，沉主里，滞主气血凝涩。产后取凉，寒邪客于血分，寒凝血滞，故寒热交作似疟。脉沉滞反映寒凝血脉、气血不畅之病机，非疟邪为患，故治疟罔效，当温经散寒活血。", ["沉", "滞"]], "12202": ["病机", "六脉沉滞，为寒凝血滞无疑。沉主病在里，滞主气血涩滞不行。因受凉而致寒凝，血得寒则凝，脉道不利，故见沉滞。此脉象直接说明寒邪内侵、血行瘀滞之病机，故用温经补气活血、羌活祛寒以根治。", ["沉", "滞"]], "12203": ["病机", "肝脉沉弦有力直冲至寸，脾脉滑数微虚。沉弦有力主郁怒伤肝、肝气横逆；滑数主痰热；微虚为脾虚。木旺土衰，脾虚生痰，肝火上冲，故脇疼如刀刺、吐鲜血。脉象揭示郁怒伤肝、木旺土衰、痰热内蕴之病机。", ["沉", "弦", "滑", "数"]], "12204": ["病机", "六脉极虚细欲脱，虚细主气血大亏，欲脱为阳气衰微。孕妇禀弱，泄泻日久，饮食日减，又误用凉血安胎，更伤脾胃阳气，气血生化无源，胎失所养。脉象说明气血虚极、脾肾阳衰、胎元不固之病机，故用十全大补汤温补而愈。", ["虚", "细"]], "12205": ["妇人", "左关滑数极虚细，两尺重取虽无力亦不绝。滑数主孕脉，虚细为气血不足；两尺不绝为胎元未损。前医误作经闭破血，致腹疼下坠、饮食大减。脉象说明虽气血虚细，但孕脉滑数仍在，胎元尚存，故急服安胎药而母子俱安。", ["滑", "数", "虚", "细"]], "12206": ["妇人", "寸洪关滑，两尺不绝。洪滑为孕脉之象，尺脉不绝主胎元未损。前医误作经闭破血，几致损胎。脉象说明此为真胎妇脉，非经闭实证，故令勿药调养，十月产男。此段警示少妇经闭当慎辨孕脉。", ["洪", "滑"]], "12207": ["病机", "心脉沉滞而数，脾脉数而有力。沉滞主心气抑郁，数而有力主脾热郁结。思虑伤脾，心气郁结，二阳郁热，故经闭、寒热、咳嗽、燥红、瘰鬁。脉象说明心脾郁结、二阳热盛之病机，治宜开心窍、养脾阴、解肝郁。", ["沉", "滞", "数"]], "12208": ["妇人", "脉肉肿甚厚，浮中沉均不得，推筋著骨诊得寸洪关滑，两尺不绝，左手大于右手。水气在表，气血养胎，故脉象虽为水肿所掩，然洪滑之象显于寸关，尺脉不绝，左手大，为男胎之兆。此非水臌，乃妊娠兼水气，病机在肺有水气，气血养胎，水停表分。", ["洪", "滑"]], "12209": ["病机", "脾肺二部脉濡细无力，濡主湿、细主虚，脾肺气虚，气血双亏，中气下陷，无力升提，故子宫脱出，色黑紫大如茄。此脉象说明气血大虚，升举无力，非大补升提不可，与阴茄症相应。", ["濡", "细"]], "12210": ["预后", "六脉虚细欲脱，虚细为气血大亏，欲脱则元气将绝。产后痢三月未愈，肉脱骨存，面黄唇白，言语低微，脉证相符，故辞不治。此脉示气血耗竭，胃气将败，预后不良，虽勉力施治，吉凶难定。", ["虚", "细"]], "12211": ["病机", "脾脉虚弱无力，命门脉细微，幸而均有神。虚弱为脾气不足，细微为命门火衰。火衰不能生土，故泄泻日久，夜间尤甚。此脉说明火不生土，脾肾阳虚，与五更泻、完谷不化相应，治当温补命火，兼顾脾阴。", ["虚", "弱", "细", "微"]], "12212": ["病机", "肺脉沉涩，脾脉虚弱无力。沉涩为气郁不降，虚弱为脾虚不运。思虑伤脾，脾气郁结，母病及子，肺气不降，故呃逆生焉。此脉说明脾肺气郁，升降失常，与呃逆、胸闷相应，治宜降气开郁。", ["沉", "涩", "虚", "弱"]], "12213": ["妇人", "孕脉俱现，惟虚弱过甚。虚弱为气血不足，虽为喜脉，然胎元不固，胎不长者，因冲任血海不足，阳明气血亏虚。此脉说明脾虚血少，胎失所养，与胎萎不长相应，速补脾养血，培养胎元，免小产之患。", ["虚", "弱"]], "12214": ["病机", "胃脉沉实有力，肺脉洪大，此子母俱实之证。沉实为燥屎内结，洪大为肺热上壅。肺气不降，脾津不布，化为痰涎，噎膈由生。此脉说明大肠燥结，肺胃实热，与噎膈、便秘相应，治当通下泻实。", ["沉", "实", "洪", "大"]], "12215": ["治法", "胃脉沉实有力，肺脉洪大，即为立法之准绳。沉实主燥结，洪大主热壅，此上病治下，反治法之依据。若舍下治上，徒用化痰降逆，则魄门闭塞，必成关格。此脉说明病本在下，当通腑泻实，为立法之准绳。", ["沉", "实", "洪", "大"]], "12216": ["病机", "原文诊得肝肾二脉濡细无力，濡为湿象而细为血少，无力则正气不足。肝为血脏、肾主胞胎，二脏虚亏则胎失所养，故屡孕屡堕。此脉不主外邪，而主肝肾精血内亏、胎元不固之病机，与连续小产、怀胎恐堕之症相应，故用大补肝肾之品以固胎。", ["濡", "细", "虚", "无力"]], "12217": ["病机", "肺胃脉洪数有力，洪为阳盛，数为热，有力为实。原文谓年虽老而病有余，大肠有结粪停滞不行，下窍不通必反于上，肺脉洪数实由此也。故洪数非肺胃本病，而是大肠燥结、腑气上逆之反映，与食后呕吐尽净、四月不愈之反胃症相应，治当通下而非清肺胃。", ["洪", "数", "有力"]], "12218": ["病机", "脾胃脉洪盛有力，洪盛为阳明热盛，有力为实火内炽。原文断为阳明胃经实火，胃多气多血，齿龈属胃，胃火上冲则血随火升，故齿龈出血碗许。此脉主实火迫血妄行之病机，与每日出血、十灰散止血无效之症相应，当泻胃火而非单纯收涩止血。", ["洪", "盛", "有力"]], "12219": ["预后", "原文未识出脉名，仅言六脉无败象。患者郁怒日久，如痴如迷、问之不语、自言自语、不食、摇发，前医顺气开郁化痰及痰火治法皆无效，病势沉重已备后事。六脉无败象说明脏腑真气未绝，故虽奄奄待毙而尚有生机，与败脉主死相对，为判断可治与否的预后依据。", []], "12220": ["死脉", "脉见鱼翔，为七怪脉之一，指脉来如鱼游翔，头定尾摇，若有若无，是元气将绝、真脏之气外露之象。原文形脉俱败，目闭口开、痰声如锯、脱汗似油、精神全失，形与脉俱败，故断不可救药。此脉主脏气竭绝之死候，与类中风脱证诸危象相应，预后天亡。", ["鱼翔"]], "12221": ["病机", "初诊肝脉弦数已极，弦为肝风，数为热，极则风火将动，故引诸风掉眩皆属于肝，恐风将作。后见目闭口开、两手握固、六脉洪大无伦，洪大为热盛，无伦为脉失常度，是类中风之热、风火相煽之病机，与猝然昏仆、握固不语之症相应，故刺穴泻热、平肝清热而愈。", ["弦", "数", "洪", "大"]], "12222": ["其他", "本段未识出脉名，通篇论疡科与内科同源之理，谓疮疡分险顺逆、纯阳纯阴半阴半阳，须明经络脏腑部位方能判生死，并斥按穴生疮主吉主凶之说为守株待兔。所论不在脉象而在辨证方法，故脉象要素为空，主旨属疡科辨证之泛论，非主病、病机或死脉之具体脉例。", []], "12223": ["病机", "原文以脉数有力辨阳证、脉数无力辨阴证。数主热，有力为实，故阳证红肿痛甚属热毒壅盛；数而无力为正虚邪陷，故阴证漫肿色黯属气血不足、毒滞难化。本例背疽几满一背而判为阴证，当有肿处色黯不红、痛微、脉数无力为凭，脉之有力无力正是阴阳虚实之关键。", ["数", "有力", "无力"]], "12224": ["预后", "脉杂乱无统绪，即脉象散乱无根，为胃气衰败、气血逆乱之象。唇疽肿厚二寸，目脱神，乃毒邪内陷、正气溃散，故脉失统绪。此脉主病危，预后不良，故断为速备后事，越三日而殒。", []], "12225": ["预后", "茧唇晚期，脾湿胃热薰蒸日久，气血耗竭，故脉杂乱无统绪。目脱神为神气将绝，脉无统绪为胃气已败，二者并见，说明病至晚期，正气不支，故不日而损。", []], "12226": ["病机", "疮溃三月，脓水清稀，六脉虚细无力，饮食减少，显系气血两虚、脾胃受损。前医误用凉血解毒，更伤脾胃，不知虚实。虚细脉主气血不足，无力鼓动，故用十全大补汤补益气血，外上红升丹化腐生肌，月余方愈。", ["虚", "细"]], "12227": ["病机", "脓水清稀，六脉虚细无力，为阴证非阳证。虚细脉主气血亏虚，脓水清稀为正气不足、不能化腐成脓，故服凉药不效。此脉此症，当以温补托里为治，不可再投寒凉。", ["虚", "细"]], "12228": ["病机", "关脉芤，按之胃脘有块大如碗，为中脘疽。芤脉主血虚，亦主瘀血内阻、血不循经。误服消积破块药十余剂，更伤气血，故关脉见芤。当托里透脓，令疮头向外，若内破则恐烂胃腐肠。", ["芤"]], "12229": ["预后", "少腹痈月余，命似悬丝，后事已备，然诊其脉幸有力有神，许其可治。脉有力有神，说明胃气未绝、正气尚存，虽疮口出血如注，仍可托补。故用十全大补汤，外上红升丹，饮食日增，精神日强。", []], "12230": ["病机", "乳疽脉弦细劲硬，弦主肝郁，细主血少，劲硬为郁怒伤肝、思虑伤脾，肝脾两亏，气郁血滞。故用健脾疏肝之药，外上红升丹，腐脱新生，月余痊愈，且无残废。", ["弦", "细", "劲", "硬"]], "12231": ["病机", "托腮疔，寒热呕吐，神昏谵语，疔色红紫，坚似钉尖。心、肝二部洪数有力，为肝木太旺，木生心火，火毒炽盛。洪数主实热，故用犀角黄连汤泻火解毒，大黄加至36克，大泻二次，毒散病愈。", ["洪", "数"]], "12232": ["病机", "疔色红紫，脉洪数有力，为阳证无疑。洪数有力主热毒炽盛，气血壅滞，正邪交争剧烈。热毒蕴结肌肤，故见疔疮色红紫、肿痛；脉洪数有力反映胃经实热邪火，与局部红肿热痛相应。治以清热解毒，犀角黄连汤加减，肿痛尽消，脉证相符。", ["洪", "数", "有", "力"]], "12233": ["病机", "阳明脉洪数有力，疮形如酒杯，疼痛非常，坚硬如石。洪数有力主胃经实热邪火，热毒壅盛，气血瘀滞。诸痛痒疮皆属于心，心火炽盛，故痛甚；热毒深结，故坚硬如石。脉证合参，属阳证实热，急泻火毒，二花大黄汤泻下后痛减，脉象相应。", ["洪", "数", "有", "力"]], "12234": ["其他", "本段未识别脉名，纯述肉瘤不痛不痒，误触则流血不止。患处无赤脉，必非血瘤，说明病机非血热妄行，而是气血结聚成瘤，络脉未显。以药线扎紧，使瘤体坏死脱落，属外治之法。脉象缺如，故脉素为空，病机分析从症候推断。", []], "12235": ["主病", "关脉犯芤，右腿难伸，少腹右生疙瘩大如覆碗，疼痛难忍，日轻夜重，寒热交作。芤脉主血虚失血，亦主痈脓。《脉诀》云关内逢芤肠胃痈，以脉证合参，确属大肠痈。热毒壅聚肠道，血肉腐败成脓，故脉芤；脓未成或已成，气血两伤，故见寒热、饮食减少。", ["芤"]], "12236": ["病机", "乳疽烂去一半，脓水交流，色紫黑，骨瘦似柴，言语低微，面色焦黄，脉濡弱虚细。濡弱虚细主气血两虚，肝脾郁损。郁怒伤肝，思虑伤脾，肝脾气郁结于乳房，血行不畅，久则腐溃，耗伤气血。脉证相应，治以八珍汤加减疏肝健脾，培补气血，以绝病本。", ["濡", "弱", "虚", "细"]], "12237": ["病机", "七十岁患承山发，满面通红，疮大似盘，腐肉肿寸余，绝无脓意，脉洪数有力。洪数有力主实热壅盛，虽年高而病却有余，形无败象。热毒炽盛，气血壅滞，故肿硬无脓；脉证相符，先以仙方活命饮清热解毒，后以十全大补汤扶正收功。", ["洪", "数", "有", "力"]], "12238": ["病机", "本段未识别脉名，述偏对口月余不溃，肿势甚大，坚硬如石。正对口属督脉为阳，易肿溃；偏对口属膀胱为阴，由上行下，纯阴无阳，故月余不溃。病机为阴寒凝滞，气血亏虚，无力托毒外出。治以黄耆托里汤加减，令阴变为阳，托毒透脓，疮根日收，脓出而愈。", []], "12239": ["病机", "年近八十患正对口，疮口大似茶杯，脓稠黄，腐肉未脱，脉洪而有力，喜凉恶热。洪而有力主实热内盛，虽年老而禀赋厚、属阳脏，故脉证俱实。诸痛痒疮皆属于心，心火炽盛故痛不止。治以内疏黄连汤大凉兼泻，泻后脉略退，症减，外上大金丹提脓生肌。", ["洪", "有", "力"]], "12240": ["病机", "原文未载具体脉名，仅言「脉证悉属阳证」，可知脉当见阳热实象。对口属督脉阳热火盛，焮红肿痛为热毒壅盛、气血尚充之征，故易治；根大坚硬则毒深结聚、气血壅滞难化，故难疗。脉证俱属阳，说明正盛邪实、热毒未陷，故遣凉血解毒而愈，全段以脉证定性归阳为辨证眼目。", []], "12241": ["病机", "脉洪盛有力，为实热壅盛之象。中脘发疮头大如汤碗、焮肿似盘、腐肉不脱，正合洪盛有力之脉，说明脾胃火毒结聚，气血与热毒相搏。洪为火盛，盛而有力为邪实正不虚，故先以仙方活命饮解内毒，外化腐生肌，三十日而愈，脉证与治法相应。", ["洪", "盛", "有", "力"]], "12242": ["预后", "原文未载脉名，仅言「诊其脉亦无凶象」，是据脉断预后。小儿瘟疫后毒气不尽，结疮于左腮下，身体极瘦、疮口深寸许、色暗淡、脓水清稀，显系虚证；然脉无凶象、无臭气，说明胃气未绝、正尚可支，故虽属危证尚可治，惟需时日，服三十余帖近五十天方瘳。", []], "12243": ["病机", "脉皆虚细无力，为气血不足、寒湿凝滞之象。玉枕疽疮形恶、硬如铁石、半月不溃，正因督脉受寒湿凝结，阳气不能鼓动，故脉虚细无力而疮难成脓。久之寒化为热、阴变为阳方能成脓，先服仙方活命饮令速溃，以免毒气蔓延，脉虚细正是寒湿未化热之候。", ["虚", "细", "无", "力"]], "12244": ["病机", "六脉皆虚细无力，为气血大亏之象。小儿手背发，筋骨尽露、所流臭水无脓、体极瘦弱，又大便日泻三四次、饮食减少，皆虚候；臭水无脓正是元气亏损、不能化毒之明证。脉虚细无力与诸虚症相应，故先服十全大补汤壮气血，气血壮则自然化毒变脓，外上红升丹提脓。", ["虚", "细", "无", "力"]], "12245": ["治法", "原文未载具体脉象，仅引「观其脉证，知犯何逆，随证治之」，强调凭脉辨证以施治。乳岩由忧郁损于肝脾而作，属难疗之疾，故以清心涤虑为要，针药并治，补中有消、消中有补，养血调气、止痛通络，方药平淡而守仲景随证治之之法，说明重证亦不可猎奇，须依脉证缓图。", []], "12246": ["病机", "心肝二脉洪数且实，为木火亢盛之象。头疼如破、项如拔、头肿似斗、目疼如抉、云翳失明，皆肝开窍于目、木为火之母，火盛则肿，是木火通明之象。前医作风寒治，辛温反助火势，故疼转剧、目生云翳。洪数实说明火盛邪实，宜凉开泻心兼走空窍，服后渐愈。", ["洪", "数", "实"]], "12247": ["病机", "原文明言「此证勿须诊脉」，未载脉象，凭阅历断为肝火上冲、脑户受风、风火混合。头疼如碎、呕吐不止、二目失明，皆风火相煽、上扰清空之候；若误用羌、荆、防、天麻等辛温升散，则风火更炽，故治宜甘寒凉润，说明此证重在辨风火病机而非拘于脉。", []], "12248": ["病机", "肝脉弦数，弦主肝，数主火，乃怒动肝火之象。火性炎上，直冲巅顶，故卯时头疼如碎。前医误作太阳寒证发大汗，反伤津助火，故病沉重。原文明言「火盛者疼」，治宜疏肝清热，火降则疼止，脉象与肝火上冲证相应。", ["弦", "数"]], "12249": ["病机", "卯属木，应肝；肝脉弦数，弦为肝气，数为火盛，合而断为肝火上冲证。卯时疼重，正应木旺之时，火随木升，上扰清空。原文以「肝脉弦数」为据，确认清肝火治法甚当，脉象直接指示病机所在。", ["弦", "数"]], "12250": ["病机", "肺脾二部脉极细无力，细为气血不足，无力为虚。肺主上焦元气，脾为生化之源，二部脉细无力，说明上焦元气亏虚，清阳不升，脑失所养而头疼欲死。原文点明「上焦元气不足者令人头疼」，若误作他证攻伐，则虚者愈虚，病必加重，故治以大补元气。", ["细"]], "12251": ["预后", "两寸脉俱细，关尺皆已无神，寸候上焦头颅，脉细无神示正气败绝、脑髓已坏。真头疼而脉象如此，乃绝证，原文断为「脑已坏矣」，虽扁卢亦无如何，越日而亡，死后十指皆青，脉无神与死候相应，故列预后。", ["细"]], "12252": ["病机", "两寸脉浮紧，浮主表，紧主寒主痛，寸部候上焦，故断为上焦中风寒之故。前医误作上焦火，投芩连栀柏苦寒，寒邪被遏，头疼殊甚。原文以「两寸脉浮紧」纠正火证之误，说明脑中风寒、清阳被束才是病机，当以辛温散寒为治。", ["浮", "紧"]], "12253": ["病机", "六脉皆虚细无力，虚为气血亏，细为不足，产后气血双亏，风寒乘虚侵入脑户，正气不能托送，故头疼半年不愈。原文明言「新产气血双亏」，脉虚细无力正合此机，治用十全大补汤，气血充足则风寒自散，属正虚邪恋之候。", ["虚", "细"]], "12254": ["病机", "肝肾脾三部脉均沉紧，沉主里主寒，紧主寒主疼，原文引《脉诀》「沉者主寒，紧者主疼」为据。夏令大汗后乘凉卧于树下，寒邪乘虚入里，滞于经络，故两腿疼痛难移、日轻夜重。脉沉紧与寒邪无疑相应，治以温散寒邪、和通经络。", ["沉", "紧"]], "12255": ["病机", "原文仅言「诊其脉，因虚弱中风寒之故」，未识具体脉名，故脉象要素为空。八岁女童半身不遂三月，病机为正气虚弱、中风寒之邪，经络被寒邪滞塞，气血不行。治先针刺开通血脉，后回虚逐邪，徐图缓愈，属正虚邪滞之证。", []], "12256": ["病机", "肺脾脉极虚兼紧，紧主寒，虚为禀弱久坐伤脾、中气不振之征。正虚则寒邪沉匿血脉，非单纯除风可去。故以十全大补汤补正，正足则邪退，体现“补正即是发表”之旨，与半身麻木不遂相应。", ["虚", "紧"]], "12257": ["病机", "肝脉甚虚，两尺洪大且数、中取不见，为阴火太旺、水亏火炎之象。尺脉洪数主下焦相火妄动，肝虚则筋失所养，故两腿足痛如站火中、申刻大哭。用知柏地黄汤壮水制阳，正合“壮水以制阳”之法。", ["虚", "洪", "数"]], "12258": ["病机", "肺脾肾三部脉沉迟，沉主里、迟主寒，说明寒邪深入筋骨，非表浅之疾。冬令受寒，两腿麻木酸疼渐及腰，痿卧食减，皆寒凝经脉、阳气不达所致。故用大活络丹缓缓搜剔，非旦夕可愈。", ["沉", "迟"]], "12259": ["病机", "肝脉弦数，为肝经怒气化火；脾脉洪缓，为脾经湿热内蕴。怒则气逆，湿热流注筋骨，故遇怒疼甚、腰独重。前医作风寒治故不效。治当疏肝调气为主、清利脾湿为标，借酒同气相求引药直达湿邪。", ["弦", "数", "洪", "缓"]], "12260": ["病机", "本条自设问答，以每遇怒气疼甚为症据，肝脉弦数应肝经怒气，脾脉洪缓应脾经湿热。弦数示气郁化火，洪缓示湿蕴中焦，二脉合参，足证怒气与湿热合流筋骨之间，故为辨证之据。", ["弦", "数", "洪", "缓"]], "12261": ["病机", "两关两尺脉沉缓、重取微数，沉缓主湿滞中焦，微数示湿郁化热。善饮而湿邪留中，先伤脾胃中气，中气伤则不能运化酒湿，缠绵难已，故腰疼十余年不愈。病深根固，非丸药久服难求速效。", ["沉", "缓", "数"]], "12262": ["病机", "脾肾二部脉沉迟无力，沉迟主里寒，无力为气血虚弱。年六十而贫，脾肾先后天皆亏，风寒乘虚袭入二经，故腰腿疼痛麻木。治先补脾肾，气血完固则邪自去，即“补正即是驱邪”“不能补其虚，安能攻其余”之义。", ["沉", "迟", "虚"]], "12263": ["病机", "六脉虚细无力，为气血双亏之象。瘟病初愈房事太早，复伤肾水，水亏则骨失所养，故筋骨酸疼二载不愈。此证除补肾外皆非正治，虽前贤有“疼痛无补法”之说，然此属虚痛，不可执著，当以补肾为正治。", ["虚", "细"]], "12264": ["病机", "肝脉弦数有力，弦主肝郁气滞，数主郁久化热。原文谓“久积郁怒，肝气不伸”，肝性急为病多疼，故见筋骨疼痛难忍、日夜啼哭。此脉示肝郁化火、肝燥失养之病机，非虚证，故宗“肝无补法”而用泻肝补水之法，使水足木养、郁解痛止。", ["弦", "数"]], "12265": ["误治", "初诊六脉细数无力，似产后气血双亏，然细数无力亦可见恶露未尽、瘀血内阻之假虚象。误用十全大补汤反“以实填实”，致脉“虚者变实，数者更数”，症见心胸满闷、少腹疼胀，此瘀血得补而壅滞化热之征。脉由虚变实，正是误补致瘀热内结之明证。", ["细", "数", "虚", "实"]], "12266": ["病机", "六脉细数无力本似气血双亏，然服药增剧后“脉虚变实”，说明前之虚象乃恶露未尽、瘀阻脉道所致，非真虚也。瘀血内停，新血不充则细，郁而化热则数，按之无力为假虚。脉虚变实，揭示瘀血内结、误补壅实之病机，故用失笑散加玄胡活血化瘀而愈。", ["细", "数", "虚", "实"]], "12267": ["病机", "脾脉极虚，主脾气大伤。患者阴黄年余，屡服茵陈、栀子、黄柏等苦寒利湿之品，更戕脾阳，致骨瘦如柴、面如烟薰、声音低微。脉极虚说明元气亏败、脾肾两伤，非湿热阳黄之实。故治宜大健脾肾，使元气充足、生血华肉，勿专治黄而黄自化。", ["虚"]], "12268": ["病机", "脾脉沉数兼滑，沉主里，数主热，滑主湿。原文谓“湿结于脾土之中，湿化为热，故土色外现”，湿滞气遏则短气，脾失转运则食减。此脉示湿热蕴结脾土之阳黄病机，故身目黄如金、小便如黄柏水，治以茵陈柏皮汤利湿退黄。", ["沉", "数", "滑"]], "12269": ["病机", "脾胃脉沉细无力，沉主里，细主虚，无力主阳气不足。患者因饥饱劳役伤脾，又逢阴雨寒湿，致胸腹满闷、身重食减、身目如金而带灰黑。脉沉细无力说明脾阳虚弱、寒湿内困，乃阴黄之证，非湿热阳黄，故治宜温中健脾兼利小水。", ["沉", "细"]], "12270": ["其他", "此段为按语，未出具体脉象，纯述望诊“远看面有灰黑之色”与脉色相参辨阴黄之法。其要在“于疑似之间，辨其真伪”，强调脉症合参、精细辨证，非论某脉主某病，故脉象要素为空。", []], "12271": ["病机", "脾肺脉虚细无力，肾脉濡弱。虚细主气血亏少，濡弱主阳气衰微。原文谓“劳则伤肾”“劳则伤脾”，先后两天并伤，故气色灰黄发暗、动作短气。此脉示脾肾两虚、根本亏损之阴黄病机，非湿热实邪，故宜急固先天、再补后天，从根本治。", ["虚", "细", "濡", "弱"]], "12272": ["病机", "肾脉微细无力，是房劳太过、肾水亏耗、先天元气虚衰之象。脉微为阳气不振，细为阴血不足，无力则根本已虚。肾虚不能温煦脾土，土不生金，故发为黄病，且久服除湿之剂不效。此属虚黄，非湿热实邪，故当大补肾水、收复元气，不必治黄而黄自退。", ["微", "细"]], "12273": ["病机", "脾脉洪滑有力，洪为热盛，滑为湿聚，有力为邪实。面色黄明、声音壮厉、小便赤黄微疼，皆湿热壅遏中焦、结而不通之征。湿热郁蒸，胆汁外溢，故发黄。脉证相合，属实证，治宜攻其湿热、利其脾胃，邪去则黄自退。", ["洪", "滑"]], "12274": ["误治", "妊娠五月患黄，前医纯用茵陈、栀子、黄柏等寒利之品，未佐安胎，寒利太过伤胎元。诊得六脉虚细无力、似有散意，虚细为气血不足，散意为胎元不固、正气欲散。故饮食渐减、胎动不安。此段明示误治伤胎，当以安胎为主、除黄为标。", ["虚", "细", "散"]], "12275": ["病机", "脾脉滑数，肺脉亦然。滑主湿痰壅盛，数主热，脾为生痰之源，肺为贮痰之器，母病及子，故曰母令子实。湿热发黄而误认经病，服调经调气热药不验，正因未求其本。脉滑数示脾胃实热，治病必求其本，当清利湿热。", ["滑", "数"]], "12276": ["病机", "此按语申明脾脉滑数、肺脉亦滑数，乃脾胃实热之确证。滑为湿聚，数为热盛，实热上逆熏肺，故肺脉亦见滑数。翟氏据此以清热利湿与泻实热并重投治获效，说明脉象反映湿热壅实之病机，认证真切则遣方精当。", ["滑", "数"]], "12277": ["死脉", "脾脉已见屋漏，屋漏脉来良久一滴、断续不匀，为胃气衰败、后天将绝之真脏脉。面黄如土，黄病日久，脾土真色外现。古人云五脏真色见于外者死，故知不易救治，越三日而殁。此段以屋漏脉判断预后凶险。", ["屋漏"]], "12278": ["预后", "此按语承上段而发，年逾古稀、染黄日久，后天脾胃衰败，真脏脉见，故命在垂危、病情危笃。原文未明写具体脉名，仅以真脏脉概之，强调临证诊治当慎之又慎，不可妄投攻伐，以免促其危亡。", []], "12279": ["病机", "小儿脉均见细紧之象，细主正虚，紧主痛、主积。腹疼饥时多、饱时轻减，疼时无块而长条如指许凸起，结合细紧脉，提示腹中有虫积内扰、气机挛急。细紧为虫动腹痛之脉征，故翟氏由脉及症，转念虫黄之可能，运用存乎一心。", ["细", "紧"]], "12280": ["病机", "脾胃脉沉实有力，沉主里，实主邪盛，知饮食塞胃、中焦停滞不行，阻碍胃气不能下降，下既不通必反于上，故发呃逆。此新病形实，非久病胃气绝之危候，治当消积攻下，使宿食一下，三焦通顺，呃逆自除。", ["沉", "实"]], "12281": ["病机", "脾胃脉沉实有力，沉为病在里，实为邪气盛，结合新病形实，知食停胃中，伏热攻发，胃气不得下降而呃逆。久病呃逆为胃气绝，此则新病实证，故用消积攻下法立愈，示人审脉证、因病施治。", ["沉", "实"]], "12282": ["病机", "肝脉弦数，弦主肝郁，数主热，为肝郁生热、火性炎上；脾脉虚弱，为木旺土衰，土受木制，胃气不得下降，故呃逆连声不绝。治当解肝郁，使土不受制，则呃逆自除。", ["弦", "数", "虚", "弱"]], "12283": ["病机", "肝脉弦数，为肝郁化热、木胜克土；脾脉虚弱，为土衰受制，胃气不得下降，故呃逆终日连声不绝。重用柴胡、青皮、郁金疏肝解郁，令肝条达，解除对中土克伐，不治呃逆而呃逆自止。", ["弦", "数", "虚", "弱"]], "12284": ["病机", "肝脉沉滞且数，沉滞主肝气郁结，数主热，因大怒经血遂止，肝郁生热，肝为藏血之脏，郁而经血不下，肝热上冲则呃逆、鼻血。治先解肝郁、凉肝血，使血下行，天癸一见，诸症尽扫。", ["沉", "滞", "数"]], "12285": ["病机", "肺脉洪大无伦，洪大为火热亢盛之象，且无伦序，知肺火上冲，气逆而为呃逆。治宜清金宁肺，使肺火降、气逆平，则呃逆一药可愈。", ["洪", "大"]], "12286": ["病机", "肺脉洪大无伦，为肺火亢盛、上冲为呃。洪大之脉主热盛，无伦则火失常度，故以清金宁肺治之，合乎法也。", ["洪", "大"]], "12287": ["病机", "脾胃脉沉滑有力，沉主里，滑主痰，有力为实，知寒痰内阻、胃气不降，故呃逆。诸医或言气滞、胃寒、虚火、危证，皆未审脉，此乃寒痰实证，治宜温胃祛痰。", ["沉", "滑", "有", "力"]], "12288": ["死脉", "脉见鱼翔，属七怪脉之一，主胃气已绝、真元耗散。患者天癸不行、骨瘦如柴、大肉已脱，久病卧床五月，忽加呃逆，乃脾胃衰败、虚气上逆之危候。鱼翔脉来浮泛无根，如鱼游水，为阴阳离决之兆，故断为危证，勉方不效而殁。", []], "12289": ["病机", "肺胃之脉均沉迟，沉主里、迟主寒，知寒邪凝结肺胃，气机不得下降，反上逆为呃逆。饮食难进、强食噎呛，亦胃气不降之征。前医误作食积，不知脉沉迟非实滞，故温胃降气而愈。", ["沉", "迟"]], "12290": ["病机", "此按语重申肺胃寒邪凝结致呃逆之机，从肺胃脉沉迟可验。沉为在里，迟为有寒，寒凝则气不下降，逆而为呃。知脉知证，故以温胃降气取效，说明脉象是辨明寒凝气逆的关键依据。", ["沉", "迟"]], "12291": ["病机", "六脉虚数无力，虚为正气不足，数而无力为虚阳外浮。久病忽添呃逆，非绝证，乃孤阳不敛、虚火冲上所致。前医以久病呃逆为死候而辞，不知脉虚数无力尚可纳气归肾、引龙归海，故用金匮肾气汤加味。", ["虚", "数"]], "12292": ["病机", "久病脉虚数无力，脉病相符，虚为阴阳两亏，数而无力为孤阳不敛、虚火上冲。呃逆由虚火冲上而发，非绝证。故用金匮肾气汤加味，助阳生气、滋阴化水，使水火交泰，阳不上越，火不上冲，呃逆自平。", ["虚", "数"]], "12293": ["病机", "肝脉弦数有力，弦主肝病，数主热，有力为实。劳心过度患失眠，前医作心火妄动用苦寒不效，不知肝藏魂，肝热则魂不守舍，故彻夜不眠。治以宁睡清肝汤，清肝热则魂安，此隔治之妙。", ["弦", "数"]], "12294": ["病机", "心脉、命门脉俱虚细无力，虚细为阴阳两虚，无力为阳气衰微。六旬外患失眠，前医作阴虚治不效，不知阳虚不能济阴，心肾不交故不寐。用桂附八味汤加减，以阳药济阴，使阴阳平均，自然睡熟。", ["虚", "细"]], "12295": ["病机", "此按语申明心脉、命门脉虚细无力，为心肾不能交泰、水火不能既济之象。虚细无力主阴阳两亏，阳虚不能济阴，故失眠。用桂附八味汤意在引火归元，使心肾相交、水火相济、阴阳平衡，失眠自瘳。", ["虚", "细"]], "12296": ["病机", "左尺脉细弱无力，左尺候肾，细为阴血不足，弱为气衰无力，合示肾水亏虚、阴不涵阳。原文引「阴虚不寐」，正指肾阴亏耗、水不济火，心火独亢而失眠。前医平肝泻心火不效，因未补其虚；用六味合四物壮水制火、补血养阴而效，反证病机在肾阴虚而非实火。", ["细", "弱"]], "12297": ["病机", "本条为前案按语，重申左尺脉细弱无力属肾水亏而致失眠。细弱无力是阴精不足、脉道不充之象，肾水亏则不能上济心火，火扰神明故不寐。用六味汤合四物汤壮水制火、补血养阴，正合「阴虚不寐」之机，故服药立见功效，脉证方相应。", ["细", "弱"]], "12298": ["病机", "肾脉极细弱，是肾水亏极、根本不足；心脉洪数无力，洪为火象、数为热，无力则属虚火。合观为水亏不能济火，心火浮越而致怔忡惊悸、闻声惊恐汗出。前医清热镇惊化痰不效，因未抽坎塞离、交通心肾；六味加远志、菖蒲、玄参滋水降火而愈，正合此机。", ["细", "弱", "洪", "数"]], "12299": ["病机", "心肝二脉洪数有力，洪为火盛、数为热急，有力示实。原文谓「肝木太旺，心火妄动」，肝为心母，母亢害子，故怔忡惊悸、闻声惊恐、满面燥红、善饮。此为实火扰心之证，非虚损，故用四物汤加减养血平肝、除贼安君，服五帖全瘳，脉证与治法相合。", ["洪", "数"]], "12300": ["病机", "心脉虚极且数，虚为心气阴亏耗，数为火动不安。原文断为「劳心过度，心火有升无降」，即心阴不足、虚火浮越，不能下交于肾，阴阳失交，故怔忡惊悸、昼夜不寐。素有劳疾，年六旬余，正虚为本，故脉虚而非实洪，治当使心火下降、阴阳交泰。", ["虚", "数"]], "12301": ["病机", "心脉虚数，虚为心阴亏、数为火动；肝脉又洪，洪为肝火亢盛。合示肝火过旺、心火上炎不能下降，肾水亏极难以上潮，成坎离不交之象，故梦遗无隔宿、虚汗喘促、骨蒸潮热。前医涩精罔效，因未交济阴阳；阴阳两交汤使坎离交济而愈，正合此脉机。", ["虚", "数", "洪"]], "12302": ["其他", "本段为医案序跋，述翟君竹亭出示医案、嘱余校正之事，通篇论医案编次体例与著者经验，未及具体脉象与病机。原文「每案叙某病之脉证与治方」只是概述体例，非论某脉主某病，故脉象要素为空，主旨归入其他，不作病机推断。", []], "12303": ["病机", "脉弦数而未得冲和，弦为肝郁、数为火盛，失冲和则胃气不足。原文谓「相火有升腾之象」，合舌光绛兼燥刺，示阴虚阳旺、化火化痰，风趁火势、痰因火蒸上扰肺胃，酿成喉风，故寒热、咽阻疼、痰嘶气逆、溲涩便难。邪实正虚，火盛水亏，脉象正映此燎原之势。", ["弦", "数"]], "12304": ["病机", "脉洪数带弦，洪为热盛，数为火炽，弦主痰火攻冲。原文谓“热邪内蕴”“郁蒸化火，火升而为痰，痰火上攻，逆于肺胃之脉”，故脉见洪数而弦，主肺胃痰火壅盛之喉蛾，症见咽喉红肿、汤水难下、项外微肿，邪踞肺胃而未入心营。", ["洪", "数", "弦"]], "12305": ["病机", "脉息数而带弦，数为热邪鸱张，弦为风火相煽。原文谓“风火引动郁火”“痰火盘踞”，又云“火者，痰之本；痰者，火之标”，故脉数弦主痰火风热交炽，症见体热不凉、痰多且腻、咽喉红肿、便结项肿，显系火性上炎、风性善窜。", ["数", "弦"]], "12306": ["病机", "脉息细数带弦，细为阴液受伤，数为余热未净，弦主肺胃痰火未清。原文谓“喉蛾已溃，毒邪有外泄之机”，但“喉旁尚有硬块，大便坚结”，脉细数弦，说明阴液已伤而肺胃之热究属有余未净，故治当养阴清热兼润肠通便。", ["细", "数", "弦"]], "12307": ["病机", "脉来细数带弦，细主阴虚血少，数主风热化火，弦主少阳相火。原文谓“风火兼挟相火”“热邪蒸化毒邪”，故脉见细数弦，主颈痈之候，症见疮形肿焮红、寒热交作、口渴胃呆、痰稠咳逆，乃阴虚血少、风火相火壅阻少阳营卫所致。", ["细", "数", "弦"]], "12308": ["病机", "原文未识脉名，然据“骨槽风之症，邪深著骨”“元本不足，肾水素亏，外束风邪，袭入阳明胃络，乘虚而邪伏于骨”可知，病机为肾亏正虚、邪伏骨络，症见内溃外穿、脓秽难净、牙床骨露、肿势未消，属正不托邪、邪蕴难清之候。", []], "12309": ["病机", "脉涩而少力，涩主血少营滞，少力为气虚不鼓。原文谓“体素阴虚，血少循环之职”“营阴所以受伤，即卫阳亦未能滋养”，故脉涩少力主阴阳二亏、营卫失养，症见肌肉麻木、皮肤燥裂、破津黄水兼痒痛，乃阴虚内热鼓动余毒熏蒸外达所致。", ["涩"]], "12310": ["病机", "脉象细弦，细主气血两亏，弦主寒凝气滞。原文谓“血因寒滞，营气失调”“寒凝而致”“元本不足，气血两亏”，故脉细弦主寒凝经络、气血亏虚，症见手背疬核累累、胖肿脓多秽浊、筋骨作疼，乃阴阳两伤、正虚不能托毒之候。", ["细", "弦"]], "12311": ["病机", "脉象细而兼数，细主阴血不足，数主热郁化毒。原文谓“肝失畅达，乳络因而壅塞；胃乏冲和，肌肉从此疏豁”“郁蒸化毒”，故脉细数主肝胃郁热、乳络壅塞，症见乳房木硬肿痛、寒热交作、经水适断，有热入血室之征，乃外吹成痈之病机。", ["细", "数"]], "12312": ["病机", "脉息细数带弦，左关更甚，细为营阴亏虚，数为邪热未清，弦主肝经气火偏亢。产后血液亏损，肝失荣养，化火犯胃，阳明脉络阻遏，故左乳木硬红肿成外吹，溃后脓水连绵、根脚肿硬。身热纳少、头眩耳鸣、舌淡红苔薄中微黄，皆营阴未复、肝胃余热未尽之象，脉症相合。", ["细", "数", "弦"]], "12313": ["病机", "原文未识脉名，以症测机。先天不足，少阴失封蛰之司，寒湿深沉，命门无内融之力，毒阻肾俞，经脉壅塞，营气不从，遂成肾俞虚痰。穿溃月余，清水连绵如漏卮难塞，形容瘪瘦同枯木无荣，乃肾精漏泄、肝木失濡、乙癸同源俱亏之候，病本在肾，涉及肝木。", []], "12314": ["病机", "脉息细涩欠利，细为阳虚气弱，涩为湿邪壅遏、气血运行不利。年近六旬，阳气日亏，阳虚则湿胜，湿邪久踞，气血壅遏，发为肾俞发，根盘覆碗、木硬隐痛、皮色如常。舌苔淡白且腻、恶寒喜暖、声发不扬、下体酸痛，皆阳虚湿盛、湿盛阳浮之征，以脉参症，深恐难以消散。", ["细", "涩"]], "12315": ["病机", "脉息沉数带弦，沉主病在里，数主火热，弦主风火相煽、肝胃热盛。火毒燃伤，邪伤肌表，肺胃内应，故增寒壮热、大便秘结、咳嗽气急、口渴烦闷，舌尖红、中焦神昏。火盛生风，风驾火威，深恐内窜心营，脉数弦正是邪势方张、有内陷之虞的反映。", ["沉", "数", "弦"]], "12316": ["病机", "脉浮洪而且数，浮主邪在肌表，洪为阳邪炽盛、气血燔灼，数主热毒鸱张。火毒害于气血，腐烂成烂皮疔，疮形尺余属阳明，阳邪攻阳经，两阳相灼。舌焦黑尖红，营阴几劫，身热口渴、谵语神昏蜂起，脉症俱见邪势方张、热毒有内陷心营之危，故曰重极危险。", ["浮", "洪", "数"]], "12317": ["病机", "脉息沉数少神，沉主病在里，数主火毒内发，少神示正气已伤。脑疽偏左，非外感六淫，乃五脏内发，火毒之疡。经属膀胱寒水之腑，内因有五：心绪烦扰火旺、恼怒伤肝血脉不朝、思虑伤脾营气不从、恣欲伤肾真阴败而相火生，皆致毒邪凝滞项间，脉沉数少神正合内发火毒、正虚邪滞之机。", ["沉", "数"]], "12318": ["预后", "原文未识脉名，以症辨预后。二诊痛势稍缓、浆水渐来，似有松象，但根脚犹硬，毒邪盘踞，新腐未分，元气少流行之用，正虚邪滞已露端倪。脑疽偏属太阳寒水之腑，邪客最易内侵，故平塌难腐为难治；况七旬高年困一月大患，正虚邪滞，预后堪忧。", []], "12319": ["病机", "脉息右部少神，左关弦数，右部少神示元气已衰，左关弦数主肝火妄动。三诊脓水虽多而疮头塌陷、红肿蔓延，究系近增郁怒，肝火挟毒肆横。古稀患偏脑疽，正虚邪滞，毒邪逗留纠缠，邪踞经络。脉症合参，正虚而邪未净，故既不可纯用三黄解毒，亦不可骤投十全大补。", ["弦", "数"]], "12320": ["病机", "原文未载脉象，以症测机。患者质本丰腴，湿邪逗留，郁火内蕴，又值天中阳气大泄、湿热升腾之候，时邪引动蕴湿化火，毒逆太阳之脉，升降失调而成偏脑疽。疮头塌陷为毒邪盘踞，根脚旁流为火毒肆横，四肢清冷系阳虚表不固，五志昏蒙乃邪盛神无依，故有内陷外脱之虞。", []], "12321": ["预后", "脉息虚而少神，为先天元气已经告惫之征。症起多年，沉寒痼冷踞于筋骨，背如鳖背则督脉露虚，胸若鸡胸则任脉形损，加之饮食少而欠运，后天亦亏，形羸肉削、脓水连绵，元气难荣、营阴失养。脉症合参，不独身躯生废，且恐性命难全，故拟固本之方聊为延年之计。", ["虚"]], "12322": ["病机", "脉息细数少神，舌色淡白。原文自释：细为气虚，数为血虚，舌苔白则中气已惫。寒湿深伏筋骨致成附骨疽，溃后半载脓水连绵、疮口细小，形羸肉削、饮食少思，一派虚象。细数少神正合气血两虚、胃阳不振之机，故非补不宜，拟调养气血兼救胃阳。", ["细", "数"]], "12323": ["病机", "原文未载脉象，以症推机。毒阻育门则气血循环莫展，邪壅脉络则太阳道路难通，遂生下搭手。根脚红而兼紫，为毒邪盘踞之端；疮头硬且疼，是营气稽留之兆。外则浆水稀少，内则呕恶烦冤，前溲赤热，后地道不通，表里俱不宣畅，邪热无从开泄，炎蒸不熄，恐有内窜之忧，故拟清解火毒兼通地道。", []], "12324": ["病机", "脉息细数带弦，重按殊无神韵，舌质光绛且干。细数主阴液亏虚，弦为肝火挟痰之象，重按无神则元气已虚。患者偏中后左足臂不用、肌肉不仁、痰多言蹇，本属下元痰火中络；今肝火挟痰上扰，逆于太阳之脉，阻遏营气，郁蒸化毒而成上搭手。痰火久踞，元气愈虚，阴液愈损，高年患此虑其虚脱。", ["细", "数", "弦"]], "12325": ["预后", "脉和缓而且匀，为胃气渐复、痰火下降之佳兆，故红形已退、新肉齐生，气血得流形之用。舌淡红而潮润，胃津上乘，仓廪有专权。惟寤寐少宁、转侧艰难、语言蹇滞、手足不举，究系津液素虚，痰火久扰，脓浆大溃则虚者愈虚，不能内济心阳、外灌百脉。脉象虽和，图治仍难，故拟补而不滞之方。", ["缓", "和"]], "12326": ["病机", "脉细数而带弦，原文自释为虚火更兼实火。体素阳虚，湿邪内蕴，郁火恒多，湿火交结于肺俞而成上搭手。细数主营阴亏虚，弦主火毒壅于脉络。疮形数寸、黑烂无休，恐犯三陷之局；红霞散漫，尽有肆横之征；浆稀水少，脓毒盘踞。身微寒而兼热，湿邪且挟风邪，恶候已见，故宜未雨绸缪，扶正却邪，标本兼顾。", ["细", "数", "弦"]], "12327": ["病机", "身热脉弦，原文断为由真阴之下竭，耳鸣头晕属肝阳之上浮。寒凝脉络则少阳道路难通，湿阻肌膜则气血循环莫展，寒郁为热、热甚肉腐而成环跳疽。症起胎前、溃于产后，脓水连绵二月，形躯瘪瘦，数孔相串，饮食少思则中气告惫。良由产后营阴大耗，加以脓水久溃，虚者愈虚而肝阳失潜，故脉见弦。", ["弦"]], "12328": ["病机", "脉细数而少神，细为血虚，数因火炽，少神示正气已亏。原文谓“血虚则涵养失令，筋脉从此不舒；气虚则外卫不周，寒湿因而侵袭”，致营卫欠流行、经络阻碍，延成环跳疽。少阳相火内寄，火炽则痛，血不足则肌肉难长，故脓水淋漓、根脚板硬、疮孔深远而痛，取效难。", ["细", "数"]], "12329": ["病机", "脉空虚，主气血阴阳俱亏。原文“八脉空虚，藉归、龟以调剂”，又“一阴不足，赖元母以扶助”，说明阴血亏虚、奇经失养，故用首、地养阴，参、术壮气，归、龟调剂八脉。虚象为本，故以补益为法，兼顾肝阳潜伏、胃阴上承。", ["虚", "空"]], "12330": ["病机", "脉洪数而带弦，洪数为火邪方炽，弦主肝郁或痰火内蕴。原文“风温外袭，肌肤失周流之度；痰火内蕴，肺胃失清降之权”，火邪炽盛故脉洪数，痰火郁结故带弦。症见咳嗽痰稠如胶、肿延胸胁焮红疼痛、间有神昏，为肺胃邪热渐欲入营之象。", ["洪", "数", "弦"]], "12331": ["病机", "脉细数而带弦，细数主阴虚火旺，弦为肝阳失潜。原文“体归阳盛，质本阴虚”，又“湿温久扰，虚者愈虚，余湿不能尽化，注于会阴之间，酿成肛痈”。脉细数带弦，正合肝阳失潜、湿热未清之机，故根脚木硬、脓流如漏卮，虚处患症难期速效。", ["细", "数", "弦"]], "12332": ["病机", "脉虚弱少神，左关独弦，虚为正气衰惫，弱为元气不足，弦主肝阳偏亢。原文“总由正气衰惫，余邪不宣化”，又“质本阴虚，肝肾早失涵濡之用”，故疮口不愈、头晕气冲。脉症合参，日久根深，须大剂穷源固本、阴阳并补，使气机流畅、精血两充。", ["虚", "弱", "弦"]], "12333": ["病机", "脉息细数犹见少神，左关仍留弦象。原文自释“细数者，余邪未净也；少神者，元气未充也；带弦者，肝阳未熄也”。劳心所致，君相二火频升，一水不能相济。虚体患此，标易敛而真阴难复，故须阴阳并补，阳生阴长，不可偏胜。", ["细", "数", "弦"]], "12334": ["病机", "脉右大而左弦，右大主肺胃热盛，左弦主肝火上升。原文“肺机不畅，降令失权，酿成肺痈”，症见痰涎漉漉、咳嗽频频、或脓或血、中府隐痛。脉右大而左弦，正合“肝火有上升之兆；舌微黄而尖绛，肺津无下降之征”，故须肃肺清金兼熄肝阳。", ["大", "弦"]], "12335": ["病机", "脉左弦而右大，左弦为肝阳左升太过，右大为肺金右降失权。原文“痰多气急，金府之右降失权；肋痛头眩，肝垣之左升太过”，又“邪热未平”“阴液暗损”。肝热魂不归舍，肺热魄不归藏，故夜寐少宁。面萎黄、口不燥渴，湿邪未化、蓄饮内留，仍宜清肃太阴。", ["弦", "大"]], "12336": ["病机", "原文未载脉象，仅述漏蹄风由风湿下注、气血稽留、筋脉失荣而致，病程一载反复，口僵孔深妨于步履。其病机为风湿久羁，气血运行不畅，筋脉失养，属邪深正伤之候，故难许脱体。", []], "12337": ["病机", "脉细弦而近数，细为阴伤，弦主肝木乘脾，数乃相火扰动。症见咳胀、肠鸣作泻、胀痛引腰及少腹，显系肝脾不和、厥阴少阳相火内引浊饮上升，真邪相攻，且肾亦暗伤，与经文肝胀、肾胀相符。", ["细", "弦", "数"]], "12338": ["病机", "脉沉主里，此由暑湿新凉交蒸氤氲于气分，邪不得从汗解而蕴结于中，故便结脉沉。症见畏寒发热、昏烦脘闷、白㾦隐而不明，甚则讝语躁扰，为气分邪遏、里结已成之象，故症颇棘手。", ["沉"]], "12339": ["病机", "脉象甚弦，弦主肝阳亢盛、阴液受灼。症见身热口渴、神昏肢痉、白㾦红疹、舌燥齿垢，乃暑邪深入营阴，少火悉成壮火，心阳扰动肝阳，胃津肾液俱伤，阴虚阳亢而邪盛正伤，故症形危笃。", ["弦"]], "12340": ["病机", "左弦右涩，弦为肝脾不和，涩主湿滞血少；继则弦象较和而带虚数，虚数示高年积劳内伤、阴血不足而余湿未清。症见下痢赤白、溲涩胃呆、肢倦少寐，正是中气虚而溲便变、胃不和则卧不安之候。", ["弦", "涩", "虚", "数"]], "12341": ["病机", "脉沉弦，沉主里、弦主肝，未甚虚弱示邪实尚存。湿蕴相火上升化毒，下注肝肾，致少腹作胀、溲涩淋浊遗精，精浊混来如漏卮。脉沉弦与症相合，为由外而内、有形精血受损而神智欠安之候。", ["沉", "弦"]], "12342": ["病机", "脉细弦，右寸关独见弦大，细为肝肾真阴不足，弦大为肺胃痰热上壅。咯血屡发于春分，厥阴少阳相火升腾克金，故脉症合参为虚在下而实在上，二虚一实，先治其实，清肺胃以制木安血。", ["细", "弦", "大"]], "12343": ["病机", "左手脉弦细而劲，右手脉数细而滑。弦劲为肝胆风阳内动，细为阴亏；数细滑为脾胃湿痰化热。症见寒热交错、神志混淆、手振肢掣，乃君相火炽、风阳入络、湿痰扰及清灵，风胜津干、热胜液涸之候。", ["弦", "细", "劲", "数"]], "12344": ["病机", "脉来沉数，沉主里、数主热，合溲赤而浑、苔黄而厚，显系阴亏水不涵木、七情郁结化火，风邪乘袭厥阴、横扰阳明。沉为在里，数为火盛，故脉不浮而沉、不迟而数，正合阴虚火盛、风火内扰之机，故见神识不清、口眼㖞斜、语言謇涩，并须防呃逆鼾呼大汗。", ["沉", "数"]], "12345": ["病机", "药后神志渐清、黄苔渐腐、身有微热微汗，而沉数之脉依然，口目㖞斜未正。沉数不去，说明阴虚火盛之本未除、风邪扰乱厥阴之络仍在，虽外症稍减而里热未清，故脉象未变，原方加减续进，仍以桂酒涂颊外治。", ["沉", "数"]], "12346": ["预后", "前案沉数之脉，今转为缓，且原文以阳明为十二经脉之长，脉之长、脉亦缓并见。缓为胃气渐和、风淫渐解之象，与神识已清、语言已爽、身热得微汗已解、黄腐之苔渐退相应，说明真阴渐复、风邪渐散；惟口目仍斜，风淫未尽，故仍守原方加减。", ["长", "缓"]], "12347": ["兼症", "本段未载脉象，专论口目之斜未复。口目常动属风生，耳鼻常静属风息，肝气通于目、胃脉环于口，故口目平复必待肝胃冲和。此承前案风淫未尽、真阴未复而来，指出余邪留滞本络，仍以原方增损、桂酒涂颊，属兼症调治之论。", []], "12348": ["病机", "本段未出脉象，而言气脉为之动变。症本血燥召风，风翻胃海，气脉动变则霾曀上冒清空、分布不周于本络，故口目㖞斜，斜乃风之象。风淫虽解未尽、阴液虽复未充，气脉未能流畅，故以脾肾为主，六味归脾加减为丸，从本缓图。", []], "12349": ["病机", "脉来浮数，按之则缓。浮为风邪在表，数为热，酒渍于内、热炙于外，左颊汗出如浆，虚风乘之扰乱三阳之络，故脉浮数；按之缓则示里无实热、正气尚和。浮数应风热外袭，与口㖞于右、目眇于左相应，故拟玉屏风散二陈汤加味辅正散风。", ["浮", "数", "缓"]], "12350": ["预后", "叠进玉屏风二陈加味后，左颊之汗已收、口目之斜俱正，浮数之脉已缓。浮数去而转为缓，是风淫已散、表热已解之征，脉症相符，故为向愈之候；第因年高二气本亏，风邪易袭，故宜常服十全丸以杜未来之患。", ["缓"]], "12351": ["病机", "年逾四旬、形丰脉软，软为气虚湿盛之象，形丰则气馁于内。风袭阳明，营卫俱伤，血凝气阻，故遍身麻痹、口目蠕𥆧、眉棱骨痛按之益甚，名曰肉苛。脉软正应营卫俱伤、气血不充，故慎防倾跌，治当辅正散风。", ["软"]], "12352": ["预后", "原文述“软散之脉已敛”，软散为营卫俱虚、气不敛摄之象，经言“营气虚则不仁，卫气虚则不用”，故见苛痹、𥆧动。服补中益气加味后，营卫风淫渐散，眉棱骨痛平，软散之脉渐敛，说明中州升补、营卫渐充，为邪退正复之佳兆。", ["散", "软"]], "12353": ["病机", "形充而脉弱，为气歉于中、分腠不固，故常多自汗，风邪易引。肾水上泛，脾液倒行，凝滞成痰，隧窍阻塞，遂卒然昏聩、气促痰鸣言謇、舌苔白滑。脉弱正反映中气不足、正不敌邪，木旺金衰，有汗脱之虞。", ["弱"]], "12354": ["预后", "前案脉弱，服正气散、六君汤后“脉弱起”，即弱脉渐起而有力，为邪退正复之兆。神识清、热退汗收、舌强和、痰声息，皆中土渐旺、风痰渐化之征。惟右肢苛痹，乃偏枯之象，证本脾肾双亏、气虚夹痰，故以丸缓治。", ["弱"]], "12355": ["病机", "脉沉涩无力，沉主里、涩主滞、无力为虚，合食入作呕、大便恒溏，知风淫于胃、湿著于脾，分布不周于脉络。湿滞脉道故涩，中阳不足故无力，遂致偏枯于右、痛无定止，逢阴雨烦劳益甚，为风痹之属，阴阳易位、更虚更实。", ["沉", "涩", "无", "力"]], "12356": ["病机", "脉来弦数，弦为肝旺，数为热，合涎唾不禁、舌蹇难言、身形强直，知肾阴素亏，肺损于上，风引传肝，肝主筋而筋弱不能自收；肝复传脾，脾伤四肢不用；脾复传胃，胃缓则廉泉开而涎下。弦数正示风火内动、阴亏日甚，病势苦深。", ["弦", "数"]], "12357": ["病机", "脉来三五不调，为心火盛、肾水虚，五志过极，湿土生痰，机窍不利，脉道失其常度。舌强言謇、右臂麻木不舒，乃类中复萌已著。心火盛则脉数而乱，肾水虚则脉不根，湿痰阻窍则脉来参差，故理阳明、和太阴、佐化湿痰。", ["三五不调"]], "12358": ["病机", "脉来甚慢，如结代之状，尺部尤甚，为心火暴甚、肾水虚衰，智意不和，湿痰阻窍。结代脉主脉气不相接续，慢而尺甚，示肾元亏虚、心肾不交，故本拟泻心法而仍从中治，理阳明、和太阴，以保心肾。", ["结", "代"]], "12359": ["兼症", "两进理阳明、和太阴、佐化湿痰后，舌强渐和、语言渐展、右肢麻痹亦舒，但胸次反觉不畅，清涎上溢，湿痰未化，心火未平，脉仍三五不调。脉未和调，说明痰火湿浊仍阻机窍，故未宜骤补，原方加减继进。", ["三五不调"]], "12360": ["病机", "原文未载脉象，但述舌强渐和、语言渐爽等症，并引心脉系舌本、肾脉循喉咙、脾脉连舌本，说明病机为太阴不营、湿痰自生，肾水不生、心火自盛，三经失和，水不升火不降，中土不畅，机窍不利。现湿土用事、肝火司权，故治以崇土养营、和肝熄风、引益肾水。", []], "12361": ["病机", "脉来甚慢即迟缓，主湿郁中虚、痰湿内阻。偏枯于左、口㖞于右、舌强语謇、涎下不禁，乃湿热不攘、中虚痰郁为患。大筋软短、小筋弛长，为湿热伤筋、筋脉失养之象。脉迟缓正合湿浊困阻、阳气不运之机。", ["缓"]], "12362": ["预后", "脉来迟缓，主阳气衰微、气血运行无力。卒然昏聩、柔汗、溲便遗失、四肢不收、口噤不语，乃烦劳扰乱阳气，气不归精，精不化气，神无所倚，阴阳离决之危候。脉迟缓示阳衰阴盛，故勉拟回阳饮追敛散亡之气，预后难料。", ["迟", "缓"]], "12363": ["病机", "脉象小驶于迟，即稍数于迟而近缓，示阳回而阴液未复。药后汗收、神清、语言渐展、肢体徐转，是阳气渐回；惟心烦意乱、莫能自主，乃阴液亏虚、心神失养。脉小驶于迟正合阳回阴未复之机，故危症得安而仍需善后。", ["缓"]], "12364": ["病机", "脉小驶于迟曰缓，即稍数于迟而近缓，主阳回而阴液未复。心中愦愦不安、语言尚謇，乃阴血不足、心神失养。经云无阳则阴无以生，连进回阳生阴之品颇合机宜，脉缓示阳气渐回而阴液未充，故安不忘危，善后宜加意。", ["缓"]], "12365": ["主病", "脉来微细如丝，主心肾亏虚、气血衰微。素耽酒色，精损于频、气伤于渐，卒然神志沉迷、口眼㖞斜、语言謇涩，乃精竭气伤、神失所养。微细如丝示正气虚极，慎防汗脱，故从色厥论治，急固其本。", ["微", "细"]], "12366": ["治法", "原文仅载生脉散加熟地、山药、山芋、制附子，未述脉象。此为回阳生阴、补益心肾之法，针对阳回阴液未复、心肾亏虚之机。生脉散益气敛阴，熟地、山药、山芋滋补肾阴，附子温阳，合而阴阳并补，使阳生阴长。", []], "12367": ["死脉", "脉象洪空，即洪大而中空，主真阴枯涸、心火自焚。卒然昏聩、劲直口开、手撒遗溲、自汗、痰鸣、气促，乃暴病属火、火性疾速，真阴竭而心主自焚。洪空为阴竭阳浮之象，五绝见三，虽司命不可为，故议镇固之法以副或免之望。", ["洪", "空"]], "12368": ["主病", "脉浮紧为太阳伤寒表实证之典型脉象。寒邪伤营，血涩无汗，皮肤闭而为热，故脉浮紧；头身腰背俱痛、溲色澄清、大便五日不解，皆寒邪束表、营卫不通之象。浮主表，紧主寒主痛，脉证相合，尚属太阳经症，故宜麻黄汤发汗解表。", ["浮", "紧"]], "12369": ["主病", "脉浮主表，苔白亦主表寒。巅痛身疼、恶寒发热为风寒外袭；有汗不透、痰溲气促，乃风寒两伤、营卫俱病，表气郁而不畅。溲便自调说明里无实热。脉浮与表证相应，故法宜解肌兼汗，使营卫调和而邪从汗解。", ["浮"]], "12370": ["主病", "脉象浮紧主风寒束表。发热恶寒发于阳，巅痛身疼、无汗、苔白、胸痞，皆寒邪闭表、卫阳被遏之征。浮为邪在表，紧为寒邪劲急，表闭无汗则脉气紧张。脉证合参，病属太阳表实兼胸痞，故先开其表，取九味羌活汤发汗解表。", ["浮", "紧"]], "12371": ["主病", "脉体尺寸俱浮，说明寒邪外袭，表气皆浮。头身俱痛、翕翕发热、啬啬振寒，为寒邪甚厉、卫阳被郁之象。禀赋虽充，然月郭空虚、霜露之疾，外邪乘虚而入。尺寸俱浮主表邪弥漫，故拟南阳败毒饮祛邪返正，得汗便解。", ["浮"]], "12372": ["病机", "脉虚为气虚之象。身热恶热、烦渴、巅痛似属火盛，然神倦脉虚，说明热伤元气、火盛乘金，气耗于内。此非实火，乃暑热伤气之中暍证。脉虚与神倦相应，揭示气虚为本、热盛为标，故治以寒以取之，清暑热而保元气。", ["虚"]], "12373": ["治法", "此段为治法方药，非脉象描述。白虎汤清暑热，生脉散益气生津，加淡竹叶、卷心清心除烦。前方针对暑热伤气阴之病机，后方针对脉散（气阴耗散）之象，两方合用，清补兼施，使暑热得清、气阴得复，脉散可收。", []], "12374": ["病机", "脉软为暑湿伤气、气不充脉之象。暑必夹湿，湿著为病，伤阴伤气，故神倦脉软；身热自汗、恶风口渴，为暑热熏蒸、气阴两伤；溲便自调、不思饮食，说明湿困中焦，心脾肺三经互病。脉软与神倦相应，主气耗湿困，故拟清暑益气加减。", ["软"]], "12375": ["病机", "脉来滑数无力，滑主湿，数主热，无力为虚。湿热伤阴，五液日耗，故脉虽滑数而无力；形神慵倦、骨痿不能起于床，为阴液耗损、筋骨失养之象。此非实热，乃湿热久羁、气阴两伤，故苦寒虽效非常服之方，宜甘露饮加减补阴化湿。", ["滑", "数", "虚"]], "12376": ["病机", "脉长为湿热蕴于阳明，熏蒸肝木，耗损肾阴之象。阳明为十二经脉之长，湿热郁蒸则脉道充盈而长；肝主筋、肾统水，阴伤筋弱故体倦多眠；热蒸上干清窍则唇疡、目涩、颊肿咽痛；苔黄舌绛为湿热伤阴之征。病延六载，药浅病深，故脉长不退。", ["长"]], "12377": ["病机", "脉数主邪伏膜原，外越太阳经。憎寒发热、头痛、腰背俱痛、无汗为太阳表证；苔白、溲赤示邪郁化热。数脉为邪正相争、热势渐起之象，邪从膜原外透太阳，故脉数而兼表证，非单纯里热。", ["数"]], "12378": ["病机", "脉洪长而数，为伏邪外越阳明经腑不和之候。洪长主阳明热盛气分，数主热邪亢盛；恶寒罢而昼夜发热、日晡益甚、鼻干不得卧、溲浑赤，皆阳明经腑热炽之征。脉洪长数而神未昏、无呃逆，示邪尚在气分，故为吉。", ["洪", "长", "数"]], "12379": ["病机", "脉弦数主伏邪并交少阳阳明。弦为少阳主脉，数主热；得汗热不解、憎寒、心烦喜呕、胸满胁痛为少阳枢机不利；苔淡黄、溲浑赤为阳明里热。弦数并见，示邪从膜原内陷，少阳阳明同病，故用小茈达原加减和解透达。", ["弦", "数"]], "12380": ["病机", "脉弦数依旧，示伏邪仍踞少阳阳明。烦呕稍减、夜得少寐为药后枢机略畅；然寒热依旧、耳聋、胸满、溲浑赤，弦数未衰，说明少阳郁热未解、阳明里热未清。脉证相合，故守原方加味，继续和解透邪。", ["弦", "数"]], "12381": ["病机", "脉仍弦数，示伏邪渐溃而未尽，阴液已耗。大解如败酱、溲色转淡为邪有下行之势；夜寐稍安、自汗身热乍退为邪减之象；然唇燥舌干、心烦作呕，弦数不退，说明少阳郁热未清、阴伤液耗，故虑生歧变。", ["弦", "数"]], "12382": ["病机", "原文未识脉名，仅言热退脉不静，示伏邪化热伤阴、余邪未靖。大便如败酱、溲浑如豆汁为湿热下迫；夜寐不沉、胸痞不食、心烦作呕、舌燥作渴、苔黄不腐，皆热伤阴液、胃气不和之征。脉不静说明邪热未全退，故最忌神昏苔剥呃逆之剧。", []], "12383": ["病机", "脉数主邪伏少阳倒入阳明，化热伤阴。便未解、溲浑近赤、额前心下俱热、有汗、苔黄舌尖赤有刺、口燥作渴为阳明腑热伤阴；肢微冷为热极反兼寒化；神烦少寐为热扰心神。脉数示热势未衰，腑气不通，邪无出路，故当承气下结存阴，因二气素虚而姑缓。", ["数"]], "12384": ["病机", "原文述伏邪服药后便下瘀血、诸症减而“数脉缓”，缓为胃热得下、腑气宣通、邪有出路之象。脉由数转缓，说明阳明伏热渐化，胃热迫血流入大肠之势已挫，故额热退、烦渴减、四肢和。然便黑带血，病及至阴，脾伤失统，仍虑大便复闭、阳邪复聚，故以养阴通腑续治。", ["缓"]], "12385": ["预后", "原文“诸症悉除……身凉脉缓”，脉缓为邪解正安、胃气来复之象。伏邪从血分而下，犹表邪随汗而解，故脉由数转缓、身凉神安、知饿思食。惟溲色犹浑、胸前尚热，是余气未尽、真阴五液俱伤，故以补阴益气善后，脉缓在此示病退向愈之机。", ["缓"]], "12386": ["预后", "原文“脉微数，按之不鼓”，微为元气衰微，数为邪热未清，按之不鼓则正虚无力鼓动。形容枯削、肢体振掉、苔灰黑、言不足以听，皆真阴枯涸、邪热纵横之候。脉微数而不鼓，说明邪虽欲解而元气渺无驱逐之权，势必邪正俱败，危如朝露，故急宜峻补以冀战汗。", ["微", "数"]], "12387": ["治法", "本段为方药组成，未出脉象，故脉象要素为空。生脉散加生地、归身、茯神、远志、枣仁、芦根，乃益气养阴、安神生津之法。结合前案脉微数按之不鼓、真阴枯涸，此方意在峻补五液三阴，使正复容邪、从中击外，属针对正虚邪恋的治法，非主病或平脉之论。", []], "12388": ["病机", "原文“六脉俱数，浮取不足，沉取有余”，数为热，浮取不足示表分已虚，沉取有余示伏热盘踞于里。神昏独语、目赤唇焦、溲色红浑，皆伏邪化热、热入膀胱、逆传心包之象。脉沉取有余正是邪热内结之征，故虑其犯死阴之禁，拟犀角地黄汤合导赤散清心保肺、导火下行。", ["数", "浮", "沉"]], "12389": ["预后", "本段未识别脉名，原文仅言“六脉俱静”，属脉象描述而非具体脉字，故脉象要素为空。伤寒汗出淋漓病不除，伏邪汗出淋漓则病将解；今汗大出、遍体凉和、六脉俱静、溲色澄清，是伏邪随汗外解、营卫调和之象。惟中胃未醒，故宜养胃生阴以善其后，脉静在此示邪退向安。", []], "12390": ["病机", "本段未出脉象，专论五志化火、金水交伤之病机。原文“诸气𪱥郁，皆属于肺”“诸逆冲上，皆属于火”，悲恐忧思耗气伤阴，五志之阳与邪浑一俱从火化，壮火食气、烁阴耗液，致清肃不行、肾水不升、肺气不降、水火不济。溲赤为饮入于胃、输脾归肺、注膀胱而热移下焦之明验。", []], "12391": ["主病", "原文“脉伏而数，巅痛身疼，无汗，翕翕发热，啬啬恶寒”，伏为邪郁腠理、玄府不开，数为热郁于表。脉伏而数，说明三阳表证邪正交争于表分，卫阳被遏故恶寒无汗，经气不利故巅痛身疼。此脉主三阳表实之病，故拟九味羌活汤加味以开玄府、解表散邪。", ["伏", "数"]], "12392": ["病机", "原文述服冲和汤后“浮数之脉已缓”，浮数主表邪未净，今脉缓知新感寒邪已从汗解，寒热巅疼亦除；惟“身痛不休”乃表气未和，营卫尚欠通调，故脉虽缓而身痛存，主病机为表气未和，宜桂枝汤小和营卫。", ["浮", "数", "缓"]], "12393": ["病机", "服桂枝汤后“脉反滑数”，滑主痰湿伏邪，数主化热，与苔白如积粉、汗出如浴、溲赤而浑、间有谵语并见，知伏邪盘踞膜原，化热伤阴，直贯阳明，液耗阴伤，故脉反滑数，非桂枝之过，乃伏邪内动之征。", ["滑", "数"]], "12394": ["病机", "进达原饮后“脉来滑数”，滑主腑浊痰湿，数主热，与舌苔转黄、身热不从汗解、溲赤而浑、便溏色绛、神烦谵语、心下拒按相应，知腑浊虽行而液耗阴伤，伏热未清，脉滑数正是邪热内壅、阴液受灼之象。", ["滑", "数"]], "12395": ["病机", "战汗前“脉细如丝”，细主正虚，与憎寒寒战、四肢厥逆、神情萧索并见，乃内伏之邪从腑气宣通而溃，在经之邪孤悬，外与正争，邪正交争则战；正气不支故脉细如丝，及汗出邪退则脉静身凉，此战汗之机，宜安神养营。", ["细"]], "12396": ["预后", "原文“筋脉动惕”即脉动惕，动主惊惕不安，与䐃肉全消、苔剥唇裂、神昏如醉并见，乃伏热稽留，夺血无汗、夺汗无血，表液已枯、里血复竭，邪正两亡，筋脉失养而动惕，故曰殊难奏捷，属预后不良之候。", ["动"]], "12397": ["病机", "“脉长洪而数”，长主邪气盛，洪主热盛，数主热，与大汗淋漓、身反大热、消渴引饮、舌苔根黄尖绛、溲浑赤、便不解并见，知复邪中溃，郁热暴伸，散漫经中而不传胃腑，欲作战汗，故脉长洪而数，宜人参白虎汤清解。", ["长", "洪", "数"]], "12398": ["病机", "服小柴胡、小陷胸后“数脉已缓”，数主伏热，缓为邪退之象；与寒热往来热势减半、濈然汗出、遍体凉和、黄苔立腐、溲浑赤渐清并见，知伏邪中溃，表里分传，正复不能容邪，余气散漫，故数脉转缓，宜开鬼门洁净腑以击其惰归。", ["数", "缓"]], "12399": ["预后", "“脉空弦无力”，空主血脱阴枯，弦主厥阴为病，无力主正气大虚；与口禁不语、身卧如塑、溲浑如柏汁、便解如猪肤、肉全消、皮肤甲错、舌卷目上视并见，知伏邪深陷厥阴，液脱阴枯已著，攻补两难，故曰两无生理，勉拟黄龙汤攻补兼施。", ["空", "弦"]], "12400": ["预后", "原文“脉夺”指脉气耗夺，非具体脉象。液脱阴亡，髓热发痉，化源已绝，神机已息，故脉失充养而夺。形消、口禁、身强直、目眩不瞑，皆阴竭阳越、筋脉失濡之候。脉夺示胃气已败，无复资生，虽扁仓复起亦难措手，属危候。", []], "12401": ["病机", "脉来滑数无神，滑主湿浊痰热，数主热，无神示正气已虚。疟后留热未除，脾肾不足，湿遏发黄，热留阴分，故脉滑数；无神则因先天后天俱不振，精微不化。潮热、啮齿、抽搐皆湿热伤阴、肝热风动之症，脉象与病机相应。", ["滑", "数"]], "12402": ["兼症", "脉象尚带微弦，弦主肝郁湿滞，微示余邪未净。痎势十去八九，口干溲频黄而不浑，目眦黄侵白眼，乃湿运余热未清；奔驰多汗、气喘耳鸣、左疝、鼻流清涕，则肾肺不足。脉弦为肝木未舒，微为湿浊留连，故平补三阴缓治。", ["弦", "微"]], "12403": ["预后", "原文未识具体脉名，仅言“脉神形色俱起”，指脉之神气、形色皆见起色。进补肾阴养心脾后，阴黄已退，饮食增，二便如常，故脉神渐复。此段以脉神形色并观，判断效机已获，依方进步，属预后佳象。", []], "12404": ["病机", "脉软主虚，为正气不足之象。三阴痎疟寒热俱重，已发八次，溲清脉软，知邪伏太阴而脾阳式微。软脉不任邪争，故寒热虽重而脉不鼓，示正虚邪陷，极难奏效，未宜止截，当从本治。", ["软"]], "12405": ["病机", "脉来迟缓，迟主寒，缓主虚，为脾肾双亏、阳气不振之象。老疟间日一发，寒重热轻，精神疲倦，正合脉迟缓所主。脾肾虚寒，邪伏阴分，故未宜止截，拟东垣法补中升阳，使正气渐复。", ["迟", "缓"]], "12406": ["病机", "脉来软数无力，软为阴亏，数为虚热，无力示中气不足。疟后中土受伤，怒郁肝阳苦逆，土不载木，阴不配阳，故竟夜无眠、食少体倦、虚阳上越。曾患血崩，肝木失舒，木郁化火耗液伤阴，脉软数无力正合脏阴亏虚、虚火内扰之机。", ["软", "数"]], "12407": ["主病", "脉数主热，肠癖赤白、后重腹疼、溲赤，暑滞俱重，气血俱伤，热蕴肠道，故脉数。数而有力为实热，与暑湿积滞相搏，气血凝滞成脓血。河间谓行血调气，宜芍药汤，脉数正是热滞内盛之征。", ["数"]], "12408": ["病机", "脉来缓弱，缓为湿滞，弱为气虚，正合过食生冷、寒湿犯中所致。寒湿伤脾，脾失健运，下传于肾而成肠癖，溲色清澄为寒湿内停、无热之明验。脉缓弱说明中阳不足、寒湿内盛，故治以温中为主，温散寒湿则脾胃自复。", ["缓", "弱"]], "12409": ["预后", "脉体和而又否，即脉虽略见和缓之意而旋即转差，反映脾肾阳气潜伤、中寒格阳、清浊升降失常之肠癖日久。病延近载，补中益气、胃关煎等温补固涩而病势退复进，脉不能持续和缓，说明命门火衰、阴阳不相维系，故曰病势若深、殊难奏捷，预后堪忧。", []], "12410": ["病机", "脉弦无力，弦为肝旺，无力为虚，正合吐泻伤阴阳、五液俱耗之后。肾阴不足则肝阳失制，肝志为怒，怒则气上填胸，故胸次胀满而口干非渴，非食滞可比。脉弦无力说明阴不制阳、阴阳俱亏，故主张补肾即所以补肝，益气生阴、阴从阳化。", ["弦"]], "12411": ["治法", "脉散为阳气浮越、根本欲脱之象，故用参脉散以敛浮越之阳、益气固脱，配合阳八味地黄丸温补肾命、引火归元。散脉说明真阳不藏、肾气不固，单补阴则阳无所附，单敛阳则根不固，故两方合用，敛散固脱与温补下元并行，使阳气归窟。", ["散"]], "12412": ["病机", "肝脉渐和而胃脉尚软，软为胃气未复、中阳不振之象。素本肾亏虚寒，大病后二气交伤、五液互损，脏腑之气难以骤复，故胃脉软弱。治以地黄守补配桂附走而不守，达肾火之窟、蕴生中土，化液生阴，补肾则胃开、补命门则脾健，正合脉软所主之虚寒病机。", ["软"]], "12413": ["预后", "原文未识脉名，仅言脉神形色俱起，即脉之神气与形色一同转佳，为胃气渐复之征。立秋后四日，脾胃渐苏，大病新瘥而脏腑初和、二气未定，故脉虽起而未全复。此时全在静养，守摇精劳形之戒、澄心息虑，使五内得太和之气，则脉神自臻康豫，属瘥后调摄之预后判断。", []], "12414": ["预后", "身冷脉伏，伏为阳气闭郁不出、脉道沉匿之象，合吐泻交作、三焦俱伤，柔汗不收则阳随汗泄，目赤溲红浑如中毒，是阴阳离决、邪毒内闭之危候。脉伏说明正气不能外达、阳衰于内，故曰危在须臾，勉拟元戎法尽其心力，属死生关头之预后判断。", ["伏"]], "12415": ["病机", "六脉细涩无力，细为阴血不足，涩为气滞血少、脉络不畅，无力为正气虚。沙气袭络，络脉痹阻，故遍身苛痹、肢尖逆冷、胸喉气不展舒。脉细涩无力说明沙毒闭阻络脉而正气已虚，气血不能充达四末，故拟正气六和加减，扶正与疏和并用。", ["细", "涩"]], "12416": ["主病", "脉细涩为沙候。细主阴血不足，涩主气滞血瘀，脉道不利。沙候多因感受秽浊之气，气机壅塞，血行不畅，故见烦闷欲吐、巅痛、肢尖冷。细涩脉反映气血两亏兼瘀滞，与沙证之邪闭络脉、阳气不达四末相应。", ["细", "涩"]], "12417": ["病机", "六脉洪大而急，为真元耗损、液络大亏，阴不制阳，虚阳外浮之象。洪大主热，急主弦劲，此非实热，乃水不荣木、阳生风动。故见咽嗌结核、瘰疬串久不消，四肢串肿而痛，睡将熟则肢节挛搐动摇，皆肝风内动、血不归肝之候。", ["洪", "大", "急"]], "12418": ["病机", "原文未识脉名，然据症推机：肝血不充络，气燥不养筋。《经》云“软短为拘，陷脉为偻”，言筋脉失养则拘挛佝偻。此由水不涵木，肝血亏虚，络脉失濡，气燥生风，故拟滋肝养血舒筋，缓缓培养，佐外熏络以通气血。", []], "12419": ["主病", "脉弦无力，主肝扰阳明。弦为肝脉，无力为虚，乃肝血不足、肝阳上扰，乘犯阳明。头风自幼年，疼时太阳发胀、牙关亦然，饮热茶汗出则止，每晨起午后渐止，饮食如常而精神日减，皆肝血虚不能充养形骸，风阳扰动阳明经脉所致。", ["弦", "无力"]], "12420": ["病机", "六脉细数而软，细为阴亏，数为火旺，软为虚风。恙由耳后冲及巅顶，项强神烦，食减作痛，时作时止，乃虚风游走，风化为火，风愈高火愈炽，阳不能固，阴不能敛。细数软脉正是阴亏火旺、虚风内动之征，故拟扶阳敛阴，俾气行血流。", ["细", "数", "软"]], "12421": ["病机", "脉来软数兼弦，软为水亏，数为火升，弦为木燥。水亏于下，火升于上，壮火食气，上虚则眩，故头晕足软如立舟车，咽喉干燥，梦泄频作。精不化气，水不上潮，木燥生火，煎熬津液成痰。值春令阳升，防其痉厥，法宜壮水佐以化痰。", ["软", "数", "弦"]], "12422": ["病机", "脉来软数无神，软为气虚，数为虚火，无神为胃气衰。素本脾胃不足，抑郁不宣，气郁生痰，上扰清明之府，故颠眩如驾风云，卒然溃乱忽而神清。此非类中，乃痰伏中州，清气无由上达，下取无以上承，故以治痰为主。", ["软", "数"]], "12423": ["病机", "右脉虚大而弦，左脉濡滑。右脉候脾，虚大为气虚，弦为肝强；左脉候肾，濡滑为湿。肾阴亏则肝阳强，心气不足，脾虚生湿。曲运神机劳伤心神，暗汲肾阴，子午不交故寤而不寐。湿热伤阴，气虚不化，故宜从心脾肾进补。", ["虚", "大", "弦", "濡"]], "12424": ["病机", "原文述“脉不应指”，指脉象难以应指而辨，反映气血大伤、心肾交亏。心主血脉，肾藏精，二天不振则脉道不充，故脉不应指。此脉主瘰疬难痊、气血伤而未复，并见心跳作呕，为心脾肝肾俱损之候。", []], "12425": ["病机", "原文“冲脉动，诸脉皆动”，冲脉起于气街，夹脐上行。冲脉动则诸脉皆动，从少腹跳动、冲逆上行，见心慌意乱、虚里跳跃如梭。此因肾不养肝，气失摄纳，根蒂亏虚，冲气上逆，故脉动不宁。", ["动"]], "12426": ["病机", "脉来虚数，虚为正气不足，数为阴亏有热。患者先天薄弱，盗汗梦泄，病中走泄，气血肾气伤而未复，故脉虚；阴不制阳，虚热内生，故脉数。症见午后拘束、烦心即心中疼痛气闷，皆虚数脉所主之正虚邪少、阴亏火动之机。", ["虚", "数"]], "12427": ["病机", "脉来弦数，按之无力。弦主肝木偏亢，数主虚热，无力为正气内亏。三阴内亏，金水交伤，阴虚生内热，故脉弦数；虚劳内损，二气皆亏，故按之无力。症见咳嗽夜甚、手心蒸热、形容日羸，正合虚劳阴虚阳浮之病机。", ["弦", "数"]], "12428": ["病机", "左脉甚小，心肝肾三阴皆亏，肾不养肝，心气益虚；右脉濡而且慢，濡主湿、缓主阳气衰，真阳亦衰。头目眩晕、不耐操劳，皆由三阴虚损、真阳式微，清阳不升所致。脉小濡缓，正合虚损劳伤、中虚寒痰之候。", ["小", "濡", "缓"]], "12429": ["预后", "原文“脉神形色俱起”，指脉之神、形、色皆渐起，为好转之象。眩晕渐减，但中气、心气、肾气皆亏，水不涵木，木火交并，二气俱损。脉神形色俱起说明药后胃气渐复，预后向安，故前进黑归脾尚合机宜。", []], "12430": ["病机", "脉象六阴，按之虚数不静。六阴脉本属阴盛，按之虚数不静，则阴亏而虚阳上浮，心肾两亏。水不配木，肾不纳气，气不归元，气有余便是火，故右肾热气常漫、带多走泄。虚数不静正示水火不济、虚阳扰动之机。", ["虚", "数"]], "12431": ["病机", "脉来细小，细主阴血不足，小主脉道不充。年已二旬而灵机蒙蔽、神识不开，脉细小反映先天不足、肾精亏虚，精不充脉，故脉道细小。此脉主先天薄弱、神识不开之病机，治当养先天、炼后天，徐徐调养。", ["细", "小"]], "12432": ["治法", "原文仅载“生脉散加陈仓米”一方，脉象写法“脉散”提示脉气耗散，为气阴两伤、脉失敛摄之象。生脉散益气敛阴，加陈仓米和胃气，针对脉散所主的气阴耗散病机，属治法范畴。", ["散"]], "12433": ["病机", "“男子脉大为劳”，大脉为三阴内损、虚阳外浮之象，非实热之大。原文见下患痔漏、咳嗽气急、呕吐酸水，皆脾肺肾虚损、气不归元所致。脉大而症见虚损，故主劳病，病机在脾胃虚衰、金水不生。", ["大"]], "12434": ["预后", "原文未识脉名，仅言“脉症渐定，即是转机”。症见胸中饱闷渐舒、食粥不多、便溏、面黄瘦、颧红退、咳痰减，脉症由不定渐定，示阴阳渐分、胃气渐复，故为好转之预后，非主病或病机。", []], "12435": ["病机", "“脉来细涩”主脏阴营液俱亏，细为阴血不足，涩为脉道不利。症见形容消瘦、食少运迟、卧则气促、腹右气坠，皆脾胃不健、后天不振，兼先天不足。脉细涩正合营液亏虚、运化无力之病机。", ["细", "涩"]], "12436": ["病机", "“脉来细涩”虽眠食安，然运纳不健，二天不振。细涩为营阴亏少、脉道涩滞，主心脾两虚、肝胃不和。脉象反映气血不足、运化迟滞，故治法养心脾兼和肝胃，属病机分析。", ["细", "涩"]], "12437": ["预后", "原文未识脉名，仅言“脉神形色俱起”，与眠食俱安、运纳健旺并见，示胃气渐复、二天有振之机。脉神形色俱起为好转征象，故属预后判断，非主病或病机。", []], "12438": ["预后", "原文未识脉名，言“脉神色俱起，胃口大开，生气来矣”，脉与神、色同见好转，示胃气来复、生机渐振。以丸代煎，并嘱节制，皆基于脉症向愈之预后，故归预后。", []], "12439": ["病机", "“心脉短，肝脉虚，尺脉小”，短虚小示心气亏虚、肝血不足、肾气亦弱；“右脉濡滑”主湿郁气虚。症见性燥多虑、神倦无力、时发寒热、多走气急，皆二气亏虚、湿郁气滞之病机，故拟何人六君加味。", ["短", "虚", "小", "濡"]], "12440": ["病机", "脉来虚数，虚为三阴不足、精血亏虚，数为阴不敛阳、虚火内扰。心肾不交、水火不配，故见精神不振、饮食不甘；虚火扰神则五心烦躁、寤而不安。此脉主阴亏火旺、心肾失交之病机。", ["虚", "数"]], "12441": ["预后", "原文未载具体脉象，仅言“脉神色俱起”，即脉象与神色均好转。三进阿胶鸡子黄汤后脉神俱起，说明阴血渐复、神气来复，属预后佳象，故原方进步。", []], "12442": ["病机", "脉见双弦，弦为肝脉，双弦则肝木偏旺。忧思郁结伤肝，肝旺犯脾则饮食不思；木火刑金则咳嗽痰多；肝风内动则肢颤发抖、惊悸慌乱。形容消瘦、脉见双弦，犯五行之忌，主肝郁化火、木旺克土之病机。", ["弦"]], "12443": ["病机", "脉来软数无神，软为阴亏血少、脉道不充，数为虚火内动，无神则真阴耗损。半产后阴阳未复，阴亏水不济火，血少木失敷荣，肝病传脾，故精神不振、动劳发热。此脉主阴亏血枯、脾弱失运之病机，有经闭血枯之象。", ["软", "数"]], "12444": ["病机", "原文未载脉象，然述半产后阴伤精损、阴不敛阳、水不配火、精不化气，壮火食气、火灼金伤，肺肾俱困，肝病传脾，土不生金，金不平木，木复生火，上扰君心，故心烦意乱、竟夕无眠、虚里穴动、食减神疲。主肺肾两亏、虚火上炎之病机。", []], "12445": ["治法", "脉散为气阴耗散、真元不固之象。六味地黄丸合生脉散加龟板蜜丸，取六味培补肾阴，生脉散敛耗散之气阴，龟板潜阳固摄。以脉散为凭，治从补阴敛气、潜阳固本，属治法条目。", ["散"]], "12446": ["病机", "脉来软数无力，软为脏阴亏虚、脉道不充，数为虚火内扰，无力则中气不足。少年真阴不固、真阳失守，水不生木、火不生土，脾伤及肺，宗气无根则虚里震动，肾虚水反为湿则溲便如膏糊。主脾肾两虚、水火不交之病机。", ["软", "数"]], "12447": ["病机", "脉软而弦，软为真阴下亏、脉道失充，弦为虚阳上越、肝木偏旺。五志过极俱从火化，火愈炽水愈亏，阴不敛阳则竟夜不寐、心烦意乱。此脉主阴亏阳浮、心肾乖违、肝火偏亢之病机，故以六味三才加介类潜阳。", ["软", "弦"]], "12448": ["病机", "脉虚数而弦，虚为阴亏于下、荣失中守，数为营虚生热，弦乃木失敷荣、木乘土位之象。阴亏则水源不足、瘦削日加；木乘土位则脾困健运失常、饮食减少；奇脉有亏故经候不一。症由辛苦操劳耗伤脾肾，故法当脾肾双培，紧扣原文“阴亏于下，木失敷荣”“脾困于中”。", ["虚", "数", "弦"]], "12449": ["病机", "六脉细数而软，细为阴液久亏、脉道不充，数为阴亏生内热，软则气亦不足。原文谓“咽属少阴，发乃血余”，少阴主水，水不荣木，故少年白发、咽嗌不爽。此脉示水亏木失濡养而非实火，故宜壮水制火、缓缓调养，使血行气流，不可峻补峻清。", ["细", "数", "软"]], "12450": ["病机", "脉来沉滑而疾，沉主病在里，滑主痰涎壅盛，疾为郁而化火之征。原文“气闷痰郁，肺胃不展”，痰郁中焦则多食不舒，肺胃气不展则咳嗽气喘、胸中气急且闷，痰火升腾则甚则头面上火。脉沉滑疾正合痰郁化火、肺胃不展之机，故暂以外台茯苓饮加味以展气化痰。", ["沉", "滑", "疾"]], "12451": ["病机", "左脉涩、右脉沉，按之不宁静，涩为阴血亏涩，沉为病在里。原文谓“心肝肾三阴内亏，疟后又伤湿热，郁而不化”，中虚肺虚则劳动气喘、面带阳光；金水交伤则气火升腾莫制，咳嗽、两胁微疼、牙疼火炎于上。脉示阴亏而湿热郁滞、气火不制，病延已久，故虑难奏捷。", ["涩", "沉"]], "12452": ["病机", "左脉沉涩、右脉沉滑，推之不静。沉主里，涩为阴亏血少，滑为痰郁内壅。原文“痰郁咳嗽，阴亏虽虚，肺气不展”，久咳不已则三焦受伤。脉示虚中夹痰、肺气不展，故慎勿轻视，宜舒肺胃以展气化；最怕心令司权、火旺刑金，致有音哑之患。", ["沉", "涩", "滑"]], "12453": ["预后", "脉来滑数，滑主痰涎郁结，数主郁热内蒸。原文“肺有郁痰，咳喘不宁，口干身倦，不思饮食”，痰郁于肺则咳喘，郁热伤津则口干，脾运受困则不思饮食、身倦。病久人虚而脉见滑数，正虚邪恋，故断为极难奏效，属预后之论。", ["滑", "数"]], "12454": ["病机", "脉来濡滑，濡为气虚湿困、脉道软弱，滑为痰湿内盛。原文“气虚痰郁，脾受湿侵，渍之于肺”，脾虚失运则湿聚成痰，上渍于肺故咳嗽痰多。脉濡滑正合气虚痰湿之机，病本在脾而标在肺，故以杏苏二陈加味健脾燥湿、理气化痰。", ["濡", "滑"]], "12455": ["预后", "原文未识出脉名，仅言“脉尚未清”。服药四剂后咳嗽稍松、肺气已舒、腋痛已止，诸症渐退而脉气未复清宁，说明邪虽减而未尽、正气尚待恢复。此为据脉判断病情向愈而未全之预后语，故仍须续服调治，不可遽停药。", []], "12456": ["病机", "左脉沉小示肝阴不足、肝虚气冲于上；右脉濡涩示气虚痰郁、肺为娇脏不耐邪侵。肺不和则鼻不闻香臭，冒风则咳甚，卧时喉中水鸡声，皆肺虚治节不行、痰郁气逆之候。脉沉小濡涩正合肝虚肺郁、气虚痰郁之病机，故先以清疏为主。", ["沉", "小", "濡", "涩"]], "12457": ["病机", "咳势大减、痰涎已少、舌苔已化、饮食稍增，诸症向愈而脉来甚小，是邪退而正气已虚之象。脉小为正气不足，故仍宗前法助以辅正。此段以脉小点明正虚，非邪盛，与咳减寐安相应，属病后调补之机。", ["小"]], "12458": ["预后", "咳喘痰涎白沫、音哑食少、形容日羸、舌白脉弦，弦为土败金伤、肾虚水泛之象。中虚积饮浸淫渍肺，肺伤于肾，三焦俱病，故脉弦主虚损水泛。原文谓殊堪大虑、谨防喘促，是以脉弦测预后不良，非单纯主病。", ["弦"]], "12459": ["治法", "本段为复脉汤去桂枝、姜、枣，加黄芩、白糖拌黑芝麻之方药加减，未识别出脉名，纯属治法用药记载。去桂枝姜枣避其温散，加黄芩清郁热，白糖黑芝麻润养，体现复脉基础上清润兼施的治法思路，故归治法。", []], "12460": ["病机", "咳逆日久五更更剧，经云五更嗽者火浮于肺；寒热胸闷不欲食，脉浮而滑。浮为风邪在表、火浮于肺，滑为痰涎内蕴，风逆肺腑久则伤脾。脉浮滑正合风痰郁肺、火浮之机，故补土生金为治，明言非劳瘵。", ["浮", "滑"]], "12461": ["病机", "肝火冲肺则咳逆作热，热久伤胃则口无味、不欲食、难于大解，脉软神疲。软为正气虚弱、肝脾肺三经受恙之象，热久耗气故脉不弦劲而软，神疲亦虚候。脉软点明三经同病而正气已伤，非实火独盛。", ["软"]], "12462": ["病机", "幼年哮喘秋冬举发，发则不能安枕，痰豁乃平，脉弦兼滑。弦主风邪郁肺、气机不利，滑主痰涎壅盛，风痰郁肺已历多年，故脉弦滑相应。原文谓极难脱体，先以小青龙汤加味，是据弦滑辨风痰郁肺之病机。", ["弦", "滑"]], "12463": ["病机", "脉滑而数，滑主郁痰、数主郁热，痰热郁结则清肃不行，发为大哮痰喘。原文谓郁热郁痰、清肃不行，正合滑数之脉。久病肺虚，苦寒虽效不宜常服，恐伤生发之气，是据脉辨痰热而兼虑正虚，年少病深难于奏捷。", ["滑", "数"]], "12464": ["病机", "脉滑数较平，说明痰热渐化，气分热势已减。原文“胃口渐开，夜能安卧，头痛已痊”为热退症减之象；“哮喘未作，惟早间稍有咳嗽，气不舒畅”示余热未清，肺气未畅。滑主痰，数主热，较平则病势向愈，故仍清气分之热以彻余邪。", ["滑", "数"]], "12465": ["病机", "原文未及脉象，专论肺为娇脏，寒邪客肺，郁而化哮喘。谓“邪郁肺络，变生哮喘，发则声如曳锯，不能安卧”，说明病机为寒邪郁肺、络脉壅滞、气逆痰阻。已延四载，终身之累，强调久病入络、邪伏难拔，非单纯表邪可比。", []], "12466": ["病机", "脉来软细而空，即“形丰脉空，外强中弱”，为正气肾气皆亏之象。童年哮喘延久，痰中带血、白沫多、气急难卧，示肺病及肾、本虚标实。软细主气血不足，空主脉道不充，故骤补则郁痰，疏则正气更伤，治当补土生金、金来生水。", ["软", "细", "空"]], "12467": ["病机", "脉沉滑而疾，右得涩象，沉主病在里，滑主痰湿，疾主热，涩主络滞。幼年哮喘病入肺络，正气肾气俱亏，不能化邪外达，故脉沉滑而疾；右涩为痰瘀阻络。久病已和，调养肺胃，示不可峻攻，当缓图本元。", ["沉", "滑", "疾", "涩"]], "12468": ["病机", "脉来沉滑而疾，右之濡象俱透，似有火象。沉滑主痰湿内蕴，疾主火升，濡为湿象。气闷作嘈、气升则头汗、喉中有声、不能见风，皆痰火随气上逆之症。久病正气肺气俱亏，故虽见火象，难于速效，不可纯用苦寒。", ["沉", "滑", "疾", "濡"]], "12469": ["预后", "脉来虚数，虚主正气不足，数主火热内扰。中伤肺虚，咳嗽失血，痰中带血，形消发热，为肺阴亏虚、虚火灼金之候。虚数之脉示正虚火旺，故“慎防喉痛音哑，变生肺痿”，属预后警示，强调金伤成痿之变。", ["虚", "数"]], "12470": ["预后", "脉来细虚，细主阴血不足，虚主气弱。火灼金伤，风伏肺络，咳嗽失红，音哑，手足发热，口干心悸，浮火时升，皆肺阴亏虚、虚火上炎之症。细虚之脉示金伤成痿，故曰“恐难奏效”，属预后不良之判。", ["细", "虚"]], "12471": ["病机", "脉来沉数，原文自释“沉者郁也；数者，火也”。久咳音哑、喉痛作干、形神日瘦，为金水两伤、阴不上潮，肺痿已著。七情不适，郁结化火，火灼金伤，故脉沉数。沉为郁结在里，数为火郁于内，治当补阴，暂从木郁达之，补土生金。", ["沉", "数"]], "12472": ["病机", "脉来沉数，沉为病在里，数为热，合咳嗽虽平而喉痛声哑、蒸热未退，知郁结化火，火灼金伤，真阴消耗，热郁于里而肺金受灼，故脉沉数不去，病深难为力。", ["沉", "数"]], "12473": ["病机", "脉来细数不宁，细为阴血亏少，数为虚热内扰，右寸不来则肺气衰败。咳经年而形神变、午后发热、喉痛难食，正合金水交亏、中伤肺痿，虚火灼金而肺之部不应，故极难奏捷。", ["细", "数"]], "12474": ["预后", "原文未识脉名，仅言脉形神俱亏，即脉与形神皆见亏损。久咳喉痛、午后发热、饮食不思、苔黄，为火燥金痿、金水交伤；补肺后症减而脉无起色，脉不复则根本未回，故究属不宜，预后难吉。", []], "12475": ["预后", "原文未出脉名，只言服药虽效而脉无起色。症减而脉不应，是邪虽稍退、正气未复，脉象不随症转，故终属不宜，须再拟方观察，示脉为预后之凭，不可仅据症状言效。", []], "12476": ["预后", "脉来芤象，芤主失血伤阴、血虚而气不固。伤力蓄瘀、气血紊乱，咳喘痰带花红腥秽，肺痈已著，血络已伤而阴血外泄，故见芤脉，殊属不宜，示正伤邪著、预后可虑。", ["芤"]], "12477": ["病机", "脉滑痰多，滑主痰湿内盛。幼年失血，今咳不宁、天明尤甚、食不甘味，是肺胃中伤，痰湿壅于中上二焦，胃气不降则食少，肺失清肃则咳甚，故脉滑而痰多，难于速效。", ["滑"]], "12478": ["病机", "脉来虚数，虚为正气不足，数为阴亏虚热。阴虚伤风久咳，痰曾带红，兼耳鸣、盗汗、脱肛，皆肾虚不摄、虚火内动之象，故曰肺肾两伤、此属内损，宜远房帷静养以复真阴。", ["虚", "数"]], "12479": ["病机", "原文未识脉名，只言脉不安静，即脉失平和、躁动不宁。咳而呕恶食少，冬春吐血鲜红，咳不能寐，身痛麻木，是气分有火、血分有热，火热血动则脉不安，络伤血溢则吐红，故脉不安静。", []], "12480": ["病机", "脉沉弦，沉为气郁于里，弦为肝木失和。原文谓“肝郁中伤，肺胃交病”，因思虑烦心，肝郁气滞，横逆犯胃则胸次作胀、不饥不纳；木火刑金则呛咳吐血；气阻中宫，升降失司，故脉见沉弦。此脉主肝郁中伤、肺胃同病之机。", ["沉", "弦"]], "12481": ["病机", "脉来弦数，弦属肝木，数主火热。原文“郁结化火，火载血上”，大怒则血菀于上，狂吐后咳嗽、旬日遗泄，乃水不养肝、木击金鸣、肝虚制胃。弦为肝旺，数为火炎，故脉示肝郁化火、水亏木亢之病机。", ["弦", "数"]], "12482": ["病机", "脉来虚数，虚为三阴内亏、气血不足，数为酒湿兼伤、火载血上。原文“三阴内亏，酒湿兼伤，下有漏危，火载血上”，咳嗽食少，三焦俱损。虚数并见，示正虚火浮、阴亏液耗之病机，故需静养保守。", ["虚", "数"]], "12483": ["预后", "原文未识脉名，但言“脉神形色未起”，进补土生金后饮食未增、咳嗽仍然，脉神形色俱无起色，又值暑热伤阴，故“殊堪大虑”。此段以脉神形色判断亏损之病预后不良，暑热伤阴尤为棘手，再拟一方以观效。", []], "12484": ["预后", "原文未识脉名，但言“脉夺”，即脉气耗夺、重按无力，结合形消、子午咳嗽稍轻，知亏损已极。脉夺示正气衰败，形消为阴血耗损，故补土生金或可有济，然预后堪忧。此段以脉夺判断亏损至极之预后。", []], "12485": ["预后", "脉来参伍不调，即结代散乱之象，原文谓“生气大损，胃败中伤”。年逾花甲，二气就衰，湿热内困，土败金伤，痰红、气喘、足跗浮肿蔓延于上，脉见参伍不调，示胃气衰败、生机大损，故暂养心脾胃，胃开纳食方能转机。", ["结", "代"]], "12486": ["病机", "脉来细涩，细为阴血亏少，涩为营液耗滞。原文“先天本弱，脏阴营液俱耗”，素有走泄，肺肾两亏，咯血载余、干咳血上。细涩并见，示脏阴营液俱耗、肺肾两亏之病机，故极难调治。", ["细", "涩"]], "12487": ["预后", "脉之细涩较和，细涩本主脏阴营液俱耗，今较前和缓，示营液渐有来复之机。咯血略减，仍有紫色，说明瘀血未尽，但脉象转和，故仍守原意调治。此段以脉象较和判断病情向愈之预后。", ["细", "涩"]], "12488": ["预后", "左脉涩象渐和，说明瘀滞渐化、血行渐畅。前此咳血，涩脉主血少或血瘀，今渐和则知血络渐通，故三日未见血迹、咳势大减，为向愈之兆。", ["涩"]], "12489": ["病机", "脉来虚大而弦，虚为气血不足，大为劳热外浮，弦为肝木偏旺。年逾五六，饮食少纳，四肢无力，咳嗽带红，右胁痛胀，显系肝木犯肺、木扣金鸣，阳明不司束筋骨，故周身不和。", ["虚", "大", "弦"]], "12490": ["病机", "脉来细涩，细为阴血亏少，涩为气滞血瘀。疟后腹胀、失血、咳嗽气逆、呕吐白沫，乃金水交伤、肾气不纳，虚阳上冲，故痰中带血、卧则痰声咳醒，病机深重。", ["细", "涩"]], "12491": ["病机", "脉象闪烁，指脉来模糊不定，主正气虚衰、痰饮内停。咳甚痰嘶难出、音声不振、面无华色、唇舌皆白，乃气不生阴、阴不上潮，积痰化饮，故似宜真武法温阳化饮。", []], "12492": ["病机", "脉来细涩不起，细主阴血不足，涩主气滞血瘀，不起为阳气衰微。音声不开、痰声略减而饮食不增，乃肺脾两虚、金水交损，故拟琼玉膏滋阴益气，并嘱静养以护神明。", ["细", "涩"]], "12493": ["病机", "脉来洪大而弦，洪大为气火亢盛，弦为肝木失柔。半产后气血紊乱，血随气上，血不养肝，肝不藏血，气火升腾莫制，故失血之脉洪大为逆，慎防喘汗血脱。", ["洪", "大", "弦"]], "12494": ["病机", "脉弦而数，弦为肝郁，数为火旺。肝郁化火，火灼金伤，故咳嗽发热、失血红紫不一，血止后咳嗽不宁，木扣金鸣，治以解郁疏肝。", ["弦", "数"]], "12495": ["病机", "脉仍弦数，弦主肝郁，数主火盛。木火刑金，故失红后咳嗽不宁；蒸热、带下，乃肝火下迫、气虚阴亏，肝火失达，病机未变。", ["弦", "数"]], "12496": ["病机", "脉来虚数，虚为中气不足、肺气亦虚，数因湿热郁痰化火，故见寒热干呛、咳嗽带红，昼少夜多。虚数并见，说明正虚而邪热内郁，痰湿与虚火交争，病机属中虚肺虚、湿热郁痰为患。", ["虚", "数"]], "12497": ["病机", "脉来虚数，虚为阴血亏耗、肝失藏血，数因火载血上、木扣金鸣。忧思动怒伤肝，肝不藏血，火升咳血口干，虚数之脉正示阴亏火旺、肝不平宁，又值火令司权，故谨防喉痛音哑。", ["虚", "数"]], "12498": ["病机", "原文未出脉名，以肺司百脉之气、肝藏诸经之血、肾司生命之本立论。咳嗽失血、痰中带血，午后浮火时升，常多走泄，说明气不摄血、阴不敛阳，虚火浮越，下关不固，故欲图生机必得下关速闭。", []], "12499": ["预后", "脉来滑数，滑主痰湿壅盛，数主火邪内炽。风湿上受化火，火犯阳络则吐血鲜红、两胁胸次微痛。失血之脉贵乎宁静，今滑数不静，说明火势未平、络伤未复，故极难奏效，仍防涌逆。", ["滑", "数"]]});